def _qimage_buffer_bytes(image):
    """Copy a QImage's pixel buffer using the PySide6 buffer protocol.

    PySide6 returns a Python buffer view from bits()/constBits(); unlike the
    pointer-style wrapper, it does not require (or provide) setsize(). The explicit
    size bound also keeps the helper safe if a binding returns a larger view.
    """
    size = int(image.sizeInBytes())
    bits = image.constBits()
    data = bytes(bits)
    if len(data) < size:
        raise BufferError(
            f"QImage buffer is shorter than sizeInBytes(): {len(data)} < {size}")
    return data[:size]


def _qt_event_position(event):
    """Return a Qt 6 pointer/drag event's local position as an integer QPoint.

    Qt 6 exposes these positions as QPointF. Convert only at the widget APIs
    (itemAt, QRect hit testing, etc.) that use integer widget coordinates.
    """
    return event.position().toPoint()


def _qt_event_global_position(event):
    """Return a Qt 6 mouse event's global position as an integer QPoint."""
    return event.globalPosition().toPoint()

# ---------------------------------------------------------------------------
# Global Qt/native-resource lifetime management
# ---------------------------------------------------------------------------
_APP_SHUTTING_DOWN = False
_APP_SHUTDOWN_COMPLETE = False
_RESTART_AFTER_UPDATE = False

# QThread objects are retained until they are definitely stopped.  The previous
# implementation also scheduled every tracked QThread itself for deleteLater().
# That is unsafe during QApplication shutdown because the GUI event loop may stop
# before the DeferredDelete event is processed.  We therefore keep the registry
# alive, stop everything explicitly, drain deferred deletes while Qt is still alive,
# and only then release native QThread objects.
# Keep insertion order so shutdown can stop the most recently-created workers first.
# A plain set has no ordering guarantee, which made the original ordering comment untrue.
_QTHREAD_REGISTRY = collections.OrderedDict()
_QTHREAD_METADATA = {}
_QTHREAD_REGISTRY_LOCK = threading.RLock()

# ProcessBridge owns multiprocessing.Pipe + Process resources and is not itself a
# QThread, so it needs the same application-exit fence.
_PROCESS_BRIDGE_REGISTRY = set()
_PROCESS_BRIDGE_REGISTRY_LOCK = threading.RLock()


def _forget_tracked_qthread(thread):
    try:
        with _QTHREAD_REGISTRY_LOCK:
            _QTHREAD_REGISTRY.pop(thread, None)
            _QTHREAD_METADATA.pop(thread, None)
    except Exception:
        pass


class _QThreadCompletionRelay(QtCore.QObject):
    """Release a tracked QThread only after its native cleanup has completed.

    Qt may emit QThread.finished() before thread-local destructors have finished.
    Keep the Python wrapper retained until wait(0) confirms the native thread has
    completely stopped. The relay lives in the application (GUI) thread, so it
    never releases the last wrapper reference from the worker thread itself.
    """

    def __init__(self, thread, parent=None):
        super().__init__(parent)
        self._thread = thread
        self._poll_timer = QtCore.QTimer(self)
        self._poll_timer.setInterval(10)
        self._poll_timer.timeout.connect(self._try_release)
        self._release_started = False

    @QtCore.Slot()
    def _on_thread_finished(self):
        if self._release_started:
            return
        self._release_started = True
        self._try_release()

    @QtCore.Slot()
    def _try_release(self):
        thread = self._thread
        if thread is None:
            self._poll_timer.stop()
            self.deleteLater()
            return

        try:
            fully_stopped = bool(thread.wait(0))
        except Exception:
            # An unexpected binding/wrapper failure is not proof that native
            # cleanup completed. Retain the thread until the application fence.
            self._poll_timer.stop()
            return

        if not fully_stopped:
            if not self._poll_timer.isActive():
                self._poll_timer.start()
            return

        self._poll_timer.stop()
        self._thread = None
        _forget_tracked_qthread(thread)
        self.deleteLater()


def _track_qthread(thread, managed_worker=None):
    """Retain a QThread until its native completion is synchronized."""
    if thread is None:
        return None
    with _QTHREAD_REGISTRY_LOCK:
        if _APP_SHUTTING_DOWN:
            # Do not register late workers after the application exit fence starts.
            return thread
        # Re-tracking moves an existing entry to the newest position.
        _QTHREAD_REGISTRY.pop(thread, None)
        _QTHREAD_REGISTRY[thread] = None
        _QTHREAD_METADATA[thread] = {
            "managed_worker": managed_worker,
            "completion_relay": None,
        }

    # A QObject receiver with GUI-thread affinity is important here. A plain
    # Python lambda can run in the emitting thread under some callable-connection
    # paths, potentially dropping the QThread wrapper before native cleanup ends.
    try:
        app = QtWidgets.QApplication.instance()
        if app is not None:
            relay = _QThreadCompletionRelay(thread, parent=app)
            with _QTHREAD_REGISTRY_LOCK:
                metadata = _QTHREAD_METADATA.get(thread)
                if metadata is not None:
                    metadata["completion_relay"] = relay
            thread.finished.connect(
                relay._on_thread_finished,
                QtCore.Qt.ConnectionType.QueuedConnection,
            )
    except Exception:
        # Keep the registered reference until the coordinated application fence
        # if a completion relay cannot be installed.
        pass
    return thread


def _dispose_stopped_qthread(thread, managed_worker=None):
    """Intentionally retain stopped native QObjects until process exit.

    Direct binding-level deletion during application teardown is avoided because Qt may still
    have queued ownership metadata for these objects. Every caller reaches this helper only
    after the native thread has been fenced. The process-level exit path then reclaims the
    remaining stopped objects without running a second binding-level destructor pass.
    """
    return

def _stop_qthread(thread, stop_callback=None, timeout_ms=5000, force_wait_ms=2000):
    """Stop a QThread and synchronize with native cleanup before releasing it."""
    if thread is None:
        return True
    try:
        running = bool(thread.isRunning())
    except Exception:
        return True

    if running:
        if callable(stop_callback):
            try:
                stop_callback()
            except Exception:
                pass

        try:
            thread.quit()
        except Exception:
            pass
    else:
        # finished() can precede the end of thread-local cleanup. In that state,
        # isRunning() is already false, but wait() is still needed as a fence.
        try:
            if not thread.isFinished():
                # A constructed but never-started QThread owns no running native
                # execution context and requires no join.
                return True
        except Exception:
            return True

    try:
        if thread.wait(max(0, int(timeout_ms))):
            return True
    except Exception:
        pass

    try:
        if thread.wait(max(0, int(force_wait_ms))):
            return True
    except Exception:
        pass

    try:
        thread.wait()
    except Exception:
        pass
    try:
        return not thread.isRunning()
    except Exception:
        return True


def _register_process_bridge(bridge):
    if bridge is None:
        return
    with _PROCESS_BRIDGE_REGISTRY_LOCK:
        _PROCESS_BRIDGE_REGISTRY.add(bridge)


def _forget_process_bridge(bridge):
    if bridge is None:
        return
    with _PROCESS_BRIDGE_REGISTRY_LOCK:
        _PROCESS_BRIDGE_REGISTRY.discard(bridge)


def _shutdown_all_process_bridges():
    with _PROCESS_BRIDGE_REGISTRY_LOCK:
        bridges = list(_PROCESS_BRIDGE_REGISTRY)
    for bridge in bridges:
        try:
            bridge.shutdown()
        except Exception:
            pass


def _shutdown_all_tracked_qthreads(finalize=False):
    """Application-exit fence for every tracked QThread."""
    with _QTHREAD_REGISTRY_LOCK:
        # Ordered registry: newest workers first, to reduce producer/dependent races.
        threads = list(reversed(_QTHREAD_REGISTRY))

    # Stop newest workers first. This reduces the chance that a producer remains
    # alive while a dependent viewer/controller is being dismantled.
    for thread in threads:
        managed_worker = None
        try:
            with _QTHREAD_REGISTRY_LOCK:
                managed_worker = (_QTHREAD_METADATA.get(thread) or {}).get("managed_worker")
        except Exception:
            pass

        # Direct QThread subclasses own their signals. Suppress new queued UI
        # notifications during the final application fence. Plain QThread objects
        # with an external worker must keep signals enabled so finished->worker
        # cleanup can run normally.
        if managed_worker is None:
            try:
                thread.blockSignals(True)
            except Exception:
                pass

        def _cancel(t=thread):
            for method_name in ("request_cancel", "stop", "shutdown"):
                try:
                    method = getattr(t, method_name, None)
                    if callable(method):
                        method()
                except Exception:
                    pass

        _stop_qthread(thread, stop_callback=_cancel, timeout_ms=5000, force_wait_ms=3000)

        if finalize:
            _dispose_stopped_qthread(thread, managed_worker=managed_worker)

    if finalize:
        # Do not explicitly destroy stopped QThread/QObject wrappers here. The coordinated
        # stop/wait above is the important safety boundary; native object destruction is left
        # to process termination so no Python-side second teardown can race Qt's shutdown.
        with _QTHREAD_REGISTRY_LOCK:
            _QTHREAD_REGISTRY.clear()
            _QTHREAD_METADATA.clear()


def _shutdown_application_resources(finalize=False):
    """Single idempotent shutdown fence used before QApplication tears down."""
    global _APP_SHUTTING_DOWN, _APP_SHUTDOWN_COMPLETE
    with _QTHREAD_REGISTRY_LOCK:
        if _APP_SHUTDOWN_COMPLETE:
            return
        _APP_SHUTTING_DOWN = True

    _shutdown_all_process_bridges()
    _shutdown_all_tracked_qthreads(finalize=finalize)

    if finalize:
        _APP_SHUTDOWN_COMPLETE = True

