class _ReverseWheelStepMixin:
    """Reverse mouse-wheel changes while keeping normal arrows and keyboard steps."""

    def wheelEvent(self, event):
        delta = int(event.angleDelta().y())
        if not delta:
            return super().wheelEvent(event)

        # Preserve Qt's 120-unit wheel-notch behavior, including high-resolution wheels.
        accumulated = getattr(self, "_reverse_wheel_delta", 0) + delta
        steps = int(accumulated / 120)
        self._reverse_wheel_delta = accumulated - (steps * 120)
        if steps:
            self.stepBy(-steps)
        event.accept()


class _SettingsSpinBox(_ReverseWheelStepMixin, QtWidgets.QSpinBox):
    pass


class _SettingsDoubleSpinBox(_ReverseWheelStepMixin, QtWidgets.QDoubleSpinBox):
    pass

