def _default_cpu_worker_count(max_workers=None):
    """Return the shared default CPU worker count used by OCR and multiprocessing settings.

    The policy matches the OCR CPU-workers dropdown: use half the logical CPU count,
    with a minimum of one worker and a maximum of four.
    """
    if max_workers is None:
        max_workers = os.cpu_count() or 4
    max_workers = max(1, int(max_workers))
    return max(1, min(4, max_workers // 2 if max_workers > 1 else 1))


DEFAULT_CPU_WORKER_COUNT = _default_cpu_worker_count()

