def _ensure_icons_exist():
    """Create missing SVG icons only in explicit TEST MODE.

    In normal/installed mode the icon files are package data supplied by the wheel.
    The installed package must never populate or modify an ``icons/`` directory in
    the user's current working directory, and it should not mutate its own installed
    package resources at runtime either.
    """
    if not MERGERZ_TEST_MODE:
        return

    try:
        os.makedirs(ICONS_FOLDER, exist_ok=True)
        for name, content in _SVG_ICONS.items():
            path = os.path.join(ICONS_FOLDER, name)
            if os.path.isfile(path):
                continue
            try:
                with open(path, "x", encoding="utf-8") as f:
                    f.write(content)
            except FileExistsError:
                # Another startup/helper reached the same icon between the check and open.
                continue
            except Exception:
                pass
    except Exception as e:
        print(f"Could not write TEST MODE SVG icons: {e}")


def _looks_like_font(path):
    try:
        return os.path.isfile(path) and os.path.getsize(path) > 0
    except Exception:
        return False


def _font_or_none(path):
    try:
        if _looks_like_font(path):
            return fitz.Font(fontfile=path)
    except Exception:
        pass
    return None


def _fallback_font(name):
    try:
        return fitz.Font(name)
    except Exception:
        return None


def _make_muted_pixmap(pixmap):
    muted = QtGui.QPixmap(pixmap.size())
    muted.fill(QtCore.Qt.GlobalColor.transparent)
    painter = QtGui.QPainter(muted)
    painter.drawPixmap(0, 0, pixmap)
    painter.setCompositionMode(QtGui.QPainter.CompositionMode.CompositionMode_SourceIn)
    painter.fillRect(muted.rect(), QtGui.QColor(110, 110, 110, 150))
    painter.end()
    return muted


def _render_svg_icon_pixmap(path, size=26, muted=False):
    if not (_HAS_QT_SVG and os.path.isfile(path)):
        return None
    try:
        renderer = QSvgRenderer(path)
        if not renderer.isValid():
            return None
        pixmap = QtGui.QPixmap(size, size)
        pixmap.fill(QtCore.Qt.GlobalColor.transparent)
        painter = QtGui.QPainter(pixmap)
        painter.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        painter.setRenderHint(QtGui.QPainter.RenderHint.SmoothPixmapTransform, True)
        renderer.render(painter)
        painter.end()
        if muted:
            pixmap = _make_muted_pixmap(pixmap)
        return pixmap
    except Exception:
        return None


def _render_svg_icon(path, size=26, color=None):
    pix_normal = _render_svg_icon_pixmap(path, size, muted=False)
    if pix_normal is None:
        return None
    icon = QtGui.QIcon()
    icon.addPixmap(pix_normal, QtGui.QIcon.Mode.Normal, QtGui.QIcon.State.Off)
    pix_muted = _render_svg_icon_pixmap(path, size, muted=True)
    if pix_muted is not None:
        icon.addPixmap(pix_muted, QtGui.QIcon.Mode.Disabled, QtGui.QIcon.State.Off)
    return icon


def _render_svg_icon_rotated(path, size, angle_deg):
    if not (_HAS_QT_SVG and os.path.isfile(path)):
        return None
    try:
        renderer = QSvgRenderer(path)
        if not renderer.isValid():
            return None
        pixmap = QtGui.QPixmap(size, size)
        pixmap.fill(QtCore.Qt.GlobalColor.transparent)
        painter = QtGui.QPainter(pixmap)
        painter.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        painter.setRenderHint(QtGui.QPainter.RenderHint.SmoothPixmapTransform, True)
        painter.translate(size / 2.0, size / 2.0)
        painter.rotate(angle_deg)
        painter.translate(-size / 2.0, -size / 2.0)
        renderer.render(painter)
        painter.end()
        return QtGui.QIcon(pixmap)
    except Exception:
        return None



# ============================================================
# CUSTOM WINDOW CHROME
# ============================================================
# All application top-level windows use this shared frameless title bar. The
# underlying Qt object remains a real QDialog/QMainWindow, so modal behavior,
# closeEvent handling, focus, window state and normal application logic remain
# unchanged. Move/resize operations are delegated to the native window system.

_CUSTOM_TITLEBAR_HEIGHT = 40
_CUSTOM_RESIZE_MARGIN = 7
_CUSTOM_TITLEBAR_TOP_RESIZE = 5
_CUSTOM_WINDOW_RADIUS = 12


class _MacWindowButton(QtWidgets.QToolButton):
    """Small macOS-style traffic-light button used by the custom title bar."""
    _COLORS = {
        "close": QtGui.QColor("#ff5f57"),
        "minimize": QtGui.QColor("#febc2e"),
        "maximize": QtGui.QColor("#28c840"),
    }

    def __init__(self, role, parent=None):
        super().__init__(parent)
        self.role = str(role)
        self._hovered = False
        self.setFixedSize(16, 16)
        self.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.setAutoRaise(True)
        self.setFocusPolicy(QtCore.Qt.FocusPolicy.NoFocus)
        self.setToolTip({
            "close": "Close",
            "minimize": "Minimize",
            "maximize": "Maximize",
        }.get(self.role, ""))
        self.setAttribute(QtCore.Qt.WidgetAttribute.WA_Hover, True)

    def enterEvent(self, event):
        self._hovered = True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._hovered = False
        self.update()
        super().leaveEvent(event)

    def paintEvent(self, event):
        painter = QtGui.QPainter(self)
        painter.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        painter.setPen(QtCore.Qt.PenStyle.NoPen)
        painter.setBrush(self._COLORS.get(self.role, QtGui.QColor("#888888")))
        painter.drawEllipse(QtCore.QRectF(1, 1, 14, 14))

        # macOS reveals the control glyph when the pointer is over the traffic
        # light. Keep it subtle so the buttons still read as simple colored dots.
        if self._hovered:
            pen = QtGui.QPen(QtGui.QColor("#4b4b4b"))
            pen.setWidthF(1.05)
            pen.setCapStyle(QtCore.Qt.PenCapStyle.RoundCap)
            pen.setJoinStyle(QtCore.Qt.PenJoinStyle.RoundJoin)
            painter.setPen(pen)
            if self.role == "close":
                painter.drawLine(QtCore.QPointF(5.0, 5.0), QtCore.QPointF(11.0, 11.0))
                painter.drawLine(QtCore.QPointF(11.0, 5.0), QtCore.QPointF(5.0, 11.0))
            elif self.role == "minimize":
                painter.drawLine(QtCore.QPointF(4.8, 8.0), QtCore.QPointF(11.2, 8.0))
            elif self.role == "maximize":
                # Four tiny outward corners, close to the glyph used on macOS.
                painter.drawLine(QtCore.QPointF(4.7, 7.0), QtCore.QPointF(4.7, 4.7))
                painter.drawLine(QtCore.QPointF(4.7, 4.7), QtCore.QPointF(7.0, 4.7))
                painter.drawLine(QtCore.QPointF(11.3, 7.0), QtCore.QPointF(11.3, 4.7))
                painter.drawLine(QtCore.QPointF(11.3, 4.7), QtCore.QPointF(9.0, 4.7))
                painter.drawLine(QtCore.QPointF(4.7, 9.0), QtCore.QPointF(4.7, 11.3))
                painter.drawLine(QtCore.QPointF(4.7, 11.3), QtCore.QPointF(7.0, 11.3))
                painter.drawLine(QtCore.QPointF(11.3, 9.0), QtCore.QPointF(11.3, 11.3))
                painter.drawLine(QtCore.QPointF(11.3, 11.3), QtCore.QPointF(9.0, 11.3))
        painter.end()


class _WindowTitleBar(QtWidgets.QWidget):
    """Aesthetic draggable title bar shared by every top-level Mergerz window."""
    def __init__(self, window, parent=None):
        super().__init__(parent or window)
        self.window = window
        self.setObjectName("mergerzCustomTitleBar")
        self.setFixedHeight(_CUSTOM_TITLEBAR_HEIGHT)
        self.setMouseTracking(True)
        self.setAttribute(QtCore.Qt.WidgetAttribute.WA_StyledBackground, True)
        self.setStyleSheet("""
            QWidget#mergerzCustomTitleBar {
                background: qlineargradient(
                    x1:0, y1:0, x2:0, y2:1,
                    stop:0 #242a32,
                    stop:0.5 #22282f,
                    stop:0.88 #20252c,
                    stop:1 #1f242a
                );
                border: none;
            }
            QLabel#mergerzTitleIcon {
                background: transparent;
                border: none;
            }
        """)

        outer = QtWidgets.QVBoxLayout(self)
        outer.setContentsMargins(0, 0, 0, 0)
        outer.setSpacing(0)

        row = QtWidgets.QHBoxLayout()
        row.setContentsMargins(12, 0, 10, 0)
        row.setSpacing(9)
        outer.addLayout(row, 1)

        self.logo = QtWidgets.QLabel(self)
        self.logo.setObjectName("mergerzTitleIcon")
        self.logo.setFixedSize(28, 28)
        self.logo.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.logo.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        icon = _render_svg_icon(os.path.join(ICONS_FOLDER, "logo2.svg"), size=22)
        if icon is not None:
            self.logo.setPixmap(icon.pixmap(22, 22))
        row.addWidget(self.logo, 0, QtCore.Qt.AlignmentFlag.AlignVCenter)

        self.title = QtWidgets.QLabel(self)
        self.title.setSizePolicy(QtWidgets.QSizePolicy.Policy.Expanding, QtWidgets.QSizePolicy.Policy.Preferred)
        self.title.setStyleSheet(
            "QLabel { color:#f1f3f6; background:transparent; "
            "font-size:10.5pt; font-weight:600; padding:0; }"
        )
        self.title.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        row.addWidget(self.title, 1, QtCore.Qt.AlignmentFlag.AlignVCenter)

        controls = QtWidgets.QWidget(self)
        controls.setObjectName("mergerzWindowControls")
        controls.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, False)
        controls.setStyleSheet("""
            QWidget#mergerzWindowControls {
                background: rgba(0, 0, 0, 0.13);
                border: 1px solid rgba(255, 255, 255, 0.055);
                border-radius: 9px;
            }
        """)
        controls_layout = QtWidgets.QHBoxLayout(controls)
        controls_layout.setContentsMargins(6, 4, 6, 4)
        controls_layout.setSpacing(6)

        self.min_button = _MacWindowButton("minimize", controls)
        self.max_button = _MacWindowButton("maximize", controls)
        self.close_button = _MacWindowButton("close", controls)
        controls_layout.addWidget(self.min_button, 0, QtCore.Qt.AlignmentFlag.AlignVCenter)
        controls_layout.addWidget(self.max_button, 0, QtCore.Qt.AlignmentFlag.AlignVCenter)
        controls_layout.addWidget(self.close_button, 0, QtCore.Qt.AlignmentFlag.AlignVCenter)
        row.addWidget(controls, 0, QtCore.Qt.AlignmentFlag.AlignVCenter)

        self.min_button.clicked.connect(self.window.showMinimized)
        self.max_button.clicked.connect(self._toggle_maximized)
        self.close_button.clicked.connect(self.window.close)
        self._refresh_title()

    def _refresh_title(self):
        self.title.setText(str(self.window.windowTitle() or "Mergerz"))

    def _toggle_maximized(self):
        if self.window.isMaximized():
            self.window.showNormal()
        else:
            self.window.showMaximized()

    def mouseDoubleClickEvent(self, event):
        if event.button() == QtCore.Qt.MouseButton.LeftButton:
            self._toggle_maximized()
            event.accept()
            return
        event.ignore()

    def mousePressEvent(self, event):
        if event.button() == QtCore.Qt.MouseButton.LeftButton:
            handle = self.window.windowHandle()
            if handle is not None:
                # Keep the very top few pixels available for native top-edge
                # resizing. The rest of the title bar behaves like a normal
                # draggable desktop title bar.
                try:
                    if _qt_event_position(event).y() <= _CUSTOM_TITLEBAR_TOP_RESIZE:
                        if handle.startSystemResize(QtCore.Qt.Edge.TopEdge):
                            event.accept()
                            return
                except Exception:
                    pass
                try:
                    if handle.startSystemMove():
                        event.accept()
                        return
                except Exception:
                    pass
        event.ignore()


class _WindowChromeManager(QtCore.QObject):
    """Application-wide installer for the custom title bar on all top-level dialogs/windows."""
    def __init__(self, app):
        super().__init__(app)
        self._app = app
        self._installed = {}
        app.installEventFilter(self)

    @staticmethod
    def _is_real_top_level(widget):
        if not isinstance(widget, (QtWidgets.QDialog, QtWidgets.QMainWindow)):
            return False
        # Presentation mode is a deliberate chrome-free fullscreen surface.
        # It must never receive the application's custom title bar, even though
        # it is implemented as a QDialog so it can still use exec() cleanly.
        if bool(widget.property("_mergerz_skip_custom_chrome")):
            return False
        # Embedded viewers are intentionally QWidget instances and must retain
        # their normal in-app appearance instead of becoming a window chrome.
        if widget.windowType() == QtCore.Qt.WindowType.Widget:
            return False
        return bool(widget.isWindow())

    def _install(self, window):
        if not self._is_real_top_level(window):
            return
        key = id(window)
        if key in self._installed:
            bar = self._installed[key]
            try:
                bar._refresh_title()
            except Exception:
                pass
            return

        flags = window.windowFlags()
        flags |= QtCore.Qt.WindowType.Window
        flags |= QtCore.Qt.WindowType.FramelessWindowHint
        flags |= QtCore.Qt.WindowType.WindowSystemMenuHint
        flags |= QtCore.Qt.WindowType.WindowMinimizeButtonHint
        flags |= QtCore.Qt.WindowType.WindowMaximizeButtonHint
        flags |= QtCore.Qt.WindowType.WindowCloseButtonHint
        window.setWindowFlags(flags)

        bar = _WindowTitleBar(window, window)
        self._installed[key] = bar
        window.setProperty("_mergerz_custom_chrome", True)

        # QDialog content already has its own layout. Add exactly one title-bar
        # height to its top margin rather than reparenting or wrapping content.
        layout = window.layout()
        if layout is not None and not bool(window.property("_mergerz_chrome_margin_added")):
            l, t, r, b = layout.getContentsMargins()
            layout.setContentsMargins(l, t + _CUSTOM_TITLEBAR_HEIGHT, r, b)
            window.setProperty("_mergerz_chrome_margin_added", True)

        self._apply_window_shape(window)
        bar.show()
        bar.raise_()
        self._position(window)
        try:
            window.windowTitleChanged.connect(bar._refresh_title)
        except Exception:
            pass

    @staticmethod
    def _apply_window_shape(window):
        """Clip every custom-chrome window to a smooth rounded rectangle.

        Normal windows get rounded corners. Maximized/fullscreen windows are
        intentionally returned to a full-rect shape so they still meet the
        screen edges cleanly.
        """
        try:
            if window.isMaximized() or window.isFullScreen():
                window.clearMask()
                return

            width = max(1, int(window.width()))
            height = max(1, int(window.height()))
            radius = max(1, min(_CUSTOM_WINDOW_RADIUS, width // 2, height // 2))
            path = QtGui.QPainterPath()
            path.addRoundedRect(
                QtCore.QRectF(0.0, 0.0, float(width), float(height)),
                float(radius),
                float(radius),
            )
            window.setMask(QtGui.QRegion(path.toFillPolygon(QtGui.QTransform()).toPolygon()))
        except Exception:
            # Shape clipping is cosmetic; never allow it to interfere with
            # normal window creation, resizing, or closing.
            try:
                window.clearMask()
            except Exception:
                pass

    def _position(self, window):
        bar = self._installed.get(id(window))
        if bar is None:
            return
        bar.setGeometry(0, 0, window.width(), _CUSTOM_TITLEBAR_HEIGHT)
        bar.raise_()
        self._apply_window_shape(window)

        if isinstance(window, QtWidgets.QMainWindow):
            # Let QMainWindow's own layout reserve the title-bar strip.
            try:
                if window.menuWidget() is not bar:
                    window.setMenuWidget(bar)
            except Exception:
                pass

    def _resize_from_edge(self, window, global_pos):
        if window.isMaximized() or window.isFullScreen():
            return False
        handle = window.windowHandle()
        if handle is None:
            return False

        pos = window.mapFromGlobal(global_pos)
        w, h = window.width(), window.height()
        m = _CUSTOM_RESIZE_MARGIN
        left = pos.x() <= m
        right = pos.x() >= w - m
        top = pos.y() <= m
        bottom = pos.y() >= h - m

        edges = QtCore.Qt.Edges()
        if left:
            edges |= QtCore.Qt.Edge.LeftEdge
        if right:
            edges |= QtCore.Qt.Edge.RightEdge
        if top:
            edges |= QtCore.Qt.Edge.TopEdge
        if bottom:
            edges |= QtCore.Qt.Edge.BottomEdge
        if not edges:
            return False
        try:
            return bool(handle.startSystemResize(edges))
        except Exception:
            return False

    def _update_cursor(self, window, global_pos):
        if window.isMaximized() or window.isFullScreen():
            window.unsetCursor()
            return
        try:
            pos = window.mapFromGlobal(global_pos)
        except Exception:
            return
        w, h = window.width(), window.height()
        m = _CUSTOM_RESIZE_MARGIN
        left = pos.x() <= m
        right = pos.x() >= w - m
        top = pos.y() <= m
        bottom = pos.y() >= h - m
        if (left and top) or (right and bottom):
            window.setCursor(QtCore.Qt.CursorShape.SizeFDiagCursor)
        elif (right and top) or (left and bottom):
            window.setCursor(QtCore.Qt.CursorShape.SizeBDiagCursor)
        elif left or right:
            window.setCursor(QtCore.Qt.CursorShape.SizeHorCursor)
        elif top or bottom:
            window.setCursor(QtCore.Qt.CursorShape.SizeVerCursor)
        else:
            window.unsetCursor()

    def eventFilter(self, watched, event):
        # Catch both construction and showing so dialogs that alter their own
        # flags later still receive the same custom chrome.
        if isinstance(watched, (QtWidgets.QDialog, QtWidgets.QMainWindow)) and watched.isWindow():
            if event.type() in (QtCore.QEvent.Type.Polish, QtCore.QEvent.Type.Show):
                if watched.windowType() != QtCore.Qt.WindowType.Widget:
                    self._install(watched)
                    if event.type() == QtCore.QEvent.Type.Show:
                        self._position(watched)

        top = None
        try:
            candidate = watched.window() if isinstance(watched, QtWidgets.QWidget) else None
            if isinstance(candidate, (QtWidgets.QDialog, QtWidgets.QMainWindow)):
                top = candidate
        except Exception:
            top = None

        if top is not None and id(top) in self._installed:
            if event.type() == QtCore.QEvent.Type.Resize and watched is top:
                self._position(top)
            elif event.type() == QtCore.QEvent.Type.MouseMove:
                try:
                    self._update_cursor(top, _qt_event_global_position(event))
                except Exception:
                    pass
            elif event.type() == QtCore.QEvent.Type.MouseButtonPress:
                try:
                    if event.button() == QtCore.Qt.MouseButton.LeftButton:
                        bar = self._installed[id(top)]
                        if bar.geometry().contains(top.mapFromGlobal(_qt_event_global_position(event))):
                            return False
                        if self._resize_from_edge(top, _qt_event_global_position(event)):
                            return True
                except Exception:
                    pass
            elif event.type() == QtCore.QEvent.Type.WindowStateChange and watched is top:
                QtCore.QTimer.singleShot(0, lambda w=top: self._position(w))

            elif event.type() == QtCore.QEvent.Type.WindowActivate and watched is top:
                # Re-apply the shape when the window is activated because some
                # window managers can reset the native region during activation.
                self._apply_window_shape(top)

        return super().eventFilter(watched, event)


def _pil_to_qimage(img):
    if img is None:
        return QtGui.QImage()
    rgb = img.convert("RGB")
    data = rgb.tobytes("raw", "RGB")
    qimg = QtGui.QImage(data, rgb.width, rgb.height, rgb.width * 3,
                        QtGui.QImage.Format.Format_RGB888)
    return qimg.copy()


def _pil_to_qimage_rgba(img):
    """Create a detached RGBA QImage suitable for delivery from a worker thread.

    Keep the same RGBA8888 pixel representation used by _pil_to_qpixmap(); the
    explicit bytes-per-line value documents the four-byte pixel stride.
    """
    if img is None:
        return QtGui.QImage()
    if img.mode != "RGBA":
        img = img.convert("RGBA")
    data = img.tobytes("raw", "RGBA")
    qimg = QtGui.QImage(
        data, img.width, img.height, img.width * 4,
        QtGui.QImage.Format.Format_RGBA8888)
    return qimg.copy()


def _pil_to_qpixmap(img):
    if img.mode != "RGBA":
        img = img.convert("RGBA")
    data = img.tobytes("raw", "RGBA")
    qimg = QtGui.QImage(data, img.width, img.height,
                        QtGui.QImage.Format.Format_RGBA8888)
    return QtGui.QPixmap.fromImage(qimg.copy())


def _invert_qpixmap(pixmap):
    """Fast screen-preview equivalent of the PDF-native white/Difference inversion.

    Saved PDFs and delayed exact previews use the isolated DeviceRGB Form-XObject implementation.
    This helper remains raster-only because the GUI must produce pixels for immediate display.
    """
    if pixmap is None or pixmap.isNull():
        return pixmap
    out = QtGui.QPixmap(pixmap.size())
    out.fill(QtGui.QColor("#ffffff"))
    painter = QtGui.QPainter(out)
    painter.setCompositionMode(QtGui.QPainter.CompositionMode.CompositionMode_Difference)
    painter.drawPixmap(0, 0, pixmap)
    painter.end()
    return out


# ============================================================
# PDF / LIVE FILTER ENGINE
# ============================================================
FILTER_BLEND_MODES = (
    "Normal", "Multiply", "Screen", "Overlay", "Soft Light", "Hard Light",
    "Darken", "Lighten", "Color Dodge", "Color Burn", "Difference",
    "Exclusion", "Hue", "Saturation", "Color", "Luminosity",
)

FILTER_CONFIG_KEYS = (
    "layer_color", "blend_mode", "opacity",
    "brightness", "contrast", "gamma", "black_point", "white_point",
    "saturation", "warmth", "tint",
    "grayscale", "invert", "threshold",
    "invert_exclude_images", "invert_images_only",
)


def _neutral_filter_config():
    return {
        "layer_color": "#ffffff",
        "blend_mode": "Normal",
        "opacity": 0,
        "brightness": 0,
        "contrast": 0,
        "gamma": 1.0,
        "black_point": 0,
        "white_point": 100,
        "saturation": 100,
        "warmth": 0,
        "tint": 0,
        "grayscale": 0,
        "invert": 0,
        "threshold": 0,
        # Fixed inversion modes are semantic flags rather than custom slider values.
        "invert_exclude_images": False,
        "invert_images_only": False,
    }


def _clamp_filter_num(value, lo, hi, default):
    try:
        value = float(value)
    except Exception:
        value = float(default)
    if not math.isfinite(value):
        value = float(default)
    return max(float(lo), min(float(hi), value))


def _normalize_filter_config(config=None):
    base = _neutral_filter_config()
    if isinstance(config, dict):
        base.update(config)
    color = str(base.get("layer_color", "#ffffff") or "#ffffff").strip()
    if not re.fullmatch(r"#[0-9a-fA-F]{6}", color):
        color = "#ffffff"
    mode = str(base.get("blend_mode", "Normal") or "Normal")
    if mode not in FILTER_BLEND_MODES:
        mode = "Normal"
    base["layer_color"] = color.lower()
    base["blend_mode"] = mode
    base["opacity"] = round(_clamp_filter_num(base.get("opacity"), 0, 100, 0), 3)
    base["brightness"] = round(_clamp_filter_num(base.get("brightness"), -100, 100, 0), 3)
    base["contrast"] = round(_clamp_filter_num(base.get("contrast"), -100, 100, 0), 3)
    base["gamma"] = round(_clamp_filter_num(base.get("gamma"), 0.2, 5.0, 1.0), 4)
    base["black_point"] = round(_clamp_filter_num(base.get("black_point"), 0, 100, 0), 3)
    base["white_point"] = round(_clamp_filter_num(base.get("white_point"), 0, 100, 100), 3)
    base["saturation"] = round(_clamp_filter_num(base.get("saturation"), 0, 100, 100), 3)
    base["warmth"] = round(_clamp_filter_num(base.get("warmth"), -100, 100, 0), 3)
    base["tint"] = round(_clamp_filter_num(base.get("tint"), -100, 100, 0), 3)
    base["grayscale"] = round(_clamp_filter_num(base.get("grayscale"), 0, 100, 0), 3)
    base["invert"] = round(_clamp_filter_num(base.get("invert"), 0, 100, 0), 3)
    base["threshold"] = round(_clamp_filter_num(base.get("threshold"), 0, 100, 0), 3)
    base["invert_exclude_images"] = bool(base.get("invert_exclude_images", False))
    base["invert_images_only"] = bool(base.get("invert_images_only", False))
    # These are mutually exclusive inversion modes. If a malformed/imported config
    # specifies both, keep the more explicit image-only operation deterministic.
    if base["invert_images_only"]:
        base["invert_exclude_images"] = False
    return base


def _entry_filter_config(entry):
    if not isinstance(entry, dict):
        return _neutral_filter_config()
    cfg = entry.get("filter_config")
    if isinstance(cfg, dict):
        return _normalize_filter_config(cfg)
    # Legacy Edit PDF entries are migrated logically: old invert state is now
    # represented as the new fixed Invert preset without changing the old key.
    if bool(entry.get("invert_colors", False)):
        return _preset_filter_config("Invert")
    return _neutral_filter_config()


def _effective_filter_config(config):
    cfg = _normalize_filter_config(config)
    if cfg["opacity"] <= 1e-6:
        # Layer color and blend mode have no visual effect while the layer is invisible.
        cfg["layer_color"] = "#ffffff"
        cfg["blend_mode"] = "Normal"
        cfg["opacity"] = 0
    return cfg


def _filter_config_active(config):
    cfg = _effective_filter_config(config)
    neutral = _neutral_filter_config()
    return cfg != neutral


def _filter_configs_equal(a, b):
    return _effective_filter_config(a) == _effective_filter_config(b)


def _preset_filter_config(name):
    cfg = _neutral_filter_config()
    cfg["layer_color"] = "#ffffff"
    if name == "Invert":
        cfg["blend_mode"] = "Difference"
        cfg["opacity"] = 100
    elif name == "Inv. (no images)":
        cfg["blend_mode"] = "Difference"
        cfg["opacity"] = 100
        cfg["invert_exclude_images"] = True
    elif name == "Inv. (images only)":
        cfg["invert_images_only"] = True
    elif name == "Grayscale":
        cfg["saturation"] = 0
    return _normalize_filter_config(cfg)


def _filter_badge_text(config):
    if not _filter_config_active(config):
        return ""
    cfg = _normalize_filter_config(config)
    if _filter_configs_equal(cfg, _preset_filter_config("Inv. (no images)")):
        return "INV. NO IMAGES"
    if _filter_configs_equal(cfg, _preset_filter_config("Inv. (images only)")):
        return "INV. IMAGES ONLY"
    if _filter_configs_equal(cfg, _preset_filter_config("Invert")):
        return "INVERT"
    if _filter_configs_equal(cfg, _preset_filter_config("Grayscale")):
        return "GRAYSCALE"
    return "FILTER"


def _fast_pixel_preview_filter_config(config):
    """Return the cheap raster approximation used before the delayed exact PDF preview.

    The no-images preset falls back to ordinary full-page Invert for a responsive
    approximation. Image-only inversion must not do that: a flattened QImage has no
    reliable distinction between embedded images and text/vector artwork, so the fast
    preview leaves image inversion unapplied until the delayed PDF-native preview can
    target the actual image objects. Other pixel-friendly adjustments remain available.
    """
    cfg = _normalize_filter_config(config)
    if cfg.get("invert_exclude_images"):
        return _preset_filter_config("Invert")
    if cfg.get("invert_images_only"):
        cfg["invert_images_only"] = False
        cfg["invert_exclude_images"] = False
    # Gamma is intentionally omitted from the immediate raster approximation.
    # The delayed PDF preview is authoritative and applies the selected gamma value.
    cfg["gamma"] = 1.0
    return cfg


def _filter_hex_to_rgb(color):
    c = str(color or "#ffffff").lstrip("#")
    try:
        return tuple(int(c[i:i + 2], 16) for i in (0, 2, 4))
    except Exception:
        return (255, 255, 255)


def _warmth_color(value):
    value = _clamp_filter_num(value, -100, 100, 0)
    if value >= 0:
        t = value / 100.0
        # White -> warm amber/peach.
        return tuple(round(255 * (1 - t) + 228 * t) if i == 0 else
                     round(255 * (1 - t) + (170 if i == 1 else 92) * t)
                     for i in range(3))
    t = (-value) / 100.0
    # White -> cool sky-blue.
    return tuple(round(255 * (1 - t) + (82 if i == 0 else 175 if i == 1 else 255) * t)
                 for i in range(3))


def _tint_color(value):
    value = _clamp_filter_num(value, -100, 100, 0)
    if value >= 0:
        t = value / 100.0
        return tuple(round(255 * (1 - t) + (236 if i == 0 else 128 if i == 1 else 210) * t)
                     for i in range(3))
    t = (-value) / 100.0
    return tuple(round(255 * (1 - t) + (100 if i == 0 else 215 if i == 1 else 145) * t)
                 for i in range(3))


def _tone_lut(config):
    cfg = _normalize_filter_config(config)
    black = cfg["black_point"] / 100.0
    white = cfg["white_point"] / 100.0
    gamma = cfg["gamma"]
    brightness = cfg["brightness"] / 100.0
    contrast = 1.0 + cfg["contrast"] / 100.0
    threshold_amount = cfg["threshold"] / 100.0
    invert_amount = cfg["invert"] / 100.0
    if white <= black + 1e-5:
        white = min(1.0, black + 1e-5)

    lut = []
    for i in range(256):
        x = i / 255.0
        x = max(0.0, min(1.0, (x - black) / (white - black)))
        x = max(0.0, min(1.0, x ** (1.0 / gamma)))
        x = max(0.0, min(1.0, (x - 0.5) * contrast + 0.5 + brightness))
        if threshold_amount > 0:
            hard = 1.0 if x >= 0.5 else 0.0
            x = x * (1.0 - threshold_amount) + hard * threshold_amount
        if invert_amount > 0:
            x = x * (1.0 - invert_amount) + (1.0 - x) * invert_amount
        lut.append(int(round(max(0.0, min(1.0, x)) * 255.0)))
    return lut


def _blend_pil_layer(base, rgb, amount, mode):
    """Apply a constant-color compositing layer using the same semantics as saved PDF filters."""
    if base is None or amount <= 1e-6:
        return base
    amount = max(0.0, min(1.0, float(amount)))
    overlay = Image.new("RGB", base.size, tuple(int(max(0, min(255, v))) for v in rgb))
    try:
        if mode == "Normal":
            mixed = overlay
        elif mode == "Multiply":
            mixed = ImageChops.multiply(base, overlay)
        elif mode == "Screen":
            mixed = ImageChops.screen(base, overlay)
        elif mode == "Overlay":
            mixed = ImageChops.overlay(base, overlay)
        elif mode == "Soft Light":
            mixed = ImageChops.soft_light(base, overlay)
        elif mode == "Hard Light":
            mixed = ImageChops.hard_light(base, overlay)
        elif mode == "Darken":
            mixed = ImageChops.darker(base, overlay)
        elif mode == "Lighten":
            mixed = ImageChops.lighter(base, overlay)
        elif mode == "Difference":
            mixed = ImageChops.difference(base, overlay)
        elif mode == "Exclusion":
            base_bytes = base.tobytes()
            overlay_bytes = overlay.tobytes()
            out = bytearray(len(base_bytes))
            for i, (cb, cs) in enumerate(zip(base_bytes, overlay_bytes)):
                b = cb / 255.0
                c = cs / 255.0
                out[i] = int(round(max(0.0, min(1.0, b + c - 2.0 * b * c)) * 255.0))
            mixed = Image.frombytes("RGB", base.size, bytes(out))
        elif mode == "Color Dodge":
            mixed = ImageChops.screen(base, overlay)
        elif mode == "Color Burn":
            mixed = ImageChops.multiply(base, overlay)
        elif mode in {"Hue", "Saturation", "Color", "Luminosity"}:
            # PIL does not provide the PDF HSL operators directly in a form that is
            # guaranteed identical to every PDF renderer, so keep the preview restrained.
            mixed = Image.blend(base, overlay, 0.65)
        else:
            mixed = overlay
    except Exception:
        mixed = overlay
    return Image.blend(base, mixed, amount)


def _pdf_like_tone_preview(image, cfg):
    """Preview tone edits using the same vector-native layer semantics used for saved PDFs."""
    img = image

    gamma = float(cfg["gamma"])
    if abs(gamma - 1.0) > 1e-6:
        lut = [
            int(round(max(0.0, min(1.0, (i / 255.0) ** (1.0 / gamma))) * 255.0))
            for i in range(256)
        ]
        img = img.point(lut * 3)

    black_point = float(cfg["black_point"]) / 100.0
    if black_point > 1e-6:
        img = _blend_pil_layer(img, (0, 0, 0), black_point * 0.60, "Multiply")

    white_point = max(0.0, 100.0 - float(cfg["white_point"])) / 100.0
    if white_point > 1e-6:
        img = _blend_pil_layer(img, (255, 255, 255), white_point * 0.60, "Screen")

    contrast = float(cfg["contrast"])
    if abs(contrast) > 1e-6:
        source = 0.5 + (contrast / 100.0) * 0.40
        gray = int(round(max(0.0, min(1.0, source)) * 255.0))
        img = _blend_pil_layer(img, (gray, gray, gray), abs(contrast) / 100.0 * 0.75, "Overlay")

    brightness = float(cfg["brightness"])
    if brightness > 1e-6:
        img = _blend_pil_layer(img, (255, 255, 255), brightness / 100.0, "Normal")
    elif brightness < -1e-6:
        img = _blend_pil_layer(img, (0, 0, 0), -brightness / 100.0, "Normal")

    threshold = float(cfg["threshold"]) / 100.0
    if threshold > 1e-6:
        source = int(round(128 + 120 * threshold))
        img = _blend_pil_layer(img, (source, source, source), threshold * 0.55, "Overlay")

    invert = float(cfg["invert"])
    if invert > 1e-6:
        img = _blend_pil_layer(img, (255, 255, 255), invert / 100.0, "Difference")
    return img


def _apply_filter_to_pil_image(image, config):
    """Display/export helper aligned with the PDF-native filter stack."""
    if image is None:
        return image
    cfg = _normalize_filter_config(config)
    img = image.convert("RGB")

    img = _pdf_like_tone_preview(img, cfg)

    desat_amount = max(
        1.0 - cfg["saturation"] / 100.0,
        cfg["grayscale"] / 100.0,
    )
    if desat_amount > 1e-6:
        gray = ImageOps.grayscale(img).convert("RGB")
        img = Image.blend(img, gray, max(0.0, min(1.0, desat_amount)))

    # Use Normal alpha compositing for Warmth/Tint so the fast raster preview
    # uses the same per-pixel blend equation as the PDF-native adjustment layers.
    if abs(float(cfg["warmth"])) > 1e-6:
        img = _blend_pil_layer(
            img, _warmth_color(cfg["warmth"]),
            abs(float(cfg["warmth"])) / 100.0 * 0.45, "Normal")
    if abs(float(cfg["tint"])) > 1e-6:
        img = _blend_pil_layer(
            img, _tint_color(cfg["tint"]),
            abs(float(cfg["tint"])) / 100.0 * 0.45, "Normal")

    if cfg["opacity"] > 1e-6:
        img = _blend_pil_layer(
            img, _filter_hex_to_rgb(cfg["layer_color"]),
            cfg["opacity"] / 100.0, cfg["blend_mode"])
    return img


def _qt_composition_mode(mode):
    composition_mode = QtGui.QPainter.CompositionMode
    mapping = {
        "Normal": composition_mode.CompositionMode_SourceOver,
        "Multiply": composition_mode.CompositionMode_Multiply,
        "Screen": composition_mode.CompositionMode_Screen,
        "Overlay": composition_mode.CompositionMode_Overlay,
        "Soft Light": composition_mode.CompositionMode_SoftLight,
        "Hard Light": composition_mode.CompositionMode_HardLight,
        "Darken": composition_mode.CompositionMode_Darken,
        "Lighten": composition_mode.CompositionMode_Lighten,
        "Color Dodge": composition_mode.CompositionMode_ColorDodge,
        "Color Burn": composition_mode.CompositionMode_ColorBurn,
        "Difference": composition_mode.CompositionMode_Difference,
        "Exclusion": composition_mode.CompositionMode_Exclusion,
        "Hue": composition_mode.CompositionMode_Hue,
        "Saturation": composition_mode.CompositionMode_Saturation,
        "Color": composition_mode.CompositionMode_Color,
        "Luminosity": composition_mode.CompositionMode_Luminosity,
    }
    return mapping.get(mode, composition_mode.CompositionMode_SourceOver)


def _paint_filter_overlay_qpixmap(pixmap, rgb, mode, opacity):
    if pixmap is None or pixmap.isNull() or opacity <= 1e-6:
        return pixmap
    out = QtGui.QPixmap(pixmap)
    painter = QtGui.QPainter(out)
    painter.setCompositionMode(_qt_composition_mode(mode))
    painter.setOpacity(max(0.0, min(1.0, float(opacity))))
    painter.fillRect(out.rect(), QtGui.QColor(*rgb))
    painter.end()
    return out


def _apply_filter_to_qpixmap(pixmap, config):
    if pixmap is None or pixmap.isNull():
        return pixmap
    cfg = _normalize_filter_config(config)
    try:
        qimg = pixmap.toImage().convertToFormat(QtGui.QImage.Format.Format_RGBA8888)
        pixel_bytes = _qimage_buffer_bytes(qimg)
        img = Image.frombytes("RGBA", (qimg.width(), qimg.height()), pixel_bytes)
        img = _apply_filter_to_pil_image(img, cfg)
        return _pil_to_qpixmap(img)
    except Exception:
        return QtGui.QPixmap(pixmap)


def _ps_num(value):
    return f"{float(value):.8g}"


def _build_pdf_transfer_function_ps(config):
    """Build a conservative Type 4 function for component-wise tone edits."""
    cfg = _normalize_filter_config(config)
    black = cfg["black_point"] / 100.0
    white = cfg["white_point"] / 100.0
    gamma = cfg["gamma"]
    brightness = cfg["brightness"] / 100.0
    contrast = 1.0 + cfg["contrast"] / 100.0
    threshold_amount = cfg["threshold"] / 100.0
    invert_amount = cfg["invert"] / 100.0
    if white <= black + 1e-5:
        white = min(1.0, black + 1e-5)

    parts = [
        f"{_ps_num(black)} sub",
        f"{_ps_num(white - black)} div",
        "dup 0 lt { pop 0 } if",
        "dup 1 gt { pop 1 } if",
        f"{_ps_num(1.0 / gamma)} exp",
        f"{_ps_num(contrast)} mul",
        "0.5 sub",
        f"{_ps_num(brightness)} add",
        "0.5 add",
        "dup 0 lt { pop 0 } if",
        "dup 1 gt { pop 1 } if",
    ]
    if threshold_amount > 0:
        # Stack: y -> y, hard -> hard*(1-a), y -> y*(1-a), then add.
        parts.extend([
            "dup", "0.5 ge { 1 } { 0 } ifelse",
            "exch",
            f"{_ps_num(1.0 - threshold_amount)} mul",
            "exch",
            f"{_ps_num(threshold_amount)} mul",
            "add",
        ])
    if invert_amount > 0:
        # y = y*(1-a) + (1-y)*a
        parts.extend([
            "dup", f"{_ps_num(1.0 - invert_amount)} mul",
            "exch", "1 exch sub", f"{_ps_num(invert_amount)} mul", "add",
        ])
    parts.extend([
        "dup 0 lt { pop 0 } if",
        "dup 1 gt { pop 1 } if",
    ])
    return "{ " + " ".join(parts) + " }"


def _pikepdf_clone_resource_category(value):
    """Clone one PDF resource category dictionary without cloning its referenced objects."""
    if not isinstance(value, pikepdf.Dictionary):
        return value
    cloned = pikepdf.Dictionary()
    for key, child in value.items():
        cloned[key] = child
    return cloned


def _pikepdf_clone_resources(resources):
    """Clone a page/form Resources dictionary with independent category dictionaries.

    PDF page resources may be inherited from a parent page-tree node. Mutating a nested resource
    dictionary in-place can therefore accidentally change resources shared by other pages. The
    inversion engine only needs independent resource *dictionaries*; the actual fonts, images,
    patterns, etc. remain shared PDF objects by reference, so the copy is cheap and preserves the
    original document structure.
    """
    if resources is None:
        return pikepdf.Dictionary()
    if not isinstance(resources, pikepdf.Dictionary):
        raise RuntimeError("PDF page Resources entry is not a dictionary.")

    cloned = pikepdf.Dictionary()
    for key, value in resources.items():
        cloned[key] = _pikepdf_clone_resource_category(value)
    return cloned


def _pikepdf_ensure_local_page_resources(page):
    """Return a page-local copy of Resources so generated inversion resources cannot leak."""
    current = page.get("/Resources")
    if current is None:
        current = pikepdf.Dictionary()
    local = _pikepdf_clone_resources(current)
    page["/Resources"] = local
    return local


def _pikepdf_unique_resource_name(resource_dict, prefix):
    """Return a collision-safe PDF resource name."""
    for _ in range(32):
        candidate = f"/{prefix}{uuid.uuid4().hex[:14]}"
        if candidate not in resource_dict:
            return candidate
    # UUID collisions are extraordinarily unlikely; retain a deterministic fallback anyway.
    index = 1
    while True:
        candidate = f"/{prefix}{index}"
        if candidate not in resource_dict:
            return candidate
        index += 1


def _pikepdf_content_objects(page):
    """Return page content stream objects as a list without changing their order."""
    contents = page.get("/Contents")
    if contents is None:
        return []
    if isinstance(contents, pikepdf.Array):
        return list(contents)
    return [contents]


def _pikepdf_content_bytes(content_objects):
    """Coalesce PDF content streams exactly as PDF's content-stream array semantics require."""
    parts = []
    for content in content_objects:
        if content is None:
            continue
        try:
            parts.append(content.read_bytes())
        except Exception as exc:
            raise RuntimeError(
                f"Could not read a PDF content stream while building the inversion group: {exc}") from exc
    return b"\n".join(parts)


def _pikepdf_wrap_contents_with_inversion(pdf, page, content_objects, opacity=1.0, tag="Invert",
                                           page_resources=None):
    """Wrap existing PDF content in an isolated DeviceRGB Difference-inversion Form XObject.

    The resulting page remains fully vector-native: original page operators, text, vectors and
    image XObjects are preserved as PDF content. Only the compositing boundary is changed. The
    form is isolated so the inversion's blending color space is deterministic and cannot depend
    on the source page's existing transparency group or output device.
    """
    opacity = max(0.0, min(1.0, float(opacity)))
    if opacity <= 1e-6:
        return list(content_objects)

    cover_x, cover_y, cover_width, cover_height = _pikepdf_filter_coverage_rect(page)
    if page_resources is None:
        page_resources = _pikepdf_ensure_local_page_resources(page)
    elif not isinstance(page_resources, pikepdf.Dictionary):
        raise RuntimeError("PDF page Resources entry is not a dictionary.")

    # The Form gets its own resource dictionaries so adding the inversion ExtGState does not
    # mutate a page's original/inherited resource dictionary. Referenced objects remain shared.
    form_resources = _pikepdf_clone_resources(page_resources)
    form_extg = form_resources.get("/ExtGState")
    if form_extg is None:
        form_extg = pikepdf.Dictionary()
    elif not isinstance(form_extg, pikepdf.Dictionary):
        raise RuntimeError("PDF ExtGState resources entry is not a dictionary.")

    inversion_gs_name = _pikepdf_unique_resource_name(form_extg, "MergerzInvGS")
    form_extg[inversion_gs_name] = pikepdf.Dictionary({
        "/BM": pikepdf.Name("/Difference"),
        "/ca": opacity,
        "/CA": opacity,
    })
    form_resources["/ExtGState"] = form_extg

    # Isolated + DeviceRGB is the critical robustness improvement: the inversion is evaluated
    # against the white background inside a controlled RGB transparency group rather than the
    # source page's potentially inherited/output-device blending context.
    form_group = pikepdf.Dictionary({
        "/S": pikepdf.Name("/Transparency"),
        "/I": True,
        "/K": False,
        "/CS": pikepdf.Name("/DeviceRGB"),
    })

    original_bytes = _pikepdf_content_bytes(content_objects)
    bg_ops = (
        "q\n"
        "1 1 1 rg\n"
        f"{_ps_num(cover_x)} {_ps_num(cover_y)} "
        f"{_ps_num(cover_width)} {_ps_num(cover_height)} re\n"
        "f\n"
        "Q\n"
    ).encode("ascii")

    inv_ops = (
        "\nq\n"
        f"{inversion_gs_name} gs\n"
        "1 1 1 rg\n"
        f"{_ps_num(cover_x)} {_ps_num(cover_y)} "
        f"{_ps_num(cover_width)} {_ps_num(cover_height)} re\n"
        "f\n"
        "Q\n"
    ).encode("ascii")

    form_stream = pikepdf.Stream(
        pdf,
        bg_ops + original_bytes + inv_ops,
    )
    form_stream["/Type"] = pikepdf.Name("/XObject")
    form_stream["/Subtype"] = pikepdf.Name("/Form")
    form_stream["/FormType"] = 1
    form_stream["/BBox"] = pikepdf.Array([
        cover_x,
        cover_y,
        cover_x + cover_width,
        cover_y + cover_height,
    ])
    form_stream["/Resources"] = form_resources
    form_stream["/Group"] = form_group
    form_ref = pdf.make_indirect(form_stream)

    page_xobj = page_resources.get("/XObject")
    if page_xobj is None:
        page_xobj = pikepdf.Dictionary()
    elif not isinstance(page_xobj, pikepdf.Dictionary):
        raise RuntimeError("PDF XObject resources entry is not a dictionary.")

    form_name = _pikepdf_unique_resource_name(page_xobj, "MergerzInvFm")
    page_xobj[form_name] = form_ref
    page_resources["/XObject"] = page_xobj

    placement = pikepdf.Stream(
        pdf,
        f"q\n{form_name} Do\nQ\n".encode("ascii"),
    )
    return [placement]


def _pikepdf_resources(page):
    """Return a page-local ExtGState dictionary for ordinary filter layers."""
    resources = _pikepdf_ensure_local_page_resources(page)
    extgstate = resources.get("/ExtGState")
    if extgstate is None:
        extgstate = pikepdf.Dictionary()
        resources["/ExtGState"] = extgstate
    elif not isinstance(extgstate, pikepdf.Dictionary):
        raise RuntimeError("PDF ExtGState resources entry is not a dictionary.")
    return extgstate


def _pikepdf_identity_rgb_name(resources):
    """Return a dedicated identity CalRGB space for synthetic filter rectangles."""
    if "/ColorSpace" not in resources:
        resources["/ColorSpace"] = pikepdf.Dictionary()
    colorspaces = resources["/ColorSpace"]
    name = "/MergerzFilterRGB"
    if name not in colorspaces:
        colorspaces[name] = pikepdf.Array([
            pikepdf.Name("/CalRGB"),
            pikepdf.Dictionary({
                "/WhitePoint": [0.95047, 1.0, 1.08883],
                "/Gamma": [1.0, 1.0, 1.0],
                "/Matrix": [
                    0.4124, 0.2126, 0.0193,
                    0.3576, 0.7152, 0.1192,
                    0.1805, 0.0722, 0.9505,
                ],
            }),
        ])
    return name


def _pikepdf_filter_coverage_rect(page):
    """Return an oversized rectangle that safely covers every page-box region.

    Synthetic filter layers are painted in the page's default user space. A page is not
    guaranteed to use (0, 0) as its lower-left coordinate: MediaBox and related page boxes
    may be shifted, negative, or otherwise unusual. Build the coverage rectangle from the
    union of every relevant page box, then add a bounded overscan margin. The page boundary
    clips anything outside the page, so the extra coverage is invisible while preventing
    antialiased/page-edge gaps caused by coordinate-origin assumptions.
    """
    box_names = (
        "/MediaBox",
        "/CropBox",
        "/BleedBox",
        "/TrimBox",
        "/ArtBox",
    )
    rects = []

    for name in box_names:
        value = None
        try:
            value = page[name]
        except Exception:
            try:
                value = getattr(page, name[1:])
            except Exception:
                value = None
        if value is None:
            continue
        try:
            if len(value) != 4:
                continue
            x0, y0, x1, y1 = (float(value[0]), float(value[1]),
                              float(value[2]), float(value[3]))
            if not all(math.isfinite(v) for v in (x0, y0, x1, y1)):
                continue
            left = min(x0, x1)
            bottom = min(y0, y1)
            right = max(x0, x1)
            top = max(y0, y1)
            if right > left and top > bottom:
                rects.append((left, bottom, right, top))
        except Exception:
            continue

    if not rects:
        # MediaBox is mandatory in a valid PDF, so this is only a defensive fallback for
        # a malformed/incomplete page object. Keep the historical zero-origin dimensions.
        try:
            mb = page.MediaBox
            x0, y0, x1, y1 = map(float, mb[:4])
            left = min(x0, x1)
            bottom = min(y0, y1)
            right = max(x0, x1)
            top = max(y0, y1)
        except Exception:
            raise RuntimeError("Page has no usable page-box geometry for filter application.")
    else:
        left = min(r[0] for r in rects)
        bottom = min(r[1] for r in rects)
        right = max(r[2] for r in rects)
        top = max(r[3] for r in rects)

    width = right - left
    height = top - bottom
    if width <= 0 or height <= 0:
        raise RuntimeError("Page has invalid dimensions for filter application.")

    # Deliberate overscan. It is outside the physical page and therefore clipped by the PDF
    # page boundary. The bounded value avoids unnecessarily huge coordinates on giant pages.
    pad = max(12.0, min(72.0, max(width, height) * 0.02))
    return left - pad, bottom - pad, width + 2.0 * pad, height + 2.0 * pad


def _pikepdf_rect_stream(pdf, page, width=None, height=None, color=(1, 1, 1)):
    resources = page["/Resources"]
    rgb_name = _pikepdf_identity_rgb_name(resources)
    r, g, b = color
    x, y, cover_width, cover_height = _pikepdf_filter_coverage_rect(page)
    return pikepdf.Stream(pdf, (
        f"q\n{rgb_name} cs\n{_ps_num(r)} {_ps_num(g)} {_ps_num(b)} sc\n"
        f"{_ps_num(x)} {_ps_num(y)} {_ps_num(cover_width)} {_ps_num(cover_height)} re\nf\nQ\n"
    ).encode("ascii"))


def _pikepdf_overlay_stream(pdf, page, width=None, height=None, color=(1, 1, 1), gs_name=""):
    resources = page["/Resources"]
    rgb_name = _pikepdf_identity_rgb_name(resources)
    r, g, b = color
    x, y, cover_width, cover_height = _pikepdf_filter_coverage_rect(page)
    return pikepdf.Stream(pdf, (
        "q\n"
        f"/{gs_name} gs\n"
        f"{rgb_name} cs\n{_ps_num(r)} {_ps_num(g)} {_ps_num(b)} sc\n"
        f"{_ps_num(x)} {_ps_num(y)} {_ps_num(cover_width)} {_ps_num(cover_height)} re\n"
        "f\nQ\n"
    ).encode("ascii"))


def _pdf_calrgb_gamma_exponent(gamma):
    """Map the UI's encoded-RGB gamma curve to a PDF CalRGB linear-light exponent.

    The fast preview applies x ** (1 / gamma) to rendered, sRGB-encoded pixel values.
    CalRGB's /Gamma is applied before the calibrated RGB-to-XYZ matrix, i.e. in
    linear-light space. Using 1/gamma directly therefore applies an extra display
    encoding curve and makes the exact PDF preview substantially more washed out.
    Fit the CalRGB exponent at middle gray so the PDF-rendered sRGB value matches
    the fast preview there, while remaining close over the rest of the tonal range.
    """
    gamma = _clamp_filter_num(gamma, 0.2, 5.0, 1.0)
    target_encoded = 0.5 ** (1.0 / gamma)
    if target_encoded <= 0.04045:
        target_linear = target_encoded / 12.92
    else:
        target_linear = ((target_encoded + 0.055) / 1.055) ** 2.4
    # For a 0.5 input, target_linear == 0.5 ** exponent.
    return max(1e-6, math.log(target_linear) / math.log(0.5))


def _pikepdf_default_color_space_setup(page, gamma):
    """Install safe DefaultRGB/DefaultGray gamma mappings only when no defaults exist."""
    if abs(float(gamma) - 1.0) <= 1e-6:
        return False
    if "/Resources" not in page:
        page["/Resources"] = pikepdf.Dictionary()
    resources = page["/Resources"]
    if "/ColorSpace" not in resources:
        resources["/ColorSpace"] = pikepdf.Dictionary()
    cs = resources["/ColorSpace"]
    if "/DefaultRGB" in cs or "/DefaultGray" in cs:
        return False

    g = _pdf_calrgb_gamma_exponent(gamma)
    calrgb = pikepdf.Array([
        pikepdf.Name("/CalRGB"),
        pikepdf.Dictionary({
            "/WhitePoint": [0.95047, 1.0, 1.08883],
            "/Gamma": [g, g, g],
            "/Matrix": [
                0.4124, 0.2126, 0.0193,
                0.3576, 0.7152, 0.1192,
                0.1805, 0.0722, 0.9505,
            ],
        }),
    ])
    calgray = pikepdf.Array([
        pikepdf.Name("/CalGray"),
        pikepdf.Dictionary({
            "/WhitePoint": [0.95047, 1.0, 1.08883],
            "/BlackPoint": [0.0, 0.0, 0.0],
            "/Gamma": g,
        }),
    ])
    cs["/DefaultRGB"] = calrgb
    cs["/DefaultGray"] = calgray
    return True


def _pdf_blend_name(mode):
    return {
        "Normal": "/Normal", "Multiply": "/Multiply", "Screen": "/Screen",
        "Overlay": "/Overlay", "Soft Light": "/SoftLight", "Hard Light": "/HardLight",
        "Darken": "/Darken", "Lighten": "/Lighten", "Color Dodge": "/ColorDodge",
        "Color Burn": "/ColorBurn", "Difference": "/Difference", "Exclusion": "/Exclusion",
        "Hue": "/Hue", "Saturation": "/Saturation", "Color": "/Color",
        "Luminosity": "/Luminosity",
    }.get(mode, "/Normal")


def _add_pdf_constant_layer(pdf, page, extgstate, width, height, color, mode, opacity, tag):
    opacity = max(0.0, min(1.0, float(opacity)))
    if opacity <= 1e-6:
        return None
    gs_name = f"/Filter{tag}GS"
    extgstate[gs_name] = pikepdf.Dictionary({
        "/BM": pikepdf.Name(_pdf_blend_name(mode)),
        "/ca": opacity,
        "/CA": opacity,
    })
    return _pikepdf_overlay_stream(
        pdf, page, width, height,
        tuple(float(v) for v in color), gs_name[1:])



# ============================================================
# IMAGE-PRESERVING VECTOR INVERSION HELPERS
# ============================================================
def _pikepdf_stream_clone(pdf, source_stream):
    """Clone a PDF stream without decoding or recompressing its payload."""
    if not isinstance(source_stream, pikepdf.Stream):
        raise RuntimeError("Expected a PDF stream while cloning an image/Form XObject.")
    raw = source_stream.read_raw_bytes()
    data = pikepdf.Dictionary()
    for key, value in source_stream.items():
        if str(key) == "/Length":
            continue
        data[key] = value
    return pikepdf.Stream(pdf, raw, data)


def _pikepdf_filter_names(image_obj):
    """Return the image stream's filter names as normalized strings."""
    value = image_obj.get("/Filter")
    if value is None:
        return []
    if isinstance(value, pikepdf.Array):
        values = list(value)
    else:
        values = [value]
    return [str(v) for v in values]


def _pikepdf_resolve_colorspace(cs, resources):
    """Resolve a named color-space resource without altering the original object."""
    if cs is None:
        return None
    name = str(cs)
    if name.startswith("/") and name not in {
        "/DeviceGray", "/DeviceRGB", "/DeviceCMYK", "/Pattern",
        "/CalGray", "/CalRGB", "/Lab", "/ICCBased", "/Indexed",
        "/Separation", "/DeviceN",
    }:
        spaces = resources.get("/ColorSpace") if isinstance(resources, pikepdf.Dictionary) else None
        if isinstance(spaces, pikepdf.Dictionary):
            try:
                resolved = spaces.get(cs)
            except Exception:
                resolved = None
            if resolved is not None:
                return resolved
    return cs


def _pikepdf_simple_image_components(image_obj, resources):
    """Return component count only for native-safe DeviceGray/DeviceRGB images."""
    cs = _pikepdf_resolve_colorspace(image_obj.get("/ColorSpace"), resources)
    name = str(cs)
    if name == "/DeviceGray":
        return 1
    if name == "/DeviceRGB":
        return 3
    return None


def _pikepdf_decode_flip_array(image_obj, component_count):
    """Return the complement mapping for an image's current /Decode array."""
    decode = image_obj.get("/Decode")
    if decode is None:
        values = [0.0, 1.0] * int(component_count)
    else:
        if not isinstance(decode, pikepdf.Array):
            return None
        values = []
        try:
            for value in decode:
                number = float(value)
                if not math.isfinite(number):
                    return None
                values.append(number)
        except Exception:
            return None
        if len(values) != int(component_count) * 2:
            return None
    flipped = []
    for index in range(0, len(values), 2):
        lo, hi = values[index], values[index + 1]
        flipped.extend([hi, lo])
    return pikepdf.Array(flipped)


def _pikepdf_clone_image_for_decode(pdf, image_obj, resources):
    """Create a lossless clone and reverse each supported image component's Decode range."""
    components = _pikepdf_simple_image_components(image_obj, resources)
    if components is None:
        return None, False
    # pikepdf's image model specifically warns that DCT/JPX codecs carry their own color
    # semantics. Keep those on the targeted pixel fallback instead of risking codec-level
    # double inversion or color-management changes.
    filters = set(_pikepdf_filter_names(image_obj))
    if "/DCTDecode" in filters or "/JPXDecode" in filters:
        return None, False
    if bool(image_obj.get("/ImageMask", False)):
        return None, False
    flipped_decode = _pikepdf_decode_flip_array(image_obj, components)
    if flipped_decode is None:
        return None, False
    clone = _pikepdf_stream_clone(pdf, image_obj)
    clone["/Decode"] = flipped_decode
    return clone, True


def _pikepdf_raster_fallback_inverted_image(pdf, image_obj, resources):
    """Targeted image-only fallback for image encodings/color spaces that cannot safely use /Decode.

    The PDF page itself is never rasterized. Only this one image object is decoded to Pillow and
    replaced by a losslessly Flate-compressed RGB/Gray image; any existing image transparency is
    preserved as a separate soft mask with identical dimensions.
    """
    work_image = image_obj
    cs = image_obj.get("/ColorSpace")
    resolved_cs = _pikepdf_resolve_colorspace(cs, resources)
    if resolved_cs is not None and resolved_cs is not cs and str(cs) not in {"/DeviceGray", "/DeviceRGB", "/DeviceCMYK"}:
        work_image = _pikepdf_stream_clone(pdf, image_obj)
        work_image["/ColorSpace"] = resolved_cs

    try:
        pdf_image = pikepdf.PdfImage(work_image)
        pil = pdf_image.as_pil_image(apply_decode_array=True, apply_mask=True)
    except Exception as exc:
        raise RuntimeError(
            f"Could not decode an embedded image for image-preserving inversion: {exc}") from exc

    if pil is None:
        raise RuntimeError("Embedded image decoder returned no image.")

    # Preserve alpha/transparency; invert only visible color channels.
    alpha = None
    if pil.mode in {"RGBA", "LA"}:
        alpha = pil.getchannel("A")
        pil = pil.convert("RGB" if pil.mode == "RGBA" else "L")
    elif pil.mode == "P":
        transparency = pil.info.get("transparency")
        if transparency is not None:
            rgba = pil.convert("RGBA")
            alpha = rgba.getchannel("A")
            pil = rgba.convert("RGB")
        else:
            pil = pil.convert("RGB")
    elif pil.mode not in {"L", "RGB"}:
        pil = pil.convert("RGB")

    pil = ImageOps.invert(pil)
    width, height = pil.size
    if width <= 0 or height <= 0:
        raise RuntimeError("Embedded image has invalid dimensions.")

    if pil.mode == "L":
        color_space = pikepdf.Name("/DeviceGray")
        raw = pil.tobytes()
        components = 1
    else:
        color_space = pikepdf.Name("/DeviceRGB")
        raw = pil.convert("RGB").tobytes()
        components = 3

    image_dict = pikepdf.Dictionary({
        "/Type": pikepdf.Name("/XObject"),
        "/Subtype": pikepdf.Name("/Image"),
        "/Width": int(width),
        "/Height": int(height),
        "/ColorSpace": color_space,
        "/BitsPerComponent": 8,
        "/Filter": pikepdf.Name("/FlateDecode"),
    })
    for key in ("/Interpolate", "/Intent"):
        if key in image_obj:
            image_dict[key] = image_obj[key]

    replacement = pikepdf.Stream(pdf, zlib.compress(raw, level=6), image_dict)

    if alpha is not None:
        smask = pikepdf.Stream(pdf, zlib.compress(alpha.tobytes(), level=6), pikepdf.Dictionary({
            "/Type": pikepdf.Name("/XObject"),
            "/Subtype": pikepdf.Name("/Image"),
            "/Width": int(width),
            "/Height": int(height),
            "/ColorSpace": pikepdf.Name("/DeviceGray"),
            "/BitsPerComponent": 8,
            "/Filter": pikepdf.Name("/FlateDecode"),
            "/Decode": pikepdf.Array([0, 1]),
        }))
        replacement["/SMask"] = smask

    return replacement, True


def _pikepdf_form_source_resources(form_obj, parent_resources):
    raw = form_obj.get("/Resources")
    if raw is None:
        return parent_resources
    if not isinstance(raw, pikepdf.Dictionary):
        raise RuntimeError("A Form XObject has an invalid /Resources entry.")
    return raw


def _pikepdf_process_no_image_scope(pdf, scope_obj, source_resources, form_memo, image_memo,
                                    active_forms, stats):
    """Clone only resource objects whose actual drawn content reaches an embedded image."""
    if not isinstance(source_resources, pikepdf.Dictionary):
        raise RuntimeError("PDF graphics scope has invalid resources.")

    scope_key = None
    if hasattr(scope_obj, "objgen"):
        try:
            scope_key = tuple(scope_obj.objgen)
        except Exception:
            scope_key = None
    if scope_key is not None and scope_key in active_forms:
        raise RuntimeError("Cyclic Form XObject reference cannot be safely image-inverted.")

    if scope_key is not None:
        active_forms = set(active_forms)
        active_forms.add(scope_key)

    try:
        instructions = pikepdf.parse_content_stream(scope_obj)
    except Exception as exc:
        raise RuntimeError(f"Could not parse PDF drawing content for image-preserving inversion: {exc}") from exc

    xobjects = source_resources.get("/XObject")
    if xobjects is not None and not isinstance(xobjects, pikepdf.Dictionary):
        raise RuntimeError("PDF XObject resources entry is not a dictionary.")

    local_resources = None
    local_xobjects = None
    changed = False

    def ensure_local_resources():
        nonlocal local_resources, local_xobjects
        if local_resources is None:
            local_resources = _pikepdf_clone_resources(source_resources)
            original_xobjects = source_resources.get("/XObject")
            if isinstance(original_xobjects, pikepdf.Dictionary):
                local_xobjects = _pikepdf_clone_resource_category(original_xobjects)
                local_resources["/XObject"] = local_xobjects
            else:
                local_xobjects = pikepdf.Dictionary()
                local_resources["/XObject"] = local_xobjects

    for instruction in instructions:
        try:
            operator = str(instruction.operator)
        except Exception:
            continue
        if operator != "Do":
            continue
        operands = instruction.operands
        if not operands:
            continue
        xname = operands[0]
        target = xobjects.get(xname) if isinstance(xobjects, pikepdf.Dictionary) else None
        if target is None:
            # Missing resources are left to the normal PDF renderer; this feature cannot safely
            # infer or rewrite a drawing object that the source PDF itself cannot resolve here.
            continue
        try:
            subtype = str(target.get("/Subtype"))
        except Exception:
            subtype = ""

        if subtype == "/Image":
            if bool(target.get("/ImageMask", False)):
                continue
            image_key = None
            try:
                image_key = tuple(target.objgen)
            except Exception:
                pass
            replacement = image_memo.get(image_key) if image_key is not None else None
            if replacement is None:
                replacement, native = _pikepdf_clone_image_for_decode(pdf, target, source_resources)
                if native:
                    stats["native"] += 1
                else:
                    replacement, _ = _pikepdf_raster_fallback_inverted_image(
                        pdf, target, source_resources)
                    stats["fallback"] += 1
                if image_key is not None:
                    image_memo[image_key] = replacement
            ensure_local_resources()
            local_xobjects[xname] = replacement
            changed = True
            stats["images"] += 1
            continue

        if subtype == "/Form":
            form_key = None
            try:
                form_key = tuple(target.objgen)
            except Exception:
                pass
            replacement_form = form_memo.get(form_key) if form_key is not None else None
            if replacement_form is None:
                form_resources = _pikepdf_form_source_resources(target, source_resources)
                nested_resources, nested_changed = _pikepdf_process_no_image_scope(
                    pdf, target, form_resources, form_memo, image_memo, active_forms, stats)
                if nested_changed:
                    replacement_form = _pikepdf_stream_clone(pdf, target)
                    replacement_form["/Resources"] = nested_resources
                    if form_key is not None:
                        form_memo[form_key] = replacement_form
                else:
                    replacement_form = target
                    if form_key is not None:
                        form_memo[form_key] = replacement_form
            if replacement_form is not target:
                ensure_local_resources()
                local_xobjects[xname] = replacement_form
                changed = True
            continue

    # Tiling patterns are content-bearing graphics scopes too. Recurse into PatternType 1
    # streams so images painted by a pattern are not accidentally inverted.
    patterns = source_resources.get("/Pattern")
    if isinstance(patterns, pikepdf.Dictionary):
        local_patterns = None
        for pname, pattern in patterns.items():
            if not isinstance(pattern, pikepdf.Stream):
                continue
            if str(pattern.get("/PatternType")) != "1":
                continue
            pattern_resources = pattern.get("/Resources")
            if pattern_resources is None:
                pattern_resources = source_resources
            elif not isinstance(pattern_resources, pikepdf.Dictionary):
                raise RuntimeError("Tiling pattern has invalid /Resources.")
            pattern_key = None
            try:
                pattern_key = tuple(pattern.objgen)
            except Exception:
                pass
            replacement_pattern = form_memo.get(("pattern",) + pattern_key) if pattern_key else None
            if replacement_pattern is None:
                nested_resources, nested_changed = _pikepdf_process_no_image_scope(
                    pdf, pattern, pattern_resources, form_memo, image_memo, active_forms, stats)
                if nested_changed:
                    replacement_pattern = _pikepdf_stream_clone(pdf, pattern)
                    replacement_pattern["/Resources"] = nested_resources
                else:
                    replacement_pattern = pattern
                if pattern_key:
                    form_memo[("pattern",) + pattern_key] = replacement_pattern
            if replacement_pattern is not pattern:
                if local_resources is None:
                    local_resources = _pikepdf_clone_resources(source_resources)
                if local_patterns is None:
                    local_patterns = _pikepdf_clone_resource_category(patterns)
                    local_resources["/Pattern"] = local_patterns
                local_patterns[pname] = replacement_pattern
                changed = True

    if changed:
        assert local_resources is not None
        return local_resources, True
    return source_resources, False


def _pikepdf_preinvert_visible_images(pdf, page):
    """Prepare all drawn embedded images for the subsequent page-level Difference inversion."""
    # pikepdf can externalize inline images without rasterizing their pixels. This gives the
    # recursive resource walker one uniform Image XObject representation and also covers inline
    # images nested inside Form XObjects.
    externalize = getattr(page, "externalize_inline_images", None)
    if callable(externalize):
        try:
            externalize(min_size=0, shallow=False)
        except Exception as exc:
            raise RuntimeError(f"Could not externalize inline images safely: {exc}") from exc
    else:
        # Current supported pikepdf exposes this operation. Silently ignoring inline images would
        # violate the advertised "No images" semantics, so fail the exact operation rather than
        # producing an incomplete result.
        try:
            instructions = pikepdf.parse_content_stream(page)
            has_inline = any(hasattr(item, "iimage") for item in instructions)
        except Exception as exc:
            raise RuntimeError(f"Could not inspect inline images: {exc}") from exc
        if has_inline:
            raise RuntimeError(
                "This pikepdf version cannot safely externalize inline images required by "
                "Inv. (no images).")

    page_resources = _pikepdf_ensure_local_page_resources(page)
    stats = {"images": 0, "native": 0, "fallback": 0}
    form_memo = {}
    image_memo = {}
    processed_resources, changed = _pikepdf_process_no_image_scope(
        pdf, page, page_resources, form_memo, image_memo, set(), stats)
    if changed and processed_resources is not page_resources:
        page["/Resources"] = processed_resources
    return stats

def _apply_pdf_filter_to_page(pdf, page, config):
    """Apply the complete filter stack with PDF-native content and compositing operations only."""
    cfg = _normalize_filter_config(config)
    if not _filter_config_active(cfg):
        return

    # Keep width/height available for the existing call structure, but the synthetic layer
    # helpers intentionally recompute an oversized page-coverage rectangle from the actual
    # page boxes so no filter can inherit a stale/zero-origin geometry assumption.
    _cover_x, _cover_y, width, height = _pikepdf_filter_coverage_rect(page)

    # Inv. (images only) reuses the exact image-object pre-inversion algorithm from
    # Inv. (no images), but intentionally omits the page-level Difference inversion.
    # A pure image-only preset can return immediately, preserving the page's original
    # transparency and all non-image content exactly as authored.
    if bool(cfg.get("invert_images_only", False)):
        _pikepdf_preinvert_visible_images(pdf, page)
        other_cfg = dict(cfg)
        other_cfg["invert_images_only"] = False
        if not _filter_config_active(other_cfg):
            return

    # Inv. (no images) uses targeted image pre-inversion followed by the shared isolated
    # DeviceRGB Difference inversion. The two inversions cancel for images, while non-image
    # artwork receives only the page-level inversion.
    if bool(cfg.get("invert_exclude_images", False)):
        _pikepdf_preinvert_visible_images(pdf, page)

    extgstate = _pikepdf_resources(page)
    bg_stream = _pikepdf_rect_stream(pdf, page, width, height, (1, 1, 1))

    orig = _pikepdf_content_objects(page)
    new_contents = [bg_stream]

    gamma = float(cfg["gamma"])
    gamma_applied = False
    if orig and abs(gamma - 1.0) > 1e-6:
        gamma_applied = _pikepdf_default_color_space_setup(page, gamma)

    new_contents.extend(orig)

    # If an existing page DefaultRGB/DefaultGray prevented the dedicated CalRGB mapping,
    # keep gamma visible via a restrained PDF-native overlay rather than changing the source
    # page's existing color-management definition.
    if abs(gamma - 1.0) > 1e-6 and not gamma_applied:
        # A pre-existing DefaultRGB/DefaultGray prevents us from installing the
        # calibrated mapping without replacing document color management. Use a
        # Normal black/white layer whose effect is fitted at middle gray to the same
        # encoded-RGB curve as the fast pixel preview. This keeps the fallback's
        # direction and midtone strength consistent instead of using an Overlay guess.
        middle_target = 0.5 ** (1.0 / gamma)
        if gamma > 1.0:
            gamma_opacity = max(0.0, min(1.0, 2.0 * middle_target - 1.0))
            gamma_color = (1.0, 1.0, 1.0)
        else:
            gamma_opacity = max(0.0, min(1.0, 1.0 - 2.0 * middle_target))
            gamma_color = (0.0, 0.0, 0.0)
        if gamma_opacity > 1e-6:
            layer = _add_pdf_constant_layer(
                pdf, page, extgstate, width, height,
                gamma_color, "Normal", gamma_opacity, "GammaFallback")
            if layer is not None:
                new_contents.append(layer)

    # Tone layers are intentionally applied after the original artwork. This is the robust
    # renderer-compatible path for adjustments that cannot be expressed by a single color-space
    # transform (or where a transfer function is not honored by the renderer).
    black_point = float(cfg["black_point"]) / 100.0
    if black_point > 1e-6:
        layer = _add_pdf_constant_layer(
            pdf, page, extgstate, width, height, (0, 0, 0),
            "Multiply", black_point * 0.60, "BlackPoint")
        if layer is not None:
            new_contents.append(layer)

    white_point = max(0.0, 100.0 - float(cfg["white_point"])) / 100.0
    if white_point > 1e-6:
        layer = _add_pdf_constant_layer(
            pdf, page, extgstate, width, height, (1, 1, 1),
            "Screen", white_point * 0.60, "WhitePoint")
        if layer is not None:
            new_contents.append(layer)

    contrast = float(cfg["contrast"])
    if abs(contrast) > 1e-6:
        source = max(0.0, min(1.0, 0.5 + (contrast / 100.0) * 0.40))
        layer = _add_pdf_constant_layer(
            pdf, page, extgstate, width, height,
            (source, source, source), "Overlay",
            abs(contrast) / 100.0 * 0.75, "Contrast")
        if layer is not None:
            new_contents.append(layer)

    brightness = float(cfg["brightness"])
    if brightness > 1e-6:
        layer = _add_pdf_constant_layer(
            pdf, page, extgstate, width, height, (1, 1, 1),
            "Normal", brightness / 100.0, "Brightness")
        if layer is not None:
            new_contents.append(layer)
    elif brightness < -1e-6:
        layer = _add_pdf_constant_layer(
            pdf, page, extgstate, width, height, (0, 0, 0),
            "Normal", -brightness / 100.0, "Brightness")
        if layer is not None:
            new_contents.append(layer)

    threshold = float(cfg["threshold"]) / 100.0
    if threshold > 1e-6:
        source = max(0.0, min(1.0, 0.5 + 0.47 * threshold))
        layer = _add_pdf_constant_layer(
            pdf, page, extgstate, width, height,
            (source, source, source), "Overlay",
            threshold * 0.55, "Threshold")
        if layer is not None:
            new_contents.append(layer)

    desat_amount = max(
        1.0 - cfg["saturation"] / 100.0,
        cfg["grayscale"] / 100.0,
    )
    if desat_amount > 1e-6:
        layer = _add_pdf_constant_layer(
            pdf, page, extgstate, width, height,
            (0.5, 0.5, 0.5), "Saturation",
            desat_amount, "Desat")
        if layer is not None:
            new_contents.append(layer)

    # Match the immediate Pillow preview: Normal blend mode with the same
    # overlay colors and alpha amounts for both Warmth and Tint.
    if abs(float(cfg["warmth"])) > 1e-6:
        c = _warmth_color(cfg["warmth"])
        layer = _add_pdf_constant_layer(
            pdf, page, extgstate, width, height,
            tuple(v / 255.0 for v in c), "Normal",
            abs(float(cfg["warmth"])) / 100.0 * 0.45, "Warmth")
        if layer is not None:
            new_contents.append(layer)

    if abs(float(cfg["tint"])) > 1e-6:
        c = _tint_color(cfg["tint"])
        layer = _add_pdf_constant_layer(
            pdf, page, extgstate, width, height,
            tuple(v / 255.0 for v in c), "Normal",
            abs(float(cfg["tint"])) / 100.0 * 0.45, "Tint")
        if layer is not None:
            new_contents.append(layer)

    # Inversion is a compositing operation, not a color-definition rewrite. Wrap the
    # accumulated stack in an isolated DeviceRGB transparency-group Form XObject so the white
    # Difference operation sees the fully composited page state in a controlled RGB space.
    invert = float(cfg["invert"])
    if invert > 1e-6:
        new_contents = _pikepdf_wrap_contents_with_inversion(
            pdf, page, new_contents, invert / 100.0, "Invert",
            page_resources=page.get("/Resources"))

    # The fixed Invert preset is represented by a final white Difference layer for backwards
    # compatibility with the stored filter configuration. Route that exact visual operation
    # through the same isolated inversion primitive rather than the generic page-level layer path.
    if cfg["opacity"] > 1e-6:
        layer_is_inversion = (
            str(cfg.get("layer_color", "")).strip().lower() == "#ffffff"
            and str(cfg.get("blend_mode", "")).strip() == "Difference"
        )
        if layer_is_inversion:
            new_contents = _pikepdf_wrap_contents_with_inversion(
                pdf, page, new_contents, cfg["opacity"] / 100.0, "LayerInvert",
                page_resources=page.get("/Resources"))
        else:
            layer_color = tuple(v / 255.0 for v in _filter_hex_to_rgb(cfg["layer_color"]))
            layer = _add_pdf_constant_layer(
                pdf, page, extgstate, width, height,
                layer_color, cfg["blend_mode"], cfg["opacity"] / 100.0, "Layer")
            if layer is not None:
                new_contents.append(layer)

    page.Contents = pikepdf.Array(new_contents)


def process_page_filters_pdf_file(input_pdf_path, output_pdf_path, page_configs):
    """Apply filter configs keyed by zero-based PDF page index."""
    try:
        with pikepdf.open(input_pdf_path) as pdf:
            for index, cfg in sorted(page_configs.items()):
                index = int(index)
                if index < 0 or index >= len(pdf.pages):
                    raise IndexError(f"Selected page index {index} is out of range.")
                _apply_pdf_filter_to_page(pdf, pdf.pages[index], cfg)
            pdf.save(output_pdf_path)
        return True
    except Exception:
        try:
            if os.path.exists(output_pdf_path):
                os.remove(output_pdf_path)
        except Exception:
            pass
        return False




class _FilterPreviewRenderThread(QtCore.QThread):
    """Persistent latest-request-wins worker for live filter preview rendering."""
    result_signal = QtCore.Signal(int, object, object)

    def __init__(self, parent=None):
        # Keep QThread lifetime independent of the viewer/widget that displays its result.
        super().__init__(None)
        self._owner_hint = parent
        _track_qthread(self)
        self._condition = threading.Condition()
        self._task = None
        self._busy = False
        self._stop_requested = False

    def is_busy(self):
        """Return whether the worker is actively processing a filter task."""
        with self._condition:
            return bool(self._task is not None or getattr(self, "_busy", False))

    def submit(self, generation, qimage, config):
        if qimage is None or qimage.isNull():
            return
        # QImage is implicitly shared and the cached base image is never mutated.
        # Keep the same object reference here so rapid slider movement does not incur
        # a full-size GUI-thread image copy for every request.
        with self._condition:
            # Keep only the newest queued request. Intermediate slider frames are stale.
            self._task = (int(generation), qimage, _normalize_filter_config(config))
            self._condition.notify()

    def stop(self):
        with self._condition:
            self._stop_requested = True
            self._task = None
            self._condition.notify()

    def run(self):
        while True:
            with self._condition:
                while not self._stop_requested and self._task is None:
                    self._condition.wait()
                if self._stop_requested:
                    return
                generation, qimage, config = self._task
                self._task = None
                self._busy = True

            try:
                rgba = qimage.convertToFormat(QtGui.QImage.Format.Format_RGBA8888)
                pixel_bytes = _qimage_buffer_bytes(rgba)
                image = Image.frombytes(
                    "RGBA", (rgba.width(), rgba.height()), pixel_bytes)
                filtered = _apply_filter_to_pil_image(
                    image, _fast_pixel_preview_filter_config(config))
                result = _pil_to_qimage(filtered)
                self.result_signal.emit(generation, result, None)
            except Exception as exc:
                self.result_signal.emit(
                    generation, None, f"{type(exc).__name__}: {exc}")
            finally:
                with self._condition:
                    self._busy = False
                    self._condition.notify_all()


class _SelectedPageFilterThread(QtCore.QThread):
    """Run selected-page vector filter application outside the GUI thread."""
    finished_signal = QtCore.Signal(bool, str)

    def __init__(self, input_pdf_path, output_pdf_path, page_configs, parent=None):
        super().__init__(None)
        self._owner_hint = parent
        _track_qthread(self)
        self.input_pdf_path = input_pdf_path
        self.output_pdf_path = output_pdf_path
        self.page_configs = {int(k): _normalize_filter_config(v)
                             for k, v in (page_configs or {}).items()}

    def run(self):
        try:
            ok = process_page_filters_pdf_file(
                self.input_pdf_path, self.output_pdf_path, self.page_configs)
            if ok:
                self.finished_signal.emit(True, "")
            else:
                self.finished_signal.emit(False, "Filter application failed for selected page(s).")
        except Exception as exc:
            self.finished_signal.emit(False, f"{type(exc).__name__}: {exc}")


def _flip_qpixmap(pixmap, flip_h, flip_v):
    if not (flip_h or flip_v):
        return pixmap
    t = QtGui.QTransform()
    cx = pixmap.width() / 2.0
    cy = pixmap.height() / 2.0
    t.translate(cx, cy)
    t.scale(-1 if flip_h else 1, -1 if flip_v else 1)
    t.translate(-cx, -cy)
    return pixmap.transformed(t)


# ============================================================
# VECTOR PAGE HELPERS
# ============================================================
def _visible_to_underlying(page, visible_rect):
    try:
        vr = page.rect
        vis = fitz.Rect(visible_rect) & vr
        if vis.is_empty:
            return None
        under = vis * page.derotation_matrix
        try:
            under = under & page.mediabox
        except Exception:
            pass
        if under.is_empty or under.width < 1 or under.height < 1:
            return None
        return fitz.Rect(
            min(under.x0, under.x1), min(under.y0, under.y1),
            max(under.x0, under.x1), max(under.y0, under.y1),
        )
    except Exception:
        return None


def _visible_box_to_underlying(source_pdf, page_idx, total_rotation, vis_box,
                                base_crop=None, stretch_ratio=None,
                                flip_h=False, flip_v=False):
    """Convert a visible crop selection back into source PDF coordinates.

    ``vis_box`` is relative to the displayed page. The inverse transforms are applied in the
    same reverse order as the visible editing pipeline: undo the visible flip first, then undo
    display-only stretch, then use PyMuPDF's derotation mapping to return to source coordinates.
    """
    try:
        with fitz.open(source_pdf) as doc:
            page = doc.load_page(page_idx)
            orig_rot = int(page.rotation) % 360
            source_crop = fitz.Rect(page.cropbox)

            if base_crop is not None:
                try:
                    candidate = fitz.Rect(*base_crop) & page.mediabox
                    if (not candidate.is_empty and candidate.width >= 1
                            and candidate.height >= 1):
                        source_crop = candidate
                except Exception:
                    pass

            # Explicitly establish the coordinate system that was visible in
            # the crop dialog.  This is crucial after a previous saved crop.
            try:
                page.set_cropbox(source_crop)
            except Exception:
                pass
            page.set_rotation((orig_rot + int(total_rotation)) % 360)

            visible_rect = fitz.Rect(page.rect)
            mapped_box = fitz.Rect(*vis_box)

            # The crop canvas shows flips in visible/page space. Undo the final display flip
            # before undoing stretch or derotating back to source coordinates. The helper maps
            # the stored source flip flags onto the visible axes when the page is rotated.
            vis_flip_h, vis_flip_v = _source_flip_for_display(
                bool(flip_h), bool(flip_v), int(total_rotation))
            if vis_flip_h or vis_flip_v:
                x_sum = visible_rect.x0 + visible_rect.x1
                y_sum = visible_rect.y0 + visible_rect.y1
                x0, x1 = mapped_box.x0, mapped_box.x1
                y0, y1 = mapped_box.y0, mapped_box.y1
                if vis_flip_h:
                    x0, x1 = x_sum - mapped_box.x1, x_sum - mapped_box.x0
                if vis_flip_v:
                    y0, y1 = y_sum - mapped_box.y1, y_sum - mapped_box.y0
                mapped_box = fitz.Rect(
                    min(x0, x1), min(y0, y1),
                    max(x0, x1), max(y0, y1))

            if stretch_ratio is not None:
                try:
                    ratio = float(stretch_ratio)
                    if math.isfinite(ratio) and ratio > 0:
                        stretched_w, stretched_h = calculate_stretch_dimensions(
                            visible_rect.width, visible_rect.height, ratio)
                        sx = visible_rect.width / stretched_w
                        sy = visible_rect.height / stretched_h
                        mapped_box = fitz.Rect(
                            visible_rect.x0 + (mapped_box.x0 - visible_rect.x0) * sx,
                            visible_rect.y0 + (mapped_box.y0 - visible_rect.y0) * sy,
                            visible_rect.x0 + (mapped_box.x1 - visible_rect.x0) * sx,
                            visible_rect.y0 + (mapped_box.y1 - visible_rect.y0) * sy,
                        )
                except (TypeError, ValueError, OverflowError):
                    pass

            under = _visible_to_underlying(page, mapped_box)
            if under is None:
                return None

            # derotation_matrix gives crop-relative unrotated coordinates.
            # Restore the real PDF/user-space origin exactly once.
            under.x0 += float(source_crop.x0)
            under.x1 += float(source_crop.x0)
            under.y0 += float(source_crop.y0)
            under.y1 += float(source_crop.y0)

            under = fitz.Rect(
                min(under.x0, under.x1), min(under.y0, under.y1),
                max(under.x0, under.x1), max(under.y0, under.y1),
            ) & page.mediabox
            if under.is_empty or under.width < 1 or under.height < 1:
                return None
            return (float(under.x0), float(under.y0),
                    float(under.x1), float(under.y1))
    except Exception:
        return None


def _source_flip_for_display(flip_h, flip_v, total_rotation):
    rh = int(total_rotation) % 360
    if rh in (90, 270):
        return bool(flip_v), bool(flip_h)
    return bool(flip_h), bool(flip_v)


def _flip_rect_in_source_space(page, rect, flip_h, flip_v):
    if rect is None:
        return None
    r = fitz.Rect(rect)
    mb = page.mediabox
    cx = (mb.x0 + mb.x1) / 2.0
    cy = (mb.y0 + mb.y1) / 2.0

    x0, x1 = r.x0, r.x1
    y0, y1 = r.y0, r.y1
    if flip_h:
        x0, x1 = 2.0 * cx - r.x1, 2.0 * cx - r.x0
    if flip_v:
        y0, y1 = 2.0 * cy - r.y1, 2.0 * cy - r.y0

    out = fitz.Rect(min(x0, x1), min(y0, y1),
                    max(x0, x1), max(y0, y1))
    try:
        out = out & mb
    except Exception:
        pass
    if out.is_empty or out.width < 1 or out.height < 1:
        return None
    return out


def _apply_flip_to_page(page, flip_h, flip_v):
    if not (flip_h or flip_v):
        return
    try:
        doc = page.parent
        xrefs = list(page.get_contents())
        if not xrefs:
            return
        mb = page.mediabox
        cx = (mb.x0 + mb.x1) / 2.0
        cy = (mb.y0 + mb.y1) / 2.0
    except Exception:
        return

    sx = -1 if flip_h else 1
    sy = -1 if flip_v else 1
    tx = 2.0 * cx if flip_h else 0.0
    ty = 2.0 * cy if flip_v else 0.0
    prefix = ("q %g 0 0 %g %g %g cm\n" %
              (sx, sy, tx, ty)).encode("ascii")

    try:
        first = xrefs[0]
        first_data = doc.xref_stream(first)
        doc.update_stream(first, prefix + first_data)
        last = xrefs[-1]
        last_data = doc.xref_stream(last)
        doc.update_stream(last, last_data + b"\nQ")
    except Exception:
        pass


def apply_entry_to_page(page, entry, src_rot=None):
    if src_rot is None:
        try:
            src_rot = int(page.rotation) % 360
        except Exception:
            src_rot = 0
    try:
        src_rot = int(src_rot) % 360
    except Exception:
        src_rot = 0

    flip_h = bool(entry.get('flip_h', False))
    flip_v = bool(entry.get('flip_v', False))
    rot = int(entry.get('rotation', 0)) % 360
    total_rot = (src_rot + rot) % 360

    crop_rect = None
    crop = entry.get('crop')
    if crop:
        try:
            crop_rect = fitz.Rect(*crop)
            crop_rect = crop_rect & page.mediabox
            if crop_rect.is_empty or crop_rect.width < 1 or crop_rect.height < 1:
                crop_rect = None
        except Exception:
            crop_rect = None

    src_h, src_v = _source_flip_for_display(flip_h, flip_v, total_rot)

    final_crop = crop_rect
    if src_h or src_v:
        if crop_rect is not None:
            final_crop = _flip_rect_in_source_space(
                page, crop_rect, src_h, src_v)
        _apply_flip_to_page(page, src_h, src_v)

    if final_crop is not None:
        try:
            page.set_cropbox(final_crop)
        except Exception:
            pass

    if rot:
        try:
            page.set_rotation((src_rot + rot) % 360)
        except Exception:
            pass


def _render_selected_image_sp_common(entries, indices, image_dpi, image_format,
                              output_paths, save_dlg, results, worker_errors, webp_mode="lossy"):
    """Render selected pages synchronously with live per-page progress."""
    total = len(entries)
    source_docs = {}
    image_format = str(image_format or "jpg").lower()
    try:
        for selection_index in indices:
            if save_dlg.is_cancel_requested():
                break
            entry = entries[selection_index]
            source_pdf = entry.get("source_pdf")
            page_idx = int(entry.get("original_idx", 0))
            try:
                if source_pdf not in source_docs:
                    source_docs[source_pdf] = fitz.open(source_pdf)
                page = source_docs[source_pdf].load_page(page_idx)
                src_rot = int(page.rotation) % 360
                ordered_doc = None
                if _page_design_has_any(entry) and _page_design_anchor_state(entry) is not None:
                    ordered_doc = _page_design_ordered_document(entry, apply_filters=True)
                    page = ordered_doc[0]
                else:
                    apply_entry_to_page(page, entry, src_rot=src_rot)
                rect = page.rect
                if rect.width <= 0 or rect.height <= 0:
                    raise RuntimeError("Page has invalid dimensions after applying edits")
                target_width = _thumbnail_target_width_for_dpi(rect, image_dpi)
                zoom = target_width / max(1.0, float(rect.width))
                pix = page.get_pixmap(matrix=fitz.Matrix(zoom, zoom), alpha=False)
                img = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
                if not (_page_design_has_any(entry) and _page_design_anchor_state(entry) is not None):
                    filter_cfg = _entry_filter_config(entry)
                    if _filter_config_active(filter_cfg):
                        img = _apply_filter_to_pil_image(img, filter_cfg)
                    stretch_ratio = entry.get("stretch_ratio")
                    if stretch_ratio is not None:
                        sw, sh = calculate_stretch_dimensions(
                            img.width, img.height, float(stretch_ratio))
                        target = (max(1, int(round(sw))), max(1, int(round(sh))))
                        if img.size != target:
                            resample = getattr(Image, "Resampling", Image).LANCZOS
                            img = img.resize(target, resample=resample)
                    img = _page_design_pil_draw(img, entry, image_dpi)
                if ordered_doc is not None:
                    try:
                        ordered_doc.close()
                    except Exception:
                        pass
                    ordered_doc = None
                out_path = output_paths[selection_index]
                if image_format == "png":
                    img.save(out_path, format="PNG", optimize=False, compress_level=6)
                elif image_format == "webp":
                    save_kwargs = {"method": 4, "lossless": str(webp_mode or "lossy").lower() == "lossless"}
                    if not save_kwargs["lossless"]:
                        save_kwargs["quality"] = 100
                    img.save(out_path, format="WEBP", **save_kwargs)
                else:
                    img.save(out_path, format="JPEG", quality=85)
                size_bytes = int(os.path.getsize(out_path))
                results[selection_index] = (out_path, size_bytes, int(img.width), int(img.height))
                completed = selection_index + 1
                save_dlg.set_progress(completed, max(1, total), "Generating images")
                if completed == 1 or completed == total or completed % 10 == 0:
                    save_dlg.append_log(
                        f"  Generated {completed}/{total} {image_format.upper()} image(s)", "info")
                QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)
            except Exception as exc:
                worker_errors.append(f"Selected page {selection_index + 1}: {exc}")
                save_dlg.set_progress(selection_index + 1, max(1, total), "Generating images")
                QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)
    finally:
        for doc in source_docs.values():
            try:
                doc.close()
            except Exception:
                pass


# ============================================================
# GLOBAL STATE
# ============================================================
total_page = 0
animation_stopped = False

remove_first_slides = False
indicate_stars = False
pdf_bookmark = False
page_numbers = False
slide_borders = False
first_slide_numbers = []

LOG_CALLBACK = None
INFINITE_ANIM_START = None
INFINITE_ANIM_STOP = None
PROGRESS_UPDATE = None


def log(msg, level="info"):
    if LOG_CALLBACK:
        LOG_CALLBACK(msg, level)


def start_infinite_anim(label="Working"):
    if INFINITE_ANIM_START:
        INFINITE_ANIM_START(label)


def stop_infinite_anim():
    if INFINITE_ANIM_STOP:
        INFINITE_ANIM_STOP()


def update_progress(value, total, label=""):
    if PROGRESS_UPDATE:
        PROGRESS_UPDATE(value, total, label)


def format_file_size(num_bytes):
    if num_bytes < 1024:
        return f"{num_bytes} B"
    if num_bytes < 1024 * 1024:
        return f"{num_bytes / 1024:.2f} KB"
    if num_bytes < 1024 * 1024 * 1024:
        return f"{num_bytes / (1024 * 1024):.2f} MB"
    return f"{num_bytes / (1024 ** 3):.2f} GB"


def _pad_label(label, width=14):
    return label + " " * max(0, width - len(label))


def _is_inside(path, folder):
    try:
        path_abs = os.path.abspath(path)
        folder_abs = os.path.abspath(folder)
        return os.path.commonpath([path_abs, folder_abs]) == folder_abs
    except ValueError:
        return False


def validate_files_exist(paths):
    return [p for p in paths if not os.path.isfile(p)]


# ============================================================
# SUBPROCESS PIPE BRIDGE
# ============================================================
def _setup_queue_callbacks(conn):
    global LOG_CALLBACK, INFINITE_ANIM_START, INFINITE_ANIM_STOP, PROGRESS_UPDATE

    def _send(msg):
        try:
            conn.send(msg)
        except (BrokenPipeError, EOFError, OSError):
            pass

    LOG_CALLBACK = lambda msg, level="info": _send(('log', (msg, level)))
    INFINITE_ANIM_START = lambda label="": _send(('inf_start', label))
    INFINITE_ANIM_STOP = lambda: _send(('inf_stop', None))
    PROGRESS_UPDATE = lambda v, t, l="": _send(('progress', (v, t, l)))


# ============================================================
# ALGORITHM FUNCTIONS
# ============================================================
def check_free_storage():
    total, used, free = shutil.disk_usage(os.getcwd())
    return f"{free / (1024 ** 3):.2f} GB"


def _prepare_temp_folder():
    if not os.path.exists(STATIC_FOLDER):
        os.makedirs(STATIC_FOLDER, exist_ok=True)
    remove_temp_folder()
    os.makedirs(TEMP_FOLDER, exist_ok=True)


def remove_temp_folder(max_retries=5, delay=1):
    retries = 0
    while retries < max_retries:
        try:
            if os.path.exists(TEMP_FOLDER):
                shutil.rmtree(TEMP_FOLDER)
            break
        except OSError:
            retries += 1
            time.sleep(delay)


def _cleanup_temp_workspace_background():
    """Recover stale temporary artifacts without blocking application startup.

    The previous workspace is renamed out of the active path first. That makes the cleanup
    independent from the GUI: the application gets a fresh temp directory immediately while
    the old directory is removed by a daemon thread. If the atomic rename is unavailable,
    a best-effort contents cleanup is used without retry sleeps.
    """
    try:
        active = os.path.abspath(TEMP_FOLDER)
        parent = os.path.dirname(active) or os.getcwd()
        os.makedirs(parent, exist_ok=True)

        if not os.path.exists(active):
            os.makedirs(active, exist_ok=True)
            return

        stale = os.path.join(
            parent,
            f".{os.path.basename(active)}_startup_cleanup_{uuid.uuid4().hex}",
        )
        try:
            os.replace(active, stale)
        except OSError:
            # Cross-platform fallback: remove only current entries, never sleep/retry here.
            try:
                for entry in os.scandir(active):
                    try:
                        if entry.is_dir(follow_symlinks=False):
                            shutil.rmtree(entry.path, ignore_errors=True)
                        else:
                            os.remove(entry.path)
                    except Exception:
                        pass
            except Exception:
                pass
            os.makedirs(active, exist_ok=True)
            return

        os.makedirs(active, exist_ok=True)
        try:
            shutil.rmtree(stale, ignore_errors=True)
        except Exception:
            pass
    except Exception:
        try:
            os.makedirs(TEMP_FOLDER, exist_ok=True)
        except Exception:
            pass


def _start_background_temp_cleanup():
    """Start startup temp recovery without holding up the Qt event loop."""
    threading.Thread(
        target=_cleanup_temp_workspace_background,
        name="MergerzTempCleanup",
        daemon=True,
    ).start()


def unique_filename(base, ext, folder):
    filename = f"{base}{ext}"
    counter = 1
    while os.path.exists(os.path.join(folder, filename)):
        filename = f"{base}_{counter}{ext}"
        counter += 1
    return filename


def format_time(seconds):
    days = int(seconds // 86400)
    seconds %= 86400
    minutes = int(seconds // 60)
    seconds = int(seconds % 60)
    return f"{days}d : {minutes}m : {seconds}s"


