def create_cover_page(page_orientation, title_text, chapter_no, subject,
                      student_name, include_back=True):
    try:
        if page_orientation == "Portrait":
            layout = cover_params["A4_portrait"]
        else:
            layout = cover_params["A4_landscape"]

        title_font_obj    = _font_or_none(layout["title_font"]) or _fallback_font("Times-Bold")
        cs_font_obj       = _font_or_none(layout["cs_font"])    or _fallback_font("helv")
        student_font_obj  = _font_or_none(layout["student_font"]) or _fallback_font("helv")

        use_custom_title = _looks_like_font(layout["title_font"])
        use_custom_helv  = _looks_like_font(layout["cs_font"])
        use_custom_back  = _looks_like_font(layout["backside_font"])
        title_pdfname = "cTitle" if use_custom_title else "tibo"
        helv_pdfname  = "cHelv"  if use_custom_helv  else "helv"
        back_pdfname  = "cHelv"  if use_custom_back  else "helv"

        if title_font_obj and title_font_obj.text_length(
                title_text, fontsize=layout["title_font_size"]) > 450:
            raise ValueError("Input limit reached for chapter_name")

        if cs_font_obj:
            w_static = cs_font_obj.text_length("Chapter: ", fontsize=layout["cs_font_size"])
            w_sep    = cs_font_obj.text_length("  |  Subject: ", fontsize=layout["cs_font_size"])
            max_user_width = 450 - (w_static + w_sep)
            w_ch = cs_font_obj.text_length(str(chapter_no), fontsize=layout["cs_font_size"])
            w_su = cs_font_obj.text_length(subject, fontsize=layout["cs_font_size"])
            if w_ch + w_su > max_user_width:
                raise ValueError("Input limit reached for chapter_no / subject")

        if student_font_obj and student_font_obj.text_length(
                student_name, fontsize=layout["student_font_size"]) > 213:
            raise ValueError("Input limit reached for student_name")

        doc = fitz.open()
        page = doc.new_page(width=layout["width"], height=layout["height"])
        page.draw_rect(fitz.Rect(0, 0, layout["width"], layout["height"]),
                       color=(1, 1, 1), fill=(1, 1, 1))

        if use_custom_title:
            page.insert_font(fontname="cTitle", fontfile=layout["title_font"])
        if use_custom_helv:
            page.insert_font(fontname="cHelv", fontfile=layout["cs_font"])

        line_above_start = ((layout["width"] - layout["title_line_above_width"]) / 2,
                            layout["title_line_above_y"])
        line_above_end = (((layout["width"] + layout["title_line_above_width"]) / 2),
                          layout["title_line_above_y"])
        page.draw_line(line_above_start, line_above_end,
                       color=(0, 0, 0), width=layout["title_line_thickness"])

        title_rect = fitz.Rect(0,
                               layout["title_y"] - layout["title_font_size"],
                               layout["width"],
                               layout["title_y"] + layout["title_font_size"])
        page.insert_textbox(title_rect, title_text,
                            fontname=title_pdfname,
                            fontsize=layout["title_font_size"],
                            color=(0, 0, 0), align=1)

        line_below_start = ((layout["width"] - layout["title_line_below_width"]) / 2,
                            layout["title_line_below_y"])
        line_below_end = (((layout["width"] + layout["title_line_below_width"]) / 2),
                          layout["title_line_below_y"])
        page.draw_line(line_below_start, line_below_end,
                       color=(0, 0, 0), width=layout["title_line_thickness"])

        cs_text = f"Chapter: {chapter_no}  |  Subject: {subject}"
        cs_rect = fitz.Rect(0,
                            layout["cs_line_y"] - layout["cs_font_size"],
                            layout["width"],
                            layout["cs_line_y"] + layout["cs_font_size"])
        page.insert_textbox(cs_rect, cs_text,
                            fontname=helv_pdfname,
                            fontsize=layout["cs_font_size"],
                            color=(0, 0, 0), align=1)

        bg_pad = {"t": 1, "b": 5.45, "l": 3.8, "r": 4}
        student_width = (student_font_obj.text_length(
            student_name, fontsize=layout["student_font_size"])
            if student_font_obj else 0)
        student_x_start = layout["width"] - student_width - 60 - bg_pad["l"]
        page.draw_rect(
            fitz.Rect(student_x_start,
                      layout["student_y"] - layout["student_font_size"] - bg_pad["t"],
                      layout["width"] - 60 + bg_pad["r"],
                      layout["student_y"] + bg_pad["b"]),
            color=None, fill=(0, 0, 0))
        page.insert_text((student_x_start + bg_pad["l"], layout["student_y"]),
                         student_name,
                         fontname=helv_pdfname,
                         fontsize=layout["student_font_size"],
                         color=(1, 1, 1))

        if include_back:
            doc.new_page(width=layout["width"], height=layout["height"])
            page2 = doc[-1]
            page2.draw_rect(fitz.Rect(0, 0, layout["width"], layout["height"]),
                            color=(1, 1, 1), fill=(1, 1, 1))
            if use_custom_back:
                page2.insert_font(fontname="cHelv", fontfile=layout["backside_font"])
            backside_rect = fitz.Rect(
                0,
                layout["backside_y"] - layout["backside_font_size"],
                layout["width"],
                layout["backside_y"] + layout["backside_font_size"])
            page2.insert_textbox(backside_rect, layout["backside_text"],
                                 fontname=back_pdfname,
                                 fontsize=layout["backside_font_size"],
                                 color=(0, 0, 0), align=1)

        output_path = os.path.join(TEMP_FOLDER, "cover_page.pdf")
        try:
            doc.save(output_path)
        finally:
            try:
                doc.close()
            except Exception:
                pass
        return True
    except ValueError as ve:
        try:
            if 'output_path' in locals() and os.path.exists(output_path):
                os.remove(output_path)
        except Exception:
            pass
        log(f"Cover validation failed: {ve}", "error")
        raise
    except Exception as e:
        try:
            if 'output_path' in locals() and os.path.exists(output_path):
                os.remove(output_path)
        except Exception:
            pass
        log(f"Cover page error: {e}", "error")
        return False


# ============================================================
# MERGE PDFs
# ============================================================
def merge_pdfs_to_result(pdf_paths, output_folder, add_bookmarks=False,
                         optimize_pdf=False, optimizer_conn=None):
    global animation_stopped
    animation_stopped = False
    start_infinite_anim("Merging PDFs")
    start_time = time.time()
    pdf_count = len(pdf_paths)
    log(f"Starting to merge {pdf_count} PDF(s).", "info")

    merged_pdf = fitz.open()
    toc_entries = []
    running_page = 0
    for idx, path in enumerate(pdf_paths, start=1):
        if not os.path.exists(path):
            raise FileNotFoundError(f"Source PDF not found: {path}")
        try:
            with fitz.open(path) as pdf:
                pc = pdf.page_count
                merged_pdf.insert_pdf(pdf)
            log(f"[{idx}/{pdf_count}] {os.path.basename(path)} — {pc} page(s)", "info")
            if add_bookmarks:
                title = os.path.splitext(os.path.basename(path))[0]
                toc_entries.append([1, title, running_page + 1])
            running_page += pc
        except Exception as e:
            log(f"[{idx}/{pdf_count}] Failed to read {os.path.basename(path)}: {e}", "error")
            raise

    if add_bookmarks and toc_entries:
        try:
            merged_pdf.set_toc(toc_entries)
            log(f"Added {len(toc_entries)} PDF bookmark(s).", "success")
        except Exception as e:
            log(f"Bookmark insertion failed: {e}", "error")

    total_pages = merged_pdf.page_count
    output_filename = unique_filename('Merged_PDF', '.pdf', output_folder)
    result_path = os.path.join(output_folder, output_filename)
    merged_pdf.save(result_path)
    merged_pdf.close()
    try:
        size_str = format_file_size(os.path.getsize(result_path))
    except OSError:
        size_str = "unknown size"
    log(f"Merged {pdf_count} PDF(s) into {total_pages} page(s) — {output_filename} ({size_str})", "success")

    optimization_info = None
    if bool(optimize_pdf):
        # Reuse Make Printable's default optimizer and its verified replacement rule:
        # only a smaller, same-page-count candidate replaces the original merged PDF.
        optimization_info = _optimize_printable_merged_working_pdf(
            result_path, optimizer_conn)

    animation_stopped = True
    stop_infinite_anim()
    time_taken = format_time(time.time() - start_time)
    result = {
        'path': result_path,
        'pdfs': pdf_count,
        'pages': total_pages,
        'time': time_taken,
        'optimization_requested': bool(optimize_pdf),
    }
    if optimization_info is not None:
        result.update(optimization_info)
    return result


def merge_pdfs_to_temp_vector(pdf_paths):
    global total_page, first_slide_numbers, remove_first_slides
    merged_pdf = fitz.open()
    first_slide_numbers = []
    pdf_count = len(pdf_paths)
    log(f"Combining {pdf_count} PDF(s) to temporary file...", "info")
    for idx, path in enumerate(pdf_paths, start=1):
        if not os.path.exists(path):
            raise FileNotFoundError(f"Source PDF not found: {path}")
        try:
            with fitz.open(path) as pdf:
                pc = pdf.page_count
                first_slide_numbers.append(merged_pdf.page_count + 1)
                if remove_first_slides:
                    if pc > 1:
                        merged_pdf.insert_pdf(pdf, from_page=1)
                        log(f"[{idx}/{pdf_count}] {os.path.basename(path)} — {pc} page(s), skipped 1st", "info")
                    else:
                        merged_pdf.insert_pdf(pdf)
                        log(f"[{idx}/{pdf_count}] {os.path.basename(path)} — only 1 page, kept it", "warning")
                else:
                    merged_pdf.insert_pdf(pdf)
                    log(f"[{idx}/{pdf_count}] {os.path.basename(path)} — {pc} page(s)", "info")
        except Exception as e:
            log(f"[{idx}/{pdf_count}] Failed to read {os.path.basename(path)}: {e}", "error")
            raise
    temp_path = os.path.join(TEMP_FOLDER, 'Merged_PDF_temp.pdf')
    total_page = merged_pdf.page_count
    try:
        merged_pdf.save(temp_path)
    except Exception:
        try:
            merged_pdf.close()
        except Exception:
            pass
        try:
            if os.path.exists(temp_path):
                os.remove(temp_path)
        except Exception:
            pass
        raise
    merged_pdf.close()
    log(f"Temporary PDF built: {total_page} page(s).", "success")
    return temp_path


