class PluginTaskThread(QtCore.QThread):
    log_signal = QtCore.Signal(str, str)
    progress_signal = QtCore.Signal(int, int, str)
    infinite_signal = QtCore.Signal(bool, str)
    result_signal = QtCore.Signal(dict)
    error_signal = QtCore.Signal(str)
    cancelled_signal = QtCore.Signal()

    def __init__(self, task, parent=None):
        # The progress dialog is a UI target, not a safe lifetime owner for the thread.
        super().__init__(None)
        self._ui_target = parent
        _track_qthread(self)
        self._task = task
        self._cancel = threading.Event()

    def request_cancel(self):
        self._cancel.set()
        try:
            self._task.cancel()
        except Exception:
            pass

    def is_cancelled(self):
        return self._cancel.is_set()

    def log(self, message, level="info"):
        self.log_signal.emit(str(message), str(level))

    def progress(self, current, total, label=""):
        self.progress_signal.emit(int(current), int(total), str(label))

    def set_infinite(self, visible, label=""):
        self.infinite_signal.emit(bool(visible), str(label))

    def set_eta_enabled(self, enabled):
        parent = self._ui_target
        setter = getattr(parent, "set_eta_enabled", None)
        if callable(setter):
            setter(bool(enabled))

    def set_cancel_enabled(self, enabled, text=None):
        parent = self._ui_target
        setter = getattr(parent, "set_cancel_enabled", None)
        if callable(setter):
            setter(bool(enabled), text)

    def run(self):
        try:
            result = self._task.run(self)
            if self.is_cancelled():
                self.cancelled_signal.emit()
                return
            self.result_signal.emit(result if result is not None else {"ok": True})
        except Exception as exc:
            if self.is_cancelled():
                self.cancelled_signal.emit()
            else:
                self.error_signal.emit(f"{type(exc).__name__}: {exc}")


class _PluginInstallerTask:
    def __init__(self, plugin_id):
        self.plugin_id = plugin_id
        self._proc = None

    def cancel(self):
        _terminate_process(self._proc)

    def _run_proc(self, worker, cmd, cwd=None, env=None, label=None):
        if worker.is_cancelled():
            raise RuntimeError("Installation cancelled.")
        if label:
            worker.set_infinite(True, str(label))
            worker.log(label, "info")
        kwargs = dict(
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1,
        )
        if os.name == "nt":
            kwargs["creationflags"] = (
                getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
                | getattr(subprocess, "CREATE_NO_WINDOW", 0)
            )
        else:
            kwargs["start_new_session"] = True
        self._proc = subprocess.Popen(cmd, **kwargs)
        rc = None
        try:
            for line in iter(self._proc.stdout.readline, ""):
                if line:
                    worker.log(line.rstrip("\r\n"), "info")
                if worker.is_cancelled():
                    _terminate_process(self._proc)
                    raise RuntimeError("Installation cancelled.")
            rc = self._proc.wait()
        finally:
            self._proc = None
        if rc != 0:
            raise RuntimeError(f"Command failed with exit code {rc}: {' '.join(cmd)}")

    def _create_venv(self, worker, root):
        self._run_proc(
            worker,
            [sys.executable, "-m", "venv", os.path.join(root, "venv")],
            cwd=root,
            env=os.environ.copy(),
            label="Creating OCR VM...",
        )
        pyexe = _ocr_venv_python(root)
        if not os.path.isfile(pyexe):
            raise RuntimeError("The isolated virtual environment was created without a usable Python executable.")
        cp = _run_capture([pyexe, "-m", "ensurepip", "--upgrade"], env=_plugin_env(root), timeout=180)
        if cp.returncode == 0:
            worker.log("Bundled pip bootstrap completed.", "success")
        else:
            worker.log("ensurepip is unavailable; checking for an existing pip module.", "warning")
        cp = _run_capture([pyexe, "-m", "pip", "--version"], env=_plugin_env(root), timeout=60)
        if cp.returncode != 0:
            raise RuntimeError("The isolated Python environment does not provide pip.")
        worker.log(cp.stdout.strip(), "info")
        return pyexe

    def _pip_base(self, pyexe):
        return [
            pyexe,
            "-m",
            "pip",
            "install",
            "--disable-pip-version-check",
            "--only-binary=:all:",
            "--prefer-binary",
        ]

    def run(self, worker):
        runtime = _current_runtime_info()
        plan = _ocr_package_plan(runtime, gpu=False)
        parent = _ocr_plugin_root()
        os.makedirs(parent, exist_ok=True)
        staging = os.path.join(parent, "staging_" + uuid.uuid4().hex)
        os.makedirs(staging, exist_ok=True)
        worker.set_infinite(True, "Preparing OCR")
        worker.log("Mergerz OCR plugin installer", "success")
        worker.log(f"OS: {runtime['os']} {runtime['os_release']}", "info")
        worker.log(f"Architecture: {runtime['machine']} ({runtime['bits']}-bit)", "info")
        worker.log(f"Python: {runtime['python']}", "info")
        worker.log("CPU OCR baseline: ONNX Runtime", "success")
        worker.log("Libraries: " + ", ".join(plan["packages"]), "info")
        try:
            pyexe = self._create_venv(worker, staging)
            env = _plugin_env(staging)
            base = self._pip_base(pyexe)
            self._run_proc(
                worker,
                base + ["--dry-run", "--upgrade"] + plan["packages"],
                cwd=staging,
                env=env,
                label="Installing dependencies...",
            )
            self._run_proc(
                worker,
                base + ["--upgrade"] + plan["packages"],
                cwd=staging,
                env=env,
                label="Installing dependencies...",
            )
            _write_plugin_runner(staging)
            versions = _package_versions_in_venv(pyexe, ["paddleocr", "onnxruntime"])
            worker.set_infinite(True, "Fetching OCR languages and models...")
            worker.log("Fetching OCR languages and models...", "info")
            language_info = _fetch_ocr_languages_from_plugin(staging, worker=worker)
            _save_ocr_capability_cache(
                language_info.get("paddleocr_version") or versions.get("paddleocr"),
                language_info.get("languages"),
                language_info.get("models"),
                language_info.get("language_models"),
                language_info.get("automatic_model"),
                language_info.get("automatic_pairs"),
                language_info.get("paddleocr_default_model"),
            )
            verify_cmd = [pyexe, _ocr_runner_path(staging), "--verify"]
            self._run_proc(
                worker,
                verify_cmd,
                cwd=staging,
                env=env,
                label="Testing OCR...",
            )
            manifest = {
                "manifest_version": PLUGIN_MANIFEST_VERSION,
                "plugin_id": OCR_PLUGIN_ID,
                "plugin_version": OCR_PLUGIN_VERSION,
                "api_version": PLUGIN_API_VERSION,
                "verified": True,
                "inference_engine": "onnxruntime",
                "python": {
                    "version": runtime["python"],
                    "machine": runtime["machine"],
                    "implementation": runtime["implementation"],
                },
                "platform": {
                    "system": runtime["os"],
                    "release": runtime["os_release"],
                },
                "packages": versions,
                "gpu_support": {
                    "installed": False,
                    "healthy": False,
                    "package": None,
                    "version": None,
                    "extra_packages": {},
                },
            }
            worker.set_infinite(True, "Finishing OCR...")
            _write_json_atomic(_ocr_manifest_path(staging), manifest)
            _promote_plugin(staging)
            worker.log("OCR plugin activated successfully with CPU OCR support.", "success")
            return {"ok": True, "status": _plugin_status(), "manifest": manifest}
        except Exception:
            shutil.rmtree(staging, ignore_errors=True)
            raise


class _LibreOfficeInstallerTask:
    """Download, extract, verify, and atomically activate the shared LibreOffice runtime."""
    def __init__(self, update=False, update_info=None):
        self.update = bool(update)
        self.update_info = dict(update_info or {})
        self._external_proc = None
        self._response = None

    def cancel(self):
        try:
            response = self._response
            if response is not None:
                response.close()
        except Exception:
            pass
        _terminate_process(self._external_proc)

    def run(self, worker):
        system, arch, _path_part, _template = _libreoffice_platform_descriptor()
        parent = _libreoffice_plugin_root()
        os.makedirs(parent, exist_ok=True)
        staging = os.path.join(parent, "staging_" + uuid.uuid4().hex)
        os.makedirs(staging, exist_ok=True)
        worker.set_infinite(True, "Checking for updates..." if self.update else "Preparing LibreOffice")
        worker.log("Mergerz LibreOffice Runtime installer", "success")
        worker.log(f"Platform: {system} / {arch}", "info")
        try:
            current_manifest = _read_json_file(_libreoffice_manifest_path(_libreoffice_active_root())) or {}
            current_distribution = str(current_manifest.get("distribution_version") or "").strip()
            if self.update and self.update_info:
                item = (self.update_info.get("updates") or {}).get("libreoffice") or {}
                version = str(item.get("latest") or "").strip()
                if not version:
                    raise RuntimeError("No confirmed LibreOffice update is available to install.")
            else:
                version = _discover_latest_libreoffice_version(worker)
                worker.log(f"Latest stable LibreOffice release: {version}", "success")
                if self.update:
                    if current_distribution and not _version_is_newer(version, current_distribution):
                        worker.log(
                            f"No update available for LibreOffice Runtime ({current_distribution}).",
                            "success")
                        return {
                            "ok": True,
                            "no_update": True,
                            "plugin": "LibreOffice Runtime",
                            "current_version": current_distribution,
                            "latest_version": version,
                        }
                    worker.log(
                        f"LibreOffice Runtime update available: {current_distribution or 'unknown'} → {version}",
                        "info")
            url, filename = _libreoffice_download_url(version)
            worker.log(f"Distribution: {filename}", "info")
            archive_path = os.path.join(staging, filename)
            worker.set_infinite(True, "Downloading runtime")
            worker.log(f"Downloading official LibreOffice runtime from {url}", "info")
            _download_file_with_progress(url, archive_path, worker)
            if worker.is_cancelled():
                raise RuntimeError("LibreOffice installation cancelled.")

            worker.set_infinite(True, "Verifying download")
            archive_sha256 = _sha256_file(archive_path)
            expected_sha256, checksum_url = _official_checksum(url, filename, worker)
            if expected_sha256:
                if archive_sha256.lower() != expected_sha256.lower():
                    raise RuntimeError(
                        "LibreOffice download checksum verification failed. "
                        "The downloaded archive does not match the official checksum."
                    )
                worker.log(f"Official SHA-256 checksum verified: {archive_sha256}", "success")
                worker.log(f"Checksum source: {checksum_url}", "info")
            else:
                worker.log(
                    "No standard official SHA-256 sidecar was published at the expected location; "
                    "continuing with bundled soffice verification.", "warning")
                worker.log(f"Downloaded archive SHA-256: {archive_sha256}", "info")

            if system == "linux":
                runtime_root = _extract_linux_libreoffice_distribution(archive_path, staging, worker)
            elif system == "windows":
                runtime_root = _extract_windows_libreoffice_distribution(archive_path, staging, worker)
            elif system == "macos":
                runtime_root = _extract_macos_libreoffice_distribution(archive_path, staging, worker)
            else:
                raise RuntimeError(f"Unsupported operating system: {system}")
            try:
                os.remove(archive_path)
                worker.log("Downloaded LibreOffice archive removed after extraction.", "success")
            except Exception as cleanup_exc:
                worker.log(f"Could not remove downloaded archive: {cleanup_exc}", "warning")

            worker.set_infinite(True, "Testing LibreOffice")
            soffice = _find_libreoffice_soffice(runtime_root)
            if not soffice or not os.path.isfile(soffice):
                raise RuntimeError("LibreOffice runtime was extracted, but no bundled soffice executable was found.")
            probe_profile = os.path.join(staging, "probe_profile")
            runtime_version, raw_version = _libreoffice_version_from_command(soffice, probe_profile)
            worker.log(f"Bundled soffice: {soffice}", "info")
            worker.log(f"Verified LibreOffice version: {runtime_version}", "success")

            try:
                relative_soffice = os.path.relpath(soffice, staging)
            except Exception:
                relative_soffice = os.path.basename(soffice)
            manifest = {
                "manifest_version": LIBREOFFICE_PLUGIN_MANIFEST_VERSION,
                "plugin_id": LIBREOFFICE_PLUGIN_ID,
                "verified": True,
                "runtime_version": runtime_version,
                "distribution_version": version,
                "platform": {"system": system, "architecture": arch},
                "distribution_file": filename,
                "soffice_relpath": relative_soffice,
                "download_url": url,
                "runtime_type": "bundled",
                "archive_sha256": archive_sha256,
                "checksum_verified": bool(expected_sha256),
            }
            worker.set_infinite(True, "Activating LibreOffice update" if self.update else "Finishing LibreOffice")
            _write_json_atomic(_libreoffice_manifest_path(staging), manifest)
            # probe_profile is not needed after verification.
            shutil.rmtree(probe_profile, ignore_errors=True)
            if worker.is_cancelled():
                raise RuntimeError("LibreOffice installation cancelled before activation.")
            # The final directory swap is the only non-cancellable critical section.
            worker.set_cancel_enabled(False, "Finishing...")
            _promote_libreoffice_plugin(staging)
            worker.log("LibreOffice Runtime activated successfully.", "success")
            return {"ok": True, "status": _libreoffice_plugin_status(), "manifest": manifest}
        except Exception:
            shutil.rmtree(staging, ignore_errors=True)
            raise


class _LibreOfficeUninstallerTask:
    def cancel(self):
        pass

    def run(self, worker):
        root = _libreoffice_plugin_root()
        active = _libreoffice_active_root()
        worker.set_infinite(True, "Removing LibreOffice Runtime")
        artifact_present = os.path.isdir(active) or os.path.isfile(_libreoffice_manifest_path(active))
        if artifact_present:
            worker.log("Removing the isolated LibreOffice runtime...", "info")
            shutil.rmtree(active, ignore_errors=False)
            worker.log("LibreOffice Runtime removed.", "success")
        else:
            worker.log("LibreOffice Runtime was already absent.", "info")
        if os.path.isdir(root):
            for name in os.listdir(root):
                if name.startswith("staging_") or name == "active_backup":
                    shutil.rmtree(os.path.join(root, name), ignore_errors=True)
            try:
                if not os.listdir(root):
                    os.rmdir(root)
            except Exception:
                pass
        worker.progress(1, 1, "Uninstall")
        return {"ok": True, "removed": artifact_present}


class _Pdf2DocxInstallerTask:
    """Install PDF2DOCX into its own isolated virtual environment and verify it."""
    def __init__(self):
        self._proc = None

    def cancel(self):
        _terminate_process(self._proc)

    def _run_proc(self, worker, cmd, cwd=None, env=None, label=None):
        if worker.is_cancelled():
            raise RuntimeError("Installation cancelled.")
        if label:
            worker.set_infinite(True, str(label))
            worker.log(label, "info")
        kwargs = dict(
            cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            text=True, bufsize=1,
        )
        if os.name == "nt":
            kwargs["creationflags"] = (
                getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
                | getattr(subprocess, "CREATE_NO_WINDOW", 0)
            )
        else:
            kwargs["start_new_session"] = True
        self._proc = subprocess.Popen(cmd, **kwargs)
        rc = None
        try:
            for line in iter(self._proc.stdout.readline, ""):
                if line:
                    worker.log(line.rstrip("\r\n"), "info")
                if worker.is_cancelled():
                    _terminate_process(self._proc)
                    raise RuntimeError("Installation cancelled.")
            rc = self._proc.wait()
        finally:
            self._proc = None
        if rc != 0:
            raise RuntimeError(f"Command failed with exit code {rc}: {' '.join(cmd)}")

    def _create_venv(self, worker, root):
        self._run_proc(
            worker,
            [sys.executable, "-m", "venv", os.path.join(root, "venv")],
            cwd=root, env=os.environ.copy(), label="Creating PDF2DOCX VM...",
        )
        pyexe = _pdf2docx_venv_python(root)
        if not os.path.isfile(pyexe):
            raise RuntimeError("The isolated PDF2DOCX Python environment was not created correctly.")
        cp = _run_capture([pyexe, "-m", "ensurepip", "--upgrade"],
                          env=_pdf2docx_plugin_env(root), timeout=180)
        if cp.returncode == 0:
            worker.log("Bundled pip bootstrap completed.", "success")
        else:
            worker.log("ensurepip is unavailable; checking for an existing pip module.", "warning")
        cp = _run_capture([pyexe, "-m", "pip", "--version"],
                          env=_pdf2docx_plugin_env(root), timeout=60)
        if cp.returncode != 0:
            raise RuntimeError("The isolated PDF2DOCX environment does not provide pip.")
        worker.log(cp.stdout.strip(), "info")
        return pyexe

    def _pip_base(self, pyexe):
        return [
            pyexe, "-m", "pip", "install", "--disable-pip-version-check",
            "--prefer-binary",
        ]

    def run(self, worker):
        runtime = _current_runtime_info()
        if runtime["implementation"] != "CPython":
            raise RuntimeError("The PDF2DOCX plugin requires CPython.")
        py = tuple(runtime.get("python_tuple") or sys.version_info[:3])[:2]
        if py < PDF2DOCX_PLUGIN_PYTHON_MIN:
            raise RuntimeError("The PDF2DOCX plugin requires Python 3.10 or newer.")
        if runtime["bits"] != 64:
            raise RuntimeError("The PDF2DOCX plugin requires a 64-bit Python runtime.")

        parent = _pdf2docx_plugin_root()
        os.makedirs(parent, exist_ok=True)
        staging = os.path.join(parent, "staging_" + uuid.uuid4().hex)
        os.makedirs(staging, exist_ok=True)
        worker.set_infinite(True, "Preparing PDF2DOCX")
        worker.log("Mergerz PDF2DOCX plugin installer", "success")
        worker.log(f"OS: {runtime['os']} {runtime['os_release']}", "info")
        worker.log(f"Architecture: {runtime['machine']} ({runtime['bits']}-bit)", "info")
        worker.log(f"Python: {runtime['python']}", "info")
        worker.log("Library: PDF2DOCX", "success")
        try:
            pyexe = self._create_venv(worker, staging)
            env = _pdf2docx_plugin_env(staging)
            base = self._pip_base(pyexe)
            # Deliberately unpinned: pip resolves the latest available compatible PDF2DOCX.
            self._run_proc(
                worker, base + ["--dry-run", "pdf2docx"],
                cwd=staging, env=env, label="Installing dependencies...",
            )
            self._run_proc(
                worker, base + ["--upgrade", "pdf2docx"],
                cwd=staging, env=env, label="Installing dependencies...",
            )
            _write_pdf2docx_runner(staging)
            self._run_proc(
                worker, [pyexe, _pdf2docx_runner_path(staging), "--verify"],
                cwd=staging, env=env, label="Testing PDF2DOCX...",
            )
            versions = _package_versions_in_venv(pyexe, ["pdf2docx"])
            manifest = {
                "manifest_version": PDF2DOCX_PLUGIN_MANIFEST_VERSION,
                "plugin_id": PDF2DOCX_PLUGIN_ID,
                "api_version": PLUGIN_API_VERSION,
                "verified": True,
                "python": {
                    "version": runtime["python"],
                    "machine": runtime["machine"],
                    "implementation": runtime["implementation"],
                },
                "platform": {
                    "system": runtime["os"],
                    "release": runtime["os_release"],
                },
                "packages": versions,
                "library_display": "PDF2DOCX",
            }
            worker.set_infinite(True, "Finishing PDF2DOCX...")
            _write_json_atomic(_pdf2docx_manifest_path(staging), manifest)
            _promote_pdf2docx_plugin(staging)
            worker.log("PDF2DOCX plugin activated successfully.", "success")
            return {"ok": True, "status": _pdf2docx_plugin_status(), "manifest": manifest}
        except Exception:
            shutil.rmtree(staging, ignore_errors=True)
            raise


class _OCRUpdateTask:
    """Stage and activate a previously confirmed OCR update without rechecking online."""
    def __init__(self, update_info=None):
        self.update_info = dict(update_info or {})
        self._proc = None

    def cancel(self):
        _terminate_process(self._proc)

    def _run_proc(self, worker, cmd, cwd=None, env=None, label=None):
        if worker.is_cancelled():
            raise RuntimeError("OCR update cancelled.")
        if label:
            worker.set_infinite(True, label)
            worker.log(label, "info")
        kwargs = dict(cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                      text=True, bufsize=1)
        if os.name == "nt":
            kwargs["creationflags"] = (
                getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
                | getattr(subprocess, "CREATE_NO_WINDOW", 0))
        else:
            kwargs["start_new_session"] = True
        self._proc = subprocess.Popen(cmd, **kwargs)
        try:
            for line in iter(self._proc.stdout.readline, ""):
                if line:
                    worker.log(line.rstrip("\r\n"), "info")
                if worker.is_cancelled():
                    _terminate_process(self._proc)
                    raise RuntimeError("OCR update cancelled.")
            rc = self._proc.wait()
        finally:
            self._proc = None
        if rc != 0:
            raise RuntimeError(f"Command failed with exit code {rc}: {' '.join(cmd)}")

    def run(self, worker):
        status = _plugin_status()
        if not status.get("healthy"):
            raise RuntimeError(status.get("reason") or "OCR plugin is not ready for update.")
        installed = {str(name): str(version) for name, version in (status.get("libraries") or []) if version}
        packages = ["paddleocr"]
        if "onnxruntime-gpu" in installed:
            packages.append("onnxruntime-gpu")
        else:
            packages.append("onnxruntime")
        if self.update_info:
            updates = dict(self.update_info.get("updates") or {})
            if not updates:
                raise RuntimeError("No confirmed OCR updates are available to install.")
        else:
            worker.set_infinite(True, "Checking for updates...")
            worker.log("Checking the latest available OCR library releases...", "info")
            latest, updates = _latest_package_updates(
                {name: installed.get(name) for name in packages if installed.get(name)},
                worker=worker,
            )
            for name, ver in latest.items():
                worker.log(
                    f"Latest checked: {_plugin_library_display_name(name)} {ver}",
                    "info",
                )
            if not updates:
                worker.log("No update available for OCR.", "success")
                return {"ok": True, "no_update": True, "plugin": "OCR", "current_versions": installed, "latest_versions": latest}

        runtime = _current_runtime_info()
        py = tuple(runtime.get("python_tuple") or sys.version_info[:3])[:2]
        if runtime["implementation"] != "CPython" or py < OCR_PYTHON_MIN or py > OCR_PYTHON_MAX[:2] or runtime["bits"] != 64:
            raise RuntimeError("The current Python runtime is not supported for an OCR update.")
        parent = _ocr_plugin_root()
        os.makedirs(parent, exist_ok=True)
        staging = os.path.join(parent, "staging_update_" + uuid.uuid4().hex)
        os.makedirs(staging, exist_ok=True)
        use_gpu = bool((status.get("gpu_support") or {}).get("installed"))
        try:
            worker.set_infinite(True, "Preparing OCR update")
            self._run_proc(worker, [sys.executable, "-m", "venv", os.path.join(staging, "venv")],
                           cwd=staging, env=os.environ.copy(), label="Creating OCR VM...")
            pyexe = _ocr_venv_python(staging)
            if not os.path.isfile(pyexe):
                raise RuntimeError("The staged OCR virtual environment was not created correctly.")
            _run_capture([pyexe, "-m", "ensurepip", "--upgrade"], env=_plugin_env(staging), timeout=180)
            env = _plugin_env(staging)
            base = [pyexe, "-m", "pip", "install", "--disable-pip-version-check", "--only-binary=:all:", "--prefer-binary"]
            install_specs = ["paddleocr", "onnxruntime-gpu[cuda,cudnn]" if use_gpu else "onnxruntime"]
            self._run_proc(worker, base + ["--upgrade"] + install_specs, cwd=staging, env=env, label="Installing dependencies...")
            _write_plugin_runner(staging)
            versions = _package_versions_in_venv(
                pyexe, ["paddleocr", "onnxruntime-gpu" if use_gpu else "onnxruntime"]
            )
            worker.set_infinite(True, "Fetching OCR languages and models...")
            worker.log("Fetching OCR languages and models...", "info")
            language_info = _fetch_ocr_languages_from_plugin(staging, worker=worker)
            _save_ocr_capability_cache(
                language_info.get("paddleocr_version") or versions.get("paddleocr"),
                language_info.get("languages"),
                language_info.get("models"),
                language_info.get("language_models"),
                language_info.get("automatic_model"),
                language_info.get("automatic_pairs"),
                language_info.get("paddleocr_default_model"),
            )
            verify_cmd = [pyexe, _ocr_runner_path(staging), "--verify"]
            if use_gpu:
                verify_cmd.extend(["--prefer-gpu", "--require-gpu"])
            self._run_proc(worker, verify_cmd, cwd=staging, env=env, label="Testing OCR...")
            manifest = dict(status.get("manifest") or {})
            manifest.update({
                "manifest_version": PLUGIN_MANIFEST_VERSION,
                "plugin_id": OCR_PLUGIN_ID,
                "api_version": PLUGIN_API_VERSION,
                "plugin_version": OCR_PLUGIN_VERSION,
                "verified": True,
                "packages": versions,
                "python": {
                    "version": runtime["python"],
                    "machine": runtime["machine"],
                    "implementation": runtime["implementation"],
                },
                "platform": {"system": runtime["os"], "release": runtime["os_release"]},
            })
            if use_gpu:
                after = _pip_list_in_venv(pyexe, env)
                manifest["gpu_support"] = {
                    "installed": True, "healthy": True, "package": "onnxruntime-gpu",
                    "version": versions.get("onnxruntime-gpu"),
                    "extra_packages": _nvidia_packages(after),
                }
            else:
                manifest["gpu_support"] = {
                    "installed": False, "healthy": False, "package": None,
                    "version": None, "extra_packages": {},
                }
            _write_json_atomic(_ocr_manifest_path(staging), manifest)
            if worker.is_cancelled():
                raise RuntimeError("OCR update cancelled before activation.")
            worker.set_infinite(True, "Activating OCR update")
            worker.set_cancel_enabled(False, "Finishing...")
            _promote_plugin(staging)
            worker.log("OCR plugin update activated successfully.", "success")
            return {"ok": True, "updated": True, "status": _plugin_status(), "manifest": manifest, "updates": updates}
        except Exception:
            shutil.rmtree(staging, ignore_errors=True)
            raise


class _Pdf2DocxUpdateTask:
    """Stage and activate a previously confirmed PDF2DOCX update without rechecking online."""
    def __init__(self, update_info=None):
        self.update_info = dict(update_info or {})
        self._proc = None

    def cancel(self):
        _terminate_process(self._proc)

    def _run_proc(self, worker, cmd, cwd=None, env=None, label=None):
        if worker.is_cancelled():
            raise RuntimeError("PDF2DOCX update cancelled.")
        if label:
            worker.set_infinite(True, label)
            worker.log(label, "info")
        kwargs = dict(cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)
        if os.name == "nt":
            kwargs["creationflags"] = (
                getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
                | getattr(subprocess, "CREATE_NO_WINDOW", 0))
        else:
            kwargs["start_new_session"] = True
        self._proc = subprocess.Popen(cmd, **kwargs)
        try:
            for line in iter(self._proc.stdout.readline, ""):
                if line:
                    worker.log(line.rstrip("\r\n"), "info")
                if worker.is_cancelled():
                    _terminate_process(self._proc)
                    raise RuntimeError("PDF2DOCX update cancelled.")
            rc = self._proc.wait()
        finally:
            self._proc = None
        if rc != 0:
            raise RuntimeError(f"Command failed with exit code {rc}: {' '.join(cmd)}")

    def run(self, worker):
        status = _pdf2docx_plugin_status()
        if not status.get("healthy"):
            raise RuntimeError(status.get("reason") or "PDF2DOCX plugin is not ready for update.")
        installed = {str(name): str(version) for name, version in (status.get("libraries") or []) if version}
        current = installed.get("pdf2docx")
        if not current:
            raise RuntimeError("The installed PDF2DOCX version could not be determined.")
        if self.update_info:
            updates = dict(self.update_info.get("updates") or {})
            update_item = updates.get("pdf2docx")
            if not update_item:
                raise RuntimeError("No confirmed PDF2DOCX update is available to install.")
            latest = str(update_item.get("latest") or "").strip()
        else:
            worker.set_infinite(True, "Checking for updates...")
            worker.log("Checking the latest available PDF2DOCX release...", "info")
            latest = _latest_pypi_release("pdf2docx", worker=worker)
            worker.log(f"Current version: PDF2DOCX {current}", "info")
            worker.log(f"Latest checked: PDF2DOCX {latest}", "info")
            if not _version_is_newer(latest, current):
                worker.log("No update available for PDF to DOCX.", "success")
                return {"ok": True, "no_update": True, "plugin": "PDF2DOCX", "current_version": current, "latest_version": latest}

        runtime = _current_runtime_info()
        py = tuple(runtime.get("python_tuple") or sys.version_info[:3])[:2]
        if runtime["implementation"] != "CPython" or py < PDF2DOCX_PLUGIN_PYTHON_MIN or runtime["bits"] != 64:
            raise RuntimeError("The current Python runtime is not supported for a PDF2DOCX update.")
        parent = _pdf2docx_plugin_root()
        os.makedirs(parent, exist_ok=True)
        staging = os.path.join(parent, "staging_update_" + uuid.uuid4().hex)
        os.makedirs(staging, exist_ok=True)
        try:
            self._run_proc(worker, [sys.executable, "-m", "venv", os.path.join(staging, "venv")],
                           cwd=staging, env=os.environ.copy(), label="Creating PDF2DOCX VM...")
            pyexe = _pdf2docx_venv_python(staging)
            if not os.path.isfile(pyexe):
                raise RuntimeError("The staged PDF2DOCX virtual environment was not created correctly.")
            _run_capture([pyexe, "-m", "ensurepip", "--upgrade"], env=_pdf2docx_plugin_env(staging), timeout=180)
            env = _pdf2docx_plugin_env(staging)
            base = [pyexe, "-m", "pip", "install", "--disable-pip-version-check", "--prefer-binary"]
            self._run_proc(worker, base + ["--upgrade", "pdf2docx"], cwd=staging, env=env, label="Installing dependencies...")
            _write_pdf2docx_runner(staging)
            self._run_proc(worker, [pyexe, _pdf2docx_runner_path(staging), "--verify"],
                           cwd=staging, env=env, label="Testing PDF2DOCX...")
            versions = _package_versions_in_venv(pyexe, ["pdf2docx"])
            manifest = dict(status.get("manifest") or {})
            manifest.update({
                "manifest_version": PDF2DOCX_PLUGIN_MANIFEST_VERSION,
                "plugin_id": PDF2DOCX_PLUGIN_ID,
                "api_version": PLUGIN_API_VERSION,
                "verified": True,
                "packages": versions,
                "library_display": "PDF2DOCX",
                "python": {
                    "version": runtime["python"],
                    "machine": runtime["machine"],
                    "implementation": runtime["implementation"],
                },
                "platform": {"system": runtime["os"], "release": runtime["os_release"]},
            })
            _write_json_atomic(_pdf2docx_manifest_path(staging), manifest)
            if worker.is_cancelled():
                raise RuntimeError("PDF2DOCX update cancelled before activation.")
            worker.set_infinite(True, "Activating PDF2DOCX update")
            worker.set_cancel_enabled(False, "Finishing...")
            _promote_pdf2docx_plugin(staging)
            worker.log("PDF2DOCX plugin update activated successfully.", "success")
            return {"ok": True, "updated": True, "status": _pdf2docx_plugin_status(), "manifest": manifest, "updates": {"pdf2docx": {"current": current, "latest": latest}}}
        except Exception:
            shutil.rmtree(staging, ignore_errors=True)
            raise


class _PluginBatchUpdateTask:
    """Install already-confirmed plugin updates sequentially in one progress workflow."""
    def __init__(self, update_results):
        self.update_results = [dict(item) for item in (update_results or [])]
        self._current_task = None

    def cancel(self):
        current = self._current_task
        if current is not None:
            try:
                current.cancel()
            except Exception:
                pass

    def _make_task(self, result):
        plugin_id = result.get("plugin_id")
        if plugin_id == OCR_PLUGIN_ID:
            return _OCRUpdateTask(update_info=result)
        if plugin_id == PDF2DOCX_PLUGIN_ID:
            return _Pdf2DocxUpdateTask(update_info=result)
        if plugin_id == LIBREOFFICE_PLUGIN_ID:
            return _LibreOfficeInstallerTask(update=True, update_info=result)
        raise ValueError(f"Unknown plugin id: {plugin_id}")

    def run(self, worker):
        successes = []
        failures = []
        total = len(self.update_results)
        for index, result in enumerate(self.update_results, 1):
            if worker.is_cancelled():
                raise RuntimeError("Plugin updates cancelled.")
            plugin_name = str(result.get("plugin") or _plugin_update_display_name(result.get("plugin_id")))
            worker.set_cancel_enabled(True, "Cancel")
            worker.set_infinite(True, f"Updating {plugin_name}...")
            worker.log(f"Updating {plugin_name} ({index}/{total})...", "info")
            task = self._make_task(result)
            self._current_task = task
            try:
                child_result = task.run(worker)
                if child_result and child_result.get("ok"):
                    successes.append(plugin_name)
                    worker.log(f"{plugin_name} update completed successfully.", "success")
                else:
                    failures.append((plugin_name, "Update did not complete successfully."))
                    worker.log(f"{plugin_name} update did not complete successfully.", "error")
            except Exception as exc:
                if worker.is_cancelled():
                    raise
                failures.append((plugin_name, f"{type(exc).__name__}: {exc}"))
                worker.log(f"{plugin_name} update failed: {type(exc).__name__}: {exc}", "error")
            finally:
                self._current_task = None

        summary_lines = []
        if successes:
            summary_lines.append("Updated successfully: " + ", ".join(successes))
        if failures:
            summary_lines.append(
                "Updates with errors: "
                + ", ".join(name for name, _ in failures)
            )
            for name, error in failures:
                summary_lines.append(f"{name}: {error}")
        summary = "\n".join(summary_lines) or "No plugin updates were installed."
        return {
            "ok": True,
            "updated": successes,
            "failures": failures,
            "partial_failure": bool(failures),
            "summary": summary,
        }


class _LibreOfficeConversionTask:
    """Run the shared bundled LibreOffice runtime against a temporary output file."""
    def __init__(self, input_path, output_dir, target_ext, spec):
        self.input_path = os.path.abspath(str(input_path))
        self.output_dir = os.path.abspath(str(output_dir))
        self.target_ext = str(target_ext).lstrip(".").lower()
        self.spec = dict(spec or {})
        self._proc = None
        self._profile_dir = None

    def cancel(self):
        _terminate_process(self._proc)

    def run(self, worker):
        api = get_libreoffice_runtime_api()
        if not os.path.isfile(self.input_path):
            raise RuntimeError("The selected input file no longer exists.")
        os.makedirs(self.output_dir, exist_ok=True)
        input_ext = os.path.splitext(self.input_path)[1].lower()
        output_ext = self.target_ext
        worker.set_infinite(True, "Preparing to convert")
        worker.log(f"Input file: {self.input_path}", "info")
        worker.log(f"Output format: {output_ext.upper()}", "info")
        worker.log(f"LibreOffice runtime: {api['version']}", "success")
        worker.log("Output is being written to a temporary file until the final save location is confirmed.", "info")
        command, self._profile_dir = build_libreoffice_headless_command(
            self.input_path, self.output_dir, output_ext,
            filter_name=self.spec.get("filter_name"),
            input_filter_name=self.spec.get("input_filter_name"),
        )
        kwargs = {
            "cwd": os.path.dirname(api["soffice"]),
            "env": api["environment"],
            "stdout": subprocess.PIPE,
            "stderr": subprocess.STDOUT,
            "text": True,
            "bufsize": 1,
        }
        if os.name == "nt":
            kwargs["creationflags"] = (
                getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
                | getattr(subprocess, "CREATE_NO_WINDOW", 0)
            )
        else:
            kwargs["start_new_session"] = True
        worker.set_infinite(True, "Converting")
        worker.log(f"Converting {input_ext.lstrip('.').upper()} to {output_ext.upper()}...", "info")
        self._proc = subprocess.Popen(command, **kwargs)
        try:
            for line in iter(self._proc.stdout.readline, ""):
                if line:
                    clean = _strip_ansi_sequences(line.rstrip("\r\n"))
                    if clean:
                        worker.log(clean, "info")
                if worker.is_cancelled():
                    _terminate_process(self._proc)
                    raise RuntimeError("Conversion cancelled.")
            rc = self._proc.wait()
        finally:
            self._proc = None
            if self._profile_dir:
                shutil.rmtree(self._profile_dir, ignore_errors=True)
                self._profile_dir = None
        if rc != 0:
            raise RuntimeError(f"LibreOffice conversion failed with exit code {rc}.")

        stem = os.path.splitext(os.path.basename(self.input_path))[0]
        expected = os.path.join(self.output_dir, stem + "." + output_ext)
        if not os.path.isfile(expected):
            candidates = []
            for name in os.listdir(self.output_dir):
                full = os.path.join(self.output_dir, name)
                if os.path.isfile(full) and name.lower().endswith("." + output_ext):
                    candidates.append(full)
            if len(candidates) == 1:
                expected = candidates[0]
        if not os.path.isfile(expected) or os.path.getsize(expected) <= 0:
            raise RuntimeError("LibreOffice finished without producing a valid output file.")
        size = os.path.getsize(expected)
        worker.log(f"Temporary output created: {format_file_size(size)}", "success")
        return {"ok": True, "path": expected, "size": size}

class _Pdf2DocxConversionTask:
    """Run PDF2DOCX from the isolated plugin environment against a temporary DOCX."""
    def __init__(self, input_pdf, output_docx, password=None):
        self.input_pdf = os.path.abspath(str(input_pdf))
        self.output_docx = os.path.abspath(str(output_docx))
        self.password = password
        self._proc = None

    def cancel(self):
        _terminate_process(self._proc)

    def run(self, worker):
        status = _pdf2docx_plugin_status()
        if not status.get("healthy"):
            raise RuntimeError(status.get("reason") or "PDF2DOCX plugin is not ready.")
        pyexe = status["python"]
        runner = status["runner"]
        if not os.path.isfile(self.input_pdf):
            raise RuntimeError("The selected PDF no longer exists.")
        os.makedirs(os.path.dirname(self.output_docx), exist_ok=True)
        worker.set_eta_enabled(False)
        worker.set_infinite(True, "Preparing to convert")
        worker.log(f"Input PDF: {self.input_pdf}", "info")
        worker.log("Output is being written to a temporary file until the final save location is confirmed.", "info")
        kwargs = dict(
            cwd=status["root"], env=_pdf2docx_plugin_env(status["root"]),
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            text=True, bufsize=1,
        )
        if os.name == "nt":
            kwargs["creationflags"] = (
                getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
                | getattr(subprocess, "CREATE_NO_WINDOW", 0)
            )
        else:
            kwargs["start_new_session"] = True
        command = [pyexe, runner, "--convert", self.input_pdf, self.output_docx]
        if self.password is not None:
            command.append("--password-stdin")
        self._proc = subprocess.Popen(command, **kwargs)
        try:
            if self.password is not None:
                self._proc.stdin.write(self.password + "\n")
            self._proc.stdin.close()
        except Exception:
            try:
                self._proc.stdin.close()
            except Exception:
                pass
        rc = None
        current_stage = None
        current_total = None
        stage_finished_sent = False
        try:
            for line in iter(self._proc.stdout.readline, ""):
                if line:
                    clean = _strip_ansi_sequences(line.rstrip("\r\n"))
                    worker.log(clean, "info")

                    stage_match = re.search(
                        r"\[([1-4])/4\]\s*(Opening document|Analyzing document|Parsing pages|Creating pages)\.\.\.",
                        clean,
                        flags=re.IGNORECASE,
                    )
                    if stage_match:
                        stage_name = stage_match.group(2).strip().lower()
                        if stage_name == "parsing pages":
                            current_stage = "Parsing pages"
                            current_total = None
                            stage_finished_sent = False
                            worker.set_eta_enabled(False)
                            worker.set_infinite(True, "Parsing pages")
                        elif stage_name == "creating pages":
                            current_stage = "Creating Pages"
                            current_total = None
                            stage_finished_sent = False
                            worker.set_eta_enabled(False)
                            worker.set_infinite(True, "Creating Pages")
                        else:
                            worker.set_eta_enabled(True)
                            current_stage = None
                            current_total = None
                            stage_finished_sent = False
                            worker.set_infinite(True, "Preparing to convert")

                    if current_stage:
                        page_match = re.search(r"\((\d+)\s*/\s*(\d+)\)\s*Page\s+\d+", clean, flags=re.IGNORECASE)
                        if page_match:
                            current_value = int(page_match.group(1))
                            current_total = int(page_match.group(2))
                            worker.progress(current_value, current_total, current_stage)
                            if current_value >= current_total and not stage_finished_sent:
                                # ProgressDialog deliberately holds the 100% stage for a
                                # short moment before switching to its indeterminate
                                # "Please wait..." state for unreported library work.
                                stage_finished_sent = True

                if worker.is_cancelled():
                    _terminate_process(self._proc)
                    raise RuntimeError("Conversion cancelled.")
            rc = self._proc.wait()
        finally:
            self._proc = None
        if rc != 0:
            raise RuntimeError(f"PDF2DOCX conversion failed with exit code {rc}.")
        if not os.path.isfile(self.output_docx) or os.path.getsize(self.output_docx) <= 0:
            raise RuntimeError("PDF2DOCX finished without producing a valid DOCX file.")
        size = os.path.getsize(self.output_docx)
        worker.log(f"Temporary DOCX created: {format_file_size(size)}", "success")
        return {"ok": True, "path": self.output_docx, "size": size}


class _Pdf2DocxUninstallerTask:
    def cancel(self):
        pass

    def run(self, worker):
        root = _pdf2docx_plugin_root()
        worker.set_infinite(True, "Removing PDF2DOCX Plugin")
        worker.log("Removing the isolated PDF2DOCX plugin environment...", "info")
        if os.path.isdir(root):
            shutil.rmtree(root, ignore_errors=False)
            worker.log("PDF2DOCX plugin environment removed.", "success")
            return {"ok": True, "removed": True}
        worker.log("PDF2DOCX plugin was already absent.", "info")
        return {"ok": True, "removed": False}



def _uninstall_packages(worker, task, pyexe, package_names, env, label):
    names = [n for n in package_names if n]
    if not names:
        return
    task._run_proc(
        worker,
        [pyexe, "-m", "pip", "uninstall", "-y"] + names,
        cwd=os.path.dirname(pyexe),
        env=env,
        label=label,
    )


class _PluginGpuSupportTask:
    def __init__(self, install=True):
        self.install = bool(install)
        self._proc = None

    def cancel(self):
        _terminate_process(self._proc)

    def _run_proc(self, worker, cmd, cwd=None, env=None, label=None):
        if worker.is_cancelled():
            raise RuntimeError("GPU support operation cancelled.")
        if label:
            worker.set_infinite(True, str(label))
            worker.log(label, "info")
        kwargs = dict(
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1,
        )
        if os.name == "nt":
            kwargs["creationflags"] = (
                getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
                | getattr(subprocess, "CREATE_NO_WINDOW", 0)
            )
        else:
            kwargs["start_new_session"] = True
        self._proc = subprocess.Popen(cmd, **kwargs)
        rc = None
        try:
            for line in iter(self._proc.stdout.readline, ""):
                if line:
                    worker.log(line.rstrip("\r\n"), "info")
                if worker.is_cancelled():
                    _terminate_process(self._proc)
                    raise RuntimeError("GPU support operation cancelled.")
            rc = self._proc.wait()
        finally:
            self._proc = None
        if rc != 0:
            raise RuntimeError(f"Command failed with exit code {rc}: {' '.join(cmd)}")

    def _pip(self, pyexe):
        return [
            pyexe,
            "-m",
            "pip",
            "install",
            "--disable-pip-version-check",
            "--only-binary=:all:",
            "--prefer-binary",
        ]

    def _uninstall_ort(self, worker, pyexe, env, extra_names=None):
        names = ["onnxruntime", "onnxruntime-gpu"]
        names.extend(sorted(set(extra_names or [])))
        self._run_proc(
            worker,
            [pyexe, "-m", "pip", "uninstall", "-y"] + names,
            cwd=os.path.dirname(pyexe),
            env=env,
            label="Replacing ONNX Runtime...",
        )

    def _install_cpu(self, worker, pyexe, env):
        self._run_proc(
            worker,
            self._pip(pyexe) + ["--upgrade", "onnxruntime"],
            cwd=os.path.dirname(pyexe),
            env=env,
            label="Restoring CPU ORT...",
        )

    def _install_gpu(self, worker, pyexe, env, package):
        self._run_proc(
            worker,
            self._pip(pyexe) + ["--upgrade", package],
            cwd=os.path.dirname(pyexe),
            env=env,
            label=f"Installing GPU dependencies...",
        )

    def run(self, worker):
        status = _plugin_status()
        if not status.get("healthy"):
            raise RuntimeError(status.get("reason") or "Install the OCR plugin before changing GPU support.")

        root = status["root"]
        manifest = dict(status.get("manifest") or {})
        runtime = _current_runtime_info()
        gpu_plan = _gpu_support_plan(runtime)
        pyexe = _ocr_venv_python(root)
        env = _plugin_env(root)
        existing_gpu = bool((manifest.get("gpu_support") or {}).get("installed"))
        current_gpu_extras = dict((manifest.get("gpu_support") or {}).get("extra_packages") or {})
        worker.set_infinite(True, "Configuring GPU")

        if self.install:
            if not gpu_plan.get("supported"):
                raise RuntimeError(gpu_plan.get("reason") or "GPU acceleration is not supported on this system.")
            if existing_gpu:
                worker.log("GPU support is already installed. Re-running GPU verification...", "info")
                verify_cmd = [pyexe, _ocr_runner_path(root), "--verify", "--prefer-gpu", "--require-gpu"]
                self._run_proc(worker, verify_cmd, cwd=root, env=env, label="Testing GPU OCR...")
                manifest["verified"] = True
                manifest["gpu_support"]["healthy"] = True
                _write_json_atomic(_ocr_manifest_path(root), manifest)
                return {"ok": True, "status": _plugin_status()}

            before = _pip_list_in_venv(pyexe, env)
            try:
                self._uninstall_ort(worker, pyexe, env)
                self._install_gpu(worker, pyexe, env, gpu_plan["package"])
                _write_plugin_runner(root)
                verify_cmd = [pyexe, _ocr_runner_path(root), "--verify", "--prefer-gpu", "--require-gpu"]
                self._run_proc(worker, verify_cmd, cwd=root, env=env, label="Testing GPU OCR...")
                after = _pip_list_in_venv(pyexe, env)
                extra = {
                    name: version
                    for name, version in _nvidia_packages(after).items()
                    if name not in _nvidia_packages(before)
                }
                versions = _package_versions_in_venv(pyexe, ["paddleocr", "onnxruntime-gpu"])
                manifest["packages"] = versions
                manifest["gpu_support"] = {
                    "installed": True,
                    "healthy": True,
                    "package": "onnxruntime-gpu",
                    "version": versions["onnxruntime-gpu"],
                    "extra_packages": extra,
                }
                manifest["verified"] = True
                _write_json_atomic(_ocr_manifest_path(root), manifest)
                worker.log("NVIDIA GPU acceleration is installed and verified.", "success")
                return {"ok": True, "status": _plugin_status()}
            except Exception as exc:
                worker.log("GPU installation failed; restoring CPU OCR...", "warning")
                rollback_error = None
                try:
                    after = _pip_list_in_venv(pyexe, env)
                    gpu_names = set(_nvidia_packages(after)) - set(_nvidia_packages(before))
                    self._uninstall_ort(worker, pyexe, env, sorted(gpu_names))
                    self._install_cpu(worker, pyexe, env)
                    _write_plugin_runner(root)
                    self._run_proc(
                        worker,
                        [pyexe, _ocr_runner_path(root), "--verify"],
                        cwd=root,
                        env=env,
                        label="Testing CPU OCR...",
                    )
                    manifest["packages"] = _package_versions_in_venv(pyexe, ["paddleocr", "onnxruntime"])
                    manifest["gpu_support"] = {
                        "installed": False,
                        "healthy": False,
                        "package": None,
                        "version": None,
                        "extra_packages": {},
                    }
                    manifest["verified"] = True
                    _write_json_atomic(_ocr_manifest_path(root), manifest)
                except Exception as restore_exc:
                    rollback_error = restore_exc
                if rollback_error:
                    raise RuntimeError(
                        f"GPU support installation failed: {exc}; CPU rollback also failed: {rollback_error}"
                    ) from exc
                raise

        if not existing_gpu:
            worker.log("GPU support is already absent.", "info")
            return {"ok": True, "status": _plugin_status()}

        try:
            self._uninstall_ort(worker, pyexe, env, current_gpu_extras.keys())
            self._install_cpu(worker, pyexe, env)
            _write_plugin_runner(root)
            self._run_proc(
                worker,
                [pyexe, _ocr_runner_path(root), "--verify"],
                cwd=root,
                env=env,
                label="Testing CPU OCR...",
            )
            cpu_versions = _package_versions_in_venv(pyexe, ["paddleocr", "onnxruntime"])
            manifest["packages"] = cpu_versions
            manifest["gpu_support"] = {
                "installed": False,
                "healthy": False,
                "package": None,
                "version": None,
                "extra_packages": {},
            }
            manifest["verified"] = True
            _write_json_atomic(_ocr_manifest_path(root), manifest)
            worker.log("GPU acceleration removed. CPU OCR remains installed.", "success")
            return {"ok": True, "status": _plugin_status()}
        except Exception as exc:
            worker.log("GPU removal failed; attempting to restore GPU support...", "warning")
            restore_error = None
            try:
                self._uninstall_ort(worker, pyexe, env)
                # Deliberately unpinned: restore the latest available compatible GPU runtime.
                gpu_package = "onnxruntime-gpu[cuda,cudnn]"
                self._install_gpu(worker, pyexe, env, gpu_package)
                _write_plugin_runner(root)
                self._run_proc(
                    worker,
                    [pyexe, _ocr_runner_path(root), "--verify", "--prefer-gpu", "--require-gpu"],
                    cwd=root,
                    env=env,
                    label="Testing GPU OCR...",
                )
                versions = _package_versions_in_venv(pyexe, ["paddleocr", "onnxruntime-gpu"])
                manifest["packages"] = versions
                manifest["gpu_support"] = {
                    "installed": True,
                    "healthy": True,
                    "package": "onnxruntime-gpu",
                    "version": versions["onnxruntime-gpu"],
                    "extra_packages": current_gpu_extras,
                }
                manifest["verified"] = True
                _write_json_atomic(_ocr_manifest_path(root), manifest)
            except Exception as restore_exc:
                restore_error = restore_exc
            if restore_error:
                raise RuntimeError(
                    f"GPU support removal failed: {exc}; GPU rollback also failed: {restore_error}"
                ) from exc
            raise


class _PluginUninstallerTask:
    def run(self, worker):
        worker.set_infinite(True, "Removing OCR...")
        root = _ocr_plugin_root()
        active = _ocr_active_root()
        artifact_present = os.path.isdir(active) or os.path.isfile(_ocr_manifest_path(active))
        if worker.is_cancelled():
            raise RuntimeError("Uninstall cancelled.")
        worker.log("Removing isolated OCR environment and model cache...", "info")
        if os.path.isdir(active):
            last_exc = None
            for attempt in range(3):
                try:
                    shutil.rmtree(active)
                    last_exc = None
                    break
                except Exception as exc:
                    last_exc = exc
                    if attempt < 2:
                        time.sleep(0.4)
            if last_exc is not None:
                raise RuntimeError(f"Could not remove the OCR plugin directory: {last_exc}")
        if os.path.isdir(root):
            for name in os.listdir(root):
                if name.startswith("staging_") or name == "active_backup":
                    target = os.path.join(root, name)
                    try:
                        shutil.rmtree(target, ignore_errors=False)
                    except Exception as exc:
                        raise RuntimeError(f"Could not remove plugin cleanup directory '{name}': {exc}")
            try:
                if not os.listdir(root):
                    os.rmdir(root)
            except Exception:
                pass
        worker.progress(1, 1, "Uninstall")
        worker.log("OCR plugin removed." if artifact_present else "OCR plugin was already absent.", "success" if artifact_present else "info")
        return {"ok": True, "removed": artifact_present}


PLUGIN_UPDATE_ORDER = (OCR_PLUGIN_ID, PDF2DOCX_PLUGIN_ID, LIBREOFFICE_PLUGIN_ID)
PLUGIN_UPDATE_NAMES = {
    OCR_PLUGIN_ID: "OCR",
    PDF2DOCX_PLUGIN_ID: "PDF to DOCX",
    LIBREOFFICE_PLUGIN_ID: "LibreOffice Runtime",
}

PLUGIN_LIBRARY_DISPLAY_NAMES = {
    "paddleocr": "PaddleOCR",
    "onnxruntime": "ONNX Runtime",
    "onnxruntime-gpu": "ONNX Runtime GPU",
    "pdf2docx": "PDF2DOCX",
    "libreoffice": "LibreOffice",
}


def _plugin_library_display_name(package_name):
    return PLUGIN_LIBRARY_DISPLAY_NAMES.get(str(package_name), str(package_name))


def _plugin_update_display_name(plugin_id):
    return PLUGIN_UPDATE_NAMES.get(str(plugin_id), str(plugin_id))


def _check_plugin_updates(plugin_id, worker=None):
    """Check installed libraries/runtime releases only; never mutate a plugin."""
    plugin_id = str(plugin_id)
    if worker is not None and worker.is_cancelled():
        raise RuntimeError("Update check cancelled.")

    if plugin_id == OCR_PLUGIN_ID:
        status = _plugin_status()
        if not status.get("installed"):
            if status.get("stale"):
                raise RuntimeError(status.get("reason") or "OCR plugin installation is incomplete.")
            return {
                "ok": True, "skipped": True, "plugin_id": plugin_id,
                "plugin": _plugin_update_display_name(plugin_id),
                "current_versions": {}, "latest_versions": {}, "updates": {},
            }
        if not status.get("healthy"):
            raise RuntimeError(status.get("reason") or "OCR plugin is not ready for an update check.")
        installed = {
            str(name): str(version)
            for name, version in (status.get("libraries") or [])
            if version
        }
        packages = ["paddleocr"]
        packages.append(
            "onnxruntime-gpu" if "onnxruntime-gpu" in installed else "onnxruntime"
        )
        latest, updates = _latest_package_updates(
            {name: installed.get(name) for name in packages if installed.get(name)},
            worker=worker,
        )
        return {
            "ok": True,
            "plugin_id": plugin_id,
            "plugin": _plugin_update_display_name(plugin_id),
            "current_versions": installed,
            "latest_versions": latest,
            "updates": updates,
        }

    if plugin_id == PDF2DOCX_PLUGIN_ID:
        status = _pdf2docx_plugin_status()
        if not status.get("installed"):
            if status.get("stale"):
                raise RuntimeError(
                    status.get("reason") or
                    "PDF2DOCX plugin installation is incomplete."
                )
            return {
                "ok": True, "skipped": True, "plugin_id": plugin_id,
                "plugin": _plugin_update_display_name(plugin_id),
                "current_versions": {}, "latest_versions": {}, "updates": {},
            }
        if not status.get("healthy"):
            raise RuntimeError(
                status.get("reason") or
                "PDF2DOCX plugin is not ready for an update check."
            )
        installed = {
            str(name): str(version)
            for name, version in (status.get("libraries") or [])
            if version
        }
        current = installed.get("pdf2docx")
        if not current:
            raise RuntimeError("The installed PDF2DOCX version could not be determined.")
        latest, updates = _latest_package_updates(
            {"pdf2docx": current}, worker=worker
        )
        return {
            "ok": True,
            "plugin_id": plugin_id,
            "plugin": _plugin_update_display_name(plugin_id),
            "current_versions": installed,
            "latest_versions": latest,
            "updates": updates,
        }

    if plugin_id == LIBREOFFICE_PLUGIN_ID:
        status = _libreoffice_plugin_status()
        if not status.get("installed"):
            if status.get("stale"):
                raise RuntimeError(
                    status.get("reason") or
                    "LibreOffice Runtime installation is incomplete."
                )
            return {
                "ok": True, "skipped": True, "plugin_id": plugin_id,
                "plugin": _plugin_update_display_name(plugin_id),
                "current_versions": {}, "latest_versions": {}, "updates": {},
            }
        if not status.get("healthy"):
            raise RuntimeError(
                status.get("reason") or
                "LibreOffice Runtime is not ready for an update check."
            )
        current = str(
            status.get("distribution_version")
            or (status.get("manifest") or {}).get("distribution_version")
            or status.get("runtime_version")
            or status.get("version")
            or ""
        ).strip()
        if not current:
            raise RuntimeError("The installed LibreOffice distribution version could not be determined.")
        latest = _discover_latest_libreoffice_version(worker)
        updates = {}
        if _version_is_newer(latest, current):
            updates["libreoffice"] = {"current": current, "latest": latest}
        return {
            "ok": True,
            "plugin_id": plugin_id,
            "plugin": _plugin_update_display_name(plugin_id),
            "current_versions": {"libreoffice": current},
            "latest_versions": {"libreoffice": latest},
            "updates": updates,
        }

    raise ValueError(f"Unknown plugin id: {plugin_id}")


class _PluginUpdateCheckTask:
    def __init__(self, plugin_id):
        self.plugin_id = str(plugin_id)

    def cancel(self):
        pass

    def run(self, worker):
        worker.set_infinite(True, "Checking for updates...")
        plugin_name = _plugin_update_display_name(self.plugin_id)
        worker.log(f"Checking for {plugin_name} updates...", "info")
        result = _check_plugin_updates(self.plugin_id, worker=worker)
        updates = result.get("updates") or {}
        if updates:
            for name, item in updates.items():
                library_name = _plugin_library_display_name(name)
                worker.log(
                    f"Update available: {library_name} {item['current']} → {item['latest']}.",
                    "success",
                )
        else:
            worker.log(f"No update available for {plugin_name}.", "success")
        return result


def _installed_mergerz_version():
    """Return the version of the installed Mergerz distribution in normal/package mode."""
    try:
        import importlib.metadata as importlib_metadata
        version = str(importlib_metadata.version("mergerz") or "").strip()
        if version:
            return version
    except Exception:
        pass
    return str(__version__)


class _MergerzUpdateCheckTask:
    """Silently check PyPI for a newer Mergerz release."""

    def cancel(self):
        pass

    def run(self, worker):
        worker.set_infinite(True, "Checking for updates...")
        worker.log("Checking Mergerz for updates...", "info")
        latest = _latest_pypi_release("mergerz", worker=worker)
        current = _installed_mergerz_version()
        if _version_is_newer(latest, current):
            worker.log(
                f"New Mergerz update available: {current} → {latest}.",
                "success",
            )
            return {
                "ok": True,
                "update_available": True,
                "current_version": current,
                "latest_version": latest,
            }

        worker.log(f"Mergerz {current} is up to date.", "success")
        return {
            "ok": True,
            "update_available": False,
            "current_version": current,
            "latest_version": latest,
        }


class _MergerzUpdateInstallTask:
    """Install one exact Mergerz release into the currently running Python environment."""

    def __init__(self, target_version):
        self.target_version = str(target_version or "").strip()
        self._proc = None

    def cancel(self):
        _terminate_process(self._proc)

    def _run_proc(self, worker, cmd, label):
        if worker.is_cancelled():
            raise RuntimeError("Mergerz update cancelled.")
        worker.set_infinite(True, str(label))
        worker.log(str(label), "info")

        env = os.environ.copy()
        env["PYTHONUNBUFFERED"] = "1"
        kwargs = {
            "cwd": os.getcwd(),
            "env": env,
            "stdout": subprocess.PIPE,
            "stderr": subprocess.STDOUT,
            "text": True,
            "bufsize": 1,
        }
        if os.name == "nt":
            kwargs["creationflags"] = (
                getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
                | getattr(subprocess, "CREATE_NO_WINDOW", 0)
            )
        else:
            kwargs["start_new_session"] = True

        self._proc = subprocess.Popen(cmd, **kwargs)
        rc = None
        try:
            for line in iter(self._proc.stdout.readline, ""):
                if line:
                    worker.log(line.rstrip("\r\n"), "info")
                if worker.is_cancelled():
                    _terminate_process(self._proc)
                    raise RuntimeError("Mergerz update cancelled.")
            rc = self._proc.wait()
        finally:
            self._proc = None

        if rc != 0:
            raise RuntimeError(
                f"Mergerz update command failed with exit code {rc}."
            )

    def run(self, worker):
        if not self.target_version:
            raise ValueError("No target Mergerz version was supplied.")

        current_version = _installed_mergerz_version()
        if not _version_is_newer(self.target_version, current_version):
            raise RuntimeError(
                f"Mergerz {self.target_version} is not newer than the installed version {current_version}."
            )

        worker.log(
            f"Current Mergerz version: {current_version}; target version: {self.target_version}.",
            "info",
        )
        worker.log(f"Python environment: {sys.executable}", "info")

        command = [
            sys.executable,
            "-m",
            "pip",
            "install",
            "--upgrade",
            "--disable-pip-version-check",
            "--no-input",
            f"mergerz=={self.target_version}",
        ]
        self._run_proc(
            worker,
            command,
            f"Installing Mergerz {self.target_version}...",
        )

        try:
            import importlib.metadata as importlib_metadata
            installed = str(importlib_metadata.version("mergerz") or "").strip()
        except Exception as exc:
            raise RuntimeError(
                f"Mergerz was installed, but the installed version could not be verified: {exc}"
            ) from exc

        if installed != self.target_version:
            raise RuntimeError(
                f"Mergerz update verification failed: expected {self.target_version}, "
                f"but the environment reports {installed or 'unknown'}."
            )

        worker.log(
            f"Mergerz {installed} was installed and verified successfully.",
            "success",
        )
        return {
            "ok": True,
            "version": installed,
            "restart_required": True,
        }


class _AllPluginsUpdateCheckTask:
    def cancel(self):
        pass

    def run(self, worker):
        worker.set_infinite(True, "Checking for plugin updates...")
        worker.log("Checking installed plugins for updates...", "info")
        results = {}
        errors = {}
        with ThreadPoolExecutor(
            max_workers=len(PLUGIN_UPDATE_ORDER), thread_name_prefix="plugin-update-check"
        ) as executor:
            futures = {
                executor.submit(_check_plugin_updates, plugin_id, worker): plugin_id
                for plugin_id in PLUGIN_UPDATE_ORDER
            }
            for future in as_completed(futures):
                plugin_id = futures[future]
                if worker.is_cancelled():
                    raise RuntimeError("Update check cancelled.")
                try:
                    result = future.result()
                    results[plugin_id] = result
                    plugin_name = str(result.get("plugin") or _plugin_update_display_name(plugin_id))
                    if result.get("skipped"):
                        worker.log(f"{plugin_name}: not installed; skipped.", "info")
                    elif result.get("updates"):
                        for name, item in (result.get("updates") or {}).items():
                            library_name = _plugin_library_display_name(name)
                            worker.log(
                                f"{plugin_name}: update available — {library_name} "
                                f"{item['current']} → {item['latest']}.",
                                "success",
                            )
                    else:
                        worker.log(f"{plugin_name}: no update available.", "info")
                except Exception as exc:
                    errors[plugin_id] = f"{type(exc).__name__}: {exc}"
                    worker.log(
                        f"{_plugin_update_display_name(plugin_id)} could not be checked: {errors[plugin_id]}",
                        "error",
                    )
        available = [
            results[plugin_id]
            for plugin_id in PLUGIN_UPDATE_ORDER
            if plugin_id in results and results[plugin_id].get("updates")
        ]
        if available:
            names = ", ".join(str(item.get("plugin") or "") for item in available)
            worker.log(f"Updates available for: {names}.", "success")
        elif errors:
            worker.log(
                "No confirmed updates were found, but one or more plugins could not be checked.",
                "warning",
            )
        else:
            worker.log("No plugin updates are available.", "success")
        return {
            "ok": True,
            "plugins": [results[plugin_id] for plugin_id in PLUGIN_UPDATE_ORDER if plugin_id in results],
            "errors": errors,
        }


class PluginsScanThread(QtCore.QThread):
    """Collect all plugin statuses off the GUI thread for the Plugins page."""
    result_signal = QtCore.Signal(dict)
    error_signal = QtCore.Signal(str)

    def __init__(self, parent=None):
        super().__init__(None)
        self._owner_hint = parent
        _track_qthread(self)

    def run(self):
        checks = (
            ("ocr", _plugin_status),
            ("pdf2docx", _pdf2docx_plugin_status),
            ("libreoffice", _libreoffice_plugin_status),
        )
        statuses = {}
        try:
            with ThreadPoolExecutor(
                max_workers=len(checks), thread_name_prefix="plugin-status"
            ) as executor:
                futures = {executor.submit(checker): key for key, checker in checks}
                for future in as_completed(futures):
                    key = futures[future]
                    statuses[key] = future.result()
            self.result_signal.emit({key: statuses.get(key, {}) for key, _ in checks})
        except Exception as exc:
            self.error_signal.emit(f"{type(exc).__name__}: {exc}")


class PluginStatusThread(QtCore.QThread):
    result_signal = QtCore.Signal(dict)
    error_signal = QtCore.Signal(str)

    def __init__(self, parent=None, checker=None):
        super().__init__(None)
        self._owner_hint = parent
        _track_qthread(self)
        self._checker = checker or _plugin_status

    def run(self):
        try:
            self.result_signal.emit(self._checker())
        except Exception as exc:
            self.error_signal.emit(f"{type(exc).__name__}: {exc}")


class OCRPluginStatusThread(QtCore.QThread):
    result_signal = QtCore.Signal(dict)
    error_signal = QtCore.Signal(str)
    phase_signal = QtCore.Signal(str)
    log_signal = QtCore.Signal(str, str)

    def __init__(self, parent=None):
        super().__init__(None)
        self._owner_hint = parent
        _track_qthread(self)

    def run(self):
        try:
            status = _plugin_status()
            if status.get("healthy"):
                self.phase_signal.emit("Fetching OCR languages and models...")
                self.log_signal.emit("Fetching OCR languages and models...", "info")
                try:
                    status = _ensure_ocr_languages(status)
                except Exception as exc:
                    status = dict(status)
                    status["language_list_ready"] = False
                    status["language_error"] = f"{type(exc).__name__}: {exc}"
                    status["languages"] = []
                    status["models"] = []
                    status["language_models"] = {}
                    status["automatic_model"] = {}
                    status["model_list_ready"] = False
            self.result_signal.emit(status)
        except Exception as exc:
            self.error_signal.emit(f"{type(exc).__name__}: {exc}")


def _show_plugin_check_dialog(parent, plugin_name="OCR", status_checker=None, log_text=None):
    plugin_name = str(plugin_name or "Plugin").strip() or "Plugin"
    dlg = ProgressDialog(parent)
    dlg.setWindowTitle(f"Checking {plugin_name} Plugin")
    dlg.start_infinite(f"Checking {plugin_name} plugin...")
    dlg.append_log(log_text or f"Checking the isolated {plugin_name} plugin environment...", "info")
    dlg.show()
    outcome = {"status": None, "error": None}

    if plugin_name.lower() == "ocr" and status_checker is None:
        thread = OCRPluginStatusThread(dlg)
        thread.phase_signal.connect(dlg.start_infinite)
        thread.log_signal.connect(dlg.append_log)
    else:
        thread = PluginStatusThread(dlg, checker=status_checker)

    thread.result_signal.connect(lambda status: (outcome.__setitem__("status", status), dlg.accept()))
    thread.error_signal.connect(lambda msg: (outcome.__setitem__("error", msg), dlg.accept()))
    thread.start()
    dlg.exec()
    if thread.isRunning():
        _stop_qthread(thread, timeout_ms=3000, force_wait_ms=1500)
    return outcome["status"] or {
        "healthy": False,
        "reason": outcome["error"] or f"{plugin_name} plugin status could not be determined.",
    }


def _show_missing_plugin_dialog(parent, plugin_name, status):
    plugin_name = str(plugin_name or "Plugin").strip() or "Plugin"
    msg = QtWidgets.QMessageBox(parent)
    msg.setWindowTitle(f"{plugin_name} Plugin Required")
    msg.setText(f"The {plugin_name} plugin is not fully installed or verified.")
    reason = str((status or {}).get("reason") or "").strip()
    if reason and reason.lower().rstrip(".") != "not installed":
        msg.setInformativeText(reason)
    open_btn = msg.addButton("Open Plugins", QtWidgets.QMessageBox.ButtonRole.AcceptRole)
    msg.addButton("Cancel", QtWidgets.QMessageBox.ButtonRole.RejectRole)
    msg.exec()
    if msg.clickedButton() is open_btn:
        controller = parent
        while controller is not None and not hasattr(controller, "open_plugins"):
            try:
                controller = controller.parentWidget()
            except Exception:
                controller = None
        if controller is not None:
            controller.open_plugins(force_front=True)


def _read_ocr_response_line(proc, timeout_seconds=OCR_INFERENCE_TIMEOUT_SECONDS,
                             cancel_check=None, heartbeat_seconds=OCR_INFERENCE_HEARTBEAT_SECONDS,
                             heartbeat_callback=None):
    """Read one runner response without allowing native inference to block forever."""
    if proc is None or proc.stdout is None:
        raise RuntimeError("OCR plugin runner output is unavailable.")

    line_holder = {}
    read_done = threading.Event()

    def _read_response():
        try:
            line_holder["line"] = proc.stdout.readline()
        except Exception as exc:
            line_holder["error"] = exc
        finally:
            read_done.set()

    threading.Thread(target=_read_response, daemon=True).start()
    started = time.monotonic()
    next_heartbeat = max(1.0, float(heartbeat_seconds))
    while not read_done.wait(0.10):
        if cancel_check is not None and cancel_check():
            _terminate_process(proc)
            raise RuntimeError("OCR cancelled.")
        elapsed = time.monotonic() - started
        if heartbeat_callback is not None and elapsed >= next_heartbeat:
            try:
                heartbeat_callback(elapsed)
            except Exception:
                pass
            next_heartbeat += max(1.0, float(heartbeat_seconds))
        if timeout_seconds is not None and elapsed >= float(timeout_seconds):
            _terminate_process(proc)
            raise TimeoutError(
                f"OCR inference timed out after {float(timeout_seconds):.0f}s; "
                "the selected model did not return a result."
            )

    if cancel_check is not None and cancel_check():
        raise RuntimeError("OCR cancelled.")
    if "error" in line_holder:
        exc = line_holder["error"]
        raise RuntimeError(
            f"OCR plugin runner communication failed: {type(exc).__name__}: {exc}")

    line = line_holder.get("line")
    if not line:
        if cancel_check is not None and cancel_check():
            raise RuntimeError("OCR cancelled.")
        raise RuntimeError(
            f"OCR plugin runner exited unexpectedly (exit code {proc.poll()}).")
    return json.loads(line)


def _ocr_plugin_cpu_process_worker(page_entries, language, ocr_version, model_config, dpi, detection_size_percent, plugin_root,
                                   result_queue, worker_index):
    """Process one assigned CPU page range in a spawn-safe worker process.

    The worker process never imports PaddleOCR itself. Instead it launches one
    long-lived runner.py from the isolated OCR plugin environment, so every CPU
    worker gets its own OCR engine while the main Mergerz environment remains
    free of Paddle/PaddleX/ONNX native libraries.
    """
    runner = None
    docs = {}
    job_dir = None
    total = len(page_entries)

    def send(kind, *payload):
        try:
            result_queue.put((kind, worker_index, *payload))
        except Exception:
            pass

    try:
        if os.name == "nt":
            runner_kwargs = {
                "stdin": subprocess.PIPE,
                "stdout": subprocess.PIPE,
                "stderr": subprocess.DEVNULL,
                "text": True,
                "bufsize": 1,
                "cwd": plugin_root,
                "env": _plugin_env(plugin_root),
                "creationflags": (
                    getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
                    | getattr(subprocess, "CREATE_NO_WINDOW", 0)
                ),
            }
        else:
            runner_kwargs = {
                "stdin": subprocess.PIPE,
                "stdout": subprocess.PIPE,
                "stderr": subprocess.DEVNULL,
                "text": True,
                "bufsize": 1,
                "cwd": plugin_root,
                "env": _plugin_env(plugin_root),
                "start_new_session": True,
            }

        env = dict(runner_kwargs["env"] or {})
        env.setdefault("OMP_NUM_THREADS", "1")
        env.setdefault("MKL_NUM_THREADS", "1")
        env.setdefault("OPENBLAS_NUM_THREADS", "1")
        env.setdefault("NUMEXPR_NUM_THREADS", "1")
        env["PYTHONUNBUFFERED"] = "1"
        runner_kwargs["env"] = env

        runner = subprocess.Popen(
            [_ocr_venv_python(plugin_root), _ocr_runner_path(plugin_root), "--serve"],
            **runner_kwargs,
        )
        send("worker_log", f"CPU worker {worker_index + 1}: OCR runner started.", "info")

        job_dir = os.path.abspath(os.path.join(
            TEMP_FOLDER,
            "ocr_plugin",
            f"cpu_worker_{os.getpid()}_{uuid.uuid4().hex}",
        ))
        os.makedirs(job_dir, exist_ok=True)

        for pos, (uid, pdf_path, idx, entry) in enumerate(page_entries, 1):
            image_path = os.path.join(job_dir, f"{uid}.png")
            label = f"{os.path.basename(pdf_path)} page #{int(idx) + 1}"
            try:
                doc = docs.get(pdf_path)
                if doc is None:
                    doc = fitz.open(pdf_path)
                    docs[pdf_path] = doc

                img, meta = _render_page_for_ocr(
                    pdf_path,
                    int(idx),
                    entry,
                    doc=doc,
                    ocr_dpi=float(dpi),
                )
                img.save(image_path, format="PNG")

                if runner.stdin is None or runner.stdout is None:
                    raise RuntimeError("OCR plugin runner pipes are unavailable.")
                runner.stdin.write(json.dumps({
                    "id": str(uid),
                    # The runner's cwd is the isolated plugin directory, so
                    # image_path must always be absolute across this process boundary.
                    "image_path": os.path.abspath(image_path),
                    "language": str(language or "auto"),
                    "model": ocr_version or "auto",
                    "model_config": dict(model_config or {}),
                    "detection_limit_px": _ocr_detection_limit_px_for_image(img, detection_size_percent),
                }, ensure_ascii=False) + "\n")
                runner.stdin.flush()
                response = _read_ocr_response_line(
                    runner,
                    heartbeat_callback=lambda elapsed: send(
                        "worker_log",
                        f"CPU worker {worker_index + 1}: OCR inference still running ({elapsed:.0f}s)...",
                        "info",
                    ),
                )
                if not response.get("ok"):
                    raise RuntimeError(
                        response.get("error") or "OCR plugin returned an unknown error.")

                blocks = response.get("blocks") or []
                mapped = _map_ocr_blocks_to_pdf(blocks, meta)
                send("page_ok", uid, int(idx), label, mapped, len(blocks))
            except Exception as exc:
                send("page_error", uid, int(idx), label, f"{type(exc).__name__}: {exc}")
                try:
                    if runner is None or runner.poll() is not None:
                        _terminate_process(runner)
                        runner = None
                        if pos < total:
                            runner = subprocess.Popen(
                                [_ocr_venv_python(plugin_root), _ocr_runner_path(plugin_root), "--serve"],
                                **runner_kwargs,
                            )
                            send("worker_log", f"CPU worker {worker_index + 1}: OCR runner restarted after the failed page.", "info")
                except Exception as restart_exc:
                    send("worker_error", f"OCR runner restart failed: {type(restart_exc).__name__}: {restart_exc}")
                    break
            finally:
                try:
                    if os.path.exists(image_path):
                        os.remove(image_path)
                except Exception:
                    pass

    except Exception as exc:
        send("worker_error", f"{type(exc).__name__}: {exc}")
    finally:
        for doc in docs.values():
            try:
                doc.close()
            except Exception:
                pass
        _terminate_process(runner)
        runner = None
        shutil.rmtree(job_dir or "", ignore_errors=True)
        send("worker_done")


class OCRPluginWorker(QtCore.QThread):
    log_signal = QtCore.Signal(str, str)
    progress_signal = QtCore.Signal(int, int, str)
    result_signal = QtCore.Signal(dict)
    error_signal = QtCore.Signal(str)

    def __init__(self, page_entries, language, ocr_version, model_config, dpi, detection_size_percent, use_gpu, plugin_status,
                 num_workers=1, parent=None):
        super().__init__(None)
        self._owner_hint = parent
        _track_qthread(self)
        self.page_entries = list(page_entries)
        self.language = language
        self.ocr_version = str(ocr_version or "")
        self.model_config = dict(model_config or {})
        self.dpi = float(dpi)
        self.detection_size_percent = int(detection_size_percent or DEFAULT_OCR_DETECTION_SIZE_PERCENT)
        if self.detection_size_percent not in OCR_DETECTION_SIZE_PERCENT_OPTIONS:
            raise ValueError("OCR detector-size percentage is invalid.")
        self.use_gpu = bool(use_gpu)
        self.plugin_status = dict(plugin_status or {})
        self.num_workers = max(1, int(num_workers or 1))
        self._cancel = threading.Event()
        self._proc = None
        self._cpu_processes = []
        self._cpu_queue = None
        self._job_dir = None
        self._actual_device = "CPU"

    @staticmethod
    def _build_page_chunks(entries, workers):
        """Match the old CPU OCR partitioning rule: non-empty contiguous chunks."""
        total = len(entries)
        workers = max(1, min(int(workers), total)) if total else 1
        if total <= 1 or workers <= 1:
            return [list(entries)] if total else []
        base, remainder = divmod(total, workers)
        chunks = []
        cursor = 0
        for worker_index in range(workers):
            size = base + (remainder if worker_index == workers - 1 else 0)
            chunks.append(list(entries[cursor:cursor + size]))
            cursor += size
        return [chunk for chunk in chunks if chunk]

    def request_cancel(self):
        self._cancel.set()
        _terminate_process(self._proc)
        for proc in list(self._cpu_processes):
            try:
                if proc.is_alive():
                    proc.terminate()
            except Exception:
                pass

    def _send_request(self, image_path, language, request_id):
        if self._proc is None or self._proc.stdin is None or self._proc.stdout is None:
            raise RuntimeError("OCR plugin runner is not running.")
        if self._cancel.is_set():
            raise RuntimeError("OCR cancelled.")

        self._proc.stdin.write(json.dumps({
            "id": request_id,
            "image_path": os.path.abspath(image_path),
            "language": language,
            "model": self.ocr_version or "auto",
            "model_config": self.model_config,
            "detection_limit_px": _ocr_detection_limit_px_for_path(image_path, self.detection_size_percent),
        }, ensure_ascii=False) + "\n")
        self._proc.stdin.flush()

        proc = self._proc
        data = _read_ocr_response_line(
            proc,
            cancel_check=self._cancel.is_set,
            heartbeat_callback=lambda elapsed: self.log_signal.emit(
                f"OCR inference still running ({elapsed:.0f}s)...", "info"
            ),
        )
        if not data.get("ok"):
            raise RuntimeError(data.get("error") or "OCR plugin returned an unknown error.")
        self._actual_device = str(data.get("device") or self._actual_device)
        return data.get("blocks") or []

    def _start_runner(self, root, prefer_gpu=False):
        kwargs = {
            "stdin": subprocess.PIPE,
            "stdout": subprocess.PIPE,
            "stderr": subprocess.PIPE,
            "text": True,
            "bufsize": 1,
            "cwd": root,
            "env": _plugin_env(root),
        }
        if os.name == "nt":
            kwargs["creationflags"] = (
                getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
                | getattr(subprocess, "CREATE_NO_WINDOW", 0)
            )
        else:
            kwargs["start_new_session"] = True
        cmd = [
            _ocr_venv_python(root),
            _ocr_runner_path(root),
            "--serve",
        ]
        if prefer_gpu:
            cmd.append("--prefer-gpu")
        self._proc = subprocess.Popen(cmd, **kwargs)

        def read_stderr(proc):
            try:
                for line in iter(proc.stderr.readline, ""):
                    if line:
                        self.log_signal.emit(line.rstrip("\r\n"), "info")
            except Exception:
                pass

        threading.Thread(
            target=read_stderr,
            args=(self._proc,),
            daemon=True,
        ).start()

    def _run_cpu_multiprocess(self, root, results, failed):
        total = len(self.page_entries)
        chunks = self._build_page_chunks(self.page_entries, self.num_workers)
        worker_count = len(chunks)
        if worker_count <= 1:
            return self._run_cpu_single(root, results, failed), 1

        self.log_signal.emit(
            f"CPU OCR: requested {self.num_workers}, effective {worker_count} worker(s).",
            "info",
        )
        self.log_signal.emit(
            "Strategy: MP; each worker renders complete pages, uses its own isolated OCR runner, and releases each page image before continuing.",
            "info",
        )

        ctx = multiprocessing.get_context("spawn")
        result_queue = ctx.Queue()
        self._cpu_queue = result_queue
        processes = []
        for worker_index, chunk in enumerate(chunks):
            proc = ctx.Process(
                target=_ocr_plugin_cpu_process_worker,
                args=(chunk, self.language, self.ocr_version, self.model_config, self.dpi, self.detection_size_percent, root, result_queue, worker_index),
            )
            processes.append(proc)

        self._cpu_processes = processes
        for proc in processes:
            proc.start()

        done_pages = 0
        finished_workers = 0
        worker_errors = []
        try:
            while finished_workers < worker_count:
                if self._cancel.is_set():
                    raise RuntimeError("OCR cancelled.")
                try:
                    message = result_queue.get(timeout=0.15)
                except queue.Empty:
                    # If all processes are gone without enough completion messages,
                    # surface a real failure instead of hanging indefinitely.
                    if all(not p.is_alive() for p in processes) and finished_workers < worker_count:
                        break
                    continue

                kind = message[0]
                worker_index = message[1]
                payload = message[2:]
                if kind == "worker_log":
                    self.log_signal.emit(str(payload[0]), str(payload[1]))
                elif kind == "page_ok":
                    uid, idx, label, blocks, block_count = payload
                    results[uid] = blocks
                    done_pages += 1
                    self.log_signal.emit(
                        f"[{done_pages}/{total}] {label}: {int(block_count)} region(s)",
                        "success",
                    )
                    self.progress_signal.emit(done_pages, total, "OCR")
                elif kind == "page_error":
                    uid, idx, label, err = payload
                    failed[uid] = str(err)
                    done_pages += 1
                    self.log_signal.emit(
                        f"[{done_pages}/{total}] {label} failed: {err}",
                        "error",
                    )
                    self.progress_signal.emit(done_pages, total, "OCR")
                elif kind == "worker_error":
                    err = str(payload[0]) if payload else "Unknown CPU OCR worker failure."
                    worker_errors.append(f"Worker {worker_index + 1}: {err}")
                    self.log_signal.emit(worker_errors[-1], "error")
                elif kind == "worker_done":
                    finished_workers += 1
        finally:
            if self._cancel.is_set():
                for proc in processes:
                    try:
                        if proc.is_alive():
                            proc.terminate()
                    except Exception:
                        pass
            for proc in processes:
                try:
                    proc.join(timeout=2.0)
                except Exception:
                    pass
                try:
                    if proc.is_alive():
                        proc.kill()
                        proc.join(timeout=1.0)
                except Exception:
                    pass
            self._cpu_processes = []
            try:
                result_queue.close()
                result_queue.join_thread()
            except Exception:
                pass
            self._cpu_queue = None

        if self._cancel.is_set():
            raise RuntimeError("OCR cancelled.")
        if done_pages != total:
            details = "; ".join(worker_errors) if worker_errors else "One or more CPU OCR workers exited unexpectedly."
            raise RuntimeError(
                f"CPU OCR workers processed {done_pages}/{total} page(s). {details}")
        if worker_errors:
            raise RuntimeError("; ".join(worker_errors))
        return None, worker_count

    def _run_cpu_single(self, root, results, failed):
        total = len(self.page_entries)
        self.log_signal.emit("Strategy: SP (1 CPU OCR worker).", "info")
        self.log_signal.emit("CPU workers: effective 1 (single complete page pipeline at a time).", "info")
        docs = {}
        try:
            self._start_runner(root, prefer_gpu=False)
            for pos, (uid, pdf_path, idx, entry) in enumerate(self.page_entries, 1):
                if self._cancel.is_set():
                    raise RuntimeError("OCR cancelled.")
                label = f"{os.path.basename(pdf_path)} page #{int(idx) + 1}"
                image_path = os.path.abspath(os.path.join(
                    TEMP_FOLDER,
                    "ocr_plugin",
                    f"single_{uuid.uuid4().hex}_{uid}.png",
                ))
                os.makedirs(os.path.dirname(image_path), exist_ok=True)
                try:
                    doc = docs.get(pdf_path)
                    if doc is None:
                        doc = fitz.open(pdf_path)
                        docs[pdf_path] = doc
                    img, meta = _render_page_for_ocr(
                        pdf_path, int(idx), entry, doc=doc, ocr_dpi=self.dpi)
                    img.save(image_path, format="PNG")
                    blocks = self._send_request(image_path, self.language, uid)
                    results[uid] = _map_ocr_blocks_to_pdf(blocks, meta)
                    self.log_signal.emit(
                        f"[{pos}/{total}] {label}: {len(blocks)} region(s)", "success")
                except Exception as exc:
                    # Cancellation is control flow, not a page failure. Propagate it
                    # immediately so progress never reaches 100% and the normal OCR
                    # completion path cannot run after Cancel.
                    if self._cancel.is_set():
                        raise RuntimeError("OCR cancelled.") from None
                    failed[uid] = f"{type(exc).__name__}: {exc}"
                    self.log_signal.emit(f"[{pos}/{total}] {label} failed: {exc}", "error")
                    if self._proc is None or self._proc.poll() is not None:
                        _terminate_process(self._proc)
                        self._proc = None
                        if pos < total and not self._cancel.is_set():
                            self.log_signal.emit("OCR runner restarted after the failed page.", "info")
                            self._start_runner(root, prefer_gpu=False)
                finally:
                    try:
                        if os.path.exists(image_path):
                            os.remove(image_path)
                    except Exception:
                        pass
                self.progress_signal.emit(pos, total, "OCR")
        finally:
            for doc in docs.values():
                try:
                    doc.close()
                except Exception:
                    pass
            _terminate_process(self._proc)
            self._proc = None

    def run(self):
        results, failed = {}, {}
        self._start_time = time.time()
        start_time = self._start_time
        root = self.plugin_status.get("root") or _ocr_active_root()
        gpu_support = self.plugin_status.get("gpu_support") or {}
        if not self.plugin_status.get("healthy"):
            self.error_signal.emit("The OCR plugin is not healthy.")
            return
        if self.use_gpu and not gpu_support.get("installed"):
            self.error_signal.emit(
                "GPU support is not installed. OCR can only run on CPU until GPU support is installed."
            )
            return

        total = len(self.page_entries)
        if total == 0:
            self.result_signal.emit({
                "pages": {}, "failed": {}, "backend": "onnxruntime",
                "engine": "ONNX Runtime", "device": "CPU",
                "workers": 1, "time": format_time(0),
                "dpi": self.dpi, "detection_size_percent": self.detection_size_percent,
                "language": self.language,
                "ocr_version": self.ocr_version,
                "detection_model": self.model_config.get("detection_model", ""),
                "recognition_model": self.model_config.get("recognition_model", ""),
            })
            return

        self._job_dir = os.path.abspath(os.path.join(TEMP_FOLDER, "ocr_plugin", "jobs"))
        os.makedirs(self._job_dir, exist_ok=True)
        try:
            self.log_signal.emit("OCR inference engine: ONNX Runtime", "success")
            self.log_signal.emit(
                "GPU preference: enabled" if self.use_gpu else "GPU preference: disabled",
                "info",
            )
            self.log_signal.emit(f"Plugin Python: {_ocr_venv_python(root)}", "info")
            self.log_signal.emit(f"Language: {self.language}", "info")
            self.log_signal.emit(f"OCR version: {self.ocr_version}", "info")
            self.log_signal.emit(f"Detection model: {self.model_config.get('detection_model', '')}", "info")
            self.log_signal.emit(f"Recognition model: {self.model_config.get('recognition_model', '')}", "info")
            self.log_signal.emit(
                f"Render DPI: {int(self.dpi)}; detector max side: {self.detection_size_percent}% of each rendered page's longest side.",
                "info",
            )

            actual_gpu = False
            effective_workers = 1
            if self.use_gpu:
                # GPU OCR intentionally remains single-process. This mirrors the
                # previous stable GPU strategy and avoids multiple CUDA runtimes.
                self.log_signal.emit("Strategy: GPU single long-lived worker.", "info")
                self._start_runner(root, prefer_gpu=True)
                self._actual_device = "GPU"
                docs = {}
                try:
                    for pos, (uid, pdf_path, idx, entry) in enumerate(self.page_entries, 1):
                        if self._cancel.is_set():
                            raise RuntimeError("OCR cancelled.")
                        label = f"{os.path.basename(pdf_path)} page #{int(idx) + 1}"
                        image_path = os.path.join(self._job_dir, f"gpu_{uid}.png")
                        try:
                            doc = docs.get(pdf_path)
                            if doc is None:
                                doc = fitz.open(pdf_path)
                                docs[pdf_path] = doc
                            img, meta = _render_page_for_ocr(
                                pdf_path, int(idx), entry, doc=doc, ocr_dpi=self.dpi)
                            img.save(image_path, format="PNG")
                            blocks = self._send_request(image_path, self.language, uid)
                            results[uid] = _map_ocr_blocks_to_pdf(blocks, meta)
                            self.log_signal.emit(
                                f"[{pos}/{total}] {label}: {len(blocks)} region(s)", "success")
                        except Exception as exc:
                            # Cancellation aborts the whole OCR job rather than being
                            # recorded as an ordinary page failure.
                            if self._cancel.is_set():
                                raise RuntimeError("OCR cancelled.") from None
                            failed[uid] = f"{type(exc).__name__}: {exc}"
                            self.log_signal.emit(f"[{pos}/{total}] {label} failed: {exc}", "error")
                            if self._proc is None or self._proc.poll() is not None:
                                _terminate_process(self._proc)
                                self._proc = None
                                if pos < total and not self._cancel.is_set():
                                    self.log_signal.emit("OCR runner restarted after the failed page.", "info")
                                    self._start_runner(root, prefer_gpu=True)
                        finally:
                            try:
                                if os.path.exists(image_path):
                                    os.remove(image_path)
                            except Exception:
                                pass
                        self.progress_signal.emit(pos, total, "OCR")
                        actual_gpu = self._actual_device.upper() == "GPU"
                finally:
                    for doc in docs.values():
                        try:
                            doc.close()
                        except Exception:
                            pass
                    _terminate_process(self._proc)
                    self._proc = None
                effective_workers = 1
            else:
                self.log_signal.emit(
                    "GPU preference: disabled; CPU OCR will use the selected worker count.",
                    "info",
                )
                _unused, effective_workers = self._run_cpu_multiprocess(root, results, failed)
                actual_gpu = False

            elapsed = format_time(time.time() - start_time)
            self.log_signal.emit(
                f"OCR completed: {len(results)} page(s); failed: {len(failed)}; time taken: {elapsed}",
                "success" if not failed else "warning",
            )
            self.result_signal.emit({
                "pages": results,
                "failed": failed,
                "backend": "onnxruntime",
                "engine": "ONNX Runtime",
                "device": "GPU" if actual_gpu else "CPU",
                "workers": effective_workers,
                "time": elapsed,
                "dpi": self.dpi,
                "detection_size_percent": self.detection_size_percent,
                "language": self.language,
                "ocr_version": self.ocr_version,
                "detection_model": self.model_config.get("detection_model", ""),
                "recognition_model": self.model_config.get("recognition_model", ""),
            })
        except Exception as exc:
            self.error_signal.emit(
                "OCR cancelled by user." if self._cancel.is_set()
                else f"{type(exc).__name__}: {exc}"
            )
        finally:
            _terminate_process(self._proc)
            self._proc = None
            for proc in list(self._cpu_processes):
                try:
                    if proc.is_alive():
                        proc.terminate()
                except Exception:
                    pass
            for proc in list(self._cpu_processes):
                try:
                    proc.join(timeout=1.0)
                except Exception:
                    pass
            self._cpu_processes = []


