# OCR CONFIG DIALOG
# ============================================================


def _effective_cropbox(page, entry):
    """Set the same crop used by the editor and return its source-space rect."""
    try:
        crop_rect = fitz.Rect(page.cropbox)
    except Exception:
        crop_rect = fitz.Rect(page.mediabox)

    crop = entry.get('crop')
    if crop:
        try:
            under = fitz.Rect(*crop) & page.mediabox
            if not under.is_empty and under.width >= 1 and under.height >= 1:
                page.set_cropbox(under)
                crop_rect = fitz.Rect(under)
        except Exception:
            pass
    return crop_rect


def _render_page_for_ocr(pdf_path, page_idx, entry, doc=None, ocr_dpi=OCR_DPI):
    """Render the exact edited page view without OCR-only runtime dependencies."""
    owned_doc = False
    if doc is None:
        doc = fitz.open(pdf_path)
        owned_doc = True
    page = None
    try:
        page = doc.load_page(page_idx)
        orig_rot = int(page.rotation) % 360
        original_crop = fitz.Rect(page.cropbox)
        effective_crop = _effective_cropbox(page, entry)
        rot = int(entry.get('rotation', 0)) % 360
        total_rot = (orig_rot + rot) % 360
        page.set_rotation(total_rot)
        dpi = max(36.0, float(ocr_dpi))
        scale = dpi / 72.0
        pix = page.get_pixmap(matrix=fitz.Matrix(scale, scale), alpha=False)
        mode = "RGBA" if pix.n == 4 else "RGB"
        img = Image.frombytes(mode, (pix.width, pix.height), pix.samples).convert("RGB")
        flip_h = bool(entry.get('flip_h', False))
        flip_v = bool(entry.get('flip_v', False))
        if flip_h:
            img = ImageOps.mirror(img)
        if flip_v:
            img = ImageOps.flip(img)
        visible_w = float(page.rect.width)
        visible_h = float(page.rect.height)
        return img, {
            'effective_crop': effective_crop,
            'total_rot': total_rot,
            'visible_w': visible_w,
            'visible_h': visible_h,
            'scale_x': pix.width / visible_w if visible_w > 0 else scale,
            'scale_y': pix.height / visible_h if visible_h > 0 else scale,
            'display_flip_h': flip_h,
            'display_flip_v': flip_v,
            'derot': page.derotation_matrix,
        }
    finally:
        try:
            if page is not None:
                page.set_rotation(orig_rot)
                page.set_cropbox(original_crop)
        except Exception:
            pass
        if owned_doc:
            doc.close()

def _ocr_detection_limit_px_for_image(image, percentage):
    """Convert the UI detector-size percentage into a concrete per-page pixel limit.

    The percentage is applied to the longest side of the exact rendered image sent to OCR.
    That matches PaddleOCR's max-side semantics and remains correct for portrait, landscape,
    rotated, cropped, and flipped pages.
    """
    try:
        pct = float(percentage)
    except Exception as exc:
        raise ValueError("OCR detector-size percentage is invalid.") from exc
    if pct <= 0.0 or pct > 100.0:
        raise ValueError("OCR detector-size percentage must be between 1% and 100%.")
    try:
        width, height = image.size
        longest_side = max(int(width), int(height))
    except Exception as exc:
        raise ValueError("Could not determine the rendered OCR image size.") from exc
    if longest_side <= 0:
        raise ValueError("The rendered OCR image has an invalid size.")
    limit = int(round(longest_side * pct / 100.0))
    return max(32, min(longest_side, limit))

def _ocr_detection_limit_px_for_path(image_path, percentage):
    """Calculate the detector limit from an on-disk rendered OCR image."""
    with Image.open(image_path) as image:
        return _ocr_detection_limit_px_for_image(image, percentage)

def _map_ocr_blocks_to_pdf(blocks, meta):
    """Map OCR boxes from the FINAL edited display back to source PDF space."""
    derot = meta['derot']
    visible_w = float(meta.get('visible_w', 0.0))
    visible_h = float(meta.get('visible_h', 0.0))
    scale_x = float(meta.get('scale_x', _OCR_SCALE))
    scale_y = float(meta.get('scale_y', _OCR_SCALE))
    flip_h = bool(meta.get('display_flip_h', False))
    flip_v = bool(meta.get('display_flip_v', False))

    out_blocks = []
    for blk in blocks:
        px0, py0, px1, py1 = blk['px']

        # Undo the exact raster-space flip before using PyMuPDF's derotation
        # matrix. OCR saw the fully flipped image, so its boxes must be
        # reflected back into the unflipped rotated/cropped page first.
        if flip_h:
            px0, px1 = visible_w * scale_x - px1, visible_w * scale_x - px0
        if flip_v:
            py0, py1 = visible_h * scale_y - py1, visible_h * scale_y - py0

        vx0, vy0 = px0 / scale_x, py0 / scale_y
        vx1, vy1 = px1 / scale_x, py1 / scale_y
        # PyMuPDF's derotation_matrix maps the rotated display coordinates
        # back into crop-relative, unrotated page coordinates. The effective
        # CropBox origin is added immediately below to obtain source-PDF
        # coordinates.
        r = fitz.Rect(vx0, vy0, vx1, vy1) * derot

        # PyMuPDF's derotation_matrix maps the displayed, cropped page
        # coordinates back into the *crop-relative* unrotated space.  The
        # OCR boxes therefore still need the effective CropBox origin to
        # land in the source page's PDF coordinate system.  This offset is
        # exactly what is missing when OCR is performed after an unsaved crop.
        crop = meta.get('effective_crop')
        if crop is not None:
            try:
                r.x0 += float(crop.x0)
                r.x1 += float(crop.x0)
                r.y0 += float(crop.y0)
                r.y1 += float(crop.y0)
            except Exception:
                pass

        bx0, by0, bx1, by1 = r.x0, r.y0, r.x1, r.y1

        out_blocks.append({
            'rect': (min(bx0, bx1), min(by0, by1),
                     max(bx0, bx1), max(by0, by1)),
            'text': blk['text'],
            'conf': blk['conf'],
        })
    return out_blocks


def _ocr_blocks_source_to_page_space(page, blocks):
    """Convert canonical source-PDF OCR boxes to PyMuPDF page coordinates.

    OCR boxes are stored by the application in stable source/user-space coordinates
    so they survive crop edits and reloads. PyMuPDF's text insertion/extraction
    coordinates, however, become CropBox-relative when a PDF with a non-default
    CropBox is reopened. Therefore insertion into a page must subtract the page's
    current CropBox origin exactly once.
    """
    if not blocks:
        return []
    try:
        crop = fitz.Rect(page.cropbox)
        dx = float(crop.x0)
        dy = float(crop.y0)
    except Exception:
        dx = dy = 0.0

    out = []
    for blk in blocks:
        try:
            x0, y0, x1, y1 = map(float, blk.get('rect', ()))
        except Exception:
            continue
        b = dict(blk)
        b['rect'] = (x0 - dx, y0 - dy, x1 - dx, y1 - dy)
        out.append(b)
    return out


def _existing_text_rects(page):
    """Return real selectable text block rectangles without deleting anything."""
    rects = []
    try:
        for block in page.get_text('blocks'):
            if len(block) >= 5 and str(block[4]).strip():
                r = fitz.Rect(block[:4])
                if not r.is_empty and r.width > 0.5 and r.height > 0.5:
                    rects.append(r)
    except Exception:
        pass
    return rects


def _filter_duplicate_ocr_blocks(page, blocks):
    """Keep OCR on scanned/mixed pages while avoiding duplicate native text.

    ``blocks`` are canonical source-PDF coordinates. Existing PyMuPDF text
    rectangles are in the current page/CropBox coordinate space, so candidate
    OCR rectangles are converted before comparison. The original source-space
    blocks are returned unchanged for later insertion.
    """
    existing = _existing_text_rects(page)
    if not existing:
        return list(blocks), 0

    page_blocks = _ocr_blocks_source_to_page_space(page, blocks)
    kept = []
    skipped = 0
    for src_blk, page_blk in zip(blocks, page_blocks):
        try:
            br = fitz.Rect(page_blk['rect'])
        except Exception:
            kept.append(src_blk)
            continue
        barea = max(1e-6, br.get_area())
        duplicate = False
        for er in existing:
            inter = br & er
            if inter.is_empty:
                continue
            ia = inter.get_area()
            if ia / barea >= 0.45:
                duplicate = True
                break
            union = barea + max(1e-6, er.get_area()) - ia
            if ia / union >= 0.20:
                duplicate = True
                break
        if duplicate:
            skipped += 1
        else:
            kept.append(src_blk)
    return kept, skipped


def _ocr_font_paths():
    """Return candidate Unicode fonts already installed on the user's system."""
    import glob
    candidates = [
        # App-local optional fonts.
        os.path.join(FONTS_FOLDER, 'NotoSansBengali-Regular.ttf'),
        os.path.join(FONTS_FOLDER, 'NotoSansArabic-Regular.ttf'),
        os.path.join(FONTS_FOLDER, 'NotoSansDevanagari-Regular.ttf'),
        os.path.join(FONTS_FOLDER, 'NotoSans-Regular.ttf'),
        os.path.join(FONTS_FOLDER, 'DejaVuSans.ttf'),
        os.path.join(FONTS_FOLDER, 'FreeSans.ttf'),
        # Common Linux locations.
        '/usr/share/fonts/truetype/noto/NotoSansBengali-Regular.ttf',
        '/usr/share/fonts/opentype/noto/NotoSansBengali-Regular.ttf',
        '/usr/share/fonts/truetype/noto/NotoSansArabic-Regular.ttf',
        '/usr/share/fonts/opentype/noto/NotoSansArabic-Regular.ttf',
        '/usr/share/fonts/truetype/noto/NotoSansDevanagari-Regular.ttf',
        '/usr/share/fonts/opentype/noto/NotoSansDevanagari-Regular.ttf',
        '/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf',
        '/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc',
        '/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.otf',
        '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
        '/usr/share/fonts/truetype/freefont/FreeSans.ttf',
        # Common Windows location.
        os.path.join(os.environ.get('WINDIR', 'C:/Windows'), 'Fonts', 'arial.ttf'),
    ]
    for root in ('/usr/share/fonts', '/usr/local/share/fonts'):
        candidates.extend(glob.glob(os.path.join(root, '**', 'NotoSans*.ttf'), recursive=True))
        candidates.extend(glob.glob(os.path.join(root, '**', 'NotoSerif*.ttf'), recursive=True))
        candidates.extend(glob.glob(os.path.join(root, '**', 'DejaVuSans*.ttf'), recursive=True))
    out = []
    seen = set()
    for path in candidates:
        if path in seen or not os.path.isfile(path):
            continue
        seen.add(path)
        out.append(path)
    return out


_OCR_FONT_PATHS = None
_OCR_FONT_OBJECTS = {}


def _ocr_font_for_text(text):
    """Pick a font whose cmap contains every character in text, when possible."""
    global _OCR_FONT_PATHS
    if _OCR_FONT_PATHS is None:
        _OCR_FONT_PATHS = _ocr_font_paths()
    chars = [ch for ch in str(text) if not ch.isspace()]
    if not chars:
        return None, None
    for path in _OCR_FONT_PATHS:
        try:
            font = _OCR_FONT_OBJECTS.get(path)
            if font is None:
                font = fitz.Font(fontfile=path)
                _OCR_FONT_OBJECTS[path] = font
            if all(font.has_glyph(ord(ch)) for ch in set(chars)):
                return path, font
        except Exception:
            continue
    return None, None


def _ocr_font_runs(text):
    """Split mixed-script OCR text into contiguous runs covered by one font."""
    text = str(text)
    runs = []
    if not text:
        return runs

    current = ''
    current_path = None
    current_font = None
    for ch in text:
        # Keep whitespace with the current run when its font can represent it.
        probe = current + ch
        path, font = _ocr_font_for_text(probe)
        if path is None:
            path, font = _ocr_font_for_text(ch)
        if path is None:
            path, font = current_path, current_font

        if current and path != current_path:
            runs.append((current, current_path, current_font))
            current = ''
        if not current:
            current_path, current_font = path, font
        current += ch
    if current:
        runs.append((current, current_path, current_font))
    return runs


def _insert_ocr_text(page, blocks, filter_existing=True):
    """Insert invisible selectable text into an unrotated/unflipped page."""
    if not blocks:
        return 0

    if filter_existing:
        blocks, _ = _filter_duplicate_ocr_blocks(page, blocks)

    # OCR boxes are canonical source-PDF coordinates. Convert them to the
    # current PyMuPDF CropBox-relative coordinate system immediately before
    # insertion; this is essential after reopening a previously cropped PDF.
    page_blocks = _ocr_blocks_source_to_page_space(page, blocks)

    inserted = 0
    font_resources = {}
    fallback_warned = False

    for blk in page_blocks:
        text = (blk.get('text') or '').strip()
        rect = blk.get('rect')
        if not text or not rect:
            continue
        try:
            x0, y0, x1, y1 = map(float, rect)
            try:
                page_space = fitz.Rect(
                    0.0, 0.0,
                    float(page.cropbox.width), float(page.cropbox.height))
            except Exception:
                page_space = fitz.Rect(0, 0,
                    float(page.mediabox.width), float(page.mediabox.height))
            r = fitz.Rect(x0, y0, x1, y1) & page_space
            if r.is_empty or r.width < 1 or r.height < 1:
                continue

            h = max(2.0, r.height)
            fontsize = max(3.0, min(72.0, h * 0.82))
            runs = _ocr_font_runs(text)
            if not runs:
                runs = [(text, None, None)]

            # If the line contains mixed scripts, place font runs consecutively
            # using each font's own metrics. Invisible text needs no wrapping.
            run_x = r.x0
            for run_text, path, font in runs:
                if not run_text:
                    continue
                font_name = 'helv'
                metric = fitz.Font(fontname='helv')
                if path and font:
                    if path not in font_resources:
                        try:
                            font_name = f"mergerz_ocr_{len(font_resources)}"
                            # Keep fontfile attached to the text insertion.
                            # This preserves a correct ToUnicode mapping when
                            # multiple Unicode fonts are used on one page.
                            font_resources[path] = font_name
                        except Exception:
                            font_name = 'helv'
                    else:
                        font_name = font_resources[path]
                    if font_name != 'helv':
                        metric = font

                measured = metric.text_length(run_text, fontsize=fontsize)
                # Keep OCR runs inside the detected word/line box when the
                # substitute font is wider than the OCR source glyphs.
                remaining = max(0.5, r.x1 - run_x)
                run_fs = fontsize
                if measured > remaining and measured > 0:
                    run_fs = max(2.5, fontsize * remaining / measured)
                    measured = metric.text_length(run_text, fontsize=run_fs)

                baseline = min(r.y1 - 0.05 * h, r.y0 + run_fs)
                if font_name == 'helv' and path and not fallback_warned:
                    log("Warning: no installed Unicode font covers part of an OCR line; Helvetica fallback may not preserve those glyphs.", "warning")
                    fallback_warned = True

                if font_name != 'helv':
                    # Supplying fontfile on the actual insertion call is
                    # important for reliable Unicode extraction/search.
                    page.insert_text(
                        (run_x, baseline),
                        run_text,
                        fontsize=run_fs,
                        fontname=font_name,
                        fontfile=path,
                        render_mode=3,
                        color=(0, 0, 0),
                    )
                else:
                    page.insert_text(
                        (run_x, baseline),
                        run_text,
                        fontsize=run_fs,
                        fontname='helv',
                        render_mode=3,
                        color=(0, 0, 0),
                    )
                run_x += max(0.0, measured)
                inserted += 1
        except Exception:
            # A single unsupported glyph/span must not corrupt the page.
            continue
    return inserted







