class ToggleTile(QtWidgets.QPushButton):
    def __init__(self, text, parent=None):
        super().__init__(text, parent)
        self.setCheckable(True)
        self.setMinimumHeight(52)
        self.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.toggled.connect(self._refresh)
        self._refresh(False)

    def _refresh(self, checked):
        if checked:
            self.setStyleSheet("""
                QPushButton {
                    background-color: #14361e;
                    color: #4ade80;
                    border: 1px solid #22c55e;
                    border-radius: 8px;
                    font-weight: bold;
                    font-size: 11pt;
                }
                QPushButton:hover { background-color: #1a4526; }
            """)
        else:
            self.setStyleSheet("""
                QPushButton {
                    background-color: #3a1414;
                    color: #f87171;
                    border: 1px solid #ef4444;
                    border-radius: 8px;
                    font-weight: bold;
                    font-size: 11pt;
                }
                QPushButton:hover { background-color: #4a1a1a; }
            """)

    def setEnabledState(self, enabled):
        self.setEnabled(enabled)
        if not enabled:
            self.setStyleSheet("""
                QPushButton {
                    background-color: #2a2a2a;
                    color: #666;
                    border: 1px solid #3a3a3a;
                    border-radius: 8px;
                    font-weight: bold;
                    font-size: 11pt;
                }
            """)
        else:
            self._refresh(self.isChecked())


class TriSlideSelector(QtWidgets.QWidget):
    valueChanged = QtCore.Signal(int)
    _OPTIONS = ((3, "Portrait", "100%"), (4, "Landscape", "82.5%"), (6, "Landscape", "69.1%"))
    _RADIUS = 18
    _CY = 34

    def __init__(self, parent=None):
        super().__init__(parent)
        self._value = 3
        self._hover = -1
        self.setMinimumHeight(118)
        self.setMouseTracking(True)
        self.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)

    def value(self):
        return self._value

    def setValue(self, v):
        if v not in (3, 4, 6):
            return
        if v != self._value:
            self._value = v
            self.update()
            self.valueChanged.emit(v)

    def _positions(self):
        w = self.width()
        n = len(self._OPTIONS)
        margin = 60
        if n == 1:
            return [w // 2]
        step = (w - 2 * margin) / (n - 1)
        return [int(margin + i * step) for i in range(n)]

    def _circle_rect(self, idx, xs):
        r = self._RADIUS
        return QtCore.QRect(xs[idx] - r, self._CY - r, 2 * r, 2 * r)

    def paintEvent(self, event):
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing)
        xs = self._positions()
        cy = self._CY

        if len(xs) >= 2:
            pen = QtGui.QPen(QtGui.QColor("#0078d7"), 4)
            pen.setCapStyle(QtCore.Qt.PenCapStyle.RoundCap)
            p.setPen(pen)
            p.drawLine(xs[0], cy, xs[-1], cy)

        for i, (val, orient, readability) in enumerate(self._OPTIONS):
            rect = self._circle_rect(i, xs)
            active = (val == self._value)
            hover = (i == self._hover)

            if active:
                p.setBrush(QtGui.QColor("#0078d7"))
                p.setPen(QtGui.QPen(QtGui.QColor("#4a9eff"), 3))
            elif hover:
                p.setBrush(QtGui.QColor("#2a3a4a"))
                p.setPen(QtGui.QPen(QtGui.QColor("#0078d7"), 2))
            else:
                p.setBrush(QtGui.QColor("#1e1e1e"))
                p.setPen(QtGui.QPen(QtGui.QColor("#555"), 2))
            p.drawEllipse(rect)

            f = self.font(); f.setBold(True); f.setPointSize(11)
            p.setFont(f)
            p.setPen(QtGui.QColor("white") if active else QtGui.QColor("#d0d0d0"))
            p.drawText(rect, QtCore.Qt.AlignmentFlag.AlignCenter, str(val))

            f.setPointSize(9); f.setBold(False); p.setFont(f)
            p.setPen(QtGui.QColor("#4a9eff") if active else QtGui.QColor("#888"))
            p.drawText(QtCore.QRect(xs[i] - 70, cy + 24, 140, 20),
                       QtCore.Qt.AlignmentFlag.AlignCenter, f"({orient})")
            p.drawText(QtCore.QRect(xs[i] - 70, cy + 44, 140, 20),
                       QtCore.Qt.AlignmentFlag.AlignCenter, f"Readability: {readability}")

    def mouseMoveEvent(self, event):
        xs = self._positions()
        new_hover = -1
        for i in range(len(self._OPTIONS)):
            if self._circle_rect(i, xs).contains(_qt_event_position(event)):
                new_hover = i
                break
        if new_hover != self._hover:
            self._hover = new_hover
            self.update()

    def leaveEvent(self, event):
        self._hover = -1
        self.update()

    def mousePressEvent(self, event):
        xs = self._positions()
        for i in range(len(self._OPTIONS)):
            if self._circle_rect(i, xs).contains(_qt_event_position(event)):
                self.setValue(self._OPTIONS[i][0])
                return


class ElidedLabel(QtWidgets.QLabel):
    def __init__(self, text="", mode=QtCore.Qt.TextElideMode.ElideMiddle, parent=None):
        super().__init__(parent)
        self._full_text = ""
        self._mode = mode
        self._natural_width = 0
        self.setSizePolicy(QtWidgets.QSizePolicy.Policy.Preferred,
                           QtWidgets.QSizePolicy.Policy.Preferred)
        self.setMinimumWidth(40)
        self.setText(text)

    def setText(self, text):
        self._full_text = text or ""
        self.setToolTip(text or "")
        self._recompute_natural_width()
        self._apply_elide()
        self.updateGeometry()

    def fullText(self):
        return self._full_text

    def _recompute_natural_width(self):
        try:
            fm = QtGui.QFontMetrics(self.font())
            self._natural_width = (fm.horizontalAdvance(self._full_text)
                                   if self._full_text else 0)
        except Exception:
            self._natural_width = 0

    def _stylesheet_padding(self):
        ss = self.styleSheet() or ""
        if not ss:
            return 0, 0, 0, 0
        import re
        m = re.search(r"padding\s*:\s*([^;]+);?", ss)
        if not m:
            return 0, 0, 0, 0
        parts = m.group(1).strip().split()
        try:
            vals = []
            for p in parts:
                p = p.strip().lower().replace("px", "").strip()
                vals.append(int(float(p)))
        except Exception:
            return 0, 0, 0, 0
        if len(vals) == 1:
            return vals[0], vals[0], vals[0], vals[0]
        if len(vals) == 2:
            v, h = vals
            return h, v, h, v
        if len(vals) == 3:
            t, h, b = vals
            return h, t, h, b
        if len(vals) == 4:
            return vals[0], vals[1], vals[2], vals[3]
        return 0, 0, 0, 0

    def _horizontal_padding(self):
        try:
            m = self.contentsMargins()
            base = max(0, m.left()) + max(0, m.right())
        except Exception:
            base = 0
        pl, _pt, pr, _pb = self._stylesheet_padding()
        return base + pl + pr

    def changeEvent(self, event):
        et = event.type()
        if et in (QtCore.QEvent.Type.FontChange, QtCore.QEvent.Type.StyleChange):
            self._recompute_natural_width()
            self._apply_elide()
            self.updateGeometry()
        super().changeEvent(event)

    def sizeHint(self):
        self._recompute_natural_width()
        h = super().sizeHint().height()
        pad = self._horizontal_padding()
        natural = self._natural_width + pad
        mw = self.maximumWidth()
        if 0 < mw < 16777215:
            natural = min(natural, mw)
        mn = self.minimumWidth()
        if natural < mn:
            natural = mn
        return QtCore.QSize(max(40, natural), h)

    def minimumSizeHint(self):
        h = super().minimumSizeHint().height()
        return QtCore.QSize(self.minimumWidth(), h)

    def _apply_elide(self):
        try:
            fm = QtGui.QFontMetrics(self.font())
            avail = max(20, self.width() - self._horizontal_padding())
            if avail < self._natural_width:
                new_text = fm.elidedText(self._full_text, self._mode, avail)
            else:
                new_text = self._full_text
            if super().text() != new_text:
                super().setText(new_text)
        except Exception:
            pass

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._apply_elide()


# ---------------- Deselect mixin ----------------
class _SingleClickDeselectMixin:
    def _install_deselect_behavior(self):
        self._click_deselect_item = None
        self._click_deselect_timer = QtCore.QTimer(self)
        self._click_deselect_timer.setSingleShot(True)
        self._click_deselect_timer.timeout.connect(self._on_deselect_timeout)

    def _on_deselect_timeout(self):
        if self._click_deselect_item is not None:
            try:
                self._click_deselect_item.setSelected(False)
            except Exception:
                pass
            self._click_deselect_item = None
        try:
            self.viewport().update()
        except Exception:
            pass

    def _handle_deselect_press(self, event):
        if event.button() != QtCore.Qt.MouseButton.LeftButton:
            return
        try:
            item = self.itemAt(_qt_event_position(event))
        except Exception:
            return
        if item is None:
            self.clearSelection()
            self._click_deselect_item = None
            self._click_deselect_timer.stop()
            return
        if (self.selectionMode()
                == QtWidgets.QAbstractItemView.SelectionMode.SingleSelection
                and item.isSelected()):
            if len(self.selectedItems()) <= 1:
                self._click_deselect_item = item
                self._click_deselect_timer.start(
                    QtWidgets.QApplication.doubleClickInterval())
            else:
                self._click_deselect_item = None
                self._click_deselect_timer.stop()
        else:
            self._click_deselect_item = None
            self._click_deselect_timer.stop()


def _pdf_paths_from_urls(urls):
    out = []
    for u in urls:
        if not u.isLocalFile():
            continue
        p = u.toLocalFile()
        if p.lower().endswith(".pdf"):
            out.append(p)
    return out


def _pdf_or_image_paths_from_urls(urls):
    """Return local PDF/PNG/JPG/JPEG paths for Edit PDF imports/drops."""
    allowed = {".pdf", ".png", ".jpg", ".jpeg"}
    out = []
    for u in urls:
        if not u.isLocalFile():
            continue
        p = u.toLocalFile()
        if os.path.splitext(p)[1].lower() in allowed:
            out.append(p)
    return out


class DragDropFileList(_SingleClickDeselectMixin, QtWidgets.QListWidget):
    orderChanged = QtCore.Signal()
    editRequested = QtCore.Signal(str)
    openPdfRequested = QtCore.Signal(str)
    removeFileRequested = QtCore.Signal(str)

    def __init__(self, parent=None, unit_label="Pages"):
        super().__init__(parent)
        self._unit_label = unit_label
        self.setDragEnabled(True)
        self.setAcceptDrops(True)
        self.setDropIndicatorShown(False)
        self.setDragDropMode(QtWidgets.QAbstractItemView.DragDropMode.DragDrop)
        self.setDefaultDropAction(QtCore.Qt.DropAction.MoveAction)
        self.setSelectionMode(QtWidgets.QAbstractItemView.SelectionMode.SingleSelection)
        self.setSpacing(4)
        self.setUniformItemSizes(True)
        self.files = []
        self._drag_src_row = -1
        self._drag_src_file = None
        self._drag_src_widget = None
        self._placeholder_row = -1

        self._autoscroll_margin = 60
        self._autoscroll_max_speed = 2
        self._autoscroll_min_speed = 1
        self._autoscroll_direction = 0
        self._autoscroll_speed = 0.0
        self._last_drag_pos = None
        self._autoscroll_timer = QtCore.QTimer(self)
        self._autoscroll_timer.setInterval(16)
        self._autoscroll_timer.timeout.connect(self._autoscroll_step)

        self.itemDoubleClicked.connect(self._on_item_double_clicked)

        self._install_deselect_behavior()

        self.setStyleSheet("""
            QListWidget {
                background-color: #1e1e1e;
                border: 1px solid #3a3a3a;
                border-radius: 6px;
                padding: 4px;
            }
            QListWidget::item {
                background-color: #242424;
                border: 1px solid #333;
                border-radius: 6px;
                padding: 4px;
            }
            QListWidget::item:selected {
                background-color: #2a3a4a;
                border: 1px solid #0078d7;
            }
        """)

    def paintEvent(self, event):
        super().paintEvent(event)
        if self.count() == 0:
            p = QtGui.QPainter(self.viewport())
            p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
            p.setPen(QtGui.QColor("#6a6a6a"))
            f = self.font()
            f.setPointSize(13)
            f.setItalic(True)
            p.setFont(f)
            p.drawText(self.viewport().rect(), QtCore.Qt.AlignmentFlag.AlignCenter,
                       "Drag and drop PDFs here\n"
                       "or click  Add PDFs")

    def mousePressEvent(self, event):
        if event.button() == QtCore.Qt.MouseButton.RightButton:
            item = self.itemAt(_qt_event_position(event))
            if item is not None and item.isSelected():
                event.accept()
                return
        self._handle_deselect_press(event)
        super().mousePressEvent(event)

    def mouseDoubleClickEvent(self, event):
        self._click_deselect_item = None
        self._click_deselect_timer.stop()
        super().mouseDoubleClickEvent(event)

    def _on_item_double_clicked(self, item):
        if item is None:
            return
        f = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
        p = f.get('path')
        if p:
            self.openPdfRequested.emit(p)

    def set_unit_label(self, label):
        self._unit_label = label
        self._rebuild()

    def add_files(self, paths):
        for p in paths:
            if any(f['path'] == p for f in self.files):
                continue
            try:
                size_mb = os.path.getsize(p) / (1024 * 1024)
                pages = 0
                try:
                    with fitz.open(p) as doc:
                        pages = doc.page_count
                except Exception:
                    pages = 0
                self.files.append({'path': p, 'name': os.path.basename(p),
                                   'size_mb': size_mb, 'pages': pages})
            except Exception:
                pass
        self._rebuild()

    def clear_files(self):
        self.files = []
        self._rebuild()

    def remove_file_by_path(self, path):
        self.files = [f for f in self.files if f['path'] != path]
        self._rebuild()

    def refresh_file_page_counts(self):
        for f in self.files:
            try:
                with fitz.open(f['path']) as doc:
                    f['pages'] = doc.page_count
                f['size_mb'] = os.path.getsize(f['path']) / (1024 * 1024)
            except Exception:
                pass
        self._rebuild()

    def reorder_by_name(self):
        self.files = natsorted(self.files,
                               key=lambda f: os.path.splitext(f['name'])[0],
                               alg=ns.IGNORECASE)
        self._rebuild()

    def _rebuild(self):
        scroll_bar = self.verticalScrollBar()
        saved_scroll = scroll_bar.value()
        self.blockSignals(True)
        self.setUpdatesEnabled(False)
        try:
            self.clear()
            for idx, f in enumerate(self.files):
                item = QtWidgets.QListWidgetItem()
                item.setSizeHint(QtCore.QSize(100, 68))
                item.setData(QtCore.Qt.ItemDataRole.UserRole, f)
                self.addItem(item)
                self.setItemWidget(item, self._make_row_widget(idx, f))
        finally:
            self.setUpdatesEnabled(True)
            self.blockSignals(False)
        QtCore.QTimer.singleShot(0, lambda v=saved_scroll: scroll_bar.setValue(v))
        self.orderChanged.emit()
        self.viewport().update()

    def startDrag(self, supportedActions):
        item = self.currentItem()
        if item is None:
            return
        self._drag_src_row = self.row(item)
        self._drag_src_file = item.data(QtCore.Qt.ItemDataRole.UserRole)
        drag = QtGui.QDrag(self)
        mime = QtCore.QMimeData()
        mime.setText(_ROW_MIME_TEXT)
        drag.setMimeData(mime)
        widget = self.itemWidget(item)
        if widget is not None:
            self._drag_src_widget = widget
            try:
                pixmap = widget.grab()
                drag.setPixmap(pixmap)
                drag.setHotSpot(QtCore.QPoint(pixmap.width() // 2, pixmap.height() // 2))
            except Exception:
                drag.setPixmap(QtGui.QPixmap(1, 1))
            try:
                effect = QtWidgets.QGraphicsOpacityEffect(widget)
                effect.setOpacity(0.3)
                widget.setGraphicsEffect(effect)
            except Exception:
                pass
        else:
            drag.setPixmap(QtGui.QPixmap(1, 1))
        drag.exec(QtCore.Qt.DropAction.MoveAction)
        try:
            if self._drag_src_widget is not None:
                self._drag_src_widget.setGraphicsEffect(None)
        except Exception:
            pass
        self._drag_src_widget = None
        self._drag_src_row = -1
        self._drag_src_file = None
        self._stop_autoscroll()
        self._remove_placeholder()

    def dragEnterEvent(self, event):
        md = event.mimeData()
        if md is not None and md.hasUrls():
            pdfs = _pdf_paths_from_urls(md.urls())
            if pdfs:
                event.setDropAction(QtCore.Qt.DropAction.CopyAction)
                event.accept()
                return
        if md is not None and md.hasText() and md.text() == _ROW_MIME_TEXT:
            event.setDropAction(QtCore.Qt.DropAction.MoveAction)
            event.accept()
        else:
            event.ignore()

    def dragMoveEvent(self, event):
        md = event.mimeData()
        if md is not None and md.hasUrls():
            pdfs = _pdf_paths_from_urls(md.urls())
            if pdfs:
                event.setDropAction(QtCore.Qt.DropAction.CopyAction)
                event.accept()
                return
            event.ignore()
            return
        if md is None or md.text() != _ROW_MIME_TEXT:
            event.ignore()
            return
        viewport_pos = self.viewport().mapFrom(self, _qt_event_position(event))
        self._last_drag_pos = viewport_pos
        self._update_autoscroll(viewport_pos)
        new_ph = self._compute_drop_index(viewport_pos)
        src_idx = self._drag_src_row
        no_op = (src_idx >= 0 and (new_ph == src_idx or new_ph == src_idx + 1))
        if no_op:
            if self._placeholder_row >= 0:
                self._remove_placeholder()
        elif new_ph != self._placeholder_row:
            self._remove_placeholder()
            self._insert_placeholder_at(new_ph)
        event.setDropAction(QtCore.Qt.DropAction.MoveAction)
        event.accept()

    def dragLeaveEvent(self, event):
        self._stop_autoscroll()
        self._remove_placeholder()
        super().dragLeaveEvent(event)

    def dropEvent(self, event):
        md = event.mimeData()
        if md is not None and md.hasUrls():
            pdfs = _pdf_paths_from_urls(md.urls())
            if pdfs:
                self.add_files(pdfs)
                event.setDropAction(QtCore.Qt.DropAction.CopyAction)
                event.accept()
                return
            event.ignore()
            return
        if md is None or md.text() != _ROW_MIME_TEXT:
            event.ignore()
            return
        ph = self._placeholder_row
        src = self._drag_src_row
        self._stop_autoscroll()
        self._remove_placeholder()
        if ph < 0 or src < 0 or not (0 <= src < len(self.files)):
            event.setDropAction(QtCore.Qt.DropAction.MoveAction)
            event.accept()
            return
        dst = ph if ph <= src else ph - 1
        if dst == src:
            event.setDropAction(QtCore.Qt.DropAction.MoveAction)
            event.accept()
            return
        moved = self.files.pop(src)
        self.files.insert(dst, moved)
        self._rebuild()
        event.setDropAction(QtCore.Qt.DropAction.MoveAction)
        event.accept()

    def _stop_autoscroll(self):
        try:
            self._autoscroll_timer.stop()
        except Exception:
            pass
        self._autoscroll_direction = 0
        self._autoscroll_speed = 0.0
        self._last_drag_pos = None

    def _update_autoscroll(self, pos):
        margin = self._autoscroll_margin
        h = self.viewport().height()
        y = pos.y()
        scrollbar = self.verticalScrollBar()
        direction = 0
        intensity = 0.0
        if y < margin and scrollbar.value() > scrollbar.minimum():
            direction = -1
            intensity = min(1.0, max(0.0, (margin - y) / float(margin)))
        elif y > h - margin and scrollbar.value() < scrollbar.maximum():
            direction = 1
            intensity = min(1.0, max(0.0, (y - (h - margin)) / float(margin)))
        self._autoscroll_direction = direction
        self._autoscroll_speed = (self._autoscroll_min_speed +
            (self._autoscroll_max_speed - self._autoscroll_min_speed) * (intensity ** 2))
        if direction != 0:
            if not self._autoscroll_timer.isActive():
                self._autoscroll_timer.start()
        else:
            self._autoscroll_timer.stop()

    def _autoscroll_step(self):
        if self._autoscroll_direction == 0 or self._autoscroll_speed <= 0:
            self._autoscroll_timer.stop()
            return
        scrollbar = self.verticalScrollBar()
        current = scrollbar.value()
        step = int(round(self._autoscroll_speed))
        if step < 1:
            step = 1
        target = current + self._autoscroll_direction * step
        target = max(scrollbar.minimum(), min(scrollbar.maximum(), target))
        if target == current:
            self._autoscroll_timer.stop()
            return
        scrollbar.setValue(target)
        if self._last_drag_pos is not None:
            new_ph = self._compute_drop_index(self._last_drag_pos)
            src_idx = self._drag_src_row
            no_op = (src_idx >= 0 and
                     (new_ph == src_idx or new_ph == src_idx + 1))
            if no_op:
                if self._placeholder_row >= 0:
                    self._remove_placeholder()
            elif new_ph != self._placeholder_row:
                self._remove_placeholder()
                self._insert_placeholder_at(new_ph)

    def _compute_drop_index(self, viewport_pos):
        y = viewport_pos.y()
        ph = self._placeholder_row
        src = self._drag_src_row
        count = self.count()
        if count == 0:
            return 0
        max_bottom = -1
        for r in range(count):
            if r == ph:
                continue
            it = self.item(r)
            if it is None:
                continue
            rc = self.visualItemRect(it)
            if rc.isValid() and not rc.isNull() and rc.bottom() > max_bottom:
                max_bottom = rc.bottom()
        if max_bottom >= 0 and y > max_bottom:
            return len(self.files)
        for r in range(count):
            if r == ph:
                continue
            item = self.item(r)
            if item is None:
                continue
            rect = self.visualItemRect(item)
            cy = rect.center().y()
            file_idx_before = (r - 1) if (ph >= 0 and r > ph) else r
            if y < cy:
                return file_idx_before
            if y == cy:
                if src < file_idx_before:
                    return file_idx_before + 1
                if src > file_idx_before:
                    return file_idx_before
                return file_idx_before
        return len(self.files)

    def _insert_placeholder_at(self, row):
        row = max(0, min(row, self.count()))
        item = QtWidgets.QListWidgetItem()
        item.setSizeHint(QtCore.QSize(100, 68))
        item.setFlags(QtCore.Qt.ItemFlag.NoItemFlags)
        self.insertItem(row, item)
        ph_widget = QtWidgets.QWidget()
        ph_widget.setStyleSheet(
            "background-color: rgba(0, 120, 215, 30); "
            "border: 2px dashed #0078d7; border-radius: 6px;")
        self.setItemWidget(item, ph_widget)
        self._placeholder_row = row

    def _remove_placeholder(self):
        if self._placeholder_row < 0:
            return
        if 0 <= self._placeholder_row < self.count():
            self.takeItem(self._placeholder_row)
        self._placeholder_row = -1

    def _make_row_widget(self, idx, f):
        w = QtWidgets.QWidget()
        w.setStyleSheet("background: transparent;")
        h = QtWidgets.QHBoxLayout(w)
        h.setContentsMargins(8, 6, 8, 6)
        h.setSpacing(10)

        num = QtWidgets.QLabel(str(idx + 1))
        num.setFixedSize(28, 28)
        num.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        num.setStyleSheet(
            "background-color: #0078d7; color: white; "
            "border-radius: 14px; font-weight: bold;")
        h.addWidget(num)

        name_col = QtWidgets.QWidget()
        name_col.setStyleSheet("background: transparent;")
        name_col.setMinimumWidth(180)
        name_col.setMaximumWidth(260)
        nc = QtWidgets.QVBoxLayout(name_col)
        nc.setContentsMargins(0, 0, 0, 0)
        nc.setSpacing(2)

        name = ElidedLabel(f['name'], QtCore.Qt.TextElideMode.ElideRight)
        name.setStyleSheet("color: #f0f0f0; font-weight: bold; font-size: 10.5pt;")
        name.setMinimumWidth(120)
        nc.addWidget(name)

        meta = QtWidgets.QLabel(
            f"{f['size_mb']:.2f} MB  |  {f['pages']} {self._unit_label}")
        meta.setStyleSheet("color: #8a8a8a; font-size: 9pt;")
        nc.addWidget(meta)
        h.addWidget(name_col, stretch=2)

        path_lbl = ElidedLabel(f['path'], QtCore.Qt.TextElideMode.ElideMiddle)
        path_lbl.setStyleSheet("color: #6a6a6a; font-size: 8.5pt;")
        path_lbl.setMinimumWidth(120)
        h.addWidget(path_lbl, stretch=3)

        open_pdf_btn = QtWidgets.QPushButton()
        open_pdf_btn.setFixedSize(34, 34)
        open_pdf_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        open_pdf_btn.setToolTip("Open full PDF")
        open_pdf_btn.setStyleSheet("""
            QPushButton {
                background-color: #14361e;
                border: 1px solid #22c55e;
                border-radius: 6px;
            }
            QPushButton:hover { background-color: #1a4526; }
        """)
        icon_path = os.path.join(ICONS_FOLDER, "open-pdf.svg")
        icon = _render_svg_icon(icon_path, size=20)
        if icon is not None:
            open_pdf_btn.setIcon(icon)
            open_pdf_btn.setIconSize(QtCore.QSize(20, 20))
        else:
            open_pdf_btn.setText("↗")
        open_pdf_btn.clicked.connect(lambda _, p=f['path']:
                                     self.openPdfRequested.emit(p))
        h.addWidget(open_pdf_btn)

        edit_btn = QtWidgets.QPushButton()
        edit_btn.setFixedSize(34, 34)
        edit_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        edit_btn.setToolTip("Edit PDF")
        edit_btn.setStyleSheet("""
            QPushButton {
                background-color: #2a3a4a;
                border: 1px solid #0078d7;
                border-radius: 6px;
            }
            QPushButton:hover { background-color: #3a4a5a; }
        """)
        icon_path = os.path.join(ICONS_FOLDER, "edit.svg")
        icon = _render_svg_icon(icon_path, size=20)
        if icon is not None:
            edit_btn.setIcon(icon)
            edit_btn.setIconSize(QtCore.QSize(20, 20))
        else:
            edit_btn.setText("✎")
        edit_btn.clicked.connect(lambda _, p=f['path']:
                                 self.editRequested.emit(p))
        h.addWidget(edit_btn)

        remove_btn = QtWidgets.QPushButton()
        remove_btn.setFixedSize(34, 34)
        remove_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        remove_btn.setToolTip("Remove from list")
        remove_btn.setStyleSheet("""
            QPushButton {
                background-color: #3a1414;
                border: 1px solid #ef4444;
                border-radius: 6px;
            }
            QPushButton:hover { background-color: #4a1a1a; }
        """)
        icon_path = os.path.join(ICONS_FOLDER, "remove.svg")
        icon = _render_svg_icon(icon_path, size=20)
        if icon is not None:
            remove_btn.setIcon(icon)
            remove_btn.setIconSize(QtCore.QSize(20, 20))
        else:
            remove_btn.setText("✕")
        remove_btn.clicked.connect(lambda _, p=f['path']:
                                   self.removeFileRequested.emit(p))
        h.addWidget(remove_btn)
        return w


# ============================================================
# THUMBNAIL DENSITY SLIDER
# ============================================================
class _ThumbnailDensitySlider(QtWidgets.QSlider):
    """Horizontal density slider whose groove click selects the nearest value."""
    def __init__(self, orientation, parent=None):
        super().__init__(orientation, parent)
        self.valueChanged.connect(self._update_value_tooltip)

    def _tooltip_text(self, value):
        return f"Pages per row: {int(value)}"

    def _update_value_tooltip(self, value=None):
        try:
            if value is None:
                value = self.value()
            self.setToolTip(self._tooltip_text(int(value)))
        except Exception:
            pass

    def mousePressEvent(self, event):
        if event.button() == QtCore.Qt.MouseButton.LeftButton:
            opt = QtWidgets.QStyleOptionSlider()
            self.initStyleOption(opt)
            groove = self.style().subControlRect(
                QtWidgets.QStyle.ComplexControl.CC_Slider, opt,
                QtWidgets.QStyle.SubControl.SC_SliderGroove, self)
            handle = self.style().subControlRect(
                QtWidgets.QStyle.ComplexControl.CC_Slider, opt,
                QtWidgets.QStyle.SubControl.SC_SliderHandle, self)

            span = max(1, groove.width() - handle.width())
            click_x = float(_qt_event_position(event).x()) - groove.left() - (handle.width() / 2.0)
            click_x = max(0.0, min(float(span), click_x))
            value = QtWidgets.QStyle.sliderValueFromPosition(
                self.minimum(), self.maximum(), int(round(click_x)), span,
                opt.upsideDown)
            self.setValue(value)
            event.accept()
            return
        super().mousePressEvent(event)


# ============================================================
# THUMBNAIL GRID
# ============================================================
_PLACEHOLDER_ROLE = QtCore.Qt.ItemDataRole.UserRole + 101


class _ThumbnailGridDelegate(QtWidgets.QStyledItemDelegate):
    def sizeHint(self, option, index):
        view = self.parent()
        # The delegate and QListView must agree on exactly the same cell size.
        # The previous implementation returned a narrower _item_size while
        # QListView was given a wider gridSize. In IconMode/Adjust that mismatch
        # could make Qt wrap a column early (e.g. 3 columns while the user chose 4).
        grid_size = getattr(view, "_grid_size", None)
        if grid_size is not None:
            return QtCore.QSize(grid_size)
        return super().sizeHint(option, index)

    def paint(self, painter, option, index):
        view = self.parent()
        inset = 3
        card = option.rect.adjusted(inset, inset, -inset, -inset)

        if bool(index.data(_PLACEHOLDER_ROLE)):
            painter.save()
            painter.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
            painter.setPen(QtGui.QPen(
                QtGui.QColor("#0078d7"), 2, QtCore.Qt.PenStyle.DashLine))
            painter.setBrush(QtGui.QBrush(QtGui.QColor(0, 120, 215, 45)))
            painter.drawRoundedRect(card, 8, 8)
            painter.restore()
            return

        painter.save()
        painter.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        painter.setRenderHint(QtGui.QPainter.RenderHint.SmoothPixmapTransform, True)

        selected = bool(option.state & QtWidgets.QStyle.StateFlag.State_Selected)
        hovered = bool(option.state & QtWidgets.QStyle.StateFlag.State_MouseOver)

        data = index.data(QtCore.Qt.ItemDataRole.UserRole) or {}
        is_cut = bool(data.get('cut'))
        is_copied = bool(data.get('copied'))

        if selected:
            bg = QtGui.QColor("#2a3a4a")
            border = QtGui.QColor("#0078d7")
        elif hovered:
            bg = QtGui.QColor("#2b2b2b")
            border = QtGui.QColor("#444444")
        else:
            bg = QtGui.QColor("#242424")
            border = QtGui.QColor("#333333")

        if is_cut:
            bg = QtGui.QColor("#3a2a1a")
            border = QtGui.QColor("#f5b942")

        painter.setPen(QtGui.QPen(border, 2))
        painter.setBrush(QtGui.QBrush(bg))
        painter.drawRoundedRect(card, 8, 8)

        icon = index.data(QtCore.Qt.ItemDataRole.DecorationRole)
        view_image_w = max(24, int(getattr(view, "_image_width", max(24, card.width() - 12))))
        view_image_h = max(24, int(getattr(view, "_image_height", 90)))
        icon_rect = QtCore.QRect(
            card.left() + max(0, (card.width() - view_image_w) // 2),
            card.top() + 4,
            min(view_image_w, max(24, card.width() - 6)),
            view_image_h,
        )
        if isinstance(icon, QtGui.QIcon) and not icon.isNull():
            if is_cut:
                painter.setOpacity(0.4)
            pm = icon.pixmap(icon_rect.size(), QtGui.QIcon.Mode.Normal, QtGui.QIcon.State.Off)
            if not pm.isNull():
                scaled = pm.scaled(
                    icon_rect.size(), QtCore.Qt.AspectRatioMode.KeepAspectRatio,
                    QtCore.Qt.TransformationMode.SmoothTransformation)
                px = icon_rect.left() + (icon_rect.width() - scaled.width()) // 2
                py = icon_rect.top() + (icon_rect.height() - scaled.height()) // 2
                painter.drawPixmap(px, py, scaled)
            painter.setOpacity(1.0)

        placeholder_row = getattr(view, "_placeholder_row", -1)
        current_num = index.row() + 1
        if placeholder_row >= 0 and index.row() > placeholder_row:
            current_num -= 1

        original_idx = data.get("original_idx")
        original_num = (original_idx + 1
                        if isinstance(original_idx, int) else current_num)

        image_h = max(24, int(getattr(view, "_image_height", 90)))
        label_rect = QtCore.QRect(
            card.left() + 8,
            card.top() + image_h + 5,
            card.width() - 16,
            max(24, card.height() - image_h - 8),
        )

        painter.setPen(QtGui.QColor("#f0f0f0"))
        font = QtGui.QFont(option.font)
        font.setBold(True)
        font.setPointSize(max(9, font.pointSize()))
        painter.setFont(font)
        painter.drawText(
            label_rect,
            QtCore.Qt.AlignmentFlag.AlignLeft | QtCore.Qt.AlignmentFlag.AlignVCenter,
            str(current_num),
        )

        rotation_present = (isinstance(data.get("rotation"), int)
                            and data["rotation"] % 360)

        if rotation_present:
            painter.save()
            badge = QtCore.QRect(card.left() + 6, card.top() + 6, 34, 22)
            painter.setPen(QtCore.Qt.PenStyle.NoPen)
            painter.setBrush(QtGui.QBrush(QtGui.QColor("#3a2a0a")))
            painter.drawRoundedRect(badge, 6, 6)
            painter.setPen(QtGui.QColor("#f5b942"))
            rf = QtGui.QFont(font)
            rf.setPointSize(max(8, font.pointSize() - 1))
            rf.setBold(True)
            painter.setFont(rf)
            painter.drawText(badge, QtCore.Qt.AlignmentFlag.AlignCenter,
                             f"{data['rotation'] % 360}°")
            painter.restore()

        flip_h_present = bool(data.get("flip_h"))
        flip_v_present = bool(data.get("flip_v"))
        flip_tags = []
        if flip_h_present:
            flip_tags.append("H")
        if flip_v_present:
            flip_tags.append("V")
        if flip_tags:
            painter.save()
            text = "FLIP " + "".join(flip_tags)
            bf = QtGui.QFont(font)
            bf.setPointSize(max(8, font.pointSize() - 1))
            bf.setBold(True)
            bm = QtGui.QFontMetrics(bf)
            bw = max(34, bm.horizontalAdvance(text) + 14)
            bh = 22
            x = card.left() + 6
            if rotation_present:
                x += 38
            badge = QtCore.QRect(x, card.top() + 6, bw, bh)
            painter.setPen(QtCore.Qt.PenStyle.NoPen)
            painter.setBrush(QtGui.QBrush(QtGui.QColor("#0a2a4a")))
            painter.drawRoundedRect(badge, 6, 6)
            painter.setPen(QtGui.QColor("#7cc0ff"))
            painter.setFont(bf)
            painter.drawText(badge, QtCore.Qt.AlignmentFlag.AlignCenter, text)
            painter.restore()

        crop_present = bool(data.get("crop"))
        if crop_present:
            painter.save()
            badge = QtCore.QRect(card.right() - 40, card.top() + 6, 34, 22)
            painter.setPen(QtCore.Qt.PenStyle.NoPen)
            painter.setBrush(QtGui.QBrush(QtGui.QColor("#0a3a2a")))
            painter.drawRoundedRect(badge, 6, 6)
            painter.setPen(QtGui.QColor("#4ade80"))
            rf = QtGui.QFont(font)
            rf.setPointSize(max(8, font.pointSize() - 1))
            rf.setBold(True)
            painter.setFont(rf)
            painter.drawText(badge, QtCore.Qt.AlignmentFlag.AlignCenter, "CROP")
            painter.restore()

        # NEW: OCR pill (top-right, below CROP badge if present)
        if data.get('ocr_done') or data.get('ocr'):
            painter.save()
            text = "OCR"
            bf = QtGui.QFont(font)
            bf.setPointSize(max(8, font.pointSize() - 1))
            bf.setBold(True)
            bm = QtGui.QFontMetrics(bf)
            bw = max(30, bm.horizontalAdvance(text) + 14)
            bh = 22
            x = card.right() - bw - 6
            y = card.top() + 6
            if crop_present:
                y += 26
            badge = QtCore.QRect(x, y, bw, bh)
            painter.setPen(QtCore.Qt.PenStyle.NoPen)
            painter.setBrush(QtGui.QBrush(QtGui.QColor("#2a1a4a")))
            painter.drawRoundedRect(badge, 6, 6)
            painter.setPen(QtGui.QColor("#a78bfa"))
            painter.setFont(bf)
            painter.drawText(badge, QtCore.Qt.AlignmentFlag.AlignCenter, text)
            painter.restore()

        # Filter pill (top-right, below OCR and CROP badges).
        filter_badge = _filter_badge_text(_entry_filter_config(data))
        if filter_badge:
            painter.save()
            text_badge = filter_badge
            bf = QtGui.QFont(font)
            bf.setPointSize(max(8, font.pointSize() - 1))
            bf.setBold(True)
            bm = QtGui.QFontMetrics(bf)
            bw = max(44, bm.horizontalAdvance(text_badge) + 14)
            bh = 22
            x = card.right() - bw - 6
            y = card.top() + 6
            if crop_present:
                y += 26
            if data.get('ocr_done') or data.get('ocr'):
                y += 26
            badge = QtCore.QRect(x, y, bw, bh)
            painter.setPen(QtCore.Qt.PenStyle.NoPen)
            painter.setBrush(QtGui.QBrush(QtGui.QColor("#2a2a2a")))
            painter.drawRoundedRect(badge, 6, 6)
            painter.setPen(QtGui.QColor("#f0f0f0"))
            painter.setFont(bf)
            painter.drawText(badge, QtCore.Qt.AlignmentFlag.AlignCenter, text_badge)
            painter.restore()

        # Page Design pill (top-right, below CROP/OCR/filter).
        design_present = _page_design_has_any(data)
        if design_present:
            painter.save()
            text = "DESIGN"
            bf = QtGui.QFont(font)
            bf.setPointSize(max(8, font.pointSize() - 1))
            bf.setBold(True)
            bm = QtGui.QFontMetrics(bf)
            bw = max(54, bm.horizontalAdvance(text) + 14)
            bh = 22
            x = card.right() - bw - 6
            y = card.top() + 6
            if crop_present:
                y += 26
            if data.get('ocr_done') or data.get('ocr'):
                y += 26
            if filter_badge:
                y += 26
            badge = QtCore.QRect(x, y, bw, bh)
            painter.setPen(QtCore.Qt.PenStyle.NoPen)
            painter.setBrush(QtGui.QBrush(QtGui.QColor("#2c244a")))
            painter.drawRoundedRect(badge, 6, 6)
            painter.setPen(QtGui.QColor("#c4b5fd"))
            painter.setFont(bf)
            painter.drawText(badge, QtCore.Qt.AlignmentFlag.AlignCenter, text)
            painter.restore()

        # Stretch pill (top-right, below CROP, OCR, filter, and Page Design).
        stretch_ratio = data.get("stretch_ratio")
        try:
            stretch_present = (stretch_ratio is not None
                               and math.isfinite(float(stretch_ratio))
                               and float(stretch_ratio) > 0)
        except (TypeError, ValueError, OverflowError):
            stretch_present = False
        if stretch_present:
            painter.save()
            text = "STRETCH"
            bf = QtGui.QFont(font)
            bf.setPointSize(max(8, font.pointSize() - 1))
            bf.setBold(True)
            bm = QtGui.QFontMetrics(bf)
            bw = max(48, bm.horizontalAdvance(text) + 14)
            bh = 22
            x = card.right() - bw - 6
            y = card.top() + 6
            if crop_present:
                y += 26
            if data.get('ocr_done') or data.get('ocr'):
                y += 26
            if filter_badge:
                y += 26
            if design_present:
                y += 26
            badge = QtCore.QRect(x, y, bw, bh)
            painter.setPen(QtCore.Qt.PenStyle.NoPen)
            painter.setBrush(QtGui.QBrush(QtGui.QColor("#12352f")))
            painter.drawRoundedRect(badge, 6, 6)
            painter.setPen(QtGui.QColor("#5eead4"))
            painter.setFont(bf)
            painter.drawText(badge, QtCore.Qt.AlignmentFlag.AlignCenter, text)
            painter.restore()

        # N-up pill (top-right, below the existing edit pills).
        if data.get("nup"):
            painter.save()
            text = "N-UP"
            bf = QtGui.QFont(font)
            bf.setPointSize(max(8, font.pointSize() - 1))
            bf.setBold(True)
            bm = QtGui.QFontMetrics(bf)
            bw = max(38, bm.horizontalAdvance(text) + 14)
            bh = 22
            x = card.right() - bw - 6
            y = card.top() + 6
            if crop_present:
                y += 26
            if data.get('ocr_done') or data.get('ocr'):
                y += 26
            if filter_badge:
                y += 26
            if design_present:
                y += 26
            if stretch_present:
                y += 26
            badge = QtCore.QRect(x, y, bw, bh)
            painter.setPen(QtCore.Qt.PenStyle.NoPen)
            painter.setBrush(QtGui.QBrush(QtGui.QColor("#153a32")))
            painter.drawRoundedRect(badge, 6, 6)
            painter.setPen(QtGui.QColor("#5eead4"))
            painter.setFont(bf)
            painter.drawText(badge, QtCore.Qt.AlignmentFlag.AlignCenter, text)
            painter.restore()

        if is_cut or is_copied:
            painter.save()
            badge_x = card.left() + 6
            if rotation_present:
                badge_x += 38
            if flip_tags:
                badge_x = card.left() + 6
            label_text = "CUT" if is_cut else "COPIED"
            bf = QtGui.QFont(font)
            bf.setPointSize(max(8, font.pointSize() - 1))
            bf.setBold(True)
            bm = QtGui.QFontMetrics(bf)
            bw = max(34, bm.horizontalAdvance(label_text) + 14)
            bh = 20
            y = card.top() + 6
            if flip_tags:
                y += 26
            badge = QtCore.QRect(badge_x, y, bw, bh)
            painter.setPen(QtCore.Qt.PenStyle.NoPen)
            if is_cut:
                painter.setBrush(QtGui.QBrush(QtGui.QColor("#3a2a0a")))
            else:
                painter.setBrush(QtGui.QBrush(QtGui.QColor("#0a3a5c")))
            painter.drawRoundedRect(badge, bh // 2, bh // 2)
            painter.setPen(QtGui.QColor("#f5b942") if is_cut
                           else QtGui.QColor("#4a9eff"))
            painter.setFont(bf)
            painter.drawText(badge, QtCore.Qt.AlignmentFlag.AlignCenter, label_text)
            painter.restore()

        pill_font = QtGui.QFont(font)
        pill_font.setPointSize(max(8, font.pointSize() - 1))
        pill_font.setBold(True)
        metrics = QtGui.QFontMetrics(pill_font)
        pill_w = max(26, metrics.horizontalAdvance(str(original_num)) + 14)
        pill_h = 22
        pill_rect = QtCore.QRect(
            card.right() - 8 - pill_w,
            label_rect.center().y() - pill_h // 2,
            pill_w,
            pill_h,
        )

        painter.setFont(pill_font)
        painter.setPen(QtCore.Qt.PenStyle.NoPen)
        painter.setBrush(QtGui.QBrush(QtGui.QColor("#0a3a5c")))
        painter.drawRoundedRect(pill_rect, 11, 11)
        painter.setPen(QtGui.QColor("#4a9eff"))
        painter.drawText(
            pill_rect,
            QtCore.Qt.AlignmentFlag.AlignCenter,
            str(original_num),
        )

        painter.restore()


class ThumbnailGrid(_SingleClickDeselectMixin, QtWidgets.QListWidget):
    orderChanged = QtCore.Signal()
    externalFilesDropped = QtCore.Signal(list)
    dragHistoryAboutToChange = QtCore.Signal()
    dragHistoryFinished = QtCore.Signal()

    # Cell geometry is calculated from the available width, the chosen number
    # of thumbnails per row, and the PDF's dominant page aspect ratio.
    _MIN_CELL_W = 72
    _LABEL_H = 38
    _INNER_X = 6
    _INNER_TOP = 5
    _INNER_BOTTOM = 5

    def __init__(self, parent=None):
        super().__init__(parent)

        self._items_per_row = 5
        self._thumb_aspect_ratio = 1.0
        self._image_width = 120
        self._image_height = 120
        self._item_size = QtCore.QSize(120, self._LABEL_H + 10 + 120)
        self._grid_size = QtCore.QSize(120, self._LABEL_H + 10 + 120)

        self.setContentsMargins(0, 0, 0, 0)
        self.setViewMode(QtWidgets.QListView.ViewMode.IconMode)
        self.setFlow(QtWidgets.QListView.Flow.LeftToRight)
        self.setWrapping(True)
        self.setResizeMode(QtWidgets.QListView.ResizeMode.Adjust)
        self.setMovement(QtWidgets.QListView.Movement.Static)
        self.setUniformItemSizes(False)
        self.setIconSize(QtCore.QSize(self._image_width, self._image_height))
        self.setGridSize(self._grid_size)
        self.setSpacing(0)
        self.setWordWrap(False)
        self.setVerticalScrollMode(QtWidgets.QAbstractItemView.ScrollMode.ScrollPerPixel)
        self._wheel_angle_delta = 0

        self._grid_delegate = _ThumbnailGridDelegate(self)
        self.setItemDelegate(self._grid_delegate)

        self.setDragEnabled(True)
        self.setAcceptDrops(True)
        self.viewport().setAcceptDrops(True)
        self.setDropIndicatorShown(False)
        self.setDragDropMode(QtWidgets.QAbstractItemView.DragDropMode.DragDrop)
        self.setDefaultDropAction(QtCore.Qt.DropAction.MoveAction)
        self.setSelectionMode(QtWidgets.QAbstractItemView.SelectionMode.SingleSelection)

        self._drag_src_uid = None
        self._drag_src_file_idx = -1
        self._placeholder_row = -1
        # Stable UID of the last item the user navigated to/selected. This lets
        # keyboard navigation collapse a multi-selection from its active anchor.
        self._navigation_anchor_uid = None
        self._recalculating_geometry = False
        self._last_geometry_key = None
        self._grid_safety_reserve = 4
        self._grid_verify_pending = False
        self._grid_verify_attempts = 0

        # The viewport width can change when the vertical scrollbar appears/disappears
        # after changing the density. Listen to the real viewport resize so geometry
        # is never based on the previous width.
        self.viewport().installEventFilter(self)
        self.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)

        self._autoscroll_margin = 60
        self._autoscroll_max_speed = 8
        self._autoscroll_min_speed = 2
        self._autoscroll_direction = 0
        self._autoscroll_speed = 0.0
        self._last_drag_pos = None
        self._autoscroll_timer = QtCore.QTimer(self)
        self._autoscroll_timer.setInterval(16)
        self._autoscroll_timer.timeout.connect(self._autoscroll_step)

        self._install_deselect_behavior()
        self.currentItemChanged.connect(self._on_navigation_current_item_changed)

        # Centered guidance shown only while the live grid has no pages.  It is
        # transparent to mouse/drop events, so it never interferes with importing.
        self._empty_grid_tip = QtWidgets.QLabel(self.viewport())
        self._empty_grid_tip.setText(
            "Drag and drop PDF or image files here, or use Add PDF/Image as pages.")
        self._empty_grid_tip.setAlignment(
            QtCore.Qt.AlignmentFlag.AlignCenter | QtCore.Qt.AlignmentFlag.AlignVCenter)
        self._empty_grid_tip.setWordWrap(True)
        self._empty_grid_tip.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self._empty_grid_tip.setStyleSheet(
            "color:#777; font-size:11pt; font-weight:600; "
            "background:transparent; padding:24px;")
        self._empty_grid_tip.show()
        QtCore.QTimer.singleShot(0, self._update_empty_grid_tip)

        # The delegate paints the entire card itself. Do not style
        # QListWidget::item here: QSS item borders/padding can participate in
        # Qt's item-size calculations and make an otherwise exact N-column
        # layout wrap early by a few pixels (which becomes a huge empty area).
        self.setStyleSheet("""
            QListWidget {
                background-color: #1a1a1a;
                border: 1px solid #3a3a3a;
                border-radius: 8px;
                padding: 0px;
            }
        """)
        QtCore.QTimer.singleShot(0, self._recalculate_grid_geometry)

    def _update_empty_grid_tip(self):
        try:
            viewport = self.viewport()
            rect = viewport.rect().adjusted(26, 26, -26, -26)
            self._empty_grid_tip.setGeometry(rect)
            self._empty_grid_tip.setVisible(self.count() == 0)
            self._empty_grid_tip.raise_()
        except Exception:
            pass

    def _schedule_empty_grid_tip_update(self):
        QtCore.QTimer.singleShot(0, self._update_empty_grid_tip)

    def addItem(self, item):
        super().addItem(item)
        self._schedule_empty_grid_tip_update()

    def insertItem(self, row, item):
        super().insertItem(row, item)
        self._schedule_empty_grid_tip_update()

    def takeItem(self, row):
        item = super().takeItem(row)
        self._schedule_empty_grid_tip_update()
        return item

    def clear(self):
        super().clear()
        self._schedule_empty_grid_tip_update()

    def wheelEvent(self, event):
        # Keep wheel movement predictable in a tall page grid: one standard
        # notch reveals one adjacent row instead of Qt's multi-item jump.
        if event.modifiers() & (QtCore.Qt.KeyboardModifier.ControlModifier | QtCore.Qt.KeyboardModifier.ShiftModifier):
            super().wheelEvent(event)
            return

        row_step = max(1, int(self._grid_size.height()))
        pixel_delta = int(event.pixelDelta().y())
        if pixel_delta:
            # Native/high-resolution scrolling remains smooth, but one event
            # cannot leap over an entire additional row.
            movement = max(-row_step, min(row_step, -pixel_delta))
        else:
            angle_delta = int(event.angleDelta().y())
            if not angle_delta:
                super().wheelEvent(event)
                return
            self._wheel_angle_delta += angle_delta
            notches = int(self._wheel_angle_delta / 120)
            self._wheel_angle_delta -= notches * 120
            if notches == 0:
                event.accept()
                return
            movement = -notches * row_step

        bar = self.verticalScrollBar()
        target = max(bar.minimum(), min(bar.maximum(), bar.value() + movement))
        if target != bar.value():
            bar.setValue(target)
        event.accept()

    def items_per_row(self):
        return int(self._items_per_row)

    def set_items_per_row(self, value):
        value = max(1, min(10, int(value)))
        if value != self._items_per_row:
            self._grid_safety_reserve = 4
            self._grid_verify_attempts = 0
        self._items_per_row = value
        self._recalculate_grid_geometry()

    def set_page_aspect_ratio(self, aspect_ratio):
        try:
            ratio = float(aspect_ratio)
        except Exception:
            ratio = 1.0
        if not math.isfinite(ratio) or ratio <= 0:
            ratio = 1.0
        self._thumb_aspect_ratio = max(0.08, min(12.0, ratio))
        self._grid_safety_reserve = 4
        self._grid_verify_attempts = 0
        self._recalculate_grid_geometry()

    def page_aspect_ratio(self):
        return float(self._thumb_aspect_ratio)

    def _recalculate_grid_geometry(self):
        if self._recalculating_geometry:
            return
        self._recalculating_geometry = True
        try:
            viewport_width = max(1, int(self.viewport().rect().width()))
            n = max(1, min(10, int(self._items_per_row)))
            ratio_key = round(float(self._thumb_aspect_ratio), 6)

            # Reserve only a tiny, deliberate amount of outer breathing room.
            # Qt's IconMode flow has a few style/rounding boundaries of its own;
            # giving it a tiny integer-safe reserve prevents a mathematically
            # exact boundary from turning N columns into N-1. The reserve is
            # deliberately constant and tiny, not a per-column gap.
            outer_reserve = min(24, max(0, viewport_width - 1), int(self._grid_safety_reserve))
            usable_width = max(n, viewport_width - outer_reserve)
            cell_width = max(1, usable_width // n)

            # The visible card gets its visual gaps from the delegate's paint
            # inset. QListView itself sees exactly one cell width and no QSS item
            # border/padding, so its flow calculation and painted geometry agree.
            card_width = max(1, cell_width - 2 * 3)
            inner_x = min(self._INNER_X, max(0, (card_width - 2) // 2))
            image_width = max(1, card_width - 2 * inner_x)
            image_height = max(1, int(round(image_width / self._thumb_aspect_ratio)))
            cell_height = (self._INNER_TOP + image_height +
                           self._LABEL_H + self._INNER_BOTTOM)

            # The delegate sizeHint and QListView gridSize are deliberately
            # identical. The actual painted card remains slightly inset, so
            # adjacent cards retain the intended small visual gap while every
            # row still consumes the complete available horizontal span.
            new_grid_size = QtCore.QSize(cell_width, cell_height)
            new_item_size = QtCore.QSize(cell_width, cell_height)
            geometry_key = (viewport_width, n, ratio_key, outer_reserve, usable_width, cell_width, card_width)
            changed = (geometry_key != self._last_geometry_key
                       or new_item_size != self._item_size
                       or image_width != self._image_width
                       or image_height != self._image_height)

            self._item_size = new_item_size
            self._grid_size = new_grid_size
            self._image_width = image_width
            self._image_height = image_height
            self._last_geometry_key = geometry_key

            if changed:
                self.setIconSize(QtCore.QSize(image_width, image_height))
                self.setGridSize(self._grid_size)

                # Explicitly invalidate the item-size/layout cache. This is
                # important because the item size changes when the window or
                # thumbnails-per-row value changes.
                try:
                    self.updateGeometries()
                except Exception:
                    pass
                self.doItemsLayout()
                self.viewport().update()

                # Qt's IconMode layout has a hard wrap boundary. Verify the
                # actual visual row after Qt has laid out the items; if the
                # requested number of columns wrapped early, add only a tiny
                # amount to the adaptive outer reserve and retry. This is a
                # feedback check against Qt's real geometry rather than a
                # guess about hidden style/rounding overhead.
                if self.count() >= n and not self._grid_verify_pending:
                    self._grid_verify_pending = True
                    QtCore.QTimer.singleShot(0, self._verify_column_fit)
        finally:
            self._recalculating_geometry = False

    def _finalize_population_layout(self):
        """Reflow the grid after the final item count is known.

        During thumbnail generation the grid can be empty while its page aspect
        ratio is established.  In SP mode especially, the vertical scrollbar and
        the real viewport width are not necessarily settled until the thumbnails
        have actually been inserted.  A final reflow after population makes the
        requested column count depend on the *final* viewport geometry, not the
        temporary geometry from before population.

        The second queued pass is intentional: it lets Qt finish any posted
        scrollbar/layout changes triggered by the item insertion before the
        feedback verifier makes its final decision.
        """
        if self._recalculating_geometry:
            QtCore.QTimer.singleShot(0, self._finalize_population_layout)
            return

        self._grid_safety_reserve = 4
        self._grid_verify_attempts = 0
        self._grid_verify_pending = False
        self._last_geometry_key = None
        self._recalculate_grid_geometry()
        self.updateGeometries()
        self.doItemsLayout()
        self.viewport().update()

        def second_pass():
            if self._recalculating_geometry:
                QtCore.QTimer.singleShot(0, second_pass)
                return
            # Re-read the now-settled viewport width (including a newly visible
            # vertical scrollbar), then let _verify_column_fit validate the real
            # first row rather than the pre-population estimate.
            self._last_geometry_key = None
            self._recalculate_grid_geometry()
            self.updateGeometries()
            self.doItemsLayout()
            self.viewport().update()

        QtCore.QTimer.singleShot(0, second_pass)
        # A short delayed pass covers platforms/styles that only finalize the
        # scrollbar after one additional event-loop turn. It is tiny and only
        # changes geometry, never re-renders thumbnails.
        QtCore.QTimer.singleShot(40, second_pass)


    def _verify_column_fit(self):
        self._grid_verify_pending = False
        try:
            target = max(1, min(10, int(self._items_per_row)))
            if self.count() < target or target <= 1:
                self._grid_verify_attempts = 0
                return

            first_index = self.model().index(0, 0)
            target_index = self.model().index(target - 1, 0)
            first_rect = self.visualRect(first_index)
            target_rect = self.visualRect(target_index)
            if not first_rect.isValid() or not target_rect.isValid():
                return

            same_row = abs(int(target_rect.top()) - int(first_rect.top())) <= 1
            if same_row:
                self._grid_verify_attempts = 0
                return

            # The requested column count wrapped. Increase the outer reserve
            # by only 2 px at a time, up to 24 px total. This keeps the normal
            # layout essentially full-width while giving Qt enough safety room
            # to absorb its internal integer/style boundary.
            if self._grid_verify_attempts >= 10 or self._grid_safety_reserve >= 24:
                self._grid_verify_attempts = 0
                return

            previous = int(self._grid_safety_reserve)
            self._grid_safety_reserve = min(24, previous + 2)
            self._grid_verify_attempts += 1
            self._recalculate_grid_geometry()
        except Exception:
            self._grid_verify_attempts = 0

    def eventFilter(self, obj, event):
        if obj is self.viewport() and event.type() == QtCore.QEvent.Type.Resize:
            result = super().eventFilter(obj, event)
            QtCore.QTimer.singleShot(0, self._recalculate_grid_geometry)
            return result
        return super().eventFilter(obj, event)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._recalculate_grid_geometry()
        self._update_empty_grid_tip()

    def showEvent(self, event):
        super().showEvent(event)
        self._update_empty_grid_tip()
        self._grid_safety_reserve = 4
        self._grid_verify_attempts = 0
        QtCore.QTimer.singleShot(0, self._recalculate_grid_geometry)

    def updateGeometries(self):
        # Geometry recalculation is driven by resize/layout events and explicitly
        # invalidated by _recalculate_grid_geometry(). Do not enqueue another
        # recalculation from inside updateGeometries(), which can otherwise create
        # a resize/layout feedback loop.
        super().updateGeometries()

    def _remember_navigation_anchor(self, item):
        if item is None:
            return
        try:
            data = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
            uid = data.get('uid') if isinstance(data, dict) else None
            if uid is not None:
                self._navigation_anchor_uid = uid
        except Exception:
            pass

    def _on_navigation_current_item_changed(self, current, _previous=None):
        self._remember_navigation_anchor(current)

    def _is_navigable_item(self, item):
        if item is None:
            return False
        try:
            return bool(item.flags() & QtCore.Qt.ItemFlag.ItemIsSelectable)
        except Exception:
            return False

    def _navigation_origin_item(self):
        selected = [item for item in self.selectedItems()
                    if self._is_navigable_item(item)]
        current = self.currentItem()
        if len(selected) > 1:
            # Prefer the most recently user-selected item when it is part of the
            # multi-selection; currentItem is the next-best Qt-maintained anchor.
            for item in selected:
                data = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
                if isinstance(data, dict) and data.get('uid') == self._navigation_anchor_uid:
                    return item
            current_row = self.row(current) if current is not None else -1
            for item in selected:
                if self.row(item) == current_row and current_row >= 0:
                    return item
            return selected[-1]
        if selected:
            return selected[0]
        if self._is_navigable_item(current):
            return current
        for row in range(self.count()):
            item = self.item(row)
            if self._is_navigable_item(item):
                return item
        return None

    def _grid_navigation_rows(self):
        rows = []
        for row_index in range(self.count()):
            item = self.item(row_index)
            if not self._is_navigable_item(item):
                continue
            rect = self.visualItemRect(item)
            if not rect.isValid() or rect.isNull():
                continue
            top = int(rect.top())
            group = next((g for g in rows if abs(g['top'] - top) <= 2), None)
            if group is None:
                group = {'top': top, 'items': []}
                rows.append(group)
            group['items'].append((item, rect))
        rows.sort(key=lambda g: g['top'])
        for group in rows:
            group['items'].sort(key=lambda pair: int(pair[1].center().x()))
        return rows

    def _grid_neighbor(self, origin, key):
        rows = self._grid_navigation_rows()
        if not rows:
            return None
        origin_rect = self.visualItemRect(origin)
        if not origin_rect.isValid() or origin_rect.isNull():
            return None
        origin_top = int(origin_rect.top())
        origin_x = float(origin_rect.center().x())
        origin_row = self.row(origin)
        origin_group = next(
            (g for g in rows if any(self.row(item) == origin_row
                                    for item, _rect in g['items'])),
            None)
        if origin_group is None:
            return None

        if key in (QtCore.Qt.Key.Key_Left, QtCore.Qt.Key.Key_Right):
            direction = -1 if key == QtCore.Qt.Key.Key_Left else 1
            candidates = [
                (item, rect) for item, rect in origin_group['items']
                if self.row(item) != origin_row
                and (float(rect.center().x()) - origin_x) * direction > 0
            ]
            if not candidates:
                return None
            return min(candidates, key=lambda pair: abs(
                float(pair[1].center().x()) - origin_x))[0]

        if key == QtCore.Qt.Key.Key_Up:
            adjacent_rows = [g for g in rows if g['top'] < origin_top - 2]
            target_group = max(adjacent_rows, key=lambda g: g['top']) if adjacent_rows else None
        else:
            adjacent_rows = [g for g in rows if g['top'] > origin_top + 2]
            target_group = min(adjacent_rows, key=lambda g: g['top']) if adjacent_rows else None
        if target_group is None or not target_group['items']:
            return None
        return min(target_group['items'], key=lambda pair: (
            abs(float(pair[1].center().x()) - origin_x),
            float(pair[1].center().x())))[0]

    def select_rows_exclusively(self, first_row, end_row):
        """Select the real items in [first_row, end_row), clearing old selections."""
        first = max(0, int(first_row))
        end = min(self.count(), max(first, int(end_row)))
        old_mode = self.selectionMode()
        selected_items = []
        self.blockSignals(True)
        try:
            # Added PDFs may contain many pages even when interactive multi-select
            # is off. Temporarily enable it for this intentional batch selection.
            self.setSelectionMode(QtWidgets.QAbstractItemView.SelectionMode.MultiSelection)
            self.clearSelection()
            for row in range(first, end):
                item = self.item(row)
                if self._is_navigable_item(item):
                    item.setSelected(True)
                    selected_items.append(item)
            if selected_items:
                last_item = selected_items[-1]
                self.setCurrentItem(last_item, QtCore.QItemSelectionModel.SelectionFlag.NoUpdate)
                self._remember_navigation_anchor(last_item)
        finally:
            self.setSelectionMode(old_mode)
            self.blockSignals(False)
        self.viewport().update()
        # Programmatic selection (initial load, imports, and paste) does not
        # automatically transfer keyboard focus to the grid. Keep the grid
        # focused so arrow navigation works immediately from these selections.
        if selected_items:
            self.setFocus(QtCore.Qt.FocusReason.OtherFocusReason)
        return len(selected_items)

    def keyPressEvent(self, event):
        key = event.key()
        arrow_keys = {
            QtCore.Qt.Key.Key_Left, QtCore.Qt.Key.Key_Right,
            QtCore.Qt.Key.Key_Up, QtCore.Qt.Key.Key_Down,
        }
        navigation_modifiers = (QtCore.Qt.KeyboardModifier.ControlModifier | QtCore.Qt.KeyboardModifier.ShiftModifier |
                                QtCore.Qt.KeyboardModifier.AltModifier | QtCore.Qt.KeyboardModifier.MetaModifier)
        if key in arrow_keys and not (event.modifiers() & navigation_modifiers):
            origin = self._navigation_origin_item()
            if origin is not None:
                target = self._grid_neighbor(origin, key)
                # At an edge, keep the anchor but still collapse a multi-selection.
                if target is None:
                    target = origin
                self.setCurrentItem(
                    target, QtCore.QItemSelectionModel.SelectionFlag.ClearAndSelect)
                self._remember_navigation_anchor(target)
                self.scrollToItem(target, QtWidgets.QAbstractItemView.ScrollHint.EnsureVisible)
                event.accept()
                return
        super().keyPressEvent(event)

    def mousePressEvent(self, event):
        if event.button() == QtCore.Qt.MouseButton.RightButton:
            item = self.itemAt(_qt_event_position(event))
            if item is not None and item.isSelected():
                event.accept()
                return
        clicked_item = self.itemAt(_qt_event_position(event))
        self._handle_deselect_press(event)
        super().mousePressEvent(event)
        if clicked_item is not None and clicked_item.isSelected():
            self._remember_navigation_anchor(clicked_item)

    def mouseDoubleClickEvent(self, event):
        self._click_deselect_item = None
        self._click_deselect_timer.stop()
        super().mouseDoubleClickEvent(event)

    def startDrag(self, supportedActions):
        item = self.currentItem()
        if item is None:
            return
        data = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
        self._drag_src_uid = data.get('uid')
        self._drag_src_file_idx = self.row(item)

        drag = QtGui.QDrag(self)
        mime = QtCore.QMimeData()
        mime.setText(_THUMB_MIME_TEXT)
        drag.setMimeData(mime)

        icon = item.icon()
        if not icon.isNull():
            pix = icon.pixmap(120, 120)
            drag.setPixmap(pix)
            drag.setHotSpot(QtCore.QPoint(pix.width() // 2, pix.height() // 2))
        else:
            drag.setPixmap(QtGui.QPixmap(1, 1))

        self.dragHistoryAboutToChange.emit()
        try:
            drag.exec(QtCore.Qt.DropAction.MoveAction)
        finally:
            self.dragHistoryFinished.emit()

        self._drag_src_uid = None
        self._drag_src_file_idx = -1
        self._stop_autoscroll()
        self._remove_placeholder()

    def _accepts_drag(self, event):
        md = event.mimeData()
        return md is not None and md.hasText() and md.text() == _THUMB_MIME_TEXT

    def dragEnterEvent(self, event):
        md = event.mimeData()
        if md is not None and md.hasUrls():
            pdfs = _pdf_or_image_paths_from_urls(md.urls())
            if pdfs:
                event.setDropAction(QtCore.Qt.DropAction.CopyAction)
                event.accept()
                return
        if self._accepts_drag(event):
            event.setDropAction(QtCore.Qt.DropAction.MoveAction)
            event.accept()
        else:
            event.ignore()

    def dragMoveEvent(self, event):
        md = event.mimeData()
        if md is not None and md.hasUrls():
            pdfs = _pdf_or_image_paths_from_urls(md.urls())
            if pdfs:
                event.setDropAction(QtCore.Qt.DropAction.CopyAction)
                event.accept()
                return
            event.ignore()
            return
        if not self._accepts_drag(event):
            event.ignore()
            return
        viewport_pos = self.viewport().mapFrom(self, _qt_event_position(event))
        self._last_drag_pos = viewport_pos
        self._update_autoscroll(viewport_pos)
        new_ph = self._compute_drop_index(viewport_pos)
        src_idx = self._drag_src_file_idx
        no_op = (src_idx >= 0 and (new_ph == src_idx or new_ph == src_idx + 1))
        if no_op:
            if self._placeholder_row >= 0:
                self._remove_placeholder()
        elif new_ph != self._placeholder_row:
            self._remove_placeholder()
            self._insert_placeholder_at(new_ph)
        event.setDropAction(QtCore.Qt.DropAction.MoveAction)
        event.accept()

    def dragLeaveEvent(self, event):
        self._stop_autoscroll()
        self._remove_placeholder()
        super().dragLeaveEvent(event)

    def dropEvent(self, event):
        md = event.mimeData()
        if md is not None and md.hasUrls():
            addable_paths = _pdf_or_image_paths_from_urls(md.urls())
            if addable_paths:
                event.setDropAction(QtCore.Qt.DropAction.CopyAction)
                event.accept()
                self.externalFilesDropped.emit(addable_paths)
                return
            event.ignore()
            return
        if not self._accepts_drag(event):
            event.ignore()
            return

        src_uid = self._drag_src_uid
        ph = self._placeholder_row

        self._stop_autoscroll()
        self._remove_placeholder()

        if src_uid is None or ph < 0:
            event.setDropAction(QtCore.Qt.DropAction.MoveAction)
            event.accept()
            return

        src_row = -1
        for r in range(self.count()):
            item = self.item(r)
            if item is None:
                continue
            d = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
            if d.get('uid') == src_uid:
                src_row = r
                break

        if src_row < 0:
            event.setDropAction(QtCore.Qt.DropAction.MoveAction)
            event.accept()
            return

        dst = ph if ph <= src_row else ph - 1
        if dst == src_row:
            event.setDropAction(QtCore.Qt.DropAction.MoveAction)
            event.accept()
            return

        taken = self.takeItem(src_row)
        self.insertItem(dst, taken)
        self.setCurrentItem(taken)
        self.orderChanged.emit()
        event.setDropAction(QtCore.Qt.DropAction.MoveAction)
        event.accept()

    def _stop_autoscroll(self):
        try:
            self._autoscroll_timer.stop()
        except Exception:
            pass
        self._autoscroll_direction = 0
        self._autoscroll_speed = 0.0
        self._last_drag_pos = None

    def _update_autoscroll(self, pos):
        margin = self._autoscroll_margin
        h = self.viewport().height()
        y = pos.y()
        scrollbar = self.verticalScrollBar()
        direction = 0
        intensity = 0.0
        if y < margin and scrollbar.value() > scrollbar.minimum():
            direction = -1
            intensity = min(1.0, max(0.0, (margin - y) / float(margin)))
        elif y > h - margin and scrollbar.value() < scrollbar.maximum():
            direction = 1
            intensity = min(1.0, max(0.0, (y - (h - margin)) / float(margin)))
        self._autoscroll_direction = direction
        self._autoscroll_speed = (self._autoscroll_min_speed +
            (self._autoscroll_max_speed - self._autoscroll_min_speed)
            * (intensity ** 2))
        if direction != 0:
            if not self._autoscroll_timer.isActive():
                self._autoscroll_timer.start()
        else:
            self._autoscroll_timer.stop()

    def _autoscroll_step(self):
        if self._autoscroll_direction == 0 or self._autoscroll_speed <= 0:
            self._autoscroll_timer.stop()
            return
        scrollbar = self.verticalScrollBar()
        current = scrollbar.value()
        step = int(round(self._autoscroll_speed))
        if step < 1:
            step = 1
        target = current + self._autoscroll_direction * step
        target = max(scrollbar.minimum(), min(scrollbar.maximum(), target))
        if target == current:
            self._autoscroll_timer.stop()
            return
        scrollbar.setValue(target)
        if self._last_drag_pos is not None:
            new_ph = self._compute_drop_index(self._last_drag_pos)
            src_idx = self._drag_src_file_idx
            no_op = (src_idx >= 0 and
                     (new_ph == src_idx or new_ph == src_idx + 1))
            if no_op:
                if self._placeholder_row >= 0:
                    self._remove_placeholder()
            elif new_ph != self._placeholder_row:
                self._remove_placeholder()
                self._insert_placeholder_at(new_ph)

    def _compute_drop_index(self, viewport_pos):
        """Return the logical insertion slot for an internal page drag.

        The previous implementation reconstructed the hovered item by scanning
        every item's rectangle. That becomes unreliable after IconMode relayout,
        especially when the pointer is over the final cell of a partially filled
        row. Qt already knows which index is under the cursor, so use indexAt() as
        the authoritative hit test. Only use geometry-based inference when the
        pointer is actually in a gap between cells.
        """
        ph = self._placeholder_row
        count = self.count()
        if count == 0:
            return 0

        real_count = count - (1 if ph >= 0 else 0)
        x = int(viewport_pos.x())
        y = int(viewport_pos.y())

        def logical_index(row):
            if ph >= 0 and row > ph:
                return row - 1
            return row

        # --------------------------------------------------------
        # 1) Direct hit test: trust Qt's own itemAt/indexAt result.
        #    This is the critical fix for last-item-of-row drags.
        # --------------------------------------------------------
        try:
            idx = self.indexAt(QtCore.QPoint(x, y))
            if idx.isValid():
                row = int(idx.row())
                if row != ph:
                    item = self.item(row)
                    if item is not None:
                        rect = self.visualItemRect(item)
                        if rect.isValid() and not rect.isNull():
                            logical = logical_index(row)
                            # Left half = insert before this exact target.
                            # Right half = insert after this exact target.
                            if x < int(rect.center().x()):
                                return max(0, min(real_count, logical))
                            return max(0, min(real_count, logical + 1))
        except Exception:
            pass

        # --------------------------------------------------------
        # 2) Pointer is in a gap rather than directly over an item.
        #    Group real items into visual rows and determine the nearest
        #    insertion slot inside that row. This fallback is spatially
        #    ordered, unlike the old global nearest-item scan.
        # --------------------------------------------------------
        rows = []
        for row in range(count):
            if row == ph:
                continue
            item = self.item(row)
            if item is None:
                continue
            rect = self.visualItemRect(item)
            if not (rect.isValid() and not rect.isNull()):
                continue
            logical = logical_index(row)

            # Find an existing visual row by top coordinate. QListWidget's
            # IconMode layout uses equal top values for cells in one row.
            matched = None
            for group in rows:
                if abs(int(group['top']) - int(rect.top())) <= 1:
                    matched = group
                    break
            if matched is None:
                matched = {'top': int(rect.top()), 'items': []}
                rows.append(matched)
            matched['items'].append((logical, rect))

        if not rows:
            return real_count

        for group in rows:
            group['items'].sort(key=lambda item: int(item[1].left()))
            group['center_y'] = sum(
                int(rect.center().y()) for _, rect in group['items']) / len(group['items'])

        # Select the visually nearest row.
        row_group = min(rows, key=lambda g: abs(float(g['center_y']) - y))
        row_items = row_group['items']

        first_logical, first_rect = row_items[0]
        if x < int(first_rect.center().x()):
            return max(0, min(real_count, first_logical))

        for pos in range(len(row_items) - 1):
            left_logical, left_rect = row_items[pos]
            right_logical, right_rect = row_items[pos + 1]
            boundary = (int(left_rect.center().x()) +
                        int(right_rect.center().x())) // 2
            if x < boundary:
                return max(0, min(real_count, left_logical + 1))

        last_logical, last_rect = row_items[-1]
        return max(0, min(real_count, last_logical + 1))

    def _insert_placeholder_at(self, row):
        row = max(0, min(row, self.count()))

        item = QtWidgets.QListWidgetItem()
        item.setFlags(QtCore.Qt.ItemFlag.NoItemFlags)
        item.setSizeHint(QtCore.QSize(self._item_size))
        item.setData(_PLACEHOLDER_ROLE, True)

        self.insertItem(row, item)
        self._placeholder_row = row

    def _remove_placeholder(self):
        if self._placeholder_row < 0:
            return
        if 0 <= self._placeholder_row < self.count():
            self.takeItem(self._placeholder_row)
        self._placeholder_row = -1


# ============================================================
# ENTER-AWARE LINE EDIT
# ============================================================
class _EnterSubmitLineEdit(QtWidgets.QLineEdit):
    """Consume Enter/Return so it cannot fall through to a dialog button."""
    enterPressed = QtCore.Signal()

    def keyPressEvent(self, event):
        if event.key() in (QtCore.Qt.Key.Key_Return, QtCore.Qt.Key.Key_Enter):
            self.enterPressed.emit()
            event.accept()
            return
        super().keyPressEvent(event)


# ============================================================
# FIND BOX
# ============================================================
class _FindBox(QtWidgets.QFrame):
    searchRequested = QtCore.Signal(str)
    nextRequested = QtCore.Signal()
    prevRequested = QtCore.Signal()
    closeRequested = QtCore.Signal()

    _DEBOUNCE_MS = 260

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setObjectName("_mergerz_findbox")
        self.setAttribute(QtCore.Qt.WidgetAttribute.WA_StyledBackground, True)
        self.setStyleSheet("""
            QFrame#_mergerz_findbox {
                background-color: #2b2b2b;
                border: 1px solid #4a4a4a;
                border-radius: 8px;
            }
        """)
        self.setFixedWidth(340)

        outer = QtWidgets.QVBoxLayout(self)
        outer.setContentsMargins(10, 8, 10, 8)
        outer.setSpacing(6)

        row1 = QtWidgets.QHBoxLayout()
        row1.setSpacing(6)

        self.input = _EnterSubmitLineEdit()
        self.input.setPlaceholderText("Search here...")
        self.input.setStyleSheet("""
            QLineEdit {
                background-color: #1e1e1e; color: #f0f0f0;
                border: 1px solid #3a3a3a; border-radius: 5px;
                padding: 5px 8px; font-size: 10pt;
            }
            QLineEdit:focus { border-color: #0078d7; }
        """)
        row1.addWidget(self.input, stretch=1)

        nav_style = """
            QPushButton {
                background-color: #2a2a2a; border: 1px solid #3a3a3a;
                border-radius: 5px;
            }
            QPushButton:hover { background-color: #3a3a3a; }
            QPushButton:disabled {
                background-color: #1e1e1e; border-color: #262626;
            }
        """

        self.prev_btn = QtWidgets.QPushButton()
        self.prev_btn.setFixedSize(30, 30)
        self.prev_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.prev_btn.setToolTip("Previous match")
        self.prev_btn.setStyleSheet(nav_style)
        ic = _render_svg_icon(os.path.join(ICONS_FOLDER, "chev-up.svg"), 16)
        if ic is not None:
            self.prev_btn.setIcon(ic)
            self.prev_btn.setIconSize(QtCore.QSize(16, 16))
        else:
            self.prev_btn.setText("↑")
        self.prev_btn.clicked.connect(self.prevRequested.emit)
        row1.addWidget(self.prev_btn)

        self.next_btn = QtWidgets.QPushButton()
        self.next_btn.setFixedSize(30, 30)
        self.next_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.next_btn.setToolTip("Next match")
        self.next_btn.setStyleSheet(nav_style)
        ic = _render_svg_icon(os.path.join(ICONS_FOLDER, "chev-down.svg"), 16)
        if ic is not None:
            self.next_btn.setIcon(ic)
            self.next_btn.setIconSize(QtCore.QSize(16, 16))
        else:
            self.next_btn.setText("↓")
        self.next_btn.clicked.connect(self.nextRequested.emit)
        row1.addWidget(self.next_btn)

        outer.addLayout(row1)

        self.status_lbl = QtWidgets.QLabel("Type to search")
        self.status_lbl.setStyleSheet(
            "color: #9a9a9a; font-size: 9pt; background: transparent; "
            "border: none;")
        outer.addWidget(self.status_lbl)

        self._debounce = QtCore.QTimer(self)
        self._debounce.setSingleShot(True)
        self._debounce.setInterval(self._DEBOUNCE_MS)
        self._debounce.timeout.connect(self._emit_search)

        self._suppress = False

        self.input.textChanged.connect(self._on_text_changed)
        self.input.enterPressed.connect(self._on_enter_pressed)

        self.set_nav_enabled(False, False)

    def _on_text_changed(self, text):
        if self._suppress:
            return
        self._debounce.stop()
        if not text.strip():
            self.searchRequested.emit("")
            return
        self._debounce.start()

    def _emit_search(self):
        if not self.isVisible():
            return
        text = self.input.text().strip()
        self.searchRequested.emit(text)

    def _on_enter_pressed(self):
        """Enter searches a changed query or advances to the next match."""
        text = self.input.text().strip()
        if not text:
            return
        if self._debounce.isActive():
            self._debounce.stop()
            self._emit_search()
            return
        if self.next_btn.isEnabled():
            self.nextRequested.emit()

    def set_status(self, text):
        self.status_lbl.setText(text)

    def set_nav_enabled(self, prev_enabled, next_enabled):
        self.prev_btn.setEnabled(bool(prev_enabled))
        self.next_btn.setEnabled(bool(next_enabled))

    def reset(self):
        self._debounce.stop()
        self._suppress = True
        self.input.clear()
        self._suppress = False
        self.set_status("Type to search")
        self.set_nav_enabled(False, False)

    def showEvent(self, event):
        super().showEvent(event)
        self.input.setFocus()
        self.input.selectAll()

    def keyPressEvent(self, event):
        if event.key() == QtCore.Qt.Key.Key_Escape:
            self.closeRequested.emit()
            return
        super().keyPressEvent(event)


class _SearchWorker(QtCore.QObject):
    finished = QtCore.Signal(str, list)

    def __init__(self, pdf_path):
        super().__init__()
        self._pdf_path = pdf_path
        self._stop_requested = False

    @QtCore.Slot(str)
    def do_search(self, query):
        self._stop_requested = False
        results = []
        try:
            with fitz.open(self._pdf_path) as doc:
                for i in range(doc.page_count):
                    if self._stop_requested:
                        break
                    try:
                        page = doc.load_page(i)
                        rects = page.search_for(query)
                        for r in rects:
                            results.append((i, float(r.x0), float(r.y0),
                                            float(r.x1), float(r.y1)))
                    except Exception:
                        pass
        except Exception:
            pass
        if self._stop_requested:
            return
        self.finished.emit(query, results)


class _SearchBridge(QtCore.QObject):
    trigger = QtCore.Signal(str)


def _open_external_pdf_link(uri):
    """Open a PDF web URI with the operating system's external URL handler."""
    try:
        value = str(uri or "").strip()
        if not value:
            return False
        url = QtCore.QUrl(value)
        if not url.isValid() or url.isRelative():
            return False
        if url.scheme().strip().lower() not in {"http", "https"}:
            return False
        return bool(QtGui.QDesktopServices.openUrl(url))
    except Exception:
        return False


# ============================================================
# LIGHTWEIGHT PAGE VIEWER
# ============================================================
def _selection_line_highlight_rects(words, selection_rect):
    """Build continuous visual highlight strips while preserving word-based selection semantics."""
    try:
        sr = selection_rect.normalized()
    except Exception:
        return []
    selected = []
    for word in words or []:
        try:
            x0, y0, x1, y1 = [float(v) for v in word[:4]]
            rect = QtCore.QRectF(x0, y0, x1 - x0, y1 - y0).normalized()
            if not rect.isEmpty() and sr.intersects(rect):
                selected.append(rect)
        except Exception:
            continue
    if not selected:
        return []
    selected.sort(key=lambda r: (r.center().y(), r.left()))
    groups = []
    for rect in selected:
        h = max(1.0, rect.height())
        cy = rect.center().y()
        best = None
        best_delta = None
        for group in groups:
            gh = max(1.0, group["height"])
            overlap = min(rect.bottom(), group["bottom"]) - max(rect.top(), group["top"])
            tolerance = max(1.5, 0.30 * max(h, gh))
            if overlap > 0.20 * min(h, gh) or abs(cy - group["cy"]) <= tolerance:
                delta = abs(cy - group["cy"])
                if best_delta is None or delta < best_delta:
                    best = group
                    best_delta = delta
        if best is None:
            groups.append({"rects":[rect], "cy":cy, "top":rect.top(), "bottom":rect.bottom(), "height":h})
        else:
            best["rects"].append(rect)
            best["top"] = min(best["top"], rect.top())
            best["bottom"] = max(best["bottom"], rect.bottom())
            best["height"] = max(best["height"], h)
            n = len(best["rects"])
            best["cy"] = ((best["cy"] * (n - 1)) + cy) / n
    result = []
    for group in groups:
        rs = group["rects"]
        try:
            left = min(r.left() for r in rs); right = max(r.right() for r in rs)
            top = min(r.top() for r in rs); bottom = max(r.bottom() for r in rs)
            if right > left and bottom > top:
                result.append(QtCore.QRectF(left, top, right-left, bottom-top))
        except Exception:
            continue
    result.sort(key=lambda r: (r.top(), r.left()))
    return result


class _PageCanvas(QtWidgets.QWidget):
    selectionChanged = QtCore.Signal(bool)
    linkActivated = QtCore.Signal(str)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._pixmap = None
        self._words = []
        self._links = []
        self._scale = 1.0
        self._offset = QtCore.QPointF(0, 0)
        self._press_origin = None
        self._sel_start = None
        self._sel_end = None
        self._sel_active = False
        self._drag_started = False
        self._double_click_word_selected = False
        self._exact_word_selection = False
        self._exact_word_text = ""
        self._pressed_link = None
        self._search_hits = []
        self._current_hit_idx = -1
        self.setMouseTracking(True)
        self.setCursor(QtCore.Qt.CursorShape.IBeamCursor)
        self.setFocusPolicy(QtCore.Qt.FocusPolicy.StrongFocus)

    def set_content(self, pixmap, words_pts, scale, links_pts=None):
        self._pixmap = pixmap
        self._words = words_pts
        if links_pts is not None:
            self._links = list(links_pts)
        self._scale = scale
        self._press_origin = None
        self._sel_start = None
        self._sel_end = None
        self._sel_active = False
        self._drag_started = False
        self._double_click_word_selected = False
        self._exact_word_selection = False
        self._exact_word_text = ""
        self._pressed_link = None
        self.selectionChanged.emit(False)
        self._update_hover_cursor(self.mapFromGlobal(QtGui.QCursor.pos()))
        self.update()

    def set_search_hits(self, hits, current_idx=-1):
        self._search_hits = list(hits) if hits else []
        self._current_hit_idx = current_idx
        self.update()

    def has_selection(self):
        if not (self._sel_active
                and self._sel_start is not None
                and self._sel_end is not None):
            return False
        if not self._words:
            return False
        r = QtCore.QRectF(self._sel_start, self._sel_end).normalized()
        pt_rect = QtCore.QRectF(
            (r.left() - self._offset.x()) / self._scale,
            (r.top() - self._offset.y()) / self._scale,
            r.width() / self._scale,
            r.height() / self._scale,
        )
        for (x0, y0, x1, y1, _t) in self._words:
            wr = QtCore.QRectF(x0, y0, x1 - x0, y1 - y0)
            if pt_rect.intersects(wr):
                return True
        return False

    def _recompute_offset(self):
        if self._pixmap is None:
            self._offset = QtCore.QPointF(0, 0)
            return
        w = self._pixmap.width()
        h = self._pixmap.height()
        self._offset = QtCore.QPointF(
            max(0, (self.width() - w) / 2.0),
            max(0, (self.height() - h) / 2.0),
        )

    def paintEvent(self, event):
        p = QtGui.QPainter(self)
        p.fillRect(self.rect(), QtGui.QColor("#0f0f0f"))
        if self._pixmap is None:
            return
        self._recompute_offset()
        p.drawPixmap(int(self._offset.x()), int(self._offset.y()), self._pixmap)

        if self._search_hits:
            p.setPen(QtCore.Qt.PenStyle.NoPen)
            for j, (x0, y0, x1, y1) in enumerate(self._search_hits):
                rect = QtCore.QRectF(
                    self._offset.x() + x0 * self._scale,
                    self._offset.y() + y0 * self._scale,
                    (x1 - x0) * self._scale,
                    (y1 - y0) * self._scale,
                )
                if j == self._current_hit_idx:
                    p.setBrush(QtGui.QColor(255, 210, 60, 150))
                else:
                    p.setBrush(QtGui.QColor(80, 220, 120, 95))
                p.drawRect(rect)

        if (self._sel_active
                and self._sel_start is not None
                and self._sel_end is not None):
            r = QtCore.QRectF(self._sel_start, self._sel_end).normalized()
            sel_pt_rect = QtCore.QRectF(
                (r.left() - self._offset.x()) / self._scale,
                (r.top() - self._offset.y()) / self._scale,
                r.width() / self._scale,
                r.height() / self._scale,
            )
            p.setPen(QtCore.Qt.PenStyle.NoPen)
            p.setBrush(QtGui.QBrush(QtGui.QColor(74, 158, 255, 90)))
            if self._exact_word_selection:
                # Double-click selects one exact word.  Do not highlight
                # neighbouring boxes merely because their edges touch.
                pix_rect = QtCore.QRectF(
                    self._offset.x() + sel_pt_rect.left() * self._scale,
                    self._offset.y() + sel_pt_rect.top() * self._scale,
                    sel_pt_rect.width() * self._scale,
                    sel_pt_rect.height() * self._scale,
                )
                p.drawRect(pix_rect)
            else:
                # Keep word-based selection/copy semantics, but paint one continuous strip
                # across whitespace between words on each visual line.
                for wr in _selection_line_highlight_rects(self._words, sel_pt_rect):
                    p.drawRect(QtCore.QRectF(
                        self._offset.x() + wr.left() * self._scale,
                        self._offset.y() + wr.top() * self._scale,
                        wr.width() * self._scale,
                        wr.height() * self._scale))

    def _select_word_at(self, pos):
        """Select the copyable word directly underneath the cursor."""
        if not self._pixmap or not self._words or self._scale <= 0:
            return False

        # _offset is calculated during painting; refresh it here too so the
        # hit test remains correct after a resize before the next repaint.
        self._recompute_offset()
        px = (float(pos.x()) - self._offset.x()) / self._scale
        py = (float(pos.y()) - self._offset.y()) / self._scale
        if px < 0 or py < 0 or px > self._pixmap.width() / self._scale or py > self._pixmap.height() / self._scale:
            return False

        candidates = []
        for word in self._words:
            try:
                x0, y0, x1, y1, text = word
                rect = QtCore.QRectF(float(x0), float(y0),
                                     float(x1) - float(x0),
                                     float(y1) - float(y0))
                # Rendering/downscaling can move a glyph edge by a fraction of a point.
                # A very small scale-aware tolerance keeps double-click selection tied to the
                # visible glyph without allowing a click in a neighboring word to jump across
                # the page.
                tol = min(4.0, max(0.75, 1.5 / float(self._scale)))
                hit_rect = rect.adjusted(-tol, -tol, tol, tol)
                if hit_rect.contains(QtCore.QPointF(px, py)):
                    cx = rect.center().x()
                    cy = rect.center().y()
                    candidates.append((abs(cx - px) + abs(cy - py), rect, str(text)))
            except Exception:
                continue

        if not candidates:
            return False

        _distance, rect, text = min(candidates, key=lambda x: x[0])
        self._sel_start = QtCore.QPointF(
            self._offset.x() + rect.left() * self._scale,
            self._offset.y() + rect.top() * self._scale)
        self._sel_end = QtCore.QPointF(
            self._offset.x() + rect.right() * self._scale,
            self._offset.y() + rect.bottom() * self._scale)
        self._sel_active = True
        self._drag_started = False
        self._press_origin = None
        self._exact_word_selection = True
        self._exact_word_text = text
        self.selectionChanged.emit(True)
        self.update()
        return True

    def _link_at(self, pos):
        """Return the web URI whose PDF link rectangle contains pos."""
        if not self._links or self._scale <= 0:
            return None
        self._recompute_offset()
        px = (float(pos.x()) - self._offset.x()) / self._scale
        py = (float(pos.y()) - self._offset.y()) / self._scale
        point = QtCore.QPointF(px, py)
        candidates = []
        for link in self._links:
            try:
                x0, y0, x1, y1, uri = link
                rect = QtCore.QRectF(float(x0), float(y0),
                                     float(x1) - float(x0),
                                     float(y1) - float(y0))
                if rect.contains(point):
                    area = max(0.0, rect.width()) * max(0.0, rect.height())
                    candidates.append((area, str(uri)))
            except Exception:
                pass
        if not candidates:
            return None
        candidates.sort(key=lambda item: item[0])
        return candidates[0][1]

    def _update_hover_cursor(self, pos):
        try:
            if pos is not None and self._link_at(pos):
                self.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
            else:
                self.setCursor(QtCore.Qt.CursorShape.IBeamCursor)
        except Exception:
            self.setCursor(QtCore.Qt.CursorShape.IBeamCursor)

    def mouseDoubleClickEvent(self, event):
        if event.button() == QtCore.Qt.MouseButton.LeftButton and self._select_word_at(_qt_event_position(event)):
            self._pressed_link = None
            # Qt sends a release event after mouseDoubleClickEvent.  Keep the
            # freshly selected word alive through that release instead of
            # treating the double-click as an ordinary click and clearing it.
            self._double_click_word_selected = True
            event.accept()
            return
        self._double_click_word_selected = False
        super().mouseDoubleClickEvent(event)

    def mousePressEvent(self, event):
        if event.button() == QtCore.Qt.MouseButton.LeftButton:
            try:
                self.setFocus(QtCore.Qt.FocusReason.MouseFocusReason)
            except Exception:
                pass
            self._pressed_link = self._link_at(_qt_event_position(event))
            self._press_origin = _qt_event_position(event)
            self._sel_start = _qt_event_position(event)
            self._sel_end = _qt_event_position(event)
            self._drag_started = False
            self._sel_active = False
            self._exact_word_selection = False
            self._exact_word_text = ""
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._press_origin is None:
            self._update_hover_cursor(_qt_event_position(event))
            return
        if not self._drag_started:
            dx = _qt_event_position(event).x() - self._press_origin.x()
            dy = _qt_event_position(event).y() - self._press_origin.y()
            if dx * dx + dy * dy < 25:
                return
            self._drag_started = True
            self._sel_active = True
            self.setCursor(QtCore.Qt.CursorShape.IBeamCursor)
        self._sel_end = _qt_event_position(event)
        self.update()

    def mouseReleaseEvent(self, event):
        if event.button() == QtCore.Qt.MouseButton.LeftButton:
            pressed_link = self._pressed_link
            self._pressed_link = None
            if self._double_click_word_selected:
                self._double_click_word_selected = False
                self._press_origin = None
                self._drag_started = False
                self.selectionChanged.emit(self.has_selection())
                self._update_hover_cursor(_qt_event_position(event))
                self.update()
                event.accept()
                return
            if not self._drag_started:
                self._sel_active = False
                self._sel_start = None
                self._sel_end = None
                if pressed_link:
                    self.linkActivated.emit(pressed_link)
            else:
                self._sel_end = _qt_event_position(event)
            self._press_origin = None
            self.selectionChanged.emit(self.has_selection())
            self._update_hover_cursor(_qt_event_position(event))
            self.update()
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def keyPressEvent(self, event):
        if event.matches(QtGui.QKeySequence.StandardKey.Copy):
            self._copy_selection()
            return
        if event.key() == QtCore.Qt.Key.Key_Escape:
            self._sel_active = False
            self._sel_start = None
            self._sel_end = None
            self._double_click_word_selected = False
            self._exact_word_selection = False
            self._exact_word_text = ""
            self._pressed_link = None
            self.selectionChanged.emit(False)
            self.update()
            return
        super().keyPressEvent(event)

    def _copy_selection(self):
        text = self.selection_text()
        if text:
            QtWidgets.QApplication.clipboard().setText(text)
        return text

    def selection_text(self):
        if (not self._sel_active
                or self._sel_start is None
                or self._sel_end is None):
            return ""
        r = QtCore.QRectF(self._sel_start, self._sel_end).normalized()
        pt_rect = QtCore.QRectF(
            (r.left() - self._offset.x()) / self._scale,
            (r.top() - self._offset.y()) / self._scale,
            r.width() / self._scale,
            r.height() / self._scale,
        )
        if self._exact_word_selection:
            # Double-click represents exactly one selectable word.  Do not
            # include neighbouring boxes just because they touch/intersect.
            return str(self._exact_word_text or "")
        chunks = []
        for (x0, y0, x1, y1, t) in self._words:
            wr = QtCore.QRectF(x0, y0, x1 - x0, y1 - y0)
            if pt_rect.intersects(wr):
                chunks.append(t)
        return " ".join(chunks)



# ============================================================
# EXACT PDF-NATIVE FILTER PREVIEW WORKERS
# ============================================================
def _build_filter_preview_base_pdf(entries, output_pdf_path):
    """Build a temporary PDF that mirrors the page state used by Edit PDF Save Changes.

    This intentionally uses the same PyMuPDF page-copy/edit path as the real save workflow.
    Filter effects are added separately by pikepdf so the preview can use the exact PDF-native
    filter implementation without modifying the user's source document.
    """
    source_docs = {}
    output_doc = None
    try:
        os.makedirs(os.path.dirname(os.path.abspath(output_pdf_path)), exist_ok=True)
        output_doc = fitz.open()
        for entry in entries or []:
            source_pdf = os.path.abspath(str(entry.get("source_pdf") or ""))
            page_idx = int(entry.get("original_idx", 0))
            if not source_pdf or not os.path.isfile(source_pdf):
                raise FileNotFoundError(f"Source PDF not found: {source_pdf}")
            if source_pdf not in source_docs:
                source_docs[source_pdf] = fitz.open(source_pdf)
            src = source_docs[source_pdf]
            if page_idx < 0 or page_idx >= src.page_count:
                raise IndexError(
                    f"Source page index {page_idx} is out of range for {source_pdf}.")

            source_page = src.load_page(page_idx)
            try:
                src_rot = int(source_page.rotation) % 360
            except Exception:
                src_rot = 0

            # Match the actual Save Changes ordering: copy the original page, add
            # any pending invisible OCR text, then apply crop/flip/rotation state.
            output_doc.insert_pdf(src, from_page=page_idx, to_page=page_idx)
            page = output_doc[-1]

            if _page_design_has_any(entry) and _page_design_anchor_state(entry) is not None:
                ordered = _page_design_ordered_document(entry, apply_filters=False)
                try:
                    output_doc.delete_page(output_doc.page_count - 1)
                except Exception:
                    pass
                output_doc.insert_pdf(ordered)
                ordered.close()
            else:
                ocr_blocks = entry.get("ocr") if (
                    entry.get("ocr_done") or entry.get("ocr")) else None
                if ocr_blocks is not None:
                    try:
                        filtered_blocks, _skipped = _filter_duplicate_ocr_blocks(
                            page, ocr_blocks)
                        _insert_ocr_text(
                            page, filtered_blocks, filter_existing=False)
                    except Exception:
                        pass
                apply_entry_to_page(page, entry, src_rot=src_rot)

        # The viewer only needs a deterministic temporary artifact. Use the same normal
        # PyMuPDF save path as the real editor's intermediate document; the later pikepdf stage
        # performs the exact isolated DeviceRGB inversion when inversion is active.
        output_doc.save(output_pdf_path)
    finally:
        if output_doc is not None:
            try:
                output_doc.close()
            except Exception:
                pass
        for doc in source_docs.values():
            try:
                doc.close()
            except Exception:
                pass


def _apply_filter_preview_pdf_or_raise(input_pdf_path, output_pdf_path, filter_config):
    """Apply the shared PDF-native filter stack to every page in an exact preview PDF."""
    cfg = _normalize_filter_config(filter_config)
    try:
        with pikepdf.open(input_pdf_path) as pdf:
            for page_index, page in enumerate(pdf.pages):
                _apply_pdf_filter_to_page(pdf, page, cfg)
            pdf.save(output_pdf_path)
    except Exception:
        try:
            if os.path.exists(output_pdf_path):
                os.remove(output_pdf_path)
        except Exception:
            pass
        raise


def _actual_filter_preview_process_worker(entries, filter_config, output_pdf_path, send_conn):
    """Spawn-safe exact-preview worker with the same ordered Page Design sequence as Save Changes."""
    base_path = output_pdf_path + ".base.pdf"
    ordered_path = output_pdf_path + ".ordered.pdf"
    try:
        anchored = [
            _page_design_has_any(entry) and _page_design_anchor_state(entry) is not None
            for entry in (entries or [])
        ]
        if anchored and all(anchored):
            temp_doc = fitz.open()
            try:
                for entry in entries or []:
                    preview_entry = copy.deepcopy(entry)
                    preview_entry["filter_config"] = _normalize_filter_config(filter_config)
                    ordered = _page_design_ordered_document(
                        preview_entry, apply_filters=True,
                        filter_override=_normalize_filter_config(filter_config))
                    temp_doc.insert_pdf(ordered)
                    ordered.close()
                temp_doc.save(output_pdf_path)
            finally:
                temp_doc.close()
        else:
            _build_filter_preview_base_pdf(entries, base_path)
            _apply_filter_preview_pdf_or_raise(
                base_path, output_pdf_path, filter_config)
            stretch_entries = [
                dict(entry, stretch_ratio=(None if (
                    _page_design_has_any(entry) and _page_design_anchor_state(entry) is not None)
                    else entry.get("stretch_ratio")))
                for entry in (entries or [])
            ]
            if any(entry.get("stretch_ratio") is not None for entry in stretch_entries):
                _stretch_pdf_for_entries(output_pdf_path, stretch_entries, progress=None)
            _apply_page_design_to_pdf(output_pdf_path, entries, progress=None)

        for candidate in (base_path, ordered_path):
            try:
                if os.path.isfile(candidate):
                    os.remove(candidate)
            except Exception:
                pass
        try:
            send_conn.send(("ok", output_pdf_path, ""))
        except Exception:
            pass
    except Exception as exc:
        for candidate in (base_path, ordered_path, output_pdf_path):
            try:
                if os.path.exists(candidate):
                    os.remove(candidate)
            except Exception:
                pass
        try:
            send_conn.send(("error", "", f"{type(exc).__name__}: {exc}"))
        except Exception:
            pass
    finally:
        try:
            send_conn.close()
        except Exception:
            pass


def _show_view_toast(widget, text, timeout=1200):
    """Show a compact transient toast above the viewer footer."""
    try:
        toast = getattr(widget, "_view_toast", None)
        timer = getattr(widget, "_view_toast_timer", None)
        if toast is None:
            toast = QtWidgets.QLabel(widget)
            toast.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
            toast.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
            toast.setStyleSheet("""
                QLabel {
                    background-color: rgba(20, 20, 20, 225);
                    color: #f0f0f0;
                    border: 1px solid #414141;
                    border-radius: 9px;
                    padding: 7px 13px;
                    font-size: 10pt;
                    font-weight: bold;
                }
            """)
            toast.hide()
            timer = QtCore.QTimer(widget)
            timer.setSingleShot(True)
            widget._view_toast = toast
            widget._view_toast_timer = timer
            timer.timeout.connect(toast.hide)
        toast.setText(str(text))
        toast.adjustSize()
        w = max(1, int(widget.width()))
        h = max(1, int(widget.height()))
        x = max(10, (w - toast.width()) // 2)
        # Keep feedback clearly above the footer.  The larger clearance also leaves
        # room for a persistent rendering-status toast immediately above it.
        footer_clearance = 92
        y = max(10, h - toast.height() - footer_clearance)
        toast.move(x, y)
        toast.show()
        toast.raise_()
        timer.start(max(300, int(timeout)))
        _reposition_view_status_toast(widget)
    except Exception:
        pass


def _reposition_view_status_toast(widget):
    """Position the persistent filter-rendering toast above the transient toast."""
    try:
        toast = getattr(widget, "_view_status_toast", None)
        if toast is None or not toast.isVisible():
            return
        toast.adjustSize()
        zoom_toast = getattr(widget, "_view_toast", None)
        w = max(1, int(widget.width()))
        h = max(1, int(widget.height()))
        x = max(10, (w - toast.width()) // 2)
        footer_clearance = 92
        zoom_height = 0
        if zoom_toast is not None and zoom_toast.isVisible():
            try:
                zoom_height = int(zoom_toast.height())
            except Exception:
                zoom_height = 0
        gap = 8
        y = h - footer_clearance - zoom_height - gap - toast.height()
        toast.move(x, max(10, y))
        toast.raise_()
    except Exception:
        pass


def _show_view_status_toast(widget, text="Rendering actual filter results..."):
    """Show a persistent status toast until the caller explicitly hides it."""
    try:
        toast = getattr(widget, "_view_status_toast", None)
        if toast is None:
            toast = QtWidgets.QLabel(widget)
            toast.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
            toast.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
            toast.setStyleSheet("""
                QLabel {
                    background-color: rgba(20, 20, 20, 225);
                    color: #bcbcbc;
                    border: 1px solid #414141;
                    border-radius: 9px;
                    padding: 7px 13px;
                    font-size: 10pt;
                    font-weight: bold;
                }
            """)
            toast.hide()
            widget._view_status_toast = toast
        toast.setText(str(text))
        toast.adjustSize()
        toast.show()
        toast.raise_()
        _reposition_view_status_toast(widget)
        # Force the toast to paint before an expensive exact-preview worker starts.
        # Without this, Qt may defer the paint until after the worker/queued events
        # have already completed, making short renders appear to skip the toast.
        toast.repaint()
    except Exception:
        pass


def _hide_view_status_toast(widget):
    try:
        toast = getattr(widget, "_view_status_toast", None)
        if toast is not None:
            toast.hide()
    except Exception:
        pass


def _make_toolbar_divider(parent=None, height=30):
    divider = QtWidgets.QFrame(parent)
    divider.setFixedSize(1, int(height))
    divider.setStyleSheet("background-color: #555555; border: none;")
    return divider


class _PdfZoomSlider(_ThumbnailDensitySlider):
    """PDF zoom slider using an absolute percentage rather than page-relative scaling."""
    def _tooltip_text(self, value):
        return f"{int(value)}%"


class _PdfZoomFooter(QtWidgets.QWidget):
    """Shared viewer footer: zoom-out, percentage slider, zoom-in, and Fit Width."""
    def __init__(self, zoom_getter, zoom_in_callback, zoom_out_callback,
                 zoom_percent_callback, fit_callback=None, parent=None):
        super().__init__(parent)
        self._zoom_getter = zoom_getter
        self._zoom_percent_callback = zoom_percent_callback
        self.setSizePolicy(QtWidgets.QSizePolicy.Policy.Fixed, QtWidgets.QSizePolicy.Policy.Fixed)

        row = QtWidgets.QHBoxLayout(self)
        row.setContentsMargins(0, 0, 0, 0)
        row.setSpacing(6)

        self.zoom_out_btn = self._make_button(
            "minus.svg", "Zoom Out (Ctrl+-)", zoom_out_callback)
        row.addWidget(self.zoom_out_btn)

        self.slider = _PdfZoomSlider(QtCore.Qt.Orientation.Horizontal)
        self.slider.setRange(15, 800)
        self.slider.setSingleStep(5)
        self.slider.setPageStep(25)
        self.slider.setValue(100)
        self.slider.setTracking(True)
        self.slider.setFixedWidth(180)
        self.slider.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.slider.setStyleSheet("""
            QSlider { background:transparent; border:none; padding:0; }
            QSlider::groove:horizontal { height:4px; background:#343434; border:none; border-radius:2px; }
            QSlider::handle:horizontal { width:14px; height:14px; margin:-5px 0; background:#0078d7; border:none; border-radius:7px; }
            QSlider::sub-page:horizontal { background:#0078d7; border:none; border-radius:2px; }
            QSlider::add-page:horizontal { background:#343434; border:none; border-radius:2px; }
        """)
        self.slider.valueChanged.connect(self._on_slider_changed)
        row.addWidget(self.slider)

        self.zoom_in_btn = self._make_button(
            "plus.svg", "Zoom In (Ctrl++)", zoom_in_callback)
        row.addWidget(self.zoom_in_btn)

        self.fit_btn = None
        if fit_callback is not None:
            self.fit_btn = self._make_button(
                "fit.svg", "Fit Width (Ctrl+0)", fit_callback)
            row.addWidget(self.fit_btn)

        self.set_zoom_factor(float(self._zoom_getter()), emit=False)

    def _make_button(self, icon_name, tooltip, callback):
        button = QtWidgets.QPushButton()
        button.setFixedSize(32, 34)
        button.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        button.setToolTip(tooltip)
        button.setIconSize(QtCore.QSize(18, 18))
        icon = _render_svg_icon(os.path.join(ICONS_FOLDER, icon_name), size=18)
        if icon is not None:
            button.setIcon(icon)
        else:
            button.setText("−" if icon_name.startswith("minus") else "+")
        button.setStyleSheet("""
            QPushButton {
                background:#2a2a2a; color:#f0f0f0;
                border:1px solid #3a3a3a; border-radius:6px;
                font-size:15pt; font-weight:bold;
            }
            QPushButton:hover { background:#3a3a3a; }
            QPushButton:pressed { background:#4a4a4a; }
            QPushButton:disabled { background:#1e1e1e; border:1px solid #2a2a2a; }
        """)
        button.clicked.connect(lambda *_args, _callback=callback: _callback())
        return button

    def _on_slider_changed(self, value):
        self._zoom_percent_callback(int(value))

    def set_zoom_factor(self, zoom, emit=False):
        try:
            percent = int(round(float(zoom) * 100.0))
        except Exception:
            percent = 100
        percent = max(self.slider.minimum(), min(self.slider.maximum(), percent))
        old = self.slider.blockSignals(True)
        self.slider.setValue(percent)
        self.slider.blockSignals(old)
        if emit:
            self._zoom_percent_callback(percent)

    def current_percent(self):
        return int(self.slider.value())


class LightweightPageViewer(QtWidgets.QDialog):
    pageChanged = QtCore.Signal(int)
    def __init__(self, pdf_path, page_idx, rotation=0, crop=None, parent=None,
                 nav_items=None, nav_index=0, show_selected_label=False,
                 total_dummy=None, flip_h=False, flip_v=False, invert_colors=False,
                 embedded=False, filter_preview_config=None,
                 actual_filter_preview=False, presentation_callback=None,
                 print_callback=None):
        super().__init__(parent)
        self.setWindowTitle("Open Page")
        self.setModal(not embedded)
        self._embedded = bool(embedded)
        self._presentation_callback = presentation_callback if callable(presentation_callback) else None
        self._print_callback = print_callback if callable(print_callback) else None

        # Standalone Edit PDF "Open Page" viewers must always expose the same
        # Presentation/Print controls, even when an older/alternate caller forgot
        # to pass explicit callbacks.  Resolve them from the owning EditPdfDialog
        # as a defensive fallback.  Embedded viewers (for example Apply Filters)
        # intentionally remain presentation/print-free.
        if not self._embedded and (self._presentation_callback is None or self._print_callback is None):
            owner = parent
            while owner is not None:
                try:
                    if hasattr(owner, "_open_presentation_for_nav") or hasattr(owner, "_selected_navigation_context"):
                        break
                    owner = owner.parentWidget()
                except Exception:
                    owner = None

            if owner is not None:
                if self._presentation_callback is None:
                    presentation_owner = owner
                    if hasattr(presentation_owner, "_open_presentation_for_nav"):
                        self._presentation_callback = (
                            lambda items, idx, _owner=presentation_owner:
                                _owner._open_presentation_for_nav(items, idx)
                        )

                if self._print_callback is None:
                    print_entries_fallback = []
                    try:
                        if hasattr(owner, "_selected_navigation_context"):
                            _items, _idx, selected_entries = owner._selected_navigation_context()
                            print_entries_fallback = [dict(entry) for entry in selected_entries]
                    except Exception:
                        print_entries_fallback = []

                    if not print_entries_fallback and self._nav_items:
                        try:
                            print_entries_fallback = [dict(self._nav_items[self._nav_index])]
                        except Exception:
                            print_entries_fallback = []

                    if hasattr(owner, "_print_entries") and print_entries_fallback:
                        self._print_callback = (
                            lambda _unused=None, entries=print_entries_fallback, _owner=owner:
                                _owner._print_entries(entries)
                        )

        if self._embedded:
            self.setObjectName("embeddedLightweightPageViewer")
            self.setAttribute(QtCore.Qt.WidgetAttribute.WA_StyledBackground, True)
            self.setAutoFillBackground(False)
            self.setStyleSheet(
                "QDialog#embeddedLightweightPageViewer { background:transparent; border:none; }"
                "QWidget#embeddedLightweightPageViewer { background:transparent; border:none; }")
        self._filter_preview_config = (
            _normalize_filter_config(filter_preview_config)
            if isinstance(filter_preview_config, dict) else None)
        if self._embedded:
            self.setWindowFlags(QtCore.Qt.WindowType.Widget)
            self.setMinimumSize(0, 0)
            self.setSizePolicy(QtWidgets.QSizePolicy.Policy.Expanding, QtWidgets.QSizePolicy.Policy.Expanding)
        else:
            self.setMinimumSize(760, 620)

        if nav_items:
            self._nav_items = [dict(it) for it in nav_items]
            try:
                idx = int(nav_index)
            except Exception:
                idx = 0
            self._nav_index = max(0, min(idx, len(self._nav_items) - 1))
        else:
            self._nav_items = [{
                'source_pdf': pdf_path,
                'original_idx': int(page_idx),
                'rotation': int(rotation or 0),
                'crop': crop,
                'flip_h': bool(flip_h),
                'flip_v': bool(flip_v),
                'invert_colors': bool(invert_colors),
                'filter_config': (_normalize_filter_config(filter_preview_config)
                                  if isinstance(filter_preview_config, dict)
                                  else (_preset_filter_config('Invert') if invert_colors else _neutral_filter_config())),
                'grid_row': 0,
            }]
            self._nav_index = 0

        if total_dummy is None:
            self._total_dummy = len(self._nav_items)
        else:
            try:
                self._total_dummy = int(total_dummy)
            except Exception:
                self._total_dummy = len(self._nav_items)

        self._show_selected_label = bool(show_selected_label)
        self._nav_multi = len(self._nav_items) > 1

        # Exact-preview mode is used by standalone Edit PDF dummy viewers. The viewer first
        # renders and displays the fast pixel-filtered result, then (after an idle delay) renders
        # only the currently visible page through the real pikepdf filter stack in an isolated
        # process. Embedded Apply Filters uses its own exact-preview controller below.
        self._actual_filter_preview_enabled = bool(actual_filter_preview) and not self._embedded
        self._actual_preview_process = None
        self._actual_preview_conn = None
        self._actual_preview_output_path = None
        self._actual_preview_page_map = []
        self._actual_preview_generation = 0
        self._actual_preview_for_nav_index = None
        self._actual_preview_start_scheduled = False
        self._actual_preview_job_output_candidate = None
        self._actual_preview_job_generation = -1
        self._actual_preview_idle_timer = None
        self._actual_preview_poll_timer = None
        self._actual_preview_retired_jobs = []
        self._actual_preview_reaper_timer = None
        if self._actual_filter_preview_enabled:
            self._actual_preview_idle_timer = QtCore.QTimer(self)
            self._actual_preview_idle_timer.setSingleShot(True)
            self._actual_preview_idle_timer.setInterval(850)
            self._actual_preview_idle_timer.timeout.connect(self._start_actual_preview_for_current_page)
            self._actual_preview_poll_timer = QtCore.QTimer(self)
            self._actual_preview_poll_timer.setInterval(40)
            self._actual_preview_poll_timer.timeout.connect(self._poll_actual_preview_job)
            self._actual_preview_reaper_timer = QtCore.QTimer(self)
            self._actual_preview_reaper_timer.setInterval(60)
            self._actual_preview_reaper_timer.timeout.connect(self._reap_actual_preview_processes)

        self._zoom = 1.0
        self._min_zoom = 0.15
        self._max_zoom = 8.0
        self._page_pt_size = (612, 792)
        self._source_page_pt_size = self._page_pt_size
        self._initial_fit_done = False
        self._auto_fit = True

        self._search_results = []
        self._current_result_idx = -1
        self._search_query = ""
        self._find_box = None

        # The PDF render is cached. Interactive filters always operate on the clean source snapshot.
        self._base_qpixmap = None
        self._base_qimage = QtGui.QImage()
        self._base_words_pt = []
        self._filter_preview_generation = 0
        self._filter_preview_last_config = None
        self._filter_preview_thread = _FilterPreviewRenderThread(self)
        self._filter_preview_thread.result_signal.connect(self._on_filter_preview_ready)
        self._filter_preview_thread.start()
        # Keep a pristine rendered source snapshot separate from the currently displayed
        # preview so switching from an exact pikepdf result back to a pixel-filter result
        # never double-applies the filter.
        self._source_qpixmap = None
        self._source_qimage = QtGui.QImage()
        self._source_words_pt = []
        self._source_zoom = None
        # Keep the most recently completed pixel-filter preview separately from the clean source
        # and from any exact pikepdf result currently displayed. This is the stable visual fallback
        # used while a new pixel frame is being rendered after a setting change.
        self._last_pixel_preview_qpixmap = None
        self._last_pixel_preview_words_pt = []
        self._last_pixel_preview_config = None
        self._last_pixel_preview_zoom = None

        self._fit_debounce = QtCore.QTimer(self)
        self._fit_debounce.setSingleShot(True)
        self._fit_debounce.setInterval(140)
        self._fit_debounce.timeout.connect(self._fit)

        layout = QtWidgets.QVBoxLayout(self)
        margin = 4 if self._embedded else 12
        layout.setContentsMargins(margin, margin, margin, margin)
        layout.setSpacing(6 if self._embedded else 8)

        header = QtWidgets.QHBoxLayout()
        header.setSpacing(8)

        logo_lbl = QtWidgets.QLabel()
        logo_icon = _render_svg_icon(
            os.path.join(ICONS_FOLDER, "logo.svg"), size=22)
        if logo_icon is not None:
            logo_lbl.setPixmap(logo_icon.pixmap(22, 22))
        logo_lbl.setFixedSize(22, 22)
        logo_lbl.setStyleSheet(
            "background: transparent; border: none; padding: 0; margin: 0;")
        header.addWidget(logo_lbl)

        self._title_lbl = ElidedLabel("", QtCore.Qt.TextElideMode.ElideMiddle)
        self._title_lbl.setStyleSheet(
            "font-size: 12pt; font-weight: bold; color: #f0f0f0; "
            "background: transparent; border: none; padding: 0; margin: 0;")
        self._title_lbl.setMinimumWidth(60)
        header.addWidget(self._title_lbl)

        self._page_pill = QtWidgets.QLabel("")
        self._page_pill.setStyleSheet("""
            background-color: #0a3a5c; color: #4a9eff;
            padding: 4px 12px; border-radius: 10px;
            font-weight: bold; font-size: 9pt;
        """)
        header.addWidget(self._page_pill)

        header.addStretch(1)

        # Keep the viewer actions together as a compact, non-stretching toolbar.
        # This prevents the filename/title area from consuming the space needed
        # by the buttons on smaller windows.
        header_actions = QtWidgets.QHBoxLayout()
        header_actions.setSpacing(6)
        header_actions.setContentsMargins(0, 0, 0, 0)

        def make_btn(icon_name, tooltip, slot):
            b = QtWidgets.QPushButton()
            b.setFixedSize(36, 36)
            b.setToolTip(tooltip)
            b.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
            b.setStyleSheet("""
                QPushButton {
                    background-color: #2a2a2a;
                    border: 1px solid #3a3a3a;
                    border-radius: 6px;
                }
                QPushButton:hover { background-color: #3a3a3a; }
                QPushButton:checked {
                    background-color: #0a3a5c;
                    border: 1px solid #0078d7;
                }
                QPushButton:disabled {
                    background-color: #1e1e1e;
                    border: 1px solid #2a2a2a;
                }
            """)
            ic = _render_svg_icon(os.path.join(ICONS_FOLDER, icon_name), 22)
            if ic is not None:
                b.setIcon(ic)
                b.setIconSize(QtCore.QSize(22, 22))
            else:
                b.setText("•")
            # QPushButton.clicked emits a boolean even for ordinary buttons.
            # Most editor actions intentionally take no arguments, so consume
            # the signal argument here rather than passing it into the action.
            b.clicked.connect(lambda *_args, _slot=slot: _slot())
            return b

        self._btn_find = make_btn("find.svg", "Find text in page (Ctrl+F)",
                                  self._toggle_find)
        self._btn_find.setCheckable(True)

        self._btn_copy = make_btn("copy.svg",
                                  "Copy selected text (Ctrl+C)",
                                  self._copy_selection)
        self._btn_copy.setEnabled(False)

        self._btn_presentation = None
        self._btn_print = None
        if not self._embedded:
            if self._presentation_callback is not None:
                self._btn_presentation = make_btn(
                    "presentation.svg",
                    "Presentation mode for selected pages (F5)",
                    self._open_presentation_callback)
            if self._print_callback is not None:
                self._btn_print = make_btn(
                    "print.svg",
                    "Print selected pages (Ctrl+P)",
                    self._print_callback)

        for _btn in (
            self._btn_find,
            self._btn_copy,
            self._btn_presentation,
            self._btn_print,
        ):
            if _btn is not None:
                header_actions.addWidget(_btn)
        header.addLayout(header_actions)
        layout.addLayout(header)

        self._page_scroll = QtWidgets.QScrollArea()
        self._page_scroll.setWidgetResizable(False)
        self._page_scroll.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self._page_scroll.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        self._page_scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self._page_scroll.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self._page_scroll.setStyleSheet(
            "QScrollArea { border: none; background: #0f0f0f; }")

        self._canvas = _PageCanvas()
        self._canvas.setStyleSheet(
            "background-color: #0f0f0f; border-radius: 6px;")
        self._canvas.setContextMenuPolicy(QtCore.Qt.ContextMenuPolicy.CustomContextMenu)
        self._canvas.customContextMenuRequested.connect(
            self._on_canvas_context_menu)
        self._canvas.selectionChanged.connect(
            lambda has: self._btn_copy.setEnabled(has))
        self._canvas.linkActivated.connect(self._open_external_link)
        self._page_scroll.setWidget(self._canvas)
        layout.addWidget(self._page_scroll, stretch=1)

        bottom = QtWidgets.QHBoxLayout()
        bottom.setContentsMargins(3, 0, 3, 0)
        bottom.setSpacing(6)

        self._zoom_footer = _PdfZoomFooter(
            lambda: self._zoom,
            self._zoom_in,
            self._zoom_out,
            self._set_zoom_percent,
            self._fit,
            self,
        )
        bottom.addWidget(self._zoom_footer)

        self._btn_prev = None
        self._btn_next = None
        self._sel_lbl = None

        # Navigation controls are part of the Edit PDF preview footer whenever this
        # viewer has an explicit navigation model, even when that model contains
        # only one page.  The buttons simply become disabled at the ends (including
        # the 1/1 case), while the page indicator remains visible for consistency.
        if self._nav_items:
            bottom.addSpacing(10)
            bottom.addWidget(_make_toolbar_divider(self))
            bottom.addSpacing(10)
            self._btn_prev = self._make_nav_btn("prev.svg",
                                                 "Previous page (Left Arrow)",
                                                 self._go_prev)
            self._btn_next = self._make_nav_btn("next.svg",
                                                 "Next page (Right Arrow)",
                                                 self._go_next)
            bottom.addWidget(self._btn_prev)
            bottom.addWidget(self._btn_next)

        if self._show_selected_label and self._sel_lbl is None and self._nav_items:
            self._sel_lbl = QtWidgets.QLabel("")
            self._sel_lbl.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
            self._sel_lbl.setStyleSheet(
                "color: #4a9eff; font-weight: bold; font-size: 10pt; "
                "background: transparent; border: none; "
                "padding-left: 8px; margin: 0;")
            bottom.addWidget(self._sel_lbl)

        bottom.addStretch()

        if not self._embedded:
            close_btn = QtWidgets.QPushButton("Close")
            close_btn.setFixedWidth(120)
            close_btn.clicked.connect(self.accept)
            bottom.addWidget(close_btn)
        layout.addLayout(bottom)

        short_in = QtGui.QShortcut(QtGui.QKeySequence("Ctrl++"), self)
        short_in.activated.connect(self._zoom_in)
        short_in2 = QtGui.QShortcut(QtGui.QKeySequence("Ctrl+="), self)
        short_in2.activated.connect(self._zoom_in)
        short_out = QtGui.QShortcut(QtGui.QKeySequence("Ctrl+-"), self)
        short_out.activated.connect(self._zoom_out)
        QtGui.QShortcut(QtGui.QKeySequence("Ctrl+0"), self,
                            self._fit)
        find_sc = QtGui.QShortcut(QtGui.QKeySequence("Ctrl+F"), self)
        find_sc.activated.connect(self._toggle_find)
        if self._nav_items:
            self._short_prev = QtGui.QShortcut(QtGui.QKeySequence("Left"), self)
            self._short_prev.setContext(QtCore.Qt.ShortcutContext.WidgetWithChildrenShortcut)
            self._short_prev.setProperty("shortcutTooltip", "Previous page (Left Arrow)")
            self._short_prev.activated.connect(self._go_prev)
            self._short_next = QtGui.QShortcut(QtGui.QKeySequence("Right"), self)
            self._short_next.setContext(QtCore.Qt.ShortcutContext.WidgetWithChildrenShortcut)
            self._short_next.setProperty("shortcutTooltip", "Next page (Right Arrow)")
            self._short_next.activated.connect(self._go_next)

        # The selected-page viewer mirrors the Full PDF Viewer shortcuts for its two
        # new actions.  Keep them local to this dialog so Ctrl+P/F5 never leaks to the
        # Edit PDF window underneath while the viewer is open.
        if self._btn_presentation is not None:
            self._presentation_shortcut = QtGui.QShortcut(QtGui.QKeySequence("F5"), self)
            self._presentation_shortcut.setContext(QtCore.Qt.ShortcutContext.WidgetWithChildrenShortcut)
            self._presentation_shortcut.activated.connect(self._open_presentation_callback)
        if self._btn_print is not None:
            self._print_shortcut = QtGui.QShortcut(QtGui.QKeySequence("Ctrl+P"), self)
            self._print_shortcut.setContext(QtCore.Qt.ShortcutContext.WidgetWithChildrenShortcut)
            self._print_shortcut.activated.connect(self._print_callback)

        self._find_box = _FindBox(self)
        self._find_box.searchRequested.connect(self._on_find_search)
        self._find_box.nextRequested.connect(self._on_find_next)
        self._find_box.prevRequested.connect(self._on_find_prev)
        self._find_box.closeRequested.connect(self._hide_find_box)
        self._find_box.hide()

        self._update_header()
        self._render()

    def _open_presentation_callback(self):
        callback = self._presentation_callback
        if callback is None or not self._nav_items:
            return
        callback([dict(item) for item in self._nav_items], int(self._nav_index))

    def _open_external_link(self, uri):
        _open_external_pdf_link(uri)

    def _make_nav_btn(self, icon_name, tooltip, slot):
        b = QtWidgets.QPushButton()
        b.setFixedSize(36, 36)
        b.setToolTip(tooltip)
        b.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        b.setStyleSheet("""
            QPushButton {
                background-color: #2a2a2a;
                border: 1px solid #3a3a3a;
                border-radius: 6px;
            }
            QPushButton:hover { background-color: #3a3a3a; }
            QPushButton:disabled {
                background-color: #1e1e1e;
                border: 1px solid #2a2a2a;
            }
        """)
        ic = _render_svg_icon(os.path.join(ICONS_FOLDER, icon_name), 22)
        if ic is not None:
            b.setIcon(ic)
            b.setIconSize(QtCore.QSize(22, 22))
        else:
            b.setText("<" if "prev" in icon_name else ">")
        b.clicked.connect(slot)
        return b

    def _update_header(self):
        if not self._nav_items:
            return
        item = self._nav_items[self._nav_index]
        display_name = item.get('display_name') or os.path.basename(item['source_pdf'])
        self._title_lbl.setText(display_name)

        grid_row = item.get('grid_row', self._nav_index)
        try:
            grid_row = int(grid_row)
        except Exception:
            grid_row = self._nav_index
        total = self._total_dummy if self._total_dummy > 0 else max(
            1, self._nav_index + 1)
        self._page_pill.setText(f"Dummy page {grid_row + 1}/{total}")

        if self._show_selected_label and self._sel_lbl is not None:
            total_sel = len(self._nav_items)
            self._sel_lbl.setText(
                f"Selected page {self._nav_index + 1}/{total_sel}")

        if self._btn_prev is not None:
            self._btn_prev.setEnabled(self._nav_index > 0)
        if self._btn_next is not None:
            self._btn_next.setEnabled(
                self._nav_index < len(self._nav_items) - 1)

    def _go_prev(self):
        if self._nav_index <= 0:
            return
        if self._actual_filter_preview_enabled:
            self._cancel_actual_preview_job(remove_output=True)
            self._clear_actual_preview_file()
            self._set_actual_preview_status(False)
        elif self._actual_preview_output_path:
            self.clear_actual_preview(restore_source=False)
        self._nav_index -= 1
        self._update_header()
        self._reset_for_new_page()
        self._render()
        if self._auto_fit:
            self._fit()
        self.pageChanged.emit(self._nav_index)

    def _go_next(self):
        if self._nav_index >= len(self._nav_items) - 1:
            return
        if self._actual_filter_preview_enabled:
            self._cancel_actual_preview_job(remove_output=True)
            self._clear_actual_preview_file()
            self._set_actual_preview_status(False)
        elif self._actual_preview_output_path:
            self.clear_actual_preview(restore_source=False)
        self._nav_index += 1
        self._update_header()
        self._reset_for_new_page()
        self._render()
        if self._auto_fit:
            self._fit()
        self.pageChanged.emit(self._nav_index)

    def current_nav_index(self):
        return int(self._nav_index)

    def _reset_for_new_page(self):
        self._search_results = []
        self._current_result_idx = -1
        self._search_query = ""
        self._canvas.set_search_hits([], -1)
        if self._find_box is not None:
            self._find_box.reset()

    def _toggle_find(self):
        if self._find_box.isVisible():
            self._hide_find_box()
        else:
            self._show_find_box()

    def _show_find_box(self):
        self._find_box.show()
        self._find_box.raise_()
        self._btn_find.setChecked(True)
        self._position_find_box()
        self._find_box.input.setFocus()

    def _hide_find_box(self):
        self._find_box.hide()
        self._btn_find.setChecked(False)
        self._search_query = ""
        self._search_results = []
        self._current_result_idx = -1
        self._canvas.set_search_hits([], -1)
        self._find_box.reset()

    def _position_find_box(self):
        if self._find_box is None:
            return
        self._find_box.adjustSize()
        w = self._find_box.width()
        margin = 20
        x = self.width() - w - margin
        y = 62
        self._find_box.move(x, y)
        self._find_box.raise_()

    def _on_find_search(self, query):
        if not query:
            self._search_query = ""
            self._search_results = []
            self._current_result_idx = -1
            self._canvas.set_search_hits([], -1)
            self._find_box.set_status("Type to search")
            self._find_box.set_nav_enabled(False, False)
            return

        self._search_query = query
        results = []
        tmp = None
        try:
            item = self._nav_items[self._nav_index]
            with fitz.open(item['source_pdf']) as doc:
                page = doc.load_page(item['original_idx'])
                ocr_blocks = item.get('ocr') if item.get('ocr_done') or item.get('ocr') else None

                if ocr_blocks:
                    tmp = fitz.open()
                    tmp.insert_pdf(doc, from_page=item['original_idx'],
                                   to_page=item['original_idx'])
                    search_page = tmp[0]
                    _insert_ocr_text(search_page, ocr_blocks, filter_existing=True)
                else:
                    search_page = page

                # Search in the same cropped page coordinate space used by the
                # viewer. PyMuPDF's search_for returns unrotated crop-relative
                # rectangles; convert them to final rotated/flipped display space
                # before drawing highlights.
                crop = item.get('crop')
                if crop:
                    under = fitz.Rect(*crop) & search_page.mediabox
                    if not under.is_empty:
                        search_page.set_cropbox(under)
                orig_rot = int(search_page.rotation) % 360
                rotation = int(item.get('rotation', 0)) % 360
                search_page.set_rotation((orig_rot + rotation) % 360)

                rects = search_page.search_for(query)
                rm = search_page.rotation_matrix
                W, H = search_page.rect.width, search_page.rect.height
                flip_h = bool(item.get('flip_h', False))
                flip_v = bool(item.get('flip_v', False))
                for r in rects:
                    rr = fitz.Rect(r) * rm
                    x0, x1 = rr.x0, rr.x1
                    y0, y1 = rr.y0, rr.y1
                    if flip_h:
                        x0, x1 = W - x1, W - x0
                    if flip_v:
                        y0, y1 = H - y1, H - y0
                    results.append((float(min(x0, x1)), float(min(y0, y1)),
                                    float(max(x0, x1)), float(max(y0, y1))))
        except Exception:
            pass
        finally:
            if tmp is not None:
                try:
                    tmp.close()
                except Exception:
                    pass

        self._search_results = results

        if not results:
            self._current_result_idx = -1
            self._find_box.set_status("No results found")
            self._find_box.set_nav_enabled(False, False)
            self._canvas.set_search_hits([], -1)
        else:
            self._current_result_idx = 0
            self._update_search_highlight()
            self._find_box.set_nav_enabled(True, True)

    def _on_find_next(self):
        if not self._search_results:
            return
        self._current_result_idx = (
            (self._current_result_idx + 1) % len(self._search_results))
        self._update_search_highlight()

    def _on_find_prev(self):
        if not self._search_results:
            return
        self._current_result_idx = (
            (self._current_result_idx - 1) % len(self._search_results))
        self._update_search_highlight()

    def _update_search_highlight(self):
        self._canvas.set_search_hits(self._search_results,
                                     self._current_result_idx)
        total = len(self._search_results)
        cur = self._current_result_idx + 1
        self._find_box.set_status(f"Showing {cur}/{total} results")
        self._find_box.set_nav_enabled(total > 0, total > 0)

    def showEvent(self, event):
        super().showEvent(event)
        if not self._initial_fit_done:
            self._initial_fit_done = True
            self._auto_fit = True
            QtCore.QTimer.singleShot(50, self._fit)
        if self._find_box is not None and self._find_box.isVisible():
            self._position_find_box()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if hasattr(self, "_view_toast") and self._view_toast.isVisible():
            try:
                _show_view_toast(self, self._view_toast.text(), 900)
            except Exception:
                pass
        _reposition_view_status_toast(self)
        if self._find_box is not None and self._find_box.isVisible():
            self._position_find_box()
        if self._initial_fit_done and self._auto_fit:
            self._fit_debounce.stop()
            self._fit_debounce.start()

    def _on_canvas_context_menu(self, pos):
        menu = QtWidgets.QMenu(self)
        menu.setStyleSheet("""
            QMenu {
                background-color: #2b2b2b;
                border: 1px solid #3a3a3a;
                border-radius: 6px;
                padding: 4px;
            }
            QMenu::item { padding: 6px 24px; color: #f0f0f0; }
            QMenu::item:selected { background-color: #2a3a4a; }
            QMenu::item:disabled { color: #666; }
        """)
        act = menu.addAction("Copy selected text")
        act.setEnabled(self._canvas.has_selection())
        chosen = menu.exec(self._canvas.mapToGlobal(pos))
        if chosen is act and act.isEnabled():
            self._canvas._copy_selection()

    def _render(self):
        if not self._nav_items:
            return

        # Invalidate every older pixel-preview callback before rebuilding the source snapshot.
        # Navigation can happen while the persistent filter worker is still rendering the previous
        # page. That worker intentionally cannot interrupt an in-progress PIL operation, so merely
        # replacing its queued task would leave the new page blocked behind the old render.
        # Retire a busy worker and give the new page a fresh worker instead.
        self._prepare_filter_preview_worker_for_new_source()

        if (self._actual_preview_output_path
                and self._actual_preview_page_index_for_current() is not None):
            self._render_actual_preview_page()
            return
        item = self._nav_items[self._nav_index]

        # Page Design is a true ordered PDF edit. For an anchored design, make the already-designed
        # PDF page authoritative from the first frame. This gives the dummy viewer the exact visual
        # state and the exact selectable text layer (including watermark/page number), and prevents
        # later filter/stretch callbacks from replacing it with an image-only approximation.
        if (not (self._embedded and self._filter_preview_config is not None)
                and _page_design_has_any(item)
                and _page_design_anchor_state(item) is not None):
            try:
                # Render the exact PDF at the same zoom that the canvas uses.  The previous
                # implementation kept this call at a minimum of 72 DPI, so a fitted page
                # (for example zoom=0.62) was rendered at 1.0 px/pt while its text hitboxes
                # were interpreted at 0.62 px/pt.  The visible page and selectable boxes then
                # occupied different coordinate systems.
                render_zoom = max(0.15, min(8.0, float(self._zoom)))
                payload = _page_design_ordered_render_payload(
                    item, render_zoom * 72.0, apply_filters=True)
                if payload is None:
                    raise RuntimeError("Could not render the ordered Page Design page.")
                image, page_size, ordered_words, ordered_links = payload
                qpix = _pil_to_qpixmap(image)
                if qpix.isNull():
                    raise RuntimeError("Could not convert the ordered Page Design render to a pixmap.")
                # Use the actual PDF-render density represented by the pixels, rather than
                # assuming the requested zoom survived all rasterization/rounding.  This is the
                # invariant the hit-testing layer needs: page-point rectangles multiplied by
                # this scale must land on the pixels that are actually drawn.
                canvas_scale = render_zoom
                try:
                    if float(page_size[0]) > 0 and qpix.width() > 0:
                        canvas_scale_x = float(qpix.width()) / float(page_size[0])
                    else:
                        canvas_scale_x = render_zoom
                    if float(page_size[1]) > 0 and qpix.height() > 0:
                        canvas_scale_y = float(qpix.height()) / float(page_size[1])
                    else:
                        canvas_scale_y = render_zoom
                    canvas_scale = (canvas_scale_x + canvas_scale_y) / 2.0
                    if not math.isfinite(canvas_scale) or canvas_scale <= 0:
                        canvas_scale = render_zoom
                except Exception:
                    canvas_scale = render_zoom
                self._source_page_pt_size = tuple(page_size)
                self._page_pt_size = tuple(page_size)
                self._source_qpixmap = QtGui.QPixmap(qpix)
                self._source_qimage = qpix.toImage().convertToFormat(QtGui.QImage.Format.Format_RGBA8888)
                self._source_words_pt = list(ordered_words)
                self._source_zoom = float(self._zoom)
                self._base_qpixmap = QtGui.QPixmap(qpix)
                self._base_qimage = QtGui.QImage(self._source_qimage)
                self._base_words_pt = list(ordered_words)
                self._last_pixel_preview_qpixmap = None
                self._last_pixel_preview_words_pt = []
                self._last_pixel_preview_config = _entry_filter_config(item)
                self._last_pixel_preview_zoom = float(self._zoom)
                self._filter_preview_config = _entry_filter_config(item)
                self._filter_preview_generation += 1
                if self._actual_filter_preview_enabled:
                    self._clear_actual_preview_file()
                    self._cancel_actual_preview_job(remove_output=True)
                self._canvas.set_content(qpix, ordered_words, canvas_scale, ordered_links)
                self._canvas.setFixedSize(qpix.size())
                self._canvas.updateGeometry()
                if self._actual_filter_preview_enabled:
                    # The ordered PDF is already exact, including any stored filter. Do not queue a
                    # second generic filter preview over this frame. The exact worker is still used
                    # when a later page has an active filter but no design anchor.
                    pass
                return
            except Exception:
                # Fall through to the legacy path for defensive compatibility with malformed older entries.
                pass

        pdf_path = item['source_pdf']
        page_idx = item['original_idx']
        rotation = int(item.get('rotation', 0))
        crop = item.get('crop')
        flip_h = bool(item.get('flip_h', False))
        flip_v = bool(item.get('flip_v', False))
        ocr_blocks = item.get('ocr') if item.get('ocr_done') or item.get('ocr') else None

        try:
            with fitz.open(pdf_path) as doc:
                page = doc.load_page(page_idx)
                orig_rot = page.rotation

                if ocr_blocks:
                    try:
                        _insert_ocr_text(page, ocr_blocks)
                    except Exception:
                        pass

                if flip_h or flip_v:
                    # Match the PDF-native page transformation used by saving: the
                    # flip is applied to the page content itself before MuPDF renders
                    # the frame. This avoids a QPixmap-only approximation and keeps
                    # flip behavior aligned with crop/rotation and the saved PDF.
                    apply_entry_to_page(page, item, src_rot=orig_rot)
                else:
                    if crop:
                        try:
                            under = fitz.Rect(*crop)
                            try:
                                under = under & page.mediabox
                            except Exception:
                                pass
                            if not under.is_empty:
                                page.set_cropbox(under)
                        except Exception:
                            pass

                    page.set_rotation((orig_rot + rotation) % 360)

                self._source_page_pt_size = (
                    float(page.rect.width), float(page.rect.height))
                self._page_pt_size = self._source_page_pt_size

                zoom = self._zoom
                mat = fitz.Matrix(zoom, zoom)
                pix = page.get_pixmap(matrix=mat, alpha=False)
                img = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
                qpix = _pil_to_qpixmap(img)

                words_pt = []
                links_pt = []
                try:
                    rotation_matrix = page.rotation_matrix
                    for (wx0, wy0, wx1, wy1, t, *_rest) in page.get_text("words"):
                        wr = fitz.Rect(wx0, wy0, wx1, wy1) * rotation_matrix
                        words_pt.append((wr.x0, wr.y0, wr.x1, wr.y1, t))
                    for link in page.get_links():
                        uri = str(link.get("uri") or "").strip()
                        if not uri:
                            continue
                        lr = fitz.Rect(link.get("from")) * rotation_matrix
                        links_pt.append((float(lr.x0), float(lr.y0),
                                         float(lr.x1), float(lr.y1), uri))
                except Exception:
                    pass

                page.set_rotation(orig_rot)
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "Open Failed", str(e))
            self.reject()
            return

        if flip_h or flip_v:
            # PDF content transforms are reflected by MuPDF's text extraction, so
            # word boxes must not be flipped a second time. Link annotations are
            # separate from page content streams; retain the viewer's display-space
            # hit-test mapping for them.
            W, H = self._page_pt_size
            new_links = []
            for (x0, y0, x1, y1, uri) in links_pt:
                nx0, nx1 = (W - x1, W - x0) if flip_h else (x0, x1)
                ny0, ny1 = (H - y1, H - y0) if flip_v else (y0, y1)
                new_links.append((nx0, ny0, nx1, ny1, uri))
            links_pt = new_links

        # Keep the clean source render separately. Exact PDF previews replace only the
        # currently displayed snapshot and never destroy this source snapshot.
        self._source_qpixmap = QtGui.QPixmap(qpix)
        try:
            self._source_qimage = qpix.toImage().convertToFormat(QtGui.QImage.Format.Format_RGBA8888)
        except Exception:
            self._source_qimage = QtGui.QImage()
        self._source_words_pt = list(words_pt)
        self._source_zoom = float(self._zoom)

        # A navigation/geometry render starts a fresh page; never carry the previous page's
        # pixel preview across to the new source page.
        self._last_pixel_preview_qpixmap = None
        self._last_pixel_preview_words_pt = []
        self._last_pixel_preview_config = None
        self._last_pixel_preview_zoom = None

        self._base_qpixmap = QtGui.QPixmap(qpix)
        self._base_qimage = QtGui.QImage(self._source_qimage)
        self._base_words_pt = list(words_pt)

        # Standalone dummy viewers must follow the filter configuration stored on the CURRENT
        # navigation item. Reusing _filter_preview_config here would carry the previous page's filter
        # into the next page and is exactly what caused "unfiltered while navigating, filtered after
        # the delayed pikepdf preview". Embedded Apply Filters intentionally keeps its live dialog
        # configuration in _filter_preview_config, so only standalone mode uses the item as authority.
        if self._actual_filter_preview_enabled:
            preview_cfg = _entry_filter_config(item)
        else:
            preview_cfg = (self._filter_preview_config
                           if self._filter_preview_config is not None
                           else _entry_filter_config(item))
        self._filter_preview_config = _normalize_filter_config(preview_cfg)

        # IMPORTANT: standalone dummy viewers are already visible when Next/Previous calls _render().
        # Painting the clean source here and waiting for the asynchronous filter worker creates a
        # visible "unfiltered -> filtered" flash. When an active filter exists, generate the existing
        # fast PIL preview synchronously from the immutable clean source BEFORE publishing the new page
        # to the canvas. This makes navigation behave like opening the filtered page directly.
        display_qpix = qpix
        display_words_pt = list(words_pt)
        display_links_pt = list(links_pt)
        # Canvas hit-testing uses point-space word rectangles multiplied by this scale.
        # Keep that scale tied to the actual rendered frame whenever an ordered PDF frame
        # is substituted below; ordinary legacy frames continue to use the viewer zoom.
        display_canvas_scale = float(self._zoom)
        fast_filter_ready = False
        if (self._actual_filter_preview_enabled
                and _filter_config_active(self._filter_preview_config)):
            try:
                display_qpix = _apply_filter_to_qpixmap(qpix, self._filter_preview_config)
                if display_qpix is None or display_qpix.isNull():
                    display_qpix = qpix
                else:
                    fast_filter_ready = True
            except Exception:
                display_qpix = qpix

        display_qpix, display_words_pt, display_links_pt = (
            self._stretch_preview_frame(
                display_qpix, display_words_pt, display_links_pt))

        # Page Design follows its recorded position in the edit sequence. For entries that were
        # designed before later geometry edits, render the ordered PyMuPDF page so flips/rotations
        # (and later stretches) transform the already-designed content instead of merely replacing
        # the background preview. Legacy entries keep the historical lightweight overlay path.
        if (_page_design_has_any(item) and _page_design_anchor_state(item) is not None):
            # Keep the embedded/legacy branch on the same exact payload contract as the
            # standalone dummy viewer: the PDF image and its selectable word layer must be
            # generated from one render and at one density.  Previously this branch rendered
            # the ordered page at a minimum of 72 DPI and then overlaid point-space words on a
            # fitted canvas, creating the same image-vs-hitbox mismatch.
            render_zoom = max(0.15, min(8.0, float(self._zoom)))
            ordered_payload = _page_design_ordered_render_payload(
                item, render_zoom * 72.0, apply_filters=True)
            if ordered_payload is not None:
                ordered_image, ordered_size, ordered_words, ordered_links = ordered_payload
                display_qpix = _pil_to_qpixmap(ordered_image)
                if display_qpix is not None and not display_qpix.isNull():
                    self._page_pt_size = tuple(ordered_size)
                    display_words_pt = list(ordered_words)
                    display_links_pt = list(ordered_links)
                    try:
                        sx = float(display_qpix.width()) / float(ordered_size[0])
                        sy = float(display_qpix.height()) / float(ordered_size[1])
                        display_canvas_scale = (sx + sy) / 2.0
                        if not math.isfinite(display_canvas_scale) or display_canvas_scale <= 0:
                            display_canvas_scale = render_zoom
                    except Exception:
                        display_canvas_scale = render_zoom
        else:
            display_qpix = _page_design_overlay_exact_qpixmap(
                display_qpix, self._page_pt_size, item)
            display_words_pt.extend(_page_design_ordered_words_pt(item) if _page_design_has_any(item) else [])
        if fast_filter_ready:
            self._last_pixel_preview_qpixmap = QtGui.QPixmap(display_qpix)
            self._last_pixel_preview_words_pt = list(display_words_pt)
            self._last_pixel_preview_config = self._filter_preview_config
            self._last_pixel_preview_zoom = float(self._zoom)
            self._filter_preview_last_config = self._filter_preview_config

        self._canvas.set_content(
            display_qpix, display_words_pt, display_canvas_scale, display_links_pt)
        self._canvas.setFixedSize(display_qpix.size())
        self._canvas.updateGeometry()

        # For the standalone viewer the synchronous frame above is already the current fast pixel
        # preview, so don't queue a duplicate worker render. Apply Filters (embedded viewer) still
        # uses _request_filter_preview() asynchronously through set_filter_preview().
        if not (self._actual_filter_preview_enabled
                and _filter_config_active(self._filter_preview_config)
                and self._last_pixel_preview_qpixmap is not None):
            self._request_filter_preview(self._filter_preview_config)

        if self._actual_filter_preview_enabled:
            self._schedule_actual_preview_start()

    def _stretch_preview_frame(self, pixmap, words_pts=None, links_pts=None):
        """Stretch a fast preview and its hit-test geometry to the item's target ratio."""
        words = list(words_pts or [])
        links = list(links_pts or [])
        if pixmap is None or pixmap.isNull() or not self._nav_items:
            return pixmap, words, links
        try:
            ratio = self._nav_items[self._nav_index].get("stretch_ratio")
            if ratio is None:
                self._page_pt_size = tuple(self._source_page_pt_size)
                return pixmap, words, links
            ratio = float(ratio)
            source_width, source_height = map(
                float, self._source_page_pt_size)
            if (not math.isfinite(ratio) or ratio <= 0
                    or not math.isfinite(source_width)
                    or not math.isfinite(source_height)
                    or source_width <= 0 or source_height <= 0):
                self._page_pt_size = tuple(self._source_page_pt_size)
                return pixmap, words, links

            target_width, target_height = calculate_stretch_dimensions(
                source_width, source_height, ratio)
            sx = target_width / source_width
            sy = target_height / source_height
            target_size = QtCore.QSize(
                max(1, int(round(pixmap.width() * sx))),
                max(1, int(round(pixmap.height() * sy))))
            if target_size != pixmap.size():
                pixmap = pixmap.scaled(
                    target_size, QtCore.Qt.AspectRatioMode.IgnoreAspectRatio,
                    QtCore.Qt.TransformationMode.SmoothTransformation)

            if not (math.isclose(sx, 1.0, rel_tol=0.0, abs_tol=1e-12)
                    and math.isclose(sy, 1.0, rel_tol=0.0, abs_tol=1e-12)):
                words = [(x0 * sx, y0 * sy, x1 * sx, y1 * sy, text)
                         for x0, y0, x1, y1, text in words]
                links = [(x0 * sx, y0 * sy, x1 * sx, y1 * sy, uri)
                         for x0, y0, x1, y1, uri in links]
            self._page_pt_size = (target_width, target_height)
            return pixmap, words, links
        except Exception:
            self._page_pt_size = tuple(self._source_page_pt_size)
            return pixmap, words, links

    def _set_actual_preview_status(self, visible):
        if visible:
            _show_view_status_toast(self, "Rendering actual filter results...")
        else:
            _hide_view_status_toast(self)

    def _queue_retired_actual_preview_process(self, proc, candidate):
        if proc is None:
            self._cleanup_actual_preview_path(candidate)
            return
        self._actual_preview_retired_jobs.append({"process": proc, "candidate": candidate})
        timer = self._actual_preview_reaper_timer
        if timer is not None and not timer.isActive():
            timer.start()

    def _reap_actual_preview_processes(self):
        jobs = getattr(self, "_actual_preview_retired_jobs", [])
        if not jobs:
            timer = getattr(self, "_actual_preview_reaper_timer", None)
            if timer is not None:
                timer.stop()
            return
        survivors = []
        for job in jobs:
            proc = job.get("process")
            candidate = job.get("candidate")
            try:
                alive = proc.is_alive()
            except Exception:
                alive = False
            if alive:
                survivors.append(job)
                continue
            try:
                proc.join(timeout=0)
            except Exception:
                pass
            try:
                if hasattr(proc, "close"):
                    proc.close()
            except Exception:
                pass
            self._cleanup_actual_preview_path(candidate)
        self._actual_preview_retired_jobs = survivors
        if not survivors:
            timer = getattr(self, "_actual_preview_reaper_timer", None)
            if timer is not None:
                timer.stop()

    def _drain_retired_actual_preview_processes(self, timeout=1.5):
        jobs = getattr(self, "_actual_preview_retired_jobs", [])
        if not jobs:
            return
        for job in jobs:
            proc = job.get("process")
            candidate = job.get("candidate")
            try:
                if proc.is_alive():
                    proc.join(timeout=max(0.0, float(timeout)))
            except Exception:
                pass
            try:
                if proc.is_alive():
                    proc.terminate()
                    proc.join(timeout=0.5)
            except Exception:
                pass
            try:
                if hasattr(proc, "close"):
                    proc.close()
            except Exception:
                pass
            self._cleanup_actual_preview_path(candidate)
        self._actual_preview_retired_jobs = []
        timer = getattr(self, "_actual_preview_reaper_timer", None)
        if timer is not None:
            timer.stop()

    def _schedule_actual_preview_start(self):
        if not self._actual_filter_preview_enabled or not self._nav_items:
            return
        if self._actual_preview_output_path is not None:
            return
        timer = self._actual_preview_idle_timer
        if timer is None:
            return
        timer.stop()
        timer.start()

    def _start_actual_preview_for_current_page(self):
        if not self._actual_filter_preview_enabled or not self._nav_items:
            return
        if self._actual_preview_process is not None:
            return
        item = copy.deepcopy(self._nav_items[self._nav_index])
        cfg = _entry_filter_config(item)
        if not _filter_config_active(cfg):
            self._set_actual_preview_status(False)
            return

        self._actual_preview_generation += 1
        generation = self._actual_preview_generation
        current_nav_index = int(self._nav_index)
        self._clear_actual_preview_file()

        output_path = os.path.abspath(os.path.join(
            TEMP_FOLDER, f"exact_filter_preview_{uuid.uuid4().hex}.pdf"))
        recv_conn = None
        send_conn = None
        try:
            os.makedirs(TEMP_FOLDER, exist_ok=True)
            ctx = multiprocessing.get_context("spawn")
            recv_conn, send_conn = ctx.Pipe(duplex=False)
            proc = ctx.Process(
                target=_actual_filter_preview_process_worker,
                args=([item], cfg, output_path, send_conn),
            )
            proc.daemon = True
            proc.start()
            try:
                send_conn.close()
            except Exception:
                pass
        except Exception:
            try:
                if recv_conn is not None:
                    recv_conn.close()
            except Exception:
                pass
            try:
                if os.path.exists(output_path):
                    os.remove(output_path)
            except Exception:
                pass
            self._set_actual_preview_status(False)
            return

        self._actual_preview_process = proc
        self._actual_preview_conn = recv_conn
        self._actual_preview_output_path = None
        self._actual_preview_for_nav_index = current_nav_index
        self._actual_preview_job_output_candidate = output_path
        self._actual_preview_job_generation = generation
        self._set_actual_preview_status(True)
        if self._actual_preview_poll_timer is not None:
            self._actual_preview_poll_timer.start()

    def _poll_actual_preview_job(self):
        proc = self._actual_preview_process
        conn = self._actual_preview_conn
        if proc is None:
            if self._actual_preview_poll_timer is not None:
                self._actual_preview_poll_timer.stop()
            return

        result = None
        try:
            if conn is not None and conn.poll():
                result = conn.recv()
        except (EOFError, OSError):
            result = None

        if result is not None:
            kind = result[0] if len(result) > 0 else "error"
            output_path = result[1] if len(result) > 1 else ""
            job_generation = int(getattr(self, "_actual_preview_job_generation", -1))
            expected_generation = int(self._actual_preview_generation)
            expected_nav = int(getattr(self, "_actual_preview_for_nav_index", -1))
            current_nav = int(self._nav_index)
            candidate = getattr(self, "_actual_preview_job_output_candidate", None)

            self._actual_preview_process = None
            self._actual_preview_conn = None
            self._actual_preview_job_output_candidate = None
            if conn is not None:
                try:
                    conn.close()
                except Exception:
                    pass
            if self._actual_preview_poll_timer is not None:
                self._actual_preview_poll_timer.stop()

            if (kind == "ok"
                    and job_generation == expected_generation
                    and expected_nav == current_nav
                    and self._actual_filter_preview_enabled
                    and output_path
                    and os.path.isfile(output_path)):
                # The child has sent the completed artifact. It may still be executing the
                # final close/send cleanup, so keep it alive in the reaper without blocking.
                try:
                    if proc.is_alive():
                        self._queue_retired_actual_preview_process(proc, None)
                    else:
                        proc.join(timeout=0)
                        if hasattr(proc, "close"):
                            proc.close()
                except Exception:
                    self._queue_retired_actual_preview_process(proc, None)
                if self.set_actual_preview_pdf(output_path, nav_page_map={current_nav: 0}):
                    self._set_actual_preview_status(False)
                    return
                self._cleanup_actual_preview_path(output_path)
                self._set_actual_preview_status(False)
                return

            # Error/stale result: wait for child death before removing its output artifact.
            self._queue_retired_actual_preview_process(proc, output_path or candidate)
            self._set_actual_preview_status(False)
            return

        try:
            alive = proc.is_alive()
        except Exception:
            alive = False
        if not alive:
            candidate = getattr(self, "_actual_preview_job_output_candidate", "")
            try:
                proc.join(timeout=0)
            except Exception:
                pass
            try:
                if hasattr(proc, "close"):
                    proc.close()
            except Exception:
                pass
            self._actual_preview_process = None
            self._actual_preview_conn = None
            self._actual_preview_job_output_candidate = None
            if self._actual_preview_poll_timer is not None:
                self._actual_preview_poll_timer.stop()
            self._cleanup_actual_preview_path(candidate)
            self._set_actual_preview_status(False)

    def _close_actual_preview_process_handles(self, join_timeout=0.5, retain_candidate=True):
        proc = self._actual_preview_process
        conn = self._actual_preview_conn
        candidate = getattr(self, "_actual_preview_job_output_candidate", None)
        self._actual_preview_process = None
        self._actual_preview_conn = None
        self._actual_preview_job_output_candidate = None
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        if proc is None:
            if not retain_candidate:
                self._cleanup_actual_preview_path(candidate)
            return candidate
        try:
            if not proc.is_alive():
                proc.join(timeout=0)
                if hasattr(proc, "close"):
                    proc.close()
                if not retain_candidate:
                    self._cleanup_actual_preview_path(candidate)
            elif float(join_timeout) > 0:
                proc.join(timeout=max(0.0, float(join_timeout)))
                if not proc.is_alive() and hasattr(proc, "close"):
                    proc.close()
                elif proc.is_alive() and retain_candidate:
                    self._queue_retired_actual_preview_process(proc, candidate)
                elif proc.is_alive():
                    self._queue_retired_actual_preview_process(proc, candidate)
        except Exception:
            self._queue_retired_actual_preview_process(proc, candidate)
        return candidate

    def _cancel_actual_preview_job(self, remove_output=True):
        self._actual_preview_generation += 1
        if self._actual_preview_idle_timer is not None:
            self._actual_preview_idle_timer.stop()
        if self._actual_preview_poll_timer is not None:
            self._actual_preview_poll_timer.stop()

        proc = self._actual_preview_process
        conn = self._actual_preview_conn
        candidate = getattr(self, "_actual_preview_job_output_candidate", None)
        self._actual_preview_process = None
        self._actual_preview_conn = None
        self._actual_preview_job_output_candidate = None

        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        if proc is None:
            if remove_output:
                self._cleanup_actual_preview_path(candidate)
        else:
            try:
                alive = proc.is_alive()
            except Exception:
                alive = False
            try:
                if alive:
                    proc.terminate()
                    self._queue_retired_actual_preview_process(proc, candidate if remove_output else None)
                else:
                    proc.join(timeout=0)
                    if hasattr(proc, "close"):
                        proc.close()
                    if remove_output:
                        self._cleanup_actual_preview_path(candidate)
            except Exception:
                self._queue_retired_actual_preview_process(proc, candidate if remove_output else None)

        self._set_actual_preview_status(False)

    def _cleanup_actual_preview_path(self, path):
        if not path:
            return
        try:
            path = os.path.abspath(str(path))
        except Exception:
            return
        for candidate in (path, path + ".base.pdf"):
            try:
                if os.path.isfile(candidate):
                    os.remove(candidate)
            except Exception:
                pass

    def _clear_actual_preview_file(self):
        path = self._actual_preview_output_path
        self._actual_preview_output_path = None
        self._actual_preview_for_nav_index = None
        self._cleanup_actual_preview_path(path)

    def set_actual_preview_pdf(self, pdf_path, nav_page_map=None):
        """Adopt an exact-preview PDF already rendered by an external process."""
        if not pdf_path or not os.path.isfile(pdf_path):
            return False
        if self._actual_preview_poll_timer is not None:
            self._actual_preview_poll_timer.stop()
        self._cancel_actual_preview_job(remove_output=False)
        self._clear_actual_preview_file()
        # In the embedded Apply Filters viewer the PIL worker may still have an older
        # frame queued. Invalidate that frame before the exact PDF becomes authoritative.
        self._filter_preview_generation += 1
        self._filter_preview_last_config = None
        self._actual_preview_output_path = os.path.abspath(str(pdf_path))
        if nav_page_map is None:
            nav_page_map = list(range(len(self._nav_items)))
        if isinstance(nav_page_map, dict):
            self._actual_preview_page_map = {int(k): int(v) for k, v in nav_page_map.items()}
        else:
            self._actual_preview_page_map = [int(v) for v in nav_page_map]
        self._actual_preview_for_nav_index = self._nav_index
        self._render_actual_preview_page()
        return True

    def clear_actual_preview(self, restore_source=True):
        self._cancel_actual_preview_job(remove_output=True)
        self._clear_actual_preview_file()
        self._filter_preview_generation += 1
        self._actual_preview_page_map = []
        self._actual_preview_for_nav_index = None
        self._set_actual_preview_status(False)
        if restore_source:
            self.restore_source_preview()

    def has_actual_preview(self):
        return bool(self._actual_preview_output_path and
                    self._actual_preview_page_index_for_current() is not None)

    def restore_source_preview(self):
        """Restore the current fast source frame after an exact filter preview is cleared."""
        # For an ordered Page Design entry the stored source snapshot may have been produced
        # before a later geometry/filter preview started. Rebuild the current designed page
        # directly from the canonical PDF state instead of compositing a potentially stale raster
        # design layer over the old snapshot. This makes the first frame after clearing an exact
        # preview identical in geometry to the later authoritative frame.
        if self._nav_items:
            try:
                item = self._nav_items[self._nav_index]
                if (_page_design_has_any(item)
                        and _page_design_anchor_state(item) is not None):
                    z = max(0.15, min(8.0, float(self._zoom)))
                    payload = _page_design_ordered_render_payload(
                        item, z * 72.0, apply_filters=True)
                    if payload is not None:
                        image, page_size, words_pt, links_pt = payload
                        qpix = _pil_to_qpixmap(image)
                        if qpix is not None and not qpix.isNull():
                            try:
                                sx = float(qpix.width()) / max(1.0, float(page_size[0]))
                                sy = float(qpix.height()) / max(1.0, float(page_size[1]))
                                canvas_scale = (sx + sy) / 2.0
                            except Exception:
                                canvas_scale = z
                            if not math.isfinite(canvas_scale) or canvas_scale <= 0:
                                canvas_scale = z
                            self._source_page_pt_size = tuple(page_size)
                            self._page_pt_size = tuple(page_size)
                            self._source_qpixmap = QtGui.QPixmap(qpix)
                            self._source_qimage = qpix.toImage().convertToFormat(QtGui.QImage.Format.Format_RGBA8888)
                            self._source_words_pt = list(words_pt)
                            self._source_zoom = float(self._zoom)
                            self._base_qpixmap = QtGui.QPixmap(qpix)
                            self._base_qimage = QtGui.QImage(self._source_qimage)
                            self._base_words_pt = list(words_pt)
                            self._canvas.set_content(qpix, words_pt, canvas_scale, links_pt)
                            self._canvas.setFixedSize(qpix.size())
                            self._canvas.updateGeometry()
                            return True
            except Exception:
                pass

        if (self._source_qpixmap is not None
                and not self._source_qpixmap.isNull()
                and self._source_zoom is not None
                and abs(float(self._source_zoom) - float(self._zoom)) <= 1e-6):
            source_pixmap, source_words, _source_links = self._stretch_preview_frame(
                QtGui.QPixmap(self._source_qpixmap), self._source_words_pt, [])
            source_pixmap = _page_design_overlay_exact_qpixmap(
                source_pixmap, self._page_pt_size, self._nav_items[self._nav_index])
            self._base_qpixmap = QtGui.QPixmap(source_pixmap)
            self._base_qimage = QtGui.QImage(
                source_pixmap.toImage().convertToFormat(QtGui.QImage.Format.Format_RGBA8888))
            self._base_words_pt = list(source_words)
            self._canvas.set_content(self._base_qpixmap, self._base_words_pt, self._zoom)
            self._canvas.setFixedSize(self._base_qpixmap.size())
            self._canvas.updateGeometry()
            return True
        self._render()
        return False

    def _actual_preview_page_index_for_current(self):
        page_map = getattr(self, "_actual_preview_page_map", [])
        if isinstance(page_map, dict):
            try:
                return int(page_map[self._nav_index])
            except (KeyError, TypeError, ValueError):
                return None
        try:
            if self._nav_index < 0 or self._nav_index >= len(page_map):
                return None
            return int(page_map[self._nav_index])
        except (TypeError, ValueError, IndexError):
            return None

    def _render_actual_preview_page(self):
        path = self._actual_preview_output_path
        if not path or not os.path.isfile(path):
            return
        page_index = self._actual_preview_page_index_for_current()
        if page_index is None:
            return
        try:
            with fitz.open(path) as doc:
                if page_index < 0 or page_index >= doc.page_count:
                    raise IndexError("Exact preview page index is out of range.")
                page = doc.load_page(page_index)
                self._page_pt_size = (page.rect.width, page.rect.height)
                pix = page.get_pixmap(matrix=fitz.Matrix(self._zoom, self._zoom), alpha=False)
                img = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
                qpix = _pil_to_qpixmap(img)
                words_pt = _pdf_page_words_in_display_space(page)
        except Exception:
            return

        # Exact output is display-only. Keep the clean source snapshot and the most recent pixel
        # preview untouched so a later interaction can switch back without flashing the original.
        self._canvas.set_content(qpix, words_pt, self._zoom)
        self._canvas.setFixedSize(qpix.size())
        self._canvas.updateGeometry()

    def set_filter_preview(self, config):
        cfg = _normalize_filter_config(config)
        self._filter_preview_config = cfg
        self._request_filter_preview(cfg)

    def _restore_last_pixel_preview(self):
        qpix = self._last_pixel_preview_qpixmap
        zoom = self._last_pixel_preview_zoom
        if (qpix is None or qpix.isNull() or zoom is None
                or abs(float(zoom) - float(self._zoom)) > 1e-6):
            return False
        self._base_qpixmap = QtGui.QPixmap(qpix)
        self._base_qimage = QtGui.QImage(qpix.toImage().convertToFormat(QtGui.QImage.Format.Format_RGBA8888))
        self._base_words_pt = list(self._last_pixel_preview_words_pt)
        self._canvas.set_content(self._base_qpixmap, self._base_words_pt, self._zoom)
        self._canvas.setFixedSize(self._base_qpixmap.size())
        self._canvas.updateGeometry()
        return True

    def _prepare_filter_preview_worker_for_new_source(self):
        """Invalidate stale pixel jobs and replace a busy worker before rendering a new source."""
        self._filter_preview_generation += 1

        thread = getattr(self, "_filter_preview_thread", None)
        busy = False
        try:
            busy = bool(thread is not None and thread.is_busy())
        except Exception:
            busy = False

        if not busy:
            return

        # The old worker may be inside a CPU-bound PIL operation and cannot be safely interrupted.
        # Ask it to stop after its current operation, then immediately give the new source its own
        # worker so the new pixel preview does not wait behind the previous page. The global QThread
        # registry retains the retired worker until Qt emits finished.
        try:
            thread.stop()
        except Exception:
            pass

        try:
            replacement = _FilterPreviewRenderThread(self)
            replacement.result_signal.connect(self._on_filter_preview_ready)
            replacement.start()
            self._filter_preview_thread = replacement
        except Exception:
            # Falling back to the existing worker is still correct; its next submit() will replace
            # the queued task and the generation check will discard any stale callback.
            self._filter_preview_thread = thread

    def _compose_embedded_filter_preview(self, pixmap, config):
        """Compose the embedded fast preview from the canonical current-geometry PDF frame.

        The old fast path accepted the caller's raster snapshot as the geometry authority and
        then painted Page Design separately. That is exactly where an already-applied design could
        jump back to its design-time coordinates after a later rotate/crop/flip.

        The fast path now uses the ordered PyMuPDF renderer *without the active filter* as its
        geometry authority. This is still a lightweight PDF render (no pikepdf filter processing),
        but it gives the raster filter preview the same current crop/flip/rotation/stretch/design
        coordinate system as the authoritative result. PIL is then used only for the interactive
        filter approximation:
          * unchanged design-time filter: filter the designless current page, then overlay the
            transformed design layer (filter -> design);
          * changed/new filter: render the already-designed current page, then filter it
            (design -> filter);
          * no active filter: keep the already-designed current page.
        """
        if pixmap is None or pixmap.isNull() or not self._nav_items:
            return pixmap
        item = self._nav_items[self._nav_index]
        if not (_page_design_has_any(item)
                and _page_design_anchor_state(item) is not None):
            return pixmap
        cfg = _normalize_filter_config(config)
        anchor = _page_design_anchor_state(item) or {}
        anchor_filter = _normalize_filter_config(anchor.get("filter_config"))
        same_filter = _page_design_filter_state_equal(cfg, anchor_filter)

        try:
            z = max(0.15, min(8.0, float(self._zoom)))

            # Always establish the base from the current canonical page geometry. This avoids
            # compositing an old design-time raster over a newly rotated/cropped fast frame.
            base_payload = _page_design_ordered_render_payload(
                item, z * 72.0, apply_filters=False,
                design_override={
                    "page_numbering": None,
                    "page_border": None,
                    "page_watermark": None,
                } if (same_filter and _filter_config_active(cfg)) else _PAGE_DESIGN_UNSET)

            if base_payload is None:
                raise RuntimeError("Could not build the canonical fast-preview base page.")
            base_image, base_size, _base_words, _base_links = base_payload
            base_qpix = _pil_to_qpixmap(base_image)
            if base_qpix is None or base_qpix.isNull():
                raise RuntimeError("Could not convert the canonical fast-preview base page.")

            if same_filter and _filter_config_active(cfg):
                # Existing filter is pre-design in the recorded timeline. Apply the interactive
                # filter to the exact current-geometry background, then place the already-transformed
                # design layer on top. The visual location therefore cannot revert to design time.
                filtered = _apply_filter_to_qpixmap(base_qpix, cfg)
                if filtered is None or filtered.isNull():
                    filtered = base_qpix
                return _page_design_overlay_exact_qpixmap(
                    filtered, base_size, item)

            # No active pre-existing filter: the canonical base already contains the transformed
            # design at its current location. A newly changed filter is a post-design edit, so the
            # raster approximation is intentionally applied to the whole designed frame.
            designed = base_qpix
            if not _filter_config_active(cfg):
                return designed
            filtered = _apply_filter_to_qpixmap(designed, cfg)
            return filtered if filtered is not None and not filtered.isNull() else designed
        except Exception:
            # Preserve the existing frame if the fast canonical render is unavailable. The delayed
            # exact preview remains authoritative and will replace it when it completes.
            return pixmap

    def _request_filter_preview(self, config):
        cfg = _normalize_filter_config(config)
        source_image = self._source_qimage
        source_pixmap = self._source_qpixmap
        source_words = self._source_words_pt
        if source_pixmap is None or source_pixmap.isNull() or source_image.isNull():
            return

        # Never replace the currently displayed page with the clean source merely because a
        # new filter frame is being rendered. For an active filter, keep the latest completed
        # pixel preview visible until the newest frame arrives. This removes original/filter flicker
        # during rapid slider movement and button changes.
        self._filter_preview_generation += 1
        generation = self._filter_preview_generation
        if not _filter_config_active(cfg):
            self._filter_preview_last_config = cfg
            display_pixmap, display_words, _display_links = (
                self._stretch_preview_frame(
                    QtGui.QPixmap(source_pixmap), source_words, []))
            display_pixmap = self._compose_embedded_filter_preview(
                display_pixmap, cfg)
            self._base_qpixmap = QtGui.QPixmap(display_pixmap)
            self._base_qimage = QtGui.QImage(source_image)
            self._base_words_pt = list(display_words)
            self._last_pixel_preview_qpixmap = None
            self._last_pixel_preview_words_pt = []
            self._last_pixel_preview_config = cfg
            self._last_pixel_preview_zoom = float(self._zoom)
            self._canvas.set_content(self._base_qpixmap, self._base_words_pt, self._zoom)
            self._canvas.setFixedSize(self._base_qpixmap.size())
            self._canvas.updateGeometry()
            return

        if not self._restore_last_pixel_preview():
            # Only on first load (before any filtered frame exists) is there no previous pixel
            # frame to retain. The clean source is shown until the first filtered frame completes.
            display_pixmap, display_words, _display_links = (
                self._stretch_preview_frame(
                    QtGui.QPixmap(source_pixmap), source_words, []))
            display_pixmap = self._compose_embedded_filter_preview(
                display_pixmap, cfg)
            self._base_qpixmap = QtGui.QPixmap(display_pixmap)
            self._base_qimage = QtGui.QImage(source_image)
            self._base_words_pt = list(display_words)
            self._canvas.set_content(self._base_qpixmap, self._base_words_pt, self._zoom)
            self._canvas.setFixedSize(self._base_qpixmap.size())
            self._canvas.updateGeometry()

        # The worker always receives the immutable clean source image, never the displayed/exact frame.
        self._base_qimage = QtGui.QImage(source_image)
        self._filter_preview_thread.submit(generation, self._base_qimage, cfg)

    def _on_filter_preview_ready(self, generation, qimage, error_text):
        if int(generation) != int(self._filter_preview_generation):
            return
        if qimage is None or qimage.isNull():
            return
        # Once an exact PDF preview has been adopted, late PIL callbacks must never
        # replace it with an older pixel approximation or the un-stretched source.
        if (self._actual_preview_output_path
                and self._actual_preview_page_index_for_current() is not None):
            return
        qpix = QtGui.QPixmap.fromImage(qimage)
        qpix, preview_words, _preview_links = self._stretch_preview_frame(
            qpix, self._source_words_pt, [])
        qpix = self._compose_embedded_filter_preview(
            qpix, self._filter_preview_config)
        self._filter_preview_last_config = self._filter_preview_config
        self._last_pixel_preview_qpixmap = QtGui.QPixmap(qpix)
        self._last_pixel_preview_words_pt = list(preview_words)
        self._last_pixel_preview_config = self._filter_preview_config
        self._last_pixel_preview_zoom = float(self._zoom)
        self._base_qpixmap = QtGui.QPixmap(qpix)
        self._base_qimage = QtGui.QImage(
            qpix.toImage().convertToFormat(QtGui.QImage.Format.Format_RGBA8888))
        self._base_words_pt = list(preview_words)
        self._canvas.set_content(qpix, self._base_words_pt, self._zoom)
        self._canvas.setFixedSize(qpix.size())
        self._canvas.updateGeometry()

    def shutdown_filter_preview_thread(self, wait_ms=3000):
        """Stop the persistent live-filter preview worker before the viewer is destroyed."""
        thread = getattr(self, "_filter_preview_thread", None)
        if thread is None:
            return True
        stopped = _stop_qthread(
            thread,
            stop_callback=getattr(thread, "stop", None),
            timeout_ms=wait_ms,
            force_wait_ms=1500,
        )
        if stopped:
            self._filter_preview_thread = None
        # A stopped flag is important here: never discard the last Python reference
        # while QThread still reports itself running. The global registry also retains
        # the thread until Qt emits finished.
        return stopped

    def done(self, result):
        try:
            if self._actual_filter_preview_enabled:
                self.clear_actual_preview(restore_source=False)
                self._drain_retired_actual_preview_processes(timeout=0.8)
        except Exception:
            pass
        try:
            self.shutdown_filter_preview_thread()
        except Exception:
            pass
        super().done(result)

    def closeEvent(self, event):
        try:
            if self._actual_filter_preview_enabled:
                self.clear_actual_preview(restore_source=False)
                self._drain_retired_actual_preview_processes(timeout=0.8)
        except Exception:
            pass
        try:
            self.shutdown_filter_preview_thread()
        except Exception:
            pass
        super().closeEvent(event)

    def _set_zoom_percent(self, percent):
        try:
            percent = int(percent)
        except Exception:
            percent = 100
        percent = max(int(round(self._min_zoom * 100)),
                      min(int(round(self._max_zoom * 100)), percent))
        self._auto_fit = False
        self._fit_debounce.stop()
        new = percent / 100.0
        if abs(new - self._zoom) > 1e-6:
            self._zoom = new
            self._render()
        if hasattr(self, "_zoom_footer"):
            self._zoom_footer.set_zoom_factor(self._zoom)
        _show_view_toast(self, f"{int(round(self._zoom * 100))}%")

    def _zoom_in(self):
        self._auto_fit = False
        self._fit_debounce.stop()
        new = min(self._max_zoom, self._zoom * 1.25)
        if new != self._zoom:
            self._zoom = new
            self._render()
        if hasattr(self, "_zoom_footer"):
            self._zoom_footer.set_zoom_factor(self._zoom)
        _show_view_toast(self, f"{int(round(self._zoom * 100))}%")

    def _zoom_out(self):
        self._auto_fit = False
        self._fit_debounce.stop()
        new = max(self._min_zoom, self._zoom / 1.25)
        if new != self._zoom:
            self._zoom = new
            self._render()
        if hasattr(self, "_zoom_footer"):
            self._zoom_footer.set_zoom_factor(self._zoom)
        _show_view_toast(self, f"{int(round(self._zoom * 100))}%")

    def _fit(self):
        self._auto_fit = True
        viewport = self._page_scroll.viewport()
        vw = max(50, viewport.width() - 20)
        vh = max(50, viewport.height() - 20)
        pw, ph = self._page_pt_size
        if pw <= 0 or ph <= 0:
            return
        new = min(vw / pw, vh / ph)
        if new > 0:
            new = max(self._min_zoom, min(self._max_zoom, new))
            if abs(new - self._zoom) > 1e-4:
                self._zoom = new
                self._render()
            if hasattr(self, "_zoom_footer"):
                self._zoom_footer.set_zoom_factor(self._zoom)

    def _copy_selection(self):
        text = self._canvas.selection_text()
        if text:
            QtWidgets.QApplication.clipboard().setText(text)


class _PageRenderWorker(QtCore.QObject):
    page_rendered = QtCore.Signal(int, object, object, float)
    ready = QtCore.Signal(bool)

    def __init__(self, pdf_path):
        super().__init__()
        self._pdf_path = pdf_path
        self._doc = None
        self._current_targets = []
        self._stopping = False

    @QtCore.Slot()
    def start(self):
        try:
            self._doc = fitz.open(self._pdf_path)
        except Exception:
            self._doc = None
        try:
            self.ready.emit(self._doc is not None)
        except Exception:
            pass

    @QtCore.Slot(list)
    def set_targets(self, targets):
        self._current_targets = list(targets)
        if not self._stopping:
            QtCore.QTimer.singleShot(0, self._process_one)

    @QtCore.Slot()
    def stop(self):
        self._stopping = True
        self._current_targets = []
        try:
            if self._doc is not None:
                self._doc.close()
        except Exception:
            pass
        self._doc = None

    @QtCore.Slot()
    def _process_one(self):
        if self._stopping or self._doc is None:
            return
        if not self._current_targets:
            return
        idx, zoom = self._current_targets.pop(0)
        self._render_and_emit(idx, zoom)
        if self._current_targets:
            QtCore.QTimer.singleShot(0, self._process_one)

    def _render_and_emit(self, idx, zoom):
        try:
            page = self._doc.load_page(idx)
            mat = fitz.Matrix(zoom, zoom)
            pix = page.get_pixmap(matrix=mat, alpha=False)
            img = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
            # QPixmap is a GUI resource. Transfer a detached QImage across the
            # worker boundary and create the QPixmap in the GUI-thread receiver.
            qimage = _pil_to_qimage_rgba(img)

            words_pt = _pdf_page_words_in_display_space(page)

            self.page_rendered.emit(idx, qimage, words_pt, float(zoom))
        except Exception:
            pass


# ============================================================
# LAZY-LOADING FULL PDF VIEWER
# ============================================================
class _LazyPdfView(QtWidgets.QWidget):
    selectionChanged = QtCore.Signal(bool)
    linkActivated = QtCore.Signal(str)
    _request_render = QtCore.Signal(list)

    _MAX_CACHE       = 10
    _PAGE_GAP        = 14
    _SIDE_MARGIN     = 16
    _TOP_MARGIN      = 16
    _BOTTOM_MARGIN   = 16
    _MAX_ZOOM        = 8.0
    _MIN_ZOOM        = 0.15

    def __init__(self, pdf_path, parent=None):
        super().__init__(parent)
        self._pdf_path = pdf_path
        self._doc = fitz.open(pdf_path)
        self._num_pages = self._doc.page_count

        self._page_sizes = []
        self._links_by_page = [None] * self._num_pages
        self._bookmarks = self._load_bookmarks()
        for i in range(self._num_pages):
            try:
                r = self._doc.load_page(i).rect
                self._page_sizes.append((float(r.width), float(r.height)))
            except Exception:
                self._page_sizes.append((612.0, 792.0))

        self._zoom = 1.0
        self._cache = collections.OrderedDict()

        self._sel_page = -1
        self._sel_start = None
        self._sel_end = None
        self._sel_active = False
        self._press_origin = None
        self._drag_started = False
        self._double_click_word_selected = False
        self._exact_word_selection = False
        self._exact_word_text = ""
        self._pressed_link = None

        self._search_hits_by_page = {}
        self._current_hit = None

        self._doc_closed = False

        self._render_thread = QtCore.QThread()
        self._render_worker = _PageRenderWorker(pdf_path)
        self._render_worker.moveToThread(self._render_thread)
        _track_qthread(self._render_thread, managed_worker=self._render_worker)
        self._render_thread.started.connect(self._render_worker.start)
        self._render_thread.finished.connect(self._render_worker.deleteLater)
        self._render_worker.page_rendered.connect(self._on_page_rendered)
        self._request_render.connect(self._render_worker.set_targets)
        self._render_thread.start()

        self.setMouseTracking(True)
        self.setFocusPolicy(QtCore.Qt.FocusPolicy.StrongFocus)
        self.setCursor(QtCore.Qt.CursorShape.IBeamCursor)
        self.setAutoFillBackground(False)

        self._recompute_layout()

    def close_doc(self):
        if self._doc_closed:
            return
        self._doc_closed = True

        render_thread = self._render_thread
        render_worker = self._render_worker
        if render_worker is not None:
            # Set the stop flag immediately from the GUI thread. Queuing stop() and
            # then quitting the worker event loop can otherwise leave the queued stop
            # invocation stranded during teardown. The flag is only read by the worker.
            try:
                render_worker._stopping = True
                render_worker._current_targets = []
            except Exception:
                pass

        if render_thread is not None:
            _stop_qthread(render_thread, timeout_ms=3000, force_wait_ms=1500)

        # The worker is no longer executing after the thread fence above, so closing
        # its PyMuPDF handle directly is safe even though its normal QObject affinity
        # was the render thread.
        if render_worker is not None:
            try:
                render_worker.stop()
            except Exception:
                pass

        self._render_thread = None
        self._render_worker = None

        try:
            if self._doc is not None:
                self._doc.close()
        except Exception:
            pass
        self._doc = None
        self._cache.clear()
        self._links_by_page = [None] * self._num_pages

    def num_pages(self):
        return self._num_pages

    def bookmarks(self):
        """Return the PDF outline entries used by the Full PDF Viewer bookmark pane."""
        return list(self._bookmarks)

    def _load_bookmarks(self):
        """Read the PDF's native outline/bookmark tree without changing the document."""
        if self._doc is None:
            return []

        bookmarks = []
        try:
            toc = self._doc.get_toc(simple=False)
        except Exception:
            return []

        for entry in toc or []:
            if not isinstance(entry, (list, tuple)) or len(entry) < 3:
                continue
            try:
                level = max(1, int(entry[0]))
            except Exception:
                level = 1

            title = str(entry[1] or "").strip()
            if not title:
                title = "Untitled"

            try:
                page_number = int(entry[2])
            except Exception:
                page_number = 0
            page_idx = page_number - 1 if page_number > 0 else -1
            if page_idx < 0 or page_idx >= self._num_pages:
                page_idx = -1

            dest = entry[3] if len(entry) >= 4 and isinstance(entry[3], dict) else {}
            uri = str(dest.get("uri") or "").strip()

            y_pt = 0.0
            x_pt = 0.0
            point = dest.get("to")
            try:
                if point is not None:
                    if hasattr(point, "x"):
                        x_pt = float(point.x)
                    elif isinstance(point, (list, tuple)) and len(point) >= 1:
                        x_pt = float(point[0])
                    if hasattr(point, "y"):
                        y_pt = float(point.y)
                    elif isinstance(point, (list, tuple)) and len(point) >= 2:
                        y_pt = float(point[1])
            except Exception:
                x_pt = 0.0
                y_pt = 0.0

            try:
                destination_zoom = float(dest.get("zoom") or 0.0)
            except Exception:
                destination_zoom = 0.0

            bookmarks.append({
                "level": level,
                "title": title,
                "page_idx": page_idx,
                "page_number": page_idx + 1 if page_idx >= 0 else page_number,
                "x_pt": x_pt,
                "y_pt": y_pt,
                "zoom": destination_zoom,
                "uri": uri,
                "collapse": bool(dest.get("collapse", False)),
            })
        return bookmarks

    def zoom(self):
        return self._zoom

    def set_search_hits(self, hits_by_page, current_hit):
        self._search_hits_by_page = dict(hits_by_page) if hits_by_page else {}
        self._current_hit = current_hit
        self.update()

    def clear_search_hits(self):
        self._search_hits_by_page = {}
        self._current_hit = None
        self.update()

    def _find_scroll_area(self):
        p = self.parentWidget()
        while p is not None:
            if isinstance(p, QtWidgets.QScrollArea):
                return p
            p = p.parentWidget()
        return None

    def viewport_anchor(self):
        sa = self._find_scroll_area()
        if sa is None or self._num_pages == 0:
            return 0, 0.0
        scroll_y = sa.verticalScrollBar().value()
        for i in range(self._num_pages):
            top = self._page_y[i]
            bottom = top + self._page_h[i]
            if scroll_y < bottom:
                offset = max(0.0, scroll_y - top)
                return i, offset / max(1e-6, self._zoom)
        last = self._num_pages - 1
        return last, self._page_h[last] / max(1e-6, self._zoom)

    def scroll_to_anchor(self, page_idx, y_pt):
        sa = self._find_scroll_area()
        if sa is None:
            return
        if page_idx < 0 or page_idx >= self._num_pages:
            return
        target = self._page_y[page_idx] + y_pt * self._zoom
        sa.verticalScrollBar().setValue(int(max(0, target)))

    def scroll_to_result(self, page_idx, y_pt):
        sa = self._find_scroll_area()
        if sa is None:
            return
        if page_idx < 0 or page_idx >= self._num_pages:
            return
        vbar = sa.verticalScrollBar()
        viewport_h = sa.viewport().height()
        page_top = self._page_y[page_idx]
        page_bottom = page_top + self._page_h[page_idx]
        target_y = page_top + y_pt * self._zoom
        desired = int(target_y - viewport_h / 3.0)
        if desired + viewport_h > page_bottom:
            desired = int(page_bottom - viewport_h)
        if desired < page_top:
            desired = int(page_top)
        desired = max(0, min(vbar.maximum(), desired))
        vbar.setValue(desired)

    def _get_page_links(self, idx):
        """Lazily collect web-link rectangles in the page's rendered coordinate space."""
        if idx < 0 or idx >= self._num_pages:
            return []
        cached = self._links_by_page[idx]
        if cached is not None:
            return cached
        links = []
        try:
            page = self._doc.load_page(idx)
            rotation_matrix = page.rotation_matrix
            for link in page.get_links():
                uri = str(link.get("uri") or "").strip()
                if not uri:
                    continue
                lr = fitz.Rect(link.get("from")) * rotation_matrix
                links.append((float(lr.x0), float(lr.y0),
                              float(lr.x1), float(lr.y1), uri))
        except Exception:
            links = []
        self._links_by_page[idx] = links
        return links

    def _link_at(self, pos):
        """Return the web URI under the cursor in displayed page coordinates."""
        idx = self._hit_test(pos)
        if idx < 0:
            return None
        page_rect = self._page_rect(idx)
        scale = max(1e-6, self._zoom)
        px = (float(pos.x()) - page_rect.left()) / scale
        py = (float(pos.y()) - page_rect.top()) / scale
        point = QtCore.QPointF(px, py)
        candidates = []
        for link in self._get_page_links(idx):
            try:
                x0, y0, x1, y1, uri = link
                rect = QtCore.QRectF(float(x0), float(y0),
                                     float(x1) - float(x0),
                                     float(y1) - float(y0))
                if rect.contains(point):
                    area = max(0.0, rect.width()) * max(0.0, rect.height())
                    candidates.append((area, str(uri)))
            except Exception:
                pass
        if not candidates:
            return None
        candidates.sort(key=lambda item: item[0])
        return candidates[0][1]

    def _update_hover_cursor(self, pos):
        try:
            if pos is not None and self._link_at(pos):
                self.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
            else:
                self.setCursor(QtCore.Qt.CursorShape.IBeamCursor)
        except Exception:
            self.setCursor(QtCore.Qt.CursorShape.IBeamCursor)

    def _has_selection_internal(self):
        if not (self._sel_active and self._sel_page >= 0
                and self._sel_start is not None
                and self._sel_end is not None):
            return False
        cached = self._cache.get(self._sel_page)
        if cached is None:
            return False
        _pix, words, _scale = cached
        if not words:
            return False
        page_rect = self._page_rect(self._sel_page)
        sel = QtCore.QRectF(self._sel_start, self._sel_end).normalized()
        rel = QtCore.QRectF(sel.left() - page_rect.left(),
                            sel.top() - page_rect.top(),
                            sel.width(), sel.height())
        scale = self._zoom
        pt_rect = QtCore.QRectF(rel.left() / scale, rel.top() / scale,
                                rel.width() / scale, rel.height() / scale)
        for (x0, y0, x1, y1, _t) in words:
            wr = QtCore.QRectF(x0, y0, x1 - x0, y1 - y0)
            if pt_rect.intersects(wr):
                return True
        return False

    def has_selection(self):
        return self._has_selection_internal()

    def max_page_width_pts(self):
        if not self._page_sizes:
            return 612.0
        return max(w for (w, h) in self._page_sizes)

    def _recompute_layout(self):
        self._page_y = []
        self._page_w = []
        self._page_h = []

        y = float(self._TOP_MARGIN)
        for (w_pt, h_pt) in self._page_sizes:
            w = w_pt * self._zoom
            h = h_pt * self._zoom
            self._page_y.append(y)
            self._page_w.append(w)
            self._page_h.append(h)
            y += h + self._PAGE_GAP

        total_h = y - self._PAGE_GAP + self._BOTTOM_MARGIN if self._num_pages else 100
        total_w = (self.max_page_width_pts() * self._zoom
                   + 2 * self._SIDE_MARGIN)
        self.setMinimumHeight(max(100, int(total_h)))
        self.setMinimumWidth(max(100, int(total_w)))

    def set_zoom(self, z, invalidate=True):
        z = max(self._MIN_ZOOM, min(self._MAX_ZOOM, float(z)))
        if abs(z - self._zoom) < 1e-4:
            return
        self._zoom = z
        if invalidate:
            self._cache.clear()
        self._recompute_layout()
        self.updateGeometry()
        self.update()

    def _center_x(self, page_w):
        return max(self._SIDE_MARGIN, (self.width() - page_w) / 2.0)

    def _page_rect(self, idx):
        w = self._page_w[idx]
        h = self._page_h[idx]
        y = self._page_y[idx]
        x = self._center_x(w)
        return QtCore.QRectF(x, y, w, h)

    def _viewport_rect_in_widget_coords(self):
        w = self
        while w is not None:
            p = w.parentWidget()
            if isinstance(p, QtWidgets.QScrollArea):
                vp = p.viewport()
                hbar = p.horizontalScrollBar()
                vbar = p.verticalScrollBar()
                return QtCore.QRect(int(hbar.value()), int(vbar.value()),
                                    int(vp.width()), int(vp.height()))
            w = p
        return self.rect()

    def _visible_range(self):
        vp = self._viewport_rect_in_widget_coords()
        if self._num_pages == 0:
            return 0, -1
        first = -1
        last = -1
        top = vp.top()
        bottom = vp.bottom()
        for i in range(self._num_pages):
            py = self._page_y[i]
            ph = self._page_h[i]
            if py + ph < top:
                continue
            if py > bottom:
                break
            if first < 0:
                first = i
            last = i
        if first < 0:
            return 0, min(1, self._num_pages - 1)
        return first, last

    def paintEvent(self, event):
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QtGui.QPainter.RenderHint.SmoothPixmapTransform, True)
        p.fillRect(event.rect(), QtGui.QColor("#2a2a2a"))

        first, last = self._visible_range()
        if last < first:
            return

        paint_rect = QtCore.QRectF(event.rect())
        for i in range(first, last + 1):
            r = self._page_rect(i)
            if not r.intersects(paint_rect):
                continue

            cached = self._cache.get(i)
            have_pix = (cached is not None
                        and abs(cached[2] - self._zoom) < 1e-4)

            if have_pix:
                p.setPen(QtCore.Qt.PenStyle.NoPen)
                p.setBrush(QtGui.QColor(0, 0, 0, 110))
                p.drawRoundedRect(r.adjusted(-2, -2, 2, 2), 2, 2)
                p.drawPixmap(r.toRect(), cached[0])
            else:
                p.setPen(QtCore.Qt.PenStyle.NoPen)
                p.setBrush(QtGui.QColor(0, 0, 0, 110))
                p.drawRoundedRect(r.adjusted(-2, -2, 2, 2), 2, 2)
                p.setBrush(QtGui.QColor("#3a3a3a"))
                p.drawRect(r)
                p.setPen(QtGui.QPen(QtGui.QColor("#5a5a5a")))
                f = p.font()
                f.setPointSize(11)
                p.setFont(f)
                p.drawText(r, QtCore.Qt.AlignmentFlag.AlignCenter, f"Page {i + 1}")

            self._draw_search_hits(p, i, r)

            if have_pix and self._sel_active and self._sel_page == i:
                self._draw_selection_overlay(p, i, r)

            p.setPen(QtGui.QPen(QtGui.QColor("#3a3a3a"), 1))
            p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
            p.drawRect(r)

        self._request_visible()

    def _draw_search_hits(self, p, page_idx, page_rect):
        hits = self._search_hits_by_page.get(page_idx)
        if not hits:
            return
        scale = self._zoom
        p.setPen(QtCore.Qt.PenStyle.NoPen)
        cur = self._current_hit
        for j, (x0, y0, x1, y1) in enumerate(hits):
            rect = QtCore.QRectF(
                page_rect.left() + x0 * scale,
                page_rect.top() + y0 * scale,
                (x1 - x0) * scale,
                (y1 - y0) * scale,
            )
            if cur is not None and cur[0] == page_idx and cur[1] == j:
                p.setBrush(QtGui.QColor(255, 210, 60, 150))
            else:
                p.setBrush(QtGui.QColor(80, 220, 120, 95))
            p.drawRect(rect)

    def _draw_selection_overlay(self, p, page_idx, page_rect):
        if self._sel_start is None or self._sel_end is None:
            return
        sel = QtCore.QRectF(self._sel_start, self._sel_end).normalized()

        cached = self._cache.get(page_idx)
        if cached is None:
            return
        _pix, words, _scale = cached
        scale = self._zoom
        rel = QtCore.QRectF(sel.left() - page_rect.left(),
                            sel.top() - page_rect.top(),
                            sel.width(), sel.height())
        pt_rect = QtCore.QRectF(rel.left() / scale, rel.top() / scale,
                                rel.width() / scale, rel.height() / scale)
        p.setPen(QtCore.Qt.PenStyle.NoPen)
        p.setBrush(QtGui.QBrush(QtGui.QColor(74, 158, 255, 90)))
        if self._exact_word_selection:
            # Double-click selects exactly one word, even when neighbouring
            # word rectangles touch the selected rectangle.
            p.drawRect(QtCore.QRectF(
                page_rect.left() + pt_rect.left() * scale,
                page_rect.top() + pt_rect.top() * scale,
                pt_rect.width() * scale, pt_rect.height() * scale))
        else:
            # Preserve word-based selection/copy semantics, but visually join
            # the selected words on each visual line so normal inter-word
            # whitespace does not appear as a row of disconnected boxes.
            for wr in _selection_line_highlight_rects(words, pt_rect):
                p.drawRect(QtCore.QRectF(
                    page_rect.left() + wr.left() * scale,
                    page_rect.top() + wr.top() * scale,
                    wr.width() * scale, wr.height() * scale))


    def _request_visible(self):
        first, last = self._visible_range()
        if last < first:
            return
        buf = 2
        targets = []
        for i in range(max(0, first - buf),
                       min(self._num_pages, last + buf + 1)):
            cached = self._cache.get(i)
            if (cached is not None
                    and abs(cached[2] - self._zoom) < 1e-4):
                self._cache.move_to_end(i)
                continue
            targets.append((i, float(self._zoom)))
        if targets:
            self._request_render.emit(targets)

    @QtCore.Slot(int, object, object, float)
    def _on_page_rendered(self, idx, qimage, words, zoom):
        if abs(zoom - self._zoom) > 1e-4:
            return
        if idx < 0 or idx >= self._num_pages:
            return
        if qimage is None or qimage.isNull():
            return
        # This slot belongs to the GUI-thread widget; create the GUI resource here.
        qpix = QtGui.QPixmap.fromImage(qimage)
        if qpix.isNull():
            return
        self._cache[idx] = (qpix, words, zoom)
        while len(self._cache) > self._MAX_CACHE:
            self._cache.popitem(last=False)
        r = self._page_rect(idx).toRect()
        self.update(r)

    def _hit_test(self, pos):
        y = pos.y()
        for i in range(self._num_pages):
            top = self._page_y[i]
            if y < top:
                return -1
            bottom = top + self._page_h[i]
            if y < bottom:
                r = self._page_rect(i)
                if r.left() <= pos.x() <= r.right():
                    return i
                return -1
        return -1

    def _select_word_at(self, pos):
        """Select the rendered copyable word underneath the cursor."""
        idx = self._hit_test(pos)
        if idx < 0:
            return False

        cached = self._cache.get(idx)
        if cached is None:
            # The page may still be rendering.  There is deliberately no
            # gesture-specific message; a later double-click after rendering
            # simply works.
            return False

        _pix, words, _scale = cached
        page_rect = self._page_rect(idx)
        px = (float(pos.x()) - page_rect.left()) / max(1e-6, self._zoom)
        py = (float(pos.y()) - page_rect.top()) / max(1e-6, self._zoom)
        if px < 0 or py < 0 or px > page_rect.width() / self._zoom or py > page_rect.height() / self._zoom:
            return False

        candidates = []
        for word in words or []:
            try:
                x0, y0, x1, y1, text = word
                rect = QtCore.QRectF(float(x0), float(y0),
                                     float(x1) - float(x0),
                                     float(y1) - float(y0))
                if rect.contains(QtCore.QPointF(px, py)):
                    cx = rect.center().x()
                    cy = rect.center().y()
                    candidates.append((abs(cx - px) + abs(cy - py), rect, str(text)))
            except Exception:
                continue

        if not candidates:
            return False

        _distance, rect, text = min(candidates, key=lambda x: x[0])
        self._sel_page = idx
        self._sel_start = QtCore.QPointF(
            page_rect.left() + rect.left() * self._zoom,
            page_rect.top() + rect.top() * self._zoom)
        self._sel_end = QtCore.QPointF(
            page_rect.left() + rect.right() * self._zoom,
            page_rect.top() + rect.bottom() * self._zoom)
        self._sel_active = True
        self._drag_started = False
        self._press_origin = None
        self._exact_word_selection = True
        self._exact_word_text = text
        self.selectionChanged.emit(True)
        self.update()
        return True

    def mouseDoubleClickEvent(self, event):
        if event.button() == QtCore.Qt.MouseButton.LeftButton and self._select_word_at(_qt_event_position(event)):
            self._pressed_link = None
            self._double_click_word_selected = True
            event.accept()
            return
        self._double_click_word_selected = False
        super().mouseDoubleClickEvent(event)

    def mousePressEvent(self, event):
        if event.button() != QtCore.Qt.MouseButton.LeftButton:
            return
        self._pressed_link = self._link_at(_qt_event_position(event))
        idx = self._hit_test(_qt_event_position(event))
        self._press_origin = _qt_event_position(event)
        self._sel_page = idx
        if idx >= 0:
            self._sel_start = _qt_event_position(event)
            self._sel_end = _qt_event_position(event)
        else:
            self._sel_start = None
            self._sel_end = None
        self._drag_started = False
        self._sel_active = False
        self._exact_word_selection = False
        self._exact_word_text = ""

    def mouseMoveEvent(self, event):
        if self._press_origin is None:
            self._update_hover_cursor(_qt_event_position(event))
            return
        if not self._drag_started:
            dx = _qt_event_position(event).x() - self._press_origin.x()
            dy = _qt_event_position(event).y() - self._press_origin.y()
            if dx * dx + dy * dy < 25:
                return
            self._drag_started = True
            self._sel_active = self._sel_page >= 0
            self.setCursor(QtCore.Qt.CursorShape.IBeamCursor)

        if self._sel_page >= 0:
            r = self._page_rect(self._sel_page)
            x = max(r.left(), min(r.right(), float(_qt_event_position(event).x())))
            y = max(r.top(), min(r.bottom(), float(_qt_event_position(event).y())))
            self._sel_end = QtCore.QPointF(x, y)
        else:
            self._sel_end = QtCore.QPointF(_qt_event_position(event))
        self.update()

    def mouseReleaseEvent(self, event):
        if event.button() != QtCore.Qt.MouseButton.LeftButton:
            return
        pressed_link = self._pressed_link
        self._pressed_link = None
        if self._double_click_word_selected:
            self._double_click_word_selected = False
            self._press_origin = None
            self._drag_started = False
            self.selectionChanged.emit(self.has_selection())
            self._update_hover_cursor(_qt_event_position(event))
            self.update()
            event.accept()
            return
        if not self._drag_started:
            self._sel_active = False
            self._sel_start = None
            self._sel_end = None
            if pressed_link:
                self.linkActivated.emit(pressed_link)
        else:
            self._sel_end = QtCore.QPointF(_qt_event_position(event))
        self._press_origin = None
        self.selectionChanged.emit(self.has_selection())
        self._update_hover_cursor(_qt_event_position(event))
        self.update()
        event.accept()

    def keyPressEvent(self, event):
        if event.matches(QtGui.QKeySequence.StandardKey.Copy):
            self._copy_selection()
            return
        if event.key() == QtCore.Qt.Key.Key_Escape:
            self.clear_selection()
            return
        super().keyPressEvent(event)

    def _copy_selection(self):
        text = self.selection_text()
        if text:
            QtWidgets.QApplication.clipboard().setText(text)
        return text

    def selection_text(self):
        if (not self._sel_active or self._sel_page < 0
                or self._sel_start is None or self._sel_end is None):
            return ""
        cached = self._cache.get(self._sel_page)
        if cached is None:
            return ""
        _pix, words, _scale = cached
        page_rect = self._page_rect(self._sel_page)
        sel = QtCore.QRectF(self._sel_start, self._sel_end).normalized()
        rel = QtCore.QRectF(sel.left() - page_rect.left(),
                            sel.top() - page_rect.top(),
                            sel.width(), sel.height())
        scale = self._zoom
        pt_rect = QtCore.QRectF(rel.left() / scale, rel.top() / scale,
                                rel.width() / scale, rel.height() / scale)
        if self._exact_word_selection:
            # Double-click represents exactly one selectable word.
            return str(self._exact_word_text or "")
        chunks = []
        for (x0, y0, x1, y1, t) in words:
            wr = QtCore.QRectF(x0, y0, x1 - x0, y1 - y0)
            if pt_rect.intersects(wr):
                chunks.append(t)
        return " ".join(chunks)

    def clear_selection(self):
        self._sel_active = False
        self._sel_start = None
        self._sel_end = None
        self._sel_page = -1
        self._press_origin = None
        self._drag_started = False
        self._double_click_word_selected = False
        self._exact_word_selection = False
        self._exact_word_text = ""
        self._pressed_link = None
        self.selectionChanged.emit(False)
        self.update()

    def current_page_index(self):
        vp = self._viewport_rect_in_widget_coords()
        cy = (vp.top() + vp.bottom()) / 2.0
        best_idx = 0
        best_dist = None
        for i in range(self._num_pages):
            page_cy = self._page_y[i] + self._page_h[i] / 2.0
            d = abs(page_cy - cy)
            if best_dist is None or d < best_dist:
                best_dist = d
                best_idx = i
        return best_idx

    def scroll_to_page(self, idx):
        if idx < 0 or idx >= self._num_pages:
            return
        y = self._page_y[idx] - self._TOP_MARGIN
        sa = self._find_scroll_area()
        if sa is not None:
            sa.verticalScrollBar().setValue(int(max(0, y)))

    def scroll_to_bookmark(self, idx, y_pt=0.0, x_pt=0.0, destination_zoom=0.0):
        """Jump to a native PDF outline destination.

        PDF outline coordinates returned by get_toc() are already expressed in the
        page's displayed/rotated coordinate space, matching the coordinates used by
        this viewer's rendered pages.  Only the vertical destination is needed for
        the continuous page layout.
        """
        if idx < 0 or idx >= self._num_pages:
            return

        sa = self._find_scroll_area()
        if sa is None:
            return

        try:
            y_pt = max(0.0, float(y_pt))
        except Exception:
            y_pt = 0.0

        target = self._page_y[idx] + y_pt * self._zoom - 12.0
        vbar = sa.verticalScrollBar()
        vbar.setValue(int(max(0, min(vbar.maximum(), target))))

    def page_text(self, idx):
        try:
            return self._doc.load_page(idx).get_text()
        except Exception:
            return ""


class _PdfBookmarkPanel(QtWidgets.QWidget):
    """Professional-style hierarchical PDF bookmark/outline pane."""

    bookmarkActivated = QtCore.Signal(object)

    def __init__(self, bookmarks, parent=None):
        super().__init__(parent)
        self._bookmarks = list(bookmarks or [])

        self.setMinimumWidth(180)
        self.setMaximumWidth(520)
        self.setStyleSheet("""
            QWidget {
                background-color: #252525;
                color: #f0f0f0;
            }
            QLabel#bookmarkTitle {
                color: #f0f0f0;
                font-size: 10.5pt;
                font-weight: bold;
                padding: 2px 4px;
            }
            QTreeWidget {
                background-color: #252525;
                border: none;
                outline: none;
                padding: 4px 2px 6px 2px;
                font-size: 9.5pt;
            }
            QTreeWidget::item {
                padding: 4px 4px;
                min-height: 22px;
                border-radius: 4px;
            }
            QTreeWidget::item:hover {
                background-color: #303a44;
            }
            QTreeWidget::item:selected {
                background-color: #0a3a5c;
                color: #ffffff;
            }
            QTreeWidget::branch:has-siblings:!adjoins-item {
                border-image: none;
            }
            QScrollBar:vertical {
                background: #252525;
                width: 10px;
                margin: 0;
            }
            QScrollBar::handle:vertical {
                background: #4a4a4a;
                min-height: 26px;
                border-radius: 5px;
            }
            QScrollBar::handle:vertical:hover {
                background: #5a5a5a;
            }
            QScrollBar::add-line:vertical,
            QScrollBar::sub-line:vertical {
                height: 0;
            }
        """)

        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(10, 8, 6, 8)
        layout.setSpacing(6)

        title_row = QtWidgets.QHBoxLayout()
        title_row.setContentsMargins(2, 0, 2, 0)
        title = QtWidgets.QLabel("Bookmarks")
        title.setObjectName("bookmarkTitle")
        title_row.addWidget(title)
        title_row.addStretch()
        layout.addLayout(title_row)

        self.tree = QtWidgets.QTreeWidget()
        self.tree.setHeaderHidden(True)
        self.tree.setRootIsDecorated(True)
        self.tree.setIndentation(18)
        self.tree.setUniformRowHeights(False)
        self.tree.setSelectionMode(QtWidgets.QAbstractItemView.SelectionMode.SingleSelection)
        self.tree.setAnimated(True)
        self.tree.setTextElideMode(QtCore.Qt.TextElideMode.ElideRight)
        self.tree.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.tree.setVerticalScrollMode(QtWidgets.QAbstractItemView.ScrollMode.ScrollPerPixel)
        self.tree.setFocusPolicy(QtCore.Qt.FocusPolicy.StrongFocus)
        self.tree.itemClicked.connect(self._on_item_clicked)
        layout.addWidget(self.tree, stretch=1)

        self._populate()

    def _populate(self):
        self.tree.clear()
        parents = []
        items = []

        for bookmark in self._bookmarks:
            try:
                level = max(1, int(bookmark.get("level", 1)))
            except Exception:
                level = 1

            while len(parents) >= level:
                parents.pop()

            item = QtWidgets.QTreeWidgetItem()
            item.setText(0, str(bookmark.get("title") or "Untitled"))
            item.setData(0, QtCore.Qt.ItemDataRole.UserRole, bookmark)
            item.setToolTip(0, item.text(0))

            page_number = bookmark.get("page_number")
            if isinstance(page_number, int) and page_number > 0:
                item.setStatusTip(0, f"Page {page_number}")

            if parents:
                parents[-1].addChild(item)
            else:
                self.tree.addTopLevelItem(item)

            parents.append(item)
            items.append((item, bookmark))

        # Honor the PDF's explicit collapsed-outline flags. Entries without a
        # collapse flag remain expanded so the complete hierarchy is immediately
        # visible, matching the behavior users expect from a document outline pane.
        for item, bookmark in items:
            if item.childCount() > 0:
                item.setExpanded(not bool(bookmark.get("collapse", False)))

        self.tree.clearSelection()
        self.tree.setCurrentItem(None)

    def _emit_item(self, item):
        if item is None:
            return
        bookmark = item.data(0, QtCore.Qt.ItemDataRole.UserRole)
        if isinstance(bookmark, dict):
            self.bookmarkActivated.emit(bookmark)

    def _on_item_clicked(self, item, column):
        self._emit_item(item)



class _PdfBookmarkPane(QtWidgets.QWidget):
    """Resizable bookmark pane with a professional-style collapse/expand edge button."""

    _COLLAPSED_WIDTH = 32
    _DEFAULT_EXPANDED_WIDTH = 240

    def __init__(self, bookmarks, splitter=None, parent=None):
        super().__init__(parent)
        self._splitter = splitter
        self._collapsed = False
        self._expanded_width = self._DEFAULT_EXPANDED_WIDTH
        self._bookmark_panel = _PdfBookmarkPanel(bookmarks, self)
        self._bookmark_panel.setMinimumWidth(180)
        self._bookmark_panel.setMaximumWidth(520)

        self._edge_button = QtWidgets.QToolButton(self)
        self._edge_button.setObjectName("bookmarkEdgeButton")
        self._edge_button.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self._edge_button.setAutoRaise(True)
        self._edge_button.setFocusPolicy(QtCore.Qt.FocusPolicy.NoFocus)
        self._edge_button.setToolTip("Collapse bookmarks sidebar")
        self._edge_button.setText("‹")
        self._edge_button.setFixedSize(24, 48)
        self._edge_button.setStyleSheet("""
            QToolButton#bookmarkEdgeButton {
                background-color: #303030;
                color: #d8d8d8;
                border: 1px solid #454545;
                border-right: none;
                border-top-left-radius: 7px;
                border-bottom-left-radius: 7px;
                padding: 0;
                margin: 0;
                font-size: 18pt;
                font-weight: 600;
            }
            QToolButton#bookmarkEdgeButton:hover {
                background-color: #3a3a3a;
                color: #ffffff;
                border-color: #4a9eff;
            }
            QToolButton#bookmarkEdgeButton:pressed {
                background-color: #0a3a5c;
            }
        """)
        self._edge_button.clicked.connect(self.toggle_collapsed)

        self._bookmark_panel.bookmarkActivated.connect(self._forward_bookmark_activation)

        self._panel_layout = QtWidgets.QVBoxLayout(self)
        self._panel_layout.setContentsMargins(0, 0, 0, 0)
        self._panel_layout.setSpacing(0)
        self._panel_layout.addWidget(self._bookmark_panel)

        self.setMinimumWidth(0)
        self.setMaximumWidth(520)
        self.setSizePolicy(QtWidgets.QSizePolicy.Policy.Preferred, QtWidgets.QSizePolicy.Policy.Expanding)
        self._update_edge_button_geometry()

    def _forward_bookmark_activation(self, bookmark):
        self.bookmarkActivated.emit(bookmark)

    bookmarkActivated = QtCore.Signal(object)

    def is_collapsed(self):
        return self._collapsed

    def _update_edge_button_geometry(self):
        if self._edge_button is None:
            return
        x = max(0, self.width() - self._edge_button.width())
        y = max(0, (self.height() - self._edge_button.height()) // 2)
        self._edge_button.move(x, y)
        self._edge_button.raise_()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._update_edge_button_geometry()

    def _set_splitter_width(self, width):
        if self._splitter is None:
            self.setFixedWidth(int(width))
            return
        sizes = self._splitter.sizes()
        if len(sizes) < 2:
            return
        total = sum(max(0, int(v)) for v in sizes)
        target = max(0, min(int(width), max(0, total - 1)))
        self._splitter.setSizes([target, max(1, total - target)])

    def toggle_collapsed(self):
        if self._collapsed:
            self._collapsed = False
            self._bookmark_panel.show()
            self.setMaximumWidth(520)
            target = max(180, min(520, int(self._expanded_width or self._DEFAULT_EXPANDED_WIDTH)))
            self._edge_button.setText("‹")
            self._edge_button.setToolTip("Collapse bookmarks sidebar")
            self._set_splitter_width(target)
        else:
            current = int(self.width())
            if current >= 180:
                self._expanded_width = min(520, max(180, current))
            self._collapsed = True
            self._bookmark_panel.hide()
            self.setMaximumWidth(self._COLLAPSED_WIDTH)
            self._edge_button.setText("›")
            self._edge_button.setToolTip("Expand bookmarks sidebar")
            self._set_splitter_width(self._COLLAPSED_WIDTH)
        self._update_edge_button_geometry()


class _PresentationModeDialog(QtWidgets.QDialog):
    """Scrollable confirmation dialog for entering the fullscreen presentation viewer."""

    SHORTCUTS = (
        ("Exit presentation", "Esc"),
        ("Previous page", "Left / Up Arrow"),
        ("Next page", "Right / Down Arrow"),
        ("Zoom in", "Ctrl + +"),
        ("Zoom out", "Ctrl + -"),
        ("Fit width", "Ctrl + 0"),
        ("Scroll horizontally left", "Ctrl + Left Arrow"),
        ("Scroll horizontally right", "Ctrl + Right Arrow"),
        ("Scroll up", "Ctrl + Up Arrow"),
        ("Scroll down", "Ctrl + Down Arrow"),
        ("Blank page", "Ctrl + B"),
        ("First page", "Ctrl + F / Home"),
        ("Last page", "Ctrl + L / End"),
    )

    def __init__(self, parent=None, page_count=None):
        super().__init__(parent)
        self.setWindowTitle("Presentation mode")
        try:
            self._page_count = max(0, int(page_count)) if page_count is not None else 0
        except (TypeError, ValueError):
            self._page_count = 0
        self.setModal(True)
        self.setMinimumSize(520, 500)
        self.resize(680, 660)

        root = QtWidgets.QVBoxLayout(self)
        root.setContentsMargins(20, 18, 20, 16)
        root.setSpacing(12)

        title_row = QtWidgets.QHBoxLayout()
        title_row.setSpacing(12)

        icon_lbl = QtWidgets.QLabel()
        icon = _render_svg_icon(os.path.join(ICONS_FOLDER, "presentation.svg"), 28)
        if icon is not None:
            icon_lbl.setPixmap(icon.pixmap(28, 28))
        icon_lbl.setFixedSize(30, 30)
        icon_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        title_row.addWidget(icon_lbl)

        title_col = QtWidgets.QVBoxLayout()
        title_col.setSpacing(2)
        title_line = QtWidgets.QHBoxLayout()
        title_line.setSpacing(10)
        title = QtWidgets.QLabel("Presentation mode")
        title.setStyleSheet(
            "font-size: 16pt; font-weight: bold; color: #f0f0f0; background: transparent;"
        )
        title_line.addWidget(title)
        page_count = self._page_count
        page_count_text = (
            f"{page_count} page" if page_count == 1 else f"{page_count} pages"
        )
        count_pill = QtWidgets.QLabel(page_count_text)
        count_pill.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        count_pill.setStyleSheet("""
            QLabel {
                background-color:#0a3a5c; color:#4a9eff;
                padding:4px 11px; border-radius:10px;
                font-weight:bold; font-size:9pt;
            }
        """)
        title_line.addWidget(count_pill, 0, QtCore.Qt.AlignmentFlag.AlignVCenter)
        title_line.addStretch(1)
        title_col.addLayout(title_line)

        subtitle = QtWidgets.QLabel(
            "The pages will open in fullscreen. Nothing else will be shown."
        )
        subtitle.setStyleSheet(
            "font-size: 9.5pt; color: #9a9a9a; background: transparent;"
        )
        subtitle.setWordWrap(True)
        title_col.addWidget(subtitle)
        title_row.addLayout(title_col, 1)
        root.addLayout(title_row)

        hint = QtWidgets.QLabel(
            "Keyboard shortcuts available while presenting"
        )
        hint.setStyleSheet(
            "font-size: 9pt; font-weight: bold; color: #6faeff; "
            "padding: 2px 2px 0 2px; background: transparent;"
        )
        root.addWidget(hint)

        scroll = QtWidgets.QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        scroll.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setStyleSheet(
            "QScrollArea { border: none; background: transparent; }"
        )

        body = QtWidgets.QWidget()
        grid = QtWidgets.QGridLayout(body)
        grid.setContentsMargins(0, 0, 2, 0)
        grid.setHorizontalSpacing(10)
        grid.setVerticalSpacing(6)
        grid.setColumnStretch(0, 1)
        grid.setColumnStretch(1, 0)

        action_hdr = QtWidgets.QLabel("ACTION")
        shortcut_hdr = QtWidgets.QLabel("SHORTCUT")
        for hdr in (action_hdr, shortcut_hdr):
            hdr.setStyleSheet(
                "font-size: 8.5pt; font-weight: bold; color: #6d6d6d; "
                "padding: 0 8px 4px 8px; background: transparent;"
            )
        # Mirror each shortcut row's inner layout so the header is centered directly
        # above the shortcut pills, rather than centered in a narrow grid cell.
        shortcut_hdr.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter | QtCore.Qt.AlignmentFlag.AlignVCenter)
        shortcut_hdr.setFixedWidth(118)
        header_row = QtWidgets.QWidget()
        header_layout = QtWidgets.QHBoxLayout(header_row)
        header_layout.setContentsMargins(10, 0, 8, 4)
        header_layout.setSpacing(8)
        header_layout.addWidget(action_hdr, 1)
        header_layout.addWidget(shortcut_hdr, 0)
        grid.addWidget(header_row, 0, 0, 1, 2)

        for row_idx, (action, shortcut) in enumerate(self.SHORTCUTS, start=1):
            row = QtWidgets.QFrame()
            row.setObjectName("presentationShortcutRow")
            row.setStyleSheet(
                "QFrame#presentationShortcutRow {"
                "background-color: #262626; border: 1px solid #333333; border-radius: 6px;"
                "}"
            )
            row_layout = QtWidgets.QHBoxLayout(row)
            row_layout.setContentsMargins(10, 7, 8, 7)
            row_layout.setSpacing(8)

            action_lbl = QtWidgets.QLabel(action)
            action_lbl.setStyleSheet(
                "font-size: 9.5pt; color: #eeeeee; background: transparent;"
            )
            row_layout.addWidget(action_lbl, 1)

            badge = QtWidgets.QLabel(shortcut)
            badge.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
            badge.setMinimumWidth(118)
            badge.setStyleSheet(
                "QLabel {"
                "background-color: #1b1b1b; color: #b9d8ff; "
                "border: 1px solid #3c4f63; border-radius: 5px; "
                "padding: 4px 8px; font-size: 8.5pt; font-weight: bold;"
                "}"
            )
            row_layout.addWidget(badge, 0)
            grid.addWidget(row, row_idx, 0, 1, 2)

        note = QtWidgets.QLabel(
            "Horizontal movement applies only when the page is wider than the display. "
            "Blank page hides the current page until Ctrl+B is pressed again."
        )
        note.setWordWrap(True)
        note.setStyleSheet(
            "font-size: 8.5pt; color: #777777; padding: 5px 2px 2px 2px; "
            "background: transparent;"
        )
        grid.addWidget(note, len(self.SHORTCUTS) + 1, 0, 1, 2)

        scroll.setWidget(body)
        root.addWidget(scroll, 1)

        button_row = QtWidgets.QHBoxLayout()
        button_row.setContentsMargins(0, 2, 0, 0)
        button_row.addStretch()

        cancel_btn = QtWidgets.QPushButton("Cancel")
        cancel_btn.setFixedWidth(110)
        cancel_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        cancel_btn.clicked.connect(self.reject)

        start_btn = QtWidgets.QPushButton("Start presentation")
        start_btn.setFixedWidth(170)
        start_btn.setDefault(True)
        start_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        start_btn.setStyleSheet("""
            QPushButton {
                background-color: #0078d7; color: white;
                border: none; border-radius: 6px;
                padding: 8px 16px; font-weight: bold;
            }
            QPushButton:hover { background-color: #005fa3; }
            QPushButton:pressed { background-color: #004f87; }
        """)
        start_btn.clicked.connect(self.accept)

        button_row.addWidget(cancel_btn)
        button_row.addSpacing(8)
        button_row.addWidget(start_btn)
        root.addLayout(button_row)


class _PresentationPdfViewer(QtWidgets.QDialog):
    """True fullscreen, single-page-at-a-time PDF presentation surface."""

    _request_render = QtCore.Signal(list)
    _MIN_ZOOM = 0.15
    _MAX_ZOOM = 8.0
    _MOUSE_HIDE_MS = 1400
    _SCROLL_STEP = 120

    def __init__(self, pdf_path, page_idx=0, parent=None, nav_items=None, nav_index=0):
        super().__init__(parent)

        # This window is intentionally a pure presentation surface.  Mark it
        # before any show/polish event can reach _WindowChromeManager so the
        # application's custom Mac-inspired title bar is never installed here.
        self.setProperty("_mergerz_skip_custom_chrome", True)
        self.setWindowTitle("Presentation")
        self.setModal(True)
        self.setWindowFlags(QtCore.Qt.WindowType.Dialog | QtCore.Qt.WindowType.FramelessWindowHint)
        self.setAttribute(QtCore.Qt.WidgetAttribute.WA_DeleteOnClose, False)
        self.setStyleSheet("background-color: #0f0f0f;")

        self._pdf_path = str(pdf_path)
        self._editable_mode = bool(nav_items)
        self._nav_items = [dict(item) for item in (nav_items or [])]
        if self._editable_mode:
            try:
                self._nav_index = int(nav_index)
            except Exception:
                self._nav_index = 0
            self._nav_index = max(0, min(self._nav_index, len(self._nav_items) - 1)) if self._nav_items else 0
            self._page_idx = self._nav_index
        else:
            self._nav_index = 0
            self._page_idx = 0
        self._zoom = 1.0
        # Page navigation can run before the first render; initialize fit state
        # before any key event can reach _set_page().
        self._auto_fit = True
        self._page_sizes = []
        self._render_thread = None if self._editable_mode else QtCore.QThread()
        self._render_worker = None if self._editable_mode else _PageRenderWorker(self._pdf_path)
        if self._render_thread is not None:
            _track_qthread(self._render_thread, managed_worker=self._render_worker)
        self._closing = False
        self._blank_page = False
        self._cursor_hidden = False

        # Presentation startup has two asynchronous pieces: the native PDF
        # worker must open its document, and the fullscreen window must finish
        # settling its geometry.  Rendering before both are ready can produce
        # a valid page image at the old window width; resizeEvent then changes
        # the zoom, causing _on_page_rendered() to reject that image.  The old
        # implementation stopped there, leaving an apparently blank viewer
        # until a later zoom/page action triggered another render.
        self._renderer_ready = False
        self._initial_render_started = False
        self._initial_render_schedule_pending = False
        self._geometry_render_timer = QtCore.QTimer(self)
        self._geometry_render_timer.setSingleShot(True)
        self._geometry_render_timer.setInterval(80)
        self._geometry_render_timer.timeout.connect(self._render_for_current_geometry)

        if self._editable_mode:
            self._page_sizes = [None] * len(self._nav_items)
            if not self._page_sizes:
                QtWidgets.QMessageBox.critical(self, "Presentation failed", "There are no pages to present.")
                self._closing = True
                return
        else:
            try:
                with fitz.open(self._pdf_path) as doc:
                    self._page_sizes = [
                        (float(page.rect.width), float(page.rect.height))
                        for page in doc
                    ]
            except Exception as exc:
                self._page_sizes = []
                QtWidgets.QMessageBox.critical(self, "Presentation failed", str(exc))
                self._closing = True
                return

            if not self._page_sizes:
                QtWidgets.QMessageBox.critical(self, "Presentation failed", "The PDF has no pages.")
                self._closing = True
                return

        if self._editable_mode:
            self._page_idx = self._nav_index
        else:
            try:
                page_idx = int(page_idx)
            except Exception:
                page_idx = 0
            self._page_idx = max(0, min(len(self._page_sizes) - 1, page_idx))

        self.scroll = QtWidgets.QScrollArea(self)
        self.scroll.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        self.scroll.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.scroll.setWidgetResizable(False)
        self.scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.scroll.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.scroll.setStyleSheet(
            "QScrollArea { border: none; background: #0f0f0f; padding: 0; margin: 0; }"
        )

        # Use the same selectable PDF canvas as the normal dummy viewer. Presentation remains
        # chrome-free, but the page itself is interactive: teachers can double-click a word,
        # drag-select text, and press Ctrl+C without leaving fullscreen presentation mode.
        self.canvas = _PageCanvas()
        self.canvas.setStyleSheet("background: #0f0f0f; border: none;")
        self.canvas.selectionChanged.connect(self._on_canvas_selection_changed)
        self.scroll.setWidget(self.canvas)

        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)
        layout.addWidget(self.scroll, 1)

        # Keep presentation mode completely chrome-free: the PDF page is the
        # only persistent visual element. Zoom and fit remain keyboard-driven.

        self._toast = QtWidgets.QLabel(self)
        self._toast.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self._toast.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self._toast.setStyleSheet("""
            QLabel {
                background-color: rgba(20, 20, 20, 225);
                color: #f0f0f0;
                border: 1px solid #414141;
                border-radius: 9px;
                padding: 8px 14px;
                font-size: 10pt;
                font-weight: bold;
            }
        """)
        self._toast.hide()
        self._toast_timer = QtCore.QTimer(self)
        self._toast_timer.setSingleShot(True)
        self._toast_timer.setInterval(3000)
        self._toast_timer.timeout.connect(self._toast.hide)

        self._mouse_timer = QtCore.QTimer(self)
        self._mouse_timer.setSingleShot(True)
        self._mouse_timer.setInterval(self._MOUSE_HIDE_MS)
        self._mouse_timer.timeout.connect(self._hide_mouse)

        for watched in (self, self.scroll, self.scroll.viewport(), self.canvas):
            watched.setMouseTracking(True)
            watched.installEventFilter(self)

        self.setFocusPolicy(QtCore.Qt.FocusPolicy.StrongFocus)
        self.scroll.setFocusPolicy(QtCore.Qt.FocusPolicy.NoFocus)
        self.canvas.setFocusPolicy(QtCore.Qt.FocusPolicy.StrongFocus)

        if self._editable_mode:
            self._renderer_ready = True
        else:
            self._render_worker.moveToThread(self._render_thread)
            self._render_thread.started.connect(self._render_worker.start)
            self._request_render.connect(self._render_worker.set_targets)
            self._render_worker.ready.connect(self._on_renderer_ready)
            self._render_worker.page_rendered.connect(self._on_page_rendered)
            self._render_thread.start()

        QtCore.QTimer.singleShot(0, self._show_mouse)
        # showFullScreen() is invoked by FullPdfViewer immediately after this
        # object is constructed.  Defer the first render until the fullscreen
        # show/resize events have completed and the worker has reported ready.
        QtCore.QTimer.singleShot(0, self._maybe_start_initial_render)

    def showEvent(self, event):
        super().showEvent(event)
        if not self._closing:
            # Re-assert fullscreen after the first show event.  This is harmless
            # when showFullScreen() already succeeded, and prevents the custom
            # dialog/window manager from leaving us in a decorated state on
            # platforms that delay application of window state until show.
            if not self.isFullScreen():
                self.showFullScreen()
            QtCore.QTimer.singleShot(0, self._maybe_start_initial_render)

    def _on_renderer_ready(self, ready):
        if self._closing:
            return
        self._renderer_ready = bool(ready)
        if not self._renderer_ready:
            self._show_toast("Could not open this PDF for presentation.")
            return
        self._maybe_start_initial_render()

    def _maybe_start_initial_render(self):
        if (self._closing or self._initial_render_started
                or self._initial_render_schedule_pending
                or not self._renderer_ready
                or not self._page_sizes
                or not self.isVisible()
                or not self.isFullScreen()):
            return

        # Queue one more event-loop turn so the fullscreen viewport dimensions
        # are the final display dimensions before the fit-to-width calculation.
        self._initial_render_schedule_pending = True
        QtCore.QTimer.singleShot(0, self._start_initial_render)

    def _start_initial_render(self):
        self._initial_render_schedule_pending = False
        if (self._closing or self._initial_render_started
                or not self._renderer_ready or not self.isFullScreen()):
            return
        self._initial_render_started = True
        self._fit_width()
        self._request_page_render()

    def _render_for_current_geometry(self):
        if self._closing or not self._renderer_ready or not self.isFullScreen():
            return
        self._fit_width()
        self._request_page_render()

    def eventFilter(self, obj, event):
        if obj in (self, self.scroll, self.scroll.viewport(), self.canvas):
            if event.type() in (
                QtCore.QEvent.Type.MouseMove,
                QtCore.QEvent.Type.MouseButtonPress,
                QtCore.QEvent.Type.MouseButtonRelease,
                QtCore.QEvent.Type.Wheel,
            ):
                self._show_mouse()

        # The selectable canvas takes keyboard focus after the teacher clicks/selects text.
        # Route unhandled canvas key events back through the presentation controller so page
        # navigation/zoom/blank-page shortcuts continue to work while Ctrl+C copies the selected
        # PDF text. Without this bridge, giving _PageCanvas focus made the text selectable but
        # silently stranded the presentation hotkeys inside the child widget.
        if obj is self.canvas and event.type() == QtCore.QEvent.Type.KeyPress:
            try:
                self.keyPressEvent(event)
                return True
            except Exception:
                pass
        return super().eventFilter(obj, event)

    def _on_canvas_selection_changed(self, has_selection):
        # Keep keyboard copy available in presentation mode without adding persistent chrome.
        # A hidden selection state is enough; _PageCanvas owns the actual selected text.
        try:
            self.canvas.setToolTip(
                "Text selected — press Ctrl+C to copy" if has_selection else "")
        except Exception:
            pass

    def _show_mouse(self):
        if self._cursor_hidden:
            self.setCursor(QtCore.Qt.CursorShape.ArrowCursor)
            self.scroll.setCursor(QtCore.Qt.CursorShape.ArrowCursor)
            self.scroll.viewport().setCursor(QtCore.Qt.CursorShape.ArrowCursor)
            self.canvas.setCursor(QtCore.Qt.CursorShape.ArrowCursor)
            self._cursor_hidden = False
        self._mouse_timer.start()

    def _hide_mouse(self):
        if self._closing:
            return
        self.setCursor(QtCore.Qt.CursorShape.BlankCursor)
        self.scroll.setCursor(QtCore.Qt.CursorShape.BlankCursor)
        self.scroll.viewport().setCursor(QtCore.Qt.CursorShape.BlankCursor)
        self.canvas.setCursor(QtCore.Qt.CursorShape.BlankCursor)
        self._cursor_hidden = True

    def _show_toast(self, text):
        if self._closing:
            return
        self._toast.setText(text)
        self._toast.adjustSize()
        self._toast.move(
            max(12, (self.width() - self._toast.width()) // 2),
            24,
        )
        self._toast.show()
        self._toast.raise_()
        self._toast_timer.start()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if hasattr(self, "_toast"):
            self._toast.adjustSize()
            self._toast.move(
                max(12, (self.width() - self._toast.width()) // 2),
                24,
            )
        if not self._closing and self._page_sizes:
            # During initial startup, only update the stored zoom.  The actual
            # first render is deliberately deferred until fullscreen geometry is
            # settled.  After startup, debounce a fresh render for real window
            # resizes so a rejected stale frame can never leave the presentation
            # surface blank.
            self._fit_width()
            if self._initial_render_started and self._renderer_ready:
                self._geometry_render_timer.start()
            else:
                self._maybe_start_initial_render()

    def _editable_page_size(self, nav_index=None):
        if not self._editable_mode or not self._nav_items:
            return None
        if nav_index is None:
            nav_index = self._nav_index
        try:
            nav_index = int(nav_index)
            item = self._nav_items[nav_index]
            source_pdf = item.get("source_pdf")
            original_idx = int(item.get("original_idx", 0))
            if not source_pdf or not os.path.isfile(source_pdf):
                return None
            with fitz.open(source_pdf) as doc:
                page = doc.load_page(original_idx)
                try:
                    src_rot = int(page.rotation) % 360
                except Exception:
                    src_rot = 0
                apply_entry_to_page(page, item, src_rot=src_rot)
                rect = page.rect
                if rect.width > 0 and rect.height > 0:
                    ratio = item.get("stretch_ratio")
                    if ratio is not None:
                        return calculate_stretch_dimensions(
                            float(rect.width), float(rect.height), float(ratio))
                    return float(rect.width), float(rect.height)
        except Exception:
            return None
        return None

    def _fit_width(self):
        if self._editable_mode:
            size = self._editable_page_size()
            if size is None:
                return
            pw = max(1.0, size[0])
        else:
            if not self._page_sizes or self._page_idx >= len(self._page_sizes):
                return
            pw = max(1.0, self._page_sizes[self._page_idx][0])
        vw = max(1, self.scroll.viewport().width())
        self._zoom = max(self._MIN_ZOOM, min(self._MAX_ZOOM, vw / pw))

    def _render_editable_page(self):
        if self._closing or not self._nav_items:
            return
        item = self._nav_items[self._nav_index]
        try:
            # Presentation uses the same canonical PDF-native renderer as the saved/thumbnail
            # paths. This is important for unsaved edits: Page Design, crop, flip, rotation,
            # stretch, filters and OCR are all already present in the PDF whose text layer we
            # expose to the selection canvas. No separate QLabel/image-only approximation is used.
            render_zoom = max(self._MIN_ZOOM, min(self._MAX_ZOOM, float(self._zoom)))
            payload = _page_design_ordered_render_payload(
                item, render_zoom * 72.0, apply_filters=True)
            if payload is None:
                raise RuntimeError("Could not render this page.")
            image, page_size, words_pt, links_pt = payload
            qpix = _pil_to_qpixmap(image)
            if qpix.isNull():
                raise RuntimeError("Could not convert this page to a display image.")

            self._page_sizes[self._nav_index] = (
                float(page_size[0]), float(page_size[1]))
            try:
                sx = float(qpix.width()) / max(1.0, float(page_size[0]))
                sy = float(qpix.height()) / max(1.0, float(page_size[1]))
                canvas_scale = (sx + sy) / 2.0
                if not math.isfinite(canvas_scale) or canvas_scale <= 0:
                    canvas_scale = render_zoom
            except Exception:
                canvas_scale = render_zoom

            self._blank_page = False
            self.canvas.set_content(qpix, words_pt, canvas_scale, links_pt)
            self.canvas.setFixedSize(qpix.size())
            self.canvas.updateGeometry()
            self.canvas.show()
            self.canvas.setFocus(QtCore.Qt.FocusReason.OtherFocusReason)
            self.scroll.horizontalScrollBar().setValue(0)
            self.scroll.verticalScrollBar().setValue(0)
        except Exception as exc:
            self.canvas.clear()
            self._show_toast(f"Could not render this page: {exc}")


    def _request_page_render(self):
        if self._closing:
            return
        if self._editable_mode:
            self._render_editable_page()
            return
        if not self._render_worker:
            return
        self._blank_page = False
        self.canvas.show()
        self.canvas.clear()
        self.scroll.horizontalScrollBar().setValue(0)
        self.scroll.verticalScrollBar().setValue(0)
        try:
            self._render_worker._stopping = False
            self._render_worker._current_targets = []
        except Exception:
            pass
        self._request_render.emit([(self._page_idx, float(self._zoom))])

    @QtCore.Slot(int, object, object, float)
    def _on_page_rendered(self, idx, qimage, words_pt, zoom):
        if self._closing or idx != self._page_idx:
            return
        if abs(float(zoom) - float(self._zoom)) > 1e-4:
            return
        if qimage is None or qimage.isNull():
            self._show_toast("This page could not be rendered.")
            return
        qpix = QtGui.QPixmap.fromImage(qimage)
        if qpix.isNull():
            self._show_toast("This page could not be rendered.")
            return

        try:
            page_size = self._page_sizes[idx]
            sx = float(qpix.width()) / max(1.0, float(page_size[0]))
            sy = float(qpix.height()) / max(1.0, float(page_size[1]))
            canvas_scale = (sx + sy) / 2.0
            if not math.isfinite(canvas_scale) or canvas_scale <= 0:
                canvas_scale = float(zoom)
        except Exception:
            canvas_scale = float(zoom)

        self.canvas.set_content(
            qpix, list(words_pt or []), canvas_scale, [])
        self.canvas.setFixedSize(qpix.size())
        self.canvas.updateGeometry()
        self.canvas.show()
        self.canvas.setFocus(QtCore.Qt.FocusReason.OtherFocusReason)
        self.scroll.horizontalScrollBar().setValue(0)
        self.scroll.verticalScrollBar().setValue(0)

    def _set_page(self, idx):
        if not self._page_sizes:
            return
        idx = max(0, min(len(self._page_sizes) - 1, int(idx)))
        if idx == self._page_idx:
            return
        self._page_idx = idx
        if self._editable_mode:
            self._nav_index = idx
        # A manual zoom is an absolute document zoom percentage and must remain identical
        # when navigating between differently sized/cropped pages. Only an active Fit mode
        # is allowed to recalculate the zoom for the newly displayed page.
        if self._auto_fit:
            self._fit_width()
        self._request_page_render()

    def _prev_page(self):
        if self._page_idx > 0:
            self._set_page(self._page_idx - 1)

    def _next_page(self):
        if self._page_idx + 1 < len(self._page_sizes):
            self._set_page(self._page_idx + 1)

    def _set_zoom_percent(self, percent):
        try:
            percent = int(percent)
        except Exception:
            percent = 100
        percent = max(15, min(800, percent))
        self._auto_fit = False
        self._zoom = percent / 100.0
        self._request_page_render()

    def _zoom_in(self):
        self._auto_fit = False
        new_zoom = min(self._MAX_ZOOM, self._zoom * 1.25)
        if abs(new_zoom - self._zoom) > 1e-4:
            self._zoom = new_zoom
            self._request_page_render()
        # No zoom toast is shown in presentation mode, keeping the page unobstructed.

    def _zoom_out(self):
        self._auto_fit = False
        new_zoom = max(self._MIN_ZOOM, self._zoom / 1.25)
        if abs(new_zoom - self._zoom) > 1e-4:
            self._zoom = new_zoom
            self._request_page_render()
        # No zoom toast is shown in presentation mode, keeping the page unobstructed.

    def _scroll_h(self, delta):
        bar = self.scroll.horizontalScrollBar()
        bar.setValue(max(bar.minimum(), min(bar.maximum(), bar.value() + int(delta))))

    def _scroll_v(self, delta):
        bar = self.scroll.verticalScrollBar()
        bar.setValue(max(bar.minimum(), min(bar.maximum(), bar.value() + int(delta))))

    def _toggle_blank_page(self):
        self._blank_page = not self._blank_page
        if self._blank_page:
            self.canvas.hide()
        else:
            self.canvas.show()

    def _shutdown_renderer(self):
        if self._render_thread is None:
            return
        worker = self._render_worker
        try:
            if worker is not None:
                worker._stopping = True
                worker._current_targets = []
        except Exception:
            pass
        _stop_qthread(
            self._render_thread,
            timeout_ms=3000,
            force_wait_ms=1500,
        )
        try:
            if worker is not None:
                worker.stop()
        except Exception:
            pass
        self._render_worker = None
        self._render_thread = None

    def done(self, result):
        if self._closing:
            return super().done(result)
        self._closing = True
        self._mouse_timer.stop()
        self._toast_timer.stop()
        self._shutdown_renderer()
        super().done(result)

    def closeEvent(self, event):
        if not self._closing:
            self._closing = True
            self._mouse_timer.stop()
            self._toast_timer.stop()
            self._shutdown_renderer()
        super().closeEvent(event)

    def keyPressEvent(self, event):
        mods = event.modifiers()
        key = event.key()

        if key == QtCore.Qt.Key.Key_Escape:
            self.reject()
            return

        if event.matches(QtGui.QKeySequence.StandardKey.Copy):
            self.canvas._copy_selection()
            event.accept()
            return

        if (mods & QtCore.Qt.KeyboardModifier.ControlModifier) and not (mods & QtCore.Qt.KeyboardModifier.AltModifier):
            if key == QtCore.Qt.Key.Key_0:
                self._fit_width()
                self._request_page_render()
                return
            if key in (QtCore.Qt.Key.Key_Plus, QtCore.Qt.Key.Key_Equal):
                self._zoom_in()
                return
            if key == QtCore.Qt.Key.Key_Minus:
                self._zoom_out()
                return
            if key == QtCore.Qt.Key.Key_Left:
                self._scroll_h(-self._SCROLL_STEP)
                return
            if key == QtCore.Qt.Key.Key_Right:
                self._scroll_h(self._SCROLL_STEP)
                return
            if key == QtCore.Qt.Key.Key_Up:
                self._scroll_v(-self._SCROLL_STEP)
                return
            if key == QtCore.Qt.Key.Key_Down:
                self._scroll_v(self._SCROLL_STEP)
                return
            if key == QtCore.Qt.Key.Key_B:
                self._toggle_blank_page()
                return
            if key == QtCore.Qt.Key.Key_F:
                self._set_page(0)
                return
            if key == QtCore.Qt.Key.Key_L:
                self._set_page(len(self._page_sizes) - 1)
                return

        if mods == QtCore.Qt.KeyboardModifier.NoModifier:
            if key in (QtCore.Qt.Key.Key_Left, QtCore.Qt.Key.Key_Up):
                self._prev_page()
                return
            if key in (QtCore.Qt.Key.Key_Right, QtCore.Qt.Key.Key_Down):
                self._next_page()
                return
            if key == QtCore.Qt.Key.Key_Home:
                self._set_page(0)
                return
            if key == QtCore.Qt.Key.Key_End:
                self._set_page(len(self._page_sizes) - 1)
                return

        super().keyPressEvent(event)




class FullPdfViewer(QtWidgets.QDialog):
    def __init__(self, pdf_path, page_idx=0, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Open PDF")
        self.setModal(True)
        self.setMinimumSize(900, 700)
        self._pdf_path = pdf_path
        self._pending_jump = page_idx
        self._initial_fit_done = False
        self._auto_fit = True

        self._find_box = None
        self._search_results = []
        self._current_result_idx = -1
        self._pending_query = None
        self._search_thread = None
        self._search_worker = None
        self._search_bridge = None
        self._bookmark_panel = None
        self._bookmark_pane = None
        self._bookmark_splitter = None

        self._threads_shutdown = False

        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(12, 12, 12, 12)
        layout.setSpacing(8)

        header = QtWidgets.QHBoxLayout()
        header.setSpacing(8)

        logo_lbl = QtWidgets.QLabel()
        logo_icon = _render_svg_icon(
            os.path.join(ICONS_FOLDER, "logo.svg"), size=22)
        if logo_icon is not None:
            logo_lbl.setPixmap(logo_icon.pixmap(22, 22))
        logo_lbl.setFixedSize(22, 22)
        logo_lbl.setStyleSheet("background: transparent;")
        header.addWidget(logo_lbl)

        title = ElidedLabel(os.path.basename(pdf_path),
                            QtCore.Qt.TextElideMode.ElideMiddle)
        title.setStyleSheet(
            "font-size: 12pt; font-weight: bold; color: #f0f0f0;")
        title.setMinimumWidth(60)
        # Keep enough room for the complete action toolbar even when the PDF
        # filename is long. The full filename/path remains available via the tooltip.
        title.setMaximumWidth(260)

        # Keep the viewer header clean by hiding the old path pill. Hovering the
        # filename now provides the same compact, two-line tooltip used by Edit PDF.
        from html import escape as _html_escape
        full_name = _html_escape(str(os.path.basename(pdf_path) or ""), quote=False)
        full_path = _html_escape(str(pdf_path or ""), quote=False)
        title.setToolTip(
            f'<span style="font-size:9pt;"><nobr>{full_name}</nobr><br><nobr>{full_path}</nobr></span>'
            if full_path else
            f'<span style="font-size:9pt;"><nobr>{full_name}</nobr></span>')
        header.addWidget(title)

        self.page_lbl = QtWidgets.QLabel("— / —")
        self.page_lbl.setStyleSheet("""
            background-color: #0a3a5c; color: #4a9eff;
            padding: 6px 14px; border-radius: 10px;
            font-weight: bold; font-size: 11pt;
        """)
        self.page_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        header.addWidget(self.page_lbl)

        # Floating page indicator shown briefly while scrolling.
        self._scroll_page_pill = QtWidgets.QLabel("", self)
        self._scroll_page_pill.setStyleSheet("""
            background-color: #0a3a5c; color: #4a9eff;
            padding: 5px 11px; border-radius: 10px;
            font-weight: bold; font-size: 10pt;
            border: 1px solid rgba(74, 158, 255, 0.25);
        """)
        self._scroll_page_pill.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self._scroll_page_pill.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self._scroll_page_pill.hide()
        self._scroll_page_pill_raise_timer = QtCore.QTimer(self)
        self._scroll_page_pill_raise_timer.setSingleShot(True)
        self._scroll_page_pill_raise_timer.setInterval(900)
        self._scroll_page_pill_raise_timer.timeout.connect(self._hide_scroll_page_pill)

        header.addStretch()

        # Keep all viewer action buttons together as one compact toolbar.
        # This layout must be created inside FullPdfViewer before the buttons are added.
        header_actions = QtWidgets.QHBoxLayout()
        header_actions.setSpacing(6)
        header_actions.setContentsMargins(0, 0, 0, 0)

        def make_btn(icon_name, tooltip, slot):
            b = QtWidgets.QPushButton()
            b.setFixedSize(36, 36)
            b.setToolTip(tooltip)
            b.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
            b.setStyleSheet("""
                QPushButton {
                    background-color: #2a2a2a;
                    border: 1px solid #3a3a3a;
                    border-radius: 6px;
                }
                QPushButton:hover { background-color: #3a3a3a; }
                QPushButton:checked {
                    background-color: #0a3a5c;
                    border: 1px solid #0078d7;
                }
            """)
            ic = _render_svg_icon(os.path.join(ICONS_FOLDER, icon_name), 22)
            if ic is not None:
                b.setIcon(ic)
                b.setIconSize(QtCore.QSize(22, 22))
            else:
                b.setText("•")
            b.clicked.connect(slot)
            return b

        self.btn_find = make_btn("find.svg", "Find text (Ctrl+F)",
                                 self._toggle_find)
        self.btn_find.setCheckable(True)

        self.btn_copy = make_btn("copy.svg",
                                 "Copy selected text (Ctrl+C)",
                                 self._copy_selection)
        self.btn_copy.setEnabled(False)
        self.btn_presentation = make_btn(
            "presentation.svg",
            "Presentation mode (F5)",
            self._open_presentation_mode)
        self.btn_print = make_btn(
            "print.svg",
            "Print PDF (Ctrl+P)",
            self._print_pdf)

        header_actions.addWidget(self.btn_find)
        header_actions.addWidget(self.btn_copy)
        header_actions.addWidget(self.btn_presentation)
        header_actions.addWidget(self.btn_print)
        header.addLayout(header_actions)
        layout.addLayout(header)

        self.scroll = QtWidgets.QScrollArea()
        self.scroll.setWidgetResizable(True)
        self.scroll.setStyleSheet(
            "QScrollArea { border: 1px solid #2a2a2a; border-radius: 6px; "
            "background: #2a2a2a; }")
        self.scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.scroll.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)

        # Host the floating page counter on the scroll area itself so it can
        # occupy the narrow strip immediately beside the real scrollbar.
        self._scroll_page_pill.setParent(self.scroll)

        try:
            self.view = _LazyPdfView(pdf_path)
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "Open Failed", str(e))
            self.view = None

        if self.view is not None:
            self.scroll.setWidget(self.view)
            self.scroll.verticalScrollBar().valueChanged.connect(
                self._on_scroll)
            self.view.setContextMenuPolicy(QtCore.Qt.ContextMenuPolicy.CustomContextMenu)
            self.view.customContextMenuRequested.connect(
                self._on_view_context_menu)
            self.view.selectionChanged.connect(
                lambda has: self.btn_copy.setEnabled(has))
            self.view.linkActivated.connect(self._open_external_link)

            bookmarks = self.view.bookmarks()
            if bookmarks:
                self._bookmark_splitter = QtWidgets.QSplitter(QtCore.Qt.Orientation.Horizontal)
                self._bookmark_splitter.setChildrenCollapsible(False)
                self._bookmark_splitter.setHandleWidth(5)
                self._bookmark_splitter.setStyleSheet("""
                    QSplitter::handle {
                        background-color: #303030;
                    }
                    QSplitter::handle:hover {
                        background-color: #4a9eff;
                    }
                """)

                self._bookmark_pane = _PdfBookmarkPane(
                    bookmarks, splitter=self._bookmark_splitter)
                self._bookmark_pane.bookmarkActivated.connect(
                    self._on_bookmark_activated)
                self._bookmark_panel = self._bookmark_pane._bookmark_panel

                self._bookmark_splitter.addWidget(self._bookmark_pane)
                self._bookmark_splitter.addWidget(self.scroll)
                self._bookmark_splitter.setStretchFactor(0, 0)
                self._bookmark_splitter.setStretchFactor(1, 1)
                self._bookmark_splitter.setSizes([240, 660])
                layout.addWidget(self._bookmark_splitter, stretch=1)
            else:
                layout.addWidget(self.scroll, stretch=1)
        else:
            layout.addWidget(self.scroll, stretch=1)

        bottom = QtWidgets.QHBoxLayout()
        bottom.setSpacing(6)
        self._zoom_footer = _PdfZoomFooter(
            lambda: self.view.zoom() if self.view is not None else 1.0,
            self._zoom_in,
            self._zoom_out,
            self._set_zoom_percent,
            self._fit_width,
            self,
        )
        bottom.addWidget(self._zoom_footer)
        bottom.addStretch()
        close_btn = QtWidgets.QPushButton("Close")
        close_btn.setFixedWidth(120)
        close_btn.setStyleSheet("""
            QPushButton {
                background-color: #0078d7; color: white;
                border: none; border-radius: 6px;
                padding: 7px 16px; font-weight: bold;
            }
            QPushButton:hover { background-color: #005fa3; }
        """)
        close_btn.clicked.connect(self.accept)
        bottom.addWidget(close_btn)
        layout.addLayout(bottom)

        s1 = QtGui.QShortcut(QtGui.QKeySequence("Ctrl++"), self)
        s1.activated.connect(self._zoom_in)
        s2 = QtGui.QShortcut(QtGui.QKeySequence("Ctrl+="), self)
        s2.activated.connect(self._zoom_in)
        s3 = QtGui.QShortcut(QtGui.QKeySequence("Ctrl+-"), self)
        s3.activated.connect(self._zoom_out)
        s4 = QtGui.QShortcut(QtGui.QKeySequence("Ctrl+0"), self)
        s4.activated.connect(self._fit_width)
        s5 = QtGui.QShortcut(QtGui.QKeySequence("Ctrl+F"), self)
        s5.activated.connect(self._toggle_find)
        s6 = QtGui.QShortcut(QtGui.QKeySequence("Ctrl+P"), self)
        s6.activated.connect(self._print_pdf)
        s7 = QtGui.QShortcut(QtGui.QKeySequence("F5"), self)
        s7.activated.connect(self._open_presentation_mode)

        self._fit_debounce = QtCore.QTimer(self)
        self._fit_debounce.setSingleShot(True)
        self._fit_debounce.setInterval(140)
        self._fit_debounce.timeout.connect(self._fit_width)

        # Keep the document fitted to the actual viewer area while the bookmark
        # sidebar is being resized. The small debounce lets QSplitter finish
        # applying the new width before the fit calculation reads the viewport.
        if self._bookmark_splitter is not None:
            self._bookmark_splitter.splitterMoved.connect(
                self._on_bookmark_splitter_moved)

        if self.view is not None:
            self.page_lbl.setText(f"1 / {self.view.num_pages()}")

        self._find_box = _FindBox(self)
        self._find_box.searchRequested.connect(self._on_find_search)
        self._find_box.nextRequested.connect(self._on_find_next)
        self._find_box.prevRequested.connect(self._on_find_prev)
        self._find_box.closeRequested.connect(self._hide_find_box)
        self._find_box.hide()

        if self.view is not None:
            self._search_thread = QtCore.QThread()
            self._search_worker = _SearchWorker(pdf_path)
            self._search_worker.moveToThread(self._search_thread)
            _track_qthread(self._search_thread, managed_worker=self._search_worker)

            self._search_bridge = _SearchBridge()
            self._search_bridge.trigger.connect(self._search_worker.do_search)

            self._search_thread.finished.connect(self._search_worker.deleteLater)
            self._search_worker.finished.connect(self._on_search_finished)
            self._search_thread.start()

    def _shutdown_threads(self):
        if self._threads_shutdown:
            return
        self._threads_shutdown = True

        search_thread = self._search_thread
        search_worker = self._search_worker
        if search_worker is not None:
            try:
                search_worker._stop_requested = True
            except Exception:
                pass

        if search_thread is not None:
            stopped = _stop_qthread(
                search_thread,
                timeout_ms=3000,
                force_wait_ms=1500,
            )
            if stopped:
                self._search_thread = None
                self._search_worker = None
                self._search_bridge = None

        if self.view is not None:
            try:
                self.view.close_doc()
            except Exception:
                pass

    def done(self, result):
        self._shutdown_threads()
        super().done(result)

    def closeEvent(self, event):
        self._shutdown_threads()
        super().closeEvent(event)

    def _toggle_find(self):
        if self._find_box.isVisible():
            self._hide_find_box()
        else:
            self._show_find_box()

    def _show_find_box(self):
        self._find_box.show()
        self._find_box.raise_()
        self.btn_find.setChecked(True)
        self._position_find_box()
        self._find_box.input.setFocus()

    def _hide_find_box(self):
        self._find_box.hide()
        self.btn_find.setChecked(False)
        self._search_results = []
        self._current_result_idx = -1
        self._pending_query = None
        if self.view is not None:
            self.view.clear_search_hits()
        self._find_box.reset()

    def _position_find_box(self):
        if self._find_box is None:
            return
        self._find_box.adjustSize()
        w = self._find_box.width()
        margin = 20
        x = self.width() - w - margin
        y = 62
        self._find_box.move(x, y)
        self._find_box.raise_()

    def _on_find_search(self, query):
        if self.view is None or self._search_bridge is None:
            return
        if not query:
            self._search_results = []
            self._current_result_idx = -1
            self._pending_query = None
            self._find_box.set_status("Type to search")
            self._find_box.set_nav_enabled(False, False)
            self.view.clear_search_hits()
            return
        self._pending_query = query
        self._find_box.set_status("Searching...")
        self._find_box.set_nav_enabled(False, False)
        self._search_bridge.trigger.emit(query)

    def _on_search_finished(self, query, results):
        if query != self._pending_query:
            return
        self._pending_query = None
        self._search_results = results

        if self.view is None:
            return

        if not results:
            self._current_result_idx = -1
            self._find_box.set_status("No results found")
            self._find_box.set_nav_enabled(False, False)
            self.view.clear_search_hits()
            return

        current_page = self.view.current_page_index()
        start_idx = 0
        for i, (pg, *_r) in enumerate(results):
            if pg >= current_page:
                start_idx = i
                break
        else:
            start_idx = 0

        self._current_result_idx = start_idx
        self._update_search_highlight()
        self._find_box.set_nav_enabled(True, True)

    def _update_search_highlight(self):
        if self.view is None:
            return

        hits_by_page = {}
        current_loc = None
        for i, (pg, x0, y0, x1, y1) in enumerate(self._search_results):
            hits_by_page.setdefault(pg, []).append((x0, y0, x1, y1))
            if i == self._current_result_idx:
                current_loc = (pg, len(hits_by_page[pg]) - 1)

        self.view.set_search_hits(hits_by_page, current_loc)

        total = len(self._search_results)
        cur = self._current_result_idx + 1
        self._find_box.set_status(f"Showing {cur}/{total} results")
        self._find_box.set_nav_enabled(total > 0, total > 0)

        if current_loc is not None:
            pg, idx = current_loc
            rect = hits_by_page[pg][idx]
            self.view.scroll_to_result(pg, rect[1])

    def _on_find_next(self):
        if not self._search_results:
            return
        self._current_result_idx = (
            (self._current_result_idx + 1) % len(self._search_results))
        self._update_search_highlight()

    def _on_find_prev(self):
        if not self._search_results:
            return
        self._current_result_idx = (
            (self._current_result_idx - 1) % len(self._search_results))
        self._update_search_highlight()

    def showEvent(self, event):
        super().showEvent(event)
        if not self._initial_fit_done:
            self._initial_fit_done = True
            QtCore.QTimer.singleShot(50, self._initial_setup)
        if self._find_box is not None and self._find_box.isVisible():
            self._position_find_box()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        _reposition_view_status_toast(self)
        if self._find_box is not None and self._find_box.isVisible():
            self._position_find_box()
        self._position_scroll_page_pill()
        if self._initial_fit_done and self._auto_fit:
            self._fit_debounce.stop()
            self._fit_debounce.start()

    def _position_scroll_page_pill(self):
        if not hasattr(self, '_scroll_page_pill') or self.view is None:
            return

        self._scroll_page_pill.adjustSize()
        vbar = self.scroll.verticalScrollBar()
        viewport = self.scroll.viewport()
        pill_w = self._scroll_page_pill.width()
        pill_h = self._scroll_page_pill.height()

        try:
            # Work in QScrollArea coordinates.  The pill is deliberately
            # outside the viewport and just to the left of the scrollbar.
            viewport_rect = viewport.geometry()
            x = viewport_rect.right() - pill_w - 8

            # Ask the style for the actual slider rectangle first.  Unlike a
            # percentage-of-track approximation, this tracks the real thumb
            # (including style-specific groove/button metrics).
            opt = QtWidgets.QStyleOptionSlider()
            vbar.initStyleOption(opt)
            slider = vbar.style().subControlRect(
                QtWidgets.QStyle.ComplexControl.CC_ScrollBar, opt,
                QtWidgets.QStyle.SubControl.SC_ScrollBarSlider, vbar)

            if slider.isValid() and slider.height() > 0:
                slider_top_in_vbar = slider.top()
                slider_height = slider.height()
            else:
                # Fallback: reproduce Qt's value-to-position calculation
                # using the scrollbar groove and the actual slider minimum.
                groove = vbar.style().subControlRect(
                    QtWidgets.QStyle.ComplexControl.CC_ScrollBar, opt,
                    QtWidgets.QStyle.SubControl.SC_ScrollBarGroove, vbar)
                slider_height = max(
                    1,
                    vbar.style().pixelMetric(
                        QtWidgets.QStyle.PixelMetric.PM_ScrollBarSliderMin, opt, vbar))
                usable = max(0, groove.height() - slider_height)
                if vbar.maximum() > vbar.minimum():
                    pos = QtWidgets.QStyle.sliderPositionFromValue(
                        vbar.minimum(), vbar.maximum(),
                        vbar.value(), usable, opt.upsideDown)
                else:
                    pos = 0
                slider_top_in_vbar = groove.top() + pos

            # Translate the thumb center from scrollbar-local coordinates into
            # QScrollArea coordinates.  This makes the pill follow the moving
            # handle rather than the center of the scrollbar track.
            center_in_vbar = QtCore.QPoint(
                max(0, vbar.width() // 2),
                int(round(slider_top_in_vbar + slider_height / 2.0)))
            center_in_scroll = vbar.mapTo(self.scroll, center_in_vbar)
            y = center_in_scroll.y() - pill_h / 2.0

            # Keep the pill inside the scroll-area frame while preserving its
            # alignment with the thumb as much as the available space allows.
            x = max(4, min(self.scroll.width() - pill_w - 4, x))
            y = max(4, min(self.scroll.height() - pill_h - 4, y))
        except Exception:
            # Last-resort placement: stay adjacent to the scrollbar, not at
            # the dialog's centre.
            vr = viewport.geometry()
            x = max(4, vr.right() - pill_w - 8)
            y = max(4, vr.top() + (vr.height() - pill_h) / 2.0)

        self._scroll_page_pill.move(int(round(x)), int(round(y)))
        self._scroll_page_pill.raise_()

    def _show_scroll_page_pill(self):
        if self.view is None:
            return
        idx = self.view.current_page_index()
        self._scroll_page_pill.setText(f"{idx + 1} / {self.view.num_pages()}")
        self._position_scroll_page_pill()
        self._scroll_page_pill.show()
        self._scroll_page_pill.raise_()
        self._scroll_page_pill_raise_timer.start()

    def _hide_scroll_page_pill(self):
        if hasattr(self, '_scroll_page_pill'):
            self._scroll_page_pill.hide()

    def _initial_setup(self):
        self._fit_width()
        QtWidgets.QApplication.processEvents()
        if self._pending_jump > 0 and self.view is not None:
            self.view.scroll_to_page(self._pending_jump)
        self._update_page_indicator()
        self._position_scroll_page_pill()

    def _on_scroll(self, _value):
        self._update_page_indicator()
        self._show_scroll_page_pill()

    def _update_page_indicator(self):
        if self.view is None:
            return
        idx = self.view.current_page_index()
        self.page_lbl.setText(f"{idx + 1} / {self.view.num_pages()}")

    def _on_bookmark_splitter_moved(self, _pos, _index):
        # Respect manual zoom. When the viewer is in its normal fit-to-width
        # mode, resizing the bookmark pane immediately refits the page to the
        # newly available document viewport, just like professional PDF viewers.
        if not self._auto_fit:
            return
        if self.view is None or self._fit_debounce is None:
            return
        self._fit_debounce.stop()
        self._fit_debounce.start()

    def _on_bookmark_activated(self, bookmark):
        if self.view is None or not isinstance(bookmark, dict):
            return

        uri = str(bookmark.get("uri") or "").strip()
        page_idx = bookmark.get("page_idx", -1)
        try:
            page_idx = int(page_idx)
        except Exception:
            page_idx = -1

        if 0 <= page_idx < self.view.num_pages():
            # Selecting a bookmark is navigation, not text selection.  Clear any
            # active selection so it cannot remain visually attached to the page
            # after the outline jump.
            self.view.clear_selection()
            self.view.scroll_to_bookmark(
                page_idx,
                bookmark.get("y_pt", 0.0),
                bookmark.get("x_pt", 0.0),
                bookmark.get("zoom", 0.0),
            )
            self._update_page_indicator()
            self._show_scroll_page_pill()
            return

        # Some PDF outlines can contain URI destinations rather than an internal
        # page. Reuse the viewer's existing external-link handling for those.
        if uri:
            self._open_external_link(uri)

    def _open_external_link(self, uri):
        _open_external_pdf_link(uri)

    def _on_view_context_menu(self, pos):
        menu = QtWidgets.QMenu(self)
        menu.setStyleSheet("""
            QMenu {
                background-color: #2b2b2b;
                border: 1px solid #3a3a3a;
                border-radius: 6px;
                padding: 4px;
            }
            QMenu::item { padding: 6px 24px; color: #f0f0f0; }
            QMenu::item:selected { background-color: #2a3a4a; }
            QMenu::item:disabled { color: #666; }
        """)
        act = menu.addAction("Copy selected text")
        act.setEnabled(self.view.has_selection() if self.view else False)
        chosen = menu.exec(self.view.mapToGlobal(pos))
        if chosen is act and act.isEnabled():
            self.view._copy_selection()

    def _set_zoom_percent(self, percent):
        if self.view is None:
            return
        try:
            percent = int(percent)
        except Exception:
            percent = 100
        percent = max(15, min(800, percent))
        self._auto_fit = False
        self._fit_debounce.stop()
        anchor = self.view.viewport_anchor()
        self.view.set_zoom(percent / 100.0)
        self.view.scroll_to_anchor(*anchor)
        if hasattr(self, "_zoom_footer"):
            self._zoom_footer.set_zoom_factor(self.view.zoom())
        self._update_page_indicator()
        _show_view_toast(self, f"{int(round(self.view.zoom() * 100))}%")

    def _zoom_in(self):
        if self.view is None:
            return
        self._auto_fit = False
        self._fit_debounce.stop()
        anchor = self.view.viewport_anchor()
        self.view.set_zoom(self.view.zoom() * 1.25)
        self.view.scroll_to_anchor(*anchor)
        if hasattr(self, "_zoom_footer"):
            self._zoom_footer.set_zoom_factor(self.view.zoom())
        self._update_page_indicator()
        _show_view_toast(self, f"{int(round(self.view.zoom() * 100))}%")

    def _zoom_out(self):
        if self.view is None:
            return
        self._auto_fit = False
        self._fit_debounce.stop()
        anchor = self.view.viewport_anchor()
        self.view.set_zoom(self.view.zoom() / 1.25)
        self.view.scroll_to_anchor(*anchor)
        if hasattr(self, "_zoom_footer"):
            self._zoom_footer.set_zoom_factor(self.view.zoom())
        self._update_page_indicator()
        _show_view_toast(self, f"{int(round(self.view.zoom() * 100))}%")

    def _fit_width(self):
        if self.view is None:
            return
        self._auto_fit = True
        vw = max(120, self.scroll.viewport().width() - 40)
        max_w = self.view.max_page_width_pts()
        if max_w <= 0:
            return
        new = vw / max_w
        new = max(0.15, min(4.0, new))
        if abs(new - self.view.zoom()) > 1e-4:
            self.view.set_zoom(new)
        if hasattr(self, "_zoom_footer"):
            self._zoom_footer.set_zoom_factor(self.view.zoom())
        self._update_page_indicator()

    def _open_presentation_mode(self):
        if self.view is None or self.view.num_pages() <= 0:
            return

        # Capture the page the user is currently viewing. Presentation begins on
        # that page, not on page 1.
        current_page = self.view.current_page_index()
        dialog = _PresentationModeDialog(self, page_count=self.view.num_pages())
        if dialog.exec() != QtWidgets.QDialog.DialogCode.Accepted:
            return

        self._hide_find_box()
        presentation = _PresentationPdfViewer(
            self._pdf_path,
            page_idx=current_page,
            parent=self,
        )
        if getattr(presentation, "_closing", False):
            presentation.deleteLater()
            return
        presentation.showFullScreen()
        presentation.raise_()
        presentation.activateWindow()
        presentation.setFocus(QtCore.Qt.FocusReason.OtherFocusReason)
        presentation.exec()
        presentation.deleteLater()

    @staticmethod
    def _atomic_copy_pdf_for_print(source_path, destination_path):
        """Copy the original PDF byte-for-byte to a print-to-file destination."""
        source_path = os.path.abspath(str(source_path))
        destination_path = os.path.abspath(os.path.expanduser(str(destination_path)))

        if os.path.normcase(source_path) == os.path.normcase(destination_path):
            source_dir = os.path.dirname(source_path) or os.getcwd()
            source_stem = os.path.splitext(os.path.basename(source_path))[0] or "document"
            destination_path = os.path.join(source_dir, f"{source_stem} - printed.pdf")
            counter = 2
            while os.path.normcase(os.path.abspath(destination_path)) == os.path.normcase(source_path) or os.path.exists(destination_path):
                destination_path = os.path.join(
                    source_dir, f"{source_stem} - printed ({counter}).pdf"
                )
                counter += 1
            destination_path = os.path.abspath(destination_path)

        destination_dir = os.path.dirname(destination_path) or os.getcwd()
        if not os.path.isdir(destination_dir):
            raise RuntimeError(
                f"The selected output folder does not exist:\n{destination_dir}"
            )

        temp_path = None
        try:
            fd, temp_path = tempfile.mkstemp(
                prefix=".mergerz-print-",
                suffix=".pdf.tmp",
                dir=destination_dir,
            )
            os.close(fd)
            temp_path = os.path.abspath(temp_path)

            with open(source_path, "rb") as src, open(temp_path, "wb") as dst:
                shutil.copyfileobj(src, dst, length=1024 * 1024)
                dst.flush()
                try:
                    os.fsync(dst.fileno())
                except OSError:
                    pass

            source_size = os.path.getsize(source_path)
            output_size = os.path.getsize(temp_path)
            if output_size != source_size:
                raise RuntimeError(
                    "The print-to-file copy could not be verified; "
                    "the source PDF was left unchanged."
                )

            os.replace(temp_path, destination_path)
            temp_path = None
            return destination_path
        finally:
            if temp_path:
                try:
                    os.remove(temp_path)
                except OSError:
                    pass

    def _print_pdf(self):
        """Use the native print dialog while preserving the source PDF byte-for-byte for file output."""
        if not self._pdf_path or not os.path.isfile(self._pdf_path):
            QtWidgets.QMessageBox.warning(
                self, "Print", "The PDF file is no longer available.")
            return

        source_path = os.path.abspath(str(self._pdf_path))

        # Seed the native "Print to File" field with a sibling named exactly
        # "<original name>_print.pdf". Do not auto-number this default; if the file
        # already exists, the post-dialog replace confirmation handles it.
        source_dir = os.path.dirname(source_path) or os.getcwd()
        source_stem = os.path.splitext(os.path.basename(source_path))[0] or "document"
        default_output = os.path.join(source_dir, f"{source_stem}_print.pdf")

        try:
            printer = QtPrintSupport.QPrinter(QtPrintSupport.QPrinter.PrinterMode.HighResolution)
            # Keep the original document title and explicitly seed the native Print to File
            # field with the safe sibling filename. The user may still edit it in the native
            # dialog, and all platform/printer-specific options remain available.
            printer.setDocName(os.path.basename(source_path))
            try:
                printer.setOutputFileName(default_output)
            except Exception:
                # Preserve compatibility with older/platform-specific Qt builds.
                pass

            dialog = QtPrintSupport.QPrintDialog(printer, self)
            dialog.setWindowTitle("Print PDF")
            if dialog.exec() != QtWidgets.QDialog.DialogCode.Accepted:
                return

            # QPrinter uses PdfFormat for file output and NativeFormat for a real printer.
            # Check the format together with outputFileName() so the seeded default cannot
            # accidentally turn a physical-printer selection into a Print to File job.
            output_file = str(printer.outputFileName() or "").strip()
            try:
                is_file_output = (
                    printer.outputFormat() == QtPrintSupport.QPrinter.OutputFormat.PdfFormat
                    and bool(output_file)
                )
            except Exception:
                is_file_output = bool(output_file)

            if is_file_output:
                output_file = os.path.abspath(os.path.expanduser(output_file))

                # Never overwrite the source PDF. Some native Qt/CUPS dialogs restore the
                # document-derived filename even when the user did not explicitly choose one.
                # Redirect that unsafe destination to a collision-free sibling instead.
                same_source = os.path.normcase(output_file) == os.path.normcase(source_path)
                if not same_source and os.path.exists(output_file):
                    try:
                        same_source = bool(os.path.samefile(source_path, output_file))
                    except (OSError, FileNotFoundError):
                        pass

                if same_source:
                    output_file = default_output

                if os.path.exists(output_file):
                    answer = QtWidgets.QMessageBox.question(
                        self,
                        "Replace PDF?",
                        f"The file already exists:\n{output_file}\n\nReplace it?",
                        QtWidgets.QMessageBox.StandardButton.Yes | QtWidgets.QMessageBox.StandardButton.No,
                        QtWidgets.QMessageBox.StandardButton.No,
                    )
                    if answer != QtWidgets.QMessageBox.StandardButton.Yes:
                        return

                saved_path = self._atomic_copy_pdf_for_print(
                    source_path,
                    output_file,
                )
                self._show_print_file_status(saved_path)
                return

            printer_name = str(printer.printerName() or "").strip()
            if not printer_name:
                raise RuntimeError("No printer was selected.")

            # Linux and macOS normally expose CUPS. Submit the original PDF directly so
            # Mergerz never rasterizes/re-encodes it before the OS print backend receives it.
            lp_path = shutil.which("lp")
            if lp_path:
                completed = subprocess.run(
                    [lp_path, "-d", printer_name, source_path],
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True,
                    timeout=30,
                    check=False,
                )
                if completed.returncode != 0:
                    detail = (
                        completed.stderr or completed.stdout or
                        "Unknown printing error."
                    ).strip()
                    raise RuntimeError(detail)

                job_text = (completed.stdout or "").strip()
                self._show_print_status(job_text)
                return

            # Windows has no CUPS 'lp'. Use the Windows shell's PrintTo verb so the
            # selected printer is still handled by the platform's PDF print handler.
            if sys.platform.startswith("win"):
                try:
                    os.startfile(source_path, "printto", printer_name)
                except TypeError:
                    raise RuntimeError(
                        "This Python/Windows PDF handler does not expose the PrintTo operation."
                    )
                self._show_print_status(
                    f"Windows PrintTo request sent to: {printer_name}"
                )
                return

            raise RuntimeError(
                "No supported system print backend was found. On Linux/macOS, "
                "the CUPS 'lp' command is required for direct original-PDF printing."
            )
        except Exception as exc:
            QtWidgets.QMessageBox.critical(
                self,
                "Print failed",
                str(exc),
            )

    def _show_print_status(self, text=""):
        msg = QtWidgets.QMessageBox(self)
        msg.setIcon(QtWidgets.QMessageBox.Icon.Information)
        msg.setWindowTitle("Print")
        msg.setText("The PDF was sent to the selected printer.")
        if text:
            msg.setInformativeText(text)
        msg.setStandardButtons(QtWidgets.QMessageBox.StandardButton.Ok)
        msg.exec()

    def _show_print_file_status(self, path):
        msg = QtWidgets.QMessageBox(self)
        msg.setIcon(QtWidgets.QMessageBox.Icon.Information)
        msg.setWindowTitle("Print to File")
        msg.setText("The original PDF was saved to the selected file.")
        msg.setInformativeText(str(path))
        msg.setStandardButtons(QtWidgets.QMessageBox.StandardButton.Ok)
        msg.exec()

    def _copy_selection(self):
        if self.view is None:
            return
        text = self.view.selection_text()
        if text:
            QtWidgets.QApplication.clipboard().setText(text)


# ============================================================
# CROP DIALOG
# ============================================================
class _CropCanvas(QtWidgets.QWidget):
    _EDGE_TOLERANCE = 8

    def __init__(self, parent=None):
        super().__init__(parent)
        self._pixmap = None
        self._scale = 1.0
        self._offset = QtCore.QPointF(0, 0)
        self._drag_start = None
        self._drag_end = None
        self._box = None
        self._page_pt_size = (612, 792)
        self._page_origin = (0.0, 0.0)

        self._flip_h = False
        self._flip_v = False

        self._adjust_mode = None
        self._adjust_origin_box = None
        self._adjust_origin_pos = None

        self.setMouseTracking(True)
        self.setCursor(QtCore.Qt.CursorShape.CrossCursor)
        self.setFocusPolicy(QtCore.Qt.FocusPolicy.StrongFocus)

    def set_content(self, pixmap, scale, page_pt_size, page_origin,
                    initial_box=None, flip_h=False, flip_v=False):
        self._pixmap = pixmap
        self._scale = scale
        self._page_pt_size = page_pt_size
        self._page_origin = page_origin
        self._flip_h = bool(flip_h)
        self._flip_v = bool(flip_v)
        self._box = initial_box
        self._drag_start = None
        self._drag_end = None
        self._adjust_mode = None
        self._adjust_origin_box = None
        self._adjust_origin_pos = None
        self._update_cursor(None)
        self.update()

    def update_content_keep_box(self, pixmap, scale, page_pt_size, page_origin,
                                 flip_h=False, flip_v=False):
        self._pixmap = pixmap
        self._scale = scale
        self._page_pt_size = page_pt_size
        self._page_origin = page_origin
        self._flip_h = bool(flip_h)
        self._flip_v = bool(flip_v)
        self._drag_start = None
        self._drag_end = None
        self._adjust_mode = None
        self._adjust_origin_box = None
        self._adjust_origin_pos = None
        self._update_cursor(None)
        self.update()

    def get_box(self):
        return self._box

    def _recompute_offset(self):
        if self._pixmap is None:
            self._offset = QtCore.QPointF(0, 0)
            return
        self._offset = QtCore.QPointF(
            max(0, (self.width() - self._pixmap.width()) / 2.0),
            max(0, (self.height() - self._pixmap.height()) / 2.0),
        )

    def _canvas_to_pdf(self, pos):
        if self._pixmap is None:
            return self._page_origin
        px = pos.x() - self._offset.x()
        py = pos.y() - self._offset.y()
        W = float(self._pixmap.width())
        H = float(self._pixmap.height())
        ox, oy = self._page_origin

        if self._flip_h:
            x = ox + (W - px) / self._scale
        else:
            x = ox + px / self._scale
        if self._flip_v:
            y = oy + (H - py) / self._scale
        else:
            y = oy + py / self._scale

        pw, ph = self._page_pt_size
        x = max(ox, min(ox + pw, x))
        y = max(oy, min(oy + ph, y))
        return x, y

    def _pdf_to_canvas(self, x, y):
        ox, oy = self._page_origin
        if self._pixmap is not None:
            W = float(self._pixmap.width())
            H = float(self._pixmap.height())
        else:
            pw, ph = self._page_pt_size
            W = pw * self._scale
            H = ph * self._scale

        if self._flip_h:
            px = W - (x - ox) * self._scale
        else:
            px = (x - ox) * self._scale
        if self._flip_v:
            py = H - (y - oy) * self._scale
        else:
            py = (y - oy) * self._scale

        cx = self._offset.x() + px
        cy = self._offset.y() + py
        return cx, cy

    def _hit_test_box(self, pos):
        if self._box is None:
            return None
        x0, y0, x1, y1 = self._box
        cx0, cy0 = self._pdf_to_canvas(x0, y0)
        cx1, cy1 = self._pdf_to_canvas(x1, y1)
        left, right = min(cx0, cx1), max(cx0, cx1)
        top, bottom = min(cy0, cy1), max(cy0, cy1)
        TOL = self._EDGE_TOLERANCE
        px, py = pos.x(), pos.y()

        if abs(px - left) < TOL and abs(py - top) < TOL:
            return 'tl'
        if abs(px - right) < TOL and abs(py - top) < TOL:
            return 'tr'
        if abs(px - left) < TOL and abs(py - bottom) < TOL:
            return 'bl'
        if abs(px - right) < TOL and abs(py - bottom) < TOL:
            return 'br'
        if abs(py - top) < TOL and left <= px <= right:
            return 'top'
        if abs(py - bottom) < TOL and left <= px <= right:
            return 'bottom'
        if abs(px - left) < TOL and top <= py <= bottom:
            return 'left'
        if abs(px - right) < TOL and top <= py <= bottom:
            return 'right'
        return None

    def _update_cursor(self, mode):
        if mode is None:
            self.setCursor(QtCore.Qt.CursorShape.CrossCursor)
            return
        if mode in ('tl', 'br'):
            self.setCursor(QtCore.Qt.CursorShape.SizeFDiagCursor)
        elif mode in ('tr', 'bl'):
            self.setCursor(QtCore.Qt.CursorShape.SizeBDiagCursor)
        elif mode in ('left', 'right'):
            self.setCursor(QtCore.Qt.CursorShape.SizeHorCursor)
        elif mode in ('top', 'bottom'):
            self.setCursor(QtCore.Qt.CursorShape.SizeVerCursor)
        else:
            self.setCursor(QtCore.Qt.CursorShape.CrossCursor)

    def paintEvent(self, event):
        p = QtGui.QPainter(self)
        p.fillRect(self.rect(), QtGui.QColor("#0f0f0f"))
        if self._pixmap is None:
            return
        self._recompute_offset()
        p.setOpacity(0.55)
        p.drawPixmap(int(self._offset.x()), int(self._offset.y()), self._pixmap)
        p.setOpacity(1.0)

        if self._box is None:
            return

        x0, y0, x1, y1 = self._box
        cx0, cy0 = self._pdf_to_canvas(x0, y0)
        cx1, cy1 = self._pdf_to_canvas(x1, y1)

        left = min(cx0, cx1)
        top = min(cy0, cy1)
        right = max(cx0, cx1)
        bottom = max(cy0, cy1)
        box_rect = QtCore.QRectF(left, top, right - left, bottom - top)

        src = QtCore.QRectF(
            left - self._offset.x(),
            top - self._offset.y(),
            right - left,
            bottom - top,
        )
        p.setOpacity(1.0)
        p.drawPixmap(box_rect, self._pixmap, src)

        p.setPen(QtGui.QPen(QtGui.QColor("#0078d7"), 2, QtCore.Qt.PenStyle.SolidLine))
        p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
        p.drawRect(box_rect)

        p.setPen(QtCore.Qt.PenStyle.NoPen)
        p.setBrush(QtGui.QBrush(QtGui.QColor("#4a9eff")))
        r = 5
        for ccx, ccy in [(left, top), (right, top),
                         (left, bottom), (right, bottom)]:
            p.drawEllipse(QtCore.QPointF(ccx, ccy), r, r)

    def mousePressEvent(self, event):
        if event.button() != QtCore.Qt.MouseButton.LeftButton or self._pixmap is None:
            return
        if self._box is not None:
            hit = self._hit_test_box(_qt_event_position(event))
            if hit is not None:
                self._adjust_mode = hit
                self._adjust_origin_box = self._box
                self._adjust_origin_pos = _qt_event_position(event)
                return
        self._drag_start = _qt_event_position(event)
        self._drag_end = _qt_event_position(event)
        self._update_box_from_drag()
        self.update()

    def mouseMoveEvent(self, event):
        if self._adjust_mode is not None and self._adjust_origin_pos is not None:
            dx = _qt_event_position(event).x() - self._adjust_origin_pos.x()
            dy = _qt_event_position(event).y() - self._adjust_origin_pos.y()

            x0, y0, x1, y1 = self._adjust_origin_box

            cx0, cy0 = self._pdf_to_canvas(x0, y0)
            cx1, cy1 = self._pdf_to_canvas(x1, y1)
            sleft = min(cx0, cx1)
            sright = max(cx0, cx1)
            stop = min(cy0, cy1)
            sbottom = max(cy0, cy1)

            mode = self._adjust_mode
            if mode in ('tl', 'left', 'bl'):
                sleft += dx
            if mode in ('tr', 'right', 'br'):
                sright += dx
            if mode in ('tl', 'top', 'tr'):
                stop += dy
            if mode in ('bl', 'bottom', 'br'):
                sbottom += dy

            p0x, p0y = self._canvas_to_pdf(QtCore.QPointF(sleft, stop))
            p1x, p1y = self._canvas_to_pdf(QtCore.QPointF(sright, sbottom))

            nx0 = min(p0x, p1x)
            nx1 = max(p0x, p1x)
            ny0 = min(p0y, p1y)
            ny1 = max(p0y, p1y)

            if nx1 - nx0 >= 3 and ny1 - ny0 >= 3:
                self._box = (nx0, ny0, nx1, ny1)
                self.update()
            return

        hit = self._hit_test_box(_qt_event_position(event))
        self._update_cursor(hit)

        if self._drag_start is not None:
            self._drag_end = _qt_event_position(event)
            self._update_box_from_drag()
            self.update()

    def mouseReleaseEvent(self, event):
        if event.button() != QtCore.Qt.MouseButton.LeftButton:
            return
        if self._adjust_mode is not None:
            self._adjust_mode = None
            self._adjust_origin_box = None
            self._adjust_origin_pos = None
            self.update()
            return
        if self._drag_start is not None:
            self._drag_end = _qt_event_position(event)
            self._update_box_from_drag()
            self._drag_start = None
            self._drag_end = None
            self.update()

    def _update_box_from_drag(self):
        if self._drag_start is None or self._drag_end is None:
            return
        x0, y0 = self._canvas_to_pdf(self._drag_start)
        x1, y1 = self._canvas_to_pdf(self._drag_end)
        if abs(x1 - x0) < 3 or abs(y1 - y0) < 3:
            return
        self._box = (min(x0, x1), min(y0, y1),
                     max(x0, x1), max(y0, y1))


class CropBoxDialog(QtWidgets.QDialog):
    def __init__(self, pdf_path, page_idx, rotation=0, mode="single",
                 parent=None, nav_items=None, nav_index=0, total_dummy=None):
        super().__init__(parent)

        if nav_items:
            self._nav_items = [dict(it) for it in nav_items]
            try:
                idx = int(nav_index)
            except Exception:
                idx = 0
            self._nav_index = max(0, min(idx, len(self._nav_items) - 1))
        else:
            self._nav_items = [{
                'source_pdf': pdf_path,
                'original_idx': int(page_idx),
                'rotation': int(rotation or 0),
                'grid_row': 0,
            }]
            self._nav_index = 0

        if total_dummy is None:
            self._total_dummy = len(self._nav_items)
        else:
            try:
                self._total_dummy = int(total_dummy)
            except Exception:
                self._total_dummy = len(self._nav_items)

        self._mode = mode
        self._is_multi_nav = bool(self._nav_items)

        self._zoom = 1.0
        self._min_zoom = 0.15
        self._max_zoom = 8.0
        self._page_pt_size = (612, 792)
        self._page_origin = (0.0, 0.0)
        self.result_box = None
        self.result_anchor_item = None

        if mode == "single":
            self.setWindowTitle("Crop Page")
        else:
            self.setWindowTitle("Crop Pages")

        self.setModal(True)
        self.setMinimumSize(860, 680)

        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(12, 12, 12, 12)
        layout.setSpacing(8)

        header = QtWidgets.QHBoxLayout()
        header.setSpacing(8)

        logo_lbl = QtWidgets.QLabel()
        logo_icon = _render_svg_icon(
            os.path.join(ICONS_FOLDER, "logo.svg"), size=22)
        if logo_icon is not None:
            logo_lbl.setPixmap(logo_icon.pixmap(22, 22))
        logo_lbl.setFixedSize(22, 22)
        logo_lbl.setStyleSheet("background: transparent;")
        header.addWidget(logo_lbl)

        self._title_lbl = ElidedLabel("", QtCore.Qt.TextElideMode.ElideMiddle)
        self._title_lbl.setStyleSheet(
            "font-size: 12pt; font-weight: bold; color: #f0f0f0;")
        self._title_lbl.setMinimumWidth(60)
        header.addWidget(self._title_lbl)

        self._page_pill = QtWidgets.QLabel("")
        self._page_pill.setStyleSheet("""
            background-color: #0a3a5c; color: #4a9eff;
            padding: 4px 12px; border-radius: 10px;
            font-weight: bold; font-size: 9pt;
        """)
        header.addWidget(self._page_pill)

        header.addStretch()
        layout.addLayout(header)

        hint = QtWidgets.QLabel(
            "Drag to draw the area you want to keep. Hover an edge or "
            "corner to adjust it."
            + ("  The same crop will be applied to all selected pages."
               if mode == "multi"
               else ""))
        hint.setStyleSheet("color: #9a9a9a; font-style: italic;")
        hint.setWordWrap(True)
        layout.addWidget(hint)

        self._crop_scroll = QtWidgets.QScrollArea()
        self._crop_scroll.setWidgetResizable(False)
        self._crop_scroll.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self._crop_scroll.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        self._crop_scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self._crop_scroll.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self._crop_scroll.setStyleSheet(
            "QScrollArea { border: none; background: #0f0f0f; }")

        self._canvas = _CropCanvas()
        self._canvas.setStyleSheet(
            "background-color: #0f0f0f; border-radius: 6px;")
        self._crop_scroll.setWidget(self._canvas)
        layout.addWidget(self._crop_scroll, stretch=1)

        bottom = QtWidgets.QHBoxLayout()
        bottom.setSpacing(6)

        self._zoom_footer = _PdfZoomFooter(
            lambda: self._zoom,
            self._zoom_in,
            self._zoom_out,
            self._set_zoom_percent,
            self._fit,
            self,
        )
        bottom.addWidget(self._zoom_footer)

        self._btn_prev = None
        self._btn_next = None
        self._sel_lbl = None

        if self._is_multi_nav:
            bottom.addSpacing(10)
            bottom.addWidget(_make_toolbar_divider(self))
            bottom.addSpacing(10)
            self._btn_prev = self._make_nav_btn("prev.svg",
                                                 "Previous selected page",
                                                 self._go_prev)
            self._btn_next = self._make_nav_btn("next.svg",
                                                 "Next selected page",
                                                 self._go_next)
            bottom.addWidget(self._btn_prev)
            bottom.addWidget(self._btn_next)

            self._sel_lbl = QtWidgets.QLabel("")
            self._sel_lbl.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
            self._sel_lbl.setStyleSheet(
                "color: #4a9eff; font-weight: bold; font-size: 10pt; "
                "background: transparent; border: none; "
                "padding-left: 8px; margin: 0;")
            bottom.addWidget(self._sel_lbl)

        bottom.addStretch()

        cancel_btn = QtWidgets.QPushButton("Cancel")
        cancel_btn.setFixedWidth(110)
        cancel_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        cancel_btn.setStyleSheet("""
            QPushButton {
                background-color: #2a2a2a; color: #f0f0f0;
                border: 1px solid #3a3a3a; border-radius: 6px;
                padding: 7px 18px; font-weight: bold; font-size: 11pt;
            }
            QPushButton:hover { background-color: #3a3a3a; }
        """)
        cancel_btn.clicked.connect(self.reject)
        bottom.addWidget(cancel_btn)
        bottom.addSpacing(10)

        self.apply_btn = QtWidgets.QPushButton(
            "Apply to All" if mode == "multi" else "Apply")
        self.apply_btn.setFixedWidth(150)
        self.apply_btn.setEnabled(False)
        self.apply_btn.setStyleSheet("""
            QPushButton {
                background-color: #0078d7; color: white;
                border: none; border-radius: 6px;
                padding: 7px 18px; font-weight: bold; font-size: 11pt;
            }
            QPushButton:hover { background-color: #005fa3; }
            QPushButton:disabled { background-color: #2a2a2a; color: #666; }
        """)
        self.apply_btn.clicked.connect(self._on_apply)
        bottom.addWidget(self.apply_btn)
        layout.addLayout(bottom)

        QtGui.QShortcut(QtGui.QKeySequence("Ctrl++"), self,
                            self._zoom_in)
        QtGui.QShortcut(QtGui.QKeySequence("Ctrl+="), self,
                            self._zoom_in)
        QtGui.QShortcut(QtGui.QKeySequence("Ctrl+-"), self,
                            self._zoom_out)
        QtGui.QShortcut(QtGui.QKeySequence("Ctrl+0"), self,
                            self._fit)

        # Page navigation shortcuts are part of the crop viewer whenever a
        # navigation model exists (including the 1/1 case). WindowShortcut
        # keeps them active while the canvas/scroll area or another child has focus.
        crop_prev_shortcut = QtGui.QShortcut(QtGui.QKeySequence("Left"), self)
        crop_prev_shortcut.setContext(QtCore.Qt.ShortcutContext.WindowShortcut)
        crop_prev_shortcut.activated.connect(self._go_prev)
        crop_next_shortcut = QtGui.QShortcut(QtGui.QKeySequence("Right"), self)
        crop_next_shortcut.setContext(QtCore.Qt.ShortcutContext.WindowShortcut)
        crop_next_shortcut.activated.connect(self._go_next)
        self._crop_nav_shortcuts = (crop_prev_shortcut, crop_next_shortcut)

        self._apply_check_timer = QtCore.QTimer(self)
        self._apply_check_timer.setInterval(120)
        self._apply_check_timer.timeout.connect(self._check_apply_enabled)
        self._apply_check_timer.start()

        self._auto_fit = True
        self._update_header()
        self._render()

    def _make_nav_btn(self, icon_name, tooltip, slot):
        b = QtWidgets.QPushButton()
        b.setFixedSize(36, 36)
        b.setToolTip(tooltip)
        b.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        b.setStyleSheet("""
            QPushButton {
                background-color: #2a2a2a;
                border: 1px solid #3a3a3a;
                border-radius: 6px;
            }
            QPushButton:hover { background-color: #3a3a3a; }
            QPushButton:disabled {
                background-color: #1e1e1e;
                border: 1px solid #2a2a2a;
            }
        """)
        ic = _render_svg_icon(os.path.join(ICONS_FOLDER, icon_name), 22)
        if ic is not None:
            b.setIcon(ic)
            b.setIconSize(QtCore.QSize(22, 22))
        else:
            b.setText("<" if "prev" in icon_name else ">")
        b.clicked.connect(slot)
        return b

    def _update_header(self):
        if not self._nav_items:
            return
        item = self._nav_items[self._nav_index]
        self._title_lbl.setText(os.path.basename(item['source_pdf']))

        grid_row = item.get('grid_row', self._nav_index)
        try:
            grid_row = int(grid_row)
        except Exception:
            grid_row = self._nav_index
        total = self._total_dummy if self._total_dummy > 0 else max(
            1, self._nav_index + 1)
        self._page_pill.setText(f"Dummy page {grid_row + 1}/{total}")

        if self._is_multi_nav:
            total_sel = len(self._nav_items)
            if self._sel_lbl is not None:
                self._sel_lbl.setText(
                    f"Selected page {self._nav_index + 1}/{total_sel}")
            if self._btn_prev is not None:
                self._btn_prev.setEnabled(self._nav_index > 0)
            if self._btn_next is not None:
                self._btn_next.setEnabled(
                    self._nav_index < total_sel - 1)

    def _go_prev(self):
        if self._nav_index <= 0:
            return
        self._nav_index -= 1
        self._update_header()
        self._render(keep_box=True)

    def _go_next(self):
        if self._nav_index >= len(self._nav_items) - 1:
            return
        self._nav_index += 1
        self._update_header()
        self._render(keep_box=True)

    def _check_apply_enabled(self):
        box = self._canvas.get_box()
        if box is not None:
            self.apply_btn.setEnabled(True)
            if self.result_anchor_item is None or \
                    self.result_box != box:
                if self._nav_items:
                    self.result_anchor_item = dict(
                        self._nav_items[self._nav_index])

    def _render(self, keep_box=False):
        if not self._nav_items:
            return
        item = self._nav_items[self._nav_index]
        # When Page Design already exists, the crop editor must see the same PDF-native designed
        # page that the user would get by continuing the edit sequence. This keeps the design
        # visible in the crop surface instead of silently reverting to the undecorated source.
        if _page_design_has_any(item) and _page_design_anchor_state(item) is not None:
            try:
                ordered = _page_design_ordered_document(item, apply_filters=True)
                page = ordered[0]
                rect = page.rect
                self._page_pt_size = (float(rect.width), float(rect.height))
                self._page_origin = (float(rect.x0), float(rect.y0))
                if self._auto_fit:
                    viewport = self._crop_scroll.viewport()
                    vw = max(200, viewport.width() - 20)
                    vh = max(200, viewport.height() - 20)
                    z = min(vw / max(1.0, rect.width), vh / max(1.0, rect.height))
                    if z > 0:
                        self._zoom = max(self._min_zoom, min(self._max_zoom, z))
                pix = page.get_pixmap(matrix=fitz.Matrix(self._zoom, self._zoom), alpha=False)
                img = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
                qpix = _pil_to_qpixmap(img)
                ordered.close()
                # The new crop has not been chosen yet, so keep the currently visible designed page
                # intact and let the canvas overlay the interactive crop rectangle.
                self._canvas.set_content(qpix, self._zoom, self._page_pt_size, self._page_origin,
                                         flip_h=False, flip_v=False) if not keep_box else self._canvas.update_content_keep_box(
                                             qpix, self._zoom, self._page_pt_size, self._page_origin,
                                             flip_h=False, flip_v=False)
                self._canvas.setFixedSize(qpix.size())
                self._canvas.updateGeometry()
                if hasattr(self, "_zoom_footer"):
                    self._zoom_footer.set_zoom_factor(self._zoom)
                return
            except Exception:
                pass

        pdf_path = item['source_pdf']
        page_idx = item['original_idx']
        rotation = int(item.get('rotation', 0))
        flip_h = bool(item.get('flip_h', False))
        flip_v = bool(item.get('flip_v', False))
        stretch_ratio = item.get('stretch_ratio')

        try:
            with fitz.open(pdf_path) as doc:
                page = doc.load_page(page_idx)
                orig_rot = page.rotation

                # Re-cropping must show the page exactly as it currently exists.
                # ``entry['crop']`` represents an unsaved crop in source-PDF
                # coordinates; a previously saved crop is already the page's
                # actual CropBox.  Establish whichever is newer before rendering.
                existing_crop = item.get('crop')
                if existing_crop:
                    try:
                        existing_crop = fitz.Rect(*existing_crop) & page.mediabox
                        if (not existing_crop.is_empty and existing_crop.width >= 1
                                and existing_crop.height >= 1):
                            page.set_cropbox(existing_crop)
                    except Exception:
                        pass

                page.set_rotation((orig_rot + rotation) % 360)
                vr = fitz.Rect(page.rect)
                display_width, display_height = vr.width, vr.height
                if stretch_ratio is not None:
                    try:
                        ratio = float(stretch_ratio)
                        if math.isfinite(ratio) and ratio > 0:
                            display_width, display_height = calculate_stretch_dimensions(
                                vr.width, vr.height, ratio)
                    except (TypeError, ValueError, OverflowError):
                        pass
                self._page_pt_size = (display_width, display_height)
                self._page_origin = (vr.x0, vr.y0)

                if self._auto_fit:
                    viewport = self._crop_scroll.viewport()
                    vw = max(200, viewport.width() - 20)
                    vh = max(200, viewport.height() - 20)
                    if display_width > 0 and display_height > 0:
                        z = min(vw / display_width, vh / display_height)
                        if z > 0:
                            self._zoom = max(self._min_zoom,
                                             min(self._max_zoom, z))

                # Render the stretched page directly with an anisotropic matrix.
                # This gives the crop canvas the same geometry the user sees,
                # without first enlarging or shrinking a low-resolution pixmap.
                sx = display_width / max(1e-12, vr.width)
                sy = display_height / max(1e-12, vr.height)
                mat = fitz.Matrix(self._zoom * sx, 0, 0,
                                  self._zoom * sy, 0, 0)
                pix = page.get_pixmap(matrix=mat, alpha=False)
                img = Image.frombytes(
                    "RGB", [pix.width, pix.height], pix.samples)
                qpix = _pil_to_qpixmap(img)
                page.set_rotation(orig_rot)
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "Crop Open Failed", str(e))
            self.reject()
            return

        if flip_h or flip_v:
            qpix = _flip_qpixmap(qpix, flip_h, flip_v)

        if keep_box:
            self._canvas.update_content_keep_box(
                qpix, self._zoom, self._page_pt_size, self._page_origin,
                flip_h=flip_h, flip_v=flip_v)
            self._canvas.setFixedSize(qpix.size())
            self._canvas.updateGeometry()
        else:
            self._canvas.set_content(
                qpix, self._zoom, self._page_pt_size, self._page_origin,
                flip_h=flip_h, flip_v=flip_v)
            self._canvas.setFixedSize(qpix.size())
            self._canvas.updateGeometry()
        if hasattr(self, "_zoom_footer"):
            self._zoom_footer.set_zoom_factor(self._zoom)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if self._auto_fit:
            QtCore.QTimer.singleShot(60, lambda: self._render(keep_box=True))

    def _set_zoom_percent(self, percent):
        try:
            percent = int(percent)
        except Exception:
            percent = 100
        percent = max(15, min(800, percent))
        self._auto_fit = False
        self._zoom = percent / 100.0
        if hasattr(self, "_zoom_footer"):
            self._zoom_footer.set_zoom_factor(self._zoom)
        self._render(keep_box=True)
        _show_view_toast(self, f"{int(round(self._zoom * 100))}%")

    def _zoom_in(self):
        self._auto_fit = False
        new = min(self._max_zoom, self._zoom * 1.25)
        if new != self._zoom:
            self._zoom = new
            self._render(keep_box=True)
        if hasattr(self, "_zoom_footer"):
            self._zoom_footer.set_zoom_factor(self._zoom)
        _show_view_toast(self, f"{int(round(self._zoom * 100))}%")

    def _zoom_out(self):
        self._auto_fit = False
        new = max(self._min_zoom, self._zoom / 1.25)
        if new != self._zoom:
            self._zoom = new
            self._render(keep_box=True)
        if hasattr(self, "_zoom_footer"):
            self._zoom_footer.set_zoom_factor(self._zoom)
        _show_view_toast(self, f"{int(round(self._zoom * 100))}%")

    def _fit(self):
        self._auto_fit = True
        self._render(keep_box=True)

    def _on_apply(self):
        box = self._canvas.get_box()
        if box is None:
            QtWidgets.QMessageBox.warning(
                self, "No Crop Area",
                "Please drag on the page to define the crop area.")
            return
        x0, y0, x1, y1 = box
        if x1 - x0 < 3 or y1 - y0 < 3:
            QtWidgets.QMessageBox.warning(
                self, "Crop Too Small",
                "The crop area is too small. Please draw a larger rectangle.")
            return
        self.result_box = (float(x0), float(y0), float(x1), float(y1))
        if self.result_anchor_item is None and self._nav_items:
            self.result_anchor_item = dict(self._nav_items[self._nav_index])
        self.accept()


def _crop_dialog_factory(pdf_path, page_idx, rotation, mode, parent=None,
                          nav_items=None, nav_index=0, total_dummy=None):
    return CropBoxDialog(pdf_path, page_idx, rotation, mode, parent,
                          nav_items=nav_items, nav_index=nav_index,
                          total_dummy=total_dummy)


# ============================================================
# CUSTOM CONTEXT MENU
# ============================================================
class _MenuItemWidget(QtWidgets.QWidget):
    clicked = QtCore.Signal()

    def __init__(self, icon_name, text, shortcut="", enabled=True, parent=None):
        super().__init__(parent)
        self._enabled = enabled
        self._hovered = False
        self.setAttribute(QtCore.Qt.WidgetAttribute.WA_Hover, True)
        self.setAttribute(QtCore.Qt.WidgetAttribute.WA_StyledBackground, True)
        self.setMouseTracking(True)
        if enabled:
            self.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)

        layout = QtWidgets.QHBoxLayout(self)
        layout.setContentsMargins(14, 6, 18, 6)
        layout.setSpacing(10)

        self.icon_label = QtWidgets.QLabel()
        if icon_name:
            pix = _render_svg_icon_pixmap(
                os.path.join(ICONS_FOLDER, icon_name),
                16, muted=not enabled)
            if pix is not None:
                self.icon_label.setPixmap(pix)
        self.icon_label.setFixedSize(16, 16)
        self.icon_label.setStyleSheet("background: transparent;")
        self.icon_label.setAttribute(
            QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        layout.addWidget(self.icon_label)

        self.text_label = QtWidgets.QLabel(text)
        self.text_label.setAttribute(
            QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        layout.addWidget(self.text_label, stretch=1)

        self.shortcut_label = QtWidgets.QLabel(shortcut)
        self.shortcut_label.setAlignment(
            QtCore.Qt.AlignmentFlag.AlignRight | QtCore.Qt.AlignmentFlag.AlignVCenter)
        self.shortcut_label.setAttribute(
            QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self.shortcut_label.setMinimumWidth(72)
        layout.addWidget(self.shortcut_label)

        self._apply_style()

    def _apply_style(self):
        if not self._enabled:
            self.setStyleSheet(
                "QWidget { background-color: transparent; }")
            self.text_label.setStyleSheet(
                "color: #666; font-size: 10pt; background: transparent;")
            self.shortcut_label.setStyleSheet(
                "color: #555; font-size: 9pt; background: transparent;")
            return
        if self._hovered:
            self.setStyleSheet(
                "QWidget { background-color: #2a3a4a; border-radius: 4px; }")
        else:
            self.setStyleSheet(
                "QWidget { background-color: transparent; }")
        self.text_label.setStyleSheet(
            "color: #f0f0f0; font-size: 10pt; background: transparent;")
        self.shortcut_label.setStyleSheet(
            "color: #8a8a8a; font-size: 9pt; background: transparent;")

    def enterEvent(self, e):
        if self._enabled:
            self._hovered = True
            self._apply_style()
        super().enterEvent(e)

    def leaveEvent(self, e):
        self._hovered = False
        self._apply_style()
        super().leaveEvent(e)

    def mouseReleaseEvent(self, e):
        if self._enabled and e.button() == QtCore.Qt.MouseButton.LeftButton:
            self.clicked.emit()
        super().mouseReleaseEvent(e)


def _add_menu_item(menu, icon_name, text, slot, shortcut="", enabled=True):
    action = QtWidgets.QWidgetAction(menu)
    widget = _MenuItemWidget(icon_name, text, shortcut, enabled)

    def _on_clicked():
        try:
            menu.close()
        except Exception:
            pass
        QtCore.QTimer.singleShot(10, slot)

    widget.clicked.connect(_on_clicked)
    action.setDefaultWidget(widget)
    menu.addAction(action)
    return action


