class OCRConfigDialog(QtWidgets.QDialog):
    def __init__(self, parent=None, n_pages=0, plugin_status=None):
        super().__init__(parent)
        self.setWindowTitle("Configure OCR")
        self.setModal(True)
        self.setMinimumWidth(560)
        self.plugin_status = plugin_status or {}
        self._n_pages = int(n_pages)

        screen = self.screen() or QtWidgets.QApplication.primaryScreen()
        if screen is not None:
            available = screen.availableGeometry()
            # Keep the normal dialog tight around its content; the form becomes scrollable
            # automatically when a short display cannot fit the full configuration.
            target_height = min(445, max(390, available.height() - 90))
            target_width = min(680, max(560, int(available.width() * 0.46)))
            self.resize(target_width, target_height)
            self.setMaximumHeight(max(390, available.height() - 35))

        root = QtWidgets.QVBoxLayout(self)
        root.setContentsMargins(22, 12, 22, 10)
        root.setSpacing(5)

        header_row = QtWidgets.QHBoxLayout()
        header_row.setContentsMargins(0, 0, 0, 0)
        header_row.setSpacing(8)
        header_row.setAlignment(QtCore.Qt.AlignmentFlag.AlignLeft | QtCore.Qt.AlignmentFlag.AlignVCenter)

        header = QtWidgets.QLabel("Scan text from selected pages")
        header.setStyleSheet("font-size:14pt;font-weight:bold;color:#fff;")
        header.setSizePolicy(QtWidgets.QSizePolicy.Policy.Fixed, QtWidgets.QSizePolicy.Policy.Preferred)
        header_row.addWidget(header, 0, QtCore.Qt.AlignmentFlag.AlignVCenter)

        page_text = f"{self._n_pages} page" if self._n_pages == 1 else f"{self._n_pages} pages"
        page_pill = QtWidgets.QLabel(page_text)
        page_pill.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        page_pill.setStyleSheet("""
            background-color:#0a3a5c; color:#4a9eff;
            padding:3px 9px; border-radius:10px;
            font-weight:700; font-size:9pt;
        """)
        page_fm = QtGui.QFontMetrics(page_pill.font())
        page_pill.setFixedWidth(max(52, page_fm.horizontalAdvance(page_text) + 22))
        page_pill.setFixedHeight(max(23, page_fm.height() + 8))
        page_pill.setToolTip(f"{self._n_pages} selected page(s)")
        header_row.addWidget(page_pill, 0, QtCore.Qt.AlignmentFlag.AlignVCenter)
        root.addLayout(header_row)
        # Give the title row a small breathing space before the first form control.
        root.addSpacing(10)

        self.scroll = QtWidgets.QScrollArea()
        self.scroll.setWidgetResizable(True)
        self.scroll.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        self.scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.scroll.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.scroll.setWidgetResizable(True)
        root.addWidget(self.scroll, 1)

        form = QtWidgets.QWidget()
        self._form_widget = form
        self.scroll.setWidget(form)
        layout = QtWidgets.QVBoxLayout(form)
        layout.setContentsMargins(0, 12, 8, 4)
        layout.setSpacing(7)

        def make_combo():
            combo = QtWidgets.QComboBox()
            combo.setMinimumHeight(32)
            combo.setStyleSheet("""
                QComboBox { background:#2a2a2a; color:#f0f0f0; border:1px solid #3a3a3a;
                            border-radius:5px; padding:5px 9px; }
                QComboBox:hover { border-color:#4a4a4a; }
                QComboBox QAbstractItemView { background:#2a2a2a; color:#f0f0f0;
                            selection-background-color:#174a70; }
            """)
            return combo

        def add_row(label_text):
            row = QtWidgets.QHBoxLayout()
            label = QtWidgets.QLabel(label_text)
            label.setMinimumWidth(145)
            row.addWidget(label)
            combo = make_combo()
            row.addWidget(combo, 1)
            layout.addLayout(row)
            return combo

        self.lang_combo = add_row("OCR language")
        self.lang_combo.setMaxVisibleItems(18)
        self.lang_combo.addItem("Automatic (limited languages)", "auto")
        language_entries = []
        for entry in list(self.plugin_status.get("languages") or []):
            if not isinstance(entry, dict):
                continue
            code = str(entry.get("code") or "").strip().lower()
            if not code or code == "auto":
                continue
            name = _ocr_language_name(code)
            resolved = name != code
            language_entries.append((resolved, name.casefold(), code, name))
        language_entries.sort(key=lambda x: (not x[0], x[1] if x[0] else x[2]))
        for resolved, _, code, name in language_entries:
            self.lang_combo.addItem(f"{name} ({code})" if resolved else code, code)
        self.lang_combo.setEnabled(self.lang_combo.count() > 1)

        self.version_combo = add_row("OCR version")
        self.version_combo.setMaxVisibleItems(12)
        self.detection_combo = add_row("Detection model")
        self.detection_combo.setMaxVisibleItems(16)
        self.recognition_combo = add_row("Recognition model")
        self.recognition_combo.setMaxVisibleItems(16)

        self.dpi_combo = add_row("Render DPI")
        for value in (200, 300, 600):
            self.dpi_combo.addItem(f"{value} DPI", value)
        self.dpi_combo.setCurrentIndex(1)
        self.dpi_combo.setToolTip(
            "Controls the resolution of the image rendered from the PDF before OCR."
        )

        self.detection_size_combo = add_row("Detector max side")
        for value in OCR_DETECTION_SIZE_PERCENT_OPTIONS:
            self.detection_size_combo.addItem(f"{value}%", value)
        self.detection_size_combo.setCurrentIndex(
            max(0, self.detection_size_combo.findData(DEFAULT_OCR_DETECTION_SIZE_PERCENT))
        )
        self.detection_size_combo.setToolTip(
            "Percentage of the final rendered page image's longest side used as the detector max side. "
            "The concrete pixel limit is calculated separately for every page; Render DPI remains independent."
        )

        self.workers_combo = add_row("CPU workers")
        maxw = max(1, os.cpu_count() or 4)
        default_workers = _default_cpu_worker_count(maxw)
        for workers in range(1, maxw + 1):
            self.workers_combo.addItem(str(workers), workers)
        self.workers_combo.setCurrentIndex(max(0, min(maxw - 1, default_workers - 1)))

        engine_row = QtWidgets.QHBoxLayout()
        engine_row.setContentsMargins(0, 0, 0, 0)
        engine_row.setSpacing(0)
        engine_label = QtWidgets.QLabel("OCR engine")
        engine_label.setFixedWidth(151)
        engine_row.addWidget(engine_label)
        self.engine_label = QtWidgets.QLabel("ONNX Runtime")
        self.engine_label.setFixedHeight(20)
        self.engine_label.setStyleSheet("color:#4ade80;font-weight:bold;background:transparent;")
        engine_row.addWidget(self.engine_label, 1)

        gpu_info = self.plugin_status.get("gpu_support") or {}
        gpu_installed = bool(gpu_info.get("installed"))
        gpu_supported = bool(gpu_info.get("supported"))
        if gpu_installed:
            gpu_text = "Use GPU"
            gpu_tooltip = "GPU support is installed. The selected detection and recognition models remain unchanged."
        elif gpu_supported:
            gpu_text = "Use GPU  (GPU support not installed)"
            gpu_tooltip = "Install GPU support from Plugins to enable this option."
        else:
            gpu_text = "Use GPU  (GPU support unavailable)"
            gpu_tooltip = gpu_info.get("reason") or "GPU acceleration is unavailable on this system."
        self.gpu_check = QtWidgets.QCheckBox(gpu_text)
        self.gpu_check.setChecked(gpu_installed)
        self.gpu_check.setEnabled(gpu_installed)
        self.gpu_check.setToolTip(gpu_tooltip)
        self.gpu_check.setFixedHeight(18)
        self._gpu_row = QtWidgets.QHBoxLayout()
        self._gpu_row.setContentsMargins(0, 0, 0, 0)
        self._gpu_row.setSpacing(0)
        self._gpu_row.setAlignment(QtCore.Qt.AlignmentFlag.AlignLeft | QtCore.Qt.AlignmentFlag.AlignVCenter)
        self._gpu_row.addWidget(self.gpu_check, 0, QtCore.Qt.AlignmentFlag.AlignLeft | QtCore.Qt.AlignmentFlag.AlignVCenter)

        engine_group = QtWidgets.QVBoxLayout()
        engine_group.setContentsMargins(0, 0, 0, 0)
        engine_group.setSpacing(0)
        engine_group.addLayout(engine_row)
        engine_group.addLayout(self._gpu_row)
        layout.addLayout(engine_group)

        buttons = QtWidgets.QHBoxLayout()
        buttons.addStretch()
        cancel = QtWidgets.QPushButton("Cancel")
        cancel.setFixedWidth(110)
        cancel.clicked.connect(self.reject)
        buttons.addWidget(cancel)
        start_button = QtWidgets.QPushButton("Start OCR")
        start_button.setFixedWidth(125)
        start_button.setStyleSheet(
            "QPushButton{background:#0078d7;color:white;border:none;border-radius:6px;"
            "padding:8px 18px;font-weight:bold;} QPushButton:hover{background:#005fa3;}"
        )
        start_button.clicked.connect(self.accept)
        buttons.addWidget(start_button)
        root.addLayout(buttons)

        self.lang_combo.currentIndexChanged.connect(self._refresh_for_language)
        self.version_combo.currentIndexChanged.connect(self._refresh_pair_choices)
        self.detection_combo.currentIndexChanged.connect(self._refresh_recognition_choices)
        self._refresh_for_language()

    def _populate_combo(self, combo, items, current=None, enabled=True):
        combo.blockSignals(True)
        try:
            combo.clear()
            for text, data in items:
                combo.addItem(text, data)
            combo.setEnabled(bool(items) and enabled)
            if items:
                idx = combo.findData(current)
                combo.setCurrentIndex(idx if idx >= 0 else 0)
        finally:
            combo.blockSignals(False)

    def _language(self):
        return str(self.lang_combo.currentData() or "auto").strip().lower() or "auto"

    def _automatic_pairs(self):
        return [p for p in (self.plugin_status.get("automatic_pairs") or [])
                if isinstance(p, dict) and p.get("onnxruntime_supported")]

    def _version_info(self):
        language = self._language()
        if language == "auto":
            auto = _normalize_ocr_model_pair(self.plugin_status.get("automatic_model")) or {}
            return str(auto.get("ocr_version") or "").strip(), self._automatic_pairs()
        info = ((self.plugin_status.get("language_models") or {}).get(language) or {})
        version = str(self.version_combo.currentData() or "").strip()
        pairs = list(((info.get("models") or {}).get(version) or {}).get("pairs") or [])
        return version, [p for p in pairs if isinstance(p, dict) and p.get("onnxruntime_supported")]

    def _refresh_for_language(self):
        language = self._language()
        if language == "auto":
            auto = _normalize_ocr_model_pair(self.plugin_status.get("automatic_model")) or {}
            version = str(auto.get("ocr_version") or "").strip()
            self._populate_combo(self.version_combo, [(version, version)] if version else [], current=version, enabled=False)
            pairs = self._automatic_pairs()
            if not pairs and auto:
                pairs = [auto]
            preferred = (str(auto.get("detection_model") or ""), str(auto.get("recognition_model") or ""))
            dets = sorted({str(p.get("detection_model") or "") for p in pairs if p.get("detection_model")}, key=str.casefold)
            self._populate_combo(self.detection_combo, [(x, x) for x in dets], current=preferred[0], enabled=True)
            self._refresh_recognition_choices(preferred_rec=preferred[1])
            return

        info = ((self.plugin_status.get("language_models") or {}).get(language) or {})
        versions = info.get("models") or {}
        items = []
        for version in sorted(versions, key=_ocr_model_sort_key, reverse=True):
            pairs = (versions.get(version) or {}).get("pairs") or []
            if any(bool(p.get("onnxruntime_supported")) for p in pairs):
                items.append((version, version))
        self._populate_combo(self.version_combo, items, enabled=True)
        self._refresh_pair_choices()

    def _current_pairs(self):
        _, pairs = self._version_info()
        return pairs

    def _refresh_pair_choices(self):
        language = self._language()
        current_det = self.detection_combo.currentData()
        current_rec = self.recognition_combo.currentData()
        pairs = self._current_pairs()
        if language == "auto":
            auto = _normalize_ocr_model_pair(self.plugin_status.get("automatic_model")) or {}
            current_det = current_det or auto.get("detection_model")
            current_rec = current_rec or auto.get("recognition_model")
        dets = sorted({str(p.get("detection_model") or "") for p in pairs if p.get("detection_model")}, key=str.casefold)
        self._populate_combo(self.detection_combo, [(x, x) for x in dets], current=current_det, enabled=True)
        self._refresh_recognition_choices(preferred_rec=current_rec)

    def _refresh_recognition_choices(self, preferred_rec=None):
        pairs = self._current_pairs()
        det = str(self.detection_combo.currentData() or "").strip()
        recs = sorted({str(p.get("recognition_model") or "") for p in pairs
                       if str(p.get("detection_model") or "").strip() == det and p.get("recognition_model")},
                      key=str.casefold)
        self._populate_combo(self.recognition_combo, [(x, x) for x in recs], current=preferred_rec, enabled=True)

    def _align_gpu_checkbox(self):
        """Kept for compatibility; the GPU control is intentionally left-aligned."""
        return

    def resizeEvent(self, event):
        super().resizeEvent(event)

    def get_config(self):
        return {
            "language": self._language(),
            "ocr_version": self.version_combo.currentData() or "",
            "detection_model": self.detection_combo.currentData() or "",
            "recognition_model": self.recognition_combo.currentData() or "",
            "dpi": self.dpi_combo.currentData() or OCR_DPI,
            "detection_size_percent": int(self.detection_size_combo.currentData() or DEFAULT_OCR_DETECTION_SIZE_PERCENT),
            "workers": int(self.workers_combo.currentData() or 1),
            "use_gpu": bool(self.gpu_check.isChecked() and self.gpu_check.isEnabled()),
        }

def _history_action(method):
    """Record one logical document edit for Edit PDF Undo/Redo history."""
    @wraps(method)
    def wrapped(self, *args, **kwargs):
        if getattr(self, "_history_suspended", False):
            return method(self, *args, **kwargs)

        before = self._capture_edit_state()
        redo_was_nonempty = bool(self._redo_stack)
        try:
            result = method(self, *args, **kwargs)
        except Exception:
            # Operations that allocate thumbnail resources must roll back their own
            # partial work. Do not run the global reachability cleanup here: a
            # failed/cancelled operation may legitimately share thumbnails with the
            # current document, Undo history, or clipboard.
            raise
        after = self._capture_edit_state()

        changed = not self._edit_states_equal(before, after)
        history_trimmed = False
        if changed:
            self._undo_stack.append(before)
            self._redo_stack.clear()
            history_trimmed = bool(self._trim_history())
            self._update_history_buttons()

        # A new edit after Undo intentionally invalidates the old Redo branch.
        # Any thumbnail resources that existed only for that invalidated branch are
        # now unreachable and should be released immediately. Cancellations/no-op
        # operations intentionally do not trigger this global cleanup path.
        if changed and (redo_was_nonempty or history_trimmed):
            try:
                self._cleanup_released_thumbnail_resources()
            except Exception:
                pass

        return result
    return wrapped


# ============================================================
# THUMBNAIL STORAGE / RAM SAFETY HELPERS
# ============================================================
def _get_available_ram_bytes():
    """Return OS-reported available RAM without requiring an extra pip package."""
    try:
        if sys.platform.startswith("linux"):
            with open("/proc/meminfo", "r", encoding="utf-8") as f:
                values = {}
                for line in f:
                    parts = line.split()
                    if len(parts) >= 2 and parts[0].endswith(":"):
                        try:
                            values[parts[0][:-1]] = int(parts[1]) * 1024
                        except Exception:
                            pass
                if values.get("MemAvailable", 0) > 0:
                    return int(values["MemAvailable"])
        elif sys.platform == "win32":
            import ctypes
            class MEMORYSTATUSEX(ctypes.Structure):
                _fields_ = [
                    ("dwLength", ctypes.c_ulong),
                    ("dwMemoryLoad", ctypes.c_ulong),
                    ("ullTotalPhys", ctypes.c_ulonglong),
                    ("ullAvailPhys", ctypes.c_ulonglong),
                    ("ullTotalPageFile", ctypes.c_ulonglong),
                    ("ullAvailPageFile", ctypes.c_ulonglong),
                    ("ullTotalVirtual", ctypes.c_ulonglong),
                    ("ullAvailVirtual", ctypes.c_ulonglong),
                    ("sullAvailExtendedVirtual", ctypes.c_ulonglong),
                ]
            status = MEMORYSTATUSEX()
            status.dwLength = ctypes.sizeof(MEMORYSTATUSEX)
            if ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(status)):
                return int(status.ullAvailPhys)
        elif sys.platform == "darwin":
            import subprocess
            vm_stat = subprocess.check_output(["vm_stat"], text=True, stderr=subprocess.DEVNULL)
            page_size = 4096
            free_pages = 0
            inactive_pages = 0
            speculative_pages = 0
            for line in vm_stat.splitlines():
                if "page size of" in line:
                    try:
                        page_size = int(line.split("page size of", 1)[1].split("bytes", 1)[0].strip())
                    except Exception:
                        pass
                elif line.startswith("Pages free"):
                    free_pages = int(line.split(":", 1)[1].strip().rstrip("."))
                elif line.startswith("Pages inactive"):
                    inactive_pages = int(line.split(":", 1)[1].strip().rstrip("."))
                elif line.startswith("Pages speculative"):
                    speculative_pages = int(line.split(":", 1)[1].strip().rstrip("."))
            return int((free_pages + inactive_pages + speculative_pages) * page_size)
    except Exception:
        pass
    return None


def _format_bytes_human(num_bytes):
    try:
        value = float(max(0, num_bytes))
    except Exception:
        value = 0.0
    units = ("B", "KB", "MB", "GB", "TB")
    idx = 0
    while value >= 1024 and idx < len(units) - 1:
        value /= 1024.0
        idx += 1
    return f"{value:.1f} {units[idx]}"


def _render_thumbnail_pages_worker(pdf_path, page_indices, thumbnail_dpi,
                                   result_queue, worker_index, disk_output_dir=None):
    """Render a contiguous thumbnail page range.

    In memory mode, only plain RGB bytes cross the process boundary. In disk mode,
    workers write JPEGs directly and only the resulting file paths cross the boundary.
    """
    try:
        with fitz.open(pdf_path) as doc:
            for page_idx in page_indices:
                try:
                    page = doc.load_page(page_idx)
                    vr = page.rect
                    target_width = _thumbnail_target_width_for_dpi(vr, thumbnail_dpi)
                    zoom = target_width / max(1.0, vr.width)
                    mat = fitz.Matrix(zoom, zoom)
                    pix = page.get_pixmap(matrix=mat, alpha=False)
                    if disk_output_dir:
                        out_path = os.path.join(
                            disk_output_dir, f"page_{page_idx + 1:06d}.jpg")
                        img = Image.frombytes(
                            "RGB", [pix.width, pix.height], pix.samples)
                        img.save(out_path, format="JPEG", quality=85)
                        result_queue.put((
                            "disk", worker_index, page_idx,
                            int(pix.width), int(pix.height), out_path, None))
                    else:
                        result_queue.put((
                            "memory", worker_index, page_idx,
                            int(pix.width), int(pix.height), bytes(pix.samples), None))
                except Exception as exc:
                    result_queue.put((
                        "page", worker_index, page_idx,
                        0, 0, "", str(exc)))
    except Exception as exc:
        for page_idx in page_indices:
            try:
                result_queue.put((
                    "page", worker_index, page_idx,
                    0, 0, "", f"Worker could not open PDF: {exc}"))
            except Exception:
                pass
    finally:
        try:
            result_queue.put(("done", worker_index, -1, 0, 0, "", None))
        except Exception:
            pass


# ============================================================
# IMAGE OPTIMIZATION HELPERS
# ============================================================
_IMAGE_OPT_INPUT_EXTENSIONS = {".jpg", ".jpeg", ".png", ".webp"}
_IMAGE_OPT_FORMATS = {"jpg", "png", "webp"}


def _image_has_transparency(image):
    try:
        mode = str(image.mode or "")
        if "A" in mode:
            return True
        if mode == "P" and "transparency" in getattr(image, "info", {}):
            return True
    except Exception:
        pass
    return False


def _capture_pillow_metadata(image):
    """Capture common non-pixel metadata without carrying format-specific save state forward."""
    info = dict(getattr(image, "info", {}) or {})
    result = {}
    for key in ("exif", "icc_profile", "xmp", "dpi", "comment"):
        value = info.get(key)
        if value is None:
            continue
        if key in {"exif", "icc_profile"} and isinstance(value, (bytes, bytearray)):
            result[key] = bytes(value)
        elif key == "xmp" and isinstance(value, (bytes, bytearray, str)):
            result[key] = bytes(value) if isinstance(value, (bytes, bytearray)) else value
        elif key == "comment" and isinstance(value, (bytes, bytearray, str)):
            result[key] = bytes(value) if isinstance(value, (bytes, bytearray)) else value
        elif key == "dpi":
            try:
                result[key] = (float(value[0]), float(value[1]))
            except Exception:
                pass

    png_text = getattr(image, "text", None)
    if isinstance(png_text, dict):
        clean_text = {}
        for key, value in png_text.items():
            if isinstance(key, str) and isinstance(value, str):
                clean_text[key] = value
        if clean_text:
            result["png_text"] = clean_text
    return result


def _normalize_pillow_exif_orientation(metadata, orientation):
    if not metadata.get("exif") or orientation in (None, 1):
        return
    try:
        exif = Image.Exif()
        exif.load(metadata["exif"])
        exif[274] = 1
        metadata["exif"] = exif.tobytes()
    except Exception:
        pass


def _prepare_pillow_image(input_path):
    """Load one supported image into memory, bake EXIF orientation, and return source metadata."""
    input_path = os.path.abspath(str(input_path))
    with Image.open(input_path) as source:
        if bool(getattr(source, "is_animated", False)):
            raise RuntimeError("Animated images are not supported by Optimize Images.")
        source.load()
        metadata = _capture_pillow_metadata(source)
        orientation = None
        try:
            orientation = source.getexif().get(274)
        except Exception:
            pass
        image = ImageOps.exif_transpose(source)
    _normalize_pillow_exif_orientation(metadata, orientation)
    return image, metadata


def _resize_pillow_image(image, scale_percent):
    scale = max(1.0, min(100.0, float(scale_percent)))
    if abs(scale - 100.0) < 0.0001:
        return image
    original_width, original_height = [int(v) for v in image.size]
    new_width = max(1, int(round(original_width * scale / 100.0)))
    new_height = max(1, int(round(new_width * original_height / max(1, original_width))))
    if new_width == original_width and new_height == original_height:
        return image
    return image.resize((new_width, new_height), Image.Resampling.LANCZOS)


def _prepare_jpeg_pixels(image):
    if _image_has_transparency(image):
        rgba = image.convert("RGBA")
        background = Image.new("RGB", rgba.size, (255, 255, 255))
        background.paste(rgba, mask=rgba.getchannel("A"))
        return background
    if image.mode in {"RGB", "L"}:
        return image
    return image.convert("RGB")


def _prepare_webp_pixels(image):
    if _image_has_transparency(image):
        return image.convert("RGBA")
    if image.mode in {"RGB", "RGBA", "L"}:
        return image
    return image.convert("RGB")


def _prepare_png_pixels(image):
    if image.mode in {"1", "L", "LA", "P", "RGB", "RGBA", "I;16"}:
        return image
    if image.mode == "I":
        # PNG supports integer data, but Image.save handles 32-bit integer PNGs less uniformly
        # across Pillow builds than the common 8/16-bit modes used by the application.
        return image.convert("L")
    return image.convert("RGB")


def _reduce_png_to_palette(image):
    has_alpha = _image_has_transparency(image)
    if has_alpha:
        rgba = image.convert("RGBA")
        return rgba.quantize(
            colors=256,
            method=Image.Quantize.FASTOCTREE,
            dither=Image.Dither.FLOYDSTEINBERG,
        )
    if image.mode == "L":
        return image.quantize(
            colors=256,
            method=Image.Quantize.MEDIANCUT,
            dither=Image.Dither.FLOYDSTEINBERG,
        )
    rgb = image.convert("RGB")
    return rgb.quantize(
        colors=256,
        method=Image.Quantize.MEDIANCUT,
        dither=Image.Dither.FLOYDSTEINBERG,
    )


def _pillow_save_metadata_kwargs(metadata, target_format, keep_metadata):
    if not keep_metadata:
        return {}
    kwargs = {}
    for key in ("exif", "icc_profile", "xmp", "comment"):
        value = metadata.get(key)
        if value is not None:
            kwargs[key] = value
    dpi = metadata.get("dpi")
    if dpi is not None:
        try:
            kwargs["dpi"] = (float(dpi[0]), float(dpi[1]))
        except Exception:
            pass

    if target_format == "png":
        text_items = metadata.get("png_text") or {}
        if isinstance(text_items, dict) and text_items:
            pnginfo = PngImagePlugin.PngInfo()
            for key, value in text_items.items():
                try:
                    pnginfo.add_text(str(key), str(value))
                except Exception:
                    pass
            kwargs["pnginfo"] = pnginfo
        # PNG does not use WebP/JPEG comment/XMP save arguments consistently across Pillow
        # releases; common textual PNG metadata is already represented above.
        kwargs.pop("comment", None)
        kwargs.pop("xmp", None)
    elif target_format == "jpg":
        kwargs.pop("xmp", None)
    return kwargs


def _normalize_image_format_from_extension(path_or_ext):
    """Normalize supported image extensions so JPG/JPEG are treated as one image type."""
    value = str(path_or_ext or "").strip().lower()
    if not value.startswith("."):
        value = "." + value
    if value in {".jpg", ".jpeg"}:
        return "jpg"
    if value == ".png":
        return "png"
    if value == ".webp":
        return "webp"
    return os.path.splitext(value)[1].lstrip(".")


def _same_image_type(input_path, target_format):
    """Return True only for same logical image-family conversions (JPG/JPEG are one family)."""
    return _normalize_image_format_from_extension(os.path.splitext(str(input_path))[1]) == str(target_format or "").lower()


def _atomic_copy_file(source_path, destination_path):
    """Copy source bytes to destination atomically, avoiding a partially written final file."""
    source_path = os.path.abspath(str(source_path))
    destination_path = os.path.abspath(str(destination_path))
    destination_dir = os.path.dirname(destination_path) or os.getcwd()
    os.makedirs(destination_dir, exist_ok=True)
    temporary_path = os.path.join(
        destination_dir,
        f".mergerz_image_copy_{uuid.uuid4().hex}.tmp",
    )
    try:
        shutil.copyfile(source_path, temporary_path)
        os.replace(temporary_path, destination_path)
    except Exception:
        try:
            if os.path.isfile(temporary_path):
                os.remove(temporary_path)
        except Exception:
            pass
        raise


def _atomic_replace_file(source_path, destination_path):
    """Atomically promote a fully written candidate to its final output path."""
    source_path = os.path.abspath(str(source_path))
    destination_path = os.path.abspath(str(destination_path))
    os.replace(source_path, destination_path)


def _process_one_image_with_pillow(input_path, output_path, settings):
    """Process one image and prevent same-type optimization from ever increasing file size.

    Cross-type conversions use the requested encoding normally. Same-type conversions
    (JPG/JPEG→JPG, PNG→PNG, WebP→WebP) are protected by a size guard: when the generated
    candidate is strictly larger than the source file, the candidate is discarded and an
    exact byte-for-byte copy of the original is written under the intended output name.
    """
    input_path = os.path.abspath(str(input_path))
    output_path = os.path.abspath(str(output_path))
    target_format = str(settings.get("format") or "jpg").lower()
    if target_format not in _IMAGE_OPT_FORMATS:
        raise ValueError(f"Unsupported output format: {target_format}")
    if not os.path.isfile(input_path):
        raise FileNotFoundError(input_path)

    original_size_bytes = int(os.path.getsize(input_path))
    same_type_guard = _same_image_type(input_path, target_format)
    output_dir = os.path.dirname(output_path) or os.getcwd()
    os.makedirs(output_dir, exist_ok=True)
    candidate_path = os.path.join(
        output_dir, f".mergerz_image_candidate_{uuid.uuid4().hex}.tmp")

    try:
        image, metadata = _prepare_pillow_image(input_path)
        image = _resize_pillow_image(image, settings.get("scale_percent", 100))
        keep_metadata = str(settings.get("metadata") or "remove").lower() == "keep"

        if target_format == "jpg":
            image = _prepare_jpeg_pixels(image)
            save_kwargs = {
                "quality": max(0, min(100, int(settings.get("jpeg_quality", 85)))),
                "optimize": bool(settings.get("jpeg_optimize", True)),
                "progressive": bool(settings.get("jpeg_progressive", True)),
            }
            subsampling = str(settings.get("jpeg_subsampling") or "auto")
            if subsampling in {"4:4:4", "4:2:2", "4:2:0"}:
                save_kwargs["subsampling"] = subsampling
            save_kwargs.update(_pillow_save_metadata_kwargs(metadata, "jpg", keep_metadata))
            image.save(candidate_path, format="JPEG", **save_kwargs)
        elif target_format == "webp":
            image = _prepare_webp_pixels(image)
            lossless = str(settings.get("webp_mode") or "lossy").lower() == "lossless"
            save_kwargs = {
                "lossless": lossless,
                "method": max(0, min(6, int(settings.get("webp_method", 4)))),
            }
            if not lossless:
                save_kwargs["quality"] = max(0, min(100, int(settings.get("webp_quality", 80))))
            save_kwargs.update(_pillow_save_metadata_kwargs(metadata, "webp", keep_metadata))
            image.save(candidate_path, format="WEBP", **save_kwargs)
        else:
            image = _prepare_png_pixels(image)
            if str(settings.get("png_color_reduction") or "off").lower() == "palette":
                image = _reduce_png_to_palette(image)
            png_optimize = bool(settings.get("png_optimize", True))
            # Pillow explicitly ignores compress_level when optimize=True and uses level 9.
            # Keep the effective behavior deterministic even if settings come from an older UI.
            png_compression = 9 if png_optimize else max(0, min(9, int(settings.get("png_compression", 9))))
            save_kwargs = {
                "compress_level": png_compression,
                "optimize": png_optimize,
                "interlace": str(settings.get("png_interlace") or "none").lower() == "adam7",
            }
            save_kwargs.update(_pillow_save_metadata_kwargs(metadata, "png", keep_metadata))
            image.save(candidate_path, format="PNG", **save_kwargs)

        if not os.path.isfile(candidate_path):
            raise RuntimeError("Image encoder did not produce an output file.")
        candidate_size_bytes = int(os.path.getsize(candidate_path))
        fallback_used = False

        if same_type_guard and candidate_size_bytes > original_size_bytes:
            # Never let an attempted same-type optimization make the output larger. The
            # fallback is an exact byte-for-byte source copy under the name requested by
            # the output-path generator. This also guarantees output_size == original_size.
            os.remove(candidate_path)
            _atomic_copy_file(input_path, output_path)
            output_size_bytes = int(os.path.getsize(output_path))
            fallback_used = True
        else:
            _atomic_replace_file(candidate_path, output_path)
            output_size_bytes = int(os.path.getsize(output_path))

        return {
            "input_path": input_path,
            "output_path": output_path,
            "original_size": original_size_bytes,
            "output_size": output_size_bytes,
            "candidate_size": candidate_size_bytes,
            "fallback_used": fallback_used,
            "same_type_guard": same_type_guard,
            "width": int(image.width),
            "height": int(image.height),
        }
    except Exception:
        try:
            if os.path.isfile(candidate_path):
                os.remove(candidate_path)
        except Exception:
            pass
        # Do not leave a stale final output behind if this task fails before the final
        # candidate is promoted. The caller already removes generated files on batch failure.
        raise


def _optimize_images_worker(tasks, settings, worker_index, result_queue):
    """Spawn-safe Optimize Images worker; each task is one complete Pillow processing pipeline."""
    try:
        for task in tasks:
            task_index = int(task["task_index"])
            input_path = str(task["input_path"])
            output_path = str(task["output_path"])
            try:
                result = _process_one_image_with_pillow(input_path, output_path, settings)
                result_queue.put((
                    "done", int(worker_index), task_index, output_path,
                    int(result["original_size"]), int(result["output_size"]),
                    int(result["width"]), int(result["height"]), None,
                    bool(result.get("fallback_used", False)),
                ))
            except Exception as exc:
                try:
                    if os.path.isfile(output_path):
                        os.remove(output_path)
                except Exception:
                    pass
                result_queue.put((
                    "error", int(worker_index), task_index, output_path,
                    0, 0, 0, 0, f"{type(exc).__name__}: {exc}",
                ))
    except Exception as exc:
        for task in tasks:
            try:
                result_queue.put((
                    "error", int(worker_index), int(task["task_index"]),
                    str(task["output_path"]), 0, 0, 0, 0,
                    f"Worker could not process image: {type(exc).__name__}: {exc}",
                ))
            except Exception:
                pass
    finally:
        try:
            result_queue.put(("worker_done", int(worker_index), -1, "", 0, 0, 0, 0, None))
        except Exception:
            pass


def _render_selected_image_pages_worker(entries, image_dpi, image_format,
                                         result_queue, worker_index, webp_mode="lossy"):
    """Render selected PDF pages with the editor's canonical ordered page state."""
    image_format = str(image_format or "jpg").lower()
    if image_format not in {"jpg", "png", "webp"}:
        image_format = "jpg"
    source_docs = {}
    try:
        for selection_index, entry, out_path in entries:
            source_pdf = entry.get("source_pdf")
            page_idx = int(entry.get("original_idx", 0))
            ordered_doc = None
            try:
                if _page_design_has_any(entry) and _page_design_anchor_state(entry) is not None:
                    ordered_doc = _page_design_ordered_document(entry, apply_filters=True)
                    page = ordered_doc[0]
                else:
                    if source_pdf not in source_docs:
                        source_docs[source_pdf] = fitz.open(source_pdf)
                    page = source_docs[source_pdf].load_page(page_idx)
                    src_rot = int(page.rotation) % 360
                    apply_entry_to_page(page, entry, src_rot=src_rot)

                rect = page.rect
                if rect.width <= 0 or rect.height <= 0:
                    raise RuntimeError("Page has invalid dimensions after applying edits")
                target_width = _thumbnail_target_width_for_dpi(rect, image_dpi)
                zoom = target_width / max(1.0, float(rect.width))
                pix = page.get_pixmap(matrix=fitz.Matrix(zoom, zoom), alpha=False)
                img = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)

                if ordered_doc is None:
                    filter_cfg = _entry_filter_config(entry)
                    if _filter_config_active(filter_cfg):
                        img = _apply_filter_to_pil_image(img, filter_cfg)
                    stretch_ratio = entry.get("stretch_ratio")
                    if stretch_ratio is not None:
                        sw, sh = calculate_stretch_dimensions(
                            img.width, img.height, float(stretch_ratio))
                        target = (max(1, int(round(sw))), max(1, int(round(sh))))
                        if img.size != target:
                            resample = getattr(Image, "Resampling", Image).LANCZOS
                            img = img.resize(target, resample=resample)
                    img = _page_design_pil_draw(img, entry, image_dpi)

                if image_format == "png":
                    img.save(out_path, format="PNG", optimize=False, compress_level=6)
                elif image_format == "webp":
                    save_kwargs = {"method": 4, "lossless": str(webp_mode or "lossy").lower() == "lossless"}
                    if not save_kwargs["lossless"]:
                        save_kwargs["quality"] = 100
                    img.save(out_path, format="WEBP", **save_kwargs)
                else:
                    img.save(out_path, format="JPEG", quality=85)
                size_bytes = int(os.path.getsize(out_path))
                result_queue.put(("done", worker_index, selection_index,
                                  out_path, size_bytes, int(img.width), int(img.height), None))
            except Exception as exc:
                result_queue.put(("error", worker_index, selection_index,
                                  "", 0, 0, 0, str(exc)))
            finally:
                if ordered_doc is not None:
                    try:
                        ordered_doc.close()
                    except Exception:
                        pass
    except Exception as exc:
        for selection_index, _entry, _out_path in entries:
            result_queue.put(("error", worker_index, selection_index,
                              "", 0, 0, 0, f"Worker could not open source PDF: {exc}"))
    finally:
        for doc in source_docs.values():
            try:
                doc.close()
            except Exception:
                pass
        try:
            result_queue.put(("worker_done", worker_index, -1, "", 0, 0, 0, None))
        except Exception:
            pass


class MemorySafetyDialog(QtWidgets.QDialog):
    """Choose how an image-heavy operation should proceed when RAM is insufficient."""
    def __init__(
        self,
        operation_title,
        detail_text,
        work_label,
        work_count,
        dpi_label,
        dpi_options,
        current_dpi,
        use_memory,
        safety_info,
        parent=None,
        generate_thumbnails=None,
    ):
        super().__init__(parent)
        self.setWindowTitle("Insufficient Memory")
        self.setModal(True)
        self.setMinimumSize(620, 0)
        self.resize(720, 460)
        # Keep the dialog content-sized on normal workloads. Very long safety
        # details are constrained to the available screen height and remain
        # accessible through the scroll area.
        screen = self.screen() or QtWidgets.QApplication.primaryScreen()
        if screen is not None:
            available_height = screen.availableGeometry().height()
            self.setMaximumHeight(max(360, int(available_height * 0.86)))

        outer = QtWidgets.QVBoxLayout(self)
        outer.setContentsMargins(18, 12, 18, 12)
        outer.setSpacing(9)

        # Keep the heading outside the scroll area. The previous all-in-one
        # scroll layout could stretch the labels vertically and create large,
        # uneven gaps above the diagnostic details.
        header = QtWidgets.QWidget(self)
        header_layout = QtWidgets.QVBoxLayout(header)
        header_layout.setContentsMargins(0, 0, 0, 0)
        # Clear, deliberate separation between title, operation subtitle and
        # explanatory copy without wasting vertical space.
        header_layout.setSpacing(8)

        title = QtWidgets.QLabel("Insufficient Memory")
        title.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        title.setSizePolicy(QtWidgets.QSizePolicy.Policy.Preferred, QtWidgets.QSizePolicy.Policy.Fixed)
        title.setStyleSheet(
            "font-size:17pt; font-weight:700; color:#f5b942;")
        header_layout.addWidget(title)

        operation = QtWidgets.QLabel(str(operation_title))
        operation.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        operation.setSizePolicy(QtWidgets.QSizePolicy.Policy.Preferred, QtWidgets.QSizePolicy.Policy.Fixed)
        operation.setStyleSheet(
            "font-size:11.5pt; font-weight:700; color:#e7e7e7;")
        header_layout.addWidget(operation)

        detail = QtWidgets.QLabel(str(detail_text))
        detail.setWordWrap(True)
        detail.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        detail.setSizePolicy(QtWidgets.QSizePolicy.Policy.Preferred, QtWidgets.QSizePolicy.Policy.Maximum)
        detail.setStyleSheet("color:#d0d0d0; font-size:10pt; padding:0 8px;")
        header_layout.addWidget(detail)
        outer.addWidget(header, 0)

        scroll = QtWidgets.QScrollArea(self)
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        scroll.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setStyleSheet("""
            QScrollArea { background: transparent; border: none; }
            QScrollBar:vertical {
                width: 10px; background: #1f1f1f; margin: 2px;
            }
            QScrollBar::handle:vertical {
                background: #444444; border-radius: 5px; min-height: 28px;
            }
            QScrollBar::handle:vertical:hover { background: #555555; }
            QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical,
            QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
                background: none; border: none;
            }
        """)
        content = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(content)
        layout.setContentsMargins(4, 2, 4, 4)
        layout.setSpacing(8)
        layout.setSizeConstraint(QtWidgets.QLayout.SizeConstraint.SetMinimumSize)
        scroll.setWidget(content)
        # Do not give the scroll area a stretch factor: it should request only
        # the height its contents need, up to the dialog's screen-height cap.
        outer.addWidget(scroll, 0)

        info_frame = QtWidgets.QFrame()
        info_frame.setObjectName("memoryInfoFrame")
        info_frame.setStyleSheet(
            "QFrame#memoryInfoFrame { background:#161616; border:1px solid #303030; "
            "border-radius:7px; }")
        info_layout = QtWidgets.QVBoxLayout(info_frame)
        info_layout.setContentsMargins(12, 10, 12, 10)
        info_layout.setSpacing(0)
        info_label = QtWidgets.QLabel(
            self._info_text(
                operation_title, work_label, work_count, current_dpi, safety_info
            )
        )
        info_label.setWordWrap(True)
        info_label.setAlignment(QtCore.Qt.AlignmentFlag.AlignLeft | QtCore.Qt.AlignmentFlag.AlignVCenter)
        info_label.setStyleSheet(
            "background:transparent; border:none; color:#bcbcbc; font-size:9.5pt; "
            "padding:0;")
        info_layout.addWidget(info_label)
        layout.addWidget(info_frame)

        # Keep the emergency choices visually compact. Boxed group sections are
        # reserved for the Settings page; this dialog uses simple aligned rows.
        controls = QtWidgets.QWidget(content)
        cg = QtWidgets.QVBoxLayout(controls)
        cg.setContentsMargins(4, 4, 4, 4)
        cg.setSpacing(10)

        self.thumbnail_generation_group = None
        if generate_thumbnails is not None:
            thumbnails_row = QtWidgets.QHBoxLayout()
            thumbnails_row.setContentsMargins(0, 0, 0, 0)
            thumbnails_row.setSpacing(10)
            thumbnails_label = QtWidgets.QLabel("Generate thumbnails:")
            thumbnails_label.setFixedWidth(165)
            thumbnails_label.setStyleSheet("color:#d8d8d8; font-weight:600;")
            thumbnails_row.addWidget(thumbnails_label)

            self.thumbnail_generation_group = QtWidgets.QButtonGroup(self)
            self.thumbnails_on = QtWidgets.QRadioButton("On")
            self.thumbnails_off = QtWidgets.QRadioButton("Off")
            for radio in (self.thumbnails_on, self.thumbnails_off):
                radio.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
                radio.setStyleSheet("color:#f0f0f0; font-size:9.5pt;")
                self.thumbnail_generation_group.addButton(radio)
                thumbnails_row.addWidget(radio)
            self.thumbnails_on.setChecked(bool(generate_thumbnails))
            self.thumbnails_off.setChecked(not bool(generate_thumbnails))
            thumbnails_row.addStretch(1)
            cg.addLayout(thumbnails_row)

        dpi_row = QtWidgets.QHBoxLayout()
        dpi_row.setContentsMargins(0, 0, 0, 0)
        dpi_row.setSpacing(10)
        dpi_lbl = QtWidgets.QLabel(str(dpi_label))
        dpi_lbl.setFixedWidth(165)
        dpi_lbl.setStyleSheet("color:#d8d8d8; font-weight:600;")
        dpi_row.addWidget(dpi_lbl)

        self.dpi_combo = QtWidgets.QComboBox()
        self.dpi_combo.setFixedWidth(112)
        self.dpi_combo.setStyleSheet("""
            QComboBox {
                background:#2a2a2a; color:#f0f0f0;
                border:1px solid #3a3a3a; border-radius:5px; padding:3px 6px;
            }
            QComboBox:hover { border-color:#5a9bd5; }
            QComboBox QAbstractItemView {
                background:#2a2a2a; color:#f0f0f0;
                selection-background-color:#315b82;
            }
        """)
        for value in dpi_options:
            self.dpi_combo.addItem(f"{int(value)} dpi", int(value))
        idx = self.dpi_combo.findData(int(current_dpi))
        self.dpi_combo.setCurrentIndex(max(0, idx))
        dpi_row.addWidget(self.dpi_combo)
        dpi_row.addStretch(1)
        cg.addLayout(dpi_row)

        memory_row = QtWidgets.QHBoxLayout()
        memory_row.setContentsMargins(0, 0, 0, 0)
        memory_row.setSpacing(10)
        memory_label = QtWidgets.QLabel("Use memory:")
        memory_label.setFixedWidth(165)
        memory_label.setStyleSheet("color:#d8d8d8; font-weight:600;")
        memory_row.addWidget(memory_label)

        self.mode_group = QtWidgets.QButtonGroup(self)
        self.mode_radios = {}
        mode_specs = (
            ("auto", "Auto"),
            ("on", "On"),
            ("off", "Off"),
        )
        selected_mode = str(use_memory or "auto").strip().lower()
        if selected_mode not in {"auto", "on", "off"}:
            selected_mode = "auto"

        for key, label in mode_specs:
            radio = QtWidgets.QRadioButton(label)
            radio.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
            radio.setStyleSheet("color:#f0f0f0; font-size:9.5pt;")
            radio.setChecked(key == selected_mode)
            self.mode_group.addButton(radio)
            self.mode_radios[key] = radio
            memory_row.addWidget(radio)

        memory_row.addStretch(1)
        cg.addLayout(memory_row)
        layout.addWidget(controls)
        btns = QtWidgets.QHBoxLayout()
        btns.setSpacing(10)
        btns.addStretch()
        cancel = QtWidgets.QPushButton("Cancel")
        cancel.setFixedWidth(115)
        cancel.clicked.connect(self.reject)
        btns.addWidget(cancel)

        apply_btn = QtWidgets.QPushButton("Apply and Continue")
        apply_btn.setFixedWidth(170)
        apply_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        apply_btn.setStyleSheet("""
            QPushButton {
                background-color:#0078d7; color:white; border:none;
                border-radius:6px; padding:8px 16px; font-weight:bold;
            }
            QPushButton:hover { background-color:#005fa3; }
        """)
        apply_btn.clicked.connect(self.accept)
        btns.addWidget(apply_btn)
        outer.addLayout(btns)
        # Recompute from the completed layouts so the initial window fits the
        # diagnostic panel and controls instead of retaining the old tall size.
        self.adjustSize()

    @staticmethod
    def _info_text(operation_title, work_label, work_count, current_dpi, info):
        lines = [
            f"Operation: {operation_title}",
            f"{work_label}: {int(work_count)}",
            f"Current quality/target: {int(current_dpi)} dpi",
        ]
        available = info.get("available")
        if available is None:
            lines.append("Available RAM: Could not be measured")
        else:
            lines.append(f"Available RAM: {_format_bytes_human(available)}")
        if info.get("per_unit") is not None:
            lines.append(
                f"Measured sample memory: {_format_bytes_human(info.get('per_unit', 0))}"
            )
        if info.get("required") is not None:
            lines.append(
                f"Estimated memory required: {_format_bytes_human(info.get('required', 0))}"
            )
        if info.get("safe_budget") is not None:
            lines.append(
                f"Safe RAM budget: {_format_bytes_human(info.get('safe_budget', 0))}"
            )
        if info.get("capacity") is not None and info.get("capacity") > 0:
            lines.append(f"Estimated safe capacity: {int(info['capacity'])} {work_label.lower()}")
        reason = str(info.get("reason") or "").strip()
        if reason and reason not in {"OK"}:
            lines.append(f"Check: {reason}")
        return "\n".join(lines)

    def get_settings(self):
        selected = "auto"
        for key, radio in self.mode_radios.items():
            if radio.isChecked():
                selected = key
                break
        result = {
            "dpi": int(self.dpi_combo.currentData()),
            "use_memory": selected,
        }
        if self.thumbnail_generation_group is not None:
            result["generate_thumbnails"] = bool(self.thumbnails_on.isChecked())
        return result


class ImageFormatDetailsDialog(QtWidgets.QDialog):
    """Explain the image formats offered by PDF page/image export workflows."""
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Image format details")
        self.setModal(True)
        self.setFixedWidth(760)
        self.resize(760, 620)
