class PageRangeDialog(QtWidgets.QDialog):
    """Modern, self-correcting page-range selector."""
    def __init__(self, total_pages, parent=None):
        super().__init__(parent)
        self.total_pages = max(1, int(total_pages))
        self.page_range = None
        self.setWindowTitle("Select Page Range")
        self.setModal(True)
        self.setMinimumSize(430, 165)

        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(24, 20, 24, 18)
        layout.setSpacing(14)

        row = QtWidgets.QHBoxLayout()
        row.setSpacing(8)
        row.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)

        label_from = QtWidgets.QLabel("Select pages from")
        label_from.setStyleSheet("font-size: 11pt; color: #f0f0f0;")
        row.addWidget(label_from)

        self.from_spin = QtWidgets.QSpinBox()
        self.from_spin.setRange(1, self.total_pages)
        self.from_spin.setValue(1)
        self.from_spin.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.from_spin.setMinimumWidth(74)
        self.from_spin.setToolTip(f"Page number from 1 to {self.total_pages}")
        row.addWidget(self.from_spin)

        label_to = QtWidgets.QLabel("to")
        label_to.setStyleSheet("font-size: 11pt; color: #f0f0f0;")
        row.addWidget(label_to)

        self.to_spin = QtWidgets.QSpinBox()
        self.to_spin.setRange(1, self.total_pages)
        self.to_spin.setValue(self.total_pages)
        self.to_spin.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.to_spin.setMinimumWidth(74)
        self.to_spin.setToolTip(f"Page number from 1 to {self.total_pages}")
        row.addWidget(self.to_spin)

        layout.addLayout(row)

        hint = QtWidgets.QLabel(
            f"Pages are limited to 1–{self.total_pages}. The range is kept valid automatically.")
        hint.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        hint.setStyleSheet("color: #7f7f7f; font-size: 9pt;")
        layout.addWidget(hint)

        button_row = QtWidgets.QHBoxLayout()
        button_row.setSpacing(10)
        button_row.addStretch()

        cancel_btn = QtWidgets.QPushButton("Cancel")
        cancel_btn.setFixedWidth(105)
        cancel_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        button_row.addWidget(cancel_btn)

        confirm_btn = QtWidgets.QPushButton("Confirm")
        confirm_btn.setFixedWidth(115)
        confirm_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        confirm_btn.setDefault(True)
        button_row.addWidget(confirm_btn)
        layout.addLayout(button_row)

        cancel_btn.clicked.connect(self.reject)
        confirm_btn.clicked.connect(self._confirm)
        self.from_spin.valueChanged.connect(self._from_changed)
        self.to_spin.valueChanged.connect(self._to_changed)
        self.from_spin.editingFinished.connect(self._normalize)
        self.to_spin.editingFinished.connect(self._normalize)

        self._normalizing = False
        self._normalize()

    def _normalize(self):
        if self._normalizing:
            return
        self._normalizing = True
        try:
            maximum = self.total_pages
            start = min(max(1, self.from_spin.value()), maximum)
            end = min(max(1, self.to_spin.value()), maximum)
            # Equal endpoints are valid: selecting X to X means page X only.
            # When the user crosses the endpoints, keep the edited endpoint and
            # move the other endpoint to the same page rather than adding/removing
            # an adjacent page implicitly.
            if start > end:
                if self.sender() is self.from_spin:
                    end = start
                elif self.sender() is self.to_spin:
                    start = end
                else:
                    end = start
            self.from_spin.setValue(start)
            self.to_spin.setValue(end)
        finally:
            self._normalizing = False

    def _from_changed(self, value):
        if self._normalizing or self.total_pages < 1:
            return
        if value > self.to_spin.value():
            self._normalizing = True
            try:
                self.to_spin.setValue(value)
            finally:
                self._normalizing = False

    def _to_changed(self, value):
        if self._normalizing or self.total_pages < 1:
            return
        if value < self.from_spin.value():
            self._normalizing = True
            try:
                self.from_spin.setValue(value)
            finally:
                self._normalizing = False

    def _confirm(self):
        self._normalize()
        start = min(max(1, self.from_spin.value()), self.total_pages)
        end = min(max(1, self.to_spin.value()), self.total_pages)
        if start <= end:
            self.page_range = (start, end)
            self.accept()


def _thumbnail_disk_root():
    return os.path.join(TEMP_FOLDER, "thumbnail")


def _make_thumbnail_disk_job_dir():
    import tempfile
    root = _thumbnail_disk_root()
    os.makedirs(root, exist_ok=True)
    return tempfile.mkdtemp(prefix="job_", dir=root)


def _cleanup_thumbnail_disk_job_dir(path):
    if not path:
        return
    try:
        shutil.rmtree(path, ignore_errors=True)
    except Exception:
        pass


def _estimate_thumbnail_memory_safety(pdf_path, total_pages, thumbnail_dpi):
    """Conservatively estimate in-memory thumbnail cost from the first two pages.

    Single-page PDFs are intentionally skipped by the caller. For multi-page PDFs,
    page 1 and page 2 are rendered independently using the same pixel-to-Qt path as
    the in-memory thumbnail pipeline. Each sample is fully released before the next
    one is rendered. The larger measured buffer footprint is used as the approximate
    per-page RAM requirement so an unusually small or blank first page cannot make the
    safety check falsely optimistic.
    """
    available = _get_available_ram_bytes()
    if available is None:
        return {
            "available": None, "required": None, "per_page": None,
            "capacity": None, "safe": True,
            "samples": [],
            "reason": "RAM information is unavailable on this system."
        }

    if total_pages <= 0:
        return {
            "available": available, "required": 0, "per_page": 0,
            "capacity": 0, "safe": True, "samples": [],
            "reason": "No pages to render."
        }

    sample_indices = [0]
    if total_pages >= 2:
        sample_indices.append(1)

    samples = []

    def measure_page(page_idx):
        """Render one page through the thumbnail representation and measure its buffers."""
        with fitz.open(pdf_path) as doc:
            page = doc.load_page(page_idx)
            rect = page.rect
            target_width = _thumbnail_target_width_for_dpi(rect, thumbnail_dpi)
            zoom = target_width / max(1.0, float(rect.width))
            pix = page.get_pixmap(
                matrix=fitz.Matrix(zoom, zoom), alpha=False)
            width = int(pix.width)
            height = int(pix.height)
            channels = int(getattr(pix, "n", 3) or 3)

            raw = pix.samples
            raw_size = int(width * height * channels)

            fmt = (QtGui.QImage.Format.Format_RGB888
                   if channels == 3
                   else QtGui.QImage.Format.Format_RGBA8888)
            qimg = QtGui.QImage(
                raw, width, height, width * channels, fmt).copy()
            try:
                qimg_size = int(qimg.sizeInBytes())
            except Exception:
                qimg_size = int(width * height * channels)

            qpix = QtGui.QPixmap.fromImage(qimg)
            if qpix.isNull():
                raise RuntimeError("Qt could not create the thumbnail pixmap")
            try:
                qpix_size = int(qpix.sizeInBytes())
            except Exception:
                try:
                    qpix_size = int(qpix.toImage().sizeInBytes())
                except Exception:
                    qpix_size = int(width * height * 4)

            # Count all three representations that can coexist during creation:
            # MuPDF RGB bytes, the copied QImage, and the resulting QPixmap. This is
            # deliberately conservative because this check is a RAM safety gate.
            total_buffer = int(raw_size + qimg_size + qpix_size)

            return {
                "sample_page": int(page_idx),
                "width": width,
                "height": height,
                "sample_width_pt": float(rect.width),
                "sample_height_pt": float(rect.height),
                "raw_size": raw_size,
                "qimg_size": qimg_size,
                "qpix_size": qpix_size,
                "memory": total_buffer,
            }

    try:
        for page_idx in sample_indices:
            try:
                sample = measure_page(page_idx)
                samples.append(sample)
            finally:
                # Make the C++/Python image objects and any temporary buffers from
                # this sample unreachable before the next sample is rendered. The
                # helper's local scope already releases them; gc adds another pass
                # before we proceed to the next page.
                gc.collect()

        if not samples:
            raise RuntimeError("No safety-check sample could be rendered.")

        per_page = max(int(s["memory"]) for s in samples)
        worst = max(samples, key=lambda s: int(s["memory"]))
    except Exception as exc:
        gc.collect()
        return {
            "available": available,
            "required": None,
            "per_page": None,
            "capacity": None,
            "safe": False,
            "samples": samples,
            "reason": f"Could not render the safety-check sample page: {exc}"
        }

    # Keep 40% of currently available RAM outside the thumbnail workload. The
    # page figure is based on the larger of the two real sample buffer footprints.
    safe_budget = int(available * 0.60)
    capacity = int(safe_budget // max(1, per_page))
    required = int(total_pages * per_page)
    safe = capacity >= total_pages
    return {
        "available": available,
        "required": required,
        "per_page": per_page,
        "capacity": capacity,
        "safe": safe,
        "samples": samples,
        "worst_sample_page": int(worst["sample_page"]),
        "worst_width": int(worst["width"]),
        "worst_height": int(worst["height"]),
        "safe_budget": safe_budget,
        "reason": "OK" if safe else "Estimated thumbnail memory exceeds the safe RAM budget."
    }

def _thumbnail_sample_log(info, thumbnail_dpi, total_pages):
    if info.get("available") is None:
        return (
            f"Safety Check: RAM information unavailable; proceeding conservatively "
            f"at {thumbnail_dpi} DPI."
        )

    lines = [
        f"PDF pages: {total_pages}",
        f"Current quality: {thumbnail_dpi} dpi",
        f"Available RAM: {_format_bytes_human(info['available'])}",
    ]

    samples = info.get("samples") or []
    for sample in samples:
        lines.append(
            f"Sample page {int(sample.get('sample_page', 0)) + 1}: "
            f"{int(sample.get('width', 0))}×{int(sample.get('height', 0))} px — "
            f"{_format_bytes_human(sample.get('memory', 0))}"
        )

    lines.append(
        f"Worst measured thumbnail memory per page: "
        f"{_format_bytes_human(info.get('per_page', 0))}"
    )
    lines.append(
        f"Estimated safe capacity: {info.get('capacity', 0)} page(s)"
    )
    return "\n".join(lines)




class _FilterSliderRow(QtWidgets.QWidget):
    """Minimal labelled slider row used by Apply Filters."""
    valueChanged = QtCore.Signal(float)

    def __init__(self, label, minimum, maximum, value, step=1.0, decimals=0, parent=None):
        super().__init__(parent)
        self._minimum = float(minimum)
        self._maximum = float(maximum)
        self._step = float(step)
        self._decimals = int(decimals)
        self._scale = 10 ** self._decimals

        row = QtWidgets.QHBoxLayout(self)
        row.setContentsMargins(0, 1, 0, 1)
        row.setSpacing(8)

        self.label = QtWidgets.QLabel(label)
        self.label.setMinimumWidth(94)
        self.label.setStyleSheet(
            "color:#d8d8d8; background:transparent; border:none; padding:0; margin:0;")
        row.addWidget(self.label)

        self.slider = QtWidgets.QSlider(QtCore.Qt.Orientation.Horizontal)
        self.slider.setRange(
            int(round(self._minimum * self._scale)),
            int(round(self._maximum * self._scale)),
        )
        self.slider.setSingleStep(max(1, int(round(self._step * self._scale))))
        self.slider.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.slider.setFixedHeight(18)
        self.slider.setStyleSheet("""
            QSlider { background: transparent; border: none; padding: 0; }
            QSlider::groove:horizontal {
                height: 4px; background: #30343a; border: none; border-radius: 2px;
            }
            QSlider::sub-page:horizontal {
                height: 4px; background: #1686d8; border: none; border-radius: 2px;
            }
            QSlider::add-page:horizontal {
                height: 4px; background: #30343a; border: none; border-radius: 2px;
            }
            QSlider::handle:horizontal {
                width: 13px; height: 13px; margin: -4.5px 0;
                background: #e7edf3; border: 1px solid #7b8794; border-radius: 6.5px;
            }
            QSlider::handle:horizontal:disabled {
                background: #656a70; border: 1px solid #555960;
            }
            QSlider::sub-page:horizontal:disabled { background: #4b4f54; }
            QSlider::add-page:horizontal:disabled { background: #2a2d31; }
        """)
        row.addWidget(self.slider, 1)

        self.value_label = QtWidgets.QLabel("")
        self.value_label.setAlignment(QtCore.Qt.AlignmentFlag.AlignRight | QtCore.Qt.AlignmentFlag.AlignVCenter)
        self.value_label.setMinimumWidth(48)
        self.value_label.setStyleSheet(
            "color:#aeb6bf; background:transparent; border:none; padding:0; margin:0;")
        row.addWidget(self.value_label)

        self.slider.valueChanged.connect(self._on_slider)
        self.setValue(value)

    def _on_slider(self, raw):
        value = raw / self._scale
        if self._decimals:
            value = round(value, self._decimals)
            text = f"{value:.{self._decimals}f}"
        else:
            value = int(round(value))
            text = str(value)
        self.value_label.setText(text)
        self.valueChanged.emit(float(value))

    def value(self):
        return self.slider.value() / self._scale

    def setValue(self, value):
        value = max(self._minimum, min(self._maximum, float(value)))
        self.slider.blockSignals(True)
        self.slider.setValue(int(round(value * self._scale)))
        self.slider.blockSignals(False)
        self._on_slider(self.slider.value())

    def setRange(self, minimum, maximum):
        self._minimum = float(minimum)
        self._maximum = float(maximum)
        self.slider.setRange(int(round(minimum * self._scale)),
                             int(round(maximum * self._scale)))


class ApplyFiltersDialog(QtWidgets.QDialog):
    """Live, non-destructive PDF-native filter editor for selected Edit PDF pages."""
    _CARD = ("QFrame { background:#161616; border:1px solid #2d2d2d; "
             "border-radius:8px; }")
    _SECTION = ("QLabel { color:#f0f0f0; font-size:10.5pt; font-weight:bold; "
                "background:transparent; border:none; padding:0; margin:0; }")
    _TEXT_LABEL = "QLabel { background:transparent; border:none; padding:0; margin:0; }"

    def __init__(self, page_edit, selected_entries, selected_anchor=0, parent=None):
        super().__init__(parent or page_edit)
        self.page_edit = page_edit
        # Keep the original Edit PDF grid rows alongside the entry snapshots.
        # The preview needs the real dummy-page position (e.g. 8/10), not the
        # compact selection position (e.g. 1/7).
        self._selected_row_entries = []
        for row, entry in selected_entries:
            try:
                row = int(row)
            except (TypeError, ValueError):
                row = len(self._selected_row_entries)
            self._selected_row_entries.append((row, copy.deepcopy(entry)))
        self.selected_entries = [copy.deepcopy(entry) for _, entry in self._selected_row_entries]
        self._initial_configs = [_entry_filter_config(e) for e in self.selected_entries]
        self._custom_config = self._common_or_neutral(self._initial_configs)
        self._mode = "Custom"
        self._updating = False
        self._preview_timer = QtCore.QTimer(self)
        self._preview_timer.setSingleShot(True)
        self._preview_timer.setInterval(20)
        self._preview_timer.timeout.connect(self._render_preview_now)
        self._pending_preview_config = None
        self._filter_preview_shutdown = False
        self._actual_preview_idle_timer = QtCore.QTimer(self)
        self._actual_preview_idle_timer.setSingleShot(True)
        self._actual_preview_idle_timer.setInterval(850)
        self._actual_preview_idle_timer.timeout.connect(self._start_actual_filter_preview)
        self._actual_preview_poll_timer = QtCore.QTimer(self)
        self._actual_preview_poll_timer.setInterval(50)
        self._actual_preview_poll_timer.timeout.connect(self._poll_actual_filter_preview)
        self._actual_preview_process = None
        self._actual_preview_conn = None
        self._actual_preview_candidate = None
        self._actual_preview_job_nav_index = -1
        self._actual_preview_generation = 0
        self._actual_preview_retired_jobs = []
        self._actual_preview_reaper_timer = QtCore.QTimer(self)
        self._actual_preview_reaper_timer.setInterval(60)
        self._actual_preview_reaper_timer.timeout.connect(self._reap_actual_preview_processes)

        self.setWindowTitle("Apply Filters")
        self.setModal(True)
        self.setMinimumSize(930, 610)
        screen = QtWidgets.QApplication.primaryScreen()
        if screen is not None:
            geom = screen.availableGeometry()
            self.resize(min(1180, max(930, geom.width() - 70)),
                        min(760, max(610, geom.height() - 90)))
        else:
            self.resize(1120, 700)

        root = QtWidgets.QVBoxLayout(self)
        root.setContentsMargins(18, 16, 18, 16)
        root.setSpacing(10)

        header = QtWidgets.QHBoxLayout()
        header.setContentsMargins(0, 0, 0, 2)
        title = QtWidgets.QLabel("Apply filters for selected pages")
        title.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        title.setStyleSheet(
            "font-size:14pt; font-weight:bold; color:#f0f0f0; "
            "background:transparent; border:none; padding:0; margin:0;")
        header.addWidget(title, 1)
        root.addLayout(header)

        splitter = QtWidgets.QSplitter(QtCore.Qt.Orientation.Horizontal)
        splitter.setChildrenCollapsible(False)
        root.addWidget(splitter, 1)

        # LEFT: filter chooser + embedded viewer.
        left = QtWidgets.QWidget()
        left_layout = QtWidgets.QVBoxLayout(left)
        left_layout.setContentsMargins(0, 0, 0, 0)
        left_layout.setSpacing(8)

        filters_card = QtWidgets.QFrame()
        filters_card.setStyleSheet(self._CARD)
        fc = QtWidgets.QVBoxLayout(filters_card)
        fc.setContentsMargins(10, 9, 10, 9)
        fc.setSpacing(6)
        flabel = QtWidgets.QLabel("Filters")
        flabel.setStyleSheet(self._SECTION)
        fc.addWidget(flabel)
        self.filter_group = QtWidgets.QButtonGroup(self)
        self.filter_group.setExclusive(True)
        fgrid = QtWidgets.QGridLayout()
        fgrid.setHorizontalSpacing(6)
        fgrid.setVerticalSpacing(6)
        self.filter_buttons = {}
        for button_index, name in enumerate((
                "Custom", "Invert", "Inv. (no images)",
                "Inv. (images only)", "Grayscale")):
            b = QtWidgets.QPushButton(name)
            b.setCheckable(True)
            b.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
            b.setMinimumHeight(34)
            b.setStyleSheet("""
                QPushButton { background:#242424; color:#d8d8d8; border:1px solid #363636;
                    border-radius:6px; padding:6px 14px; font-weight:bold; }
                QPushButton:hover { background:#303030; }
                QPushButton:checked { background:#0a3a5c; color:#ffffff; border:1px solid #0078d7; }
            """)
            if name == "Inv. (no images)":
                b.setToolTip(
                    "Invert page artwork while preserving embedded raster-image appearance. "
                    "The saved/exact result stays vector-native; the instant preview is an approximation.")
            elif name == "Inv. (images only)":
                b.setToolTip(
                    "Invert embedded images only, leaving text, vector artwork and page background unchanged. "
                    "The instant preview temporarily shows a full-page inversion for responsiveness.")
            elif name == "Invert":
                b.setToolTip("Invert all page artwork, including embedded raster images.")
            self.filter_group.addButton(b)
            self.filter_buttons[name] = b
            fgrid.addWidget(b, button_index // 3, button_index % 3)
        fc.addLayout(fgrid)
        left_layout.addWidget(filters_card)

        viewer_card = QtWidgets.QFrame()
        viewer_card.setStyleSheet("QFrame { background:#0f0f0f; border:1px solid #2d2d2d; border-radius:8px; }")
        vc = QtWidgets.QVBoxLayout(viewer_card)
        vc.setContentsMargins(4, 4, 4, 4)
        vc.setSpacing(0)
        nav_items = []
        for row, entry in self._selected_row_entries:
            d = dict(entry)
            d['grid_row'] = row
            nav_items.append(d)
        initial_index = max(0, min(int(selected_anchor), max(0, len(nav_items) - 1))) if nav_items else 0
        self.viewer = LightweightPageViewer(
            self.selected_entries[initial_index]['source_pdf'] if nav_items else "",
            self.selected_entries[initial_index].get('original_idx', 0) if nav_items else 0,
            rotation=self.selected_entries[initial_index].get('rotation', 0) if nav_items else 0,
            crop=self.selected_entries[initial_index].get('crop') if nav_items else None,
            flip_h=bool(self.selected_entries[initial_index].get('flip_h', False)) if nav_items else False,
            flip_v=bool(self.selected_entries[initial_index].get('flip_v', False)) if nav_items else False,
            parent=viewer_card, nav_items=nav_items, nav_index=initial_index,
            show_selected_label=True, total_dummy=self.page_edit.grid.count(),
            embedded=True, filter_preview_config=self._custom_config,
        )
        vc.addWidget(self.viewer, 1)
        self.viewer.pageChanged.connect(self._on_viewer_page_changed)
        left_layout.addWidget(viewer_card, 1)
        splitter.addWidget(left)

        # RIGHT: scrollable adjustment panel.
        self.adjust_scroll = QtWidgets.QScrollArea()
        self.adjust_scroll.setWidgetResizable(True)
        self.adjust_scroll.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        self.adjust_scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.adjust_scroll.setStyleSheet("QScrollArea { border:none; background:transparent; }")
        right_inner = QtWidgets.QWidget()
        self.adjust_layout = QtWidgets.QVBoxLayout(right_inner)
        self.adjust_layout.setContentsMargins(2, 0, 4, 0)
        self.adjust_layout.setSpacing(8)

        self.controls = []
        adjustments_header = QtWidgets.QHBoxLayout()
        adjustments_header.setContentsMargins(0, 0, 0, 0)
        adjustments_header.setSpacing(6)

        adjustments_title = QtWidgets.QLabel("Adjustments")
        adjustments_title.setStyleSheet(
            "font-size:11pt; font-weight:bold; color:#f0f0f0; "
            "background:transparent; border:none; padding:0 0 0 2px; margin:0;")
        adjustments_header.addWidget(adjustments_title)
        adjustments_header.addStretch()

        self.import_btn = QtWidgets.QPushButton("Import")
        self.import_btn.setFixedHeight(30)
        self.import_btn.setMinimumWidth(82)
        self.import_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.import_btn.setToolTip("Import Custom filter adjustments from a JSON file")
        self.import_btn.setStyleSheet("""
            QPushButton {
                background:#242424; color:#d8d8d8; border:1px solid #363636;
                border-radius:5px; padding:5px 12px; font-weight:bold;
            }
            QPushButton:hover { background:#303030; }
            QPushButton:pressed { background:#3a3a3a; }
        """)
        self.import_btn.clicked.connect(self._import_custom_adjustments)
        adjustments_header.addWidget(self.import_btn)

        self.export_btn = QtWidgets.QPushButton("Export")
        self.export_btn.setFixedHeight(30)
        self.export_btn.setMinimumWidth(82)
        self.export_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.export_btn.setToolTip("Export the current Custom filter adjustments to a JSON file")
        self.export_btn.setStyleSheet("""
            QPushButton {
                background:#242424; color:#d8d8d8; border:1px solid #363636;
                border-radius:5px; padding:5px 12px; font-weight:bold;
            }
            QPushButton:hover { background:#303030; }
            QPushButton:pressed { background:#3a3a3a; }
        """)
        self.export_btn.clicked.connect(self._export_custom_adjustments)
        adjustments_header.addWidget(self.export_btn)

        self.adjust_layout.addLayout(adjustments_header)
        self._build_layer_section()
        self._build_tone_section()
        self._build_color_section()
        self._build_special_section()
        self._build_advanced_gamma_section()
        self.adjust_layout.addStretch()
        self.adjust_scroll.setWidget(right_inner)
        splitter.addWidget(self.adjust_scroll)
        splitter.setSizes([560, 480])

        bottom = QtWidgets.QHBoxLayout()
        bottom.setSpacing(8)
        self.reset_btn = QtWidgets.QPushButton("Reset")
        self.reset_btn.setFixedWidth(110)
        self.reset_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.reset_btn.setStyleSheet("""
            QPushButton {
                background:#2a2a2a; color:#f0f0f0; border:1px solid #3a3a3a;
                border-radius:6px; padding:8px 16px; font-weight:bold;
            }
            QPushButton:hover { background:#343434; }
            QPushButton:pressed { background:#3c3c3c; }
            QPushButton:disabled { background:#222222; color:#666666; border:1px solid #2a2a2a; }
        """)
        self.reset_btn.clicked.connect(self._reset_to_custom_defaults)
        bottom.addWidget(self.reset_btn)

        bottom.addStretch()
        cancel_btn = QtWidgets.QPushButton("Cancel")
        cancel_btn.setFixedWidth(120)
        cancel_btn.clicked.connect(self.reject)
        bottom.addWidget(cancel_btn)
        self.apply_btn = QtWidgets.QPushButton("Apply Filters")
        self.apply_btn.setFixedWidth(145)
        self.apply_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.apply_btn.setStyleSheet("""
            QPushButton { background:#0078d7; color:white; border:none; border-radius:6px;
                padding:8px 16px; font-weight:bold; }
            QPushButton:hover { background:#005fa3; }
            QPushButton:disabled { background:#2b2b2b; color:#696969; border:1px solid #3a3a3a; }
        """)
        self.apply_btn.clicked.connect(self._apply)
        bottom.addWidget(self.apply_btn)
        root.addLayout(bottom)

        self.filter_group.buttonClicked.connect(self._filter_button_clicked)
        self._set_initial_common_filter_state()
        self._update_reset_enabled()
        self._update_apply_enabled()
        QtCore.QTimer.singleShot(0, self._refresh_preview)

    @staticmethod
    def _validate_imported_adjustments(payload):
        """Validate an imported Custom filter JSON object without silently clamping values."""
        if not isinstance(payload, dict):
            raise ValueError("The JSON root must be an object.")

        # Accept the native Mergerz export envelope. A plain adjustment object is also accepted
        # for convenience when a user manually edits a JSON file.
        if "adjustments" in payload:
            if payload.get("format") != "Mergerz Custom Filter" or payload.get("version") != 1:
                raise ValueError("Unsupported Mergerz filter JSON format or version.")
            config = payload.get("adjustments")
        else:
            config = payload

        if not isinstance(config, dict):
            raise ValueError("The JSON adjustments field must be an object.")

        # Older filter exports predate the image-aware inversion flags. Treat missing
        # fields as their legacy/default false values so existing exports remain importable.
        config = dict(config)
        config.setdefault("invert_exclude_images", False)
        config.setdefault("invert_images_only", False)
        missing = [key for key in FILTER_CONFIG_KEYS if key not in config]
        if missing:
            raise ValueError("Missing adjustment field(s): " + ", ".join(missing))

        allowed = set(FILTER_CONFIG_KEYS)
        unexpected = sorted(set(config) - allowed)
        if unexpected:
            raise ValueError("Unknown adjustment field(s): " + ", ".join(unexpected))

        def number(key, lo, hi):
            value = config[key]
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(f"{key} must be a number.")
            value = float(value)
            if not math.isfinite(value) or value < lo or value > hi:
                raise ValueError(f"{key} must be between {lo:g} and {hi:g}.")

        color = config["layer_color"]
        if not isinstance(color, str) or not re.fullmatch(r"#[0-9a-fA-F]{6}", color.strip()):
            raise ValueError("layer_color must be a six-digit hexadecimal color such as #ffffff.")

        blend_mode = config["blend_mode"]
        if not isinstance(blend_mode, str) or blend_mode not in FILTER_BLEND_MODES:
            raise ValueError("blend_mode is not a supported filter blend mode.")

        ranges = {
            "opacity": (0, 100),
            "brightness": (-100, 100),
            "contrast": (-100, 100),
            "gamma": (0.2, 5.0),
            "black_point": (0, 100),
            "white_point": (0, 100),
            "saturation": (0, 100),
            "warmth": (-100, 100),
            "tint": (-100, 100),
            "grayscale": (0, 100),
            "invert": (0, 100),
            "threshold": (0, 100),
        }
        for key, (lo, hi) in ranges.items():
            number(key, lo, hi)

        if type(config["invert_exclude_images"]) is not bool:
            raise ValueError("invert_exclude_images must be true or false.")
        if type(config["invert_images_only"]) is not bool:
            raise ValueError("invert_images_only must be true or false.")
        if config["invert_exclude_images"] and config["invert_images_only"]:
            raise ValueError("Only one image-aware inversion mode can be enabled at a time.")

        return _normalize_filter_config(config)

    def _export_custom_adjustments(self):
        """Export the editor's current Custom configuration as JSON."""
        default_name = "mergerz-custom-filter.json"
        path, _ = QtWidgets.QFileDialog.getSaveFileName(
            self,
            "Export Custom Filter",
            default_name,
            "JSON files (*.json);;All files (*)",
        )
        if not path:
            return
        if not path.lower().endswith(".json"):
            path += ".json"

        payload = {
            "format": "Mergerz Custom Filter",
            "version": 1,
            "adjustments": _normalize_filter_config(self._custom_config),
        }
        try:
            with open(path, "w", encoding="utf-8") as handle:
                json.dump(payload, handle, indent=2, ensure_ascii=False)
                handle.write("\n")
        except Exception as exc:
            QtWidgets.QMessageBox.critical(
                self, "Export Failed", f"Could not export the filter settings.\n\n{exc}")
            return

        QtWidgets.QMessageBox.information(
            self, "Filter Exported", f"Custom filter adjustments exported to:\n{path}")

    def _import_custom_adjustments(self):
        """Import and apply a validated Custom filter configuration to the editor only."""
        path, _ = QtWidgets.QFileDialog.getOpenFileName(
            self,
            "Import Custom Filter",
            "",
            "JSON files (*.json);;All files (*)",
        )
        if not path:
            return

        try:
            with open(path, "r", encoding="utf-8") as handle:
                payload = json.load(handle)
            config = self._validate_imported_adjustments(payload)
        except json.JSONDecodeError as exc:
            QtWidgets.QMessageBox.critical(
                self,
                "Import Failed",
                f"The selected file is not valid JSON.\n\nLine {exc.lineno}, column {exc.colno}: {exc.msg}",
            )
            return
        except (OSError, ValueError, TypeError) as exc:
            QtWidgets.QMessageBox.critical(
                self, "Import Failed", f"Could not import the filter settings.\n\n{exc}")
            return
        except Exception as exc:
            QtWidgets.QMessageBox.critical(
                self, "Import Failed", f"Could not import the filter settings.\n\n{exc}")
            return

        self._mode = "Custom"
        self._custom_config = config
        self.filter_buttons["Custom"].setChecked(True)
        self._set_config_to_controls(config)
        self._set_adjustments_enabled(True)
        self._refresh_preview(config)
        self._update_reset_enabled()
        self._update_apply_enabled()

    def _shutdown_preview_thread(self):
        """Stop all preview workers before dialog teardown."""
        if self._filter_preview_shutdown:
            return
        self._filter_preview_shutdown = True
        try:
            timer = getattr(self, "_preview_timer", None)
            if timer is not None:
                timer.stop()
            idle_timer = getattr(self, "_actual_preview_idle_timer", None)
            if idle_timer is not None:
                idle_timer.stop()
            reaper = getattr(self, "_actual_preview_reaper_timer", None)
            if reaper is not None:
                reaper.stop()
            self._pending_preview_config = None
        except Exception:
            pass
        try:
            self._cancel_actual_filter_preview()
            self._drain_retired_actual_preview_processes(timeout=0.8)
        except Exception:
            pass
        try:
            viewer = getattr(self, "viewer", None)
            if viewer is not None:
                viewer.clear_actual_preview(restore_source=False)
                viewer.shutdown_filter_preview_thread()
                if hasattr(viewer, "_drain_retired_actual_preview_processes"):
                    viewer._drain_retired_actual_preview_processes(timeout=0.8)
        except Exception:
            pass

    def done(self, result):
        self._shutdown_preview_thread()
        super().done(result)

    def closeEvent(self, event):
        self._shutdown_preview_thread()
        event.accept()

    def _set_initial_common_filter_state(self):
        """Prime the dialog from the exact common filter state of the selection."""
        common = _normalize_filter_config(self._custom_config)
        mode = "Custom"
        for name in ("Invert", "Inv. (no images)", "Inv. (images only)", "Grayscale"):
            if _filter_configs_equal(common, _preset_filter_config(name)):
                mode = name
                break
        self._mode = mode
        self.filter_buttons[mode].setChecked(True)
        self._set_config_to_controls(
            _preset_filter_config(mode) if mode != "Custom" else common)
        self._set_adjustments_enabled(mode == "Custom")

    @staticmethod
    def _common_or_neutral(configs):
        if configs and all(_filter_configs_equal(configs[0], c) for c in configs[1:]):
            return _normalize_filter_config(configs[0])
        return _neutral_filter_config()

    def _make_card(self, title):
        card = QtWidgets.QFrame()
        card.setStyleSheet(self._CARD)
        layout = QtWidgets.QVBoxLayout(card)
        layout.setContentsMargins(10, 9, 10, 9)
        layout.setSpacing(7)
        label = QtWidgets.QLabel(title)
        label.setStyleSheet(self._SECTION)
        layout.addWidget(label)
        self.adjust_layout.addWidget(card)
        return layout

    def _add_slider(self, layout, key, label, lo, hi, value, step=1, decimals=0):
        row = _FilterSliderRow(label, lo, hi, value, step=step, decimals=decimals)
        layout.addWidget(row)
        self.controls.append(row)
        row.valueChanged.connect(lambda _v, k=key: self._control_changed(k))
        setattr(self, f"_ctrl_{key}", row)
        return row

    def _build_layer_section(self):
        layout = self._make_card("Layer")
        color_row = QtWidgets.QHBoxLayout()
        color_lbl = QtWidgets.QLabel("Layer Color")
        color_lbl.setMinimumWidth(94)
        color_lbl.setStyleSheet(self._TEXT_LABEL + " color:#d8d8d8;")
        color_row.addWidget(color_lbl)
        self.layer_color_btn = QtWidgets.QPushButton()
        self.layer_color_btn.setFixedHeight(32)
        self.layer_color_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.layer_color_btn.setText("#ffffff")
        color_row.addWidget(self.layer_color_btn, 1)
        layout.addLayout(color_row)
        self.layer_color_btn.clicked.connect(self._choose_layer_color)
        self._add_combo(layout, "blend_mode", "Blend Mode", FILTER_BLEND_MODES)
        self._add_slider(layout, "opacity", "Opacity", 0, 100, 0)

    def _add_combo(self, layout, key, label, items):
        row = QtWidgets.QHBoxLayout()
        lab = QtWidgets.QLabel(label)
        lab.setMinimumWidth(94)
        lab.setStyleSheet(self._TEXT_LABEL + " color:#d8d8d8;")
        row.addWidget(lab)
        combo = QtWidgets.QComboBox()
        combo.addItems(items)
        row.addWidget(combo, 1)
        layout.addLayout(row)
        self.controls.extend([lab, combo])
        setattr(self, f"_ctrl_{key}", combo)
        combo.currentIndexChanged.connect(lambda _i, k=key: self._control_changed(k))
        return combo

    def _build_tone_section(self):
        layout = self._make_card("Tone")
        self._add_slider(layout, "brightness", "Brightness", -100, 100, 0)
        self._add_slider(layout, "contrast", "Contrast", -100, 100, 0)
        self._add_slider(layout, "black_point", "Black Point", 0, 100, 0)
        self._add_slider(layout, "white_point", "White Point", 0, 100, 100)

    def _build_color_section(self):
        layout = self._make_card("Color")
        self._add_slider(layout, "saturation", "Saturation", 0, 100, 100)
        self._add_slider(layout, "warmth", "Warmth", -100, 100, 0)
        self._add_slider(layout, "tint", "Tint", -100, 100, 0)

    def _build_special_section(self):
        layout = self._make_card("Special")
        self._add_slider(layout, "grayscale", "Grayscale", 0, 100, 0)
        self._add_slider(layout, "invert", "Invert", 0, 100, 0)
        self._add_slider(layout, "threshold", "Threshold", 0, 100, 0)

    def _build_advanced_gamma_section(self):
        """Place Gamma behind a collapsed Advanced disclosure with a preview warning."""
        advanced = QtWidgets.QWidget()
        advanced_layout = QtWidgets.QVBoxLayout(advanced)
        advanced_layout.setContentsMargins(8, 0, 0, 0)
        advanced_layout.setSpacing(5)
        self._add_slider(
            advanced_layout, "gamma", "Gamma", 0.2, 5.0, 1.0,
            step=0.01, decimals=2)

        note = QtWidgets.QLabel("May make the live preview inaccurate.")
        note.setWordWrap(True)
        note.setStyleSheet("color:#858585; font-size:9pt; padding-left:2px;")
        advanced_layout.addWidget(note)

        row = QtWidgets.QHBoxLayout()
        # Match the left inset of the Gamma control inside the expanded section.
        row.setContentsMargins(8, 0, 0, 0)
        row.setSpacing(6)
        label = QtWidgets.QLabel("Advanced")
        label.setStyleSheet(
            "color:#d8d8d8; background:transparent; border:none; "
            "padding:0; font-weight:600;")
        row.addWidget(label, 0, QtCore.Qt.AlignmentFlag.AlignVCenter)

        arrow = QtWidgets.QToolButton()
        arrow.setCheckable(True)
        arrow.setChecked(False)
        arrow.setArrowType(QtCore.Qt.ArrowType.DownArrow)
        arrow.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        arrow.setFixedSize(22, 22)
        arrow.setStyleSheet("""
            QToolButton {
                color:#d8d8d8; background:transparent; border:none;
                padding:0; margin:0;
            }
            QToolButton:hover { color:#ffffff; background:#2b2b2b; border-radius:4px; }
        """)
        row.addWidget(arrow, 0, QtCore.Qt.AlignmentFlag.AlignVCenter)
        row.addStretch(1)
        self.adjust_layout.addLayout(row)
        self.adjust_layout.addWidget(advanced)
        advanced.setVisible(False)

        def update(checked):
            arrow.setArrowType(QtCore.Qt.ArrowType.UpArrow if checked else QtCore.Qt.ArrowType.DownArrow)
            advanced.setVisible(bool(checked))
            if checked:
                # Let Qt recalculate the scroll area's range after revealing Gamma,
                # then move to the bottom so the entire advanced section is visible.
                QtCore.QTimer.singleShot(
                    0,
                    lambda: self.adjust_scroll.verticalScrollBar().setValue(
                        self.adjust_scroll.verticalScrollBar().maximum()))

        arrow.toggled.connect(update)

    def _choose_layer_color(self):
        cfg = self._controls_to_config()
        initial = QtGui.QColor(cfg["layer_color"])
        color = QtWidgets.QColorDialog.getColor(initial, self, "Choose Layer Color",
                                                 options=QtWidgets.QColorDialog.ColorDialogOption.DontUseNativeDialog)
        if not color.isValid():
            return
        self.layer_color_btn.setText(color.name().lower())
        self.layer_color_btn.setStyleSheet(
            f"QPushButton {{ background:{color.name()}; border:none; border-radius:5px; color:{('#111111' if color.lightness() > 150 else '#ffffff')}; font-weight:bold; }} "
            "QPushButton:hover { border:none; }")
        self.layer_color_btn.setProperty("filter_color", color.name().lower())
        self._custom_config["layer_color"] = color.name().lower()
        self._custom_config = _normalize_filter_config(self._custom_config)
        self._refresh_preview()
        self._update_reset_enabled()
        self._update_apply_enabled()

    def _control_changed(self, key):
        if self._updating:
            return
        self._custom_config = self._controls_to_config()
        self._refresh_preview()
        self._update_reset_enabled()
        self._update_apply_enabled()

    def _controls_to_config(self):
        cfg = _normalize_filter_config(self._custom_config)
        cfg["layer_color"] = self.layer_color_btn.property("filter_color") or cfg["layer_color"]
        if isinstance(self.layer_color_btn.property("filter_color"), str):
            cfg["layer_color"] = self.layer_color_btn.property("filter_color")
        for key in ("opacity", "brightness", "contrast", "gamma", "black_point",
                    "white_point", "saturation", "warmth", "tint", "grayscale",
                    "invert", "threshold"):
            ctrl = getattr(self, f"_ctrl_{key}")
            if isinstance(ctrl, _FilterSliderRow):
                cfg[key] = ctrl.value()
        combo = getattr(self, "_ctrl_blend_mode")
        cfg["blend_mode"] = combo.currentText()
        return _normalize_filter_config(cfg)

    def _set_config_to_controls(self, config):
        cfg = _normalize_filter_config(config)
        self._updating = True
        try:
            self.layer_color_btn.setProperty("filter_color", cfg["layer_color"])
            qcolor = QtGui.QColor(cfg['layer_color'])
            self.layer_color_btn.setText(cfg['layer_color'])
            self.layer_color_btn.setStyleSheet(
                f"QPushButton {{ background:{cfg['layer_color']}; border:none; border-radius:5px; color:{('#111111' if qcolor.lightness() > 150 else '#ffffff')}; font-weight:bold; }} "
                "QPushButton:hover { border:none; }")
            combo = getattr(self, "_ctrl_blend_mode")
            ix = combo.findText(cfg["blend_mode"])
            combo.setCurrentIndex(max(0, ix))
            for key in ("opacity", "brightness", "contrast", "gamma", "black_point",
                        "white_point", "saturation", "warmth", "tint", "grayscale",
                        "invert", "threshold"):
                getattr(self, f"_ctrl_{key}").setValue(cfg[key])
        finally:
            self._updating = False

    def _set_adjustments_enabled(self, enabled):
        # Whole control surface is muted for fixed presets but still displays values.
        self.adjust_scroll.setProperty("adjustments_enabled", bool(enabled))
        for ctrl in self.controls:
            ctrl.setEnabled(bool(enabled))
        self.layer_color_btn.setEnabled(bool(enabled))

    def _filter_button_clicked(self, button):
        name = button.text()
        if name == "Custom":
            self._mode = "Custom"
            self._set_config_to_controls(self._custom_config)
            self._set_adjustments_enabled(True)
            self._refresh_preview()
        else:
            self._mode = name
            cfg = _preset_filter_config(name)
            self._set_config_to_controls(cfg)
            self._set_adjustments_enabled(False)
            self._refresh_preview(cfg)
        self._update_reset_enabled()
        self._update_apply_enabled()

    def _refresh_preview(self, override=None):
        cfg = _normalize_filter_config(
            override if override is not None else
            (self._custom_config if self._mode == "Custom"
             else _preset_filter_config(self._mode)))

        # Any filter interaction is a hard boundary for exact preview. Cancellation is intentionally
        # nonblocking so buttons and sliders remain responsive even while pikepdf is finishing a job.
        self._cancel_actual_filter_preview()
        try:
            # Keep the latest completed pixel preview visible while the new pixel frame is rendered.
            # Restoring the clean source here was the direct cause of the original/filter flicker.
            self.viewer.clear_actual_preview(restore_source=False)
        except Exception:
            pass

        self._pending_preview_config = cfg
        # Push the current config directly to the pixel preview. The worker itself is latest-request-wins,
        # so repeated slider events remain cheap and stale frames are discarded by generation checks.
        try:
            self.viewer.set_filter_preview(cfg)
        except Exception:
            pass
        self._pending_preview_config = None
        self._actual_preview_idle_timer.start()

    def _render_preview_now(self):
        cfg = self._pending_preview_config
        self._pending_preview_config = None
        if cfg is not None:
            self.viewer.set_filter_preview(cfg)

    def _on_viewer_page_changed(self, _index):
        self._cancel_actual_filter_preview()
        try:
            self.viewer.clear_actual_preview(restore_source=False)
        except Exception:
            pass
        cfg = self._active_config()
        try:
            self.viewer.set_filter_preview(cfg)
        except Exception:
            pass
        self._actual_preview_idle_timer.start()

    def _set_actual_preview_status(self, visible):
        viewer = getattr(self, "viewer", None)
        if viewer is None:
            return
        if visible:
            _show_view_status_toast(viewer, "Rendering actual filter results...")
        else:
            _hide_view_status_toast(viewer)

    def _start_actual_filter_preview(self):
        self._actual_preview_idle_timer.stop()
        self._cancel_actual_filter_preview()

        try:
            current_index = int(self.viewer.current_nav_index())
        except Exception:
            current_index = 0
        if current_index < 0 or current_index >= len(self.selected_entries):
            return

        cfg = self._active_config()
        if not _filter_config_active(cfg):
            self._set_actual_preview_status(False)
            return

        entry = copy.deepcopy(self.selected_entries[current_index])
        self._actual_preview_generation += 1
        generation = self._actual_preview_generation
        output_path = os.path.abspath(os.path.join(
            TEMP_FOLDER, f"apply_filters_exact_preview_{uuid.uuid4().hex}.pdf"))
        recv_conn = None
        send_conn = None
        try:
            os.makedirs(TEMP_FOLDER, exist_ok=True)
            ctx = multiprocessing.get_context("spawn")
            recv_conn, send_conn = ctx.Pipe(duplex=False)
            proc = ctx.Process(
                target=_actual_filter_preview_process_worker,
                args=([entry], cfg, output_path, send_conn),
            )
            proc.daemon = True
            proc.start()
            try:
                send_conn.close()
            except Exception:
                pass
        except Exception:
            try:
                if recv_conn is not None:
                    recv_conn.close()
            except Exception:
                pass
            try:
                if os.path.exists(output_path):
                    os.remove(output_path)
            except Exception:
                pass
            self._set_actual_preview_status(False)
            return

        self._actual_preview_process = proc
        self._actual_preview_conn = recv_conn
        self._actual_preview_candidate = output_path
        self._actual_preview_job_nav_index = current_index
        self._actual_preview_job_generation = generation
        self._set_actual_preview_status(True)
        self._actual_preview_poll_timer.start()

    def _poll_actual_filter_preview(self):
        proc = self._actual_preview_process
        conn = self._actual_preview_conn
        if proc is None:
            self._actual_preview_poll_timer.stop()
            return

        result = None
        try:
            if conn is not None and conn.poll():
                result = conn.recv()
        except (EOFError, OSError):
            result = None

        if result is not None:
            kind = result[0] if len(result) > 0 else "error"
            output_path = result[1] if len(result) > 1 else ""
            current_generation = int(getattr(self, "_actual_preview_job_generation", -1))
            expected_generation = int(self._actual_preview_generation)
            job_nav = int(getattr(self, "_actual_preview_job_nav_index", -1))
            try:
                current_nav = int(self.viewer.current_nav_index())
            except Exception:
                current_nav = -1
            candidate = self._actual_preview_candidate

            self._detach_actual_preview_process()
            self._actual_preview_poll_timer.stop()

            if (kind == "ok"
                    and current_generation == expected_generation
                    and job_nav == current_nav
                    and output_path
                    and os.path.isfile(output_path)):
                try:
                    self.viewer.set_actual_preview_pdf(output_path, nav_page_map={current_nav: 0})
                except Exception:
                    self._cleanup_actual_filter_preview_path(output_path)
                    self._set_actual_preview_status(False)
                    return
                self._actual_preview_candidate = None
                self._set_actual_preview_status(False)
                return

            self._queue_retired_preview_process(proc, output_path or candidate)
            self._actual_preview_candidate = None
            self._set_actual_preview_status(False)
            return

        try:
            alive = proc.is_alive()
        except Exception:
            alive = False
        if not alive:
            candidate = self._actual_preview_candidate
            try:
                proc.join(timeout=0)
            except Exception:
                pass
            try:
                if hasattr(proc, "close"):
                    proc.close()
            except Exception:
                pass
            self._actual_preview_process = None
            self._actual_preview_conn = None
            self._actual_preview_candidate = None
            self._actual_preview_poll_timer.stop()
            self._cleanup_actual_filter_preview_path(candidate)
            self._set_actual_preview_status(False)

    def _queue_retired_preview_process(self, proc, candidate):
        if proc is None:
            self._cleanup_actual_filter_preview_path(candidate)
            return
        self._actual_preview_retired_jobs.append({"process": proc, "candidate": candidate})
        if not self._actual_preview_reaper_timer.isActive():
            self._actual_preview_reaper_timer.start()

    def _detach_actual_preview_process(self):
        conn = self._actual_preview_conn
        proc = self._actual_preview_process
        self._actual_preview_conn = None
        self._actual_preview_process = None
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        if proc is not None:
            try:
                if proc.is_alive():
                    self._queue_retired_preview_process(proc, None)
                else:
                    proc.join(timeout=0)
                    if hasattr(proc, "close"):
                        proc.close()
            except Exception:
                try:
                    self._queue_retired_preview_process(proc, None)
                except Exception:
                    pass
        return proc

    def _reap_actual_preview_processes(self):
        if not self._actual_preview_retired_jobs:
            self._actual_preview_reaper_timer.stop()
            return
        survivors = []
        for job in self._actual_preview_retired_jobs:
            proc = job.get("process")
            candidate = job.get("candidate")
            try:
                alive = proc.is_alive()
            except Exception:
                alive = False
            if alive:
                survivors.append(job)
                continue
            try:
                proc.join(timeout=0)
            except Exception:
                pass
            try:
                if hasattr(proc, "close"):
                    proc.close()
            except Exception:
                pass
            self._cleanup_actual_filter_preview_path(candidate)
        self._actual_preview_retired_jobs = survivors
        if not survivors:
            self._actual_preview_reaper_timer.stop()

    def _close_actual_filter_preview_handles(self, join_timeout=0.5):
        # Compatibility helper retained for the existing workflow, but no longer blocks the
        # GUI on a long join. Active processes are detached and reaped asynchronously.
        proc = self._actual_preview_process
        conn = self._actual_preview_conn
        candidate = self._actual_preview_candidate
        self._actual_preview_process = None
        self._actual_preview_conn = None
        self._actual_preview_candidate = None
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        if proc is None:
            self._cleanup_actual_filter_preview_path(candidate)
            return
        try:
            if proc.is_alive():
                proc.terminate()
                self._queue_retired_preview_process(proc, candidate)
            else:
                proc.join(timeout=0)
                if hasattr(proc, "close"):
                    proc.close()
                self._cleanup_actual_filter_preview_path(candidate)
        except Exception:
            self._queue_retired_preview_process(proc, candidate)

    def _cleanup_actual_filter_preview_path(self, path):
        if not path:
            return
        try:
            path = os.path.abspath(str(path))
        except Exception:
            return
        for candidate in (path, path + ".base.pdf"):
            try:
                if os.path.isfile(candidate):
                    os.remove(candidate)
            except Exception:
                pass

    def _cancel_actual_filter_preview(self):
        self._actual_preview_generation += 1
        self._actual_preview_idle_timer.stop()
        self._actual_preview_poll_timer.stop()

        proc = self._actual_preview_process
        conn = self._actual_preview_conn
        candidate = self._actual_preview_candidate
        self._actual_preview_process = None
        self._actual_preview_conn = None
        self._actual_preview_candidate = None
        self._actual_preview_job_nav_index = -1

        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass

        if proc is not None:
            try:
                if proc.is_alive():
                    proc.terminate()
                    self._queue_retired_preview_process(proc, candidate)
                else:
                    proc.join(timeout=0)
                    if hasattr(proc, "close"):
                        proc.close()
                    self._cleanup_actual_filter_preview_path(candidate)
            except Exception:
                self._queue_retired_preview_process(proc, candidate)
        else:
            self._cleanup_actual_filter_preview_path(candidate)

        self._set_actual_preview_status(False)

    def _drain_retired_actual_preview_processes(self, timeout=1.5):
        jobs = getattr(self, "_actual_preview_retired_jobs", [])
        if not jobs:
            return
        for job in jobs:
            proc = job.get("process")
            candidate = job.get("candidate")
            try:
                if proc.is_alive():
                    proc.join(timeout=max(0.0, float(timeout)))
            except Exception:
                pass
            try:
                if proc.is_alive():
                    proc.terminate()
                    proc.join(timeout=0.5)
            except Exception:
                pass
            try:
                if hasattr(proc, "close"):
                    proc.close()
            except Exception:
                pass
            self._cleanup_actual_filter_preview_path(candidate)
        self._actual_preview_retired_jobs = []
        timer = getattr(self, "_actual_preview_reaper_timer", None)
        if timer is not None:
            timer.stop()

    def _active_config(self):
        if self._mode == "Custom":
            return _normalize_filter_config(self._custom_config)
        return _preset_filter_config(self._mode)

    def _reset_to_custom_defaults(self):
        # Reset only the pending filter-editor state; the main Edit PDF document is untouched
        # until Apply Filters is pressed.
        self._mode = "Custom"
        self._custom_config = _neutral_filter_config()
        self.filter_buttons["Custom"].setChecked(True)
        self._set_config_to_controls(self._custom_config)
        self._set_adjustments_enabled(True)
        self._refresh_preview()
        self._update_reset_enabled()
        self._update_apply_enabled()

    def _update_reset_enabled(self):
        if not hasattr(self, "reset_btn"):
            return
        default_cfg = _neutral_filter_config()
        enabled = (self._mode != "Custom" or
                   not _filter_configs_equal(self._custom_config, default_cfg))
        self.reset_btn.setEnabled(bool(enabled))

    def _update_apply_enabled(self):
        cfg = self._active_config()
        changed = any(not _filter_configs_equal(cfg, old) for old in self._initial_configs)
        self.apply_btn.setEnabled(bool(changed))

    def _apply(self):
        self._actual_preview_idle_timer.stop()
        self._cancel_actual_filter_preview()
        try:
            self.viewer.clear_actual_preview(restore_source=False)
        except Exception:
            pass
        cfg = self._active_config()
        self.page_edit._apply_filter_config_to_selection(cfg)
        self.accept()


class _CompactDecimalSpinBox(QtWidgets.QDoubleSpinBox):
    """Display only significant decimal digits without changing the stored value."""
    def textFromValue(self, value):
        try:
            # Match the control's 12-decimal precision, but omit insignificant zeros
            # and the decimal separator when the value is effectively an integer.
            text = f"{float(value):.12f}".rstrip("0").rstrip(".")
            return text if text not in {"", "-0"} else "0"
        except Exception:
            return super().textFromValue(value)


class StretchSelectedPagesDialog(QtWidgets.QDialog):
    """Preview and apply a vector-preserving stretch ratio to selected Edit PDF pages."""
    _CARD = ("QFrame { background:#161616; border:1px solid #2d2d2d; "
             "border-radius:8px; }")
    _SECTION = ("QLabel { color:#f0f0f0; font-size:10.5pt; font-weight:bold; "
                "background:transparent; border:none; padding:0; margin:0; }")

    def __init__(self, page_edit, selected_entries, selected_anchor=0, parent=None):
        super().__init__(parent or page_edit)
        self.page_edit = page_edit
        # Preserve each selected entry's real Edit PDF grid row so the viewer
        # header can show the true dummy-page position against the full grid.
        self._original_row_entries = []
        for row, entry in selected_entries:
            try:
                row = int(row)
            except (TypeError, ValueError):
                row = len(self._original_row_entries)
            self._original_row_entries.append((row, copy.deepcopy(entry)))
        self._original_entries = [copy.deepcopy(entry) for _, entry in self._original_row_entries]
        self._selected_uids = [entry.get("uid") for entry in self._original_entries]
        self._common_ratio = self._calculate_common_ratio_value(
            self._original_entries)
        # Prefer the most common visible ratio. Keep 16:9 only as the fallback
        # when the selection has no unique repeated ratio.
        self._initial_target_ratio = (
            self._common_ratio if self._common_ratio is not None else 16.0 / 9.0)
        self._initial_ratio_values = self._ratio_spin_values(
            self._initial_target_ratio)
        self._nav_items = []
        for row, entry in self._original_row_entries:
            preview_entry = copy.deepcopy(entry)
            preview_entry["grid_row"] = row
            preview_entry["stretch_ratio"] = self._initial_target_ratio
            self._nav_items.append(preview_entry)

        self._preview_generation = 0
        self._preview_process = None
        self._preview_conn = None
        self._preview_candidate = None
        self._preview_job_generation = -1
        self._preview_job_nav_index = -1
        self._retired_preview_jobs = []
        self._preview_idle_timer = QtCore.QTimer(self)
        self._preview_idle_timer.setSingleShot(True)
        self._preview_idle_timer.setInterval(850)
        self._preview_idle_timer.timeout.connect(self._start_exact_preview)
        self._preview_poll_timer = QtCore.QTimer(self)
        self._preview_poll_timer.setInterval(50)
        self._preview_poll_timer.timeout.connect(self._poll_exact_preview)
        self._preview_reaper_timer = QtCore.QTimer(self)
        self._preview_reaper_timer.setInterval(60)
        self._preview_reaper_timer.timeout.connect(self._reap_preview_jobs)

        self.setWindowTitle("Stretch Selected Pages")
        self.setModal(True)
        self.setMinimumSize(900, 610)
        screen = QtWidgets.QApplication.primaryScreen()
        if screen is not None:
            geom = screen.availableGeometry()
            self.resize(min(1120, max(900, geom.width() - 70)),
                        min(730, max(610, geom.height() - 90)))
        else:
            self.resize(1060, 690)

        root = QtWidgets.QVBoxLayout(self)
        root.setContentsMargins(18, 16, 18, 16)
        root.setSpacing(10)
        title = QtWidgets.QLabel("Stretch selected pages")
        title.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        title.setStyleSheet(
            "font-size:14pt; font-weight:bold; color:#f0f0f0; "
            "background:transparent; border:none; padding:0; margin:0;")
        root.addWidget(title)

        splitter = QtWidgets.QSplitter(QtCore.Qt.Orientation.Horizontal)
        splitter.setChildrenCollapsible(False)
        root.addWidget(splitter, 1)

        viewer_card = QtWidgets.QFrame()
        viewer_card.setStyleSheet(self._CARD)
        viewer_layout = QtWidgets.QVBoxLayout(viewer_card)
        viewer_layout.setContentsMargins(4, 4, 4, 4)
        viewer_layout.setSpacing(0)
        initial_index = max(0, min(int(selected_anchor), len(self._nav_items) - 1))
        initial = self._nav_items[initial_index]
        self.viewer = LightweightPageViewer(
            initial.get("source_pdf", ""), initial.get("original_idx", 0),
            rotation=initial.get("rotation", 0), crop=initial.get("crop"),
            flip_h=bool(initial.get("flip_h", False)),
            flip_v=bool(initial.get("flip_v", False)),
            parent=viewer_card, nav_items=self._nav_items,
            nav_index=initial_index, show_selected_label=True,
            total_dummy=self.page_edit.grid.count(), embedded=True)
        viewer_layout.addWidget(self.viewer, 1)
        self.viewer.pageChanged.connect(self._on_viewer_page_changed)
        splitter.addWidget(viewer_card)

        controls_card = QtWidgets.QFrame()
        controls_card.setStyleSheet(self._CARD)
        controls_layout = QtWidgets.QVBoxLayout(controls_card)
        controls_layout.setContentsMargins(14, 13, 14, 13)
        controls_layout.setSpacing(12)
        controls_title = QtWidgets.QLabel("Stretch ratio")
        controls_title.setStyleSheet(self._SECTION)
        controls_layout.addWidget(controls_title)

        target_label = QtWidgets.QLabel("Stretch to width:height")
        target_label.setStyleSheet(
            "color:#bdbdbd; background:transparent; border:none;")
        controls_layout.addWidget(target_label)

        ratio_row = QtWidgets.QHBoxLayout()
        ratio_row.setSpacing(8)
        self.width_spin = _CompactDecimalSpinBox()
        self.height_spin = _CompactDecimalSpinBox()
        for spin in (self.width_spin, self.height_spin):
            spin.setLocale(ENGLISH_LOCALE)
            spin.setRange(0.000001, 1000000.0)
            spin.setDecimals(12)
            spin.setKeyboardTracking(True)
            spin.setMinimumWidth(110)
            spin.setFixedHeight(36)
            spin.setStyleSheet("""
                QDoubleSpinBox {
                    background:#242424; color:#f0f0f0; border:1px solid #3a3a3a;
                    border-radius:6px; padding:4px 8px; selection-background-color:#0078d7;
                }
                QDoubleSpinBox:focus { border:1px solid #0078d7; }
            """)
        self.width_spin.setValue(self._initial_ratio_values[0])
        self.height_spin.setValue(self._initial_ratio_values[1])
        ratio_row.addWidget(self.width_spin, 1)
        colon = QtWidgets.QLabel(":")
        colon.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        colon.setStyleSheet("font-size:14pt; font-weight:bold; color:#f0f0f0;")
        ratio_row.addWidget(colon)
        ratio_row.addWidget(self.height_spin, 1)
        controls_layout.addLayout(ratio_row)

        common_label = QtWidgets.QLabel("Common ratio in selection")
        common_label.setStyleSheet(
            "color:#bdbdbd; background:transparent; border:none;")
        controls_layout.addWidget(common_label)
        self.common_ratio_value = QtWidgets.QLabel(
            _format_aspect_ratio(self._common_ratio)
            if self._common_ratio is not None else "None")
        self.common_ratio_value.setAlignment(QtCore.Qt.AlignmentFlag.AlignLeft | QtCore.Qt.AlignmentFlag.AlignVCenter)
        self.common_ratio_value.setStyleSheet(
            "font-size:13pt; font-weight:bold; color:#4a9eff; "
            "background:transparent; border:none;")
        controls_layout.addWidget(self.common_ratio_value)

        hint = QtWidgets.QLabel(
            "The selected pages are stretched non-proportionally. "
            "Text and vector artwork remain vector-based in the saved PDF.")
        hint.setWordWrap(True)
        hint.setStyleSheet(
            "color:#8b8b8b; font-size:9pt; background:transparent; border:none;")
        controls_layout.addWidget(hint)
        controls_layout.addStretch(1)
        splitter.addWidget(controls_card)
        splitter.setSizes([660, 340])

        bottom = QtWidgets.QHBoxLayout()
        bottom.setSpacing(8)
        bottom.addStretch(1)
        cancel_btn = QtWidgets.QPushButton("Cancel")
        cancel_btn.setFixedWidth(120)
        cancel_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        cancel_btn.setStyleSheet("""
            QPushButton { background:#2a2a2a; color:#f0f0f0; border:1px solid #3a3a3a;
                border-radius:6px; padding:8px 16px; font-weight:bold; }
            QPushButton:hover { background:#343434; }
        """)
        cancel_btn.clicked.connect(self.reject)
        bottom.addWidget(cancel_btn)
        self.apply_btn = QtWidgets.QPushButton("Stretch Pages")
        self.apply_btn.setFixedWidth(150)
        self.apply_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.apply_btn.setStyleSheet("""
            QPushButton { background:#0078d7; color:white; border:none; border-radius:6px;
                padding:8px 16px; font-weight:bold; }
            QPushButton:hover { background:#005fa3; }
            QPushButton:disabled { background:#2b2b2b; color:#696969; border:1px solid #3a3a3a; }
        """)
        self.apply_btn.clicked.connect(self._apply)
        bottom.addWidget(self.apply_btn)
        root.addLayout(bottom)

        self.width_spin.valueChanged.connect(self._ratio_edited)
        self.height_spin.valueChanged.connect(self._ratio_edited)
        self._update_apply_enabled()
        QtCore.QTimer.singleShot(0, self._refresh_preview)

    @staticmethod
    def _calculate_common_ratio_value(entries):
        """Return the unique most-common visible aspect ratio, or None."""
        docs = {}
        ratios = []
        try:
            for entry in entries:
                ratio = _entry_visible_aspect_ratio(entry, docs)
                if ratio is not None and math.isfinite(ratio) and ratio > 0:
                    ratios.append(float(ratio))
        finally:
            for doc in docs.values():
                try:
                    doc.close()
                except Exception:
                    pass
        if not ratios:
            return None
        if len(ratios) == 1:
            return ratios[0]

        groups = []
        for ratio in ratios:
            for group in groups:
                if math.isclose(ratio, group["ratio"], rel_tol=1e-9, abs_tol=1e-12):
                    group["values"].append(ratio)
                    break
            else:
                groups.append({"ratio": ratio, "values": [ratio]})
        highest = max(len(group["values"]) for group in groups)
        winners = [group for group in groups if len(group["values"]) == highest]
        if highest < 2 or len(winners) != 1:
            return None
        return sum(winners[0]["values"]) / len(winners[0]["values"])

    @staticmethod
    def _calculate_common_ratio(entries):
        """Compatibility formatter for the selection's unique common ratio."""
        ratio = StretchSelectedPagesDialog._calculate_common_ratio_value(entries)
        return _format_aspect_ratio(ratio) if ratio is not None else "None"

    @staticmethod
    def _ratio_spin_values(ratio):
        """Represent a ratio cleanly in the bounded width/height spin boxes."""
        ratio = float(ratio)
        fraction = Fraction(ratio).limit_denominator(1_000_000)
        candidate = fraction.numerator / fraction.denominator
        if (math.isclose(candidate, ratio, rel_tol=1e-12, abs_tol=1e-14)
                and 1e-6 <= fraction.numerator <= 1e6
                and 1e-6 <= fraction.denominator <= 1e6):
            return float(fraction.numerator), float(fraction.denominator)

        # Preserve the actual ratio if it cannot be represented by a compact
        # integer fraction, scaling both values only as needed for the UI range.
        if ratio >= 1.0:
            width = min(ratio, 1_000_000.0)
            height = width / ratio
        else:
            height = min(1.0 / ratio, 1_000_000.0)
            width = height * ratio
        if not (1e-6 <= width <= 1e6 and 1e-6 <= height <= 1e6):
            return 16.0, 9.0
        return width, height

    def _target_ratio(self):
        width = float(self.width_spin.value())
        height = float(self.height_spin.value())
        ratio = width / height
        if not math.isfinite(ratio) or ratio <= 0:
            raise ValueError("Enter a finite, positive width and height ratio.")
        return ratio

    def _update_apply_enabled(self):
        try:
            ratio = self._target_ratio()
        except Exception:
            self.apply_btn.setEnabled(False)
            return
        changed = False
        for entry in self._original_entries:
            old = entry.get("stretch_ratio")
            try:
                if old is None or not math.isclose(
                        float(old), ratio, rel_tol=1e-12, abs_tol=1e-14):
                    changed = True
                    break
            except (TypeError, ValueError, OverflowError):
                changed = True
                break
        self.apply_btn.setEnabled(changed)

    def _ratio_edited(self, *_args):
        self._update_apply_enabled()
        self._refresh_preview()

    def _set_preview_status(self, visible, text="Rendering actual filter results..."):
        try:
            if visible:
                _show_view_status_toast(self.viewer, text)
            else:
                _hide_view_status_toast(self.viewer)
        except Exception:
            pass

    @staticmethod
    def _cleanup_preview_path(path):
        if not path:
            return
        for candidate in (path, path + ".base.pdf"):
            try:
                if os.path.isfile(candidate):
                    os.remove(candidate)
            except Exception:
                pass

    def _cancel_exact_preview(self):
        self._preview_generation += 1
        self._preview_idle_timer.stop()
        self._preview_poll_timer.stop()
        proc = self._preview_process
        conn = self._preview_conn
        candidate = self._preview_candidate
        self._preview_process = None
        self._preview_conn = None
        self._preview_candidate = None
        self._preview_job_nav_index = -1
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        if proc is not None:
            try:
                if proc.is_alive():
                    proc.terminate()
                    self._retired_preview_jobs.append((proc, candidate))
                    if not self._preview_reaper_timer.isActive():
                        self._preview_reaper_timer.start()
                else:
                    proc.join(timeout=0)
                    if hasattr(proc, "close"):
                        proc.close()
                    self._cleanup_preview_path(candidate)
            except Exception:
                self._retired_preview_jobs.append((proc, candidate))
                if not self._preview_reaper_timer.isActive():
                    self._preview_reaper_timer.start()
        else:
            self._cleanup_preview_path(candidate)
        self._set_preview_status(False)

    def _reap_preview_jobs(self):
        survivors = []
        for proc, candidate in self._retired_preview_jobs:
            try:
                alive = proc.is_alive()
            except Exception:
                alive = False
            if alive:
                survivors.append((proc, candidate))
                continue
            try:
                proc.join(timeout=0)
            except Exception:
                pass
            try:
                if hasattr(proc, "close"):
                    proc.close()
            except Exception:
                pass
            self._cleanup_preview_path(candidate)
        self._retired_preview_jobs = survivors
        if not survivors:
            self._preview_reaper_timer.stop()

    def _refresh_preview(self):
        try:
            ratio = self._target_ratio()
        except Exception:
            return
        self._cancel_exact_preview()
        try:
            self.viewer.clear_actual_preview(restore_source=False)
        except Exception:
            pass
        for nav_item in self.viewer._nav_items:
            nav_item["stretch_ratio"] = ratio
        # Stretch-only previews use the ratio-aware pixel frame directly. Keep the
        # delayed PDF render only when the current page has an active filter, because
        # the fast PIL filter preview is an approximation and filters retain their
        # established exact-after-inactivity behavior.
        self.viewer._render()
        try:
            current = self.viewer._nav_items[self.viewer.current_nav_index()]
            has_active_filter = _filter_config_active(_entry_filter_config(current))
        except Exception:
            has_active_filter = False
        if has_active_filter:
            self._preview_idle_timer.start()

    def _on_viewer_page_changed(self, _index):
        self._refresh_preview()

    def _start_exact_preview(self):
        self._preview_idle_timer.stop()
        self._cancel_exact_preview()
        try:
            nav_index = int(self.viewer.current_nav_index())
            ratio = self._target_ratio()
        except Exception:
            return
        if nav_index < 0 or nav_index >= len(self.viewer._nav_items):
            return
        entry = copy.deepcopy(self.viewer._nav_items[nav_index])
        entry["stretch_ratio"] = ratio
        cfg = _entry_filter_config(entry)
        if not _filter_config_active(cfg):
            return
        output_path = os.path.abspath(os.path.join(
            TEMP_FOLDER, f"stretch_selected_exact_preview_{uuid.uuid4().hex}.pdf"))
        recv_conn = send_conn = None
        try:
            os.makedirs(TEMP_FOLDER, exist_ok=True)
            ctx = multiprocessing.get_context("spawn")
            recv_conn, send_conn = ctx.Pipe(duplex=False)
            proc = ctx.Process(
                target=_actual_filter_preview_process_worker,
                args=([entry], cfg, output_path, send_conn))
            proc.daemon = True
            proc.start()
            try:
                send_conn.close()
            except Exception:
                pass
        except Exception:
            try:
                if recv_conn is not None:
                    recv_conn.close()
            except Exception:
                pass
            self._cleanup_preview_path(output_path)
            self._set_preview_status(False, "Could not start actual stretch preview.")
            return
        self._preview_process = proc
        self._preview_conn = recv_conn
        self._preview_candidate = output_path
        self._preview_job_generation = self._preview_generation
        self._preview_job_nav_index = nav_index
        self._set_preview_status(True)
        self._preview_poll_timer.start()

    def _poll_exact_preview(self):
        proc = self._preview_process
        conn = self._preview_conn
        if proc is None:
            self._preview_poll_timer.stop()
            return
        result = None
        try:
            if conn is not None and conn.poll():
                result = conn.recv()
        except (EOFError, OSError):
            result = None
        if result is not None:
            kind = result[0] if result else "error"
            output_path = result[1] if len(result) > 1 else ""
            generation = int(getattr(self, "_preview_job_generation", -1))
            nav_index = int(getattr(self, "_preview_job_nav_index", -1))
            try:
                current_nav = int(self.viewer.current_nav_index())
            except Exception:
                current_nav = -1
            candidate = self._preview_candidate
            self._preview_process = None
            self._preview_conn = None
            self._preview_candidate = None
            self._preview_poll_timer.stop()
            if conn is not None:
                try:
                    conn.close()
                except Exception:
                    pass
            try:
                proc.join(timeout=0)
                if hasattr(proc, "close"):
                    proc.close()
            except Exception:
                pass
            if (kind == "ok" and generation == self._preview_generation
                    and nav_index == current_nav and output_path
                    and os.path.isfile(output_path)):
                try:
                    self.viewer.set_actual_preview_pdf(
                        output_path, nav_page_map={current_nav: 0})
                    self._set_preview_status(False)
                    return
                except Exception:
                    self._cleanup_preview_path(output_path)
            self._cleanup_preview_path(output_path or candidate)
            self._set_preview_status(
                False,
                "Actual stretch preview failed." if kind != "ok" else
                "Actual stretch preview was superseded.")
            return
        try:
            alive = proc.is_alive()
        except Exception:
            alive = False
        if not alive:
            candidate = self._preview_candidate
            self._preview_process = None
            self._preview_conn = None
            self._preview_candidate = None
            self._preview_poll_timer.stop()
            try:
                proc.join(timeout=0)
                if hasattr(proc, "close"):
                    proc.close()
            except Exception:
                pass
            self._cleanup_preview_path(candidate)
            self._set_preview_status(False, "Actual stretch preview failed.")

    def _apply(self):
        try:
            ratio = self._target_ratio()
        except Exception as exc:
            QtWidgets.QMessageBox.warning(self, "Invalid Stretch Ratio", str(exc))
            return
        self._preview_idle_timer.stop()
        self._cancel_exact_preview()
        try:
            self.viewer.clear_actual_preview(restore_source=False)
        except Exception:
            pass
        self.page_edit._apply_stretch_ratio_to_selection(self._selected_uids, ratio)
        self.accept()

    def done(self, result):
        try:
            self._preview_idle_timer.stop()
            self._cancel_exact_preview()
            try:
                self.viewer.clear_actual_preview(restore_source=False)
                self.viewer.shutdown_filter_preview_thread()
            except Exception:
                pass
            for proc, candidate in self._retired_preview_jobs:
                try:
                    if proc.is_alive():
                        proc.terminate()
                        proc.join(timeout=0.5)
                    else:
                        proc.join(timeout=0)
                except Exception:
                    pass
                try:
                    if hasattr(proc, "close"):
                        proc.close()
                except Exception:
                    pass
                self._cleanup_preview_path(candidate)
            self._retired_preview_jobs = []
            self._preview_reaper_timer.stop()
        except Exception:
            pass
        super().done(result)


# ============================================================
# N-UP / MERGE SELECTED PAGES
# ============================================================


def _nup_cleanup_output_files(path):
    """Remove an N-up output and its private intermediate/preview files."""
    if not path:
        return
    path = os.path.abspath(str(path))
    for candidate in (
            path, path + ".prepared.pdf",
            path + ".prepared.pdf.filtered.pdf", path + ".png",
            path + ".partial.pdf"):
        try:
            if os.path.isfile(candidate):
                os.remove(candidate)
        except OSError:
            pass
    # A forced cancellation can bypass the stretch worker's finally block.
    # Its uniquely named candidates share this output's private prefix.
    try:
        folder = os.path.dirname(path) or "."
        prefix = os.path.basename(path) + ".prepared.pdf.stretch_"
        for name in os.listdir(folder):
            if name.startswith(prefix) and name.endswith(".pdf"):
                try:
                    os.remove(os.path.join(folder, name))
                except OSError:
                    pass
    except OSError:
        pass

