_NUP_BORDER_THICKNESS_PT = 1.0
_NUP_DEFAULT_PAGE_COLOR = "#ffffff"
_NUP_DEFAULT_BORDER_COLOR = "#000000"


def _nup_normalize_hex_color(value, default):
    """Normalize an opaque RGB color to #rrggbb for stable saved settings."""
    color = str(default if value is None else value).strip()
    if len(color) == 4 and color.startswith("#"):
        color = "#" + "".join(char * 2 for char in color[1:])
    if (len(color) != 7 or not color.startswith("#")
            or any(char not in "0123456789abcdefABCDEF" for char in color[1:])):
        raise ValueError("Choose a valid 6-digit RGB color.")
    return color.lower()


def _nup_color_rgb(value, default=_NUP_DEFAULT_PAGE_COLOR):
    """Convert #rrggbb to normalized RGB floats for PyMuPDF."""
    color = _nup_normalize_hex_color(value, default)
    return tuple(int(color[index:index + 2], 16) / 255.0
                 for index in (1, 3, 5))


def _nup_color_rgb8(value, default=_NUP_DEFAULT_PAGE_COLOR):
    """Convert #rrggbb to an 8-bit RGB tuple for Pillow previews."""
    color = _nup_normalize_hex_color(value, default)
    return tuple(int(color[index:index + 2], 16)
                 for index in (1, 3, 5))


# QSpinBox uses a signed 32-bit integer; practical dimensions are capped by
# the number of selected pages in the dialog, not by an arbitrary 12x12 limit.
_NUP_MAX_GRID_DIMENSION = 2_147_483_647


def _nup_entry_visible_size(entry, document_cache=None):
    """Return the exact current visible page dimensions in PDF points."""
    if _page_design_has_any(entry) and _page_design_anchor_state(entry) is not None:
        ordered = _page_design_ordered_document(entry, apply_filters=True)
        try:
            rect = ordered[0].rect
            width, height = float(rect.width), float(rect.height)
        finally:
            ordered.close()
        if width <= 0 or height <= 0:
            raise ValueError("A selected page has invalid visible dimensions.")
        return width, height

    source_pdf = os.path.abspath(str(entry.get("source_pdf") or ""))
    if not source_pdf or not os.path.isfile(source_pdf):
        raise FileNotFoundError(f"A selected page source is missing:\n{source_pdf}")
    page_index = int(entry.get("original_idx", 0))
    docs = document_cache if document_cache is not None else {}
    own_docs = document_cache is None
    scratch = None
    try:
        if source_pdf not in docs:
            docs[source_pdf] = fitz.open(source_pdf)
        doc = docs[source_pdf]
        if page_index < 0 or page_index >= doc.page_count:
            raise IndexError(f"Selected page {page_index + 1} is outside its source PDF.")
        source_page = doc.load_page(page_index)
        source_rotation = int(source_page.rotation) % 360
        scratch = fitz.open()
        scratch.insert_pdf(doc, from_page=page_index, to_page=page_index)
        page = scratch[0]
        apply_entry_to_page(page, entry, src_rot=source_rotation)
        visible = fitz.Rect(page.rect)
        width, height = float(visible.width), float(visible.height)
        stretch_ratio = entry.get("stretch_ratio")
        if stretch_ratio is not None:
            width, height = calculate_stretch_dimensions(width, height, float(stretch_ratio))
    finally:
        if scratch is not None:
            try:
                scratch.close()
            except Exception:
                pass
        if own_docs:
            for doc in docs.values():
                try:
                    doc.close()
                except Exception:
                    pass
    if not math.isfinite(width) or not math.isfinite(height) or width <= 0 or height <= 0:
        raise ValueError("A selected page has invalid visible dimensions.")
    return float(width), float(height)

_NUP_LAYOUT_MODES = {
    "consistent_both",
    "consistent_height",
    "consistent_width",
    "auto_width",
    "auto_height",
    "uniform_scale",
}


def _nup_layout_mode_from_config(config):
    """Return the canonical layout mode, migrating previous N-up settings."""
    mode = str(config.get("layout_mode") or "").strip().lower()
    if mode in _NUP_LAYOUT_MODES:
        return mode

    # Migrate settings saved by the earlier two-choice Page area UI. The most
    # recent Fit width implementation used equal-width columns, so retain that
    # behavior as Same page width. Fit height retains its content-weighted rows.
    legacy_area = str(config.get("page_area") or "consistent").strip().lower()
    if legacy_area == "consistent":
        return "consistent_both"
    if legacy_area == "auto":
        return ("consistent_width"
                if str(config.get("auto_fit") or "width").lower() == "width"
                else "auto_height")
    if legacy_area in _NUP_LAYOUT_MODES:
        return legacy_area
    return "consistent_both"


def _nup_validate_config(config):
    """Validate normalized N-up geometry options and return a defensive copy."""
    if not isinstance(config, dict):
        raise ValueError("N-up settings are invalid.")
    cfg = copy.deepcopy(config)
    try:
        width = float(cfg.get("page_width_pt"))
        height = float(cfg.get("page_height_pt"))
        columns = int(cfg.get("columns"))
        rows = int(cfg.get("rows"))
        margins = cfg.get("margins") or {}
        top = float(margins.get("top"))
        bottom = float(margins.get("bottom"))
        left = float(margins.get("left"))
        right = float(margins.get("right"))
        horizontal_gap = float(cfg.get("horizontal_gap_pt"))
        vertical_gap = float(cfg.get("vertical_gap_pt"))
        border_thickness = float(cfg.get(
            "border_thickness_pt", _NUP_BORDER_THICKNESS_PT))
    except (TypeError, ValueError, OverflowError, AttributeError) as exc:
        raise ValueError("Enter valid numeric values for the page, grid, margins and gaps.") from exc

    numeric_values = (width, height, top, bottom, left, right,
                      horizontal_gap, vertical_gap, border_thickness)
    if not all(math.isfinite(value) for value in numeric_values):
        raise ValueError("All page dimensions, margins and gaps must be finite numbers.")
    if width < 1.0 or height < 1.0 or width > 100000.0 or height > 100000.0:
        raise ValueError("Page width and height must be between 1 and 100,000 pt.")
    if type(cfg.get("columns")) is not int or type(cfg.get("rows")) is not int:
        raise ValueError("Grid columns and rows must be whole numbers.")
    if not (1 <= columns <= _NUP_MAX_GRID_DIMENSION
            and 1 <= rows <= _NUP_MAX_GRID_DIMENSION):
        raise ValueError("Grid columns and rows must be positive whole numbers within the supported range.")
    for value, label in ((top, "Top"), (bottom, "Bottom"),
                         (left, "Left"), (right, "Right"),
                         (horizontal_gap, "Horizontal gap"),
                         (vertical_gap, "Vertical gap")):
        if value < 0.0 or value > 100000.0:
            raise ValueError(f"{label} must be between 0 and 100,000 pt.")
    if not 1.0 <= border_thickness <= 10.0:
        raise ValueError("Page border thickness must be between 1 and 10 pt.")

    mode = _nup_layout_mode_from_config(cfg)
    cfg["layout_mode"] = mode
    cfg.pop("page_area", None)
    cfg.pop("auto_fit", None)
    cfg["border_thickness_pt"] = border_thickness
    cfg["page_color"] = _nup_normalize_hex_color(
        cfg.get("page_color"), _NUP_DEFAULT_PAGE_COLOR)
    cfg["border_color"] = _nup_normalize_hex_color(
        cfg.get("border_color"), _NUP_DEFAULT_BORDER_COLOR)
    cfg["consistent_across_sheets"] = bool(cfg.get("consistent_across_sheets", False))
    cfg["never_enlarge"] = bool(cfg.get("never_enlarge", False))
    cfg["auto_rotate"] = bool(cfg.get("auto_rotate", False))

    usable_width = width - left - right
    usable_height = height - top - bottom
    if usable_width <= 0.0 or usable_height <= 0.0:
        raise ValueError("Margins leave no usable area on the target page.")
    if mode in {"consistent_both", "consistent_height", "consistent_width", "uniform_scale"}:
        cell_width = (usable_width - (columns - 1) * horizontal_gap) / columns
        cell_height = (usable_height - (rows - 1) * vertical_gap) / rows
        if cell_width <= 0.0 or cell_height <= 0.0:
            raise ValueError("The selected margins and gaps leave no room for the grid.")
    if cfg.get("page_order") not in {
            "row", "row_reverse", "column", "column_reverse"}:
        raise ValueError("Choose one of the four supported page-order directions.")
    return cfg


def _nup_position_for_index(index, columns, rows, page_order):
    """Map reading order to a zero-based grid slot.

    Reversed modes reverse the fill direction within each row or column,
    matching the conventional Horizontal/Reversed and Vertical/Reversed order.
    """
    index = int(index)
    columns = int(columns)
    rows = int(rows)
    order = str(page_order or "row")
    if order == "column":
        return index % rows, index // rows
    if order == "column_reverse":
        return rows - 1 - (index % rows), index // rows
    if order == "row_reverse":
        return index // columns, columns - 1 - (index % columns)
    return index // columns, index % columns


def _nup_rotation_layout_area(dimensions, config):
    """Return the total visible page area for a candidate rotation assignment.

    This mirrors the geometry used by _nup_compute_sheet_layout, but computes
    its objective directly in one pass over the document. It is intentionally
    independent of PDF rendering so rotation search stays vector-safe.
    """
    cfg = _nup_validate_config(config)
    dims = []
    for index, pair in enumerate(dimensions or []):
        try:
            width, height = float(pair[0]), float(pair[1])
        except (TypeError, ValueError, IndexError, OverflowError) as exc:
            raise ValueError(f"Page {index + 1} has invalid dimensions for rotation search.") from exc
        if not (math.isfinite(width) and math.isfinite(height)
                and width > 0.0 and height > 0.0):
            raise ValueError(f"Page {index + 1} has invalid dimensions for rotation search.")
        dims.append((width, height))
    if not dims:
        return 0.0

    page_width = float(cfg["page_width_pt"])
    page_height = float(cfg["page_height_pt"])
    margins = cfg["margins"]
    usable_width = page_width - float(margins["left"]) - float(margins["right"])
    usable_height = page_height - float(margins["top"]) - float(margins["bottom"])
    columns = int(cfg["columns"])
    rows = int(cfg["rows"])
    hgap = float(cfg["horizontal_gap_pt"])
    vgap = float(cfg["vertical_gap_pt"])
    mode = cfg["layout_mode"]
    never_enlarge = bool(cfg.get("never_enlarge", False))
    shared = bool(cfg.get("consistent_across_sheets", False)) and mode in {
        "consistent_height", "consistent_width", "auto_width", "auto_height"}
    capacity = columns * rows

    groups = []
    for start in range(0, len(dims), capacity):
        group = []
        for local_index, (width, height) in enumerate(dims[start:start + capacity]):
            row, column = _nup_position_for_index(
                local_index, columns, rows, cfg["page_order"])
            if row < 0 or row >= rows or column < 0 or column >= columns:
                raise ValueError("The selected grid cannot contain the requested page order.")
            group.append({"width": width, "height": height,
                          "row": row, "column": column})
        groups.append(group)

    def active_count(slots, axis):
        key = "column" if axis == "column" else "row"
        return max((item[key] for item in slots), default=-1) + 1

    if mode == "consistent_both":
        cell_width = (usable_width - (columns - 1) * hgap) / columns
        cell_height = (usable_height - (rows - 1) * vgap) / rows
        if cell_width <= 0.0 or cell_height <= 0.0:
            raise ValueError("The selected margins and gaps leave no room for the grid.")
        areas = []
        for group in groups:
            for item in group:
                scale = min(cell_width / item["width"], cell_height / item["height"])
                if never_enlarge:
                    scale = min(1.0, scale)
                areas.append(item["width"] * item["height"] * scale * scale)
        return math.fsum(areas)

    if mode == "uniform_scale":
        cell_width = (usable_width - (columns - 1) * hgap) / columns
        cell_height = (usable_height - (rows - 1) * vgap) / rows
        if cell_width <= 0.0 or cell_height <= 0.0:
            raise ValueError("The selected margins and gaps leave no room for the grid.")
        scale = min(min(cell_width / width, cell_height / height)
                    for width, height in dims)
        if never_enlarge:
            scale = min(1.0, scale)
        return math.fsum(width * height * scale * scale for width, height in dims)

    if mode in {"consistent_height", "consistent_width"}:
        scopes = [groups[0] if shared else group for group in groups]
        # A shared sizing choice uses the full selected document as one scope.
        if shared:
            scopes = [[item for group in groups for item in group]]
        areas = []
        cell_width = (usable_width - (columns - 1) * hgap) / columns
        cell_height = (usable_height - (rows - 1) * vgap) / rows
        if cell_width <= 0.0 or cell_height <= 0.0:
            raise ValueError("The selected margins and gaps leave no room for the grid.")
        if mode == "consistent_height":
            for scope in scopes:
                common = cell_height
                for item in scope:
                    cap = min(cell_height,
                              cell_width * item["height"] / item["width"])
                    if never_enlarge:
                        cap = min(cap, item["height"])
                    common = min(common, cap)
                ratio_sum = math.fsum(item["width"] / item["height"] for item in scope)
                areas.append(common * common * ratio_sum)
        else:
            for scope in scopes:
                common = cell_width
                for item in scope:
                    cap = min(cell_width,
                              cell_height * item["width"] / item["height"])
                    if never_enlarge:
                        cap = min(cap, item["width"])
                    common = min(common, cap)
                ratio_sum = math.fsum(item["height"] / item["width"] for item in scope)
                areas.append(common * common * ratio_sum)
        return math.fsum(areas)

    # Adaptive modes: calculate the same content-weighted tracks and the same
    # maximum common reduction used by the production layout routine.
    is_width_mode = mode == "auto_width"
    all_slots = [item for group in groups for item in group]

    def create_tracks(track_scope):
        axis = "column" if is_width_mode else "row"
        count = active_count(track_scope, axis)
        gap = hgap if is_width_mode else vgap
        available = (usable_width if is_width_mode else usable_height) - max(0, count - 1) * gap
        if count <= 0 or available <= 0.0:
            raise ValueError(
                "The selected margins and gaps leave no room for adaptive tracks.")
        key = "column" if is_width_mode else "row"
        source_key = "width" if is_width_mode else "height"
        weights = [0.0] * count
        for item in track_scope:
            weights[item[key]] = max(weights[item[key]], item[source_key])
        total = math.fsum(weights)
        if total <= 0.0:
            raise ValueError("The selected pages have invalid dimensions for adaptive sizing.")
        return [available * weight / total for weight in weights]

    def cross_tracks(group, tracks, factor):
        if is_width_mode:
            count = active_count(group, "row")
            result = [0.0] * count
            for item in group:
                scale = tracks[item["column"]] * factor / item["width"]
                if never_enlarge:
                    scale = min(1.0, scale)
                result[item["row"]] = max(
                    result[item["row"]], item["height"] * scale)
            return result
        count = active_count(group, "column")
        result = [0.0] * count
        for item in group:
            scale = tracks[item["row"]] * factor / item["height"]
            if never_enlarge:
                scale = min(1.0, scale)
            result[item["column"]] = max(
                result[item["column"]], item["width"] * scale)
        return result

    def reduction_for(track_contexts):
        def fits(factor):
            for group, tracks in track_contexts:
                cross = cross_tracks(group, tracks, factor)
                gap = vgap if is_width_mode else hgap
                usable = usable_height if is_width_mode else usable_width
                used = math.fsum(cross) + max(0, len(cross) - 1) * gap
                if used > usable + 1e-7:
                    return False
            return True

        if not fits(0.0):
            raise ValueError("The selected gaps leave no room for adaptive content.")
        if fits(1.0):
            return 1.0
        low, high = 0.0, 1.0
        for _ in range(48):
            middle = (low + high) / 2.0
            if fits(middle):
                low = middle
            else:
                high = middle
        return low

    if shared:
        shared_tracks = create_tracks(all_slots)
        track_contexts = [(group, shared_tracks) for group in groups]
        reductions = [reduction_for(track_contexts)] * len(track_contexts)
    else:
        # The editor solves each output sheet independently when cross-sheet
        # consistency is off, so the objective must do the same.
        track_contexts = [(group, create_tracks(group)) for group in groups]
        reductions = [reduction_for([context]) for context in track_contexts]

    areas = []
    for (group, tracks), reduction in zip(track_contexts, reductions):
        for item in group:
            if is_width_mode:
                scale = tracks[item["column"]] * reduction / item["width"]
            else:
                scale = tracks[item["row"]] * reduction / item["height"]
            if never_enlarge:
                scale = min(1.0, scale)
            areas.append(item["width"] * item["height"] * scale * scale)
    return math.fsum(areas)


def _nup_auto_rotation_flags(dimensions, config, optimize=True):
    """Choose output-only page rotations to maximize actual layout utilization.

    Equal-size cells use the best per-page fit. Uniform scale maximizes the
    common feasible scale. Same-height/width modes are solved exactly by a
    threshold sweep. Adaptive modes use exhaustive search for small scopes and
    deterministic bounded neighborhood search for larger scopes. Original
    orientation wins ties, and source PDF entries are never mutated.
    """
    cfg = _nup_validate_config(config)
    dims = []
    for index, pair in enumerate(dimensions or []):
        try:
            width, height = float(pair[0]), float(pair[1])
        except (TypeError, ValueError, IndexError, OverflowError) as exc:
            raise ValueError("A selected page has invalid dimensions for automatic rotation.") from exc
        if not (math.isfinite(width) and math.isfinite(height)
                and width > 0.0 and height > 0.0):
            raise ValueError("A selected page has invalid dimensions for automatic rotation.")
        dims.append((width, height))
    if not cfg.get("auto_rotate", False) or not dims:
        return [False] * len(dims)

    width = float(cfg["page_width_pt"])
    height = float(cfg["page_height_pt"])
    margins = cfg["margins"]
    usable_width = width - float(margins["left"]) - float(margins["right"])
    usable_height = height - float(margins["top"]) - float(margins["bottom"])
    columns, rows = int(cfg["columns"]), int(cfg["rows"])
    cell_width = (usable_width - (columns - 1) * float(cfg["horizontal_gap_pt"])) / columns
    cell_height = (usable_height - (rows - 1) * float(cfg["vertical_gap_pt"])) / rows
    mode = cfg["layout_mode"]
    never_enlarge = bool(cfg.get("never_enlarge", False))

    def fit_score(page_width, page_height):
        if mode == "consistent_height":
            value = min(cell_height, cell_width * page_height / page_width)
            if never_enlarge:
                value = min(value, page_height)
            return value
        if mode == "consistent_width":
            value = min(cell_width, cell_height * page_width / page_height)
            if never_enlarge:
                value = min(value, page_width)
            return value
        value = min(cell_width / page_width, cell_height / page_height)
        return min(1.0, value) if never_enlarge else value

    heuristic = []
    importance = []
    for page_width, page_height in dims:
        normal = fit_score(page_width, page_height)
        rotated = fit_score(page_height, page_width)
        choose_rotated = rotated > normal + max(1e-9, abs(normal) * 1e-9)
        heuristic.append(choose_rotated)
        denominator = max(1e-12, min(abs(normal), abs(rotated)))
        importance.append(abs(rotated - normal) / denominator)

    # Equal-size cells are independent: maximize each page's area in its own
    # cell. Uniform scale is document-coupled, but its optimal common factor is
    # the minimum of each page's best feasible orientation. Once that factor is
    # known, retain the original orientation wherever it still fits.
    if mode == "uniform_scale":
        best_per_page = [max(fit_score(w, h), fit_score(h, w)) for w, h in dims]
        common_scale = min(best_per_page)
        flags = []
        for page_width, page_height in dims:
            normal_fit = fit_score(page_width, page_height)
            rotated_fit = fit_score(page_height, page_width)
            tolerance = max(1e-9, abs(common_scale) * 1e-9)
            if normal_fit + tolerance >= common_scale:
                flags.append(False)
            elif rotated_fit + tolerance >= common_scale:
                flags.append(True)
            else:
                flags.append(rotated_fit > normal_fit)
        return flags

    coupled_modes = {"consistent_height", "consistent_width", "auto_width", "auto_height"}
    if not optimize or mode not in coupled_modes:
        return heuristic

    capacity = columns * rows
    shared = bool(cfg.get("consistent_across_sheets", False))
    if shared:
        scopes = [list(range(len(dims)))]
    else:
        scopes = [list(range(start, min(len(dims), start + capacity)))
                  for start in range(0, len(dims), capacity)]

    def better(score, candidate, best_score, best):
        tolerance = max(1e-8, max(abs(score), abs(best_score), 1.0) * 1e-10)
        if score > best_score + tolerance:
            return True
        if abs(score - best_score) <= tolerance:
            candidate_count = sum(bool(value) for value in candidate)
            best_count = sum(bool(value) for value in best)
            if candidate_count < best_count:
                return True
            if candidate_count == best_count and tuple(candidate) < tuple(best):
                return True
        return False

    def optimize_common_size(scope):
        """Find an exact rotation assignment for a shared height or width.

        For a proposed common dimension, each page may choose either
        orientation whose fit cap allows that dimension. The best orientation
        is the one with the largest area contribution. The optimum common
        dimension must be the sheet limit or one of the two orientation caps,
        so sweeping those caps solves the binary rotation problem exactly in
        O(n log n) time rather than enumerating 2**n assignments.
        """
        common_height = mode == "consistent_height"
        limit = cell_height if common_height else cell_width
        events = []
        for local_index, global_index in enumerate(scope):
            page_width, page_height = dims[global_index]
            for rotated in (False, True):
                oriented_width, oriented_height = (
                    (page_height, page_width) if rotated
                    else (page_width, page_height))
                if common_height:
                    contribution = oriented_width / oriented_height
                    cap = min(limit, cell_width * oriented_height / oriented_width)
                    if never_enlarge:
                        cap = min(cap, oriented_height)
                else:
                    contribution = oriented_height / oriented_width
                    cap = min(limit, cell_height * oriented_width / oriented_height)
                    if never_enlarge:
                        cap = min(cap, oriented_width)
                events.append((float(cap), local_index, float(contribution), rotated))

        events.sort(key=lambda item: (-item[0], item[1], item[3]))
        selected = [None] * len(scope)
        ratio_sum = 0.0
        eligible_count = 0
        best_flags = [False] * len(scope)
        best_score = -1.0
        pointer = 0
        thresholds = sorted({limit, *(event[0] for event in events)}, reverse=True)

        for threshold in thresholds:
            while pointer < len(events) and events[pointer][0] >= threshold:
                cap, page_index, contribution, rotated = events[pointer]
                old = selected[page_index]
                candidate = (cap, contribution, rotated)
                if old is None:
                    selected[page_index] = candidate
                    ratio_sum += contribution
                    eligible_count += 1
                else:
                    old_cap, old_contribution, old_rotated = old
                    tol = max(1e-12, max(abs(old_contribution), abs(contribution), 1.0) * 1e-12)
                    better_option = contribution > old_contribution + tol
                    if abs(contribution - old_contribution) <= tol:
                        better_option = (cap > old_cap + 1e-9 or
                                         (abs(cap - old_cap) <= 1e-9
                                          and old_rotated and not rotated))
                    if better_option:
                        selected[page_index] = candidate
                        ratio_sum += contribution - old_contribution
                pointer += 1

            if eligible_count != len(scope):
                continue
            effective_common = min(limit, min(item[0] for item in selected))
            score = effective_common * effective_common * ratio_sum
            candidate_flags = [bool(item[2]) for item in selected]
            if better(score, candidate_flags, best_score, best_flags):
                best_score = score
                best_flags = candidate_flags

        return best_flags

    result = [False] * len(dims)
    for scope in scopes:
        local_dims = [dims[index] for index in scope]
        local_cfg = dict(cfg)
        if not shared:
            local_cfg["consistent_across_sheets"] = False

        def score_local(local_flags):
            oriented = [((h, w) if local_flags[i] else (w, h))
                        for i, (w, h) in enumerate(local_dims)]
            return _nup_rotation_layout_area(oriented, local_cfg)

        count = len(scope)
        if mode in {"consistent_height", "consistent_width"}:
            best_flags = optimize_common_size(scope)
            for local_index, global_index in enumerate(scope):
                result[global_index] = best_flags[local_index]
            continue

        if count <= 14:
            best_flags = [False] * count
            best_score = -1.0
            for mask in range(1 << count):
                candidate = [bool(mask & (1 << index)) for index in range(count)]
                score = score_local(candidate)
                if better(score, candidate, best_score, best_flags):
                    best_score = score
                    best_flags = candidate
            for local_index, global_index in enumerate(scope):
                result[global_index] = best_flags[local_index]
            continue

        heuristic_seed = [heuristic[index] for index in scope]
        reverse_seed = [not value for value in heuristic_seed]
        alternating_seed = [bool(index % 2) for index in range(count)]
        seeds = []
        seen_seeds = set()
        for seed in ([False] * count, heuristic_seed, reverse_seed, alternating_seed):
            identity = tuple(bool(value) for value in seed)
            if identity not in seen_seeds:
                seen_seeds.add(identity)
                seeds.append(list(identity))

        best_flags = [False] * count
        best_score = score_local(best_flags)
        for seed in seeds[1:]:
            score = score_local(seed)
            if better(score, seed, best_score, best_flags):
                best_score, best_flags = score, seed[:]

        # Adaptive sizing is a coupled problem. For larger scopes, use several
        # deterministic starting points and bounded coordinate ascent. Pages
        # whose local orientation changes fit the most are considered first.
        # This finds a stronger solution than a single greedy pass while
        # keeping preview work finite for unusually large selections.
        eval_budget = max(32, min(512, 131072 // max(1, count)))
        seed_budget = max(1, eval_budget // max(1, len(seeds)))
        candidate_order = sorted(
            range(count), key=lambda i: (-importance[scope[i]], i))

        for seed in seeds:
            current_flags = seed[:]
            current_score = score_local(current_flags)
            evaluations = 0
            for sweep in range(4):
                changed = False
                order = candidate_order if sweep % 2 == 0 else list(reversed(candidate_order))
                for local_index in order:
                    if evaluations >= seed_budget:
                        break
                    trial = current_flags[:]
                    trial[local_index] = not trial[local_index]
                    score = score_local(trial)
                    evaluations += 1
                    if better(score, trial, current_score, current_flags):
                        current_flags, current_score = trial, score
                        changed = True
                if evaluations >= seed_budget or not changed:
                    break
            if better(current_score, current_flags, best_score, best_flags):
                best_score, best_flags = current_score, current_flags[:]

        for local_index, global_index in enumerate(scope):
            result[global_index] = best_flags[local_index]

    return result


def _nup_orient_dimensions(dimensions, rotation_flags):
    """Return dimensions after the output-only orientation choices."""
    result = []
    for index, pair in enumerate(dimensions or []):
        width, height = float(pair[0]), float(pair[1])
        if index < len(rotation_flags) and rotation_flags[index]:
            width, height = height, width
        result.append((width, height))
    return result


def _nup_compute_sheet_layout(dimensions, config, document_dimensions=None):
    """Calculate vector placements in top-left PDF-point coordinates.

    The sizing modes preserve their defined sizing behavior. A document-wide
    consistency request shares height/width/track geometry across sheets, while
    Uniform scale uses one factor for the entire selected document. All content
    is scaled uniformly and remains inside the requested page area.
    """
    cfg = _nup_validate_config(config)
    if not dimensions:
        raise ValueError("An N-up sheet must contain at least one page.")
    page_width = float(cfg["page_width_pt"])
    page_height = float(cfg["page_height_pt"])
    margins = cfg["margins"]
    top = float(margins["top"])
    left = float(margins["left"])
    usable_width = page_width - left - float(margins["right"])
    usable_height = page_height - top - float(margins["bottom"])
    columns = int(cfg["columns"])
    rows = int(cfg["rows"])
    horizontal_gap = float(cfg["horizontal_gap_pt"])
    vertical_gap = float(cfg["vertical_gap_pt"])
    mode = cfg["layout_mode"]
    never_enlarge = bool(cfg.get("never_enlarge", False))
    shared = bool(cfg.get("consistent_across_sheets", False)) and mode in {
        "consistent_height", "consistent_width", "auto_width", "auto_height"}

    scope_dimensions = list(document_dimensions or dimensions)
    for index, pair in enumerate(scope_dimensions):
        try:
            scope_width, scope_height = float(pair[0]), float(pair[1])
        except (TypeError, ValueError, IndexError, OverflowError) as exc:
            raise ValueError(f"Document page {index + 1} has invalid dimensions.") from exc
        if not (math.isfinite(scope_width) and math.isfinite(scope_height)
                and scope_width > 0.0 and scope_height > 0.0):
            raise ValueError(f"Document page {index + 1} has invalid dimensions.")
    capacity = columns * rows

    def make_slots(dims):
        made = []
        for index, (raw_width, raw_height) in enumerate(dims):
            w, h = float(raw_width), float(raw_height)
            if not (math.isfinite(w) and math.isfinite(h) and w > 0 and h > 0):
                raise ValueError(f"Page {index + 1} has invalid dimensions.")
            row, column = _nup_position_for_index(index, columns, rows, cfg["page_order"])
            if row >= rows or column >= columns:
                raise ValueError("The sheet contains more pages than its grid capacity.")
            made.append({"index": index, "row": row, "column": column,
                         "width": w, "height": h})
        return made

    slots = make_slots(dimensions)
    global_slots = []
    for global_index, (global_width, global_height) in enumerate(scope_dimensions):
        local_index = global_index % capacity
        row, column = _nup_position_for_index(local_index, columns, rows, cfg["page_order"])
        global_slots.append({"index": global_index, "row": row, "column": column,
                             "width": float(global_width), "height": float(global_height)})

    def active_track_count(slot_list, axis):
        key = "column" if axis == "column" else "row"
        return max(slot[key] for slot in slot_list) + 1 if slot_list else 0

    # Fixed grid cells: Equal-size cells and the two one-axis common-size modes.
    if mode in {"consistent_both", "consistent_height", "consistent_width", "uniform_scale"}:
        cell_width = (usable_width - (columns - 1) * horizontal_gap) / columns
        cell_height = (usable_height - (rows - 1) * vertical_gap) / rows
        if cell_width <= 0 or cell_height <= 0:
            raise ValueError("The selected margins and gaps leave no room for the grid.")

        placements = []
        if mode == "consistent_both":
            for slot in slots:
                scale = min(cell_width / slot["width"], cell_height / slot["height"])
                if never_enlarge:
                    scale = min(1.0, scale)
                placed_width = slot["width"] * scale
                placed_height = slot["height"] * scale
                x = left + slot["column"] * (cell_width + horizontal_gap)
                y = top + slot["row"] * (cell_height + vertical_gap)
                x += (cell_width - placed_width) / 2.0
                y += (cell_height - placed_height) / 2.0
                placements.append({"index": slot["index"], "row": slot["row"],
                                   "column": slot["column"],
                                   "rect": (x, y, x + placed_width, y + placed_height)})

        elif mode in {"consistent_height", "consistent_width"}:
            constraint_dims = scope_dimensions if shared else dimensions
            if mode == "consistent_height":
                common = cell_height
                for raw_width, raw_height in constraint_dims:
                    w, h = float(raw_width), float(raw_height)
                    common = min(common, cell_width * h / w)
                    if never_enlarge:
                        common = min(common, h)
            else:
                common = cell_width
                for raw_width, raw_height in constraint_dims:
                    w, h = float(raw_width), float(raw_height)
                    common = min(common, cell_height * w / h)
                    if never_enlarge:
                        common = min(common, w)
            if not math.isfinite(common) or common <= 0:
                raise ValueError("The selected pages cannot fit at the requested consistent size.")
            for slot in slots:
                if mode == "consistent_height":
                    placed_height = common
                    placed_width = placed_height * slot["width"] / slot["height"]
                else:
                    placed_width = common
                    placed_height = placed_width * slot["height"] / slot["width"]
                x = left + slot["column"] * (cell_width + horizontal_gap)
                y = top + slot["row"] * (cell_height + vertical_gap)
                x += (cell_width - placed_width) / 2.0
                y += (cell_height - placed_height) / 2.0
                placements.append({"index": slot["index"], "row": slot["row"],
                                   "column": slot["column"],
                                   "rect": (x, y, x + placed_width, y + placed_height)})

        else:  # uniform_scale
            common_scale = min(
                min(cell_width / float(w), cell_height / float(h))
                for w, h in scope_dimensions)
            if never_enlarge:
                common_scale = min(1.0, common_scale)
            for slot in slots:
                placed_width = slot["width"] * common_scale
                placed_height = slot["height"] * common_scale
                x = left + slot["column"] * (cell_width + horizontal_gap)
                y = top + slot["row"] * (cell_height + vertical_gap)
                x += (cell_width - placed_width) / 2.0
                y += (cell_height - placed_height) / 2.0
                placements.append({"index": slot["index"], "row": slot["row"],
                                   "column": slot["column"],
                                   "rect": (x, y, x + placed_width, y + placed_height)})

    else:
        is_width_mode = mode == "auto_width"
        local_active_columns = active_track_count(slots, "column")
        local_active_rows = active_track_count(slots, "row")
        track_scope = global_slots if shared else slots
        active_columns = (active_track_count(global_slots, "column") if shared
                          else local_active_columns)
        active_rows_global = (active_track_count(global_slots, "row") if shared
                              else local_active_rows)

        if is_width_mode:
            content_width = usable_width - (active_columns - 1) * horizontal_gap
            if content_width <= 0:
                raise ValueError("Horizontal gaps leave no room for adaptive column widths.")
            weights = [0.0] * active_columns
            for slot in track_scope:
                weights[slot["column"]] = max(weights[slot["column"]], slot["width"])
            total_weight = sum(weights)
            if total_weight <= 0:
                raise ValueError("The selected pages have invalid widths.")
            base_tracks = [content_width * weight / total_weight for weight in weights]

            def row_tracks(sheet_dims, factor):
                sheet_slots = make_slots(sheet_dims)
                # Adaptive row heights remain sheet-local even when column
                # widths are shared document-wide.
                count = active_track_count(sheet_slots, "row")
                values = [0.0] * count
                for item in sheet_slots:
                    width = base_tracks[item["column"]] * factor
                    scale = width / item["width"]
                    if never_enlarge:
                        scale = min(1.0, scale)
                    values[item["row"]] = max(
                        values[item["row"]], item["height"] * scale)
                return values

            sheets_to_check = ([scope_dimensions[i:i + capacity]
                                for i in range(0, len(scope_dimensions), capacity)]
                               if shared else [dimensions])

            def width_layout_fits(factor):
                for sheet_dims in sheets_to_check:
                    sheet_rows = row_tracks(sheet_dims, factor)
                    used = sum(sheet_rows) + max(0, len(sheet_rows) - 1) * vertical_gap
                    if used > usable_height + 1e-7:
                        return False
                return True

            if not width_layout_fits(0.0):
                raise ValueError("Vertical gaps leave no room for adaptive column widths.")
            if width_layout_fits(1.0):
                reduction = 1.0
            else:
                low, high = 0.0, 1.0
                for _ in range(48):
                    mid = (low + high) / 2.0
                    if width_layout_fits(mid):
                        low = mid
                    else:
                        high = mid
                reduction = low
            column_widths = [value * reduction for value in base_tracks]
            row_heights = row_tracks(dimensions, reduction)
            layout_width = sum(column_widths) + max(0, active_columns - 1) * horizontal_gap
            layout_height = sum(row_heights) + max(0, len(row_heights) - 1) * vertical_gap
            x_start = left + (usable_width - layout_width) / 2.0
            y_start = top + (usable_height - layout_height) / 2.0
            x_positions = []
            cursor = x_start
            for value in column_widths:
                x_positions.append(cursor)
                cursor += value + horizontal_gap
            y_positions = []
            cursor = y_start
            for value in row_heights:
                y_positions.append(cursor)
                cursor += value + vertical_gap
            placements = []
            for slot in slots:
                width = column_widths[slot["column"]]
                scale = width / slot["width"]
                if never_enlarge:
                    scale = min(1.0, scale)
                placed_width = slot["width"] * scale
                placed_height = slot["height"] * scale
                x = x_positions[slot["column"]] + (width - placed_width) / 2.0
                row_height = row_heights[slot["row"]]
                y = y_positions[slot["row"]] + (row_height - placed_height) / 2.0
                placements.append({"index": slot["index"], "row": slot["row"],
                                   "column": slot["column"],
                                   "rect": (x, y, x + placed_width, y + placed_height)})

        else:  # auto_height
            content_height = usable_height - (active_rows_global - 1) * vertical_gap if shared else (
                usable_height - (local_active_rows - 1) * vertical_gap)
            if content_height <= 0:
                raise ValueError("Vertical gaps leave no room for adaptive row heights.")
            track_count = active_rows_global if shared else local_active_rows
            weights = [0.0] * track_count
            for slot in track_scope:
                weights[slot["row"]] = max(weights[slot["row"]], slot["height"])
            total_weight = sum(weights)
            if total_weight <= 0:
                raise ValueError("The selected pages have invalid heights.")
            base_tracks = [content_height * weight / total_weight for weight in weights]

            def column_tracks(sheet_dims, factor):
                sheet_slots = make_slots(sheet_dims)
                # Adaptive column widths remain sheet-local even when row
                # heights are shared document-wide.
                count = active_track_count(sheet_slots, "column")
                values = [0.0] * count
                for item in sheet_slots:
                    height = base_tracks[item["row"]] * factor
                    scale = height / item["height"]
                    if never_enlarge:
                        scale = min(1.0, scale)
                    values[item["column"]] = max(
                        values[item["column"]], item["width"] * scale)
                return values

            sheets_to_check = ([scope_dimensions[i:i + capacity]
                                for i in range(0, len(scope_dimensions), capacity)]
                               if shared else [dimensions])

            def height_layout_fits(factor):
                for sheet_dims in sheets_to_check:
                    sheet_columns = column_tracks(sheet_dims, factor)
                    used = sum(sheet_columns) + max(0, len(sheet_columns) - 1) * horizontal_gap
                    if used > usable_width + 1e-7:
                        return False
                return True

            if not height_layout_fits(0.0):
                raise ValueError("Horizontal gaps leave no room for adaptive row heights.")
            if height_layout_fits(1.0):
                reduction = 1.0
            else:
                low, high = 0.0, 1.0
                for _ in range(48):
                    mid = (low + high) / 2.0
                    if height_layout_fits(mid):
                        low = mid
                    else:
                        high = mid
                reduction = low
            row_heights = [value * reduction for value in base_tracks]
            column_widths = column_tracks(dimensions, reduction)
            layout_width = sum(column_widths) + max(0, len(column_widths) - 1) * horizontal_gap
            layout_height = sum(row_heights) + max(0, len(row_heights) - 1) * vertical_gap
            x_start = left + (usable_width - layout_width) / 2.0
            y_start = top + (usable_height - layout_height) / 2.0
            x_positions = []
            cursor = x_start
            for value in column_widths:
                x_positions.append(cursor)
                cursor += value + horizontal_gap
            y_positions = []
            cursor = y_start
            for value in row_heights:
                y_positions.append(cursor)
                cursor += value + vertical_gap
            placements = []
            for slot in slots:
                height = row_heights[slot["row"]]
                scale = height / slot["height"]
                if never_enlarge:
                    scale = min(1.0, scale)
                placed_width = slot["width"] * scale
                placed_height = slot["height"] * scale
                column_width = column_widths[slot["column"]]
                x = x_positions[slot["column"]] + (column_width - placed_width) / 2.0
                y = y_positions[slot["row"]] + (height - placed_height) / 2.0
                placements.append({"index": slot["index"], "row": slot["row"],
                                   "column": slot["column"],
                                   "rect": (x, y, x + placed_width, y + placed_height)})

    placements.sort(key=lambda placement: placement["index"])
    epsilon = 1e-6
    right_limit = page_width - float(margins["right"])
    bottom_limit = page_height - float(margins["bottom"])
    for placement in placements:
        x0, y0, x1, y1 = placement["rect"]
        if (x0 < left - epsilon or y0 < top - epsilon
                or x1 > right_limit + epsilon
                or y1 > bottom_limit + epsilon
                or x1 <= x0 or y1 <= y0):
            raise ValueError("The calculated N-up layout exceeds the printable page area.")
    return {"page_size": (page_width, page_height), "placements": placements}


def _nup_build_pdf(entries, config, output_path, preview_png_path=None):
    """Materialize edited source pages and compose them as vector PDF overlays."""
    cfg = _nup_validate_config(config)
    if not entries:
        raise ValueError("No pages were supplied for N-up composition.")
    output_path = os.path.abspath(str(output_path))
    prepared_path = output_path + ".prepared.pdf"
    filtered_path = prepared_path + ".filtered.pdf"
    source_docs = {}
    prepared = None
    output = None
    try:
        os.makedirs(os.path.dirname(output_path) or TEMP_FOLDER, exist_ok=True)
        for path in (output_path, prepared_path, filtered_path, preview_png_path):
            if path:
                try:
                    if os.path.isfile(path):
                        os.remove(path)
                except OSError:
                    pass

        prepared = fitz.open()
        filter_configs = {}
        for index, entry in enumerate(entries):
            source_pdf = os.path.abspath(str(entry.get("source_pdf") or ""))
            if not source_pdf or not os.path.isfile(source_pdf):
                raise FileNotFoundError(
                    f"Source PDF for selected page {index + 1} is missing:\n{source_pdf}")
            if source_pdf not in source_docs:
                source_docs[source_pdf] = fitz.open(source_pdf)
            src = source_docs[source_pdf]
            page_index = int(entry.get("original_idx", 0))
            if page_index < 0 or page_index >= src.page_count:
                raise IndexError(
                    f"Page {page_index + 1} is outside {os.path.basename(source_pdf)}.")
            source_page = src.load_page(page_index)
            try:
                src_rotation = int(source_page.rotation) % 360
            except Exception:
                src_rotation = 0
            prepared.insert_pdf(src, from_page=page_index, to_page=page_index)
            page = prepared[-1]
            if _page_design_has_any(entry) and _page_design_anchor_state(entry) is not None:
                ordered = _page_design_ordered_document(entry, apply_filters=True)
                try:
                    prepared.delete_page(prepared.page_count - 1)
                except Exception:
                    pass
                prepared.insert_pdf(ordered)
                ordered.close()
            else:
                ocr_blocks = (entry.get("ocr")
                              if entry.get("ocr_done") or entry.get("ocr") else None)
                if ocr_blocks is not None:
                    filtered_blocks, _skipped = _filter_duplicate_ocr_blocks(
                        page, ocr_blocks)
                    _insert_ocr_text(page, filtered_blocks, filter_existing=False)
                apply_entry_to_page(page, entry, src_rot=src_rotation)
                filter_cfg = _entry_filter_config(entry)
                if _filter_config_active(filter_cfg):
                    filter_configs[index] = filter_cfg
        prepared.save(prepared_path, garbage=0, deflate=False)
        prepared.close()
        prepared = None
        for doc in source_docs.values():
            try:
                doc.close()
            except Exception:
                pass
        source_docs = {}

        if filter_configs:
            if not process_page_filters_pdf_file(
                    prepared_path, filtered_path, filter_configs):
                raise RuntimeError("Could not apply existing PDF filters to selected pages.")
            os.replace(filtered_path, prepared_path)

        stretch_entries = [
            dict(entry, stretch_ratio=(None if (
                _page_design_has_any(entry) and _page_design_anchor_state(entry) is not None)
                else entry.get("stretch_ratio")))
            for entry in entries
        ]
        if any(entry.get("stretch_ratio") is not None for entry in stretch_entries):
            _stretch_pdf_for_entries(prepared_path, stretch_entries)

        if any(_page_design_has_any(entry) for entry in entries):
            _apply_page_design_to_pdf(prepared_path, entries, progress=None)

        with fitz.open(prepared_path) as prepared_check:
            if prepared_check.page_count != len(entries):
                raise RuntimeError(
                    f"Prepared-page verification failed: expected {len(entries)} pages, "
                    f"found {prepared_check.page_count}.")

            # Dimensions from the dialog reflect the edited visible pages. They
            # let preview-only jobs make the same document-wide decisions as Apply.
            document_dimensions = cfg.get("_nup_document_dimensions")
            if not isinstance(document_dimensions, (list, tuple)) or not document_dimensions:
                document_dimensions = []
                for index in range(prepared_check.page_count):
                    rect = prepared_check.load_page(index).rect
                    document_dimensions.append((float(rect.width), float(rect.height)))
            else:
                document_dimensions = [tuple(map(float, pair)) for pair in document_dimensions]
            rotation_flags = _nup_auto_rotation_flags(document_dimensions, cfg)
            offset = max(0, int(cfg.get("_nup_document_offset", 0) or 0))
            local_flags = rotation_flags[offset:offset + prepared_check.page_count]
            if len(local_flags) < prepared_check.page_count:
                local_flags.extend([False] * (prepared_check.page_count - len(local_flags)))

            dimensions = []
            for index in range(prepared_check.page_count):
                page = prepared_check.load_page(index)
                if local_flags[index]:
                    page.set_rotation((int(page.rotation) + 90) % 360)
                rect = page.rect
                dimensions.append((float(rect.width), float(rect.height)))

            oriented_document_dimensions = _nup_orient_dimensions(
                document_dimensions, rotation_flags)
            capacity = int(cfg["columns"]) * int(cfg["rows"])
            sheet_count = int(math.ceil(len(entries) / float(capacity)))
            output = fitz.open()
            for sheet_index in range(sheet_count):
                start = sheet_index * capacity
                end = min(len(entries), start + capacity)
                sheet_dimensions = dimensions[start:end]
                # A preview job contains one sheet, but its offset identifies that
                # sheet in the full document for shared sizing and uniform scale.
                sheet_layout = _nup_compute_sheet_layout(
                    sheet_dimensions, cfg,
                    document_dimensions=oriented_document_dimensions)
                page_width, page_height = sheet_layout["page_size"]
                output_page = output.new_page(width=page_width, height=page_height)
                # Draw the selected paper color as a background object so it
                # remains beneath every vector-embedded source page.
                output_page.draw_rect(
                    fitz.Rect(0, 0, page_width, page_height),
                    color=None, fill=_nup_color_rgb(
                        cfg.get("page_color"), _NUP_DEFAULT_PAGE_COLOR),
                    width=0, overlay=False)
                for placement in sheet_layout["placements"]:
                    source_index = start + int(placement["index"])
                    rect = fitz.Rect(*placement["rect"])
                    source_page = prepared_check.load_page(source_index)
                    try:
                        source_rotation = int(source_page.rotation) % 360
                    except Exception:
                        source_rotation = 0
                    # show_pdf_page() interprets source_page.rect in unrotated
                    # page coordinates. Clear /Rotate before embedding and
                    # apply its inverse as a placement transform, matching the
                    # PDF-native path used by _append_display_stretched_page().
                    # CropBox stays intact, so the already-cropped-away content
                    # cannot leak into the N-up sheet.
                    if source_rotation:
                        source_page.set_rotation(0)
                    # show_pdf_page creates a PDF Form XObject. It retains vector
                    # paths/text and embedded image streams instead of rasterizing.
                    output_page.show_pdf_page(
                        rect, prepared_check, source_index,
                        keep_proportion=False, overlay=True,
                        rotate=(-source_rotation) % 360)
                    if bool(cfg.get("borders", True)):
                        output_page.draw_rect(
                            rect, color=_nup_color_rgb(
                                cfg.get("border_color"), _NUP_DEFAULT_BORDER_COLOR),
                            width=float(cfg.get(
                                "border_thickness_pt", _NUP_BORDER_THICKNESS_PT)),
                            overlay=True)
            output.save(output_path, garbage=3, deflate=True)
            output.close()
            output = None

        with fitz.open(output_path) as final_check:
            if final_check.page_count != sheet_count:
                raise RuntimeError(
                    f"N-up verification failed: expected {sheet_count} pages, "
                    f"found {final_check.page_count}.")
            target_width, target_height = cfg["page_width_pt"], cfg["page_height_pt"]
            for index in range(final_check.page_count):
                rect = final_check.load_page(index).rect
                if (not math.isclose(float(rect.width), target_width,
                                     rel_tol=0.0, abs_tol=0.05)
                        or not math.isclose(float(rect.height), target_height,
                                            rel_tol=0.0, abs_tol=0.05)):
                    raise RuntimeError(
                        f"N-up verification found an unexpected page size on sheet {index + 1}.")
            if preview_png_path:
                preview_page = final_check.load_page(0)
                preview_scale = min(96.0 / 72.0,
                                    1400.0 / max(target_width, target_height))
                pix = preview_page.get_pixmap(
                    matrix=fitz.Matrix(preview_scale, preview_scale), alpha=False)
                pix.save(preview_png_path)
        return sheet_count
    except Exception:
        for path in (output_path, prepared_path, filtered_path, preview_png_path):
            if path:
                try:
                    if os.path.isfile(path):
                        os.remove(path)
                except OSError:
                    pass
        raise
    finally:
        for doc in source_docs.values():
            try:
                doc.close()
            except Exception:
                pass
        if prepared is not None:
            try:
                prepared.close()
            except Exception:
                pass
        if output is not None:
            try:
                output.close()
            except Exception:
                pass
        try:
            if os.path.isfile(prepared_path):
                os.remove(prepared_path)
        except OSError:
            pass
        try:
            if os.path.isfile(filtered_path):
                os.remove(filtered_path)
        except OSError:
            pass


def _nup_process_worker(entries, config, output_path, preview_png_path, result_conn):
    """Spawn-safe N-up worker entry point. The UI never performs PDF composition."""
    try:
        count = _nup_build_pdf(entries, config, output_path, preview_png_path)
        result_conn.send(("ok", output_path, count))
    except Exception as exc:
        try:
            result_conn.send(("error", f"{type(exc).__name__}: {exc}"))
        except Exception:
            pass
    finally:
        try:
            result_conn.close()
        except Exception:
            pass


class _NUpNoWheelSpinBox(_SettingsSpinBox):
    """Keep the settings panel scrollable without changing values on wheel."""

    def wheelEvent(self, event):
        # Let the enclosing settings QScrollArea receive the wheel event.
        # Arrow buttons and keyboard stepping continue to work normally.
        event.ignore()


class _NUpNoWheelDoubleSpinBox(_SettingsDoubleSpinBox):
    """N-up numeric field whose value is never changed by mouse scrolling."""

    def wheelEvent(self, event):
        event.ignore()


class _NUpNoWheelComboBox(QtWidgets.QComboBox):
    """N-up selector that leaves wheel scrolling to its containing scroll area."""

    def wheelEvent(self, event):
        event.ignore()


class _NUpNoWheelSlider(QtWidgets.QSlider):
    """N-up slider that does not change value when the settings panel is scrolled."""

    def wheelEvent(self, event):
        event.ignore()


class NUpSelectedPagesDialog(QtWidgets.QDialog):
    """Configurable, vector-preserving N-up compositor for selected Edit PDF pages."""
    _CARD = ("QFrame { background:#161616; border:1px solid #2d2d2d; "
             "border-radius:8px; }")
    _SECTION = ("QLabel { color:#f0f0f0; font-size:10.5pt; font-weight:bold; "
                "background:transparent; border:none; padding:0; margin:0; }")
    _TEXT_LABEL = "QLabel { background:transparent; border:none; padding:0; margin:0; }"

    def __init__(self, page_edit, selected_entries, selected_anchor=0, parent=None):
        super().__init__(parent or page_edit)
        self.page_edit = page_edit
        self._original_entries = [copy.deepcopy(entry) for _, entry in selected_entries]
        self._selected_uids = [entry.get("uid") for entry in self._original_entries]
        self._selected_count = len(self._original_entries)
        self._page_dimensions = []
        self._page_image_cache = collections.OrderedDict()
        self._page_image_cache_bytes = 0
        self._page_image_cache_limit = 48 * 1024 * 1024
        self._fast_pixmap = QtGui.QPixmap()
        self._exact_pixmap = QtGui.QPixmap()
        self._current_sheet = 0
        self._zoom = 1.0
        self._generation = 0
        self._job = None
        self._job_conn = None
        self._job_path = None
        self._job_png_path = None
        self._job_kind = None
        self._job_generation = -1
        self._job_sheet = -1
        self._retired_jobs = []
        self._closing = False
        self._committed = False
        self.result_pdf_path = None
        self._idle_timer = QtCore.QTimer(self)
        self._idle_timer.setSingleShot(True)
        self._idle_timer.setInterval(850)
        self._idle_timer.timeout.connect(self._start_exact_preview)
        self._preview_timer = QtCore.QTimer(self)
        self._preview_timer.setSingleShot(True)
        self._preview_timer.setInterval(35)
        self._preview_timer.timeout.connect(self._refresh_fast_preview)
        self._poll_timer = QtCore.QTimer(self)
        self._poll_timer.setInterval(50)
        self._poll_timer.timeout.connect(self._poll_job)
        self._reaper_timer = QtCore.QTimer(self)
        self._reaper_timer.setInterval(60)
        self._reaper_timer.timeout.connect(self._reap_jobs)

        initial = getattr(page_edit, "_nup_last_config", None)
        if not isinstance(initial, dict):
            initial = {
                "page_size_name": "A4 Portrait",
                "page_width_pt": _NUP_PAGE_SIZES["A4 Portrait"][0],
                "page_height_pt": _NUP_PAGE_SIZES["A4 Portrait"][1],
                "columns": 2,
                "rows": 2,
                "margins": {"top": 18.0, "bottom": 18.0,
                            "left": 18.0, "right": 18.0},
                "horizontal_gap_pt": 8.0,
                "vertical_gap_pt": 8.0,
                "borders": True,
                "border_thickness_pt": 1.0,
                "page_color": _NUP_DEFAULT_PAGE_COLOR,
                "border_color": _NUP_DEFAULT_BORDER_COLOR,
                "layout_mode": "consistent_both",
                "consistent_across_sheets": False,
                "never_enlarge": False,
                "auto_rotate": False,
                "page_order": "row",
            }
        else:
            initial = copy.deepcopy(initial)
        self._initial_config = initial
        self._page_color = _nup_normalize_hex_color(
            initial.get("page_color"), _NUP_DEFAULT_PAGE_COLOR)
        self._border_color = _nup_normalize_hex_color(
            initial.get("border_color"), _NUP_DEFAULT_BORDER_COLOR)

        self.setWindowTitle("N-up / Merge Selected Pages")
        self.setModal(True)
        self.setMinimumSize(960, 640)
        screen = QtWidgets.QApplication.primaryScreen()
        if screen is not None:
            geom = screen.availableGeometry()
            self.resize(min(1220, max(960, geom.width() - 70)),
                        min(820, max(640, geom.height() - 90)))
        else:
            self.resize(1120, 730)

        root = QtWidgets.QVBoxLayout(self)
        root.setContentsMargins(18, 16, 18, 16)
        root.setSpacing(10)
        header = QtWidgets.QHBoxLayout()
        header.setContentsMargins(0, 0, 0, 2)
        title = QtWidgets.QLabel("N-up / Merge selected pages")
        title.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        title.setStyleSheet(
            "font-size:14pt; font-weight:bold; color:#f0f0f0; "
            "background:transparent; border:none; padding:0; margin:0;")
        header.addWidget(title, 1)
        # Keep the title centered over the full dialog width. The selected-page
        # count is already shown in the persistent footer summary.
        root.addLayout(header)

        splitter = QtWidgets.QSplitter(QtCore.Qt.Orientation.Horizontal)
        splitter.setChildrenCollapsible(False)
        root.addWidget(splitter, 1)

        # LEFT: output-sheet preview, intentionally separate from the settings.
        preview_card = QtWidgets.QFrame()
        self.preview_card = preview_card
        preview_card.setStyleSheet(self._CARD)
        preview_layout = QtWidgets.QVBoxLayout(preview_card)
        preview_layout.setContentsMargins(8, 8, 8, 8)
        preview_layout.setSpacing(6)
        preview_header = QtWidgets.QHBoxLayout()
        preview_title = QtWidgets.QLabel("Output preview")
        preview_title.setStyleSheet(self._SECTION)
        preview_header.addWidget(preview_title)
        preview_header.addStretch(1)
        preview_layout.addLayout(preview_header)

        self.preview_scroll = QtWidgets.QScrollArea()
        self.preview_scroll.setWidgetResizable(False)
        self.preview_scroll.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.preview_scroll.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        self.preview_scroll.setStyleSheet(
            "QScrollArea { background:#101010; border:1px solid #2d2d2d; border-radius:6px; }")
        self.preview_image_lbl = QtWidgets.QLabel()
        self.preview_image_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.preview_image_lbl.setStyleSheet("background:#101010; border:none;")
        self.preview_image_lbl.setMinimumSize(1, 1)
        self.preview_scroll.setWidget(self.preview_image_lbl)
        preview_layout.addWidget(self.preview_scroll, 1)

        # Shared preview footer: use the same zoom control widget, divider, navigation
        # button geometry, colors, icon sizes, and keyboard shortcuts as Apply Filters.
        # N-up intentionally changes only the semantic label from "Selected page" to
        # "Sheet", because the footer summary below already carries the selected count.
        preview_footer = QtWidgets.QHBoxLayout()
        preview_footer.setContentsMargins(3, 0, 3, 0)
        preview_footer.setSpacing(6)

        self.zoom_footer = _PdfZoomFooter(
            lambda: self._zoom,
            self._zoom_in_preview,
            self._zoom_out_preview,
            self._zoom_percent_preview_changed,
            self._fit_preview,
            self,
        )
        preview_footer.addWidget(self.zoom_footer)

        preview_footer.addSpacing(10)
        preview_footer.addWidget(_make_toolbar_divider(self))
        preview_footer.addSpacing(10)

        self.prev_btn = self._make_preview_nav_btn(
            "prev.svg", "Previous sheet (Left Arrow)", self._previous_sheet)
        self.next_btn = self._make_preview_nav_btn(
            "next.svg", "Next sheet (Right Arrow)", self._next_sheet)
        preview_footer.addWidget(self.prev_btn)
        preview_footer.addWidget(self.next_btn)

        self.sheet_lbl = QtWidgets.QLabel("Sheet 1/1")
        self.sheet_lbl.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        self.sheet_lbl.setStyleSheet(
            "color:#4a9eff; font-weight:bold; font-size:10pt; "
            "background:transparent; border:none; padding-left:8px; margin:0;")
        preview_footer.addWidget(self.sheet_lbl)
        preview_footer.addStretch(1)
        preview_layout.addLayout(preview_footer)
        self._install_preview_shortcuts()
        splitter.addWidget(preview_card)

        # RIGHT: scrollable option cards.
        self.settings_scroll = QtWidgets.QScrollArea()
        self.settings_scroll.setWidgetResizable(True)
        self.settings_scroll.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        self.settings_scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.settings_scroll.setStyleSheet(
            "QScrollArea { border:none; background:transparent; }")
        settings_inner = QtWidgets.QWidget()
        self.settings_layout = QtWidgets.QVBoxLayout(settings_inner)
        self.settings_layout.setContentsMargins(2, 0, 4, 0)
        self.settings_layout.setSpacing(8)

        self._build_page_card()
        self._build_grid_card()
        self._build_area_card()
        self._build_spacing_card()
        self._build_interactive_content_warning()
        self.settings_layout.addStretch()
        self.settings_scroll.setWidget(settings_inner)
        splitter.addWidget(self.settings_scroll)
        splitter.setSizes([570, 390])

        bottom = QtWidgets.QHBoxLayout()
        bottom.setSpacing(8)
        self.reset_btn = QtWidgets.QPushButton("Reset")
        self.reset_btn.setFixedWidth(110)
        self.reset_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.reset_btn.setStyleSheet("""
            QPushButton { background:#2a2a2a; color:#f0f0f0; border:1px solid #3a3a3a;
                border-radius:6px; padding:8px 16px; font-weight:bold; }
            QPushButton:hover { background:#343434; }
            QPushButton:pressed { background:#3c3c3c; }
            QPushButton:disabled { background:#222222; color:#666666; border:1px solid #2a2a2a; }
        """)
        self.reset_btn.clicked.connect(self._reset_controls)
        bottom.addWidget(self.reset_btn)
        bottom.addStretch()
        self.summary_lbl = QtWidgets.QLabel("")
        self.summary_lbl.setStyleSheet(
            "color:#aaaaaa; background:transparent; border:none; font-size:9pt;")
        bottom.addWidget(self.summary_lbl, 1)
        cancel_btn = QtWidgets.QPushButton("Cancel")
        cancel_btn.setFixedWidth(120)
        cancel_btn.clicked.connect(self.reject)
        bottom.addWidget(cancel_btn)
        self.apply_btn = QtWidgets.QPushButton("Apply N-up")
        self.apply_btn.setFixedWidth(145)
        self.apply_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.apply_btn.setStyleSheet("""
            QPushButton { background:#0078d7; color:white; border:none; border-radius:6px;
                padding:8px 16px; font-weight:bold; }
            QPushButton:hover { background:#005fa3; }
            QPushButton:disabled { background:#2b2b2b; color:#696969; border:1px solid #3a3a3a; }
        """)
        self.apply_btn.clicked.connect(self._apply)
        bottom.addWidget(self.apply_btn)
        root.addLayout(bottom)

        self._load_initial_controls()
        self._connect_control_signals()
        self._update_dynamic_controls()
        self._update_summary_and_apply()
        dimension_docs = {}
        try:
            self._page_dimensions = [
                _nup_entry_visible_size(entry, dimension_docs)
                for entry in self._original_entries]
        finally:
            for dimension_doc in dimension_docs.values():
                try:
                    dimension_doc.close()
                except Exception:
                    pass
        # Revalidate now that real source dimensions are available. In particular,
        # adaptive gap/track constraints and shared-size hints need these dimensions.
        self._update_dynamic_controls()
        self._update_summary_and_apply()
        self._update_sheet_navigation()
        QtCore.QTimer.singleShot(0, self._refresh_fast_preview)
        self._idle_timer.start()

    def _make_card(self, title):
        card = QtWidgets.QFrame()
        card.setStyleSheet(self._CARD)
        layout = QtWidgets.QVBoxLayout(card)
        layout.setContentsMargins(11, 10, 11, 10)
        layout.setSpacing(7)
        label = QtWidgets.QLabel(title)
        label.setStyleSheet(self._SECTION)
        layout.addWidget(label)
        return card, layout

    @staticmethod
    def _make_pt_spin(value=0.0, minimum=0.0, maximum=100000.0):
        spin = _NUpNoWheelDoubleSpinBox()
        spin.setLocale(ENGLISH_LOCALE)
        spin.setRange(float(minimum), float(maximum))
        spin.setDecimals(2)
        spin.setSingleStep(1.0)
        spin.setKeyboardTracking(True)
        spin.setSuffix(" pt")
        spin.setValue(float(value))
        spin.setFixedHeight(34)
        spin.setStyleSheet("""
            QDoubleSpinBox { background:#242424; color:#f0f0f0; border:1px solid #3a3a3a;
                border-radius:6px; padding:4px 8px; selection-background-color:#0078d7; }
            QDoubleSpinBox:focus { border:1px solid #0078d7; }
            QDoubleSpinBox:disabled { color:#666666; background:#1e1e1e; }
        """)
        return spin

    @staticmethod
    def _make_int_spin(value=1, minimum=1, maximum=_NUP_MAX_GRID_DIMENSION):
        spin = _NUpNoWheelSpinBox()
        spin.setLocale(ENGLISH_LOCALE)
        spin.setRange(int(minimum), int(maximum))
        spin.setKeyboardTracking(True)
        spin.setValue(int(value))
        spin.setFixedHeight(34)
        spin.setStyleSheet("""
            QSpinBox { background:#242424; color:#f0f0f0; border:1px solid #3a3a3a;
                border-radius:6px; padding:4px 8px; selection-background-color:#0078d7; }
            QSpinBox:focus { border:1px solid #0078d7; }
        """)
        return spin

    @staticmethod
    def _style_combo(combo):
        combo.setFixedHeight(34)
        combo.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        combo.setStyleSheet("""
            QComboBox { background:#242424; color:#f0f0f0; border:1px solid #3a3a3a;
                border-radius:6px; padding:4px 8px; }
            QComboBox:hover { border:1px solid #555555; }
            QComboBox:focus { border:1px solid #0078d7; }
            QComboBox QAbstractItemView { background:#242424; color:#f0f0f0;
                selection-background-color:#0a3a5c; border:1px solid #3a3a3a; }
        """)

    @staticmethod
    def _set_nup_color_swatch(button, color):
        """Render a compact, clearly outlined color sample button."""
        color = _nup_normalize_hex_color(color, _NUP_DEFAULT_PAGE_COLOR)
        button.setProperty("nupColor", color)
        button.setStyleSheet(
            "QPushButton { background-color:%s; border:1px solid #555555; "
            "border-radius:5px; padding:0; }"
            "QPushButton:hover { border:2px solid #0078d7; }"
            "QPushButton:pressed { border:2px solid #005fa3; }" % color)

    def _choose_nup_color(self, which):
        if which == "page":
            attribute = "_page_color"
            button = self.page_color_btn
            title = "Choose page color"
            default = _NUP_DEFAULT_PAGE_COLOR
        else:
            attribute = "_border_color"
            button = self.border_color_btn
            title = "Choose border color"
            default = _NUP_DEFAULT_BORDER_COLOR
        initial = QtGui.QColor(getattr(self, attribute, default))
        chosen = QtWidgets.QColorDialog.getColor(
            initial, self, title,
            options=QtWidgets.QColorDialog.ColorDialogOption.DontUseNativeDialog)
        if not chosen.isValid():
            return
        color = _nup_normalize_hex_color(chosen.name(), default)
        setattr(self, attribute, color)
        self._set_nup_color_swatch(button, color)
        self._settings_changed()

    def _choose_page_color(self):
        self._choose_nup_color("page")

    def _choose_border_color(self):
        self._choose_nup_color("border")

    def _build_page_card(self):
        card, layout = self._make_card("Page size & color")
        self.page_size_combo = _NUpNoWheelComboBox()
        for name in list(_NUP_PAGE_SIZES) + ["Custom"]:
            self.page_size_combo.addItem(name, name)
        self._style_combo(self.page_size_combo)
        size_color_row = QtWidgets.QHBoxLayout()
        size_color_row.setSpacing(7)
        size_color_row.addWidget(self.page_size_combo, 1)
        self.page_color_btn = QtWidgets.QPushButton()
        self.page_color_btn.setFixedSize(34, 34)
        self.page_color_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.page_color_btn.setToolTip("Page color — click to choose")
        self.page_color_btn.setAccessibleName("Choose page color")
        self._set_nup_color_swatch(self.page_color_btn, self._page_color)
        self.page_color_btn.clicked.connect(self._choose_page_color)
        size_color_row.addWidget(self.page_color_btn)
        layout.addLayout(size_color_row)

        self.custom_size_widget = QtWidgets.QWidget()
        custom = QtWidgets.QGridLayout(self.custom_size_widget)
        custom.setContentsMargins(0, 2, 0, 0)
        custom.setHorizontalSpacing(8)
        custom.setVerticalSpacing(4)
        width_label = QtWidgets.QLabel("Width")
        width_label.setStyleSheet("color:#bdbdbd; background:transparent; border:none;")
        height_label = QtWidgets.QLabel("Height")
        height_label.setStyleSheet("color:#bdbdbd; background:transparent; border:none;")
        self.custom_width_spin = self._make_pt_spin(
            _NUP_PAGE_SIZES["A4 Portrait"][0], 1.0, 100000.0)
        self.custom_height_spin = self._make_pt_spin(
            _NUP_PAGE_SIZES["A4 Portrait"][1], 1.0, 100000.0)
        custom.addWidget(width_label, 0, 0)
        custom.addWidget(height_label, 0, 1)
        custom.addWidget(self.custom_width_spin, 1, 0)
        custom.addWidget(self.custom_height_spin, 1, 1)
        layout.addWidget(self.custom_size_widget)
        self.settings_layout.addWidget(card)

    def _build_grid_card(self):
        card, layout = self._make_card("Grid")
        row = QtWidgets.QHBoxLayout()
        row.setSpacing(8)
        grid_maximum = max(1, min(self._selected_count, _NUP_MAX_GRID_DIMENSION))
        self.columns_spin = self._make_int_spin(min(2, grid_maximum), maximum=grid_maximum)
        self.rows_spin = self._make_int_spin(min(2, grid_maximum), maximum=grid_maximum)
        self.columns_spin.setToolTip(
            "No fixed 12-column limit; each grid dimension can use up to the number of selected pages.")
        self.rows_spin.setToolTip(
            "No fixed 12-row limit; each grid dimension can use up to the number of selected pages.")
        for label_text, spin in (("Columns", self.columns_spin),
                                 ("Rows", self.rows_spin)):
            column = QtWidgets.QVBoxLayout()
            label = QtWidgets.QLabel(label_text)
            label.setStyleSheet("color:#bdbdbd; background:transparent; border:none;")
            column.addWidget(label)
            column.addWidget(spin)
            row.addLayout(column, 1)
        separator = QtWidgets.QLabel("×")
        separator.setStyleSheet("color:#aaaaaa; background:transparent; border:none; font-size:13pt;")
        row.insertWidget(1, separator)
        layout.addLayout(row)
        self.capacity_lbl = QtWidgets.QLabel("Capacity: 4 pages per sheet")
        self.capacity_lbl.setStyleSheet("color:#999999; background:transparent; border:none; font-size:9pt;")
        layout.addWidget(self.capacity_lbl)
        self.settings_layout.addWidget(card)

    def _build_area_card(self):
        card, layout = self._make_card("Sizing mode")
        mode_header = QtWidgets.QHBoxLayout()
        mode_header.setSpacing(8)
        self.page_area_combo = _NUpNoWheelComboBox()
        for label, value in (
                ("Equal-size cells", "consistent_both"),
                ("Same page height", "consistent_height"),
                ("Same page width", "consistent_width"),
                ("Adaptive column widths", "auto_width"),
                ("Adaptive row heights", "auto_height"),
                ("Uniform scale", "uniform_scale")):
            self.page_area_combo.addItem(label, value)
        self._style_combo(self.page_area_combo)
        mode_header.addWidget(self.page_area_combo, 1)
        self.learn_more_btn = QtWidgets.QPushButton("Learn more")
        self.learn_more_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.learn_more_btn.setToolTip("Learn what each N-up option does")
        self.learn_more_btn.setStyleSheet("""
            QPushButton { background:#242424; color:#8ecbff; border:1px solid #3a3a3a;
                border-radius:6px; padding:6px 10px; font-weight:600; }
            QPushButton:hover { background:#303030; border-color:#0078d7; }
            QPushButton:pressed { background:#1d1d1d; }
        """)
        self.learn_more_btn.clicked.connect(self._show_learn_more)
        mode_header.addWidget(self.learn_more_btn)
        layout.addLayout(mode_header)

        self.area_description_lbl = QtWidgets.QLabel("")
        self.area_description_lbl.setWordWrap(True)
        self.area_description_lbl.setStyleSheet(
            "color:#999999; background:transparent; border:none; font-size:8.5pt;")
        layout.addWidget(self.area_description_lbl)

        self.consistent_check = QtWidgets.QCheckBox("Keep sizing consistent across all sheets")
        self.consistent_check.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.consistent_check.setStyleSheet("QCheckBox { color:#d8d8d8; spacing:8px; }")
        self.consistent_check.setToolTip(
            "Share the relevant height, width, or adaptive tracks across output sheets.")
        layout.addWidget(self.consistent_check)

        self.page_order_combo = _NUpNoWheelComboBox()
        self.page_order_combo.addItem("Left to right", "row")
        self.page_order_combo.addItem("Right to left", "row_reverse")
        self.page_order_combo.addItem("Top to bottom", "column")
        self.page_order_combo.addItem("Bottom to top", "column_reverse")
        self._style_combo(self.page_order_combo)
        self.page_order_combo.setToolTip(
            "Choose the direction in which selected pages fill the grid.")
        order_label = QtWidgets.QLabel("Page order")
        order_label.setStyleSheet("color:#bdbdbd; background:transparent; border:none;")
        layout.addWidget(order_label)
        layout.addWidget(self.page_order_combo)

        border_row = QtWidgets.QHBoxLayout()
        border_row.setSpacing(8)
        self.borders_check = QtWidgets.QCheckBox("Page borders")
        self.borders_check.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.borders_check.setStyleSheet("QCheckBox { color:#d8d8d8; spacing:8px; }")
        border_row.addWidget(self.borders_check)
        self.border_slider = _NUpNoWheelSlider(QtCore.Qt.Orientation.Horizontal)
        self.border_slider.setRange(1, 10)
        self.border_slider.setSingleStep(1)
        self.border_slider.setPageStep(1)
        self.border_slider.setValue(1)
        self.border_slider.setToolTip("Page border thickness: 1–10 pt")
        self.border_slider.setStyleSheet("""
            QSlider { background:transparent; border:none; padding:0; }
            QSlider::groove:horizontal { height:4px; margin:0; background:#3a3a3a;
                border:none; border-radius:2px; }
            QSlider::sub-page:horizontal { background:#0078d7; border:none;
                border-radius:2px; }
            QSlider::add-page:horizontal { background:#3a3a3a; border:none;
                border-radius:2px; }
            QSlider::handle:horizontal { background:#d8d8d8; border:1px solid #555555;
                width:14px; margin:-5px 0; border-radius:7px; }
            QSlider::handle:horizontal:hover { background:#ffffff; }
            QSlider:disabled { background:transparent; }
        """)
        border_row.addWidget(self.border_slider, 1)
        self.border_value_lbl = QtWidgets.QLabel("1 pt")
        self.border_value_lbl.setMinimumWidth(38)
        self.border_value_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignRight | QtCore.Qt.AlignmentFlag.AlignVCenter)
        self.border_value_lbl.setStyleSheet(
            "color:#bdbdbd; background:transparent; border:none;")
        border_row.addWidget(self.border_value_lbl)
        self.border_color_btn = QtWidgets.QPushButton()
        self.border_color_btn.setFixedSize(30, 30)
        self.border_color_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.border_color_btn.setToolTip("Border color — click to choose")
        self.border_color_btn.setAccessibleName("Choose border color")
        self._set_nup_color_swatch(self.border_color_btn, self._border_color)
        self.border_color_btn.clicked.connect(self._choose_border_color)
        border_row.addWidget(self.border_color_btn)
        layout.addLayout(border_row)
        self.settings_layout.addWidget(card)

        fit_card, fit_layout = self._make_card("Fitting options")
        self.never_enlarge_check = QtWidgets.QCheckBox("Never enlarge pages")
        self.never_enlarge_check.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.never_enlarge_check.setToolTip(
            "Reduce pages when needed, but never scale their edited size above 100%.")
        self.never_enlarge_check.setStyleSheet("QCheckBox { color:#d8d8d8; spacing:8px; }")
        fit_layout.addWidget(self.never_enlarge_check)
        self.auto_rotate_check = QtWidgets.QCheckBox("Automatically rotate pages to improve fit")
        self.auto_rotate_check.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.auto_rotate_check.setToolTip(
            "Permit a 90° output-only rotation when it improves fit in the grid.")
        self.auto_rotate_check.setStyleSheet("QCheckBox { color:#d8d8d8; spacing:8px; }")
        fit_layout.addWidget(self.auto_rotate_check)
        self.settings_layout.addWidget(fit_card)

    def _build_spacing_card(self):
        card, layout = self._make_card("Margins & gaps")
        margins_grid = QtWidgets.QGridLayout()
        margins_grid.setHorizontalSpacing(8)
        margins_grid.setVerticalSpacing(6)
        self.margin_spins = {}
        for index, name in enumerate(("top", "bottom", "left", "right")):
            label = QtWidgets.QLabel(name.capitalize())
            label.setStyleSheet("color:#bdbdbd; background:transparent; border:none;")
            spin = self._make_pt_spin(18.0)
            self.margin_spins[name] = spin
            margins_grid.addWidget(label, (index // 2) * 2, index % 2)
            margins_grid.addWidget(spin, (index // 2) * 2 + 1, index % 2)
        layout.addLayout(margins_grid)

        gap_grid = QtWidgets.QGridLayout()
        gap_grid.setHorizontalSpacing(8)
        gap_grid.setVerticalSpacing(4)
        self.horizontal_gap_spin = self._make_pt_spin(8.0)
        self.vertical_gap_spin = self._make_pt_spin(8.0)
        for col, (label_text, spin) in enumerate((
                ("Horizontal gap", self.horizontal_gap_spin),
                ("Vertical gap", self.vertical_gap_spin))):
            label = QtWidgets.QLabel(label_text)
            label.setStyleSheet("color:#bdbdbd; background:transparent; border:none;")
            gap_grid.addWidget(label, 0, col)
            gap_grid.addWidget(spin, 1, col)
        layout.addLayout(gap_grid)
        self.settings_layout.addWidget(card)

    def _build_interactive_content_warning(self):
        """Show the permanent PDF-interactivity warning at the bottom of settings."""
        warning = QtWidgets.QFrame()
        warning.setObjectName("nupInteractiveWarning")
        warning.setStyleSheet(
            "QFrame { background:#2a2418; border:1px solid #594b2d; "
            "border-radius:7px; }"
            "QLabel { background:transparent; border:none; }"
        )
        row = QtWidgets.QHBoxLayout(warning)
        row.setContentsMargins(11, 8, 11, 8)
        row.setSpacing(9)
        icon = QtWidgets.QLabel("⚠")
        icon.setAlignment(QtCore.Qt.AlignmentFlag.AlignTop | QtCore.Qt.AlignmentFlag.AlignHCenter)
        icon.setFixedWidth(20)
        icon.setStyleSheet("color:#f0c674; font-size:15pt; font-weight:700;")
        row.addWidget(icon)
        message = QtWidgets.QLabel(
            "<b>Interactive PDF elements are not preserved.</b><br>"
            "<span style='font-weight:400;'>Links, annotations/comments and "
            "interactive form fields are not carried into the composed N-up PDF; "
            "only visible page content is embedded.</span>"
        )
        message.setWordWrap(True)
        message.setStyleSheet("color:#d3a54c; font-size:8.8pt; font-weight:700;")
        row.addWidget(message, 1)
        self.settings_layout.addWidget(warning)

    def _load_initial_controls(self):
        cfg = self._initial_config
        size_name = str(cfg.get("page_size_name") or "A4 Portrait")
        size_index = self.page_size_combo.findData(size_name)
        if size_index < 0:
            size_index = self.page_size_combo.findData("Custom")
            self.custom_width_spin.setValue(float(cfg.get("page_width_pt", 595.2755905511812)))
            self.custom_height_spin.setValue(float(cfg.get("page_height_pt", 841.8897637795276)))
        self.page_size_combo.setCurrentIndex(max(0, size_index))
        if size_name == "Custom" or size_index == self.page_size_combo.findData("Custom"):
            self.custom_width_spin.setValue(float(cfg.get("page_width_pt", 595.2755905511812)))
            self.custom_height_spin.setValue(float(cfg.get("page_height_pt", 841.8897637795276)))
        self.columns_spin.setValue(int(cfg.get("columns", 2)))
        self.rows_spin.setValue(int(cfg.get("rows", 2)))
        area_index = self.page_area_combo.findData(_nup_layout_mode_from_config(cfg))
        self.page_area_combo.setCurrentIndex(max(0, area_index))
        self.consistent_check.setChecked(bool(cfg.get("consistent_across_sheets", False)))
        self.never_enlarge_check.setChecked(bool(cfg.get("never_enlarge", False)))
        self.auto_rotate_check.setChecked(bool(cfg.get("auto_rotate", False)))
        order_index = self.page_order_combo.findData(cfg.get("page_order", "row"))
        self.page_order_combo.setCurrentIndex(max(0, order_index))
        margins = cfg.get("margins") or {}
        for name, spin in self.margin_spins.items():
            spin.setValue(float(margins.get(name, 18.0)))
        self.horizontal_gap_spin.setValue(float(cfg.get("horizontal_gap_pt", 8.0)))
        self.vertical_gap_spin.setValue(float(cfg.get("vertical_gap_pt", 8.0)))
        self.borders_check.setChecked(bool(cfg.get("borders", True)))
        self.border_slider.setValue(int(round(float(
            cfg.get("border_thickness_pt", _NUP_BORDER_THICKNESS_PT)))))
        self._page_color = _nup_normalize_hex_color(
            cfg.get("page_color"), _NUP_DEFAULT_PAGE_COLOR)
        self._border_color = _nup_normalize_hex_color(
            cfg.get("border_color"), _NUP_DEFAULT_BORDER_COLOR)
        self._set_nup_color_swatch(self.page_color_btn, self._page_color)
        self._set_nup_color_swatch(self.border_color_btn, self._border_color)

    def _connect_control_signals(self):
        controls = [self.page_size_combo, self.custom_width_spin,
                    self.custom_height_spin, self.columns_spin, self.rows_spin,
                    self.page_area_combo, self.consistent_check,
                    self.never_enlarge_check, self.auto_rotate_check,
                    self.page_order_combo, self.horizontal_gap_spin,
                    self.vertical_gap_spin, self.borders_check, self.border_slider]
        controls.extend(self.margin_spins.values())
        for control in controls:
            signal = (control.currentIndexChanged if isinstance(control, QtWidgets.QComboBox)
                      else control.valueChanged if isinstance(
                          control, (QtWidgets.QSpinBox, QtWidgets.QDoubleSpinBox,
                                    QtWidgets.QSlider))
                      else control.toggled)
            signal.connect(self._settings_changed)

    def _read_config(self):
        size_name = self.page_size_combo.currentData()
        if size_name == "Custom":
            page_width = self.custom_width_spin.value()
            page_height = self.custom_height_spin.value()
        else:
            page_width, page_height = _NUP_PAGE_SIZES.get(
                str(size_name), _NUP_PAGE_SIZES["A4 Portrait"])
        return {
            "page_size_name": str(size_name or "A4 Portrait"),
            "page_width_pt": float(page_width),
            "page_height_pt": float(page_height),
            "columns": int(self.columns_spin.value()),
            "rows": int(self.rows_spin.value()),
            "margins": {name: float(spin.value())
                        for name, spin in self.margin_spins.items()},
            "horizontal_gap_pt": float(self.horizontal_gap_spin.value()),
            "vertical_gap_pt": float(self.vertical_gap_spin.value()),
            "borders": bool(self.borders_check.isChecked()),
            "border_thickness_pt": float(self.border_slider.value()),
            "page_color": self._page_color,
            "border_color": self._border_color,
            "layout_mode": str(self.page_area_combo.currentData() or "consistent_both"),
            "consistent_across_sheets": bool(self.consistent_check.isChecked()),
            "never_enlarge": bool(self.never_enlarge_check.isChecked()),
            "auto_rotate": bool(self.auto_rotate_check.isChecked()),
            "page_order": str(self.page_order_combo.currentData() or "row"),
        }

    def _update_dynamic_controls(self):
        custom = self.page_size_combo.currentData() == "Custom"
        self.custom_size_widget.setVisible(custom)
        mode = str(self.page_area_combo.currentData() or "consistent_both")
        descriptions = {
            "consistent_both": "Equal-size cells: pages are fitted and centered in identical cells.",
            "consistent_height": "Same page height: pages on each sheet share a rendered height.",
            "consistent_width": "Same page width: pages on each sheet share a rendered width.",
            "auto_width": "Adaptive column widths: columns adapt to the pages assigned to them.",
            "auto_height": "Adaptive row heights: rows adapt to the pages assigned to them.",
            "uniform_scale": "Uniform scale: all selected pages use one common scale factor.",
        }
        description = (
            descriptions.get(mode, descriptions["consistent_both"])
            + " Page proportions are always preserved; pages are never stretched or cropped.")
        self.area_description_lbl.setText(description)

        labels = {
            "consistent_height": "Use the same page height across all sheets",
            "consistent_width": "Use the same page width across all sheets",
            "auto_width": "Keep column widths consistent across sheets",
            "auto_height": "Keep row heights consistent across sheets",
        }
        consistency_applicable = mode in labels
        self.consistent_check.setText(labels.get(
            mode, "Keep sizing consistent across all sheets"))
        multiple_sheets = self._output_sheet_count() > 1
        self.consistent_check.setVisible(consistency_applicable)
        self.consistent_check.setEnabled(consistency_applicable and multiple_sheets)
        self.consistent_check.setToolTip(
            "Share the relevant size or adaptive tracks across the complete output document."
            if consistency_applicable else "This mode is already consistent by definition.")

        self.border_value_lbl.setText(f"{self.border_slider.value()} pt")
        self.border_slider.setEnabled(self.borders_check.isChecked())
        self.border_value_lbl.setEnabled(self.borders_check.isChecked())
        self.border_color_btn.setEnabled(self.borders_check.isChecked())

