        _frame, card = self._card(controls_layout, "Appearance")
        opacity_row = QtWidgets.QHBoxLayout()
        opacity_row.addWidget(QtWidgets.QLabel("Opacity"))
        self.wm_opacity = self._blue_slider(0, 100, 25)
        self.wm_opacity_value = QtWidgets.QLabel("25%")
        self.wm_opacity_value.setMinimumWidth(40)
