        self.wm_layer = QtWidgets.QComboBox()
        self.wm_layer.addItem("In front of content", "foreground")
        self.wm_layer.addItem("Behind content", "background")
        self.wm_layer.currentIndexChanged.connect(self._watermark_changed)
