    def _toggle_multiselect(self):
        self.multisel_btn.setChecked(not self.multisel_btn.isChecked())

    def _select_all(self):
        if self.grid.count() == 0:
            return
        self.grid.blockSignals(True)
        try:
            old_mode = self.grid.selectionMode()
            self.grid.setSelectionMode(
                QtWidgets.QAbstractItemView.SelectionMode.MultiSelection)
            for i in range(self.grid.count()):
                it = self.grid.item(i)
                if it is not None:
                    it.setSelected(True)
            if self.multisel_btn.isChecked() or self._ctrl_held:
                self.grid.setSelectionMode(old_mode)
            else:
                self.grid.setSelectionMode(
                    QtWidgets.QAbstractItemView.SelectionMode.SingleSelection)
        finally:
            self.grid.blockSignals(False)
        self._on_selection_changed()
        self.grid.viewport().update()

    def _deselect_all(self):
        self.grid.clearSelection()

    def _select_page_range(self):
        total = self.grid.count()
        if total < 2:
            return

        dialog = PageRangeDialog(total, self)
        if dialog.exec() != QtWidgets.QDialog.DialogCode.Accepted:
            return
        if not dialog.page_range:
            return

        start_page, end_page = dialog.page_range
        start_row = max(0, start_page - 1)
        end_row = min(total, end_page)

        self.grid.blockSignals(True)
        try:
            old_mode = self.grid.selectionMode()
            self.grid.setSelectionMode(
                QtWidgets.QAbstractItemView.SelectionMode.MultiSelection)
            self.grid.clearSelection()
            for row in range(start_row, end_row):
                item = self.grid.item(row)
                if item is not None:
                    item.setSelected(True)
            self.grid.setSelectionMode(old_mode)
        finally:
            self.grid.blockSignals(False)

        self._on_selection_changed()
        first_item = self.grid.item(start_row)
        if first_item is not None:
            self.grid.scrollToItem(
                first_item, QtWidgets.QAbstractItemView.ScrollHint.PositionAtCenter)
        self.grid.viewport().update()

    def _open_full_pdf(self):
        if self._blank_canvas or not self.pdf_path or not os.path.exists(self.pdf_path):
            QtWidgets.QMessageBox.warning(
                self, "Open Failed", f"File not found:\n{self.pdf_path}")
            return
        controller = _find_pdf_security_controller(self)
        if controller is not None and not controller._ensure_pdf_unlocked_for_use(
                self.pdf_path, context="opening the full PDF"):
            return
        try:
            dlg = FullPdfViewer(self.pdf_path, page_idx=0, parent=self)
        except Exception as e:
            QtWidgets.QMessageBox.critical(
                self, "Open Failed", f"Could not open PDF:\n{e}")
            return
        dlg.exec()

    def _cleanup_memory(self):
        try:
            self._clipboard = []
            self._cut_entries = []
            self._cut_selection_uids = set()
            self._pristine_cache.clear()
            self._thumb_cache.clear()
            self._disk_thumbnail_paths.clear()
            for job_dir in list(self._disk_thumbnail_job_dirs):
                _cleanup_thumbnail_disk_job_dir(job_dir)
            self._disk_thumbnail_job_dirs.clear()
            self._thumbnail_resources_dirty = False
            # The editor is ending, so temporary image-backed PDFs can no longer
            # be reached by the current document or any undo/redo state.
            for image_pdf in list(self._generated_image_page_pdfs):
                try:
                    if image_pdf and os.path.isfile(image_pdf):
                        os.remove(image_pdf)
                except Exception:
                    pass
            self._generated_image_page_pdfs.clear()
            self._entries = []
            if self._active_bridge is not None:
                bridge = self._active_bridge
                _stop_qthread(
                    bridge,
                    stop_callback=getattr(bridge, "shutdown", None) or getattr(bridge, "request_cancel", None),
                    timeout_ms=5000,
                    force_wait_ms=2000,
                )
                try:
                    if not bridge.isRunning():
                        self._active_bridge = None
                except Exception:
                    self._active_bridge = None
        except Exception:
            pass

    def done(self, result):
        self._cleanup_memory()
        super().done(result)

    def closeEvent(self, event):
        if self._allow_close_without_prompt:
            self._allow_close_without_prompt = False
            self._cleanup_memory()
            event.accept()
            return
        if self._confirm_discard_changes():
            self._allow_close_without_prompt = True
            self._cleanup_memory()
            event.accept()
        else:
            event.ignore()
    def eventFilter(self, obj, event):
        if event.type() == QtCore.QEvent.Type.KeyPress:
            key = event.key()
            mods = event.modifiers()
            if key == QtCore.Qt.Key.Key_Control:
                self._ctrl_held = True
                self._apply_selection_mode()
                return True
            if key == QtCore.Qt.Key.Key_Delete:
                if self.delete_btn.isEnabled():
                    self._delete_selected()
                    return True
            if mods & QtCore.Qt.KeyboardModifier.ControlModifier:
                if key == QtCore.Qt.Key.Key_C:
                    self._copy_selected()
                    return True
                if key == QtCore.Qt.Key.Key_V:
                    self._paste_copied()
                    return True
        elif event.type() == QtCore.QEvent.Type.KeyRelease:
            if event.key() == QtCore.Qt.Key.Key_Control:
                self._ctrl_held = False
                self._apply_selection_mode()
                return True
        return super().eventFilter(obj, event)

    def _on_multisel_toggled(self, checked):
        self._apply_selection_mode()

    def _apply_selection_mode(self):
        active = self.multisel_btn.isChecked() or self._ctrl_held
        if active:
            self.grid.setSelectionMode(
                QtWidgets.QAbstractItemView.SelectionMode.MultiSelection)
        else:
            self.grid.setSelectionMode(
                QtWidgets.QAbstractItemView.SelectionMode.SingleSelection)

    def showEvent(self, event):
        super().showEvent(event)
        if self._blank_canvas:
            return
        if not self._has_loaded_once:
            self._has_loaded_once = True
            QtCore.QTimer.singleShot(50, self._reload)

    def _source_page_aspect_ratio(self, source_pdf, page_idx):
        """Return the original source page width/height ratio, cached per page."""
        key = (os.path.abspath(str(source_pdf)), int(page_idx))
        cached = self._page_aspect_ratio_cache.get(key)
        if cached is not None:
            return cached
        ratio = None
        try:
            with fitz.open(source_pdf) as doc:
                rect = doc.load_page(int(page_idx)).rect
                width = float(rect.width)
                height = float(rect.height)
                if width > 0 and height > 0:
                    ratio = width / height
        except Exception:
            ratio = None
        if ratio is not None and math.isfinite(ratio) and ratio > 0:
            ratio = max(0.08, min(12.0, ratio))
            self._page_aspect_ratio_cache[key] = float(ratio)
            return float(ratio)
        return None

    def _recalculate_grid_page_aspect_ratio(self):
        """Set the grid ratio from the most common aspect ratio of live pages."""
        ratios = []
        for row in range(self.grid.count()):
            item = self.grid.item(row)
            if item is None:
                continue
            entry = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
            source_pdf = entry.get('source_pdf')
            page_idx = entry.get('original_idx')
            if source_pdf is None or page_idx is None:
                continue
            ratio = entry.get('stretch_ratio')
            if ratio is None:
                ratio = entry.get('page_aspect_ratio')
            try:
                ratio = float(ratio) if ratio is not None else None
            except Exception:
                ratio = None
            if ratio is None or not math.isfinite(ratio) or ratio <= 0:
                ratio = self._source_page_aspect_ratio(source_pdf, page_idx)
                if ratio is not None:
                    entry['page_aspect_ratio'] = float(ratio)
                    item.setData(QtCore.Qt.ItemDataRole.UserRole, entry)
            if ratio is not None and math.isfinite(ratio) and ratio > 0:
                ratios.append(max(0.08, min(12.0, float(ratio))))

        if not ratios:
            dominant_ratio = 1.0
        elif len(ratios) == 1:
            dominant_ratio = ratios[0]
        else:
            # Group equivalent page shapes by aspect ratio, not exact point dimensions.
            groups = collections.Counter(round(r, 3) for r in ratios)
            highest = max(groups.values())
            winners = [ratio_key for ratio_key, count in groups.items()
                       if count == highest]
            dominant_ratio = float(winners[0]) if len(winners) == 1 else 1.0

        try:
            current_ratio = self.grid.page_aspect_ratio()
        except Exception:
            current_ratio = 1.0
        if abs(float(current_ratio) - float(dominant_ratio)) > 0.0005:
            self.grid.set_page_aspect_ratio(dominant_ratio)
        return dominant_ratio

    def _prepare_thumbnail_load_settings(self, pdf_path, total, prog):
        thumb_cfg = APP_SETTINGS["multiprocessing"]["thumbnail_generation"]
        advanced_cfg = APP_SETTINGS.get("advanced", {})
        settings = {
            "processes": int(thumb_cfg["processes"]),
            "pages_threshold": int(thumb_cfg["pages_threshold"]),
            "thumbnail_dpi": int(advanced_cfg.get("thumbnail_dpi", DEFAULT_THUMBNAIL_DPI)),
            "generate_thumbnails": bool(self._thumbnails_enabled),
            "use_memory": _get_use_memory_setting(),
            "use_disk": False,
        }

        # Off is a hard storage mode: do not run a RAM probe at all.
        if settings["use_memory"] == "off":
            settings["use_disk"] = True
            prog.set_storage_notice("Using storage (slower). Check settings.")
            return settings

        # A one-page thumbnail never creates the multi-page in-memory accumulation
        # that this safety gate is designed to prevent. Treat it as safe without probing.
        if int(total) <= 1:
            prog.append_log("Single-page PDF: RAM safety check skipped.", "info")
            return settings

        while settings["use_memory"] in {"auto", "on"}:
            prog.start_infinite("Safety Check...")
            QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)
            if prog.is_cancel_requested():
                raise _ThumbnailLoadCancelled()

            prog.append_log(
                f"Safety Check: evaluating RAM safety for {total} thumbnail(s) "
                f"at {settings['thumbnail_dpi']} DPI...", "info")
            safety = _estimate_thumbnail_memory_safety(
                pdf_path, total, settings["thumbnail_dpi"])
            prog.append_log(
                _thumbnail_sample_log(safety, settings["thumbnail_dpi"], total),
                "info")

            if safety.get("safe"):
                prog.append_log("Safety Check passed.", "success")
                settings["use_disk"] = False
                prog.set_storage_notice("")
                break

            # Auto silently falls back to storage. Only an explicit On setting
            # is allowed to interrupt the workflow with the decision dialog.
            if settings["use_memory"] == "auto":
                settings["use_disk"] = True
                prog.append_log(
                    "RAM safety check failed; Auto mode is switching to temporary storage.",
                    "warning")
                prog.set_storage_notice("Using storage (slower). Check settings.")
                break

            dlg = MemorySafetyDialog(
                operation_title="Thumbnail generation",
                detail_text=(
                    "The current thumbnail workload is estimated to exceed the safe RAM budget. "
                    "Lower the thumbnail quality or choose another memory mode to continue."
                ),
                work_label="Thumbnail pages",
                work_count=total,
                dpi_label="Thumbnail quality:",
                dpi_options=THUMBNAIL_DPI_OPTIONS,
                current_dpi=settings["thumbnail_dpi"],
                use_memory=settings["use_memory"],
                safety_info=safety,
                parent=self,
                generate_thumbnails=settings["generate_thumbnails"],
            )
            if dlg.exec() != QtWidgets.QDialog.DialogCode.Accepted:
                prog.append_log("Thumbnail loading cancelled by user.", "warning")
                raise _ThumbnailLoadCancelled()

            selected = dlg.get_settings()
            settings["thumbnail_dpi"] = int(selected["dpi"])
            settings["generate_thumbnails"] = bool(
                selected.get("generate_thumbnails", settings["generate_thumbnails"]))
            self._thumbnails_enabled = settings["generate_thumbnails"]
            settings["use_memory"] = str(selected["use_memory"]).strip().lower()
            if settings["use_memory"] not in {"auto", "on", "off"}:
                settings["use_memory"] = "auto"

            # Persist explicit choices made in the emergency dialog. This is
            # intentionally not a side-effect of ordinary Settings edits.
            try:
                new_settings = _get_app_settings_snapshot()
                new_settings["advanced"]["use_memory"] = settings["use_memory"]
                new_settings["advanced"]["thumbnail_dpi"] = settings["thumbnail_dpi"]
                new_settings["advanced"]["generate_thumbnails"] = settings["generate_thumbnails"]
                _save_application_settings(new_settings)
                prog.append_log("Memory safety choice saved to settings.", "info")
            except Exception as exc:
                prog.append_log(
                    f"Could not persist memory safety choice: {exc}", "warning")

            if not settings["generate_thumbnails"]:
                settings["use_disk"] = False
                prog.set_storage_notice("")
                prog.append_log(
                    "Thumbnail generation turned off; preparing pages without previews.",
                    "info")
                return settings

            if settings["use_memory"] == "off":
                settings["use_disk"] = True
                prog.append_log(
                    "Off mode selected; thumbnails will use temporary storage.",
                    "info")
                prog.set_storage_notice("Using storage (slower). Check settings.")
                break

            if settings["use_memory"] == "auto":
                # Auto always means "try RAM first". The user may have lowered DPI in
                # the dialog, so rerun the exact same safety probe before falling back
                # to storage.
                prog.append_log(
                    f"Auto mode selected; rechecking RAM safety at "
                    f"{settings['thumbnail_dpi']} DPI...",
                    "info")
                continue

            prog.append_log(
                f"Rechecking RAM safety at {settings['thumbnail_dpi']} DPI...",
                "info")

        return settings


    def _build_entries_without_thumbnails(
        self, pdf_path, total, page_aspect_ratios, prog, base_label, check_cancel
    ):
        """Create page entries with blank preview tiles and no raster rendering."""
        self._loaded_thumbnail_dpi = None
        self._loaded_thumbnail_use_disk = False
        out = []
        cache_source = os.path.abspath(str(pdf_path))
        for i in range(total):
            check_cancel()
            ratio = page_aspect_ratios[i] if i < len(page_aspect_ratios) else None
            if ratio is not None and math.isfinite(ratio) and ratio > 0:
                ratio = max(0.08, min(12.0, float(ratio)))
                self._page_aspect_ratio_cache[(cache_source, i)] = ratio
            else:
                ratio = None
            entry = {
                'source_pdf': pdf_path,
                'original_idx': i,
                'rotation': 0,
                'crop': None,
                'flip_h': False,
                'flip_v': False,
                'invert_colors': False,
                'filter_config': _neutral_filter_config(),
                'ocr_done': False,
                'page_aspect_ratio': ratio,
                'uid': self._next_uid,
            }
            self._next_uid += 1
            out.append((entry, None))
            if i == 0 or (i + 1) % 100 == 0 or i == total - 1:
                prog.set_progress(i + 1, max(1, total), base_label)
                QtWidgets.QApplication.processEvents(
                    QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 10)
                check_cancel()
        prog.append_log(
            f"Prepared {len(out)} page item(s) without thumbnails.", "success")
        return out

    def _render_pdf_pages_to_entries(self, pdf_path, prog, base_label="Loading"):
        def check_cancel():
            if prog.is_cancel_requested():
                raise _ThumbnailLoadCancelled()

        check_cancel()
        try:
            with fitz.open(pdf_path) as doc:
                total = doc.page_count
                dimensions = []
                page_aspect_ratios = []
                for idx in range(total):
                    if (not self._thumbnails_enabled
                            and (idx == 0 or (idx + 1) % 64 == 0)):
                        # Keep the no-preview metadata pass responsive/cancellable
                        # even for PDFs with very large page trees.
                        check_cancel()
                        QtWidgets.QApplication.processEvents(
                            QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 10)
                        check_cancel()
                    try:
                        rect = doc.load_page(idx).rect
                        width = float(rect.width)
                        height = float(rect.height)
                        dimensions.append((round(width, 2), round(height, 2)))
                        page_aspect_ratios.append(
                            width / height if width > 0 and height > 0 else None)
                    except Exception:
                        page_aspect_ratios.append(None)
        except Exception as e:
            prog.append_log(f"Cannot open {pdf_path}: {e}", "error")
            return []

        # Establish an initial ratio only for an empty grid. When adding pages to
        # an existing editor, the incoming PDF must not override the ratio of the
        # pages already present. The complete live grid is re-evaluated after insert.
        if self.grid.count() == 0:
            if dimensions:
                ratio_counts = collections.Counter(
                    round(w / max(1e-9, h), 3) for w, h in dimensions
                )
                highest = max(ratio_counts.values())
                winners = [ratio_key for ratio_key, count in ratio_counts.items()
                           if count == highest]
                dominant_ratio = float(winners[0]) if (total == 1 or len(winners) == 1) else 1.0
            else:
                dominant_ratio = 1.0
            self.grid.set_page_aspect_ratio(dominant_ratio)
            prog.append_log(f"Thumbnail grid ratio: {dominant_ratio:.3f}:1", "info")

        if not self._thumbnails_enabled:
            return self._build_entries_without_thumbnails(
                pdf_path, total, page_aspect_ratios, prog, base_label, check_cancel
            )

        settings = self._prepare_thumbnail_load_settings(pdf_path, total, prog)
        if not self._thumbnails_enabled:
            return self._build_entries_without_thumbnails(
                pdf_path, total, page_aspect_ratios, prog, base_label, check_cancel
            )
        thumb_processes = int(settings["processes"])
        threshold = int(settings["pages_threshold"])
        thumbnail_dpi = int(settings["thumbnail_dpi"])
        use_disk = bool(settings["use_disk"])
        if use_disk:
            prog.set_storage_notice("Using storage (slower). Check settings.")
        else:
            prog.set_storage_notice("")
        # Snapshot the exact thumbnail source used for this edit session.
        # Reset and history restoration reuse this snapshot rather than invoking
        # another full thumbnail load.
        self._loaded_thumbnail_dpi = thumbnail_dpi
        self._loaded_thumbnail_use_disk = use_disk
        actual_workers = _effective_worker_count(total, thumb_processes)
        use_mp = total > threshold and actual_workers > 1

        prog.append_log(
            f"Opening {os.path.basename(pdf_path)} — {total} page(s)...", "info")
        prog.set_progress(0, max(1, total), base_label)
        QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)
        check_cancel()

        disk_job_dir = None
        if use_disk:
            disk_job_dir = _make_thumbnail_disk_job_dir()
            self._disk_thumbnail_job_dirs.add(disk_job_dir)
            self._thumbnail_resources_dirty = True
            prog.append_log(
                f"Thumbnail storage: disk (temp/thumbnail/{os.path.basename(disk_job_dir)})",
                "info")

        if use_mp:
            mode_word = "disk" if use_disk else "memory"
            prog.append_log(
                f"Thumbnail loading mode: MP — {actual_workers} process(es) "
                f"(configured {thumb_processes}, {thumbnail_dpi} DPI, {mode_word}).", "info")

            chunks = _build_page_ranges(total, actual_workers)
            page_chunks = [list(range(start, end + 1)) for start, end in chunks]
            for worker_index, page_indices in enumerate(page_chunks):
                if page_indices:
                    prog.append_log(
                        f"  Worker {worker_index + 1}: pages "
                        f"{page_indices[0] + 1}–{page_indices[-1] + 1}", "info")

            ctx = multiprocessing.get_context("spawn")
            result_queue = ctx.Queue(maxsize=max(10, actual_workers * 2))
            processes = []
            results = {}
            completed_workers = set()
            worker_errors = []

            for worker_index, page_indices in enumerate(page_chunks):
                process = ctx.Process(
                    target=_render_thumbnail_pages_worker,
                    args=(pdf_path, page_indices, thumbnail_dpi,
                          result_queue, worker_index, disk_job_dir if use_disk else None))
                processes.append(process)

            for process in processes:
                process.start()

            received_pages = 0
            last_logged_page = 0
            try:
                while len(completed_workers) < actual_workers:
                    check_cancel()
                    try:
                        message = result_queue.get(timeout=0.20)
                    except queue.Empty:
                        if processes and all(not p.is_alive() for p in processes):
                            break
                        QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)
                        check_cancel()
                        continue

                    kind, worker_index, page_idx, width, height, payload, error = message
                    if kind == "done":
                        completed_workers.add(worker_index)
                        continue
                    if kind not in ("memory", "disk", "page"):
                        continue

                    received_pages += 1
                    if error or not payload or width <= 0 or height <= 0:
                        worker_errors.append(
                            f"Page {page_idx + 1}: {error or 'empty thumbnail result'}")
                    elif kind == "disk":
                        results[page_idx] = (width, height, payload)
                    else:
                        results[page_idx] = (width, height, payload)

                    prog.set_progress(received_pages, max(1, total), base_label)
                    if (received_pages == 1
                            or received_pages - last_logged_page >= 10
                            or received_pages == total):
                        prog.append_log(
                            f"  Rendered {received_pages}/{total} thumbnails",
                            "info")
                        last_logged_page = received_pages
                    QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)
                    check_cancel()
            finally:
                for process in processes:
                    process.join(timeout=2.0)
                for process in processes:
                    if process.is_alive():
                        try:
                            process.terminate()
                        except Exception:
                            pass
                for process_index, process in enumerate(processes):
                    try:
                        process.join(timeout=1.0)
                    except Exception:
                        pass
                    if process.exitcode not in (None, 0):
                        worker_errors.append(
                            f"Thumbnail worker {process_index + 1} exited with code {process.exitcode}.")
                try:
                    result_queue.close()
                    result_queue.join_thread()
                except Exception:
                    pass

            check_cancel()
            prog.start_infinite("Verifying...")
            # This code runs in the GUI thread; process pending paint events immediately
            # so the large state label changes from Loading to Verifying before work.
            QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)
            check_cancel()
            prog.append_log("Verifying thumbnail generation...", "info")
            missing_pages = [i for i in range(total) if i not in results]
            if missing_pages:
                prog.append_log(
                    f"Verification found {len(missing_pages)} missing/failed "
                    "thumbnail(s); repairing them in SP mode.", "warning")
                try:
                    with fitz.open(pdf_path) as doc:
                        for page_idx in missing_pages:
                            check_cancel()
                            try:
                                page = doc.load_page(page_idx)
                                vr = page.rect
                                target_width = _thumbnail_target_width_for_dpi(
                                    vr, thumbnail_dpi)
                                pix = page.get_pixmap(
                                    matrix=fitz.Matrix(
                                        target_width / max(1.0, vr.width),
                                        target_width / max(1.0, vr.width)),
                                    alpha=False)
                                if use_disk:
                                    out_path = os.path.join(
                                        disk_job_dir, f"page_{page_idx + 1:06d}.jpg")
                                    Image.frombytes(
                                        "RGB", [pix.width, pix.height], pix.samples
                                    ).save(out_path, format="JPEG", quality=85)
                                    results[page_idx] = (
                                        int(pix.width), int(pix.height), out_path)
                                else:
                                    results[page_idx] = (
                                        int(pix.width), int(pix.height), bytes(pix.samples))
                            except Exception as exc:
                                worker_errors.append(
                                    f"Page {page_idx + 1}: SP repair failed: {exc}")
                            finally:
                                QtWidgets.QApplication.processEvents(
                                    QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 10)
                                check_cancel()
                except _ThumbnailLoadCancelled:
                    raise
                except Exception as exc:
                    worker_errors.append(f"SP repair could not open PDF: {exc}")
                missing_pages = [i for i in range(total) if i not in results]
            if missing_pages:
                prog.append_log(
                    f"Thumbnail verification still has {len(missing_pages)} unresolved page(s).",
                    "error")
            else:
                prog.append_log("Thumbnail verification passed.", "success")

            prog.start_infinite("Rendering thumbnails")
            QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)
            out = []
            for i in range(total):
                check_cancel()
                payload = results.get(i)
                qpix = None
                if payload:
                    width, height, data = payload
                    try:
                        if use_disk:
                            disk_path = str(data)
                            if os.path.isfile(disk_path):
                                self._disk_thumbnail_paths[(pdf_path, i, thumbnail_dpi)] = disk_path
                                qpix = QtGui.QPixmap(disk_path)
                        else:
                            raw = data
                            qimg = QtGui.QImage(
                                raw, width, height, width * 3,
                                QtGui.QImage.Format.Format_RGB888).copy()
                            qpix = QtGui.QPixmap.fromImage(qimg)
                    except Exception as exc:
                        worker_errors.append(
                            f"Page {i + 1}: thumbnail GUI conversion failed: {exc}")

                if qpix is None or qpix.isNull():
                    prog.append_log(
                        f"Page {i + 1} could not be rendered; using a placeholder.",
                        "warning")
                    qpix = QtGui.QPixmap(max(32, self.grid._image_width),
                                         max(32, self.grid._image_height))
                    qpix.fill(QtGui.QColor("#242424"))

                if not use_disk:
                    self._pristine_cache[(pdf_path, i, thumbnail_dpi)] = qpix
                entry = {
                    'source_pdf': pdf_path,
                    'original_idx': i,
                    'rotation': 0,
                    'crop': None,
                    'flip_h': False,
                    'flip_v': False,
                    'invert_colors': False,
                    'filter_config': _neutral_filter_config(),
                    'ocr_done': False,
                    'page_aspect_ratio': self._source_page_aspect_ratio(pdf_path, i),
                    'uid': self._next_uid,
                }
                self._next_uid += 1
                out.append((entry, self._fit_into_icon(qpix)))
                del qpix
                # This is the fast final GUI-side conversion/preparation pass: the
                # PDF page pixels have already been rendered. The remaining work is
                # turning those results into QPixmaps that the grid can use.
                prog.set_progress(i + 1, max(1, total), "Rendering")
                QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 10)
                check_cancel()

            if worker_errors:
                for err in worker_errors[:12]:
                    prog.append_log(f"  {err}", "warning")
                if len(worker_errors) > 12:
                    prog.append_log(
                        f"  ...and {len(worker_errors) - 12} more thumbnail issue(s).", "warning")

            prog.append_log(
                f"Done: {len(out)} thumbnail(s) from {os.path.basename(pdf_path)}.",
                "success")
            return out

        mode_word = "disk" if use_disk else "memory"
        prog.append_log(
            f"Thumbnail loading mode: SP — single process ({thumbnail_dpi} DPI, {mode_word}).",
            "info")
        out = []
        try:
            with fitz.open(pdf_path) as doc:
                for i in range(total):
                    check_cancel()
                    page = doc.load_page(i)
                    vr = page.rect
                    target_width = _thumbnail_target_width_for_dpi(vr, thumbnail_dpi)
                    zoom = target_width / max(1.0, vr.width)
                    pix = page.get_pixmap(matrix=fitz.Matrix(zoom, zoom), alpha=False)
                    if use_disk:
                        disk_path = os.path.join(
                            disk_job_dir, f"page_{i + 1:06d}.jpg")
                        Image.frombytes(
                            "RGB", [pix.width, pix.height], pix.samples
                        ).save(disk_path, format="JPEG", quality=85)
                        self._disk_thumbnail_paths[(pdf_path, i, thumbnail_dpi)] = disk_path
                        qpix = QtGui.QPixmap(disk_path)
                    else:
                        img = Image.frombytes(
                            "RGB", [pix.width, pix.height], pix.samples)
                        qpix = _pil_to_qpixmap(img)
                        self._pristine_cache[(pdf_path, i, thumbnail_dpi)] = qpix

                    entry = {
                        'source_pdf': pdf_path,
                        'original_idx': i,
                        'rotation': 0,
                        'crop': None,
                        'flip_h': False,
                        'flip_v': False,
                        'page_aspect_ratio': self._source_page_aspect_ratio(pdf_path, i),
                        'uid': self._next_uid,
                    }
                    self._next_uid += 1
                    out.append((entry, self._fit_into_icon(qpix)))
                    del qpix

                    prog.set_progress(i + 1, max(1, total), base_label)
                    if i == 0 or (i + 1) % 10 == 0 or i == total - 1:
                        prog.append_log(
                            f"  Rendered {i+1}/{total} thumbnails", "info")
                    if i % 3 == 0:
                        QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)
                        check_cancel()
        except _ThumbnailLoadCancelled:
            raise
        except Exception as e:
            prog.append_log(f"Render failed for {pdf_path}: {e}", "error")
        prog.append_log(
            f"Done: {len(out)} thumbnail(s) from {os.path.basename(pdf_path)}.",
            "success")
        return out

    def _batch_insert_entries(self, rendered):
        if not rendered:
            return -1
        first_row = self.grid.count()
        self.grid.blockSignals(True)
        try:
            for entry, icon_pix in rendered:
                self._entries.append(entry)
                item = QtWidgets.QListWidgetItem()
                if isinstance(icon_pix, QtGui.QPixmap) and not icon_pix.isNull():
                    self._thumb_cache[entry['uid']] = icon_pix
                    item.setIcon(QtGui.QIcon(icon_pix))
                else:
                    self._thumb_cache.pop(entry['uid'], None)
                item.setData(QtCore.Qt.ItemDataRole.UserRole, entry)
                self.grid.addItem(item)
        finally:
            self.grid.blockSignals(False)
        # Recompute the ratio from the complete live grid. This is the key rule:
        # the most common page shape among all currently visible pages wins.
        self._recalculate_grid_page_aspect_ratio()
        # The final item count can change the vertical scrollbar and therefore
        # the real viewport width. Reflow only after all thumbnails are present.
        self.grid._finalize_population_layout()
        try:
            live_uids = set()
            for i in range(self.grid.count()):
                item = self.grid.item(i)
                if item is not None:
                    data = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
                    if data.get('uid') is not None:
                        live_uids.add(data.get('uid'))
            for uid in list(self._thumb_cache.keys()):
                if uid not in live_uids:
                    self._thumb_cache.pop(uid, None)
        except Exception:
            pass
        self._update_counter()
        return first_row

    def _reload_blank_canvas(self):
        """Return to the pristine empty Blank Canvas state without opening a PDF."""
        try:
            self.grid._drag_src_uid = None
            self.grid._drag_src_file_idx = -1
            self.grid._remove_placeholder()
        except Exception:
            pass
        self._clipboard = []
        self._cut_entries = []
        self._cut_selection_uids = set()
        self._pristine_cache.clear()
        self._thumb_cache.clear()
        self._disk_thumbnail_paths.clear()
        self._page_aspect_ratio_cache.clear()
        for image_pdf in list(self._generated_image_page_pdfs):
            try:
                if image_pdf and os.path.isfile(image_pdf):
                    os.remove(image_pdf)
            except Exception:
                pass
        self._generated_image_page_pdfs.clear()
        for job_dir in list(self._disk_thumbnail_job_dirs):
            _cleanup_thumbnail_disk_job_dir(job_dir)
        self._disk_thumbnail_job_dirs.clear()
        self._thumbnail_resources_dirty = False
        self._entries = []
        self.grid.blockSignals(True)
        try:
            self.grid.clear()
        finally:
            self.grid.blockSignals(False)
        self._undo_stack.clear()
        self._redo_stack.clear()
        self._external_history_before = None
        self.original_page_count = 0
        self._loaded_thumbnail_dpi = None
        self._loaded_thumbnail_use_disk = False
        try:
            self.grid.set_page_aspect_ratio(1.0)
        except Exception:
            pass
        self.original_count_lbl.setText("Originally 0 pages")
        self._update_header_for_canvas_mode()
        self._update_history_buttons()
        self._on_selection_changed()
        self.grid.viewport().update()

    def _reload(self):
        if self._blank_canvas:
            self._reload_blank_canvas()
            return
        self.grid._drag_src_uid = None
        self.grid._drag_src_file_idx = -1
        self.grid._remove_placeholder()

        self._clipboard = []
        self._cut_entries = []
        self._cut_selection_uids = set()
        self._pristine_cache.clear()
        self._thumb_cache.clear()
        self._disk_thumbnail_paths.clear()
        self._page_aspect_ratio_cache.clear()
        # Reload discards the entire current edit document, including temporary
        # image-backed page sources from this session.
        for image_pdf in list(self._generated_image_page_pdfs):
            try:
                if image_pdf and os.path.isfile(image_pdf):
                    os.remove(image_pdf)
            except Exception:
                pass
        self._generated_image_page_pdfs.clear()
        for job_dir in list(self._disk_thumbnail_job_dirs):
            _cleanup_thumbnail_disk_job_dir(job_dir)
        self._disk_thumbnail_job_dirs.clear()
        self._entries = []
        self.grid.clear()
        self._undo_stack.clear()
        self._redo_stack.clear()
        self._external_history_before = None
        self.original_count_lbl.setText("Originally 0 pages")
        self.undo_btn.setEnabled(False)
        self.redo_btn.setEnabled(False)
        self.reset_btn.setEnabled(False)

        try:
            with fitz.open(self.pdf_path) as doc:
                total = doc.page_count
        except Exception as e:
            QtWidgets.QMessageBox.critical(
                self, "Open Failed", f"Could not open PDF:\n{e}")
            return

        self.original_page_count = total
        self.original_count_lbl.setText(
            f"Originally {total} page" + ("s" if total != 1 else ""))

        skip_to_no_thumbnails = False
        prog = ProgressDialog(self, cancel_enabled=True)
        if self._thumbnails_enabled:
            prog.setWindowTitle("Loading Thumbnails")
            prog.start_infinite("Loading thumbnails")
            prog.set_skip_enabled(True)
            prog.append_log(
                f"Preparing to load thumbnails for "
                f"{os.path.basename(self.pdf_path)}...", "info")

            def on_skip_requested():
                nonlocal skip_to_no_thumbnails
                skip_to_no_thumbnails = True
                self._temporary_thumbnails_disabled = True
                prog.append_log(
                    "Thumbnail loading will be skipped. Temporary no-thumbnail mode will be used for this editing session.",
                    "warning",
                )

            prog.skip_requested.connect(on_skip_requested)
        else:
            prog.setWindowTitle("Loading Pages")
            prog.start_infinite("Preparing page grid")
            prog.append_log(
                f"Preparing blank page tiles for {os.path.basename(self.pdf_path)}...",
                "info")
        prog.show()
        QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)

        try:
            if prog.is_cancel_requested():
                rendered = []
                self._cancelled_thumbnail_load = True
            else:
                try:
                    rendered = self._render_pdf_pages_to_entries(
                        self.pdf_path, prog,
                        base_label="Loading" if self._thumbnails_enabled else "Preparing")
                except _ThumbnailLoadCancelled:
                    rendered = []
                    self._cancelled_thumbnail_load = True
        finally:
            prog.accept()

        if getattr(self, "_cancelled_thumbnail_load", False):
            self._cancelled_thumbnail_load = False
            if skip_to_no_thumbnails:
                # A Skip is deliberately different from Cancel: all partially
                # generated thumbnail resources are discarded, but the editor
                # remains open and continues this one session in no-thumbnail mode.
                self._cleanup_memory()
                self._thumbnails_enabled = False
                self._temporary_thumbnails_disabled = True

                no_thumb_prog = ProgressDialog(self, cancel_enabled=True)
                no_thumb_prog.setWindowTitle("Loading Pages")
                no_thumb_prog.start_infinite("Preparing page grid")
                no_thumb_prog.append_log(
                    "Preparing blank page tiles; thumbnail generation is disabled temporarily for this editing session.",
                    "info",
                )
                no_thumb_prog.show()
                QtWidgets.QApplication.processEvents(
                    QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)
                try:
                    if no_thumb_prog.is_cancel_requested():
                        rendered = []
                        self._cancelled_thumbnail_load = True
                    else:
                        try:
                            rendered = self._render_pdf_pages_to_entries(
                                self.pdf_path, no_thumb_prog, base_label="Preparing")
                        except _ThumbnailLoadCancelled:
                            rendered = []
                            self._cancelled_thumbnail_load = True
                finally:
                    no_thumb_prog.accept()

                if getattr(self, "_cancelled_thumbnail_load", False):
                    self._cancelled_thumbnail_load = False
                    self._cleanup_memory()
                    self.done(0)
                    return
            else:
                # Ordinary Cancel leaves Edit PDF just as before.
                self._cleanup_memory()
                self.done(0)
                return

        self._batch_insert_entries(rendered)
        if self.grid.count() > 0:
            self.grid.select_rows_exclusively(0, 1)
        self._thumbnail_resources_dirty = False
        self._undo_stack.clear()
        self._redo_stack.clear()
        self._external_history_before = None
        self._refresh_labels()
        self._on_selection_changed()
        self._update_history_buttons()

    def _populate_grid(self, total):
        self.grid.blockSignals(True)
        self.grid.clear()
        self._entries = []
        self._thumb_cache.clear()
        for i in range(total):
            entry = {
                'source_pdf': self.pdf_path,
                'original_idx': i,
                'rotation': 0,
                'crop': None,
                'flip_h': False,
                'flip_v': False,
                'invert_colors': False,
                'filter_config': _neutral_filter_config(),
                'ocr_done': False,
                'page_numbering': None,
                'page_border': None,
                'page_watermark': None,
                'page_design_anchor': None,
                'page_aspect_ratio': self._source_page_aspect_ratio(self.pdf_path, i),
                'uid': self._next_uid,
            }
            self._next_uid += 1
            self._entries.append(entry)
            pixmap = self._render_base_pixmap(entry)
            self._thumb_cache[entry['uid']] = pixmap
            item = QtWidgets.QListWidgetItem()
            item.setIcon(QtGui.QIcon(pixmap))
            item.setData(QtCore.Qt.ItemDataRole.UserRole, entry)
            self.grid.addItem(item)
        self.grid.blockSignals(False)
        self.grid._finalize_population_layout()
        if self.grid.count() > 0:
            self.grid.select_rows_exclusively(0, 1)
        self._refresh_labels()
        self._on_selection_changed()

    def _get_pristine_pixmap(self, source_pdf, page_idx, thumbnail_dpi=None):
        if thumbnail_dpi is None:
            # Prefer the DPI used when this PDF was loaded. This is essential for
            # History restoration must reuse the existing thumbnail snapshot,
            # even if the user changed global thumbnail settings afterward.
            thumbnail_dpi = self._loaded_thumbnail_dpi
        if thumbnail_dpi is None:
            thumbnail_dpi = int(APP_SETTINGS["advanced"].get("thumbnail_dpi", DEFAULT_THUMBNAIL_DPI))
        thumbnail_dpi = int(thumbnail_dpi)
        key = (source_pdf, page_idx, thumbnail_dpi)
        if key in self._pristine_cache:
            return self._pristine_cache[key]

        disk_path = self._disk_thumbnail_paths.get(key)
        if disk_path and os.path.isfile(disk_path):
            try:
                qpix = QtGui.QPixmap(disk_path)
                if not qpix.isNull():
                    return qpix
            except Exception:
                pass

        try:
            with fitz.open(source_pdf) as doc:
                page = doc.load_page(page_idx)
                vr = page.rect
                target_width = _thumbnail_target_width_for_dpi(vr, thumbnail_dpi)
                zoom = target_width / max(1.0, vr.width)
                mat = fitz.Matrix(zoom, zoom)
                pix = page.get_pixmap(matrix=mat, alpha=False)
                img = Image.frombytes(
                    "RGB", [pix.width, pix.height], pix.samples)
                qpix = _pil_to_qpixmap(img)
        except Exception:
            qpix = QtGui.QPixmap(max(32, self.grid._image_width),
                                 max(32, self.grid._image_height))
            qpix.fill(QtGui.QColor("#202020"))
        self._pristine_cache[key] = qpix
        return qpix

    def _render_base_pixmap(self, entry):
        if not getattr(self, "_thumbnails_enabled", True):
            return QtGui.QPixmap()
        dpi = int(self._loaded_thumbnail_dpi or
                  APP_SETTINGS["advanced"].get("thumbnail_dpi", DEFAULT_THUMBNAIL_DPI))
        if _page_design_has_any(entry) and _page_design_anchor_state(entry) is not None:
            ordered = _render_page_design_ordered_pixmap(entry, dpi, apply_filters=True)
            if ordered is not None:
                return self._fit_into_icon(_pil_to_qpixmap(ordered))
        rot = entry.get('rotation', 0) % 360
        crop = entry.get('crop')
        flip_h = bool(entry.get('flip_h', False))
        flip_v = bool(entry.get('flip_v', False))

        if entry.get("stretch_ratio") is not None:
            thumbnail_dpi = int(
                self._loaded_thumbnail_dpi or
                APP_SETTINGS["advanced"].get("thumbnail_dpi", DEFAULT_THUMBNAIL_DPI))
            stretched_image = _render_stretched_thumbnail_image(
                entry, thumbnail_dpi)
            if stretched_image is not None:
                pm = self._fit_into_icon(_pil_to_qpixmap(stretched_image))
                dpi = int(self._loaded_thumbnail_dpi or APP_SETTINGS["advanced"].get("thumbnail_dpi", DEFAULT_THUMBNAIL_DPI))
                return _page_design_overlay_qpixmap(pm, entry, dpi)

        if crop:
            pix = self._render_cropped_pixmap_from_source(entry)
            if pix is not None:
                if flip_h or flip_v:
                    pix = _flip_qpixmap(pix, flip_h, flip_v)
                filter_cfg = _entry_filter_config(entry)
                if _filter_config_active(filter_cfg):
                    pix = _apply_filter_to_qpixmap(pix, filter_cfg)
                pix = _stretch_qpixmap_to_ratio(pix, entry.get("stretch_ratio"))
                pix = self._fit_into_icon(pix)
                dpi = int(self._loaded_thumbnail_dpi or APP_SETTINGS["advanced"].get("thumbnail_dpi", DEFAULT_THUMBNAIL_DPI))
                return _page_design_overlay_qpixmap(pix, entry, dpi)

        base = self._get_pristine_pixmap(
            entry['source_pdf'], entry['original_idx'])

        if rot == 90:
            base = base.transformed(QtGui.QTransform().rotate(90))
        elif rot == 180:
            base = base.transformed(QtGui.QTransform().rotate(180))
        elif rot == 270:
            base = base.transformed(QtGui.QTransform().rotate(270))

        if flip_h or flip_v:
            base = _flip_qpixmap(base, flip_h, flip_v)

        filter_cfg = _entry_filter_config(entry)
        if _filter_config_active(filter_cfg):
            base = _apply_filter_to_qpixmap(base, filter_cfg)
        base = _stretch_qpixmap_to_ratio(base, entry.get("stretch_ratio"))
        base = self._fit_into_icon(base)
        dpi = int(self._loaded_thumbnail_dpi or APP_SETTINGS["advanced"].get("thumbnail_dpi", DEFAULT_THUMBNAIL_DPI))
        return _page_design_overlay_qpixmap(base, entry, dpi)

    def _fit_into_icon(self, pixmap):
        # Do not bake a fixed 16:9 canvas into the thumbnail. The grid delegate
        # now fits the original rendered pixmap into the common dynamic ratio.
        return pixmap

    def _render_cropped_pixmap_from_source(self, entry):
        try:
            with fitz.open(entry['source_pdf']) as doc:
                page = doc.load_page(entry['original_idx'])
                orig_rot = page.rotation

                crop = entry.get('crop')
                if crop:
                    try:
                        under = fitz.Rect(*crop)
                        try:
                            under = under & page.mediabox
                        except Exception:
                            pass
                        if not under.is_empty:
                            page.set_cropbox(under)
                    except Exception:
                        pass

                page.set_rotation(
                    (orig_rot + entry.get('rotation', 0)) % 360)

                vr = page.rect
                if vr.width <= 0 or vr.height <= 0:
                    page.set_rotation(orig_rot)
                    return None
                thumbnail_dpi = int(self._loaded_thumbnail_dpi or
                                    APP_SETTINGS["advanced"].get("thumbnail_dpi", DEFAULT_THUMBNAIL_DPI))
                target_width = _thumbnail_target_width_for_dpi(vr, thumbnail_dpi)
                zoom = target_width / max(1.0, vr.width)
                mat = fitz.Matrix(zoom, zoom)
                pix = page.get_pixmap(matrix=mat, alpha=False)
                img = Image.frombytes(
                    "RGB", [pix.width, pix.height], pix.samples)
                page.set_rotation(orig_rot)
            return _pil_to_qpixmap(img)
        except Exception:
            return None

    def _refresh_item_icon(self, row):
        item = self.grid.item(row)
        if item is None:
            return
        if not getattr(self, "_thumbnails_enabled", True):
            item.setIcon(QtGui.QIcon())
            entry = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
            self._thumb_cache.pop(entry.get('uid'), None)
            return
        entry = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
        pixmap = self._render_base_pixmap(entry)
        self._thumb_cache[entry.get('uid')] = pixmap
        item.setIcon(QtGui.QIcon(pixmap))

    def _refresh_labels(self):
        self._recalculate_grid_page_aspect_ratio()
        self.grid.viewport().update()
        self._update_history_buttons()
        self._update_counter()
        self._on_selection_changed()

    def _update_counter(self):
        try:
            total = self.grid.count()
            n = len(self.grid.selectedItems())
            self.sel_count_lbl.setText(f"Selected {n}  ·  Total {total}")
        except Exception:
            pass

    def _capture_edit_state(self):
        entries = []
        selected_uids = []
        for i in range(self.grid.count()):
            item = self.grid.item(i)
            if item is None:
                continue
            data = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
            if 'source_pdf' not in data or 'original_idx' not in data:
                continue
            entries.append(copy.deepcopy(data))
            if item.isSelected():
                selected_uids.append(data.get('uid'))
        return {
            'entries': entries,
            'selected_uids': selected_uids,
            'clipboard': copy.deepcopy(self._clipboard),
            'cut_entries': copy.deepcopy(self._cut_entries),
            'cut_selection_uids': set(self._cut_selection_uids),
        }

    @staticmethod
    def _edit_states_equal(a, b):
        # Selection is deliberately excluded: selecting a page is navigation/UI,
        # not a document edit. Clipboard/cut state is included so Paste can be
        # undone back to the exact pre-paste state.
        return (a['entries'] == b['entries']
                and a['clipboard'] == b['clipboard']
                and a['cut_entries'] == b['cut_entries']
                and a['cut_selection_uids'] == b['cut_selection_uids'])

    def _cleanup_stale_thumbnail_job_dirs(self):
        """Remove thumbnail job directories left by a crashed/aborted prior session."""
        root = _thumbnail_disk_root()
        try:
            if not os.path.isdir(root):
                return
            for name in os.listdir(root):
                if not name.startswith("job_"):
                    continue
                path = os.path.join(root, name)
                if os.path.isdir(path):
                    _cleanup_thumbnail_disk_job_dir(path)
            # Do not leave an otherwise-empty thumbnail root behind. It is cheap
            # to recreate on the next disk-backed thumbnail load.
            try:
                if os.path.isdir(root) and not os.listdir(root):
                    os.rmdir(root)
            except Exception:
                pass
        except Exception:
            pass

    def _collect_reachable_thumbnail_pages(self):
        """Return source PDF/page pairs still reachable by the editor state graph.

        A page is considered reachable if it exists in the visible document, any
        Undo state, any Redo state, the copy clipboard, or the cut buffer. Anything
        outside this set cannot be restored by the current editor and therefore does
        not need its pristine thumbnail kept alive.
        """
        refs = set()

        def add_entry(entry):
            if not isinstance(entry, dict):
                return
            source_pdf = entry.get("source_pdf")
            page_idx = entry.get("original_idx")
            if source_pdf is None or page_idx is None:
                return
            try:
                page_idx = int(page_idx)
            except Exception:
                return
            refs.add((source_pdf, page_idx))

        def add_entries(entries):
            if not entries:
                return
            for entry in entries:
                add_entry(entry)

        try:
            for i in range(self.grid.count()):
                item = self.grid.item(i)
                if item is not None:
                    add_entry(item.data(QtCore.Qt.ItemDataRole.UserRole) or {})
        except Exception:
            pass

        for state in list(self._undo_stack) + list(self._redo_stack):
            if not isinstance(state, dict):
                continue
            add_entries(state.get("entries", []))
            add_entries(state.get("clipboard", []))
            add_entries(state.get("cut_entries", []))

        add_entries(self._clipboard)
        add_entries(self._cut_entries)
        return refs

    def _cleanup_released_thumbnail_resources(self):
        """Free thumbnail RAM/disk resources that are no longer undo/re-do reachable.

        This is deliberately based on logical page reachability rather than on
        whether a thumbnail happens to be present in the current grid. A page that
        can still be restored by Undo/Redo or pasted from the clipboard keeps its
        pristine thumbnail. Once the corresponding state branch disappears, its
        raster resources are released. Missing disk thumbnails can always be
        regenerated from the source PDF, so deleting an unreachable/stale thumbnail
        is safe.
        """
        reachable = self._collect_reachable_thumbnail_pages()

        # Generated image-page PDFs are source documents in the same logical
        # reachability graph. Keep them while the corresponding page can still be
        # shown, undone, redone, or pasted; release them once nothing can reach them.
        for image_pdf in list(self._generated_image_page_pdfs):
            if any(source_pdf == image_pdf for source_pdf, _page_idx in reachable):
                continue
            try:
                if image_pdf and os.path.isfile(image_pdf):
                    os.remove(image_pdf)
            except Exception:
                pass
            self._generated_image_page_pdfs.discard(image_pdf)

        loaded_dpi = self._loaded_thumbnail_dpi
        try:
            loaded_dpi = int(loaded_dpi) if loaded_dpi is not None else None
        except Exception:
            loaded_dpi = None

        released_memory = 0
        released_disk_files = 0
        removed_job_dirs = 0

        # _thumb_cache contains GUI-facing pixmaps keyed by entry UID. History
        # restoration rebuilds this cache from pristine/source thumbnails, so a UID
        # that is not in the visible grid can be discarded immediately.
        try:
            live_uids = set()
            for i in range(self.grid.count()):
                item = self.grid.item(i)
                if item is not None:
                    data = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
                    uid = data.get("uid")
                    if uid is not None:
                        live_uids.add(uid)
            for uid in list(self._thumb_cache.keys()):
                if uid not in live_uids:
                    self._thumb_cache.pop(uid, None)
        except Exception:
            pass

        # In-memory pristine thumbnails. Keep only source pages that remain
        # reachable, and discard stale DPI variants because entries do not encode a
        # separate thumbnail-DPI dependency; a missing variant is safely regenerated.
        for key in list(self._pristine_cache.keys()):
            try:
                source_pdf, page_idx, dpi = key
            except Exception:
                # Drop malformed cache entries defensively.
                try:
                    self._pristine_cache.pop(key, None)
                    released_memory += 1
                except Exception:
                    pass
                continue

            keep = ((source_pdf, int(page_idx)) in reachable
                    and (loaded_dpi is None or int(dpi) == loaded_dpi))
            if not keep:
                try:
                    self._pristine_cache.pop(key, None)
                    released_memory += 1
                except Exception:
                    pass

        # Disk-backed thumbnails. Each job directory is just a disposable cache.
        # Keep only registered page files that correspond to reachable pages at the
        # currently loaded DPI. Unreachable/stale JPEGs are explicitly unlinked,
        # then any now-empty/orphaned job directory is removed.
        kept_disk_paths = set()
        for key, path in list(self._disk_thumbnail_paths.items()):
            try:
                source_pdf, page_idx, dpi = key
                keep = ((source_pdf, int(page_idx)) in reachable
                        and (loaded_dpi is None or int(dpi) == loaded_dpi)
                        and os.path.isfile(path))
            except Exception:
                keep = False

            if keep:
                try:
                    kept_disk_paths.add(os.path.abspath(path))
                except Exception:
                    pass
                continue

            try:
                if path and os.path.isfile(path):
                    os.remove(path)
                    released_disk_files += 1
            except Exception:
                pass
            self._disk_thumbnail_paths.pop(key, None)

        # Remove stray files in tracked job directories too. This covers partial MP
        # jobs, failed workers, cancelled loads, and duplicate loads whose mapping
        # was later replaced by a newer job directory.
        for job_dir in list(self._disk_thumbnail_job_dirs):
            try:
                if not os.path.isdir(job_dir):
                    self._disk_thumbnail_job_dirs.discard(job_dir)
                    continue

                for name in os.listdir(job_dir):
                    path = os.path.join(job_dir, name)
                    if os.path.isfile(path):
                        if os.path.abspath(path) not in kept_disk_paths:
                            try:
                                os.remove(path)
                                released_disk_files += 1
                            except Exception:
                                pass

                remaining_files = [
                    os.path.join(job_dir, name)
                    for name in os.listdir(job_dir)
                    if os.path.isfile(os.path.join(job_dir, name))
                ]
                if not remaining_files:
                    _cleanup_thumbnail_disk_job_dir(job_dir)
                    if not os.path.exists(job_dir):
                        self._disk_thumbnail_job_dirs.discard(job_dir)
                        removed_job_dirs += 1
            except Exception:
                pass

        try:
            gc.collect()
        except Exception:
            pass
        self._thumbnail_resources_dirty = False

        if released_memory or released_disk_files or removed_job_dirs:
            logging.debug(
                "Thumbnail cleanup: released %d memory cache entries, "
                "%d disk files, removed %d job directories.",
                released_memory, released_disk_files, removed_job_dirs)

        return {
            "reachable_pages": len(reachable),
            "released_memory_entries": released_memory,
            "released_disk_files": released_disk_files,
            "removed_job_dirs": removed_job_dirs,
        }

    def _trim_history(self):
        trimmed = False
        if len(self._undo_stack) > self._history_limit:
            del self._undo_stack[:-self._history_limit]
            trimmed = True
        if len(self._redo_stack) > self._history_limit:
            del self._redo_stack[:-self._history_limit]
            trimmed = True
        return trimmed

    def _update_history_buttons(self):
        try:
            self.undo_btn.setEnabled(bool(self._undo_stack))
            self.redo_btn.setEnabled(bool(self._redo_stack))
        except Exception:
            pass

        if self._blank_canvas:
            has_blank_changes = self.grid.count() > 0
            try:
                self.reset_btn.setEnabled(has_blank_changes)
                self.save_btn.setEnabled(has_blank_changes)
            except Exception:
                pass
            return

        if self.original_page_count <= 0:
            try:
                self.reset_btn.setEnabled(False)
                self.save_btn.setEnabled(False)
            except Exception:
                pass
            return

        current = []
        for i in range(self.grid.count()):
            item = self.grid.item(i)
            if item is None:
                continue
            data = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
            current.append((
                data.get('source_pdf'),
                data.get('original_idx', i),
                data.get('rotation', 0) % 360,
                data.get('crop'),
                bool(data.get('flip_h', False)),
                bool(data.get('flip_v', False)),
                copy.deepcopy(_entry_filter_config(data)),
                bool(data.get('ocr_done') or data.get('ocr')),
                data.get('stretch_ratio'),
                copy.deepcopy(_page_numbering_entry_config(data)),
                copy.deepcopy(_page_design_border_entry_config(data)),
                copy.deepcopy(_page_design_watermark_entry_config(data)),
            ))
        pristine = [(self.pdf_path, i, 0, None, False, False,
                     _neutral_filter_config(), False, None, None, None, None)
                    for i in range(self.original_page_count)]
        has_changes = current != pristine
        try:
            self.reset_btn.setEnabled(has_changes)
            self.save_btn.setEnabled(has_changes)
        except Exception:
            pass

    def _restore_edit_state(self, state):
        self._history_suspended = True
        try:
            try:
                self.grid._drag_src_uid = None
                self.grid._drag_src_file_idx = -1
                self.grid._remove_placeholder()
            except Exception:
                pass

            self._clipboard = copy.deepcopy(state['clipboard'])
            self._cut_entries = copy.deepcopy(state['cut_entries'])
            self._cut_selection_uids = set(state['cut_selection_uids'])

            state_uids = [e.get('uid') for e in state['entries']
                          if e.get('uid') is not None]
            if state_uids:
                self._next_uid = max(self._next_uid, max(state_uids) + 1)

            self.grid.blockSignals(True)
            try:
                self.grid.clear()
                self._entries = []
                self._thumb_cache.clear()
                for data in state['entries']:
                    entry = copy.deepcopy(data)
                    self._entries.append(entry)
                    uid = entry.get('uid')
                    pixmap = self._get_pristine_or_current_history_pixmap(entry)
                    self._thumb_cache[uid] = pixmap
                    item = QtWidgets.QListWidgetItem()
                    item.setIcon(QtGui.QIcon(pixmap))
                    item.setData(QtCore.Qt.ItemDataRole.UserRole, entry)
                    self.grid.addItem(item)
            finally:
                self.grid.blockSignals(False)

            selected = set(state.get('selected_uids', []))
            self.grid.blockSignals(True)
            try:
                for i in range(self.grid.count()):
                    item = self.grid.item(i)
                    data = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
                    item.setSelected(data.get('uid') in selected)
            finally:
                self.grid.blockSignals(False)

            self._recalculate_grid_page_aspect_ratio()
            self.grid._finalize_population_layout()
            self._refresh_labels()
        finally:
            self._history_suspended = False

    def _get_pristine_or_current_history_pixmap(self, entry):
        # Prefer the already loaded pristine thumbnail for untouched pages. For
        # transformed pages, render just this page from its cached pristine base.
        return self._render_base_pixmap(entry)

    def _undo_one(self):
        if not self._undo_stack:
            return
        current = self._capture_edit_state()
        target = self._undo_stack.pop()
        self._redo_stack.append(current)
        history_trimmed = bool(self._trim_history())
        self._restore_edit_state(target)
        self._update_history_buttons()
        if history_trimmed:
            self._cleanup_released_thumbnail_resources()

    def _redo_one(self):
        if not self._redo_stack:
            return
        current = self._capture_edit_state()
        target = self._redo_stack.pop()
        self._undo_stack.append(current)
        history_trimmed = bool(self._trim_history())
        self._restore_edit_state(target)
        self._update_history_buttons()
        if history_trimmed:
            self._cleanup_released_thumbnail_resources()

    def _history_external_begin(self):
        if not self._history_suspended:
            self._external_history_before = self._capture_edit_state()

    def _history_external_finish(self):
        before = self._external_history_before
        self._external_history_before = None
        if before is None or self._history_suspended:
            return
        after = self._capture_edit_state()
        if not self._edit_states_equal(before, after):
            redo_was_nonempty = bool(self._redo_stack)
            self._undo_stack.append(before)
            self._redo_stack.clear()
            history_trimmed = bool(self._trim_history())
            self._update_history_buttons()
            if redo_was_nonempty or history_trimmed:
                self._cleanup_released_thumbnail_resources()

    def _zoom_in_grid(self):
        # Zooming in means bigger thumbnails, therefore fewer thumbnails per row.
        slider = getattr(self, '_thumbnail_density_slider', None)
        if slider is not None and slider.value() > slider.minimum():
            slider.setValue(slider.value() - 1)

    def _zoom_out_grid(self):
        # Zooming out means smaller thumbnails, therefore more thumbnails per row.
        slider = getattr(self, '_thumbnail_density_slider', None)
        if slider is not None and slider.value() < slider.maximum():
            slider.setValue(slider.value() + 1)

    def _reset_changes(self):
        """Reset to the loaded/original PDF state and establish a new history boundary.

        Reset is intentionally not undoable. Once the user chooses Reset, edits that
        existed before that action are no longer a live Undo branch, so their exclusive
        thumbnail resources can be released immediately. Future edits can still be
        undone back to this reset state because the reset state becomes the new baseline.
        """
        if self._blank_canvas:
            if self.grid.count() == 0:
                self._update_history_buttons()
                return
            self._history_suspended = True
            try:
                try:
                    self.grid._drag_src_uid = None
                    self.grid._drag_src_file_idx = -1
                    self.grid._remove_placeholder()
                except Exception:
                    pass
                self._clear_clipboard_state()
                self.grid.blockSignals(True)
                try:
                    self.grid.clear()
                    self._entries = []
                    self._thumb_cache.clear()
                finally:
                    self.grid.blockSignals(False)
            finally:
                self._history_suspended = False
            self._undo_stack.clear()
            self._redo_stack.clear()
            self._external_history_before = None
            self._cleanup_released_thumbnail_resources()
            self._update_history_buttons()
            self.grid.viewport().update()
            return

        if self.original_page_count <= 0:
            return

        # Do not deep-copy the entire edit state here. Reset is a history boundary,
        # so only lightweight document metadata is needed to determine whether an
        # actual reset is required.
        current_doc = []
        for i in range(self.grid.count()):
            item = self.grid.item(i)
            if item is None:
                continue
            e = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
            current_doc.append((
                e.get('source_pdf'), e.get('original_idx', i),
                e.get('rotation', 0) % 360, e.get('crop'),
                bool(e.get('flip_h')), bool(e.get('flip_v')),
                copy.deepcopy(_entry_filter_config(e)),
                bool(e.get('ocr_done') or e.get('ocr')),
                e.get('stretch_ratio'),
                copy.deepcopy(_page_numbering_entry_config(e)),
                copy.deepcopy(_page_design_border_entry_config(e)),
                copy.deepcopy(_page_design_watermark_entry_config(e)))) 

        target_doc = [(self.pdf_path, i, 0, None, False, False,
                       _neutral_filter_config(), False, None, None, None, None)
                      for i in range(self.original_page_count)]

        # Reset is disabled for a pristine document. Keep the existing history/Redo
        # branch intact rather than treating a programmatic/shortcut call as a reset.
        if current_doc == target_doc:
            self._update_history_buttons()
            return

        self._history_suspended = True
        try:
            try:
                self.grid._drag_src_uid = None
                self.grid._drag_src_file_idx = -1
                self.grid._remove_placeholder()
            except Exception:
                pass

            # Clear clipboard/cut state and visual markers. The helper may perform
            # a harmless reachability pass, but pre-reset history is still retained
            # until the hard boundary below, so those resources remain protected.
            self._clear_clipboard_state()

            # Rebuild only from the already-loaded pristine/source thumbnails.
            # This does not invoke Reload, safety checks, or another MP render.
            self._populate_grid(self.original_page_count)
            self.grid.clearSelection()
        finally:
            self._history_suspended = False

        # Drop every pre-reset history state. This is the key boundary that makes
        # imported pages and their exclusive thumbnails collectible immediately.
        self._undo_stack.clear()
        self._redo_stack.clear()
        self._external_history_before = None
        self._update_history_buttons()
        try:
            self._cleanup_released_thumbnail_resources()
        except Exception:
            pass
        try:
            self.grid.viewport().update()
        except Exception:
            pass

    def _on_selection_changed(self):
        items = self.grid.selectedItems()
        n = len(items)
        self.delete_btn.setEnabled(n > 0)
        self.copy_btn.setEnabled(n > 0)
        self.cut_btn.setEnabled(n > 0)
        self.paste_btn.setEnabled(bool(self._clipboard)
                                  or bool(self._cut_entries))
        self.rotate_ccw_btn.setEnabled(n > 0)
        self.rotate_btn.setEnabled(n > 0)
        self.crop_btn.setEnabled(n > 0)
        self.stretch_btn.setEnabled(n > 0)
        self.flip_h_btn.setEnabled(n > 0)
        self.flip_v_btn.setEnabled(n > 0)
        self.page_design_btn.setEnabled(n > 0)
        self.nup_btn.setEnabled(n > 0)
        self.ocr_btn.setEnabled(n > 0)
        self.apply_filters_btn.setEnabled(n > 0)
        self.presentation_selected_btn.setEnabled(n > 0)
        self.print_selected_btn.setEnabled(n > 0)
        self.open_btn.setEnabled(n > 0)
        self.save_selected_btn.setEnabled(n > 0)
        self.selectrange_btn.setEnabled(self.grid.count() > 1)
        self.deselectall_btn.setEnabled(n > 1)
        self._update_counter()

    # ---------------- Page Design ----------------
    def _show_reapply_page_design_warning(self, selected_count):
        """Confirm clearing Page Design when selected pages have different design states."""
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle("Uncommon Page Design")
        dlg.setModal(True)
        dlg.setMinimumWidth(520)
        layout = QtWidgets.QVBoxLayout(dlg)
        layout.setContentsMargins(22, 18, 22, 18)
        layout.setSpacing(12)

        title = QtWidgets.QLabel("Selected pages have different page design settings")
        title.setStyleSheet(
            "QLabel { background:transparent; border:none; color:#f0f0f0; "
            "font-size:12pt; font-weight:700; }"
        )
        layout.addWidget(title)
        body = QtWidgets.QLabel(
            f"{selected_count} selected page(s) do not share one common Page Design configuration.\n\n"
            "The old design state must be cleared before a new shared Page Design session can open.\n"
            "You can then edit the new common design settings and apply them to the selection."
        )
        body.setWordWrap(True)
        body.setStyleSheet("QLabel { background:transparent; border:none; color:#c9c9c9; padding:0; }")
        layout.addWidget(body)
        buttons = QtWidgets.QHBoxLayout()
        buttons.setSpacing(8)
        buttons.addStretch()
        cancel = QtWidgets.QPushButton("Cancel")
        cancel.setMinimumWidth(105)
        cancel.setDefault(True)
        cancel.clicked.connect(dlg.reject)
        buttons.addWidget(cancel)
        remove = QtWidgets.QPushButton("Reload Page Design")
        remove.setMinimumWidth(150)
        remove.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        remove.setStyleSheet("""
            QPushButton {
                background:#7a2626; color:#ffffff; border:1px solid #9c3737;
                border-radius:6px; padding:7px 14px; font-weight:bold;
            }
            QPushButton:hover { background:#922d2d; }
        """)
        remove.clicked.connect(dlg.accept)
        buttons.addWidget(remove)
        layout.addLayout(buttons)
        return dlg.exec() == QtWidgets.QDialog.DialogCode.Accepted

    def _clear_page_design_for_reapply(self, selected_entries):
        """Remove selected-page design state from live data, mirrors and history snapshots."""
        affected_uids = {
            entry.get("uid")
            for _row, entry in selected_entries
            if entry.get("uid") is not None
        }

        def clear_entry(entry):
            if not isinstance(entry, dict) or entry.get("uid") not in affected_uids:
                return
            entry["page_numbering"] = None
            entry["page_border"] = None
            entry["page_watermark"] = None
            entry.pop("page_design_anchor", None)

        for i in range(self.grid.count()):
            item = self.grid.item(i)
            if item is None:
                continue
            data = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
            if data.get("uid") in affected_uids:
                clear_entry(data)
                item.setData(QtCore.Qt.ItemDataRole.UserRole, data)
                self._thumb_cache.pop(data.get("uid"), None)
                self._refresh_item_icon(i)

        for entry in getattr(self, "_entries", []):
            clear_entry(entry)
        for entries in (getattr(self, "_clipboard", []), getattr(self, "_cut_entries", [])):
            for entry in entries:
                clear_entry(entry)
        for stack in (getattr(self, "_undo_stack", []), getattr(self, "_redo_stack", [])):
            for state in stack:
                if not isinstance(state, dict):
                    continue
                for key in ("entries", "clipboard", "cut_entries"):
                    for entry in state.get(key, []):
                        clear_entry(entry)
        try:
            current_state = self._capture_edit_state()
            while self._undo_stack and self._edit_states_equal(self._undo_stack[-1], current_state):
                self._undo_stack.pop()
        except Exception:
            pass
        self._refresh_labels()
        self._update_history_buttons()

    def _page_design_selected(self):
        sel = self._selected_entries_sorted()
        if not sel:
            return

        # A common design state (including all-neutral) is reusable. A mismatch across even
        # one selected page first asks for the same reset-style confirmation used by Filters.
        if not all(_page_design_configs_equal(sel[0][1], entry) for _row, entry in sel[1:]):
            if not self._show_reapply_page_design_warning(len(sel)):
                return
            self._clear_page_design_for_reapply(sel)
            sel = self._selected_entries_sorted()

        rows = [row for row, _entry in sel]
        anchor_row = self._get_anchor_row()
        anchor_index = rows.index(anchor_row) if anchor_row in rows else 0
        nav_entries = []
        for row, entry in sel:
            data = dict(entry)
            data["grid_row"] = int(row)
            nav_entries.append(data)
        try:
            dlg = PageDesignDialog(self, nav_entries, anchor_index=anchor_index, parent=self)
        except Exception as exc:
            QtWidgets.QMessageBox.critical(
                self, "Page design", f"Could not open the page design editor:\n\n{exc}")
            return
        dlg.exec()

    @_history_action
    def _apply_page_design_to_selection(self, nav_entries, config):
        if not nav_entries:
            return
        base_num = _page_numbering_normalize_config(config.get("page_numbering")) if isinstance(config, dict) else None
        base_border = _page_design_normalize_border(config.get("page_border")) if isinstance(config, dict) else None
        base_wm = _page_design_normalize_watermark(config.get("page_watermark")) if isinstance(config, dict) else None
        uid_to_serial = {data.get("uid"): i for i, data in enumerate(nav_entries) if data.get("uid") is not None}
        affected = set(uid_to_serial)
        for row in range(self.grid.count()):
            item = self.grid.item(row)
            if item is None:
                continue
            entry = item.data(QtCore.Qt.ItemDataRole.UserRole) or {}
            uid = entry.get("uid")
            if uid not in affected:
                continue
            serial_index = uid_to_serial[uid]
            if base_num is not None:
                number = (int(base_num["start"]) + serial_index
                          if base_num["mode"] == "start"
                          else int(nav_entries[serial_index].get("grid_row", row)) + 1)
                number = max(1, min(999999999, number))
                stored_num = dict(base_num); stored_num["number"] = number
            else:
                stored_num = None
            entry["page_numbering"] = copy.deepcopy(stored_num)
            entry["page_border"] = copy.deepcopy(base_border)
            entry["page_watermark"] = copy.deepcopy(base_wm)
            if stored_num is None and base_border is None and base_wm is None:
                entry.pop("page_design_anchor", None)
            else:
                entry["page_design_anchor"] = {
                    "rotation": int(entry.get("rotation", 0)) % 360,
                    "crop": copy.deepcopy(entry.get("crop")),
                    "flip_h": bool(entry.get("flip_h", False)),
                    "flip_v": bool(entry.get("flip_v", False)),
                    "stretch_ratio": entry.get("stretch_ratio"),
                    "filter_config": copy.deepcopy(_entry_filter_config(entry)),
                    "ocr_present": bool(entry.get("ocr_done") or entry.get("ocr")),
                }
            item.setData(QtCore.Qt.ItemDataRole.UserRole, entry)
            self._refresh_item_icon(row)
            for mirror in self._entries:
                if mirror.get("uid") == uid:
                    mirror["page_numbering"] = copy.deepcopy(stored_num)
                    mirror["page_border"] = copy.deepcopy(base_border)
                    mirror["page_watermark"] = copy.deepcopy(base_wm)
                    if stored_num is None and base_border is None and base_wm is None:
                        mirror.pop("page_design_anchor", None)
                    else:
                        mirror["page_design_anchor"] = copy.deepcopy(entry.get("page_design_anchor"))
                    break
        self._refresh_labels(); self.grid.viewport().update()

    # Backward compatibility for older internal callers.
    @_history_action
    def _apply_page_numbering_to_selection(self, nav_entries, config):
        self._apply_page_design_to_selection(nav_entries, {"page_numbering": config, "page_border": None, "page_watermark": None})

    # ---------------- Selection helpers ----------------
    def _selected_entries_sorted(self):
        rows = sorted(self.grid.row(it) for it in self.grid.selectedItems())
        out = []
        for r in rows:
            it = self.grid.item(r)
            if it is None:
                continue
            out.append((r, it.data(QtCore.Qt.ItemDataRole.UserRole) or {}))
        return out

    def _consume_context_anchor(self):
        row = self._context_menu_row
        self._context_menu_row = -1
        return row

    def _get_anchor_row(self):
        row = self._consume_context_anchor()
        if row >= 0 and row < self.grid.count():
            it = self.grid.item(row)
            if it is not None and it.isSelected():
                return row
        sel = self._selected_entries_sorted()
        if sel:
            return sel[0][0]
        return -1

    def _all_grid_entries(self):
        out = []
        for i in range(self.grid.count()):
            it = self.grid.item(i)
            if it is None:
                continue
            d = it.data(QtCore.Qt.ItemDataRole.UserRole) or {}
            if 'source_pdf' in d:
                e = dict(d)
                e['grid_row'] = i
                out.append(e)
        return out

    def _on_grid_context_menu(self, pos):
        self._context_menu_row = -1
        item = self.grid.itemAt(pos)
        menu = QtWidgets.QMenu(self)
        menu.setStyleSheet("""
            QMenu {
                background-color: #2b2b2b;
                border: 1px solid #3a3a3a;
                border-radius: 6px;
                padding: 4px;
            }
            QMenu::separator {
                height: 1px;
                background: #3a3a3a;
                margin: 4px 8px;
            }
        """)

        if item is not None:
            if not item.isSelected():
                self.grid.clearSelection()
                item.setSelected(True)
            self._context_menu_row = self.grid.row(item)

            _add_menu_item(menu, "open.svg", "Open", self._open_selected,
                           "Double click", self.open_btn.isEnabled())
            _add_menu_item(menu, "save-page.svg",
                           "Save as...",
                           self._save_selected_pages, "Ctrl+Shift+S",
                           self.save_selected_btn.isEnabled())
            _add_menu_item(menu, "cut.svg", "Cut", self._cut_selected,
                           "Ctrl+X", self.cut_btn.isEnabled())
            _add_menu_item(menu, "copy.svg", "Copy", self._copy_selected,
                           "Ctrl+C", self.copy_btn.isEnabled())
            _add_menu_item(menu, "paste.svg", "Paste", self._paste_copied,
                           "Ctrl+V", self.paste_btn.isEnabled())
            _add_menu_item(menu, "delete.svg", "Delete",
                           self._delete_selected, "Delete",
                           self.delete_btn.isEnabled())
            menu.addSeparator()
            _add_menu_item(menu, "crop.svg", "Crop", self._crop_selected,
                           "Ctrl+K", self.crop_btn.isEnabled())
            _add_menu_item(menu, "stretch.svg", "Stretch",
                           self._stretch_selected_pages, "Ctrl+Shift+T",
                           self.stretch_btn.isEnabled())
            _add_menu_item(menu, "rotate-ccw.svg", "Rotate 90° CCW",
                           self._rotate_ccw_selected, "Ctrl+Left",
                           self.rotate_ccw_btn.isEnabled())
            _add_menu_item(menu, "rotate.svg", "Rotate 90° CW",
                           self._rotate_selected, "Ctrl+Right",
                           self.rotate_btn.isEnabled())
            _add_menu_item(menu, "flip-h.svg", "Flip Horizontally",
                           self._flip_h_selected, "Ctrl+Shift+H",
                           self.flip_h_btn.isEnabled())
            _add_menu_item(menu, "flip-v.svg", "Flip Vertically",
                           self._flip_v_selected, "Ctrl+Shift+V",
                           self.flip_v_btn.isEnabled())

            # Keep Page Design as its own section, matching the main toolbar:
            # transform actions | Page Design | N-up/OCR/Filters.
            menu.addSeparator()
