    def set_mergerz_update_checking(self):
        self.mergerz_update_label.setText("Checking for updates...")
        self.mergerz_update_label.setProperty("update_version", "")
        self.mergerz_update_button.hide()
        self.mergerz_update_close_button.hide()
        self.mergerz_update_footer.show()
        self.mergerz_update_footer.raise_()
        self.updateGeometry()
        self.mergerz_update_footer.repaint()

    def show_mergerz_update_available(self, version):
        version = str(version or "").strip()
        if not version:
            self.hide_mergerz_update_footer()
            return
        self.mergerz_update_label.setText(f"New update found: v{version}.")
        self.mergerz_update_label.setProperty("update_version", version)
        self.mergerz_update_button.setEnabled(True)
        self.mergerz_update_button.show()
        self.mergerz_update_close_button.setEnabled(True)
        self.mergerz_update_close_button.show()
        self.mergerz_update_footer.show()
        self.mergerz_update_footer.raise_()
        self.updateGeometry()
        self.mergerz_update_footer.repaint()

    def set_mergerz_update_installing(self):
        self.mergerz_update_label.setText("Updating Mergerz...")
        self.mergerz_update_button.setEnabled(False)
        self.mergerz_update_button.show()
        self.mergerz_update_close_button.setEnabled(False)
        self.mergerz_update_close_button.show()
        self.mergerz_update_footer.show()
        self.mergerz_update_footer.raise_()
        self.updateGeometry()
        self.mergerz_update_footer.repaint()

    def hide_mergerz_update_footer(self):
        self.mergerz_update_footer.hide()

    def _request_mergerz_update(self):
        try:
            self.mergerz_update_requested.emit(
                str(self.mergerz_update_label.property("update_version") or "")
            )
        except Exception:
            pass

    def _dismiss_mergerz_update(self):
        self.mergerz_update_footer.hide()
        try:
            self.mergerz_update_dismissed.emit()
        except Exception:
            pass

    def set_mergerz_update_version(self, version):
        self.mergerz_update_label.setProperty("update_version", str(version or ""))

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.settings_btn.move(18, 18)
        self.plugins_btn.move(max(36, self.width() - 130), 22)
        self.settings_btn.raise_()
        self.plugins_btn.raise_()
        QtCore.QTimer.singleShot(0, self._update_option_section_heights)

    def _tick_gear(self):
        self._gear_angle = (self._gear_angle + 4) % 360
        icon_path = os.path.join(ICONS_FOLDER, "gear.svg")
        icon = _render_svg_icon_rotated(icon_path, 42, self._gear_angle)
        if icon is not None:
            self.gear_label.setPixmap(icon.pixmap(42, 42))

    def refresh_storage(self, animate=True):
        try:
            self.free_storage_label.setText(
                f"Free storage: {check_free_storage()}")
        except Exception:
            pass
        if animate:
            self._trigger_reload_spin()

    def _trigger_reload_spin(self):
        self._reload_angle = 0
        self.reload_storage_btn.setEnabled(False)
        if not self._reload_spin_timer.isActive():
            self._reload_spin_timer.start()
        self._reload_stop_timer.stop()
        self._reload_stop_timer.start(700)

    def _on_reload_clicked(self):
        self.refresh_storage(animate=True)

    def _tick_reload_spin(self):
        self._reload_angle = (self._reload_angle + 30) % 360
        icon_path = os.path.join(ICONS_FOLDER, "reload.svg")
        icon = _render_svg_icon_rotated(icon_path, 17, self._reload_angle)
        if icon is not None:
            self.reload_storage_btn.setIcon(icon)

    def _end_reload_spin(self):
        self._reload_spin_timer.stop()
        self._reload_angle = 0
        icon_path = os.path.join(ICONS_FOLDER, "reload.svg")
        icon = _render_svg_icon(icon_path, size=17)
        if icon is not None:
            self.reload_storage_btn.setIcon(icon)
        self.reload_storage_btn.setEnabled(True)

    @staticmethod
    def _make_section_header(title_text, description_text=None):
        wrapper = QtWidgets.QWidget()
        wrapper.setStyleSheet("background: transparent;")
        row = QtWidgets.QHBoxLayout(wrapper)
        row.setContentsMargins(0, 0, 0, 0)
        row.setSpacing(12)

        accent = QtWidgets.QFrame()
        accent.setFixedSize(4, 34)
        accent.setStyleSheet(
            "background: #0078d7; border: none; border-radius: 2px;")
        row.addWidget(accent, 0, QtCore.Qt.AlignmentFlag.AlignTop)

        col = QtWidgets.QVBoxLayout()
        col.setContentsMargins(0, 0, 0, 0)
        col.setSpacing(2)

        title = QtWidgets.QLabel(title_text)
        title.setStyleSheet(
            "font-size: 17pt; font-weight: 800; color: #f2f2f2; "
            "background: transparent; border: none;")
        title.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        col.addWidget(title)

        if description_text:
            desc = QtWidgets.QLabel(description_text)
            desc.setWordWrap(True)
            desc.setStyleSheet(
                "font-size: 9pt; color: #777777; background: transparent; "
                "border: none;")
            desc.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
            col.addWidget(desc)
        row.addLayout(col, 1)
        return wrapper

    @staticmethod
    def _option_needed_height(btn):
        """Return the exact compact height needed by one option card at its current width."""
        if btn is None or not hasattr(btn, "_option_description_label"):
            return 0

        featured = bool(getattr(btn, "_option_featured", False))
        margins = (18, 16, 18, 16) if featured else (16, 14, 16, 14)
        spacing = 15 if featured else 13
        icon_size = 56 if featured else 48

        # The grid may briefly report zero width while the main page is being constructed.
        # In that case the next layout/resize pass will calculate the real height.
        card_width = int(btn.width())
        if card_width <= 0:
            return (146 if featured else 88)

        text_width = max(1, card_width - margins[0] - margins[2] - icon_size - spacing)
        desc = btn._option_description_label
        desc_font = desc.font()
        desc_flags = (QtCore.Qt.TextFlag.TextWordWrap
                      | QtCore.Qt.AlignmentFlag.AlignLeft
                      | QtCore.Qt.AlignmentFlag.AlignTop)
        desc_height = 0
        try:
            desc_height = int(desc.heightForWidth(text_width))
        except Exception:
            desc_height = 0
        if desc_height <= 0:
            rect = QtGui.QFontMetrics(desc_font).boundingRect(
                QtCore.QRect(0, 0, text_width, 10000),
                int(desc_flags), str(desc.text()))
            desc_height = rect.height()
        desc_height = max(1, int(desc_height))

        title_lbl = btn._option_title_label
        title_height = max(1, QtGui.QFontMetrics(title_lbl.font()).height())
        eyebrow = getattr(btn, "_option_eyebrow_label", None)
        eyebrow_height = 0
        eyebrow_spacing = 0
        if eyebrow is not None and eyebrow.isVisible():
            eyebrow_height = QtGui.QFontMetrics(eyebrow.font()).height()
            eyebrow_spacing = 2

        # The icon and the text block share the same vertical top edge. The card only
        # needs to accommodate whichever is taller, plus the real layout margins.
        text_block_height = (eyebrow_height + eyebrow_spacing + title_height
                             + (5 if featured else 3) + desc_height)
        content_height = max(icon_size, text_block_height)
        return int(margins[1] + content_height + margins[3])

    def _update_option_section_heights(self):
        """Equalize cards within each section to that section's actual maximum content height."""
        groups = (
            getattr(self, "_featured_option_buttons", ()),
            getattr(self, "_tool_option_buttons", ()),
        )
        for buttons in groups:
            if not buttons:
                continue
            heights = [self._option_needed_height(btn) for btn in buttons]
            target = max(heights) if heights else 0
            if target <= 0:
                continue
            for btn in buttons:
                if btn.height() != target:
                    btn.setFixedHeight(target)

    def _make_contact_btn(self, parent_layout, fallback_text, bg, hover,
                          tooltip, url, icon_name=None,
                          fallback_font_size="16pt"):
        btn = QtWidgets.QPushButton()
        btn.setFixedSize(46, 46)
        btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        btn.setToolTip(tooltip)
        btn.setStyleSheet(f"""
            QPushButton {{
                background-color: {bg}; color: white;
                border: none; border-radius: 23px;
                font-size: {fallback_font_size}; font-weight: bold;
            }}
            QPushButton:hover {{ background-color: {hover}; }}
            QPushButton:pressed {{ background-color: {hover}; }}
        """)
        icon_loaded = False
        if icon_name:
            icon_path = os.path.join(ICONS_FOLDER, icon_name)
            icon = _render_svg_icon(icon_path, size=26)
            if icon is not None:
                btn.setIcon(icon)
                btn.setIconSize(QtCore.QSize(26, 26))
                icon_loaded = True
        if not icon_loaded:
            btn.setText(fallback_text)
        btn.clicked.connect(lambda _, u=url:
                            QtGui.QDesktopServices.openUrl(QtCore.QUrl(u)))
        parent_layout.addWidget(btn)
        return btn

    def _make_option_btn(self, title, subtitle, icon_name=None,
                         featured=False, eyebrow=None):
        btn = QtWidgets.QPushButton()
        # Section-level sizing is applied after the grid knows its real width.
        # That lets us size every card in a section to the tallest description
        # in that section, without leaving the old fixed-height empty space.
        btn.setSizePolicy(QtWidgets.QSizePolicy.Policy.Expanding,
                          QtWidgets.QSizePolicy.Policy.Fixed)
        btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        btn.setAccessibleName(title)
        btn.setToolTip(subtitle)
        btn.setStyleSheet(
            self._FEATURED_CARD_STYLE if featured else self._CARD_STYLE)

        root = QtWidgets.QHBoxLayout(btn)
        root.setContentsMargins(16 if not featured else 18,
                                14 if not featured else 16,
                                16 if not featured else 18,
                                14 if not featured else 16)
        root.setSpacing(13 if not featured else 15)
        root.setAlignment(QtCore.Qt.AlignmentFlag.AlignTop)

        icon_box = QtWidgets.QFrame()
        icon_box.setFixedSize(48 if not featured else 56,
                              48 if not featured else 56)
        icon_box.setStyleSheet("""
            QFrame {
                background: #202a33;
                border: 1px solid #33414e;
                border-radius: 12px;
            }
        """)
        icon_label = QtWidgets.QLabel(icon_box)
        icon_label.setGeometry(8 if not featured else 10,
                               8 if not featured else 10,
                               32 if not featured else 36,
                               32 if not featured else 36)
        icon_label.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        icon_label.setStyleSheet("background: transparent; border: none;")
        icon_label.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        if icon_name:
            icon = _render_svg_icon(
                os.path.join(ICONS_FOLDER, icon_name),
                size=32 if not featured else 36)
            if icon is not None:
                icon_label.setPixmap(
                    icon.pixmap(32 if not featured else 36,
                                32 if not featured else 36))
        root.addWidget(icon_box, 0, QtCore.Qt.AlignmentFlag.AlignTop)

        text_col = QtWidgets.QVBoxLayout()
        text_col.setContentsMargins(0, 0, 0, 0)
        text_col.setSpacing(3 if not featured else 5)

        if eyebrow:
            eyebrow_lbl = QtWidgets.QLabel(eyebrow)
            eyebrow_lbl.setStyleSheet(
                "font-size: 7.5pt; font-weight: 800; letter-spacing: 1.3px; "
                "color: #5f93bd; background: transparent; border: none;")
            eyebrow_lbl.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
            text_col.addWidget(eyebrow_lbl)

        title_lbl = QtWidgets.QLabel(title)
        title_lbl.setStyleSheet(
            ("font-size: 15.5pt;" if featured else "font-size: 11.5pt;") +
            " font-weight: 800; color: #f4f4f4; background: transparent; border: none;")
        title_lbl.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        text_col.addWidget(title_lbl)

        desc_lbl = QtWidgets.QLabel(subtitle)
        desc_lbl.setWordWrap(True)
        desc_lbl.setSizePolicy(QtWidgets.QSizePolicy.Policy.Expanding,
                               QtWidgets.QSizePolicy.Policy.Minimum)
        desc_lbl.setStyleSheet(
            ("font-size: 9.2pt; color: #9a9a9a;" if featured
             else "font-size: 8.8pt; color: #8c8c8c;") +
            " background: transparent; border: none; padding: 0; margin: 0;")
        desc_lbl.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        text_col.addWidget(desc_lbl)
        text_col.addStretch(1)
        root.addLayout(text_col, 1)

        btn._option_title_label = title_lbl
        btn._option_description_label = desc_lbl
        btn._option_icon_box = icon_box
        btn._option_featured = bool(featured)
        btn._option_eyebrow_label = eyebrow_lbl if eyebrow else None
        btn._option_root_layout = root
        btn._option_text_layout = text_col
        return btn


