class FileSelectPage(QtWidgets.QWidget):
    back_signal = QtCore.Signal()
    proceed_signal = QtCore.Signal(list)

    def __init__(self, title_text, next_label="Next", step_label=None,
                 unit_label="Pages", parent=None):
        super().__init__(parent)
        self.title_text = title_text
        self.next_label = next_label
        self.unit_label = unit_label

        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(30, 6, 30, 20)
        layout.setSpacing(10)

        title = QtWidgets.QLabel(title_text)
        title.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        title.setStyleSheet(
            "font-size: 24pt; font-weight: bold; color: #ffffff;")
        layout.addWidget(title)

        divider = QtWidgets.QFrame()
        divider.setFrameShape(QtWidgets.QFrame.Shape.HLine)
        divider.setStyleSheet(
            "background-color: #3a3a3a; border: none; max-height: 1px;")
        divider.setFixedHeight(1)
        layout.addWidget(divider)
        layout.addSpacing(4)

        header = QtWidgets.QHBoxLayout()
        header.setSpacing(10)

        select_label = QtWidgets.QLabel("Select Files")
        select_label.setStyleSheet(
            "font-size: 14pt; font-weight: bold; color: #e6e6e6;")
        header.addWidget(select_label)

        if step_label:
            step = QtWidgets.QLabel(step_label)
            step.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
            step.setStyleSheet("""
                background-color: #0a3a5c; color: #4a9eff;
                padding: 4px 12px; border-radius: 10px;
                font-weight: bold; font-size: 9pt;
            """)
            header.addWidget(step)

        header.addStretch()

        self.add_btn = QtWidgets.QPushButton(" Add PDFs")
        self.add_btn.setStyleSheet("""
            QPushButton {
                background-color: #0078d7; color: white;
                border: none; border-radius: 6px;
                padding: 8px 16px; font-weight: bold;
                text-align: left;
            }
            QPushButton:hover { background-color: #005fa3; }
        """)
        add_icon = _render_svg_icon(
            os.path.join(ICONS_FOLDER, "plus.svg"), size=16)
        if add_icon is not None:
            self.add_btn.setIcon(add_icon)
            self.add_btn.setIconSize(QtCore.QSize(16, 16))
        self.add_btn.clicked.connect(self.pick_files)
        header.addWidget(self.add_btn)

        self.reorder_btn = QtWidgets.QPushButton("Re-order by File Name")
        self.reorder_btn.setStyleSheet("""
            QPushButton {
                background-color: #2a2a2a; color: #f0f0f0;
                border: 1px solid #3a3a3a; border-radius: 6px;
                padding: 8px 16px; font-weight: bold;
            }
            QPushButton:hover { background-color: #3a3a3a; }
        """)
        self.reorder_btn.clicked.connect(self.reorder_by_name)
        header.addWidget(self.reorder_btn)

        self.clear_btn = QtWidgets.QPushButton("Clear All")
        self.clear_btn.setStyleSheet("""
            QPushButton {
                background-color: #2a2a2a; color: #f0f0f0;
                border: 1px solid #3a3a3a; border-radius: 6px;
                padding: 8px 16px; font-weight: bold;
            }
            QPushButton:hover { background-color: #3a3a3a; }
        """)
        self.clear_btn.clicked.connect(self.clear_files)
        header.addWidget(self.clear_btn)

        layout.addLayout(header)

        hint = QtWidgets.QLabel(
            "\u22ee\u22ee  Hold & drag files to set their custom order. "
            "Double click a file to open it.")
        hint.setStyleSheet(
            "color: #7a7a7a; font-style: italic; padding: 2px 0 4px 0;")
        layout.addWidget(hint)

        self.list_widget = DragDropFileList(unit_label=self.unit_label)
        self.list_widget.orderChanged.connect(self.update_stats)
        self.list_widget.editRequested.connect(self._on_edit_requested)
        self.list_widget.openPdfRequested.connect(self._on_open_pdf_requested)
        self.list_widget.removeFileRequested.connect(self._on_remove_file)
        layout.addWidget(self.list_widget, stretch=1)

        self.stats_row = QtWidgets.QHBoxLayout()
        self.stats_row.setSpacing(10)
        self.stats_label = QtWidgets.QLabel(
            f"0 files | 0 {self.unit_label.lower()} | 0.00 MB")
        self.stats_label.setStyleSheet("""
            background-color: #1e2a36; color: #4a9eff;
            padding: 8px 14px; border-radius: 6px; font-weight: bold;
        """)
        self.stats_row.addWidget(self.stats_label)
        self.stats_row.addStretch()
        layout.addLayout(self.stats_row)

        bottom = QtWidgets.QHBoxLayout()
        bottom.addStretch()

        back = QtWidgets.QPushButton("Back")
        back.setFixedWidth(110)
        back.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        back.setStyleSheet("""
            QPushButton {
                background-color: #2a2a2a; color: #f0f0f0;
                border: 1px solid #3a3a3a; border-radius: 6px;
                padding: 7px 18px; font-weight: bold; font-size: 11pt;
            }
            QPushButton:hover { background-color: #3a3a3a; }
        """)
        back.clicked.connect(self.back_signal.emit)
        bottom.addWidget(back)
        bottom.addSpacing(10)

        self.next_btn = QtWidgets.QPushButton(self.next_label)
        self.next_btn.setFixedWidth(160)
        self.next_btn.setEnabled(False)
        self.next_btn.setStyleSheet("""
            QPushButton {
                background-color: #0078d7; color: white;
                border: none; border-radius: 6px;
                padding: 7px 18px; font-weight: bold; font-size: 11pt;
            }
            QPushButton:hover { background-color: #005fa3; }
            QPushButton:disabled { background-color: #2a2a2a; color: #666; }
        """)
        self.next_btn.clicked.connect(self._proceed)
        bottom.addWidget(self.next_btn)
        layout.addLayout(bottom)

    def pick_files(self):
        files, _ = QtWidgets.QFileDialog.getOpenFileNames(
            self, "Select PDF Files", "",
            "PDF Files (*.pdf)",
            options=QtWidgets.QFileDialog.Option.DontUseNativeDialog)
        if files:
            self.list_widget.add_files(files)

    def reorder_by_name(self):
        self.list_widget.reorder_by_name()

    def clear_files(self):
        self.list_widget.clear_files()

    def update_stats(self):
        files = self.list_widget.files
        total = sum(f['pages'] for f in files)
        total_size = sum(f['size_mb'] for f in files)
        self.stats_label.setText(
            f"{len(files)} files | {total} {self.unit_label.lower()} | "
            f"{total_size:.2f} MB")
        self.next_btn.setEnabled(len(files) > 0)

    def _on_edit_requested(self, path):
        controller = _find_pdf_security_controller(self)
        if controller is not None and not controller._ensure_pdf_unlocked_for_use(
                path, context="opening Edit PDF"):
            return
        dlg = PageEditDialog(path, unit_label=self.unit_label, parent=self)
        dlg.exec()
        self.list_widget.refresh_file_page_counts()
        self.update_stats()

    def _on_open_pdf_requested(self, path):
        if not os.path.exists(path):
            QtWidgets.QMessageBox.warning(
                self, "Open Failed", f"File not found:\n{path}")
            return
        controller = _find_pdf_security_controller(self)
        if controller is not None and not controller._ensure_pdf_unlocked_for_use(
                path, context="opening the PDF"):
            return
        try:
            dlg = FullPdfViewer(path, page_idx=0, parent=self)
        except Exception as e:
            QtWidgets.QMessageBox.critical(
                self, "Open Failed", f"Could not open PDF:\n{e}")
            return
        dlg.exec()

    def _on_remove_file(self, path):
        self.list_widget.remove_file_by_path(path)
        self.update_stats()

    def _proceed(self):
        paths = [f['path'] for f in self.list_widget.files]
        if not paths:
            return
        missing = validate_files_exist(paths)
        if missing:
            bullet = "\n".join(f"  •  {p}" for p in missing)
            QtWidgets.QMessageBox.critical(
                self, "Files Missing",
                "Cannot continue — the following file(s) no longer exist "
                "on disk:\n\n" + bullet +
                "\n\nPlease remove them from the list and try again.")
            return
        self.proceed_signal.emit(paths)


