    def reset_for_new_session(self):
        """Return Step 2 to its fresh-entry defaults whenever Make Printable opens."""
        defaults = (
            (self.tile_remove_first, False),
            (self.tile_new_pdf, True),
            (self.tile_bookmark, True),
            (self.tile_optimize_pdf, True),
            (self.tile_page_numbers, True),
            (self.tile_slide_borders, True),
            (self.tile_cover, False),
            (self.tile_back_cover, False),
        )

        animation = getattr(self, "_cover_fields_anim", None)
        if animation is not None:
            try:
                animation.stop()
            except Exception:
                pass
            self._cover_fields_anim = None

        # Block only the two dependency-driving toggles while resetting; each tile
        # still receives its own visual refresh after the default is restored.
        blockers = [QtCore.QSignalBlocker(self.tile_cover)]
        try:
            for tile, checked in defaults:
                tile.setChecked(checked)
        finally:
            del blockers

        for tile, checked in defaults:
            try:
                tile._refresh(checked)
            except Exception:
                pass
        self.tile_invert_none.setChecked(True)
        for button, _mode in self._inversion_mode_buttons:
            try:
                button._refresh(button.isChecked())
            except Exception:
                pass

        for field in (self.inp_title, self.inp_chapter,
                      self.inp_subject, self.inp_student):
            field.clear()
        for label in (self.err_title, self.err_cs, self.err_student):
            label.clear()
            label.hide()

        self.slide_selector.setValue(3)

        animation = getattr(self, "_cover_fields_anim", None)
        if animation is not None:
            try:
                animation.stop()
            except Exception:
                pass
        self._cover_fields_anim = None
        self.cover_fields_widget.setMaximumHeight(0)
        self.cover_fields_widget.hide()
        self.tile_new_pdf.setEnabledState(True)
        self.tile_back_cover.setEnabledState(False)
        try:
            self._preferences_scroll.verticalScrollBar().setValue(0)
            self._preferences_scroll.horizontalScrollBar().setValue(0)
        except Exception:
            pass
        self._validate_live()

    def _animate_cover_fields(self, show):
        w = self.cover_fields_widget
        if getattr(self, '_cover_fields_anim', None) is not None:
            try:
                self._cover_fields_anim.stop()
            except Exception:
                pass
            self._cover_fields_anim = None
        if show:
            w.setVisible(True)
            w.setMaximumHeight(16777215)
            w.adjustSize()
            target_h = w.sizeHint().height()
            w.setMaximumHeight(0)
            start_h = 0
        else:
            start_h = max(0, w.height())
            target_h = 0
        anim = QtCore.QPropertyAnimation(w, b"maximumHeight")
        anim.setDuration(200)
        anim.setStartValue(start_h)
        anim.setEndValue(target_h)
        anim.setEasingCurve(QtCore.QEasingCurve.Type.OutCubic)
        def _on_finished():
            if show:
                w.setMaximumHeight(16777215)
            else:
                w.setVisible(False)
                w.setMaximumHeight(16777215)
        anim.finished.connect(_on_finished)
        self._cover_fields_anim = anim
        anim.start()

    def _sync_dependencies(self):
        self.tile_new_pdf.setEnabledState(True)

        if self.tile_cover.isChecked():
            self.tile_back_cover.setEnabledState(True)
            self._animate_cover_fields(show=True)
        else:
            if self.tile_back_cover.isChecked():
                self.tile_back_cover.setChecked(False)
            self.tile_back_cover.setEnabledState(False)
            self._animate_cover_fields(show=False)

        self._validate_live()

    def _on_slide_count_change(self, value):
        pass

    def _validate_live(self):
        if not self.tile_cover.isChecked():
            self.err_title.setVisible(False)
            self.err_cs.setVisible(False)
            self.err_student.setVisible(False)
            self.merge_btn.setEnabled(True)
            return
        title = self.inp_title.text()
        chapter = self.inp_chapter.text()
        subject = self.inp_subject.text()
        student = self.inp_student.text()
        ok = True

        title_err = False
        f_title = _font_or_none(FONT_TIMES_BOLD) or _fallback_font("Times-Bold")
        if f_title is not None:
            try:
                if f_title.text_length(title, fontsize=33) > self._TITLE_MAX:
                    title_err = True
            except Exception:
                pass
        if title_err:
            ok = False
            self.err_title.setText("Length limit exceeded. Try shorter.")
        self.err_title.setVisible(title_err)

        cs_err = False
        f_helv = _font_or_none(FONT_HELVETICA) or _fallback_font("helv")
        if f_helv is not None:
            try:
                static_chapter = "Chapter: "
                separator = "  |  Subject: "
                max_user_width = (self._CS_MAX
                                  - f_helv.text_length(static_chapter, fontsize=20)
                                  - f_helv.text_length(separator, fontsize=20))
                user_width = (f_helv.text_length(chapter, fontsize=20)
                              + f_helv.text_length(subject, fontsize=20))
                if user_width > max_user_width:
                    cs_err = True
            except Exception:
                pass
        if cs_err:
            ok = False
            self.err_cs.setText(
                "Length limit exceeded. Try shorter Chapter No or Subject "
                "(they are unified).")
        self.err_cs.setVisible(cs_err)

        st_err = False
        if f_helv is not None:
            try:
                if f_helv.text_length(student, fontsize=17) > self._STUDENT_MAX:
                    st_err = True
            except Exception:
                pass
        if st_err:
            ok = False
            self.err_student.setText("Length limit exceeded. Try shorter.")
        self.err_student.setVisible(st_err)
        self.merge_btn.setEnabled(ok)

    def _emit_merge(self):
        sc = self.slide_selector.value()
        slide_count_opt = 'A' if sc == 3 else ('B' if sc == 4 else 'C')
        cfg = {
            'remove_first': self.tile_remove_first.isChecked(),
            'new_pdf_indicator': self.tile_new_pdf.isChecked(),
            'pdf_bookmark': self.tile_bookmark.isChecked(),
            'inversion_mode': next(
                (mode for button, mode in self._inversion_mode_buttons
                 if button.isChecked()),
                "everything"),
            'page_numbers': self.tile_page_numbers.isChecked(),
            'slide_borders': self.tile_slide_borders.isChecked(),
            'cover_page': self.tile_cover.isChecked(),
            'back_cover': self.tile_back_cover.isChecked(),
            'title': self.inp_title.text().strip(),
            'chapter': self.inp_chapter.text().strip(),
            'subject': self.inp_subject.text().strip(),
            'student': self.inp_student.text().strip(),
            'slide_count': slide_count_opt,
            'optimize_pdf': self.tile_optimize_pdf.isChecked(),
        }
        self.merge_signal.emit(cfg)


