# MERGE-PDFs PAGE
# ============================================================
class MergePdfPage(FileSelectPage):
    def __init__(self, parent=None):
        super().__init__("Merge PDFs", "Merge", unit_label="Pages",
                         parent=parent)
        self.add_bookmarks_cb = QtWidgets.QCheckBox("Add Bookmarks")
        self.add_bookmarks_cb.setChecked(False)
        self.add_bookmarks_cb.setToolTip(
            "Add one bookmark per input file pointing to its first page.")
        self.add_bookmarks_cb.setStyleSheet("""
            QCheckBox {
                color: #f0f0f0;
                font-weight: bold;
                padding: 4px 8px;
            }
            QCheckBox::indicator {
                width: 16px; height: 16px;
                border: 1px solid #3a3a3a;
                border-radius: 3px;
                background-color: #2a2a2a;
            }
            QCheckBox::indicator:checked {
                background-color: #0078d7;
                border: 1px solid #0078d7;
            }
        """)
        self.stats_row.addWidget(self.add_bookmarks_cb)

        self.optimize_pdf_cb = QtWidgets.QCheckBox("Optimize PDF")
        self.optimize_pdf_cb.setChecked(False)
        self.optimize_pdf_cb.setToolTip(
            "Optimize the final merged PDF using the default Optimize PDF settings. "
            "The optimized file is used only when it is smaller and passes verification; "
            "otherwise the original merged PDF is retained.")
        self.optimize_pdf_cb.setStyleSheet(self.add_bookmarks_cb.styleSheet())
        self.stats_row.addWidget(self.optimize_pdf_cb)

    def reset_for_new_session(self):
        """Restore fresh-entry defaults whenever Merge PDFs is opened from the menu."""
        # These are per-run options, not persistent preferences. Block signals so a
        # future listener cannot start work while the page is being reset.
        blockers = [
            QtCore.QSignalBlocker(self.add_bookmarks_cb),
            QtCore.QSignalBlocker(self.optimize_pdf_cb),
        ]
        try:
            self.add_bookmarks_cb.setChecked(False)
            self.optimize_pdf_cb.setChecked(False)
        finally:
            del blockers

    def get_add_bookmarks(self):
        return self.add_bookmarks_cb.isChecked()

    def get_optimize_pdf(self):
        return self.optimize_pdf_cb.isChecked()


# ============================================================
# LIVE LOG VIEW STYLE
# ============================================================
def _apply_live_log_view_style(view):
    """Give every application log view the same explicit, visible scrollbar design."""
    view.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOn)
    view.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
    view.setStyleSheet("""
        QPlainTextEdit, QTextEdit {
            background-color: #0f0f0f;
            color: #d0d0d0;
            border: 1px solid #2a2a2a;
            border-radius: 6px;
            padding: 8px;
            font-family: 'Consolas', 'Courier New', monospace;
            font-size: 9.5pt;
        }
        QScrollBar:vertical {
            width: 11px;
            background: #171717;
            margin: 2px 2px 2px 0;
            border-radius: 5px;
        }
        QScrollBar::handle:vertical {
            background: #505050;
            min-height: 30px;
            border-radius: 5px;
        }
        QScrollBar::handle:vertical:hover {
            background: #666666;
        }
        QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical,
        QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
            background: none;
            border: none;
            height: 0px;
        }
        QScrollBar:horizontal {
            height: 11px;
            background: #171717;
            margin: 0 2px 2px 2px;
            border-radius: 5px;
        }
        QScrollBar::handle:horizontal {
            background: #505050;
            min-width: 30px;
            border-radius: 5px;
        }
        QScrollBar::handle:horizontal:hover {
            background: #666666;
        }
        QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal,
        QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
            background: none;
            border: none;
            width: 0px;
        }
    """)


