class ProgressDialog(QtWidgets.QDialog):
    cancel_requested = QtCore.Signal()
    skip_requested = QtCore.Signal()

    def __init__(self, parent=None, cancel_enabled=False):
        super().__init__(parent)
        self.setWindowTitle("Processing")
        self.setModal(True)
        self.setMinimumSize(620, 460)
        self.setWindowFlag(QtCore.Qt.WindowType.WindowCloseButtonHint, False)
        self.logs = []
        self._infinite_angle = 0
        self._infinite_timer = QtCore.QTimer(self)
        self._infinite_timer.timeout.connect(self._tick_spinner)
        self._progress_start_time = None
        self._last_progress_label = None
        self._eta_enabled = True
        self._cancel_requested = False
        self._skip_requested = False
        self._progress_complete_wait_timer = QtCore.QTimer(self)
        self._progress_complete_wait_timer.setSingleShot(True)
        self._progress_complete_wait_timer.timeout.connect(
            lambda: self.start_infinite("Please wait"))

        # Live logs follow the bottom by default. Scrolling upward permanently
        # unlocks the view until the user reaches the bottom again.
        self._log_follow_bottom = True
        self._log_internal_scroll = False
        self._log_user_action_serial = 0

        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(24, 24, 24, 24)
        layout.setSpacing(14)

        self.header = QtWidgets.QLabel("Working...")
        self.header.setStyleSheet(
            "font-size: 16pt; font-weight: bold; color: #fff;")
        self.header.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        layout.addWidget(self.header)

        self.spinner = _SpinnerWidget()
        self.spinner.setFixedHeight(60)
        self.spinner.hide()
        layout.addWidget(self.spinner)

        self.progress_bar = QtWidgets.QProgressBar()
        self.progress_bar.setRange(0, 100)
        self.progress_bar.setValue(0)
        self.progress_bar.setTextVisible(True)
        self.progress_bar.setFixedHeight(24)
        self.progress_bar.hide()
        layout.addWidget(self.progress_bar)

        self.progress_label = QtWidgets.QLabel("")
        self.progress_label.setStyleSheet(
            "color: #4a9eff; font-weight: bold;")
        self.progress_label.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.progress_label.hide()
        layout.addWidget(self.progress_label)

        log_label = QtWidgets.QLabel("Logs")
        log_label.setStyleSheet("color: #aaa; font-weight: bold;")
        layout.addWidget(log_label)

        self.log_view = QtWidgets.QPlainTextEdit()
        self.log_view.setReadOnly(True)
        _apply_live_log_view_style(self.log_view)
        layout.addWidget(self.log_view, stretch=1)

        self.cancel_row_widget = QtWidgets.QWidget()
        button_row = QtWidgets.QHBoxLayout(self.cancel_row_widget)
        button_row.setContentsMargins(0, 0, 0, 0)

        self.storage_notice_label = QtWidgets.QLabel("")
        self.storage_notice_label.setStyleSheet(
            "color: #f5b942; font-size: 9.5pt; font-weight: 600; padding-left: 2px;"
        )
        self.storage_notice_label.setVisible(False)
        button_row.addWidget(self.storage_notice_label)
        button_row.addStretch()

        self.skip_button = QtWidgets.QPushButton("Skip")
        self.skip_button.setFixedWidth(125)
        self.skip_button.setMinimumHeight(36)
        self.skip_button.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.skip_button.setStyleSheet("""
            QPushButton {
                background-color: #2a2a2a; color: #f0f0f0;
                border: 1px solid #3a3a3a; border-radius: 6px;
                padding: 8px 18px; font-weight: bold; font-size: 10.5pt;
            }
            QPushButton:hover { background-color: #353535; border-color: #4a9eff; }
            QPushButton:pressed { background-color: #222; }
            QPushButton:disabled { background-color: #242424; color: #666; }
        """)
        self.skip_button.clicked.connect(self.request_skip)
        self.skip_button.setVisible(False)
        button_row.addWidget(self.skip_button)

        self.cancel_button = QtWidgets.QPushButton("Cancel")
        self.cancel_button.setFixedWidth(145)
        self.cancel_button.setMinimumHeight(36)
        self.cancel_button.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.cancel_button.setStyleSheet("""
            QPushButton {
                background-color: #2a2a2a; color: #f0f0f0;
                border: 1px solid #3a3a3a; border-radius: 6px;
                padding: 8px 18px; font-weight: bold; font-size: 10.5pt;
            }
            QPushButton:hover { background-color: #353535; }
            QPushButton:pressed { background-color: #222; }
            QPushButton:disabled { background-color: #242424; color: #666; }
        """)
        self.cancel_button.clicked.connect(self.request_cancel)
        button_row.addWidget(self.cancel_button)
        self.cancel_row_widget.setVisible(bool(cancel_enabled))
        layout.addWidget(self.cancel_row_widget)

        log_bar = self.log_view.verticalScrollBar()
        log_bar.sliderPressed.connect(self._on_log_user_scroll_start)
        log_bar.sliderReleased.connect(self._on_log_slider_released)
        log_bar.rangeChanged.connect(self._on_log_range_changed)
        self.log_view.installEventFilter(self)
        self.log_view.viewport().installEventFilter(self)
        log_bar.installEventFilter(self)
        try:
            self.log_view.document().documentLayout().documentSizeChanged.connect(
                self._on_log_document_size_changed)
        except Exception:
            pass

    def _on_log_user_scroll_start(self):
        if self._log_internal_scroll:
            return
        self._log_user_action_serial += 1

    def _sync_follow_bottom_after_user_scroll(self):
        if self._log_internal_scroll:
            return
        bar = self.log_view.verticalScrollBar()
        self._log_follow_bottom = (bar.value() >= bar.maximum())

    def _on_log_slider_released(self):
        if self._log_internal_scroll:
            return
        self._sync_follow_bottom_after_user_scroll()

    def _queue_user_scroll_state_sync(self):
        QtCore.QTimer.singleShot(0, self._sync_follow_bottom_after_user_scroll)

    def eventFilter(self, obj, event):
        if not self._log_internal_scroll:
            scroll_event = False
            if obj is self.log_view.viewport():
                scroll_event = event.type() == QtCore.QEvent.Type.Wheel
            elif obj is self.log_view:
                if event.type() == QtCore.QEvent.Type.KeyPress:
                    scroll_event = event.key() in (
                        QtCore.Qt.Key.Key_Up, QtCore.Qt.Key.Key_Down,
                        QtCore.Qt.Key.Key_PageUp, QtCore.Qt.Key.Key_PageDown,
                        QtCore.Qt.Key.Key_Home, QtCore.Qt.Key.Key_End,
                        QtCore.Qt.Key.Key_Space,
                    )
            elif obj is self.log_view.verticalScrollBar():
                scroll_event = event.type() in (
                    QtCore.QEvent.Type.Wheel,
                    QtCore.QEvent.Type.MouseButtonPress,
                    QtCore.QEvent.Type.MouseMove,
                )
            if scroll_event:
                self._log_user_action_serial += 1
                self._queue_user_scroll_state_sync()
        return super().eventFilter(obj, event)

    def _set_log_bottom(self):
        bar = self.log_view.verticalScrollBar()
        self._log_internal_scroll = True
        blocker = QtCore.QSignalBlocker(bar)
        try:
            bar.setValue(bar.maximum())
        finally:
            del blocker
            self._log_internal_scroll = False

    def _on_log_range_changed(self, minimum, maximum):
        if self._log_internal_scroll or not self._log_follow_bottom:
            return
        # The scrollbar range can change after appendHtml returns. Follow the
        # real, newly calculated maximum rather than the old visible-range end.
        self._set_log_bottom()

    def _on_log_document_size_changed(self, size):
        if self._log_internal_scroll or not self._log_follow_bottom:
            return
        self._set_log_bottom()

    def _restore_log_position(self, follow_bottom, previous_value, user_serial):
        # Never override a newer real user scroll action. Internal scrollbar changes
        # caused by document growth do not increment this serial.
        if user_serial != self._log_user_action_serial:
            return
        if follow_bottom and self._log_follow_bottom:
            self._set_log_bottom()
            try:
                self.log_view.ensureCursorVisible()
            except Exception:
                pass
            return
        if not follow_bottom:
            bar = self.log_view.verticalScrollBar()
            self._log_internal_scroll = True
            blocker = QtCore.QSignalBlocker(bar)
            try:
                bar.setValue(max(bar.minimum(), min(previous_value, bar.maximum())))
            finally:
                del blocker
                self._log_internal_scroll = False

    def _schedule_log_position_sync(self, follow_bottom, previous_value, user_serial):
        # Qt updates the text document and scrollbar range lazily. A small set of
        # queued checks makes bottom-follow reliable even when the range is rebuilt
        # after the initial queued callback. Every check still respects the user's
        # latest scroll action.
        for delay in (0, 15, 50):
            QtCore.QTimer.singleShot(
                delay,
                lambda fb=follow_bottom, pv=previous_value, us=user_serial:
                self._restore_log_position(fb, pv, us))

    def showEvent(self, event):
        super().showEvent(event)
        # A loading dialog always opens locked to the newest log entry.
        self._log_follow_bottom = True
        QtCore.QTimer.singleShot(0, self._set_log_bottom)
        QtCore.QTimer.singleShot(30, self._set_log_bottom)

    def set_storage_notice(self, text):
        text = str(text or "")
        self.storage_notice_label.setText(text)
        self.storage_notice_label.setVisible(bool(text))

    def set_eta_enabled(self, enabled):
        self._eta_enabled = bool(enabled)
        if not self._eta_enabled:
            try:
                self.progress_label.setText("")
            except Exception:
                pass

    def set_cancel_enabled(self, enabled, text=None):
        enabled = bool(enabled)
        self.cancel_button.setEnabled(enabled)
        if text is not None:
            self.cancel_button.setText(str(text))

    def set_skip_enabled(self, enabled, text=None):
        enabled = bool(enabled)
        self.skip_button.setVisible(enabled)
        self.skip_button.setEnabled(enabled and not self._cancel_requested)
        if text is not None:
            self.skip_button.setText(str(text))

    def request_skip(self):
        if self._cancel_requested or self._skip_requested:
            return
        self._skip_requested = True
        self.append_log(
            "Skip requested; stopping thumbnail generation and preparing the editor without thumbnails...",
            "warning",
        )
        self.skip_button.setEnabled(False)
        self.skip_button.setText("Skipping...")
        self.cancel_button.setEnabled(False)
        try:
            self.skip_requested.emit()
        except Exception:
            pass
        # Reuse the existing cancellation checks in the thumbnail pipeline. The
        # PageEditDialog distinguishes this from ordinary Cancel and continues
        # into a temporary no-thumbnail editing session after cleanup.
        self._cancel_requested = True
        try:
            self.cancel_requested.emit()
        except Exception:
            pass

    def request_cancel(self):
        if self._cancel_requested:
            return
        self._cancel_requested = True
        self.skip_button.setEnabled(False)
        self.cancel_button.setEnabled(False)
        self.cancel_button.setText("Cancelling...")
        self.append_log("Cancellation requested; stopping the active job...", "warning")
        try:
            QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)
        except Exception:
            pass
        try:
            self.cancel_requested.emit()
        except Exception:
            pass

    def is_cancel_requested(self):
        return bool(self._cancel_requested)

    def closeEvent(self, event):
        event.ignore()

    def reject(self):
        pass

    def keyPressEvent(self, event):
        if event.key() == QtCore.Qt.Key.Key_Escape:
            event.ignore()
            return
        super().keyPressEvent(event)

    def append_log(self, msg, level="info"):
        self.append_logs([(msg, level)])

    def append_logs(self, entries):
        """Append one or many live log entries with a single document/layout update."""
        if not entries:
            return

        normalized = []
        for item in entries:
            try:
                msg, level = item
            except Exception:
                msg, level = str(item), "info"
            msg = str(msg)
            level = str(level or "info")
            normalized.append((msg, level))
            self.logs.append((msg, level))

        if not normalized:
            return

        color_map = {
            'info': '#d0d0d0', 'success': '#4ade80',
            'warning': '#f5b942', 'error': '#f87171'
        }
        prefix_map = {
            'info': '\u2022', 'success': '\u2714',
            'warning': '\u26a0', 'error': '\u2716'
        }

        fragments = []
        for msg, level in normalized:
            color = color_map.get(level, '#d0d0d0')
            prefix = prefix_map.get(level, '\u2022')
            safe = (msg.replace('&', '&amp;').replace('<', '&lt;')
                       .replace('>', '&gt;').replace('\n', '<br>'))
            fragments.append(f'<span style="color:{color};">{prefix} {safe}</span>')

        scroll_bar = self.log_view.verticalScrollBar()
        follow_bottom = bool(self._log_follow_bottom)
        previous_value = scroll_bar.value()
        user_serial = self._log_user_action_serial
        self._log_internal_scroll = True
        blocker = QtCore.QSignalBlocker(scroll_bar)
        try:
            self.log_view.appendHtml('<br>'.join(fragments))
        finally:
            del blocker
            self._log_internal_scroll = False

        self._schedule_log_position_sync(
            follow_bottom, previous_value, user_serial)
        try:
            self.log_view.viewport().update()
        except Exception:
            pass

    @staticmethod
    def _state_label(label):
        text = str(label or "Working").strip()
        text = text.rstrip(".")
        return (text + "...") if text else "Working..."

    def start_infinite(self, label="Working"):
        try:
            self._progress_complete_wait_timer.stop()
        except Exception:
            pass
        normalized = self._state_label(label)
        self.header.setText(normalized)
        self.progress_bar.hide()
        self.progress_label.hide()
        self.spinner.show()
        self._infinite_angle = 0
        self._infinite_timer.start(40)
        self._progress_start_time = None
        self._last_progress_label = None


    def stop_infinite(self):
        self._infinite_timer.stop()
        self.spinner.hide()

    def _tick_spinner(self):
        self._infinite_angle = (self._infinite_angle + 12) % 360
        self.spinner.set_angle(self._infinite_angle)

    def set_progress(self, value, total, label=""):
        try:
            self._progress_complete_wait_timer.stop()
        except Exception:
            pass
        self.spinner.hide()
        self._infinite_timer.stop()
        self.progress_bar.show()
        self.progress_label.show()
        normalized = self._state_label(label or "Working")
        if total <= 0:
            self.header.setText(normalized)
            return
        pct = int((value / total) * 100)
        self.progress_bar.setValue(pct)
        now = time.time()

        self.header.setText(normalized)
        if normalized != self._last_progress_label or self._progress_start_time is None:
            self._progress_start_time = now
            self._last_progress_label = normalized
        elapsed = now - self._progress_start_time
        no_eta_stage = normalized.casefold() in {
            "parsing pages...",
            "creating pages...",
            "extracting runtime...",
        }
        if normalized.casefold() == "downloading runtime...":
            value_mb = float(value) / (1024.0 * 1024.0)
            total_mb = float(total) / (1024.0 * 1024.0)
            if self._eta_enabled and value > 0 and elapsed > 0:
                remaining = max(0, (elapsed / value) * (total - value))
                rem_min = int(remaining // 60)
                rem_sec = int(remaining % 60)
                eta_str = f"ETA {rem_min:02d}:{rem_sec:02d}"
            else:
                eta_str = "ETA --:--"
            self.progress_label.setText(
                f"{value_mb:.2f}MB/{total_mb:.2f}MB  ({pct}%)  |  {eta_str}")
        elif self._eta_enabled and not no_eta_stage:
            if value > 0 and elapsed > 0:
                remaining = max(0, (elapsed / value) * (total - value))
                rem_min = int(remaining // 60)
                rem_sec = int(remaining % 60)
                eta_str = f"ETA {rem_min:02d}:{rem_sec:02d}"
            else:
                eta_str = "ETA --:--"
            self.progress_label.setText(
                f"{normalized}  {value}/{total}  ({pct}%)  |  {eta_str}")
        else:
            self.progress_label.setText(
                f"{normalized}  {value}/{total}  ({pct}%)")
        if int(value) >= int(total) and int(total) > 0:
            # Let Qt paint the 100% state first, then move to an indeterminate
            # state for any library work that is not externally measurable.
            self._progress_complete_wait_timer.start(160)


class _SpinnerWidget(QtWidgets.QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self._angle = 0
        self.setMinimumHeight(60)

    def set_angle(self, a):
        self._angle = a
        self.update()

    def paintEvent(self, event):
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing)
        cx = self.width() // 2
        cy = self.height() // 2
        radius = 20
        for i in range(12):
            alpha = int(255 * ((i + 1) / 12.0))
            color = QtGui.QColor(74, 158, 255, alpha)
            p.setPen(QtCore.Qt.PenStyle.NoPen)
            p.setBrush(color)
            angle = math.radians(self._angle + i * 30)
            x = cx + radius * math.cos(angle)
            y = cy + radius * math.sin(angle)
            p.drawEllipse(QtCore.QPointF(x, y), 3.5, 3.5)


