class _ScrollableDialogMixin:
    """Small helper for dialogs whose content can grow beyond the screen."""
    @staticmethod
    def make_scroll_container(parent):
        scroll = QtWidgets.QScrollArea(parent)
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setStyleSheet("""
            QScrollArea { border:none; background:#1e1e1e; }
            QScrollBar:vertical { width:10px; background:#1e1e1e; margin:2px 2px 2px 0; }
            QScrollBar::handle:vertical { background:#444; min-height:30px; border-radius:5px; }
            QScrollBar::handle:vertical:hover { background:#555; }
            QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical,
            QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background:none; border:none; }
            QScrollBar:horizontal { height:10px; background:#1e1e1e; margin:0 2px 2px 2px; }
            QScrollBar::handle:horizontal { background:#444; min-width:30px; border-radius:5px; }
            QScrollBar::handle:horizontal:hover { background:#555; }
            QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal,
            QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background:none; border:none; }
        """)
        content = QtWidgets.QWidget()
        content.setStyleSheet("background:#1e1e1e;")
        scroll.setWidget(content)
        return scroll, content


class PdfSecurityDetailsDialog(QtWidgets.QDialog):
    """Compact explanation of password behavior in DRM-protected and custom PDF apps."""
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("PDF Security Details")
        self.setModal(True)
        self.setFixedWidth(650)
        self.resize(650, 610)
        self.setMinimumSize(620, 560)

        outer = QtWidgets.QVBoxLayout(self)
        outer.setContentsMargins(24, 20, 24, 16)
        outer.setSpacing(10)

        title = QtWidgets.QLabel("PDF Security Details")
        title.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        title.setStyleSheet("font-size:21pt; font-weight:700; color:#fff;")
        outer.addWidget(title)
        outer.addSpacing(8)

        scroll, content = _ScrollableDialogMixin.make_scroll_container(self)
        form = QtWidgets.QVBoxLayout(content)
        form.setContentsMargins(0, 0, 0, 6)
        form.setSpacing(10)
        outer.addWidget(scroll, 1)

        intro = QtWidgets.QLabel(
            "This explains which password is required by traditional DRM-protected PDF apps and custom PDF apps.")
        intro.setWordWrap(True)
        intro.setStyleSheet("color:#bcbcbc; font-size:10pt;")
        form.addWidget(intro)

        # The dialog width is intentionally sized around this matrix rather than
        # leaving a large empty area to the right of a narrow chart.
        table_widths = [86, 118, 118, 118, 118]
        total_table_width = sum(table_widths) + 2

        chart_scroll = QtWidgets.QScrollArea()
        chart_scroll.setWidgetResizable(False)
        chart_scroll.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        chart_scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        chart_scroll.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        chart_scroll.setFixedWidth(total_table_width)
        chart_scroll.setFixedHeight(171)
        chart_scroll.setStyleSheet("""
            QScrollArea { border:1px solid #343434; border-radius:8px; background:#191919; }
            QScrollBar:horizontal { height:9px; background:#191919; margin:0 2px 2px 2px; }
            QScrollBar::handle:horizontal { background:#4a4a4a; min-width:28px; border-radius:4px; }
            QScrollBar::handle:horizontal:hover { background:#5b5b5b; }
            QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal,
            QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background:none; border:none; }
        """)

        table = QtWidgets.QTableWidget(5, 5)
        table.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        table.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        table.setEditTriggers(QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        table.setSelectionMode(QtWidgets.QAbstractItemView.SelectionMode.NoSelection)
        table.setFocusPolicy(QtCore.Qt.FocusPolicy.NoFocus)
        table.setShowGrid(True)
        table.setWordWrap(True)
        table.setFixedWidth(total_table_width)
        table.setFixedHeight(158)
        table.horizontalHeader().setVisible(False)
        table.verticalHeader().setVisible(False)
        for c, width in enumerate(table_widths):
            table.setColumnWidth(c, width)

        table.setSpan(0, 1, 1, 2)
        table.setSpan(0, 3, 1, 2)
        headers = {
            (0,0): "Security state",
            (0,1): "Minimum pass to enter for Viewing",
            (0,3): "Minimum pass to enter for Editing",
            (1,1): "Traditional App", (1,2): "Custom App",
            (1,3): "Traditional App", (1,4): "Custom App",
        }
        for (r, c), value in headers.items():
            item = QtWidgets.QTableWidgetItem(value)
            item.setTextAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
            item.setForeground(QtGui.QBrush(QtGui.QColor("#f0f0f0")))
            table_font = QtGui.QFont("DejaVu Sans")
            table_font.setPointSize(8)
            table_font.setWeight(QtGui.QFont.Weight.Bold)
            item.setFont(table_font)
            table.setItem(r, c, item)

        rows = [
            ("<span>Only </span><span style='color:#ef4444;'>●</span>", "None", "None",
             "<span style='color:#ef4444;'>●</span>", "None"),
            ("<span>Only </span><span style='color:#7fbf3f;'>●</span>",
             "<span style='color:#7fbf3f;'>●</span>", "<span style='color:#7fbf3f;'>●</span>",
             "<span style='color:#7fbf3f;'>●</span>", "<span style='color:#7fbf3f;'>●</span>"),
            ("<span>Both </span><span style='color:#ef4444;'>●</span> "
             "<span style='color:#7fbf3f;'>●</span>",
             "Either", "Either",
             "<span style='color:#ef4444;'>●</span>", "Either"),
        ]

        def make_cell(html):
            label = QtWidgets.QLabel(html)
            label.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
            label.setTextFormat(QtCore.Qt.TextFormat.RichText)
            label.setStyleSheet("color:#eeeeee; font-size:8.2pt; padding:0; margin:0;")
            label.setAttribute(QtCore.Qt.WidgetAttribute.WA_TranslucentBackground, True)
            return label

        for r, row_values in enumerate(rows, 2):
            for c, value in enumerate(row_values):
                table.setCellWidget(r, c, make_cell(value))

        row_heights = [32, 26, 27, 27, 27]
        for r, height in enumerate(row_heights):
            table.setRowHeight(r, height)

        table.setStyleSheet("""
            QTableWidget {
                background:#191919; color:#eeeeee;
                border:none; gridline-color:#454545;
                outline:none;
            }
            QTableWidget::item { padding:0; border:none; }
        """)
        chart_scroll.setWidget(table)
        form.addWidget(chart_scroll, 0, QtCore.Qt.AlignmentFlag.AlignLeft)

        legend = QtWidgets.QLabel(
            '<span style="color:#ef4444;">●</span> = Editing password, '
            '<span style="color:#7fbf3f;">●</span> = Viewing password')
        legend.setStyleSheet("font-size:9.5pt; color:#bcbcbc;")
        form.addWidget(legend)

