    def _show_status(self, status):
        self.plugin_spinner.hide()
        self._clear_list()
        if isinstance(status, dict) and "ocr" in status:
            self.list_layout.addWidget(self._make_plugin_card(status.get("ocr") or {}))
            self.list_layout.addWidget(
                self._make_pdf2docx_card(status.get("pdf2docx") or {}))
            self.list_layout.addWidget(
                self._make_libreoffice_card(status.get("libreoffice") or {}))
        else:
            # Backstop for any caller still providing the legacy OCR-only status dict.
            self.list_layout.addWidget(self._make_plugin_card(status or {}))
        note = QtWidgets.QLabel(
            "Each plugin is installed per-user in its own isolated environment or bundled runtime directory.")
        note.setWordWrap(True)
        note.setStyleSheet("color:#777; font-size:9pt; padding:4px 2px 2px 2px; border:none;")
        self.list_layout.addWidget(note)
        self.content_stack.setCurrentWidget(self.list_page)

    def _run_operation(self, task, title, success_text, initial_state=None, refresh=True, show_result=True):
        if _APP_SHUTTING_DOWN:
            return
        if self._operation_thread is not None and self._operation_thread.isRunning():
            return
        dialog = ProgressDialog(self, cancel_enabled=True)
        dialog.setWindowTitle(title)
        initial_state = initial_state or ("Working..." if not str(title).lower().startswith("updating ") else "Preparing update...")
        dialog.start_infinite(initial_state)
        dialog.append_log(f"{title} started.", "info")
        dialog.show()
        thread = PluginTaskThread(task, dialog)
        self._operation_thread = thread
        thread.log_signal.connect(dialog.append_log)
        thread.progress_signal.connect(dialog.set_progress)
        thread.infinite_signal.connect(
            lambda visible, label: dialog.start_infinite(label) if visible
            else dialog.stop_infinite())
        dialog.cancel_button.clicked.connect(thread.request_cancel)
        outcome = {"result": None, "error": None, "cancelled": False}

        def on_done(result):
            if outcome["cancelled"]:
                return
            outcome["result"] = result
            dialog.accept()

        def on_error(message):
            if outcome["cancelled"]:
                return
            outcome["error"] = message
            dialog.append_log(message, "error")
            dialog.accept()

        def on_cancelled():
            if outcome["cancelled"]:
                return
            outcome["cancelled"] = True
            dialog.accept()

        thread.result_signal.connect(on_done)
        thread.error_signal.connect(on_error)
        thread.cancelled_signal.connect(on_cancelled)

        def on_finished():
            self._operation_thread = None
            if outcome["cancelled"]:
                ResultDialog(
                    False,
                    "Operation aborted by user.",
                    dialog.logs,
                    self,
                    title_text="Operation Aborted",
                ).exec()
            elif outcome["error"]:
                if show_result:
                    ResultDialog(
                        False,
                        f"{title} failed:\n{outcome['error']}",
                        dialog.logs,
                        self,
                        title_text="Plugin Operation Failed",
                    ).exec()
            elif outcome["result"] and outcome["result"].get("ok"):
                if show_result:
                    if outcome["result"].get("no_update"):
                        plugin_name = str(outcome["result"].get("plugin") or title).strip()
                        current = outcome["result"].get("current_version")
                        latest = outcome["result"].get("latest_version")
                        if not current:
                            current_map = outcome["result"].get("current_versions") or {}
                            current = ", ".join(
                                f"{self._display_library_name(k)} {v}"
                                for k, v in current_map.items() if v
                            ) or None
                        if not latest:
                            latest_map = outcome["result"].get("latest_versions") or {}
                            latest = ", ".join(
                                f"{self._display_library_name(k)} {v}"
                                for k, v in latest_map.items() if v
                            ) or None
                        if current and latest and current != latest:
                            message = (
                                f"{plugin_name} is already up to date.\n\n"
                                f"Current version: {current}\n"
                                f"Latest checked: {latest}"
                            )
                        else:
                            message = f"{plugin_name} is already up to date."
                        ResultDialog(
                            True, message, dialog.logs, self, title_text="No Update Available"
                        ).exec()
                    else:
                        summary = str(outcome["result"].get("summary") or success_text)
                        partial = bool(outcome["result"].get("partial_failure"))
                        ResultDialog(
                            not partial,
                            summary,
                            dialog.logs,
                            self,
                            title_text=(
                                "Updates Completed with Warnings" if partial else
                                "Plugin Updated" if "Update" in title or "Updating" in title else
                                "Plugin Ready" if "Install" in title or "Acceleration" in title else
                                "Plugin Removed"
                            ),
                        ).exec()
            if refresh:
                self.refresh_plugins()

        thread.finished.connect(on_finished)
        thread.start()
        dialog.exec()
        if thread.isRunning():
            _stop_qthread(thread, timeout_ms=5000, force_wait_ms=2000)

    def _set_update_check_busy(self, busy):
        self.check_all_updates_btn.setEnabled(not busy)
        self.reload_btn.setEnabled(not busy)

    def _format_update_entries(self, result):
        entries = []
        preferred_order = ("paddleocr", "onnxruntime", "onnxruntime-gpu", "pdf2docx", "libreoffice")
        updates = result.get("updates") or {}
        ordered_packages = sorted(
            updates,
            key=lambda package: (
                preferred_order.index(package) if package in preferred_order else len(preferred_order),
                str(package).casefold(),
            ),
        )
        for package in ordered_packages:
            item = updates[package]
            entries.append({
                "package": package,
                "library": self._display_library_name(package),
                "current": str(item.get("current") or ""),
                "latest": str(item.get("latest") or ""),
            })
        return entries

    def _show_no_updates_dialog(self, plugin_name, result, logs):
        current_map = result.get("current_versions") or {}
        latest_map = result.get("latest_versions") or {}
        current = ", ".join(
            f"{self._display_library_name(k)} {v}"
            for k, v in current_map.items() if v
        )
        latest = ", ".join(
            f"{self._display_library_name(k)} {v}"
            for k, v in latest_map.items() if v
        )
        message = f"{plugin_name} is already up to date."
        if current and latest:
            message += f"\n\nCurrent version: {current}\nLatest checked: {latest}"
        ResultDialog(
            True, message, logs, self, title_text="No Update Available"
        ).exec()

    def _start_update_install(self, result):
        plugin_id = result.get("plugin_id")
        plugin_name = str(result.get("plugin") or _plugin_update_display_name(plugin_id))
        if plugin_id == OCR_PLUGIN_ID:
            task = _OCRUpdateTask(update_info=result)
            title = "Updating OCR Plugin"
            success = "OCR was updated, verified, and the new isolated environment is ready to use."
        elif plugin_id == PDF2DOCX_PLUGIN_ID:
            task = _Pdf2DocxUpdateTask(update_info=result)
            title = "Updating PDF2DOCX Plugin"
            success = "PDF to DOCX was updated, verified, and the new isolated environment is ready to use."
        elif plugin_id == LIBREOFFICE_PLUGIN_ID:
            task = _LibreOfficeInstallerTask(update=True, update_info=result)
            title = "Updating LibreOffice Runtime"
            success = "LibreOffice Runtime was updated, verified, and the new bundled runtime is ready for converters."
        else:
            raise ValueError(f"Unknown plugin id: {plugin_id}")
        self._run_operation(
            task, title, success, initial_state=f"Preparing {plugin_name} update..."
        )

    def _update_clicked(self):
        self._begin_update_check(OCR_PLUGIN_ID)

    def _update_pdf2docx_clicked(self):
        self._begin_update_check(PDF2DOCX_PLUGIN_ID)

    def _update_libreoffice_clicked(self):
        self._begin_update_check(LIBREOFFICE_PLUGIN_ID)

    def _check_all_updates_clicked(self):
        self._begin_update_check(None)

    def _begin_update_check(self, plugin_id):
        if _APP_SHUTTING_DOWN:
            return
        if self._scan_thread is not None and self._scan_thread.isRunning():
            return
        if self._operation_thread is not None and self._operation_thread.isRunning():
            return
        if self._update_check_thread is not None and self._update_check_thread.isRunning():
            return

        is_all = plugin_id is None
        task = _AllPluginsUpdateCheckTask() if is_all else _PluginUpdateCheckTask(plugin_id)
        title = "Checking for Plugin Updates" if is_all else f"Checking {_plugin_update_display_name(plugin_id)} Updates"
        dialog = ProgressDialog(self, cancel_enabled=True)
        dialog.setWindowTitle(title)
        dialog.start_infinite("Checking for updates...")
        dialog.show()
        QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.ExcludeUserInputEvents, 10)

        thread = PluginTaskThread(task, dialog)
        self._update_check_thread = thread
        self._set_update_check_busy(True)
        thread.log_signal.connect(dialog.append_log)
        thread.progress_signal.connect(dialog.set_progress)
        thread.infinite_signal.connect(
            lambda visible, label: dialog.start_infinite(label) if visible else dialog.stop_infinite()
        )
        dialog.cancel_button.clicked.connect(thread.request_cancel)
        outcome = {"result": None, "error": None, "cancelled": False}

        def on_done(result):
            if outcome["cancelled"]:
                return
            outcome["result"] = result
            dialog.accept()

        def on_error(message):
            if outcome["cancelled"]:
                return
            outcome["error"] = message
            dialog.append_log(message, "error")
            dialog.accept()

        def on_cancelled():
            if outcome["cancelled"]:
                return
            outcome["cancelled"] = True
            dialog.accept()

        thread.result_signal.connect(on_done)
        thread.error_signal.connect(on_error)
        thread.cancelled_signal.connect(on_cancelled)

        def on_finished():
            self._update_check_thread = None
            self._set_update_check_busy(False)

            if outcome["cancelled"]:
                ResultDialog(
                    False,
                    "Update check aborted by user.",
                    dialog.logs,
                    self,
                    title_text="Update Check Aborted",
                ).exec()
                return

            if outcome["error"]:
                ResultDialog(
                    False,
                    f"{title} failed:\n{outcome['error']}",
                    dialog.logs,
                    self,
                    title_text="Plugin Update Check Failed",
                ).exec()
                return

            result = outcome["result"] or {}
            if not is_all:
                updates = self._format_update_entries(result)
                if not updates:
                    self._show_no_updates_dialog(
                        str(result.get("plugin") or _plugin_update_display_name(plugin_id)),
                        result,
                        dialog.logs,
                    )
                    return
                confirm = PluginUpdateConfirmationDialog(
                    str(result.get("plugin") or _plugin_update_display_name(plugin_id)),
                    updates,
                    self,
                )
                if confirm.exec() == QtWidgets.QDialog.DialogCode.Accepted:
                    self._start_update_install(result)
                return

            plugin_results = result.get("plugins") or []
            entries = []
            for plugin_result in plugin_results:
                updates = self._format_update_entries(plugin_result)
                if updates:
                    entries.append({
                        "plugin_id": plugin_result.get("plugin_id"),
                        "plugin": plugin_result.get("plugin") or _plugin_update_display_name(plugin_result.get("plugin_id")),
                        "updates": updates,
                        "check_result": plugin_result,
                    })

            if not entries:
                errors = result.get("errors") or {}
                if errors:
                    detail = "\n".join(
                        f"{_plugin_update_display_name(pid)}: {message}"
                        for pid, message in errors.items()
                    )
                    message = "No updates were confirmed, but some plugins could not be checked.\n\n" + detail
                    ResultDialog(
                        False, message, dialog.logs, self, title_text="Update Check Incomplete"
                    ).exec()
                else:
                    ResultDialog(
                        True,
                        "All installed plugins are already up to date.",
                        dialog.logs,
                        self,
                        title_text="No Updates Available",
                    ).exec()
                return

            errors = result.get("errors") or {}
            confirm = PluginUpdateSelectionDialog(entries, errors=errors, parent=self)
            if confirm.exec() != QtWidgets.QDialog.DialogCode.Accepted:
                return
            selected = confirm.selected_entries()
            if not selected:
                return
            selected_results = [entry["check_result"] for entry in selected]
            self._run_selected_plugin_updates(selected_results)

        thread.finished.connect(on_finished)
        thread.start()
        dialog.exec()

    def _run_selected_plugin_updates(self, selected_results):
        task = _PluginBatchUpdateTask(selected_results)
        self._run_operation(
            task,
            "Updating Selected Plugins",
            "Selected plugin updates were installed and verified.",
            initial_state="Preparing plugin updates...",
        )

