class _IndependentSettingsWindow(QtWidgets.QDialog):
    """Independent application-modal Settings window."""
    def __init__(self, page, parent=None):
        # Deliberately do not parent this top-level window to MainWindow.
        # ApplicationModal provides the same back-layer input lock as Edit PDF.
        super().__init__(None)
        self.page = page
        self._accepting_from_close_event = False
        self.setWindowTitle("Mergerz — Settings")
        self.setModal(True)
        self.setWindowModality(QtCore.Qt.WindowModality.ApplicationModal)
        self.setWindowFlags(
            QtCore.Qt.WindowType.Window |
            QtCore.Qt.WindowType.WindowTitleHint |
            QtCore.Qt.WindowType.WindowSystemMenuHint |
            QtCore.Qt.WindowType.WindowMinimizeButtonHint |
            QtCore.Qt.WindowType.WindowCloseButtonHint
        )
        self.setMinimumSize(760, 620)
        self.resize(820, 700)
        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)
        layout.addWidget(page)
        page.back_signal.connect(self._close_from_page)

    def _close_from_page(self):
        self.accept()

    def closeEvent(self, event):
        # Preserve Settings' existing unsaved-changes confirmation when the user
        # clicks the native window close button.  Guard the accept() path so the
        # nested QDialog close event cannot recursively re-enter _request_close().
        if self._accepting_from_close_event:
            event.accept()
            return
        self._accepting_from_close_event = True
        try:
            self.page._request_close()
        except Exception:
            self.accept()
        event.ignore()
        self._accepting_from_close_event = False


class _IndependentPluginsWindow(QtWidgets.QDialog):
    """Independent application-modal Plugins window."""
    def __init__(self, page, parent=None):
        # Deliberately do not parent this top-level window to MainWindow.
        # ApplicationModal keeps the main menu and Edit PDF blocked underneath.
        super().__init__(None)
        self.page = page
        self.setWindowTitle("Mergerz — Plugins")
        self.setModal(True)
        self.setWindowModality(QtCore.Qt.WindowModality.ApplicationModal)
        self.setWindowFlags(
            QtCore.Qt.WindowType.Window |
            QtCore.Qt.WindowType.WindowTitleHint |
            QtCore.Qt.WindowType.WindowSystemMenuHint |
            QtCore.Qt.WindowType.WindowMinimizeButtonHint |
            QtCore.Qt.WindowType.WindowCloseButtonHint
        )
        self.setMinimumSize(720, 540)
        self.resize(820, 680)
        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)
        layout.addWidget(page)
        page.close_requested.connect(self._close_from_page)

    def _close_from_page(self):
        self.accept()

    def closeEvent(self, event):
        try:
            self.page.shutdown_threads()
        except Exception:
            pass
        event.accept()


class _IndependentWorkflowWindow(QtWidgets.QDialog):
    """Independent application-modal workflow window used by Merge/Printable."""
    def __init__(self, title, pages, minimum_size=(1000, 720),
                 initial_size=(1180, 780), parent=None):
        super().__init__(None)
        self.setWindowTitle(title)
        self.setModal(True)
        self.setWindowModality(QtCore.Qt.WindowModality.ApplicationModal)
        self.setWindowFlags(
            QtCore.Qt.WindowType.Window |
            QtCore.Qt.WindowType.WindowTitleHint |
            QtCore.Qt.WindowType.WindowSystemMenuHint |
            QtCore.Qt.WindowType.WindowMinimizeButtonHint |
            QtCore.Qt.WindowType.WindowCloseButtonHint
        )
        self.setMinimumSize(*minimum_size)
        self.resize(*initial_size)
        self.page_stack = QtWidgets.QStackedWidget()
        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)
        layout.addWidget(self.page_stack)
        for page in pages:
            self.page_stack.addWidget(page)

    def show_page(self, index):
        if 0 <= int(index) < self.page_stack.count():
            self.page_stack.setCurrentIndex(int(index))
            try:
                self.page_stack.currentWidget().setFocus(QtCore.Qt.FocusReason.OtherFocusReason)
            except Exception:
                pass

    def _close(self):
        self.reject()


class _ImageOptimizationTask:
    """Background task for Optimize Images.

    The task deliberately contains *all* Pillow/image-processing orchestration outside the
    Qt GUI thread.  The GUI only receives queued progress/log/result signals from
    PluginTaskThread, so even the single-process path cannot block painting of ProgressDialog.
    """

    def __init__(self, input_paths, output_paths, output_folder, target_format, settings, total):
        self.input_paths = [os.path.abspath(str(p)) for p in input_paths]
        self.output_paths = [os.path.abspath(str(p)) for p in output_paths]
        self.output_folder = os.path.abspath(str(output_folder))
        self.target_format = str(target_format or "jpg").lower()
        self.settings = dict(settings or {})
        self.total = int(total)
        self._cancel_requested = threading.Event()

    def cancel(self):
        self._cancel_requested.set()

    def _cancelled(self, runner):
        return self._cancel_requested.is_set() or runner.is_cancelled()

    def _cleanup_generated(self):
        for path in self.output_paths:
            try:
                if os.path.isfile(path):
                    os.remove(path)
            except Exception:
                pass

    @staticmethod
    def _terminate_processes(processes):
        for process in processes:
            try:
                if process.is_alive():
                    process.terminate()
            except Exception:
                pass
        for process in processes:
            try:
                process.join(timeout=2.0)
            except Exception:
                pass
        for process in processes:
            try:
                if process.is_alive():
                    process.kill()
            except Exception:
                pass
        for process in processes:
            try:
                process.join(timeout=1.0)
            except Exception:
                pass

    def run(self, runner):
        output_folder = self.output_folder
        target_format = self.target_format
        label = target_format.upper()
        total = self.total
        settings = dict(self.settings)

        if target_format not in _IMAGE_OPT_FORMATS or total <= 0:
            raise ValueError(f"Unsupported output format or empty image selection: {target_format}")

        os.makedirs(output_folder, exist_ok=True)

        runner.log(f"Starting {label} image processing for {total} selected image(s)...", "info")
        runner.log(f"Output format: {label}", "info")
        runner.log(f"Output folder: {output_folder}", "info")
        runner.log(
            f"Resolution: {int(round(settings.get('scale_percent', 100)))}%", "info")
        runner.log(
            f"Metadata: {'Keep' if str(settings.get('metadata')).lower() == 'keep' else 'Remove'}",
            "info")

        if target_format == "jpg":
            runner.log(
                f"JPEG: quality {int(settings.get('jpeg_quality', 85))}, "
                f"optimize encoding {'On' if settings.get('jpeg_optimize', True) else 'Off'}, "
                f"progressive {'On' if settings.get('jpeg_progressive', True) else 'Off'}, "
                f"chroma {settings.get('jpeg_subsampling', 'auto')}",
                "info")
        elif target_format == "webp":
            mode = str(settings.get('webp_mode') or 'lossy').capitalize()
            log_text = f"WebP: {mode}, method {int(settings.get('webp_method', 4))}"
            if mode.lower() == "lossy":
                log_text += f", quality {int(settings.get('webp_quality', 80))}"
            runner.log(log_text, "info")
        else:
            png_optimize = bool(settings.get('png_optimize', True))
            png_level = 9 if png_optimize else max(
                0, min(9, int(settings.get('png_compression', 9))))
            if png_optimize:
                png_text = (
                    f"PNG: optimize encoding On, compression level {png_level} "
                    f"(muted; Pillow uses level 9), "
                )
            else:
                png_text = f"PNG: optimize encoding Off, compression level {png_level}, "
            runner.log(
                png_text +
                f"interlacing {settings.get('png_interlace', 'none')}, "
                f"color reduction {settings.get('png_color_reduction', 'off')}",
                "info")

        try:
            image_cfg = APP_SETTINGS["multiprocessing"]["image_generation"]
            requested_workers = int(image_cfg["processes"])
            threshold = int(image_cfg["pages_threshold"])
        except Exception:
            requested_workers = DEFAULT_CPU_WORKER_COUNT
            threshold = 4

        actual_workers = _effective_worker_count(total, requested_workers)
        use_mp = total > threshold and actual_workers > 1
        runner.log(
            f"Generation mode: {'MP' if use_mp else 'SP'} — "
            f"{actual_workers if use_mp else 1} process(es) "
            f"(MP starts above {threshold} pages/images; configured {requested_workers} workers).",
            "info")
        runner.progress(0, max(1, total), "Processing images")

        tasks = [
            {
                "task_index": index,
                "input_path": self.input_paths[index],
                "output_path": self.output_paths[index],
            }
            for index in range(total)
        ]

        worker_errors = []
        results = {}
        received = 0

        if use_mp:
            ranges = _build_page_ranges(total, actual_workers)
            chunks = [[tasks[i] for i in range(start, end + 1)] for start, end in ranges]
            for worker_index, (start, end) in enumerate(ranges):
                runner.log(
                    f"  Worker {worker_index + 1}: pages/images {start + 1}–{end + 1}",
                    "info")

            ctx = multiprocessing.get_context("spawn")
            result_queue = ctx.Queue(maxsize=max(10, actual_workers * 2))
            processes = []
            completed_workers = set()
            cancelled = False
            try:
                for worker_index, chunk in enumerate(chunks):
                    if self._cancelled(runner):
                        cancelled = True
                        break
                    process = ctx.Process(
                        target=_optimize_images_worker,
                        args=(chunk, settings, worker_index, result_queue),
                    )
                    process.daemon = False
                    processes.append(process)

                for process in processes:
                    if self._cancelled(runner):
                        cancelled = True
                        break
                    process.start()

                while not cancelled and len(completed_workers) < len(processes):
                    if self._cancelled(runner):
                        cancelled = True
                        break
                    try:
                        message = result_queue.get(timeout=0.20)
                    except queue.Empty:
                        if processes and all(not p.is_alive() for p in processes):
                            break
                        continue

                    kind, worker_index, task_index, out_path, old_size, new_size, width, height, error = message[:9]
                    fallback_used = bool(message[9]) if len(message) > 9 else False
                    worker_index = int(worker_index)
                    if kind == "worker_done":
                        completed_workers.add(worker_index)
                        continue

                    received += 1
                    if kind == "done":
                        results[int(task_index)] = {
                            "output_path": str(out_path),
                            "original_size": int(old_size),
                            "output_size": int(new_size),
                            "width": int(width),
                            "height": int(height),
                            "fallback_used": fallback_used,
                        }
                    else:
                        worker_errors.append(
                            f"Image {int(task_index) + 1}: {error or 'processing failed'}")

                    runner.progress(received, max(1, total), "Processing images")
                    if received == 1 or received == total or received % 10 == 0:
                        runner.log(f"  Processed {received}/{total} image(s)", "info")
            finally:
                if cancelled or self._cancelled(runner):
                    self._terminate_processes(processes)
                else:
                    for process in processes:
                        try:
                            process.join(timeout=2.0)
                        except Exception:
                            pass
                    for process in processes:
                        try:
                            if process.is_alive():
                                process.terminate()
                        except Exception:
                            pass
                    for process in processes:
                        try:
                            process.join(timeout=1.0)
                        except Exception:
                            pass
                try:
                    result_queue.close()
                    result_queue.join_thread()
                except Exception:
                    pass

            if cancelled or self._cancelled(runner):
                self._cleanup_generated()
                return {"cancelled": True}

            if received < total:
                worker_errors.append(
                    f"{total - received} image task(s) did not return a worker result.")
        else:
            # IMPORTANT: this loop is inside PluginTaskThread, never the GUI thread.
            # This fixes the intermittent invisible/frozen ProgressDialog for SP jobs.
            for index, task in enumerate(tasks):
                if self._cancelled(runner):
                    self._cleanup_generated()
                    return {"cancelled": True}
                try:
                    result = _process_one_image_with_pillow(
                        task["input_path"], task["output_path"], settings)
                    results[index] = {
                        "output_path": task["output_path"],
                        "original_size": int(result["original_size"]),
                        "output_size": int(result["output_size"]),
                        "width": int(result["width"]),
                        "height": int(result["height"]),
                        "fallback_used": bool(result.get("fallback_used", False)),
                    }
                except Exception as exc:
                    worker_errors.append(
                        f"Image {index + 1}: {type(exc).__name__}: {exc}")
                runner.progress(index + 1, max(1, total), "Processing images")
                if index == 0 or index + 1 == total or (index + 1) % 10 == 0:
                    runner.log(f"  Processed {index + 1}/{total} image(s)", "info")

        if self._cancelled(runner):
            self._cleanup_generated()
            return {"cancelled": True}

        unresolved = [
            i for i in range(total)
            if i not in results or not os.path.isfile(results[i]["output_path"])
        ]
        if unresolved or worker_errors:
            self._cleanup_generated()
            runner.log(
                f"Could not completely process "
                f"{len(unresolved) + (0 if unresolved else len(worker_errors))} image task(s); "
                f"partial output was removed.",
                "error")
            return {
                "failed": True,
                "worker_errors": worker_errors,
            }

        original_total = sum(int(results[i]["original_size"]) for i in range(total))
        output_total = sum(int(results[i]["output_size"]) for i in range(total))
        fallback_count = sum(
            1 for i in range(total) if results[i].get("fallback_used", False))

        if fallback_count:
            runner.log(
                f"Size guard: {fallback_count} same-type candidate(s) were larger than the source; "
                f"original file bytes were copied instead.",
                "warning")

        runner.log(f"Processed {total} {label} image(s).", "success")
        runner.log(f"Original size: {format_file_size(original_total)}", "info")
        runner.log(f"Output size: {format_file_size(output_total)}", "success")

        return {
            "success": True,
            "results": results,
            "worker_errors": worker_errors,
            "original_total": int(original_total),
            "output_total": int(output_total),
            "fallback_count": int(fallback_count),
        }


class MainWindow(QtWidgets.QMainWindow):
    def __init__(self):
        super().__init__()
        self.setWindowTitle("Mergerz")
        self.setMinimumSize(900, 700)
        self.resize(920, 720)
        self._pending_slides_paths = []
        self._active_bridge = None
        self._active_plugin_conversion_thread = None
        self._active_workflow_window = None
        self._mergerz_update_check_thread = None
        self._mergerz_update_install_thread = None
        self._mergerz_update_version = None

        self.stack = QtWidgets.QStackedWidget()
        self.setCentralWidget(self.stack)

        self.menu_page = MainMenuPage()
        self.menu_page.settings_clicked.connect(self.open_settings)
        self.menu_page.mergerz_update_requested.connect(self._start_mergerz_update)
        self.menu_page.open_pdf_clicked.connect(self.open_pdf_from_menu)
        self.menu_page.edit_pdf_clicked.connect(self.edit_pdf_from_menu)
        self.menu_page.merge_pdfs_clicked.connect(self.open_merge_pdfs)
        self.menu_page.merge_slides_clicked.connect(self.open_merge_slides)
        self.menu_page.lock_unlock_clicked.connect(self.open_pdf_security)
        self.menu_page.optimize_pdf_clicked.connect(self.open_pdf_optimizer)
        self.menu_page.optimize_images_clicked.connect(self.open_optimize_images)
        self.menu_page.converters_clicked.connect(self.open_converters)
        self.menu_page.plugins_clicked.connect(self.open_plugins)
        self.stack.addWidget(self.menu_page)

        self.settings_page = AppSettingsPage()
        self.settings_window = _IndependentSettingsWindow(self.settings_page)
        self.settings_window.hide()

        self.plugins_page = PluginsPage()
        self.plugins_window = _IndependentPluginsWindow(self.plugins_page)
        self.plugins_window.hide()

        self.merge_pdfs_page = MergePdfPage()
        self.merge_pdfs_page.proceed_signal.connect(self.run_merge_pdfs)
        self.merge_pdfs_page.back_signal.connect(
            lambda: self.merge_pdfs_window.reject())
        self.merge_pdfs_window = _IndependentWorkflowWindow(
            "Mergerz — Merge PDFs",
            [self.merge_pdfs_page],
            minimum_size=(760, 640),
            initial_size=(800, 700))
        self.merge_pdfs_window.hide()

        self.merge_slides_page = FileSelectPage(
            "Make Printable Slides", "Next", step_label="STEP 1",
            unit_label="Slides")
        self.merge_slides_page.back_signal.connect(
            lambda: self.merge_slides_window.reject())
        self.merge_slides_page.proceed_signal.connect(self.open_preferences)

        self.prefs_page = PreferencesPage()
        self.prefs_page.back_signal.connect(
            lambda: self.merge_slides_window.show_page(0))
        self.prefs_page.home_signal.connect(
            lambda: self.merge_slides_window.reject())
        self.prefs_page.merge_signal.connect(self.run_merge_slides)
        self.merge_slides_window = _IndependentWorkflowWindow(
            "Mergerz — Make Printable Slides",
            [self.merge_slides_page, self.prefs_page],
            minimum_size=(760, 640),
            initial_size=(800, 700))
        self.merge_slides_window.hide()

        QtCore.QTimer.singleShot(80, self._initial_storage_refresh)

    def _initial_storage_refresh(self):
        try:
            self.menu_page.refresh_storage(animate=True)
        except Exception:
            pass

    def _begin_mergerz_update_check(self):
        """Check for a newer Mergerz release after the main window is already visible."""
        if MERGERZ_TEST_MODE or _APP_SHUTTING_DOWN:
            return
        thread = self._mergerz_update_check_thread
        if thread is not None and thread.isRunning():
            return
        install_thread = self._mergerz_update_install_thread
        if install_thread is not None and install_thread.isRunning():
            return

        self.menu_page.set_mergerz_update_checking()
        thread = PluginTaskThread(_MergerzUpdateCheckTask(), None)
        self._mergerz_update_check_thread = thread

        def on_result(result):
            if _APP_SHUTTING_DOWN:
                return
            result = result or {}
            if result.get("update_available"):
                latest = str(result.get("latest_version") or "").strip()
                self._mergerz_update_version = latest or None
                self.menu_page.set_mergerz_update_version(latest)
                self.menu_page.show_mergerz_update_available(latest)
            else:
                self._mergerz_update_version = None
                self.menu_page.hide_mergerz_update_footer()

        def on_error(_message):
            # Startup update checks are intentionally silent. Offline/network/API
            # failures are treated exactly like "no update" for the user.
            if not _APP_SHUTTING_DOWN:
                self.menu_page.hide_mergerz_update_footer()

        def on_finished():
            self._mergerz_update_check_thread = None

        thread.result_signal.connect(on_result)
        thread.error_signal.connect(on_error)
        thread.cancelled_signal.connect(
            lambda: self.menu_page.hide_mergerz_update_footer()
        )
        thread.finished.connect(on_finished)
        thread.start()

    def _start_mergerz_update(self, requested_version=""):
        """Install the exact advertised Mergerz release, then request an app restart."""
        if MERGERZ_TEST_MODE or _APP_SHUTTING_DOWN:
            return

        version = str(requested_version or self._mergerz_update_version or "").strip()
        if not version:
            return
        current_version = _installed_mergerz_version()
        if not _version_is_newer(version, current_version):
            self.menu_page.hide_mergerz_update_footer()
            return

        thread = self._mergerz_update_install_thread
        if thread is not None and thread.isRunning():
            return

        self._mergerz_update_version = version
        self.menu_page.set_mergerz_update_installing()

        dialog = ProgressDialog(self, cancel_enabled=False)
        dialog.setWindowTitle("Updating Mergerz")
        dialog.start_infinite(f"Installing Mergerz v{version}...")
        dialog.append_log(
            f"Preparing to update Mergerz from {current_version} to {version}.",
            "info",
        )
        dialog.append_log(
            "The running application's Python environment will be updated.",
            "info",
        )
        dialog.append_log(
            "Cancellation is disabled because this update replaces the running application package.",
            "info",
        )
        dialog.show()
        QtWidgets.QApplication.processEvents(
            QtCore.QEventLoop.ProcessEventsFlag.ExcludeUserInputEvents, 10
        )

        task = _MergerzUpdateInstallTask(version)
        thread = PluginTaskThread(task, dialog)
        self._mergerz_update_install_thread = thread
        outcome = {"result": None, "error": None, "cancelled": False}

        thread.log_signal.connect(dialog.append_log)
        thread.progress_signal.connect(dialog.set_progress)
        thread.infinite_signal.connect(
            lambda visible, label: dialog.start_infinite(label)
            if visible else dialog.stop_infinite()
        )

        def on_done(result):
            if outcome["cancelled"]:
                return
            outcome["result"] = result
            dialog.start_infinite("Restarting Mergerz...")
            dialog.append_log(
                "Mergerz was updated successfully. Restarting the application...",
                "success",
            )
            QtCore.QTimer.singleShot(450, dialog.accept)

        def on_error(message):
            if outcome["cancelled"]:
                return
            outcome["error"] = message
            dialog.append_log(message, "error")
            dialog.accept()

        def on_cancelled():
            if outcome["cancelled"]:
                return
            outcome["cancelled"] = True
            dialog.accept()

        thread.result_signal.connect(on_done)
        thread.error_signal.connect(on_error)
        thread.cancelled_signal.connect(on_cancelled)

        def on_finished():
            global _RESTART_AFTER_UPDATE
            self._mergerz_update_install_thread = None

            if outcome["cancelled"]:
                self.menu_page.show_mergerz_update_available(version)
                return

            if outcome["error"]:
                self.menu_page.show_mergerz_update_available(version)
                ResultDialog(
                    False,
                    f"Mergerz update failed:\n{outcome['error']}",
                    dialog.logs,
                    self,
                    title_text="Mergerz Update Failed",
                ).exec()
                return

            result = outcome["result"] or {}
            if result.get("ok") and result.get("restart_required"):
                # Do NOT call QApplication.quit() from inside dialog.exec().
                # ProgressDialog runs a nested Qt event loop, and requesting the
                # application's outer event loop to quit from that nested loop can
                # leave the main event loop alive until the user manually closes
                # the window. We request the restart only after dialog.exec() has
                # returned below.
                _RESTART_AFTER_UPDATE = True
                try:
                    self.menu_page.mergerz_update_footer.hide()
                except Exception:
                    pass
            else:
                self.menu_page.show_mergerz_update_available(version)
                ResultDialog(
                    False,
                    "Mergerz was not restarted because the update could not be verified.",
                    dialog.logs,
                    self,
                    title_text="Mergerz Update Incomplete",
                ).exec()

        thread.finished.connect(on_finished)
        thread.start()
        dialog.exec()
        if thread.isRunning():
            _stop_qthread(thread, timeout_ms=5000, force_wait_ms=2000)

        # The ProgressDialog's nested event loop has now returned. This is the safe
        # point to request exit from the application's outer event loop. Queue the
        # quit so this slot can return cleanly before QApplication.exec() unwinds.
        result = outcome["result"] or {}
        if (not outcome["cancelled"] and not outcome["error"]
                and result.get("ok") and result.get("restart_required")):
            global _RESTART_AFTER_UPDATE
            _RESTART_AFTER_UPDATE = True
            QtCore.QTimer.singleShot(0, QtWidgets.QApplication.quit)

    def closeEvent(self, event):
        # Shutdown is deliberately split into two phases.  Stop background/native
        # work while every owner widget is still alive, but DO NOT destroy QObjects
        # from inside MainWindow.closeEvent. Qt may still be unwinding other window
        # close handlers at this point. Final native-object disposal is performed
        # after Qt has emitted aboutToQuit, with one final idempotent fence after
        # QApplication.exec() returns.
        _shutdown_application_resources(finalize=False)

        try:
            if self._active_workflow_window is not None:
                self._active_workflow_window.close()
        except Exception:
            pass
        try:
            if self._active_bridge is not None:
                self._active_bridge.shutdown()
        except Exception:
            pass
        try:
            self.plugins_page.shutdown_threads()
        except Exception:
            pass
        try:
            if (self._mergerz_update_check_thread is not None
                    and self._mergerz_update_check_thread.isRunning()):
                self._mergerz_update_check_thread.request_cancel()
                _stop_qthread(self._mergerz_update_check_thread, timeout_ms=2000, force_wait_ms=1000)
        except Exception:
            pass
        try:
            if (self._mergerz_update_install_thread is not None
                    and self._mergerz_update_install_thread.isRunning()):
                self._mergerz_update_install_thread.request_cancel()
                _stop_qthread(self._mergerz_update_install_thread, timeout_ms=5000, force_wait_ms=2000)
        except Exception:
            pass

        super().closeEvent(event)

    def go_menu(self):
        try:
            self.menu_page.refresh_storage(animate=True)
        except Exception:
            pass
        self.stack.setCurrentWidget(self.menu_page)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        try:
            if hasattr(self, "_modal_backdrop") and self._modal_backdrop.isVisible():
                self._modal_backdrop.setGeometry(self.rect())
                self._modal_backdrop.raise_()
        except Exception:
            pass

    @staticmethod
    def _present_independent_window(window):
        """Show a top-level utility window and aggressively bring it frontmost."""
        try:
            if window.isMinimized():
                window.showNormal()
            else:
                window.show()
            window.raise_()
            window.activateWindow()

            def reassert_front():
                try:
                    if window.isMinimized():
                        window.showNormal()
                    window.raise_()
                    window.activateWindow()
                except Exception:
                    pass

            # Linux window managers can defer stacking while another modal
            # dialog is in the middle of an event loop. Reassert several times.
            for delay in (0, 40, 120, 250):
                QtCore.QTimer.singleShot(delay, reassert_front)
        except Exception:
            try:
                window.show()
                window.raise_()
                window.activateWindow()
            except Exception:
                pass

    def _set_main_modal_backdrop(self, visible):
        """Dim and visually lock the main window while an independent modal window is open."""
        try:
            if visible:
                if not hasattr(self, "_modal_backdrop"):
                    self._modal_backdrop = QtWidgets.QWidget(self)
                    self._modal_backdrop.setAttribute(
                        QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
                    self._modal_backdrop.setStyleSheet(
                        "background-color: rgba(0, 0, 0, 105);")
                self._modal_backdrop.setGeometry(self.rect())
                self._modal_backdrop.show()
                self._modal_backdrop.raise_()
            elif hasattr(self, "_modal_backdrop"):
                self._modal_backdrop.hide()
        except Exception:
            pass

    def _run_independent_modal_window(self, window):
        """Run an independent top-level dialog with the main window visually/input locked."""
        previous = self._active_workflow_window
        self._active_workflow_window = window
        self._set_main_modal_backdrop(True)
        try:
            window.setModal(True)
            window.setWindowModality(QtCore.Qt.WindowModality.ApplicationModal)
            self._present_independent_window(window)
            window.exec()
        finally:
            try:
                window.setModal(True)
                window.setWindowModality(QtCore.Qt.WindowModality.ApplicationModal)
            except Exception:
                pass
            try:
                window.hide()
            except Exception:
                pass
            self._active_workflow_window = previous
            self._set_main_modal_backdrop(False)

    def _dialog_parent(self):
        """Return the visible workflow window for nested UI, otherwise the main window."""
        window = getattr(self, "_active_workflow_window", None)
        if window is not None and not window.isHidden():
            return window
        return self

    def _close_active_workflow_to_menu(self):
        window = getattr(self, "_active_workflow_window", None)
        if window is not None:
            try:
                window.reject()
            except Exception:
                pass
        self.go_menu()

    def _start_change_image_type_guide(self):
        dlg = ChangeImageTypeGuideDialog(self._dialog_parent())
        if dlg.exec() != QtWidgets.QDialog.DialogCode.Accepted:
            return "input_cancelled"
        self.open_optimize_images()
        return None

    def open_optimize_images(self):
        """Select multiple supported images and configure one Pillow batch pipeline."""
        files, _ = QtWidgets.QFileDialog.getOpenFileNames(
            self,
            "Select Images to Optimize",
            os.path.abspath(os.getcwd()),
            "Image Files (*.jpg *.jpeg *.png *.webp)",
            options=QtWidgets.QFileDialog.Option.DontUseNativeDialog,
        )
        if not files:
            return

        selected = []
        seen = set()
        for path in files:
            path = os.path.abspath(str(path))
            ext = os.path.splitext(path)[1].lower()
            if ext not in _IMAGE_OPT_INPUT_EXTENSIONS or not os.path.isfile(path):
                continue
            key = os.path.normcase(os.path.realpath(path))
            if key in seen:
                continue
            seen.add(key)
            selected.append(path)
        if not selected:
            QtWidgets.QMessageBox.warning(
                self._dialog_parent(),
                "No Supported Images",
                "No supported JPG, JPEG, PNG, or WebP files were selected.",
            )
            return

        dlg = OptimizeImageDialog(selected, self._dialog_parent())
        if dlg.exec() != QtWidgets.QDialog.DialogCode.Accepted:
            return
        self._run_image_optimizer(selected, dlg.get_settings())

    def _run_image_optimizer(self, input_paths, settings):
        """Run Optimize Images without ever doing image work on the GUI thread."""
        input_paths = [os.path.abspath(str(path)) for path in input_paths]
        output_folder = os.path.abspath(str(settings.get("output_folder") or os.getcwd()))
        target_format = str(settings.get("format") or "jpg").lower()
        label = target_format.upper()
        total = len(input_paths)
        if target_format not in _IMAGE_OPT_FORMATS or total <= 0:
            return

        try:
            os.makedirs(output_folder, exist_ok=True)
        except Exception as exc:
            QtWidgets.QMessageBox.critical(
                self._dialog_parent(),
                "Output Folder Error",
                f"Could not use the selected image output folder:\n{exc}",
            )
            return

        ext = ".jpg" if target_format == "jpg" else (".webp" if target_format == "webp" else ".png")
        output_paths = []
        reserved = set()
        for path in input_paths:
            base = os.path.splitext(os.path.basename(path))[0] or "image"
            candidate = os.path.join(output_folder, base + "_optimized" + ext)
            stem, actual_ext = os.path.splitext(candidate)
            suffix = 1
            key = os.path.normcase(os.path.realpath(candidate))
            while key in reserved or os.path.exists(candidate):
                candidate = f"{stem}-{suffix}{actual_ext}"
                key = os.path.normcase(os.path.realpath(candidate))
                suffix += 1
            reserved.add(key)
            output_paths.append(candidate)

        dlg = ProgressDialog(self._dialog_parent(), cancel_enabled=True)
        dlg.setWindowTitle("Optimize Images")
        dlg.start_infinite("Preparing image optimization")
        dlg.append_log("Preparing the image optimizer...", "info")

        task = _ImageOptimizationTask(
            input_paths=input_paths,
            output_paths=output_paths,
            output_folder=output_folder,
            target_format=target_format,
            settings=settings,
            total=total,
        )
        thread = PluginTaskThread(task, None)
        outcome = {"result": None, "error": None, "cancelled": False}

        thread.log_signal.connect(dlg.append_log)
        thread.progress_signal.connect(dlg.set_progress)
        thread.infinite_signal.connect(
            lambda visible, label_text: (
                dlg.start_infinite(label_text) if visible else dlg.stop_infinite()
            )
        )

        def on_done(result):
            if outcome["cancelled"]:
                return
            if isinstance(result, dict) and result.get("cancelled"):
                outcome["cancelled"] = True
                dlg.accept()
                return
            outcome["result"] = result
            dlg.accept()

        def on_error(message):
            if outcome["cancelled"]:
                return
            outcome["error"] = str(message)
            dlg.append_log(str(message), "error")
            dlg.accept()

        def on_cancelled():
            outcome["cancelled"] = True
            dlg.accept()

        thread.result_signal.connect(on_done)
        thread.error_signal.connect(on_error)
        thread.cancelled_signal.connect(on_cancelled)
        dlg.cancel_requested.connect(thread.request_cancel)

        started = time.time()
        try:
            # show() happens before starting the worker; the GUI event loop then paints the
            # dialog while Pillow work proceeds in PluginTaskThread.
            dlg.show()
            QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)
            thread.start()
            dlg.exec()
        except Exception as exc:
            outcome["error"] = f"Could not start the image optimizer: {type(exc).__name__}: {exc}"
        finally:
            if thread.isRunning():
                _stop_qthread(
                    thread,
                    stop_callback=thread.request_cancel,
                    timeout_ms=5000,
                    force_wait_ms=2000,
                )

        if outcome["cancelled"]:
            # The task itself already removes generated files before emitting cancelled_signal.
            summary = "\n".join([
                "Operation aborted by user.",
                "",
                f"{_pad_label('Images selected')} : {total}",
                f"{_pad_label('Status')} : Generated files from this job were removed.",
                f"{_pad_label('Time taken')} : {format_time(time.time() - started)}",
            ])
            ResultDialog(
                False,
                summary,
                dlg.logs,
                self._dialog_parent(),
                title_text="Operation Aborted",
            ).exec()
            return

        if outcome["error"]:
            # Only remove files produced by this job; the output-path generator reserved
            # unique names, so an existing unrelated file is never touched.
            for path in output_paths:
                try:
                    if os.path.isfile(path):
                        os.remove(path)
                except Exception:
                    pass
            summary = "\n".join([
                "Operation failed.",
                "",
                f"{_pad_label('Images selected')} : {total}",
                f"{_pad_label('Status')} : No complete image set was kept.",
                f"{_pad_label('Reason')} : {str(outcome['error']).splitlines()[0]}",
                f"{_pad_label('Time taken')} : {format_time(time.time() - started)}",
            ])
            ResultDialog(
                False,
                summary,
                dlg.logs,
                self._dialog_parent(),
                title_text="Image Processing Failed",
            ).exec()
            return

        result = outcome["result"] or {}
        if bool(result.get("cancelled")):
            summary = "\n".join([
                "Operation aborted by user.",
                "",
                f"{_pad_label('Images selected')} : {total}",
                f"{_pad_label('Status')} : Generated files from this job were removed.",
                f"{_pad_label('Time taken')} : {format_time(time.time() - started)}",
            ])
            ResultDialog(
                False,
                summary,
                dlg.logs,
                self._dialog_parent(),
                title_text="Operation Aborted",
            ).exec()
            return

        if bool(result.get("failed")):
            errors = list(result.get("worker_errors") or [])
            summary_lines = [
                "Operation failed.",
                "",
                f"{_pad_label('Images selected')} : {total}",
                f"{_pad_label('Status')} : No complete image set was kept.",
            ]
            if errors:
                summary_lines.append(
                    f"{_pad_label('Errors')} : {min(len(errors), 12)} task(s)")
            ResultDialog(
                False,
                "\n".join(summary_lines),
                dlg.logs,
                self._dialog_parent(),
                title_text="Image Processing Failed",
            ).exec()
            return

        original_total = int(result.get("original_total") or 0)
        output_total = int(result.get("output_total") or 0)
        fallback_count = int(result.get("fallback_count") or 0)

        size_delta = original_total - output_total
        if original_total > 0:
            pct = abs(size_delta) / original_total * 100.0
            if size_delta > 0:
                change_label = "Reduced"
                change_text = f"{pct:.1f}%"
            elif size_delta < 0:
                change_label = "Increased"
                change_text = f"{pct:.1f}%"
            else:
                change_label = "No change"
                change_text = None
        else:
            change_label = "No change"
            change_text = None

        lines = [
            f"{_pad_label('Output folder')} : {output_folder}",
            f"{_pad_label('Images processed')} : {total}",
            f"{_pad_label('Format')} : {label}",
            f"{_pad_label('Resolution')} : {int(round(settings.get('scale_percent', 100)))}%",
            f"{_pad_label('Metadata')} : {'Keep' if str(settings.get('metadata')).lower() == 'keep' else 'Remove'}",
            f"{_pad_label('Original size')} : {format_file_size(original_total)}",
            f"{_pad_label('Output size')} : {format_file_size(output_total)}",
            f"{_pad_label(change_label)} : {change_text}" if change_text is not None
            else f"{_pad_label(change_label)} : —",
            f"{_pad_label('Time taken')} : {format_time(time.time() - started)}",
        ]

        ResultDialog(
            True,
            "\n".join(lines),
            dlg.logs,
            self._dialog_parent(),
            title_text="Images Optimized!",
            folder_path=output_folder,
            folder_button_text="Open Folder",
        ).exec()


    def open_plugins(self, force_front=False):
        self.plugins_page.refresh_plugins(manual=False)
        # Plugins is always an independent application-modal window. `force_front`
        # remains accepted for the OCR/Edit PDF caller but no longer changes modality.
        self._run_independent_modal_window(self.plugins_window)

    def open_settings(self, tab_index=0):
        # Settings opens on the first tab (General) unless a caller selects another tab.
        self.settings_page._load_from_app_settings()
        try:
            requested = max(0, min(int(tab_index), self.settings_page.tabs.count() - 1))
        except Exception:
            requested = 0
        self.settings_page.tabs.setCurrentIndex(requested)
        self._run_independent_modal_window(self.settings_window)


    def open_pdf_optimizer(self):
        """Open the PDF optimizer for one PDF after the standard unlock preflight."""
        input_path, _ = QtWidgets.QFileDialog.getOpenFileName(
            self,
            "Select PDF to Optimize",
            "",
            "PDF Files (*.pdf)",
            options=QtWidgets.QFileDialog.Option.DontUseNativeDialog,
        )
        if not input_path:
            return
        input_path = os.path.abspath(str(input_path))
        if not os.path.isfile(input_path):
            QtWidgets.QMessageBox.warning(
                self._dialog_parent(), "PDF Not Found", f"File not found:\n{input_path}")
            return
        # Use the exact shared Mergerz PDF-security preflight used by the viewer, Edit PDF,
        # Merge PDFs and Make Printable Slides. Encrypted PDFs therefore prompt for the same
        # single password dialog (or use the automatic editing-only bypass) instead of being rejected.
        if not self._ensure_pdf_unlocked_for_use(input_path, context="PDF optimization"):
            return
        try:
            security_info = _inspect_pdf_security(input_path)
            security_info["path"] = input_path
        except Exception as exc:
            QtWidgets.QMessageBox.critical(
                self._dialog_parent(), "PDF Check Failed", str(exc))
            return
        if security_info.get("encrypted"):
            QtWidgets.QMessageBox.warning(
                self._dialog_parent(),
                "Protected PDF",
                "The PDF could not be fully unlocked for optimization.",
            )
            return
        if int(security_info.get("page_count") or 0) <= 0:
            QtWidgets.QMessageBox.warning(
                self._dialog_parent(), "Invalid PDF", "The selected PDF contains no pages.")
            return

        dlg = PdfOptimizationDialog(input_path, security_info, self._dialog_parent())
        if dlg.exec() != QtWidgets.QDialog.DialogCode.Accepted:
            return
        self._run_pdf_optimizer(input_path, dlg.selected_options())

    def _run_pdf_optimizer(self, input_path, options):
        input_path = os.path.abspath(str(input_path))
        os.makedirs(TEMP_FOLDER, exist_ok=True)
        optimizer_job_dir = os.path.join(TEMP_FOLDER, f"optimizer_{uuid.uuid4().hex}")
        os.makedirs(optimizer_job_dir, exist_ok=True)
        temp_output = os.path.join(optimizer_job_dir, "optimized.pdf")

        dlg = ProgressDialog(self._dialog_parent(), cancel_enabled=True)
        dlg.setWindowTitle("Optimize PDF")
        dlg.start_infinite("Optimizing PDF")
        dlg.set_storage_notice("")
        dlg.append_log("Starting PDF optimization...", "info")

        options = dict(options or {})
        options["use_memory"] = _get_use_memory_setting()
        options["image_generation_mp"] = copy.deepcopy(
            APP_SETTINGS.get("multiprocessing", {}).get("image_generation", {"processes": DEFAULT_CPU_WORKER_COUNT, "pages_threshold": 4}))
        options["resource_deduplication_mp"] = copy.deepcopy(
            APP_SETTINGS.get("multiprocessing", {}).get("resource_deduplication", {
                "processes": DEFAULT_CPU_WORKER_COUNT, "candidates_threshold": 256
            }))
        bridge = ProcessBridge(
            target_fn=_run_pdf_optimizer_subprocess,
            args=(input_path, temp_output, options),
            parent=dlg,
        )
        self._active_bridge = bridge
        outcome = {"result": None, "error": None, "cancelled": False}

        def on_inf(start, label):
            if start:
                dlg.start_infinite(label or "Optimizing PDF")
            else:
                dlg.stop_infinite()

        bridge.infinite_anim_signal.connect(on_inf)
        bridge.log_batch_signal.connect(dlg.append_logs)
        bridge.progress_signal.connect(dlg.set_progress)
        bridge.storage_signal.connect(
            lambda using_storage: dlg.set_storage_notice(
                "Using storage (slower). Check settings." if using_storage else ""
            )
        )

        def on_memory_prompt(payload):
            if outcome["cancelled"]:
                return
            payload = dict(payload or {})
            dialog = MemorySafetyDialog(
                operation_title=payload.get(
                    "operation_title", "PDF image downsampling"
                ),
                detail_text=payload.get(
                    "detail_text",
                    "The selected workload is estimated to exceed the safe RAM budget."
                ),
                work_label=payload.get("work_label", "Image tasks"),
                work_count=int(payload.get("work_count") or 0),
                dpi_label=payload.get("dpi_label", "Target:"),
                dpi_options=payload.get(
                    "dpi_options", list(OPTIMIZER_DPI_OPTIONS)
                ),
                current_dpi=int(
                    payload.get("current_dpi") or OPTIMIZER_DEFAULT_DPI
                ),
                use_memory="on",
                safety_info=dict(payload.get("safety") or {}),
                parent=dlg,
            )
            if dialog.exec() != QtWidgets.QDialog.DialogCode.Accepted:
                on_cancel()
                return

            selected = dialog.get_settings()
            try:
                _save_use_memory_preference(selected["use_memory"])
            except Exception as exc:
                dlg.append_log(
                    f"Could not persist memory setting: {exc}", "warning"
                )
            bridge.send_memory_response({
                "use_memory": selected["use_memory"],
                "dpi": int(selected["dpi"]),
            })

        bridge.memory_prompt_signal.connect(on_memory_prompt)

        def on_done(result):
            if outcome["cancelled"]:
                return
            outcome["result"] = result
            dlg.accept()

        def on_error(message):
            if outcome["cancelled"]:
                return
            outcome["error"] = message
            if not any(m == message and level == "error" for m, level in dlg.logs):
                dlg.append_log(message, "error")
            dlg.accept()

        def on_cancel():
            if outcome["cancelled"]:
                return
            outcome["cancelled"] = True
            try:
                bridge.shutdown()
            except Exception:
                pass
            try:
                dlg.accept()
            except Exception:
                pass

        bridge.done_signal.connect(on_done)
        bridge.error_signal.connect(on_error)
        dlg.cancel_button.clicked.connect(on_cancel)

        try:
            bridge.start()
            dlg.exec()
        except Exception as exc:
            outcome["error"] = f"Could not start the PDF optimizer: {type(exc).__name__}: {exc}"
        finally:
            try:
                bridge.shutdown()
            except Exception:
                pass
            self._active_bridge = None

        def cleanup_temp():
            try:
                if os.path.isdir(optimizer_job_dir):
                    shutil.rmtree(optimizer_job_dir, ignore_errors=True)
                elif os.path.exists(temp_output):
                    os.remove(temp_output)
            except Exception:
                pass

        if outcome["cancelled"]:
            cleanup_temp()
            summary = "\n".join([
                "Optimization aborted by user.",
                "",
                f"{_pad_label('File', 22)} : {os.path.basename(input_path)}",
                f"{_pad_label('Status', 22)} : No changes were made.",
            ])
            ResultDialog(
                False, summary, dlg.logs, self._dialog_parent(),
                title_text="File Aborted",
            ).exec()
            return

        if outcome["error"]:
            cleanup_temp()
            summary = "\n".join([
                "The PDF optimizer could not produce an output.",
                "",
                f"{_pad_label('File', 22)} : {os.path.basename(input_path)}",
                f"{_pad_label('Reason', 22)} : {outcome['error'].splitlines()[0]}",
                f"{_pad_label('Status', 22)} : Original PDF was left untouched.",
            ])
            ResultDialog(
                False, summary, dlg.logs, self._dialog_parent(),
                title_text="PDF Optimization Failed",
            ).exec()
            return

        result = outcome["result"] or {}
        if not bool(result.get("changed")) or not os.path.isfile(temp_output):
            cleanup_temp()
            old_size = int(result.get("old_size") or 0)
            summary = "\n".join([
                "No smaller PDF was produced.",
                "",
                f"{_pad_label('File', 22)} : {os.path.basename(input_path)}",
                f"{_pad_label('Current size', 22)} : {format_file_size(old_size)}",
                f"{_pad_label('Status', 22)} : Original PDF was preserved unchanged.",
            ])
            ResultDialog(
                True, summary, dlg.logs, self._dialog_parent(),
                title_text="No Smaller Output",
            ).exec()
            return

        complete = PdfOptimizationCompleteDialog(result, self._dialog_parent())
        if complete.exec() != QtWidgets.QDialog.DialogCode.Accepted or not complete.wants_save():
            cleanup_temp()
            old_size = int(result.get("old_size") or 0)
            new_size = int(result.get("new_size") or 0)
            summary = "\n".join([
                "Optimization was completed, but the output was not saved.",
                "",
                f"{_pad_label('Original size', 22)} : {format_file_size(old_size)}",
                f"{_pad_label('Optimized size', 22)} : {format_file_size(new_size)}",
                f"{_pad_label('Status', 22)} : File discarded by user.",
            ])
            ResultDialog(
                False, summary, dlg.logs, self._dialog_parent(),
                title_text="File Aborted",
            ).exec()
            return

        default_name = os.path.splitext(os.path.basename(input_path))[0] + "_optimized.pdf"
        target_path = ""
        while True:
            target_path, _ = QtWidgets.QFileDialog.getSaveFileName(
                self._dialog_parent(),
                "Save Optimized PDF",
                os.path.join(os.path.dirname(input_path), default_name),
                "PDF Files (*.pdf)",
                options=QtWidgets.QFileDialog.Option.DontUseNativeDialog,
            )
            if not target_path:
                cleanup_temp()
                old_size = int(result.get("old_size") or 0)
                new_size = int(result.get("new_size") or 0)
                summary = "\n".join([
                    "Optimization was completed, but no save location was selected.",
                    "",
                    f"{_pad_label('Original size', 22)} : {format_file_size(old_size)}",
                    f"{_pad_label('Optimized size', 22)} : {format_file_size(new_size)}",
                    f"{_pad_label('Status', 22)} : File discarded by user.",
                ])
                ResultDialog(
                    False, summary, dlg.logs, self._dialog_parent(),
                    title_text="File Aborted",
                ).exec()
                return
            target_path = os.path.abspath(str(target_path))
            if not target_path.lower().endswith(".pdf"):
                target_path += ".pdf"
            if os.path.normcase(os.path.realpath(target_path)) == os.path.normcase(os.path.realpath(input_path)):
                QtWidgets.QMessageBox.warning(
                    self._dialog_parent(),
                    "Choose a Different File",
                    "The optimized PDF cannot replace the source file. Choose a different output filename.",
                )
                continue
            break

        dest_tmp = os.path.join(
            os.path.dirname(target_path),
            f".{os.path.basename(target_path)}.mergerz_tmp_{uuid.uuid4().hex}")
        try:
            shutil.copyfile(temp_output, dest_tmp)
            try:
                shutil.copymode(input_path, dest_tmp)
            except Exception:
                pass
            os.replace(dest_tmp, target_path)
        except Exception as exc:
            try:
                if os.path.exists(dest_tmp):
                    os.remove(dest_tmp)
            except Exception:
                pass
            cleanup_temp()
            summary = "\n".join([
                "The optimized PDF could not be saved.",
                "",
                f"{_pad_label('Target', 22)} : {target_path}",
                f"{_pad_label('Reason', 22)} : {type(exc).__name__}: {exc}",
                f"{_pad_label('Status', 22)} : Original PDF was left untouched.",
            ])
            ResultDialog(
                False, summary, dlg.logs, self._dialog_parent(),
                title_text="File Save Failed",
            ).exec()
            return
        finally:
            cleanup_temp()

        old_size = int(result.get("old_size") or 0)
        new_size = int(result.get("new_size") or 0)
        reduction = float(result.get("reduction_percent") or 0.0)
        pages = int(result.get("pages") or 0)
        elapsed = float(result.get("elapsed") or 0.0)
        operations = list(result.get("operations") or [])
        operation_lines = "\n".join(f"  • {item}" for item in operations) or "  • No size-changing optimization was required"
        summary = "\n".join([
            f"{_pad_label('File saved to', 22)} : {target_path}",
            f"{_pad_label('Original size', 22)} : {format_file_size(old_size)}",
            f"{_pad_label('Optimized size', 22)} : {format_file_size(new_size)}",
            f"{_pad_label('Reduced', 22)} : {reduction:.1f}%",
            f"{_pad_label('Pages', 22)} : {pages}",
            f"{_pad_label('Time taken', 22)} : {format_time(elapsed)}",
            "",
            "Optimizations applied:",
            operation_lines,
        ])
        ResultDialog(
            True,
            summary,
            dlg.logs,
            self._dialog_parent(),
            title_text="PDF Optimized!",
            pdf_path=target_path,
        ).exec()

    def _ensure_pdf_unlocked_for_use(self, input_path, context="PDF"):
        """Ensure a PDF is fully accessible to Mergerz before another feature uses it.

        This is the shared preflight path for viewing, merging, printable processing,
        Edit PDF startup, and Edit PDF imports. It permanently removes PDF security from
        the source file when required. A user must explicitly confirm any viewing-password
        or both-password case; editing-only files are bypassed automatically.
        """
        input_path = os.path.abspath(str(input_path))
        if not os.path.isfile(input_path):
            QtWidgets.QMessageBox.warning(
                self._dialog_parent(), "PDF Not Found", f"File not found:\n{input_path}")
            return False

        try:
            security_info = _inspect_pdf_security(input_path)
            security_info["path"] = input_path
        except Exception as exc:
            QtWidgets.QMessageBox.critical(
                self._dialog_parent(), "PDF Security Check Failed", str(exc))
            return False

        if not security_info.get("encrypted"):
            return True

        # Editing-only protection is deliberately invisible to Mergerz's normal use:
        # no dialog is needed because the PDF can be opened with the blank user password
        # and pikepdf can bypass viewer-enforced permissions.
        if security_info.get("editing_only"):
            return bool(self._run_pdf_security_operation(
                input_path,
                "unlock",
                candidate_passwords=[""],
                editing_only_bypass=True,
                security_info=security_info,
                auto_unlock=True,
                context=context))

        # Any remaining encrypted PDF requires an explicit access password. The exact
        # same single-password dialog is used by dedicated Unlock PDF and by all automatic
        # preflight unlocks.
        while True:
            dlg = PdfUnlockPasswordDialog(security_info, self._dialog_parent())
            if dlg.exec() != QtWidgets.QDialog.DialogCode.Accepted:
                return False
            candidate = dlg.password()
            verified, _role = _verify_pdf_access_password(input_path, candidate)
            if verified:
                return bool(self._run_pdf_security_operation(
                    input_path,
                    "unlock",
                    candidate_passwords=[candidate],
                    editing_only_bypass=False,
                    security_info=security_info,
                    auto_unlock=True,
                    context=context))
            QtWidgets.QMessageBox.warning(
                self._dialog_parent(),
                "Incorrect Password",
                "That password could not be used to open this PDF. "
                "Enter the viewing password or editing password and try again.")

    def _prepare_pdf_paths_for_use(self, pdf_paths, context):
        """Unlock protected source PDFs one by one; cancellation aborts the parent operation."""
        seen = set()
        for raw_path in pdf_paths:
            path = os.path.abspath(str(raw_path))
            key = os.path.normcase(os.path.realpath(path))
            if key in seen:
                continue
            seen.add(key)
            if not self._ensure_pdf_unlocked_for_use(path, context=context):
                return False
        return True

    def _ensure_libreoffice_converter_catalog(self):
        """Prepare the LibreOffice converter catalog before opening the chooser.

        A matching catalog already loaded in memory is the fast path. The full structural
        cache validation is only performed when the runtime/cache key is not already loaded.
        When the cache is missing, stale, or invalid, the existing blocking format-loading
        dialog is shown and discovery completes before the chooser opens.
        """
        root = _libreoffice_active_root()
        try:
            manifest = _read_json_file(_libreoffice_manifest_path(root))
        except Exception:
            manifest = None

        if not isinstance(manifest, dict) or manifest.get("plugin_id") != LIBREOFFICE_PLUGIN_ID:
            _set_libreoffice_converter_specs([], cache_key=None)
            return False

        if (manifest.get("manifest_version") != LIBREOFFICE_PLUGIN_MANIFEST_VERSION
                or not bool(manifest.get("verified"))):
            _set_libreoffice_converter_specs([], cache_key=None)
            return False

        runtime_version = str(manifest.get("runtime_version") or "").strip()
        expected_key = (runtime_version, LIBREOFFICE_CONVERTER_CACHE_VERSION)

        # This is the important hot path. The initial application load has already validated
        # and materialized the matching cache, so do not re-walk thousands of cached routes here.
        if (runtime_version
                and LIBREOFFICE_CONVERTER_LOADED_CACHE_KEY == expected_key
                and LIBREOFFICE_CONVERTER_SPECS):
            return True

        cached = _lo_cache_matches_runtime_version(runtime_version)
        if cached is not None:
            cache_key = (
                str(cached.get("runtime_version") or "").strip(),
                cached.get("converter_cache_version"),
            )
            if LIBREOFFICE_CONVERTER_LOADED_CACHE_KEY != cache_key:
                _set_libreoffice_converter_specs(
                    _libreoffice_specs_from_cache(cached),
                    cached.get("formats"),
                    cache_key=cache_key,
                )
            return bool(LIBREOFFICE_CONVERTER_SPECS)

        # Cache is missing/stale/invalid. Keep the existing intentional UX: show the loading
        # dialog now and finish discovery before the converter chooser is constructed.
        soffice = _libreoffice_soffice_path(root)
        if not runtime_version or not soffice or not os.path.isfile(soffice) or (
                os.name != "nt" and not os.access(soffice, os.X_OK)):
            _set_libreoffice_converter_specs([], cache_key=None)
            return False

        parent = self._dialog_parent()
        dialog = ProgressDialog(parent, cancel_enabled=True)
        dialog.setWindowTitle("Loading LibreOffice Formats")
        dialog.start_infinite("Reading LibreOffice formats")
        dialog.append_log("Reading the installed LibreOffice format capabilities...", "info")
        task = _LibreOfficeConverterCatalogTask(root, soffice, runtime_version)
        thread = PluginTaskThread(task, dialog)
        outcome = {"result": None, "error": None, "cancelled": False}
        thread.log_signal.connect(dialog.append_log)
        thread.progress_signal.connect(dialog.set_progress)
        thread.infinite_signal.connect(
            lambda visible, label: dialog.start_infinite(label) if visible else dialog.stop_infinite())

        def on_done(result):
            outcome["result"] = result
            dialog.accept()

        def on_error(message):
            outcome["error"] = message
            dialog.append_log(message, "error")
            dialog.accept()

        def on_cancelled():
            outcome["cancelled"] = True
            dialog.accept()

        thread.result_signal.connect(on_done)
        thread.error_signal.connect(on_error)
        thread.cancelled_signal.connect(on_cancelled)
        dialog.cancel_button.clicked.connect(thread.request_cancel)
        try:
            thread.start()
            dialog.exec()
        finally:
            if thread.isRunning():
                _stop_qthread(thread, stop_callback=thread.request_cancel, timeout_ms=5000, force_wait_ms=2000)

        if outcome["result"]:
            try:
                cache = _save_libreoffice_converter_cache(outcome["result"])
                cache_key = (
                    str(cache.get("runtime_version") or "").strip(),
                    cache.get("converter_cache_version"),
                )
                _set_libreoffice_converter_specs(
                    _libreoffice_specs_from_cache(cache),
                    cache.get("formats"),
                    cache_key=cache_key,
                )
                return bool(LIBREOFFICE_CONVERTER_SPECS)
            except Exception as exc:
                QtWidgets.QMessageBox.warning(
                    parent, "LibreOffice Formats",
                    "The LibreOffice format catalog was discovered but could not be cached.\n\n" + str(exc))
                result_cache = outcome["result"]
                result_specs = _libreoffice_specs_from_cache(result_cache) if isinstance(result_cache, dict) else []
                result_key = (
                    str(result_cache.get("runtime_version") or "").strip(),
                    result_cache.get("converter_cache_version"),
                ) if isinstance(result_cache, dict) and result_specs else None
                _set_libreoffice_converter_specs(
                    result_specs,
                    (result_cache.get("formats") if isinstance(result_cache, dict) else None),
                    cache_key=result_key,
                )
                return bool(result_specs)

        fallback_cache = _libreoffice_converter_cache_snapshot()
        fallback_specs = _libreoffice_specs_from_cache(fallback_cache)
        fallback_key = (
            str(fallback_cache.get("runtime_version") or "").strip(),
            fallback_cache.get("converter_cache_version"),
        ) if isinstance(fallback_cache, dict) and fallback_specs else None
        _set_libreoffice_converter_specs(
            fallback_specs,
            (fallback_cache.get("formats") if isinstance(fallback_cache, dict) else None),
            cache_key=fallback_key,
        )
        if outcome["error"] and not outcome["cancelled"]:
            QtWidgets.QMessageBox.warning(
                parent, "LibreOffice Formats",
                "The installed LibreOffice Runtime could not provide a valid format catalog. "
                "LibreOffice converters will remain unavailable until discovery succeeds.")
        return bool(LIBREOFFICE_CONVERTER_SPECS)

    def open_converters(self):
        # Missing/stale caches are handled above with the blocking format-loading dialog before
        # the chooser is constructed. Matching caches take the lightweight in-memory path.
        libreoffice_available = self._ensure_libreoffice_converter_catalog()
        chooser = ConvertersChoiceDialog(
            self._dialog_parent(), include_libreoffice=libreoffice_available)
        while True:
            if chooser.exec() != QtWidgets.QDialog.DialogCode.Accepted:
                return
            if chooser.choice == "__reopen_converters__":
                # LibreOffice was installed while the previous chooser was open.
                # Reload the runtime-backed catalog and construct a fresh chooser immediately.
                libreoffice_available = self._ensure_libreoffice_converter_catalog()
                chooser = ConvertersChoiceDialog(
                    self._dialog_parent(), include_libreoffice=libreoffice_available)
                continue
            if chooser.choice == "pdf2docx":
                outcome = self._start_pdf_to_docx()
                if outcome == "input_cancelled":
                    continue
                return
            if chooser.choice == "pdf_to_image":
                outcome = self._start_pdf_to_image()
                if outcome == "input_cancelled":
                    continue
                return
            if chooser.choice == "image_to_pdf":
                outcome = self._start_image_to_pdf_guide()
                if outcome == "input_cancelled":
                    continue
                return
            if chooser.choice == "change_image_type":
                outcome = self._start_change_image_type_guide()
                if outcome == "input_cancelled":
                    continue
                return
            if chooser.choice == "__libreoffice_missing__":
                _show_missing_plugin_dialog(
                    self._dialog_parent(),
                    "LibreOffice Runtime",
                    _libreoffice_plugin_status(),
                )
                return
            spec = _libreoffice_converter_spec(chooser.choice)
            if spec is not None:
                outcome = self._start_libreoffice_converter(spec)
                if outcome == "input_cancelled":
                    continue
            return

    def _start_libreoffice_converter(self, spec):
        plugin_status = _show_plugin_check_dialog(
            self._dialog_parent(),
            plugin_name="LibreOffice Runtime",
            status_checker=_libreoffice_plugin_status,
            log_text="Checking the bundled LibreOffice Runtime environment...",
        )
        if not plugin_status.get("healthy"):
            _show_missing_plugin_dialog(
                self._dialog_parent(), "LibreOffice Runtime", plugin_status)
            return

        input_path, _ = QtWidgets.QFileDialog.getOpenFileName(
            self._dialog_parent(),
            f"Select {spec['source_ext'].lstrip('.').upper()} File",
            "",
            spec["source_filter"],
            options=QtWidgets.QFileDialog.Option.DontUseNativeDialog,
        )
        if not input_path:
            return "input_cancelled"
        input_path = os.path.abspath(input_path)
        if not os.path.isfile(input_path):
            QtWidgets.QMessageBox.warning(
                self._dialog_parent(), "File Not Found", f"File not found:\n{input_path}")
            return

        if str(spec.get("source_ext") or "").casefold() == ".pdf":
            if not self._ensure_pdf_unlocked_for_use(input_path, context="LibreOffice converter"):
                return "input_cancelled"

        job_root = os.path.join(TEMP_FOLDER, "libreoffice_jobs", uuid.uuid4().hex)
        output_dir = os.path.join(job_root, "output")
        os.makedirs(output_dir, exist_ok=True)
        started = time.perf_counter()
        dlg = ProgressDialog(self._dialog_parent(), cancel_enabled=True)
        dlg.setWindowTitle(f"Converting {spec['title'].replace(' → ', ' to ')}")
        dlg.start_infinite("Preparing to convert")
        dlg.append_log(
            f"Starting {spec['title']} conversion for {os.path.basename(input_path)}...",
            "info")
        task = _LibreOfficeConversionTask(
            input_path, output_dir, spec["target_ext"], spec)
        thread = PluginTaskThread(task, dlg)
        outcome = {"result": None, "error": None, "cancelled": False}
        self._active_plugin_conversion_thread = thread
        self._active_bridge = thread
        thread.log_signal.connect(dlg.append_log)
        thread.progress_signal.connect(dlg.set_progress)
        thread.infinite_signal.connect(
            lambda visible, label: dlg.start_infinite(label) if visible
            else dlg.stop_infinite())

        def on_done(result):
            if outcome["cancelled"]:
                return
            outcome["result"] = result
            dlg.accept()

        def on_error(message):
            if outcome["cancelled"]:
                return
            outcome["error"] = message
            dlg.append_log(message, "error")
            dlg.accept()

        def on_cancelled():
            if outcome["cancelled"]:
                return
            outcome["cancelled"] = True
            dlg.accept()

        def on_cancel_clicked():
            dlg.request_cancel()
            thread.request_cancel()

        thread.result_signal.connect(on_done)
        thread.error_signal.connect(on_error)
        thread.cancelled_signal.connect(on_cancelled)
        dlg.cancel_button.clicked.connect(on_cancel_clicked)

        try:
            thread.start()
            dlg.exec()
        finally:
            if thread.isRunning():
                _stop_qthread(thread, stop_callback=thread.request_cancel, timeout_ms=5000, force_wait_ms=2000)
            self._active_plugin_conversion_thread = None
            if self._active_bridge is thread:
                self._active_bridge = None

        elapsed = format_time(max(0.0, time.perf_counter() - started))

        def cleanup_job():
            shutil.rmtree(job_root, ignore_errors=True)

        if outcome["cancelled"]:
            cleanup_job()
            summary = "\n".join([
                "Operation aborted by user.", "",
                f"{_pad_label('Time taken')} : {elapsed}",
                f"{_pad_label('Status')} : No {spec['target_ext'].upper()} output was kept.",
            ])
            dlg.append_log("Conversion cancelled; temporary output was discarded.", "warning")
            ResultDialog(False, summary, dlg.logs, self._dialog_parent(),
                         title_text="Operation Aborted").exec()
            return

        if outcome["error"] is not None or not outcome["result"] or not os.path.isfile(outcome["result"].get("path", "")):
            error_text = outcome["error"] or "No optimized output was produced."
            cleanup_job()
            summary = "\n".join([
                "Operation failed.", "",
                f"{_pad_label('Time taken')} : {elapsed}",
                f"{_pad_label('Status')} : No {spec['target_ext'].upper()} output was kept.",
                f"{_pad_label('Error')} : {error_text}",
            ])
            ResultDialog(False, summary, dlg.logs, self._dialog_parent(),
                         title_text="Conversion Failed").exec()
            return

        temp_output = os.path.abspath(outcome["result"]["path"])
        generated_size = os.path.getsize(temp_output)
        default_name = os.path.splitext(os.path.basename(input_path))[0] + "." + spec["target_ext"].lstrip(".")
        save_path, _ = QtWidgets.QFileDialog.getSaveFileName(
            self._dialog_parent(),
            f"Save {spec['target_ext'].upper()} Output",
            default_name,
            spec["target_filter"],
            options=QtWidgets.QFileDialog.Option.DontUseNativeDialog,
        )
        if not save_path:
            dlg.append_log("Final save-location dialog cancelled; generated output was discarded.", "warning")
            cleanup_job()
            summary = "\n".join([
                "File aborted by user.", "",
                f"{_pad_label('Time taken')} : {elapsed}",
                f"{_pad_label('Status')} : Generated output was discarded.",
            ])
            ResultDialog(False, summary, dlg.logs, self._dialog_parent(),
                         title_text="File Aborted").exec()
            return

        dest_abs = os.path.abspath(save_path)
        target_ext = "." + spec["target_ext"].lstrip(".")
        if not dest_abs.lower().endswith(target_ext.lower()):
            dest_abs += target_ext
        saved_ok = False
        try:
            os.makedirs(os.path.dirname(dest_abs), exist_ok=True)
            if os.path.abspath(temp_output) == dest_abs:
                saved_ok = True
            else:
                os.replace(temp_output, dest_abs)
                saved_ok = os.path.isfile(dest_abs)
        except Exception as exc:
            dlg.append_log(f"Could not save output: {exc}", "error")

        if not saved_ok:
            cleanup_job()
            summary = "\n".join([
                "File save failed.", "",
                f"{_pad_label('Time taken')} : {elapsed}",
                f"{_pad_label('Status')} : Generated output was not saved.",
            ])
            ResultDialog(False, summary, dlg.logs, self._dialog_parent(),
                         title_text="File Save Failed").exec()
            return

        final_size = os.path.getsize(dest_abs) if os.path.isfile(dest_abs) else generated_size
        lines = [
            f"{_pad_label('File saved to')} : {dest_abs}",
            f"{_pad_label('File size')} : {format_file_size(final_size)}",
            f"{_pad_label('Time taken')} : {elapsed}",
        ]
        if spec["target_ext"].lower() == "pdf":
            try:
                with fitz.open(dest_abs) as out_doc:
                    lines.insert(2, f"{_pad_label('Pages')} : {out_doc.page_count}")
            except Exception:
                pass
        cleanup_job()
        dlg.append_log(f"Output saved to {dest_abs}", "success")
        ResultDialog(
            True,
            "\n".join(lines),
            dlg.logs,
            self._dialog_parent(),
            title_text="Conversion Complete!",
            folder_path=os.path.dirname(dest_abs),
            folder_button_text="Open Folder",
        ).exec()

    def _get_pdf2docx_password(self, input_path):
        """Return (proceed, password) for an encrypted PDF without changing the source file."""
        try:
            security_info = _inspect_pdf_security(input_path)
            security_info["path"] = os.path.abspath(input_path)
        except Exception as exc:
            QtWidgets.QMessageBox.critical(
                self._dialog_parent(), "PDF Security Check Failed", str(exc))
            return False, None

        if not security_info.get("encrypted"):
            return True, None
        if security_info.get("editing_only"):
            return True, ""

        while True:
            pwd_dlg = PdfUnlockPasswordDialog(security_info, self._dialog_parent())
            if pwd_dlg.exec() != QtWidgets.QDialog.DialogCode.Accepted:
                return False, None
            candidate = pwd_dlg.password()
            verified, _role = _verify_pdf_access_password(input_path, candidate)
            if verified:
                return True, candidate
            QtWidgets.QMessageBox.warning(
                self._dialog_parent(),
                "Incorrect Password",
                "That password could not be used to open this PDF. "
                "Enter the viewing password or editing password and try again.")

    def _start_pdf_to_docx(self):
        plugin_status = _show_plugin_check_dialog(
            self._dialog_parent(),
            plugin_name="PDF2DOCX",
            status_checker=_pdf2docx_plugin_status,
            log_text="Checking the isolated PDF2DOCX plugin environment...",
        )
        if not plugin_status.get("healthy"):
            _show_missing_plugin_dialog(
                self._dialog_parent(), "PDF2DOCX", plugin_status)
            return

        input_path, _ = QtWidgets.QFileDialog.getOpenFileName(
            self._dialog_parent(),
            "Select PDF to Convert",
            "",
            "PDF Files (*.pdf)",
            options=QtWidgets.QFileDialog.Option.DontUseNativeDialog,
        )
        if not input_path:
            return "input_cancelled"
        input_path = os.path.abspath(input_path)
        if not os.path.isfile(input_path):
            QtWidgets.QMessageBox.warning(
                self._dialog_parent(), "PDF Not Found", f"File not found:\n{input_path}")
            return

        # Match the rest of Mergerz's PDF workflows: use the shared security
        # detection/unlock preflight before the converter sees the source PDF.
        if not self._ensure_pdf_unlocked_for_use(input_path, context="PDF to DOCX"):
            return "input_cancelled"
        pdf_password = None

        try:
            with fitz.open(input_path) as source_doc:
                page_count = int(source_doc.page_count)
        except Exception as exc:
            QtWidgets.QMessageBox.critical(
                self._dialog_parent(), "PDF Read Failed",
                f"Could not read the selected PDF.\n\n{exc}")
            return
        if page_count <= 0:
            QtWidgets.QMessageBox.warning(
                self._dialog_parent(), "Empty PDF", "The selected PDF contains no pages.")
            return

        job_root = os.path.join(TEMP_FOLDER, "pdf2docx_jobs", uuid.uuid4().hex)
        os.makedirs(job_root, exist_ok=True)
        temp_docx = os.path.join(
            job_root, os.path.splitext(os.path.basename(input_path))[0] + ".docx")
        started = time.perf_counter()

        dlg = ProgressDialog(self._dialog_parent(), cancel_enabled=True)
        dlg.setWindowTitle("Converting PDF to DOCX")
        dlg.start_infinite("Converting PDF to DOCX")
        dlg.append_log(
            f"Starting PDF to DOCX conversion for {os.path.basename(input_path)}...",
            "info")

        task = _Pdf2DocxConversionTask(input_path, temp_docx, password=pdf_password)
        thread = PluginTaskThread(task, dlg)
        outcome = {"result": None, "error": None, "cancelled": False}
        self._active_plugin_conversion_thread = thread
        self._active_bridge = thread

        thread.log_signal.connect(dlg.append_log)
        thread.progress_signal.connect(dlg.set_progress)
        thread.infinite_signal.connect(
            lambda visible, label: dlg.start_infinite(label) if visible
            else dlg.stop_infinite())

        def on_done(result):
            if outcome["cancelled"]:
                return
            outcome["result"] = result
            dlg.accept()

        def on_error(message):
            if outcome["cancelled"]:
                return
            outcome["error"] = message
            dlg.append_log(message, "error")
            dlg.accept()

        def on_cancelled():
            if outcome["cancelled"]:
                return
            outcome["cancelled"] = True
            dlg.accept()

        def on_cancel_clicked():
            dlg.request_cancel()
            thread.request_cancel()

        thread.result_signal.connect(on_done)
        thread.error_signal.connect(on_error)
        thread.cancelled_signal.connect(on_cancelled)
        dlg.cancel_button.clicked.connect(on_cancel_clicked)

        try:
            thread.start()
            dlg.exec()
        finally:
            if thread.isRunning():
                _stop_qthread(thread, stop_callback=thread.request_cancel, timeout_ms=5000, force_wait_ms=2000)
            self._active_plugin_conversion_thread = None
            if self._active_bridge is thread:
                self._active_bridge = None

        elapsed = format_time(max(0.0, time.perf_counter() - started))

        def cleanup_job():
            try:
                shutil.rmtree(job_root, ignore_errors=True)
            except Exception:
                pass

        if outcome["cancelled"]:
            cleanup_job()
            summary = "\n".join([
                "Operation aborted by user.",
                "",
                f"{_pad_label('Pages')} : {page_count}",
                f"{_pad_label('Time taken')} : {elapsed}",
                f"{_pad_label('Status')} : No DOCX output was kept.",
            ])
            dlg.append_log("Conversion cancelled; temporary DOCX output was discarded.", "warning")
            ResultDialog(
                False, summary, dlg.logs, self._dialog_parent(),
                title_text="Operation Aborted",
            ).exec()
            return

        if outcome["error"] is not None or not os.path.isfile(temp_docx):
            error_text = outcome["error"] or "No verified DOCX output was produced."
            cleanup_job()
            summary = "\n".join([
                "Operation failed.",
                "",
                f"{_pad_label('Pages')} : {page_count}",
                f"{_pad_label('Time taken')} : {elapsed}",
                f"{_pad_label('Status')} : No DOCX output was kept.",
                f"{_pad_label('Error')} : {error_text}",
            ])
            ResultDialog(
                False, summary, dlg.logs, self._dialog_parent(),
                title_text="PDF to DOCX Failed",
            ).exec()
            return

        try:
            generated_size = os.path.getsize(temp_docx)
        except OSError:
            generated_size = 0

        default_name = os.path.splitext(os.path.basename(input_path))[0] + ".docx"
        save_path, _ = QtWidgets.QFileDialog.getSaveFileName(
            self._dialog_parent(),
            "Save DOCX Output",
            default_name,
            "Word Documents (*.docx)",
            options=QtWidgets.QFileDialog.Option.DontUseNativeDialog,
        )

        saved_ok = False
        dest_abs = None
        if save_path:
            try:
                dest_abs = os.path.abspath(save_path)
                if not dest_abs.lower().endswith(".docx"):
                    dest_abs += ".docx"
                dest_dir = os.path.dirname(dest_abs)
                if dest_dir:
                    os.makedirs(dest_dir, exist_ok=True)
                if os.path.abspath(temp_docx) == dest_abs:
                    saved_ok = True
                else:
                    os.replace(temp_docx, dest_abs)
                    saved_ok = os.path.isfile(dest_abs)
            except Exception as exc:
                dlg.append_log(f"Could not save DOCX output: {exc}", "error")
                saved_ok = False

        if not save_path:
            dlg.append_log(
                "Final save-location dialog cancelled; generated DOCX was discarded.",
                "warning")
            cleanup_job()
            summary = "\n".join([
                "File aborted by user.",
                "",
                f"{_pad_label('Pages')} : {page_count}",
                f"{_pad_label('Time taken')} : {elapsed}",
                f"{_pad_label('Status')} : Generated DOCX was discarded.",
            ])
            ResultDialog(
                False, summary, dlg.logs, self._dialog_parent(),
                title_text="File Aborted",
            ).exec()
            return

        if not saved_ok:
            cleanup_job()
            summary = "\n".join([
                "File save failed.",
                "",
                f"{_pad_label('Pages')} : {page_count}",
                f"{_pad_label('Time taken')} : {elapsed}",
                f"{_pad_label('Status')} : Generated DOCX was not saved.",
            ])
            ResultDialog(
                False, summary, dlg.logs, self._dialog_parent(),
                title_text="File Save Failed",
            ).exec()
            return

        # The temporary job root is now empty after the atomic move. Remove it without
        # touching unrelated application temp files.
        cleanup_job()
        final_size = generated_size
        try:
            final_size = os.path.getsize(dest_abs)
        except OSError:
            pass
        summary = "\n".join([
            f"{_pad_label('File saved to')} : {dest_abs}",
            f"{_pad_label('File size')} : {format_file_size(final_size)}",
            f"{_pad_label('Pages')} : {page_count}",
            f"{_pad_label('Time taken')} : {elapsed}",
        ])
        dlg.append_log(f"DOCX saved to {dest_abs}", "success")
        ResultDialog(
            True, summary, dlg.logs, self._dialog_parent(),
            title_text="Conversion Complete!",
            folder_path=os.path.dirname(dest_abs),
            folder_button_text="Open Folder",
        ).exec()

    def _start_pdf_to_image(self):
        input_path, _ = QtWidgets.QFileDialog.getOpenFileName(
            self._dialog_parent(), "Select PDF", "", "PDF Files (*.pdf)",
            options=QtWidgets.QFileDialog.Option.DontUseNativeDialog)
        if not input_path:
            return "input_cancelled"
        input_path = os.path.abspath(input_path)
        if not os.path.isfile(input_path):
            QtWidgets.QMessageBox.warning(self._dialog_parent(), "PDF Not Found", f"File not found:\n{input_path}")
            return
        # Use the exact shared PDF-security preflight used by Edit PDF / merge / printable.
        if not self._ensure_pdf_unlocked_for_use(input_path, context="PDF to Image"):
            return "input_cancelled"
        try:
            with fitz.open(input_path) as doc:
                page_count = int(doc.page_count)
        except Exception as exc:
            QtWidgets.QMessageBox.critical(self._dialog_parent(), "PDF Read Failed", f"Could not read the selected PDF.\n\n{exc}")
            return
        if page_count <= 0:
            QtWidgets.QMessageBox.warning(self._dialog_parent(), "Empty PDF", "The selected PDF contains no pages.")
            return

        while True:
            dlg = PdfToImageDialog(input_path, page_count, self._dialog_parent())
            result = dlg.exec()
            if result == PdfToImageDialog.OPEN_EDITOR_RESULT:
                editor = PageEditDialog(input_path, unit_label="Pages", parent=self._dialog_parent())
                editor.exec()
                return
            if result != QtWidgets.QDialog.DialogCode.Accepted:
                return "input_cancelled"
            settings = dlg.get_settings()
            break

        self._do_pdf_to_image_conversion(input_path, page_count, settings)

    def _do_pdf_to_image_conversion(self, input_path, page_count, settings):
        """Convert an original PDF page range to JPG/PNG using the same SP/MP image-generation engine as Save Selected Pages."""
        image_format = str(settings["format"] or "jpg").lower()
        image_dpi = int(settings["dpi"])
        webp_mode = str(settings.get("webp_mode") or "lossy").lower()
        output_folder = os.path.abspath(str(settings["output_folder"]))
        first_page = int(settings["from_page"])
        last_page = int(settings["to_page"])
        total = last_page - first_page + 1
        label = image_format.upper()
        job_root = os.path.join(TEMP_FOLDER, "pdf_to_image_jobs", uuid.uuid4().hex)
        os.makedirs(job_root, exist_ok=True)
        dlg = None
        try:
            os.makedirs(output_folder, exist_ok=True)
            entries = [
                {"source_pdf": os.path.abspath(input_path), "original_idx": idx}
                for idx in range(first_page - 1, last_page)
            ]
            output_paths = []
            reserved = set()
            ext = ".png" if image_format == "png" else (".webp" if image_format == "webp" else ".jpg")
            source_base = os.path.splitext(os.path.basename(input_path))[0].replace("/", "_").replace("\\", "_")
            for selection_index, entry in enumerate(entries):
                base_name = (
                    f"{selection_index + 1:04d}_{source_base}_page_"
                    f"{int(entry['original_idx']) + 1:06d}{ext}"
                )
                candidate = os.path.join(output_folder, base_name)
                stem, ext_actual = os.path.splitext(candidate)
                suffix = 1
                while candidate in reserved or os.path.exists(candidate):
                    candidate = f"{stem}_{suffix}{ext_actual}"
                    suffix += 1
                reserved.add(candidate)
                output_paths.append(candidate)

            dlg = ProgressDialog(self._dialog_parent(), cancel_enabled=True)
            dlg.setWindowTitle(f"Generating {label} Images")
            dlg.start_infinite("Generating images")
            dlg.append_log(
                f"Starting PDF to {label} conversion for {os.path.basename(input_path)}...", "info")
            dlg.append_log(f"Pages: {first_page}–{last_page} of {page_count}", "info")
            dlg.append_log(f"Resolution: {image_dpi} dpi", "info")
            dlg.append_log(f"Output format: {label}", "info")
            if image_format == "webp":
                dlg.append_log(f"WebP mode: {'Lossless' if webp_mode == 'lossless' else 'Lossy'}", "info")
            dlg.append_log(f"Output folder: {output_folder}", "info")
            dlg.show()
            QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)

            start = time.time()
            cancelled = False
            worker_errors = []
            results = {}
            image_cfg = APP_SETTINGS["multiprocessing"]["image_generation"]
            requested_workers = int(image_cfg["processes"])
            threshold = int(image_cfg["pages_threshold"])
            actual_workers = _effective_worker_count(total, requested_workers)
            use_mp = total > threshold and actual_workers > 1

            dlg.append_log(
                f"Generation mode: {'MP' if use_mp else 'SP'} — "
                f"{actual_workers if use_mp else 1} process(es) "
                f"(MP starts above {threshold} pages; configured {requested_workers} workers).", "info")
            if use_mp:
                chunks = _build_page_ranges(total, actual_workers)
                for worker_index, (chunk_start, chunk_end) in enumerate(chunks):
                    dlg.append_log(
                        f"  Worker {worker_index + 1}: pages "
                        f"{first_page + chunk_start}–{first_page + chunk_end}", "info")
            dlg.set_progress(0, max(1, total), "Generating images")
            QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)

            def cleanup_outputs():
                for path in output_paths:
                    try:
                        if os.path.isfile(path):
                            os.remove(path)
                    except Exception:
                        pass

            def finish_aborted():
                cleanup_outputs()
                elapsed = format_time(time.time() - start)
                dlg.append_log(
                    f"PDF to {label} conversion cancelled; generated files were removed.", "warning")
                dlg.accept()
                summary = "\n".join([
                    "Operation aborted by user.", "",
                    f"{_pad_label('Pages selected')} : {total}",
                    f"{_pad_label('Page range')} : {first_page}–{last_page}",
                    f"{_pad_label('Status')} : Generated {label} files from this job were removed.",
                    f"{_pad_label('Time taken')} : {elapsed}",
                ])
                ResultDialog(False, summary, dlg.logs, self._dialog_parent(), title_text="Operation Aborted").exec()

            processes = []

            def on_cancel():
                nonlocal cancelled
                cancelled = True
                dlg.request_cancel()
                for process in processes:
                    try:
                        if process.is_alive():
                            process.terminate()
                    except Exception:
                        pass

            dlg.cancel_button.clicked.connect(on_cancel)

            if use_mp:
                page_chunks = [
                    [(i, entries[i], output_paths[i])
                     for i in range(chunk_start, chunk_end + 1)]
                    for chunk_start, chunk_end in chunks
                ]
                ctx = multiprocessing.get_context("spawn")
                result_queue = ctx.Queue(maxsize=max(10, actual_workers * 2))
                for worker_index, chunk in enumerate(page_chunks):
                    process = ctx.Process(
                        target=_render_selected_image_pages_worker,
                        args=(chunk, image_dpi, image_format, result_queue, worker_index, webp_mode)
                    )
                    processes.append(process)
                for process in processes:
                    process.start()

                completed_workers = set()
                received = 0
                try:
                    while len(completed_workers) < actual_workers:
                        if dlg.is_cancel_requested():
                            cancelled = True
                            break
                        try:
                            message = result_queue.get(timeout=0.20)
                        except queue.Empty:
                            if processes and all(not p.is_alive() for p in processes):
                                break
                            QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)
                            continue

                        kind, worker_index, selection_index, out_path, size_bytes, width, height, error = message
                        if kind == "worker_done":
                            completed_workers.add(worker_index)
                            continue
                        if kind == "done":
                            results[selection_index] = (out_path, int(size_bytes), int(width), int(height))
                            received += 1
                        elif kind == "error":
                            worker_errors.append(
                                f"Page {selection_index + first_page}: {error or 'generation failed'}"
                            )
                            received += 1
                        dlg.set_progress(received, max(1, total), "Generating images")
                        if received == 1 or received == total or received % 10 == 0:
                            dlg.append_log(f"  Generated {received}/{total} {label} image(s)", "info")
                        QtWidgets.QApplication.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 25)
                finally:
                    if cancelled:
                        for process in processes:
                            try:
                                if process.is_alive():
                                    process.terminate()
                            except Exception:
                                pass
                    for process in processes:
                        try:
                            process.join(timeout=2.0)
                        except Exception:
                            pass
                    for process in processes:
                        if process.is_alive():
                            try:
                                process.terminate()
                            except Exception:
                                pass
                    for process in processes:
                        try:
                            process.join(timeout=1.0)
                        except Exception:
                            pass
                    try:
                        result_queue.close(); result_queue.join_thread()
                    except Exception:
                        pass
            else:
                _render_selected_image_sp_common(
                    entries, range(total), image_dpi, image_format,
                    output_paths, dlg, results, worker_errors, webp_mode
                )
                if dlg.is_cancel_requested():
                    cancelled = True

            elapsed = format_time(time.time() - start)
            if cancelled or dlg.is_cancel_requested():
                finish_aborted()
                return

            unresolved = [
                i for i in range(total)
                if i not in results or not results[i][0] or not os.path.isfile(results[i][0])
            ]
            if unresolved:
                cleanup_outputs()
                dlg.append_log(
                    f"Could not generate {len(unresolved)} {label} image(s). The partial job output was removed.",
                    "error")
                dlg.accept()
                summary = "\n".join([
                    "Operation failed.", "",
                    f"{_pad_label('Pages selected')} : {total}",
                    f"{_pad_label('Page range')} : {first_page}–{last_page}",
                    f"{_pad_label('Status')} : No complete image set was kept.",
                    f"{_pad_label('Time taken')} : {elapsed}",
                ])
                ResultDialog(False, summary, dlg.logs, self._dialog_parent(), title_text="Image Generation Failed").exec()
                return

            generated_paths = [results[i][0] for i in range(total)]
            total_size = sum(int(os.path.getsize(path)) for path in generated_paths if os.path.isfile(path))
            dlg.append_log(f"Generated {len(generated_paths)} {label} image(s).", "success")
            dlg.append_log(f"Total size: {format_file_size(total_size)}", "success")
            for err in worker_errors[:12]:
                dlg.append_log(f"  {err}", "warning")
            dlg.accept()
            summary = "\n".join([
                f"{_pad_label('Output folder')} : {output_folder}",
                f"{_pad_label('Images generated')} : {len(generated_paths)}",
                f"{_pad_label('Page range')} : {first_page}–{last_page}",
                f"{_pad_label('Format')} : {label}",
                *( [f"{_pad_label('WebP mode')} : {'Lossless' if webp_mode == 'lossless' else 'Lossy'}"] if image_format == 'webp' else [] ),
                f"{_pad_label('Resolution')} : {image_dpi} dpi",
                f"{_pad_label('Total size')} : {format_file_size(total_size)}",
                f"{_pad_label('Time taken')} : {elapsed}",
            ])
            ResultDialog(
                True, summary, dlg.logs, self._dialog_parent(),
                title_text=f"{label} Images Generated!",
                folder_path=output_folder, folder_button_text="Open Folder"
            ).exec()
        except Exception as exc:
            if dlg is not None:
                try:
                    dlg.append_log(f"{label} generation failed: {type(exc).__name__}: {exc}", "error")
                    dlg.accept()
                except Exception:
                    pass
            for path in locals().get("output_paths", []):
                try:
                    if os.path.isfile(path):
                        os.remove(path)
                except Exception:
                    pass
            if dlg is not None:
                QtWidgets.QMessageBox.critical(
                    self, "Image Generation Failed", f"Could not generate {label} images:\n{exc}"
                )
            else:
                QtWidgets.QMessageBox.critical(
                    self, "Image Generation Failed", f"Could not prepare {label} image generation:\n{exc}"
                )
        finally:
            shutil.rmtree(job_root, ignore_errors=True)

    def _start_image_to_pdf_guide(self):
        dlg = ImageToPdfGuideDialog(self._dialog_parent())
        if dlg.exec() == QtWidgets.QDialog.DialogCode.Accepted:
            editor = PageEditDialog(
                None, unit_label="Pages", parent=self._dialog_parent(), blank_canvas=True)
            editor.exec()
            return
        return "input_cancelled"

    def open_pdf_security(self):
        chooser = PdfSecurityChoiceDialog(self)
        while True:
            if chooser.exec() != QtWidgets.QDialog.DialogCode.Accepted:
                return

            input_path, _ = QtWidgets.QFileDialog.getOpenFileName(
                self,
                "Select PDF" if chooser.choice == "lock" else "Select PDF to Unlock",
                "", "PDF Files (*.pdf)",
                options=QtWidgets.QFileDialog.Option.DontUseNativeDialog)
            if not input_path:
                continue
            if not os.path.isfile(input_path):
                QtWidgets.QMessageBox.warning(self, "PDF Not Found", f"File not found:\n{input_path}")
                continue
            break

        try:
            security_info = _inspect_pdf_security(input_path)
            security_info["path"] = os.path.abspath(input_path)
        except Exception as exc:
            QtWidgets.QMessageBox.critical(self, "PDF Security Check Failed", str(exc))
            return

        if chooser.choice == "unlock":
            # Dedicated Unlock always presents the shared dialog for protected files,
            # including editing-only files; only automatic/non-security workflows bypass
            # editing-only security without a dialog.
            pwd_dlg = PdfUnlockPasswordDialog(security_info, self)
            if not security_info.get("encrypted"):
                pwd_dlg.exec()
                return

            if security_info.get("editing_only"):
                if pwd_dlg.exec() != QtWidgets.QDialog.DialogCode.Accepted:
                    return
                self._run_pdf_security_operation(
                    input_path, "unlock",
                    candidate_passwords=[""],
                    editing_only_bypass=True,
                    security_info=security_info,
                    auto_unlock=False,
                    context="PDF Security")
                return

            while True:
                if pwd_dlg.exec() != QtWidgets.QDialog.DialogCode.Accepted:
                    return
                candidate = pwd_dlg.password()
                verified, _role = _verify_pdf_access_password(input_path, candidate)
                if verified:
                    self._run_pdf_security_operation(
                        input_path, "unlock",
                        candidate_passwords=[candidate],
                        editing_only_bypass=False,
                        security_info=security_info,
                        auto_unlock=False,
                        context="PDF Security")
                    return
                QtWidgets.QMessageBox.warning(
                    self,
                    "Incorrect Password",
                    "That password could not be used to open this PDF. "
                    "Enter the viewing password or editing password and try again.")
                pwd_dlg = PdfUnlockPasswordDialog(security_info, self)

        # Dedicated Lock: define the replacement security and apply it directly to
        # the selected source PDF. Existing protected files can be opened with either
        # applicable access password; editing-only security needs no current password.
        pwd_dlg = PdfLockPasswordDialog(
            input_path,
            security_info=security_info,
            already_encrypted=bool(security_info.get("encrypted")),
            parent=self)

        while True:
            if pwd_dlg.exec() != QtWidgets.QDialog.DialogCode.Accepted:
                return
            values = pwd_dlg.values()
            if not security_info.get("encrypted") or security_info.get("editing_only"):
                break
            verified, _role = _verify_pdf_access_password(
                input_path, values.get("current_password", ""))
            if verified:
                break
            QtWidgets.QMessageBox.warning(
                self,
                "Incorrect Current Password",
                "The current password is incorrect. Enter the viewing password "
                "or editing password and try again.")
            pwd_dlg = PdfLockPasswordDialog(
                input_path,
                security_info=security_info,
                already_encrypted=True,
                parent=self)

        self._run_pdf_security_operation(
            input_path,
            "lock",
            current_password=values.get("current_password", ""),
            user_password=values.get("user_password", ""),
            new_owner_password=values.get("owner_password", ""),
            security_info=security_info,
            auto_unlock=False,
            context="PDF Security")

    def _run_pdf_security_operation(self, input_path, operation,
                                    current_password="", user_password="",
                                    new_owner_password=None, candidate_passwords=None,
                                    editing_only_bypass=False, security_info=None,
                                    auto_unlock=False, context="PDF Security"):
        """Process security in a temp file, verify it, then replace the source PDF in place.

        For automatic unlocks this method returns a boolean and never opens a result dialog.
        Dedicated PDF Security shows the normal result dialog after the source is replaced.
        """
        input_path = os.path.abspath(str(input_path))
        os.makedirs(TEMP_FOLDER, exist_ok=True)
        temp_output = os.path.join(
            TEMP_FOLDER, f"security_{operation}_{uuid.uuid4().hex}.pdf")
        try:
            if os.path.exists(temp_output):
                os.remove(temp_output)
        except Exception:
            pass

        dlg = ProgressDialog(self._dialog_parent(), cancel_enabled=True)
        dlg.setWindowTitle("Locking PDF" if operation == "lock" else "Unlocking PDF")
        dlg.start_infinite("Locking PDF" if operation == "lock" else "Unlocking PDF")
        dlg.append_log(
            f"Starting {('PDF locking' if operation == 'lock' else 'PDF unlocking')}...",
            "info")

        if operation == "lock":
            target = _run_pdf_lock_subprocess
            args = (input_path, temp_output, current_password,
                    new_owner_password or "", user_password)
        else:
            target = _run_pdf_unlock_subprocess
            args = (input_path, temp_output, list(candidate_passwords or []),
                    bool(editing_only_bypass))

        bridge = ProcessBridge(target_fn=target, args=args)
        self._active_bridge = bridge
        outcome = {"result": None, "error": None, "cancelled": False}

        def on_inf(start, label):
            if start:
                dlg.start_infinite(label or "Processing")
            else:
                dlg.stop_infinite()
        bridge.infinite_anim_signal.connect(on_inf)
        bridge.log_batch_signal.connect(dlg.append_logs)

        def on_done(result):
            if outcome["cancelled"]:
                return
            outcome["result"] = result
            dlg.accept()

        def on_err(msg):
            if outcome["cancelled"]:
                return
            outcome["error"] = msg
            if not any(m == msg and level == "error" for m, level in dlg.logs):
                dlg.append_log(msg, "error")
            dlg.accept()

        def on_cancel():
            if outcome["cancelled"]:
                return
            outcome["cancelled"] = True
            try:
                bridge.shutdown()
            except Exception:
                pass
            try:
                dlg.accept()
            except Exception:
                pass

        bridge.done_signal.connect(on_done)
        bridge.error_signal.connect(on_err)
        dlg.cancel_button.clicked.connect(on_cancel)

        try:
            bridge.start()
            dlg.exec()
        except Exception as exc:
            outcome["error"] = f"Could not start the security process: {exc}"
        finally:
            try:
                bridge.shutdown()
            except Exception:
                pass
            self._active_bridge = None

        def source_stats():
            try:
                with fitz.open(input_path) as source_doc:
                    pages = int(source_doc.page_count)
            except Exception:
                pages = 0
            try:
                size = os.path.getsize(input_path)
            except OSError:
                size = 0
            return size, pages

        def cleanup_temp():
            try:
                if os.path.exists(temp_output):
                    os.remove(temp_output)
            except Exception:
                pass

        if outcome["cancelled"]:
            cleanup_temp()
            if auto_unlock:
                return False
            size, pages = source_stats()
            summary = "\n".join([
                "Operation aborted by user.",
                "",
                f"{_pad_label('File', 22)} : {os.path.basename(input_path)}",
                f"{_pad_label('File size', 22)} : {format_file_size(size)}",
                f"{_pad_label('Pages', 22)} : {pages}",
                f"{_pad_label('Status', 22)} : No changes were made.",
            ])
            ResultDialog(False, summary, dlg.logs, self,
                         title_text="Operation Aborted").exec()
            return False

        if outcome["error"] is not None:
            cleanup_temp()
            if auto_unlock:
                QtWidgets.QMessageBox.critical(
                    self._dialog_parent(),
                    "PDF Unlock Failed",
                    f"Could not unlock the PDF for {context.lower()}.\n\n{outcome['error']}")
                return False
            size, pages = source_stats()
            summary = "\n".join([
                "Operation failed.",
                "",
                f"{_pad_label('File', 22)} : {os.path.basename(input_path)}",
                f"{_pad_label('File size', 22)} : {format_file_size(size)}",
                f"{_pad_label('Pages', 22)} : {pages}",
                f"{_pad_label('Status', 22)} : No changes were made.",
            ])
            if operation == "unlock":
                summary += "\n" + f"{_pad_label('Encryption', 22)} : Not removed"
            ResultDialog(False, summary, dlg.logs, self._dialog_parent(),
                         title_text="PDF Security Failed").exec()
            return False

        result = outcome["result"]
        if result is None or not os.path.isfile(temp_output):
            cleanup_temp()
            if auto_unlock:
                QtWidgets.QMessageBox.critical(
                    self._dialog_parent(), "PDF Unlock Failed",
                    f"The PDF could not be prepared for {context.lower()}.")
                return False
            ResultDialog(False,
                         "Operation failed.\n\nNo verified output was produced.",
                         dlg.logs, self._dialog_parent(),
                         title_text="PDF Security Failed").exec()
            return False

        try:
            # The temporary file has already been verified by the subprocess. Replace
            # the original source only now, so a failed/cancelled operation cannot damage it.
            os.replace(temp_output, input_path)
        except Exception as exc:
            cleanup_temp()
            if auto_unlock:
                QtWidgets.QMessageBox.critical(
                    self._dialog_parent(),
                    "PDF Unlock Failed" if operation == "unlock" else "PDF Lock Failed",
                    f"Could not update the original PDF.\n\n{exc}")
                return False
            size, pages = source_stats()
            summary = "\n".join([
                "Operation failed.",
                "",
                f"{_pad_label('File', 22)} : {os.path.basename(input_path)}",
                f"{_pad_label('File size', 22)} : {format_file_size(size)}",
                f"{_pad_label('Pages', 22)} : {pages}",
                f"{_pad_label('Status', 22)} : No changes were made.",
            ])
            ResultDialog(False, summary, dlg.logs, self,
                         title_text="PDF Security Failed").exec()
            return False

        if auto_unlock:
            return True

        try:
            size = os.path.getsize(input_path)
        except OSError:
            size = 0
        pages = int(result.get("pages", 0)) if isinstance(result, dict) else 0

        if operation == "lock":
            summary_lines = [
                f"{_pad_label('File saved to', 22)} : {input_path}",
                f"{_pad_label('File size', 22)} : {format_file_size(size)}",
                f"{_pad_label('Pages', 22)} : {pages}",
                f"{_pad_label('Viewing password', 22)} : {('Set' if user_password else 'Not set')}",
                f"{_pad_label('Editing password', 22)} : {('Set' if new_owner_password else 'Not set')}",
                f"{_pad_label('Encryption', 22)} : AES-256",
            ]
            ResultDialog(True, "\n".join(summary_lines), dlg.logs, self,
                         title_text="PDF Locked!", pdf_path=input_path).exec()
        else:
            bypass = bool(editing_only_bypass or (
                isinstance(result, dict) and result.get("editing_only_bypass")))
            summary_lines = [
                f"{_pad_label('File saved to', 22)} : {input_path}",
                f"{_pad_label('File size', 22)} : {format_file_size(size)}",
                f"{_pad_label('Pages', 22)} : {pages}",
                f"{_pad_label('Viewing password', 22)} : Removed",
                f"{_pad_label('Editing password', 22)} : Removed" + (" (Bypassed)" if bypass else ""),
                f"{_pad_label('Encryption', 22)} : Removed",
            ]
            ResultDialog(True, "\n".join(summary_lines), dlg.logs, self,
                         title_text="PDF Unlocked!", pdf_path=input_path).exec()
        return True

    def open_pdf_from_menu(self):
        pdf_path, _ = QtWidgets.QFileDialog.getOpenFileName(
            self, "Open PDF", "", "PDF Files (*.pdf)",
            options=QtWidgets.QFileDialog.Option.DontUseNativeDialog)
        if not pdf_path:
            return
        if not os.path.isfile(pdf_path):
            QtWidgets.QMessageBox.warning(
                self, "Open Failed", f"File not found:\n{pdf_path}")
            return
        if not self._ensure_pdf_unlocked_for_use(pdf_path, context="opening the PDF"):
            return
        viewer = FullPdfViewer(pdf_path, page_idx=0, parent=self)
        viewer.exec()

    def edit_pdf_from_menu(self):
        chooser = EditPdfChoiceDialog(self)
        while True:
            if chooser.exec() != QtWidgets.QDialog.DialogCode.Accepted:
                return

            if chooser.choice == "existing":
                pdf_path, _ = QtWidgets.QFileDialog.getOpenFileName(
                    self, "Edit PDF", "", "PDF Files (*.pdf)",
                    options=QtWidgets.QFileDialog.Option.DontUseNativeDialog)
                if not pdf_path:
                    continue
                if not os.path.isfile(pdf_path):
                    QtWidgets.QMessageBox.warning(
                        self, "Edit Failed", f"File not found:\n{pdf_path}")
                    continue
                if not self._ensure_pdf_unlocked_for_use(pdf_path, context="opening Edit PDF"):
                    return
                editor = PageEditDialog(pdf_path, unit_label="Pages", parent=self)
                editor.exec()
                return

            if chooser.choice == "blank":
                editor = PageEditDialog(
                    None, unit_label="Pages", parent=self, blank_canvas=True)
                editor.exec()
                return

            return

    def open_merge_pdfs(self):
        self.merge_pdfs_page.list_widget.clear_files()
        self.merge_pdfs_page.reset_for_new_session()
        self._run_independent_modal_window(self.merge_pdfs_window)

    def open_merge_slides(self):
        self.merge_slides_page.list_widget.clear_files()
        self._pending_slides_paths = []
        self.prefs_page.reset_for_new_session()
        self.merge_slides_window.show_page(0)
        self._run_independent_modal_window(self.merge_slides_window)

    def open_preferences(self, pdf_paths):
        missing = validate_files_exist(pdf_paths)
        if missing:
            bullet = "\n".join(f"  •  {p}" for p in missing)
            QtWidgets.QMessageBox.critical(
                self._dialog_parent(), "Files Missing",
                "Cannot continue — the following file(s) no longer exist "
                "on disk:\n\n" + bullet)
            return
        self._pending_slides_paths = list(pdf_paths)
        self.merge_slides_window.show_page(1)

    def _cleanup_temp(self):
        try:
            if os.path.exists(TEMP_FOLDER):
                shutil.rmtree(TEMP_FOLDER, ignore_errors=True)
            os.makedirs(TEMP_FOLDER, exist_ok=True)
        except Exception:
            pass

    def _postprocess_and_summarize(self, dlg, result, is_slides=False):
        temp_path = result['path']
        default_name = os.path.basename(temp_path)
        try:
            generated_size = os.path.getsize(temp_path)
        except OSError:
            generated_size = 0

        save_path, _ = QtWidgets.QFileDialog.getSaveFileName(
            self._dialog_parent(), "Save Output PDF", default_name, "PDF Files (*.pdf)",
            options=QtWidgets.QFileDialog.Option.DontUseNativeDialog)

        saved_ok = False
        skip_cleanup = False
        dest_abs = None
        if save_path:
            try:
                dest_abs = os.path.abspath(save_path)
                temp_abs = os.path.abspath(temp_path)
                if dest_abs == temp_abs:
                    saved_ok = True
                    skip_cleanup = True
                else:
                    dest_dir = os.path.dirname(dest_abs)
                    if dest_dir and not os.path.exists(dest_dir):
                        os.makedirs(dest_dir, exist_ok=True)
                    shutil.move(temp_path, dest_abs)
                    saved_ok = True
                    if _is_inside(dest_abs, TEMP_FOLDER):
                        skip_cleanup = True
            except Exception as e:
                QtWidgets.QMessageBox.warning(
                    self._dialog_parent(), "Save Error", f"Could not save: {e}")
                saved_ok = False

        final_size = None
        if saved_ok and dest_abs:
            try:
                final_size = os.path.getsize(dest_abs)
            except OSError:
                final_size = None

        lines = []
        if not save_path:
            lines.append("File aborted by user.")
            dlg.append_log(
                "Final save-location dialog cancelled; generated output was discarded.",
                "warning")
        elif saved_ok:
            lines.append(f"{_pad_label('File saved to')} : {save_path}")
        else:
            lines.append("File save failed.")
        if is_slides:
            if bool(result.get("optimization_requested")):
                initial_size = int(result.get("initial_size", generated_size) or generated_size)
                optimized_size = int(result.get("optimized_size", generated_size) or generated_size)
                reduction_percent = float(result.get("reduction_percent", 0.0) or 0.0)
                lines.append(
                    f"{_pad_label('Initial temp')} : {format_file_size(initial_size)}")
                lines.append(
                    f"{_pad_label('Optimized temp')} : {format_file_size(optimized_size)} "
                    f"(reduced {reduction_percent:.1f}%)")
            final_size_text = format_file_size(final_size) if final_size is not None else (
                "Unavailable" if saved_ok else "Not saved")
            lines.append(f"{_pad_label('Final size')} : {final_size_text}")
        elif bool(result.get("optimization_requested")):
            initial_size = int(result.get("initial_size", generated_size) or generated_size)
            reduction_percent = float(result.get("reduction_percent", 0.0) or 0.0)
            final_size_text = format_file_size(final_size) if final_size is not None else (
                "Unavailable" if saved_ok else "Not saved")
            lines.append(
                f"{_pad_label('Initial temp')} : {format_file_size(initial_size)}")
            reduction_text = (
                f"(reduced {reduction_percent:.1f}%)" if reduction_percent > 0.0
                else "(no reduction; original retained)"
            )
            lines.append(
                f"{_pad_label('Final size')} : {final_size_text} {reduction_text}")
        else:
            lines.append(f"{_pad_label('File size')} : {format_file_size(generated_size)}")
        lines.append(f"{_pad_label('PDFs Merged')} : {result['pdfs']}")
        if is_slides:
            lines.append(f"{_pad_label('Slides merged')} : {result['slides']}")
        lines.append(f"{_pad_label('Pages used')} : {result['pages']}")
        lines.append(f"{_pad_label('Time taken')} : {result['time']}")
        summary = "\n".join(lines)

        if not skip_cleanup:
            self._cleanup_temp()

        open_path = save_path if saved_ok else None
        result_title = None if saved_ok else ("File Aborted" if not save_path else "File Save Failed")
        ResultDialog(bool(saved_ok), summary, dlg.logs, self._dialog_parent(),
                     title_text=result_title, pdf_path=open_path).exec()

    def run_merge_pdfs(self, pdf_paths):
        missing = validate_files_exist(pdf_paths)
        if missing:
            bullet = "\n".join(f"  •  {p}" for p in missing)
            QtWidgets.QMessageBox.critical(
                self._dialog_parent(), "Files Missing",
                "Cannot start merge — the following file(s) no longer "
                "exist on disk:\n\n" + bullet)
            self._close_active_workflow_to_menu()
            return

        add_bookmarks = self.merge_pdfs_page.get_add_bookmarks()
        optimize_pdf = self.merge_pdfs_page.get_optimize_pdf()

        # All source files are present; now ensure every protected PDF is fully
        # unlocked before any merge worker starts. Cancelling any unlock cancels the merge.
        if not self._prepare_pdf_paths_for_use(pdf_paths, context="merging PDFs"):
            return

        dlg = ProgressDialog(self._dialog_parent(), cancel_enabled=True)
        dlg.start_infinite("Merging PDFs")

        bridge = ProcessBridge(
            target_fn=_run_merge_pdf_subprocess,
            args=(list(pdf_paths), add_bookmarks, optimize_pdf, TEMP_FOLDER))
        self._active_bridge = bridge
        bridge.log_batch_signal.connect(dlg.append_logs)

        def on_inf(start, label):
            if start:
                dlg.start_infinite(label or "Merging PDFs")
            else:
                dlg.stop_infinite()
        bridge.infinite_anim_signal.connect(on_inf)

        outcome = {'result': None, 'error': None, 'cancelled': False}

        def on_done(result):
            if outcome['cancelled']:
                return
            outcome['result'] = result
            dlg.accept()

        def on_err(msg):
            if outcome['cancelled']:
                return
            outcome['error'] = msg
            if not any(m == msg and lvl == 'error' for (m, lvl) in dlg.logs):
                dlg.append_log(msg, "error")
            dlg.accept()

        def on_cancel():
            if outcome['cancelled']:
                return
            outcome['cancelled'] = True
            dlg.append_log(
                "Merge cancelled; temporary output will be discarded.", "warning")
            bridge.request_cancel()
            dlg.accept()

        bridge.done_signal.connect(on_done)
        bridge.error_signal.connect(on_err)
        dlg.cancel_requested.connect(on_cancel)
        bridge.start()
        dlg.exec()
        bridge.shutdown()
        self._active_bridge = None

        if outcome['cancelled']:
            self._cleanup_temp()
            ResultDialog(
                False, "Operation aborted by user.\n\nNo merge output was kept.",
                dlg.logs, self._dialog_parent(), title_text="Operation Aborted").exec()
        elif outcome['error'] is not None:
            ResultDialog(False, f"Error: {outcome['error']}",
                         dlg.logs, self._dialog_parent()).exec()
            self._cleanup_temp()
        elif outcome['result'] is not None:
            self._postprocess_and_summarize(dlg, outcome['result'], is_slides=False)
        else:
            self.go_menu()

    def run_merge_slides(self, config):
        pdf_paths = self._pending_slides_paths
        if not pdf_paths:
            return
        missing = validate_files_exist(pdf_paths)
        if missing:
            bullet = "\n".join(f"  •  {p}" for p in missing)
            QtWidgets.QMessageBox.critical(
                self._dialog_parent(), "Files Missing",
                "Cannot start the merge — the following file(s) no longer "
                "exist on disk:\n\n" + bullet)
            self._close_active_workflow_to_menu()
            return

        # Perform security preflight only after the existing file-presence check.
        # Every protected source is unlocked before printable processing begins.
        if not self._prepare_pdf_paths_for_use(pdf_paths, context="making printable slides"):
            return

        dlg = ProgressDialog(self._dialog_parent(), cancel_enabled=True)
        dlg.start_infinite("Processing")
        config = dict(config)
        bridge = ProcessBridge(
            target_fn=_run_merge_slides_subprocess,
            args=(list(pdf_paths), config, TEMP_FOLDER))
        self._active_bridge = bridge
        bridge.log_batch_signal.connect(dlg.append_logs)

        def on_inf(start, label):
            if start:
                dlg.start_infinite(label or "Processing")
            else:
                dlg.stop_infinite()
        bridge.infinite_anim_signal.connect(on_inf)
        bridge.progress_signal.connect(dlg.set_progress)

        outcome = {'result': None, 'error': None, 'cancelled': False}

        def on_done(result):
            if outcome['cancelled']:
                return
            outcome['result'] = result
            dlg.accept()

        def on_err(msg):
            if outcome['cancelled']:
                return
            outcome['error'] = msg
            if not any(m == msg and lvl == 'error' for (m, lvl) in dlg.logs):
                dlg.append_log(msg, "error")
            dlg.accept()

        def on_cancel():
            if outcome['cancelled']:
                return
            outcome['cancelled'] = True
            dlg.append_log(
                "Printable generation cancelled; temporary output will be discarded.",
                "warning")
            bridge.request_cancel()
            dlg.accept()

        bridge.done_signal.connect(on_done)
        bridge.error_signal.connect(on_err)
        dlg.cancel_requested.connect(on_cancel)
        bridge.start()
        dlg.exec()
        bridge.shutdown()
        self._active_bridge = None

        if outcome['cancelled']:
            self._cleanup_temp()
            ResultDialog(
                False, "Operation aborted by user.\n\nNo printable output was kept.",
                dlg.logs, self._dialog_parent(), title_text="Operation Aborted").exec()
        elif outcome['error'] is not None:
            ResultDialog(False, f"Error: {outcome['error']}",
                         dlg.logs, self._dialog_parent()).exec()
            self._cleanup_temp()
        elif outcome['result'] is not None:
            self._postprocess_and_summarize(dlg, outcome['result'], is_slides=True)
        else:
            self.go_menu()


