# ============================================================
# ENTRY POINT
# ============================================================
def main():
    # Resource mode is selected before main() is entered, normally by the environment
    # variable above. Multiprocessing workers inherit the environment, so spawned workers
    # resolve the same icons/fonts mode as the GUI process.
    try:
        multiprocessing.set_start_method('spawn', force=True)
    except (RuntimeError, ValueError):
        pass

    # Remove stale working artifacts from interrupted previous runs before any workflow starts.
    # Individual workflows still clean their own temporary jobs during normal completion; this
    # startup sweep recovers files left behind by crashes, forced exits, or terminated workers.
    try:
        remove_temp_folder(max_retries=3, delay=0.15)
    except Exception:
        try:
            os.makedirs(TEMP_FOLDER, exist_ok=True)
        except Exception:
            pass

    _ensure_icons_exist()

    # Set the application-wide numeric locale before QApplication is created so
    # every subsequently-created numeric widget inherits English/US formatting.
    QtCore.QLocale.setDefault(ENGLISH_LOCALE)
    app = QtWidgets.QApplication(sys.argv)
    # Force all Qt numeric widgets/dialogs to use English/US formatting,
    # regardless of the desktop's system locale. This keeps values such as
    # page numbers, process counts, DPI and point sizes visually consistent
    # with the rest of the English UI.
    QtCore.QLocale.setDefault(ENGLISH_LOCALE)
    font = QtGui.QFont("Segoe UI", 10)
    app.setFont(font)
    app.setApplicationName("Mergerz")
    app.setApplicationVersion(__version__)
    app.setStyleSheet(DARK_QSS)
    _window_chrome_manager = _WindowChromeManager(app)
    app._window_chrome_manager = _window_chrome_manager

    window = MainWindow()

    def _about_to_quit():
        # MainWindow.closeEvent normally runs this first. Keep this handler as a
        # second, idempotent fence for programmatic QApplication.quit() and any
        # other route that bypasses the main window close event.
        _shutdown_application_resources(finalize=True)

    app.aboutToQuit.connect(_about_to_quit)
    window.show()

    # The core update checker is deliberately launched only after the main window has
    # been shown and the first paint can complete. This keeps network/DNS/TLS work
    # completely out of the startup path. The check itself runs in PluginTaskThread.
    if not MERGERZ_TEST_MODE:
        QtCore.QTimer.singleShot(1200, window._begin_mergerz_update_check)

    # Recover stale work files from previous/crashed sessions without blocking the Qt event loop.
    QtCore.QTimer.singleShot(0, _start_background_temp_cleanup)

    try:
        return_code = app.exec()
    finally:
        # QApplication is still a valid Python/Qt object here. Complete one final
        # deterministic native-resource fence before Python starts tearing down
        # PySide6/PyMuPDF/pikepdf globals.
        _shutdown_application_resources(finalize=True)
        try:
            logging.shutdown()
        except Exception:
            pass
        try:
            sys.stdout.flush()
            sys.stderr.flush()
        except Exception:
            pass

    # The normal application exits with os._exit() to avoid a second native teardown
    # pass. A successful Mergerz self-update uses the same finalization fence, but then
    # replaces this process image with a fresh interpreter so the newly-installed package
    # is loaded immediately. The restart path is intentionally kept here rather than in
    # __init__.py, where package import side effects would make updates unsafe.
    if _RESTART_AFTER_UPDATE:
        # Restart exactly the same installed console entry point the user launched.
        # This is preferable to `python -m mergerz.module`: this package's __init__.py
        # imports mergerz.module, so runpy would otherwise report:
        #   module found in sys.modules after import of package ...
        # The console launcher also guarantees that the same virtual environment and
        # installed distribution are used after the in-place pip upgrade.
        launcher = None
        try:
            candidate = shutil.which("mergerz")
            if candidate and os.path.isfile(candidate):
                launcher = candidate
        except Exception:
            launcher = None

        try:
            if launcher:
                os.execv(launcher, [launcher])
            else:
                # Fallback for environments where the console-script wrapper cannot
                # be resolved. Importing the module from -c avoids the runpy warning
                # produced by `-m mergerz.module`.
                code = "from mergerz.module import main; main()"
                os.execv(sys.executable, [sys.executable, "-c", code])
        except Exception:
            # Last-resort detached launch. The update has already been verified, so
            # the only failure at this point should be the process replacement itself.
            try:
                kwargs = {
                    "cwd": os.getcwd(),
                    "env": os.environ.copy(),
                    "stdin": subprocess.DEVNULL,
                    "stdout": subprocess.DEVNULL,
                    "stderr": subprocess.DEVNULL,
                }
                if os.name == "nt":
                    kwargs["creationflags"] = (
                        getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
                        | getattr(subprocess, "CREATE_NO_WINDOW", 0)
                    )
                else:
                    kwargs["start_new_session"] = True

                if launcher:
                    subprocess.Popen([launcher], **kwargs)
                else:
                    code = "from mergerz.module import main; main()"
                    subprocess.Popen(
                        [sys.executable, "-c", code],
                        **kwargs,
                    )
            except Exception:
                pass

    os._exit(int(return_code))


if __name__ == "__main__":
    main()
